-- Generated from pristine PostgreSQL 16 after V1 through V86.
-- Credential, runtime, audit, outbox, RAG, and owner-private rows are excluded.
SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;



CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;



CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;



CREATE FUNCTION public.acquire_order_fill_reconciliation_lock(requested_payload jsonb, requested_capability_token text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  requested_actor_user_id text;
  requested_actor_role text;
  requested_security_version bigint;
  requested_order_id text;
  stored_actor record;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  IF requested_payload IS NULL
     OR jsonb_typeof(requested_payload) <> 'object'
     OR NOT requested_payload ?& ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'orderId'
     ]
     OR requested_payload - ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'orderId'
     ] <> '{}'::jsonb THEN
    RETURN 'VALIDATION_ERROR';
  END IF;
  requested_actor_user_id := requested_payload ->> 'actorUserId';
  requested_actor_role := requested_payload ->> 'actorRole';
  requested_security_version := (requested_payload ->> 'securityVersion')::bigint;
  requested_order_id := requested_payload ->> 'orderId';

  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id
  FOR SHARE;
  IF NOT FOUND
     OR stored_actor.status <> 'ACTIVE'
     OR stored_actor.role <> 'ADMIN'
     OR requested_actor_role <> 'ADMIN'
     OR stored_actor.security_version <> requested_security_version THEN
    RETURN 'ACTOR_UNAUTHORIZED';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('order-fill:' || requested_order_id, 3301)
  );
  IF NOT EXISTS (
    SELECT 1 FROM public.orders stored WHERE stored.order_id = requested_order_id
  ) THEN
    RETURN 'ORDER_NOT_FOUND';
  END IF;
  RETURN 'LOCKED';
END
$$;


ALTER FUNCTION public.acquire_order_fill_reconciliation_lock(requested_payload jsonb, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.activate_rag_v2_immutable_owner_bundle(p_owner_user_id text, p_bundle_id text, p_expected_active_bundle_id text, p_expected_bundle_version bigint, p_activation_receipt_id text, p_activation_kind text DEFAULT 'OWNER_BUNDLE'::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  pointer_record public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  bundle_record public.rag_v2_immutable_bundles%ROWTYPE;
  owner_generation public.rag_v2_immutable_component_generations%ROWTYPE;
  owner_source_count bigint;
  owner_chunk_count bigint;
  owner_embedding_count bigint;
  activation_timestamp timestamptz := clock_timestamp();
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_bundle_id !~ '^rgb_[0-9a-f]{32}$'
     OR (p_expected_active_bundle_id IS NOT NULL AND p_expected_active_bundle_id !~ '^rgb_[0-9a-f]{32}$')
     OR p_expected_bundle_version < 0
     OR p_activation_receipt_id !~ '^rgr_act_[0-9a-f]{32}$'
     OR p_activation_kind NOT IN ('OWNER_BUNDLE', 'OWNER_DELETE_REPLACEMENT')
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner bundle activation arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- owner bundle activation도 public pointer를 읽기만 하므로 별도 transaction-local capability로 제한한다.
  PERFORM set_config('app.rag_admin_maintenance', 'owner_bundle_activation', true);
  -- public base replacement과 같은 lock을 사용해 owner→public pointer lock 순서를 직렬화한다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-bundle-activation', 0)
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  INSERT INTO public.rag_v2_immutable_owner_bundle_pointers (
    owner_user_id, state, active_bundle_id, bundle_version
  )
  VALUES (p_owner_user_id, 'ABSENT', NULL, 0)
  ON CONFLICT (owner_user_id) DO NOTHING;
  SELECT * INTO pointer_record
  FROM public.rag_v2_immutable_owner_bundle_pointers
  WHERE owner_user_id = p_owner_user_id
  FOR UPDATE;
  IF pointer_record.bundle_version IS DISTINCT FROM p_expected_bundle_version
     OR pointer_record.active_bundle_id IS DISTINCT FROM p_expected_active_bundle_id THEN
    RAISE EXCEPTION 'immutable RAG v2 owner pointer CAS failed'
      USING ERRCODE = '40001';
  END IF;

  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers
  WHERE state_id = 'default';
  -- 동일 advisory lock 아래에서 읽으므로 owner activation이 public pointer row lock까지 획득할 필요는 없다.
  -- 이로써 owner marker에는 public pointer UPDATE RLS capability를 부여하지 않는다.
  IF NOT FOUND OR public_pointer.state <> 'ACTIVE' THEN
    RAISE EXCEPTION 'immutable RAG v2 public base is not active'
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO bundle_record
  FROM public.rag_v2_immutable_bundles
  WHERE bundle_id = p_bundle_id
    AND owner_user_id = p_owner_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR bundle_record.state <> 'EVALUATED'
     OR bundle_record.evaluation_status <> 'PASSED'
     OR bundle_record.exact30_generation_id IS DISTINCT FROM public_pointer.exact30_generation_id
     OR bundle_record.oa112_generation_id IS DISTINCT FROM public_pointer.oa112_generation_id
     OR bundle_record.embedding_profile_id IS DISTINCT FROM public_pointer.embedding_profile_id THEN
    RAISE EXCEPTION 'immutable RAG v2 bundle is not eligible for the active public base'
      USING ERRCODE = '23514';
  END IF;
  SELECT * INTO owner_generation
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = bundle_record.owner_private_generation_id
  FOR UPDATE;
  SELECT
    COUNT(DISTINCT membership.source_revision_id),
    COUNT(membership.chunk_id),
    COUNT(embedding.chunk_id)
  INTO owner_source_count, owner_chunk_count, owner_embedding_count
  FROM public.rag_v2_immutable_generation_memberships AS membership
  LEFT JOIN public.rag_v2_immutable_generation_embeddings AS embedding
    ON embedding.component_generation_id = membership.component_generation_id
   AND embedding.chunk_id = membership.chunk_id
  WHERE membership.component_generation_id = bundle_record.owner_private_generation_id;
  -- V59에서 생성된 non-empty owner bundle은 generation identity로 profile을 전방 보정한다.
  -- 빈 replacement bundle은 NULL을 유지해 마지막 문서 삭제 뒤 library profile 잠금을 해제한다.
  IF bundle_record.owner_embedding_profile_id IS NULL AND owner_chunk_count > 0 THEN
    UPDATE public.rag_v2_immutable_bundles
    SET owner_embedding_profile_id = owner_generation.embedding_profile_id
    WHERE bundle_id = p_bundle_id
    RETURNING * INTO bundle_record;
  END IF;
  IF NOT FOUND
     OR owner_generation.component_scope <> 'OWNER_PRIVATE'
     OR owner_generation.owner_user_id IS DISTINCT FROM p_owner_user_id
     OR (
       owner_chunk_count > 0
       AND owner_generation.embedding_profile_id IS DISTINCT FROM bundle_record.owner_embedding_profile_id
     )
     OR owner_generation.state <> 'EVALUATED'
     OR owner_generation.evaluation_status <> 'PASSED'
     OR owner_generation.expected_source_count <> owner_source_count
     OR owner_generation.expected_chunk_count <> owner_chunk_count
     OR owner_generation.actual_source_count <> owner_source_count
     OR owner_generation.actual_chunk_count <> owner_chunk_count
     OR owner_embedding_count <> owner_chunk_count
     OR EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_generation_memberships AS membership
       JOIN public.rag_v2_immutable_source_revisions AS source
         ON source.source_revision_id = membership.source_revision_id
       WHERE membership.component_generation_id = owner_generation.component_generation_id
         AND (
           membership.component_scope <> 'OWNER_PRIVATE'
           OR membership.owner_user_id IS DISTINCT FROM p_owner_user_id
           OR source.source_scope <> 'OWNER_PRIVATE'
           OR source.owner_user_id IS DISTINCT FROM p_owner_user_id
     )
     OR EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_generation_embeddings AS embedding
       WHERE embedding.component_generation_id = owner_generation.component_generation_id
         AND (
           embedding.component_scope <> 'OWNER_PRIVATE'
           OR embedding.owner_user_id IS DISTINCT FROM p_owner_user_id
           OR embedding.embedding_profile_id IS DISTINCT FROM owner_generation.embedding_profile_id
         )
     )
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner component scope is invalid'
      USING ERRCODE = '23514';
  END IF;
  IF bundle_record.owner_embedding_profile_id = 'voyage_context_4_1024_v1'
     AND (
       EXISTS (
         SELECT 1
         FROM public.rag_v2_immutable_generation_memberships AS membership
         JOIN public.rag_v2_immutable_source_revisions AS source
           ON source.source_revision_id = membership.source_revision_id
         WHERE membership.component_generation_id = owner_generation.component_generation_id
           AND NOT source.external_processing_eligible
       )
       OR coalesce((
         SELECT consent.action = 'GRANT'
         FROM public.rag_v2_immutable_consent_events AS consent
         WHERE consent.owner_user_id = p_owner_user_id
           AND consent.policy_version = 'EXTERNAL_AI_RAG_V2'
         ORDER BY consent.created_at DESC, consent.consent_event_id DESC
         LIMIT 1
       ), false) = false
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 Voyage owner consent or safety gate is invalid'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.rag_v2_immutable_bundles
  SET state = 'SUPERSEDED'
  WHERE bundle_id = pointer_record.active_bundle_id
    AND state = 'ACTIVE';
  UPDATE public.rag_v2_immutable_bundles
  SET state = 'ACTIVE', activated_at = activation_timestamp
  WHERE bundle_id = p_bundle_id;
  UPDATE public.rag_v2_immutable_owner_bundle_pointers
  SET state = 'READY',
      active_bundle_id = p_bundle_id,
      bundle_version = pointer_record.bundle_version + 1,
      updated_at = activation_timestamp
  WHERE owner_user_id = p_owner_user_id;
  INSERT INTO public.rag_v2_immutable_activation_receipts (
    activation_receipt_id,
    owner_user_id,
    activation_kind,
    activated_bundle_id,
    exact30_generation_id,
    oa112_generation_id,
    owner_private_generation_id,
    embedding_profile_id,
    previous_pointer_version,
    new_pointer_version,
    created_at
  )
  VALUES (
    p_activation_receipt_id,
    p_owner_user_id,
    p_activation_kind,
    p_bundle_id,
    NULL,
    NULL,
    NULL,
    bundle_record.embedding_profile_id,
    pointer_record.bundle_version,
    pointer_record.bundle_version + 1,
    activation_timestamp
  );
  PERFORM set_config('app.rag_admin_maintenance', '', true);
  RETURN pointer_record.bundle_version + 1;
END;
$_$;


ALTER FUNCTION public.activate_rag_v2_immutable_owner_bundle(p_owner_user_id text, p_bundle_id text, p_expected_active_bundle_id text, p_expected_bundle_version bigint, p_activation_receipt_id text, p_activation_kind text) OWNER TO flyway;


CREATE FUNCTION public.activate_rag_v2_immutable_public_base(p_exact30_generation_id text, p_oa112_generation_id text, p_expected_pointer_version bigint, p_activation_receipt_id text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  pointer_record public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  exact_generation public.rag_v2_immutable_component_generations%ROWTYPE;
  oa_generation public.rag_v2_immutable_component_generations%ROWTYPE;
  exact_source_count bigint;
  exact_source_revision_count bigint;
  exact_chunk_count bigint;
  exact_embedding_count bigint;
  oa_chunk_count bigint;
  oa_embedding_count bigint;
  invalidated_owner_bundle_count integer := 0;
  superseded_owner_bundle_count integer := 0;
  activation_timestamp timestamptz := clock_timestamp();
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_exact30_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_oa112_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_exact30_generation_id = p_oa112_generation_id
     OR p_expected_pointer_version < 1
     OR p_activation_receipt_id !~ '^rgr_act_[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 public activation arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- public pointer RLS는 이 definer 호출의 bounded activation state만 읽고 바꾸도록 닫는다.
  PERFORM set_config('app.rag_admin_maintenance', 'public_base_activation', true);
  -- public/owner activation은 같은 advisory lock을 먼저 잡아 서로 반대인 pointer lock 순서의 deadlock을 막는다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-bundle-activation', 0)
  );
  SELECT *
  INTO pointer_record
  FROM public.rag_v2_immutable_public_bundle_pointers
  WHERE state_id = 'default'
  FOR UPDATE;
  IF NOT FOUND
     OR pointer_record.pointer_version IS DISTINCT FROM p_expected_pointer_version
     OR pointer_record.state NOT IN ('NOT_MATERIALIZED', 'ACTIVE', 'FAILED') THEN
    RAISE EXCEPTION 'immutable RAG v2 public pointer CAS failed'
      USING ERRCODE = '40001';
  END IF;
  IF pointer_record.state = 'ACTIVE'
     AND pointer_record.exact30_generation_id IS NOT DISTINCT FROM p_exact30_generation_id
     AND pointer_record.oa112_generation_id IS NOT DISTINCT FROM p_oa112_generation_id THEN
    RAISE EXCEPTION 'immutable RAG v2 public base is already active'
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO exact_generation
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = p_exact30_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 exact-30 component was not found'
      USING ERRCODE = '23514';
  END IF;
  SELECT * INTO oa_generation
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = p_oa112_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 OA112 component was not found'
      USING ERRCODE = '23514';
  END IF;
  IF exact_generation.component_scope <> 'EXACT30'
     OR exact_generation.owner_user_id IS NOT NULL
     OR exact_generation.state <> 'EVALUATED'
     OR exact_generation.evaluation_status <> 'PASSED'
     OR oa_generation.component_scope <> 'OA112'
     OR oa_generation.owner_user_id IS NOT NULL
     OR oa_generation.state <> 'EVALUATED'
     OR oa_generation.evaluation_status <> 'PASSED'
     OR exact_generation.embedding_profile_id IS DISTINCT FROM oa_generation.embedding_profile_id THEN
    RAISE EXCEPTION 'immutable RAG v2 public component is not activation ready'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    COUNT(DISTINCT source.source_id),
    COUNT(DISTINCT membership.source_revision_id),
    COUNT(membership.chunk_id),
    COUNT(embedding.chunk_id)
  INTO exact_source_count, exact_source_revision_count, exact_chunk_count, exact_embedding_count
  FROM public.rag_v2_immutable_generation_memberships AS membership
  LEFT JOIN public.rag_v2_immutable_generation_embeddings AS embedding
    ON embedding.component_generation_id = membership.component_generation_id
   AND embedding.chunk_id = membership.chunk_id
  JOIN public.rag_v2_immutable_source_revisions AS source
    ON source.source_revision_id = membership.source_revision_id
  WHERE membership.component_generation_id = p_exact30_generation_id
    AND membership.component_scope = 'EXACT30'
    AND source.source_scope = 'EXACT30'
    AND source.owner_user_id IS NULL
    AND NOT source.reserve_source;
  IF exact_source_count <> 30
     OR exact_source_revision_count <> exact_source_count
     OR exact_chunk_count <> exact_generation.expected_chunk_count
     OR exact_embedding_count <> exact_generation.expected_chunk_count
     OR exact_generation.actual_source_count <> exact_source_count
     OR exact_generation.actual_chunk_count <> exact_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 exact-30 component cardinality is invalid'
      USING ERRCODE = '23514';
  END IF;

  IF (
    SELECT COUNT(DISTINCT source.source_id) <> 112
        OR COUNT(DISTINCT membership.source_revision_id) <> 112
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    WHERE membership.component_generation_id = p_oa112_generation_id
      AND membership.component_scope = 'OA112'
      AND source.source_scope = 'OA112'
      AND source.owner_user_id IS NULL
      AND source.reserve_source = false
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 OA112 active source count is invalid'
      USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_oa_track_catalog AS track
    LEFT JOIN (
      SELECT
        source.oa_track_id,
        COUNT(DISTINCT source.source_id) AS active_source_count,
        COUNT(DISTINCT membership.source_revision_id) AS active_revision_count
      FROM public.rag_v2_immutable_generation_memberships AS membership
      JOIN public.rag_v2_immutable_source_revisions AS source
        ON source.source_revision_id = membership.source_revision_id
      WHERE membership.component_generation_id = p_oa112_generation_id
        AND membership.component_scope = 'OA112'
        AND source.source_scope = 'OA112'
        AND source.owner_user_id IS NULL
        AND source.reserve_source = false
      GROUP BY source.oa_track_id
    ) AS track_counts
      ON track_counts.oa_track_id = track.track_id
    WHERE coalesce(track_counts.active_source_count, 0) <> track.required_active_source_count
       OR coalesce(track_counts.active_revision_count, 0) <> track.required_active_source_count
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 OA112 track distribution is invalid'
      USING ERRCODE = '23514';
  END IF;
  IF (
    SELECT COUNT(*) > 28
    FROM public.rag_v2_immutable_source_revisions AS source
    WHERE source.source_scope = 'OA112'
      AND source.owner_user_id IS NULL
      AND source.reserve_source = true
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 OA112 reserve limit is invalid'
      USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    WHERE membership.component_generation_id = p_oa112_generation_id
      AND (
        membership.component_scope <> 'OA112'
        OR source.source_scope <> 'OA112'
        OR source.owner_user_id IS NOT NULL
        OR source.reserve_source
        OR NOT source.machine_fetch_allowed
        OR NOT source.local_processing_allowed
        OR NOT source.external_embedding_allowed
        OR NOT source.external_generation_allowed
      )
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 OA112 rights or reserve gate is invalid'
      USING ERRCODE = '23514';
  END IF;
  -- A logical 14×8 count is not sufficient evidence for a physical OA activation. Every active
  -- membership must bind to one closed, hash-verified source-card v4 record with matching rights.
  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    LEFT JOIN public.rag_v2_immutable_oa_source_cards AS card
      ON card.source_revision_id = source.source_revision_id
       AND card.source_scope = source.source_scope
    WHERE membership.component_generation_id = p_oa112_generation_id
      AND (
        card.source_revision_id IS NULL
        OR card.source_id IS DISTINCT FROM source.source_id
        OR card.raw_content_sha256 IS DISTINCT FROM source.raw_content_sha256
        OR card.canonical_https_url IS DISTINCT FROM source.canonical_https_url
        OR card.license_evidence_sha256 IS DISTINCT FROM source.license_evidence_sha256
        OR card.access_evidence_sha256 IS DISTINCT FROM source.access_evidence_sha256
        OR card.mime_type IS DISTINCT FROM source.mime_type
        OR card.machine_fetch_allowed IS DISTINCT FROM source.machine_fetch_allowed
        OR card.local_processing_allowed IS DISTINCT FROM source.local_processing_allowed
        OR card.external_embedding_allowed IS DISTINCT FROM source.external_embedding_allowed
        OR card.external_generation_allowed IS DISTINCT FROM source.external_generation_allowed
        OR card.active_oa112_eligible = false
        OR card.access_verification_state <> 'VERIFIED'
      )
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 OA112 source-card evidence gate is invalid'
      USING ERRCODE = '23514';
  END IF;
  SELECT COUNT(membership.chunk_id), COUNT(embedding.chunk_id)
  INTO oa_chunk_count, oa_embedding_count
  FROM public.rag_v2_immutable_generation_memberships AS membership
  LEFT JOIN public.rag_v2_immutable_generation_embeddings AS embedding
    ON embedding.component_generation_id = membership.component_generation_id
   AND embedding.chunk_id = membership.chunk_id
  WHERE membership.component_generation_id = p_oa112_generation_id;
  IF oa_chunk_count <> oa_generation.expected_chunk_count
     OR oa_embedding_count <> oa_generation.expected_chunk_count
     OR oa_generation.actual_source_count <> 112
     OR oa_generation.actual_chunk_count <> oa_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 OA112 component materialization is incomplete'
      USING ERRCODE = '23514';
  END IF;
  IF exact_generation.embedding_profile_id = 'voyage_context_4_1024_v1'
     AND EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_generation_memberships AS membership
       JOIN public.rag_v2_immutable_source_revisions AS source
         ON source.source_revision_id = membership.source_revision_id
       WHERE membership.component_generation_id IN (p_exact30_generation_id, p_oa112_generation_id)
         AND NOT source.external_processing_eligible
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 Voyage source safety gate is invalid'
      USING ERRCODE = '23514';
  END IF;

  -- 새 public base는 기존 owner bundle의 두 public component와 섞일 수 없다.
  -- owner evidence를 삭제하지 않고 pointer를 BUILDING으로 fail-close하여 whole-bundle 재생성을 강제한다.
  -- FORCE RLS hides every foreign owner's row by default. This transaction-local marker opens
  -- only the two typed READY→BUILDING / ACTIVE→SUPERSEDED transitions declared above.
  WITH eligible_owner_pointers AS (
    SELECT active_bundle_id
    FROM public.rag_v2_immutable_owner_bundle_pointers
    WHERE state = 'READY'
      AND active_bundle_id IS NOT NULL
  ), superseded_owner_bundles AS (
    UPDATE public.rag_v2_immutable_bundles AS bundle
    SET state = 'SUPERSEDED'
    FROM eligible_owner_pointers AS eligible
    WHERE bundle.bundle_id = eligible.active_bundle_id
      AND bundle.state = 'ACTIVE'
    RETURNING bundle.bundle_id
  ), invalidated_owner_pointers AS (
    UPDATE public.rag_v2_immutable_owner_bundle_pointers
    SET state = 'BUILDING',
        active_bundle_id = NULL,
        bundle_version = bundle_version + 1,
        updated_at = activation_timestamp
    WHERE state = 'READY'
      AND active_bundle_id IS NOT NULL
    RETURNING owner_user_id
  )
  SELECT
    (SELECT COUNT(*) FROM invalidated_owner_pointers),
    (SELECT COUNT(*) FROM superseded_owner_bundles)
  INTO invalidated_owner_bundle_count, superseded_owner_bundle_count;
  IF invalidated_owner_bundle_count <> superseded_owner_bundle_count THEN
    RAISE EXCEPTION 'immutable RAG v2 owner invalidation state is inconsistent'
      USING ERRCODE = '23514';
  END IF;
  UPDATE public.rag_v2_immutable_component_generations
  SET state = 'SUPERSEDED'
  WHERE component_generation_id IN (pointer_record.exact30_generation_id, pointer_record.oa112_generation_id)
    AND state = 'ACTIVE';
  UPDATE public.rag_v2_immutable_component_generations
  SET state = 'ACTIVE', activated_at = activation_timestamp
  WHERE component_generation_id IN (p_exact30_generation_id, p_oa112_generation_id);
  UPDATE public.rag_v2_immutable_public_bundle_pointers
  SET state = 'ACTIVE',
      exact30_generation_id = p_exact30_generation_id,
      oa112_generation_id = p_oa112_generation_id,
      embedding_profile_id = exact_generation.embedding_profile_id,
      pointer_version = pointer_record.pointer_version + 1,
      updated_at = activation_timestamp
  WHERE state_id = 'default';
  INSERT INTO public.rag_v2_immutable_activation_receipts (
    activation_receipt_id,
    owner_user_id,
    activation_kind,
    activated_bundle_id,
    exact30_generation_id,
    oa112_generation_id,
    owner_private_generation_id,
    embedding_profile_id,
    previous_pointer_version,
    new_pointer_version,
    invalidated_owner_bundle_count,
    created_at
  )
  VALUES (
    p_activation_receipt_id,
    NULL,
    'PUBLIC_BASE',
    NULL,
    p_exact30_generation_id,
    p_oa112_generation_id,
    NULL,
    exact_generation.embedding_profile_id,
    pointer_record.pointer_version,
    pointer_record.pointer_version + 1,
    invalidated_owner_bundle_count,
    activation_timestamp
  );
  PERFORM set_config('app.rag_admin_maintenance', '', true);
  RETURN pointer_record.pointer_version + 1;
END;
$_$;


ALTER FUNCTION public.activate_rag_v2_immutable_public_base(p_exact30_generation_id text, p_oa112_generation_id text, p_expected_pointer_version bigint, p_activation_receipt_id text) OWNER TO flyway;


CREATE FUNCTION public.activate_signal_model_and_batch(p_model_release_id text, p_signal_batch_id text, p_expected_model_release_id text, p_expected_signal_batch_id text, p_expected_release_manifest_sha256 text, p_expected_batch_manifest_sha256 text, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  current_model text;
  current_batch text;
  current_model_generation bigint;
  current_batch_generation bigint;
  next_generation bigint;
  transition_digest text;
  target_status text;
  target_batch_manifest text;
  publication_digest text;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_signal_admin'
     OR p_expected_release_manifest_sha256 !~ '^[0-9a-f]{64}$'
     OR p_expected_batch_manifest_sha256 !~ '^[0-9a-f]{64}$'
     OR p_reason NOT IN ('MANUAL_ACTIVATION','MANUAL_ROLLBACK') THEN
    RAISE EXCEPTION 'S5 activation actor or reason is invalid' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('s5-signal-active-pointer-v1', 0));
  SELECT model_release_id, generation INTO current_model, current_model_generation
  FROM public.active_signal_model_release WHERE singleton FOR UPDATE;
  SELECT signal_batch_id, generation INTO current_batch, current_batch_generation
  FROM public.active_signal_batch WHERE singleton FOR UPDATE;
  IF current_model IS DISTINCT FROM NULLIF(p_expected_model_release_id, '')
     OR current_batch IS DISTINCT FROM NULLIF(p_expected_signal_batch_id, '') THEN
    RAISE EXCEPTION 'S5 active pointer CAS conflict' USING ERRCODE = '40001';
  END IF;
  SELECT lifecycle_status INTO target_status
  FROM public.signal_model_releases
  WHERE model_release_id = p_model_release_id
    AND release_manifest_sha256 = p_expected_release_manifest_sha256
  FOR UPDATE;
  IF (p_reason = 'MANUAL_ACTIVATION' AND target_status IS DISTINCT FROM 'STAGED')
     OR (p_reason = 'MANUAL_ROLLBACK' AND target_status IS DISTINCT FROM 'ACCEPTED') THEN
    RAISE EXCEPTION 'S5 activation lifecycle transition is invalid' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.signal_batches batch
    JOIN public.signal_model_releases release USING (model_release_id)
    JOIN public.current_s5_signal_batch_clock() current_clock
      ON current_clock.session_date = batch.session_date AND current_clock.as_of = batch.as_of
    WHERE batch.signal_batch_id = p_signal_batch_id
      AND batch.model_release_id = p_model_release_id AND batch.status = 'FINALIZED'
      AND batch.batch_manifest_sha256 = p_expected_batch_manifest_sha256
      AND batch.batch_purpose = CASE p_reason
        WHEN 'MANUAL_ROLLBACK' THEN 'ROLLBACK' ELSE 'DAILY' END
      AND batch.row_count = 31 AND release.qualification_status = 'QUALIFIED'
      AND release.lifecycle_status IN ('STAGED','ACCEPTED')
      AND NOT EXISTS (
        SELECT 1 FROM public.signal_batch_publications publication
        WHERE publication.signal_batch_id = batch.signal_batch_id
      )
      AND (SELECT count(*) FROM public.signal_batch_members member
           WHERE member.signal_batch_id = batch.signal_batch_id AND member.status = 'AVAILABLE') = 31
  ) THEN
    RAISE EXCEPTION 'S5 activation release or batch is invalid' USING ERRCODE = '22023';
  END IF;
  SELECT batch_manifest_sha256 INTO target_batch_manifest
  FROM public.signal_batches WHERE signal_batch_id = p_signal_batch_id;
  -- daily publish는 batch generation만 전진하므로 두 pointer 중 큰 값에서 다음 세대를 만든다.
  next_generation := GREATEST(
    COALESCE(current_model_generation, 0), COALESCE(current_batch_generation, 0)
  ) + 1;
  UPDATE public.signal_model_releases SET lifecycle_status = 'ACCEPTED'
  WHERE model_release_id = p_model_release_id AND lifecycle_status = 'STAGED';
  transition_digest := encode(digest(convert_to(concat_ws(E'\n',
    's5-model-transition-v1', p_model_release_id, target_status, 'ACCEPTED',
    p_signal_batch_id, p_reason),
    'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.signal_model_release_transitions(
    transition_id, model_release_id, from_status, to_status, reason, evidence_sha256, actor_role
  ) VALUES (
    'smrt-' || substr(transition_digest, 1, 24), p_model_release_id, target_status, 'ACCEPTED',
    p_reason, target_batch_manifest,
    session_user
  ) ON CONFLICT (model_release_id, to_status, reason, evidence_sha256) DO NOTHING;
  INSERT INTO public.active_signal_model_release(singleton, model_release_id, generation)
  VALUES (true, p_model_release_id, next_generation)
  ON CONFLICT (singleton) DO UPDATE SET model_release_id = EXCLUDED.model_release_id,
    generation = EXCLUDED.generation, activated_at = clock_timestamp();
  INSERT INTO public.active_signal_batch(singleton, signal_batch_id, generation)
  VALUES (true, p_signal_batch_id, next_generation)
  ON CONFLICT (singleton) DO UPDATE SET signal_batch_id = EXCLUDED.signal_batch_id,
    generation = EXCLUDED.generation, published_at = clock_timestamp();
  publication_digest := encode(digest(convert_to(concat_ws(E'\n',
    's5-batch-publication-v1', p_signal_batch_id, next_generation::text, p_reason),
    'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.signal_batch_publications(
    publication_id, signal_batch_id, model_release_id, generation, reason, actor_role
  ) VALUES (
    'sbp-' || substr(publication_digest, 1, 24), p_signal_batch_id, p_model_release_id,
    next_generation, p_reason, session_user
  );
  RETURN next_generation;
END
$_$;


ALTER FUNCTION public.activate_signal_model_and_batch(p_model_release_id text, p_signal_batch_id text, p_expected_model_release_id text, p_expected_signal_batch_id text, p_expected_release_manifest_sha256 text, p_expected_batch_manifest_sha256 text, p_reason text) OWNER TO flyway;


CREATE FUNCTION public.activate_signal_v2_production_pointer(p_logical_identity_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  candidate public.ingested_signals%ROWTYPE;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'Signal v2 pointer actor is invalid' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO candidate FROM public.ingested_signals
  WHERE logical_identity_sha256 = p_logical_identity_sha256 FOR SHARE;
  IF NOT FOUND OR candidate.producer = 'LIGHTGBM' OR candidate.fixture
     OR candidate.provenance_class <> 'PRODUCTION' OR NOT candidate.artifact_verified
     OR candidate.status <> 'AVAILABLE' THEN
    RAISE EXCEPTION 'Signal v2 production pointer candidate is invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.signal_v2_production_pointers(producer, timeframe, logical_identity_sha256)
  VALUES (candidate.producer, candidate.timeframe, candidate.logical_identity_sha256)
  ON CONFLICT (producer, timeframe) DO UPDATE
  SET logical_identity_sha256 = EXCLUDED.logical_identity_sha256, activated_at = clock_timestamp();
END
$$;


ALTER FUNCTION public.activate_signal_v2_production_pointer(p_logical_identity_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.activate_verified_rag_generation(p_generation_id text, p_expected_current_generation_id text, p_expected_policy_version bigint, p_expected_corpus_hash text, p_generation_hash text, p_membership_hash text, p_aggregate_row_hash text, p_db_vector_hash text, p_expected_source_revision_count integer, p_expected_chunk_count integer, p_batch_size integer, p_model_revision text, p_model_file_manifest_hash text, p_tokenizer_sha256 text, p_parser_version text, p_chunker_version text, p_input_strategy_version text, p_batch_benchmark_sha256 text, p_environment_fingerprint_sha256 text, p_benchmark_report_sha256 text, p_warm_p95_ms numeric, p_approved_by_audit_ref text) RETURNS TABLE(previous_generation_id text, active_generation_id text, policy_version bigint, generation_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  state_record record;
  generation_record record;
  source_revision_count bigint;
  membership_count bigint;
  embedding_count bigint;
  invalid_vector_count bigint;
  invalid_row_hash_count bigint;
  computed_membership_hash text;
  computed_aggregate_row_hash text;
  transition_id text;
  transition_trigger text;
  transition_time timestamptz := transaction_timestamp();
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_generation_id !~ '^rag_gen_[0-9a-f]{32}$'
     OR (
       p_expected_current_generation_id IS NOT NULL
       AND p_expected_current_generation_id !~ '^rag_gen_[0-9a-f]{32}$'
     )
     OR p_expected_policy_version < 1
     OR p_expected_corpus_hash NOT IN (
       '7f2b4d72dcbaccf57cbe49a980973b17b4a9bfd85bec4694fd66fd7fd2a9decd',
       'bdc42bfb735b411156ec2f79626d6fd2cf56662c57d83e2cdb960fb74e7b0e04'
     )
     OR p_generation_hash !~ '^[0-9a-f]{64}$'
     OR p_generation_id <> 'rag_gen_' || substr(p_generation_hash, 1, 32)
     OR p_membership_hash !~ '^[0-9a-f]{64}$'
     OR p_aggregate_row_hash !~ '^[0-9a-f]{64}$'
     OR p_db_vector_hash !~ '^[0-9a-f]{64}$'
     OR p_expected_source_revision_count <> 30
     OR p_expected_chunk_count <> 30
     OR p_batch_size NOT BETWEEN 16 AND 64
     OR p_model_revision <> '5617a9f61b028005a4858fdac845db406aefb181'
     OR p_model_file_manifest_hash
        <> 'a0ae6372b2d735b593d806d24c1155cb48dd7188adebe7d6b7619a1622fb71aa'
     OR p_tokenizer_sha256
        <> '6710678b12670bc442b99edc952c4d996ae309a7020c1fa0096dd245c2faf790'
     OR p_parser_version <> 'rag-source-card-v2-markdown-v1'
     OR p_chunker_version <> 'bge-tokenizer-heading-400-600-v1'
     OR p_input_strategy_version <> 'adjacent-7.5pct-per-side-no-reallocation-v1'
     OR p_batch_benchmark_sha256 !~ '^[0-9a-f]{64}$'
     OR p_environment_fingerprint_sha256 !~ '^[0-9a-f]{64}$'
     OR p_benchmark_report_sha256 !~ '^[0-9a-f]{64}$'
     OR p_warm_p95_ms <= 0
     OR p_warm_p95_ms > 1500.0
     OR char_length(p_approved_by_audit_ref) NOT BETWEEN 16 AND 128 THEN
    RAISE EXCEPTION 'RAG verified activation argument is invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT state.*
  INTO state_record
  FROM public.rag_embedding_policy_state AS state
  WHERE state.state_id = 'default'
  FOR UPDATE;
  IF NOT FOUND
     OR state_record.version IS DISTINCT FROM p_expected_policy_version
     OR state_record.active_generation_id IS DISTINCT FROM p_expected_current_generation_id
     OR state_record.policy_id <> 'bge_only_v1'
     OR state_record.effective_profile_id <> 'bge_m3_local_1024_v1'
     OR state_record.active_generation_id IS NOT DISTINCT FROM p_generation_id THEN
    RAISE EXCEPTION 'RAG activation pointer CAS failed'
      USING ERRCODE = '40001';
  END IF;

  -- target과 이전 active row를 byte-order로 잠가 concurrent replacement의 deadlock surface를 줄인다.
  PERFORM generation.corpus_generation_id
  FROM public.rag_corpus_generations AS generation
  WHERE generation.corpus_generation_id IN (
    p_generation_id,
    coalesce(p_expected_current_generation_id, p_generation_id)
  )
  ORDER BY convert_to(generation.corpus_generation_id, 'UTF8')
  FOR UPDATE;

  SELECT generation.*
  INTO generation_record
  FROM public.rag_corpus_generations AS generation
  WHERE generation.corpus_generation_id = p_generation_id;
  IF NOT FOUND
     OR generation_record.status <> 'MATERIALIZED'
     OR generation_record.evaluation_status <> 'PENDING'
     OR generation_record.corpus_hash <> p_expected_corpus_hash
     OR generation_record.embedding_profile_id <> 'bge_m3_local_1024_v1'
     OR generation_record.vector_space <> 'bge_m3_local_1024_v1'
     OR generation_record.expected_chunk_count <> p_expected_chunk_count
     OR generation_record.actual_chunk_count <> p_expected_chunk_count THEN
    RAISE EXCEPTION 'RAG activation target generation is not materialized'
      USING ERRCODE = '23514';
  END IF;

  IF p_expected_current_generation_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.rag_corpus_generations AS previous
       WHERE previous.corpus_generation_id = p_expected_current_generation_id
         AND previous.status = 'ACTIVE'
         AND previous.embedding_profile_id = 'bge_m3_local_1024_v1'
     ) THEN
    RAISE EXCEPTION 'RAG activation previous generation is not active'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    count(DISTINCT chunk.source_revision_id),
    count(*),
    count(embedding.chunk_embedding_id),
    count(*) FILTER (
      WHERE embedding.chunk_embedding_id IS NULL
         OR vector_dims(embedding.embedding) <> 1024
         OR vector_norm(embedding.embedding)::text IN ('NaN', 'Infinity', '-Infinity')
         OR abs(vector_norm(embedding.embedding)::double precision - 1.0) > 0.00001
    ),
    count(*) FILTER (
      WHERE embedding.materialization_row_hash IS NULL
         OR embedding.materialization_row_hash !~ '^[0-9a-f]{64}$'
    ),
    encode(
      digest(
        string_agg(
          encode(
            digest(
              concat_ws(
                E'\n',
                source.source_id,
                chunk.source_revision_id,
                membership.chunk_revision_id,
                chunk.canonical_content_hash,
                membership.embedding_input_hash,
                membership.ordinal::text
              ),
              'sha256'
            ),
            'hex'
          ),
          ''
          ORDER BY membership.ordinal
        ),
        'sha256'
      ),
      'hex'
    ),
    encode(
      digest(
        string_agg(
          embedding.materialization_row_hash,
          ''
          ORDER BY convert_to(membership.chunk_revision_id, 'UTF8')
        ),
        'sha256'
      ),
      'hex'
    )
  INTO
    source_revision_count,
    membership_count,
    embedding_count,
    invalid_vector_count,
    invalid_row_hash_count,
    computed_membership_hash,
    computed_aggregate_row_hash
  FROM public.rag_generation_chunks AS membership
  JOIN public.rag_chunk_revisions AS chunk
    ON chunk.chunk_revision_id = membership.chunk_revision_id
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = chunk.source_revision_id
   AND revision.tier = 'PROJECT'
   AND revision.access_level = 'PUBLIC'
   AND (
     (
       p_expected_corpus_hash = '7f2b4d72dcbaccf57cbe49a980973b17b4a9bfd85bec4694fd66fd7fd2a9decd'
       AND revision.registry_version = 's4-7b-source-card-v2'
       AND NOT revision.external_processing_allowed
     )
     OR
     (
       p_expected_corpus_hash = 'bdc42bfb735b411156ec2f79626d6fd2cf56662c57d83e2cdb960fb74e7b0e04'
       AND revision.registry_version = 's4-7c-source-card-v2'
       AND revision.external_processing_allowed
       AND position(
         'approvalId=AUTH_EXTERNAL_PROCESSING_30_PROJECT_CARDS_20260731' IN revision.license_note
       ) > 0
     )
   )
  JOIN public.rag_sources AS source
    ON source.source_id = revision.source_id
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  LEFT JOIN public.rag_chunk_embeddings AS embedding
    ON embedding.corpus_generation_id = membership.corpus_generation_id
   AND embedding.chunk_revision_id = membership.chunk_revision_id
   AND embedding.embedding_profile_id = membership.embedding_profile_id
   AND embedding.embedding_input_hash = membership.embedding_input_hash
   AND embedding.context_set_hash IS NOT DISTINCT FROM membership.context_set_hash
  WHERE membership.corpus_generation_id = p_generation_id
    AND membership.embedding_profile_id = 'bge_m3_local_1024_v1';

  IF source_revision_count <> p_expected_source_revision_count
     OR membership_count <> p_expected_chunk_count
     OR embedding_count <> p_expected_chunk_count
     OR invalid_vector_count <> 0
     OR invalid_row_hash_count <> 0
     OR computed_membership_hash IS DISTINCT FROM p_membership_hash
     OR computed_aggregate_row_hash IS DISTINCT FROM p_aggregate_row_hash THEN
    RAISE EXCEPTION 'RAG activation graph attestation failed'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.rag_generation_attestations (
    corpus_generation_id,
    corpus_hash,
    generation_hash,
    membership_hash,
    aggregate_row_hash,
    generation_vector_hash,
    db_vector_hash,
    source_revision_count,
    chunk_count,
    batch_size,
    model_revision,
    model_file_manifest_hash,
    tokenizer_sha256,
    parser_version,
    chunker_version,
    input_strategy_version,
    batch_benchmark_sha256,
    environment_fingerprint_sha256,
    benchmark_report_sha256,
    warm_p95_ms,
    approved_by_audit_ref
  )
  VALUES (
    p_generation_id,
    p_expected_corpus_hash,
    p_generation_hash,
    p_membership_hash,
    p_aggregate_row_hash,
    p_db_vector_hash,
    p_db_vector_hash,
    p_expected_source_revision_count,
    p_expected_chunk_count,
    p_batch_size,
    p_model_revision,
    p_model_file_manifest_hash,
    p_tokenizer_sha256,
    p_parser_version,
    p_chunker_version,
    p_input_strategy_version,
    p_batch_benchmark_sha256,
    p_environment_fingerprint_sha256,
    p_benchmark_report_sha256,
    p_warm_p95_ms,
    p_approved_by_audit_ref
  );

  UPDATE public.rag_corpus_generations AS generation
  SET
    status = 'EVAL_PASSED',
    evaluation_status = 'PASSED',
    evaluated_at = transition_time
  WHERE generation.corpus_generation_id = p_generation_id
    AND generation.status = 'MATERIALIZED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG generation verification transition failed'
      USING ERRCODE = '23514';
  END IF;

  IF p_expected_current_generation_id IS NOT NULL THEN
    UPDATE public.rag_corpus_generations AS previous
    SET
      status = 'DISABLED',
      disabled_at = transition_time
    WHERE previous.corpus_generation_id = p_expected_current_generation_id
      AND previous.status = 'ACTIVE';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'RAG previous generation supersede transition failed'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  UPDATE public.rag_corpus_generations AS generation
  SET
    status = 'ACTIVE',
    activated_at = transition_time
  WHERE generation.corpus_generation_id = p_generation_id
    AND generation.status = 'EVAL_PASSED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG generation activation transition failed'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.rag_embedding_policy_state AS state
  SET
    policy_id = 'bge_only_v1',
    effective_profile_id = 'bge_m3_local_1024_v1',
    active_generation_id = p_generation_id,
    version = state.version + 1,
    changed_at = transition_time,
    changed_by_audit_ref = p_approved_by_audit_ref
  WHERE state.state_id = 'default'
    AND state.version = p_expected_policy_version
    AND state.active_generation_id IS NOT DISTINCT FROM p_expected_current_generation_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG activation pointer update lost CAS'
      USING ERRCODE = '40001';
  END IF;

  transition_trigger := CASE
    WHEN p_expected_current_generation_id IS NULL THEN 'INITIAL_ADMIN_SELECTION'
    ELSE 'ADMIN_ROLLBACK'
  END;
  transition_id :=
    'rag_pol_' ||
    substr(
      encode(
        digest(
          concat_ws(
            E'\n',
            'default',
            p_expected_policy_version::text,
            (p_expected_policy_version + 1)::text,
            coalesce(p_expected_current_generation_id, ''),
            p_generation_id,
            p_approved_by_audit_ref
          ),
          'sha256'
        ),
        'hex'
      ),
      1,
      32
    );
  INSERT INTO public.rag_embedding_policy_transitions (
    transition_id,
    state_id,
    from_version,
    to_version,
    from_policy_id,
    to_policy_id,
    from_profile_id,
    to_profile_id,
    target_generation_id,
    trigger_code,
    approved_by_audit_ref,
    approved_at
  )
  VALUES (
    transition_id,
    'default',
    p_expected_policy_version,
    p_expected_policy_version + 1,
    'bge_only_v1',
    'bge_only_v1',
    'bge_m3_local_1024_v1',
    'bge_m3_local_1024_v1',
    p_generation_id,
    transition_trigger,
    p_approved_by_audit_ref,
    transition_time
  );

  RETURN QUERY
  SELECT
    p_expected_current_generation_id,
    p_generation_id,
    p_expected_policy_version + 1,
    'ACTIVE'::text;
END
$_$;


