CREATE FUNCTION public.aggregate_signal_freshness() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  bucket_start timestamptz := date_trunc('hour', statement_timestamp())
    + floor(extract(minute FROM statement_timestamp()) / 5) * interval '5 minutes';
  completed_close timestamptz;
  source_count bigint;
  stale_count bigint;
  ratio numeric(10,6);
  changed integer;
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'stream metric writer role denied' USING ERRCODE = '42501';
  END IF;
  SELECT max(close_at) INTO completed_close
  FROM public.trading_sessions
  WHERE exchange_mic = 'XKRX' AND is_open AND close_at <= statement_timestamp();
  WITH latest AS (
    SELECT DISTINCT ON (producer, symbol, timeframe)
      producer, symbol, timeframe, as_of, status
    FROM public.ingested_signals
    WHERE fixture = false AND provenance_class = 'PRODUCTION'
    ORDER BY producer, symbol, timeframe, session_date DESC, created_at DESC, signal_id DESC
  )
  SELECT count(*), count(*) FILTER (
    WHERE status <> 'AVAILABLE' OR as_of IS NULL
       OR (timeframe = '60m' AND as_of < statement_timestamp() - interval '90 minutes')
       OR (timeframe = '1d' AND (completed_close IS NULL OR as_of < completed_close))
       OR timeframe NOT IN ('1d', '60m')
       OR as_of > statement_timestamp()
  ) INTO source_count, stale_count
  FROM latest;
  ratio := CASE WHEN source_count = 0 THEN NULL ELSE stale_count::numeric / source_count END;
  INSERT INTO public.stream_metric_snapshot(
    snapshot_id, snapshot_kind, component_status, observed_at,
    window_start, window_end, stale_signal_ratio
  ) VALUES (
    'metric_signal_' || to_char(bucket_start AT TIME ZONE 'UTC', 'YYYYMMDDHH24MI'),
    'SIGNAL_FRESHNESS', CASE WHEN source_count = 0 THEN 'UNAVAILABLE' ELSE 'OK' END,
    statement_timestamp(), bucket_start, bucket_start + interval '5 minutes', ratio
  ) ON CONFLICT (snapshot_kind, window_start) WHERE snapshot_kind <> 'LEGACY_FULL' DO NOTHING;
  GET DIAGNOSTICS changed = ROW_COUNT;
  RETURN changed = 1;
END
$$;


ALTER FUNCTION public.aggregate_signal_freshness() OWNER TO flyway;


CREATE FUNCTION public.append_analyst_revision_evidence(p_record jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  inserted_count integer;
BEGIN
  PERFORM public.validate_cross_market_fixture_payload(
    p_record,
    jsonb_build_object(
      'artifactHash', true,
      'availableAt', true,
      'brokerId', true,
      'buyOpinionWeight', true,
      'contractId', true,
      'contributorCount', true,
      'current', jsonb_build_object(
        'eps', true,
        'rating', true,
        'revenue', true,
        'targetPrice', true
      ),
      'decisionAuthority', true,
      'dedupeKeyHash', true,
      'dispersion', true,
      'estimatePeriod', true,
      'logicalIdentityHash', true,
      'originalEvidenceId', true,
      'payloadHash', true,
      'previous', jsonb_build_object(
        'eps', true,
        'rating', true,
        'revenue', true,
        'targetPrice', true
      ),
      'publishedAt', true,
      'rawTextStored', true,
      'receivedAt', true,
      'retracted', true,
      'revision', jsonb_build_object(
        'epsDelta', true,
        'ratingChanged', true,
        'revenueDelta', true,
        'targetPriceDelta', true
      ),
      'schemaVersion', true,
      'sourceLicense', true,
      'supersedesEvidenceId', true,
      'symbol', true,
      'userConfirmedTags', true
    )
  );
  IF p_record ->> 'contractId' <> 'analyst_revision_evidence.v1'
     OR p_record ->> 'schemaVersion' <> '1'
     OR p_record ->> 'logicalIdentityHash' !~ '^[0-9a-f]{64}$'
     OR p_record ->> 'payloadHash' !~ '^[0-9a-f]{64}$'
     OR p_record ->> 'artifactHash' !~ '^[0-9a-f]{64}$'
     OR (p_record ->> 'rawTextStored')::boolean
     OR (p_record ->> 'buyOpinionWeight')::numeric <> 0 THEN
    RAISE EXCEPTION 'analyst revision payload is invalid'
      USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.analyst_revision_evidence (
    logical_identity_hash, original_evidence_id, symbol, broker_id, estimate_period,
    contributor_count, buy_opinion_weight, dispersion, published_at, received_at,
    available_at, retracted, supersedes_evidence_id, dedupe_key_hash, payload_hash,
    artifact_hash, payload_json
  ) VALUES (
    p_record ->> 'logicalIdentityHash', p_record ->> 'originalEvidenceId', p_record ->> 'symbol',
    p_record ->> 'brokerId', p_record ->> 'estimatePeriod',
    (p_record ->> 'contributorCount')::integer, (p_record ->> 'buyOpinionWeight')::numeric,
    (p_record ->> 'dispersion')::numeric, (p_record ->> 'publishedAt')::timestamptz,
    (p_record ->> 'receivedAt')::timestamptz, (p_record ->> 'availableAt')::timestamptz,
    (p_record ->> 'retracted')::boolean, nullif(p_record ->> 'supersedesEvidenceId', ''),
    p_record ->> 'dedupeKeyHash', p_record ->> 'payloadHash', p_record ->> 'artifactHash', p_record
  )
  ON CONFLICT (logical_identity_hash) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count = 1 THEN RETURN 'INSERTED'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.analyst_revision_evidence
    WHERE logical_identity_hash = p_record ->> 'logicalIdentityHash' AND payload_json = p_record
  ) THEN RETURN 'REPLAY'; END IF;
  RAISE EXCEPTION 'analyst revision identity conflict' USING ERRCODE = '23505';
END
$_$;


