CREATE FUNCTION public.append_financial_engineering_result(p_run_id uuid, p_schema_version integer, p_symbol text, p_session_date date, p_as_of timestamp with time zone, p_available_at timestamp with time zone, p_source_manifest_hash text, p_config_hash text, p_numeric_payload_hash text, p_artifact_hash text, p_availability text, p_quality text, p_staleness text, p_numeric_payload_text text, p_explanatory_payload_text text, p_report_artifact_hash text, p_report_bytes integer, p_steps_text text) RETURNS TABLE(outcome text, snapshot_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  computed_snapshot_id text;
  existing public.financial_engineering_snapshots%ROWTYPE;
  existing_report public.financial_engineering_report_manifests%ROWTYPE;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_market_writer'
     OR p_schema_version <> 1
     OR p_symbol !~ '^[0-9A-Z./-]{1,32}$'
     OR p_source_manifest_hash !~ '^[0-9a-f]{64}$'
     OR p_config_hash !~ '^[0-9a-f]{64}$'
     OR p_numeric_payload_hash !~ '^[0-9a-f]{64}$'
     OR p_artifact_hash !~ '^[0-9a-f]{64}$'
     OR p_report_artifact_hash !~ '^[0-9a-f]{64}$'
     OR octet_length(p_numeric_payload_text) NOT BETWEEN 2 AND 262144
     OR octet_length(p_explanatory_payload_text) NOT BETWEEN 2 AND 65536
     OR octet_length(p_steps_text) NOT BETWEEN 2 AND 16384 THEN
    RAISE EXCEPTION 'financial engineering append arguments are invalid' USING ERRCODE = '22023';
  END IF;
  IF encode(digest(convert_to(p_numeric_payload_text, 'UTF8'), 'sha256'), 'hex') <> p_numeric_payload_hash THEN
    RAISE EXCEPTION 'numeric payload hash mismatch' USING ERRCODE = '22023';
  END IF;
  computed_snapshot_id := 'fes_' || substr(encode(digest(convert_to(concat_ws(E'\n',
    'financial-engineering-snapshot-identity-v1', p_schema_version::text, p_symbol,
    p_session_date::text, p_as_of::text, p_available_at::text), 'UTF8'), 'sha256'), 'hex'), 1, 24);

  PERFORM pg_advisory_xact_lock(hashtextextended(computed_snapshot_id, 0));
  SELECT * INTO existing FROM public.financial_engineering_snapshots
  WHERE financial_engineering_snapshots.snapshot_id = computed_snapshot_id;
  IF FOUND THEN
    SELECT * INTO existing_report FROM public.financial_engineering_report_manifests
    WHERE financial_engineering_report_manifests.snapshot_id = computed_snapshot_id;
    IF existing.artifact_hash = p_artifact_hash
       AND existing.numeric_payload_hash = p_numeric_payload_hash
       AND existing_report.report_artifact_hash = p_report_artifact_hash
       AND existing_report.complete THEN
      RETURN QUERY SELECT 'NO_OP'::text, computed_snapshot_id;
      RETURN;
    END IF;
    RAISE EXCEPTION 'financial engineering identity hash conflict' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.financial_engineering_snapshots (
    snapshot_id, schema_version, symbol, session_date, as_of, available_at,
    source_manifest_hash, config_hash, numeric_payload_hash, artifact_hash,
    availability, quality, staleness, numeric_payload, explanatory_payload
  ) VALUES (
    computed_snapshot_id, p_schema_version, p_symbol, p_session_date, p_as_of, p_available_at,
    p_source_manifest_hash, p_config_hash, p_numeric_payload_hash, p_artifact_hash,
    p_availability, p_quality, p_staleness, p_numeric_payload_text::jsonb,
    p_explanatory_payload_text::jsonb
  );
  INSERT INTO public.financial_engineering_report_manifests (
    run_id, snapshot_id, snapshot_artifact_hash, report_artifact_hash,
    report_bytes, steps, complete
  ) VALUES (
    p_run_id, computed_snapshot_id, p_artifact_hash, p_report_artifact_hash,
    p_report_bytes, p_steps_text::jsonb, true
  );
  RETURN QUERY SELECT 'INSERTED'::text, computed_snapshot_id;
END
$_$;


ALTER FUNCTION public.append_financial_engineering_result(p_run_id uuid, p_schema_version integer, p_symbol text, p_session_date date, p_as_of timestamp with time zone, p_available_at timestamp with time zone, p_source_manifest_hash text, p_config_hash text, p_numeric_payload_hash text, p_artifact_hash text, p_availability text, p_quality text, p_staleness text, p_numeric_payload_text text, p_explanatory_payload_text text, p_report_artifact_hash text, p_report_bytes integer, p_steps_text text) OWNER TO flyway;


CREATE FUNCTION public.append_kill_switch_outbox(p_event_id text, p_active boolean, p_changed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF session_user <> 'decision_app' THEN RAISE EXCEPTION 'kill switch outbox append role denied' USING ERRCODE='42501'; END IF;
  IF p_event_id !~ '^evt_[A-Za-z0-9_-]{8,96}$' OR p_changed_at IS NULL THEN
    RAISE EXCEPTION 'invalid kill switch outbox payload' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.event_outbox(
    event_id,event_type,aggregate_type,aggregate_id,partition_key,payload_json,schema_version,status,retry_count,created_at,updated_at
  ) VALUES (
    p_event_id,'kill-switch.changed','KILL_SWITCH','GLOBAL','GLOBAL',
    jsonb_build_object('active',p_active,'changedAt',p_changed_at::text),'1.0.0','PENDING',0,p_changed_at,p_changed_at
  );
  RETURN true;
END
$_$;


ALTER FUNCTION public.append_kill_switch_outbox(p_event_id text, p_active boolean, p_changed_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.append_market_cause_evidence(p_record jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  inserted_count integer;
BEGIN
  PERFORM public.validate_cross_market_fixture_payload(
    p_record,
    jsonb_build_object(
      'artifactHash', true,
      'availableAt', true,
      'classification', true,
      'contractId', true,
      'contradictionEvidenceIds', true,
      'counterargument', true,
      'decisionAuthority', true,
      'dedupeKeyHash', true,
      'logicalIdentityHash', true,
      'occurredAt', true,
      'payloadHash', true,
      'publishedAt', true,
      'receivedAt', true,
      'relatedEvidenceIds', true,
      'relation', true,
      'retracted', true,
      'sanitizedSummary', true,
      'schemaVersion', true,
      'sourceFamily', true,
      'sourceLineageHash', true,
      'supersedesEvidenceId', true
    )
  );
  IF p_record ->> 'contractId' <> 'market_cause_evidence.v1'
     OR p_record ->> 'schemaVersion' <> '1'
     OR p_record ->> 'logicalIdentityHash' !~ '^[0-9a-f]{64}$'
     OR p_record ->> 'payloadHash' !~ '^[0-9a-f]{64}$'
     OR p_record ->> 'artifactHash' !~ '^[0-9a-f]{64}$'
     OR (
       p_record ->> 'sourceFamily' = 'GDELT_AGGREGATE'
       AND (
         p_record ->> 'classification' = 'CONFIRMED_FACT'
         OR p_record ->> 'relation' = 'REPORTED_AS_CAUSE'
       )
     ) THEN
    RAISE EXCEPTION 'market cause payload is invalid'
      USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.market_cause_evidence (
    logical_identity_hash, source_family, source_lineage_hash, dedupe_key_hash,
    classification, relation, counterargument, retracted, supersedes_evidence_id,
    occurred_at, published_at, received_at, available_at, sanitized_summary,
    payload_hash, artifact_hash, payload_json
  ) VALUES (
    p_record ->> 'logicalIdentityHash', p_record ->> 'sourceFamily',
    p_record ->> 'sourceLineageHash', p_record ->> 'dedupeKeyHash',
    p_record ->> 'classification', p_record ->> 'relation',
    (p_record ->> 'counterargument')::boolean, (p_record ->> 'retracted')::boolean,
    nullif(p_record ->> 'supersedesEvidenceId', ''), (p_record ->> 'occurredAt')::timestamptz,
    (p_record ->> 'publishedAt')::timestamptz, (p_record ->> 'receivedAt')::timestamptz,
    (p_record ->> 'availableAt')::timestamptz, p_record ->> 'sanitizedSummary',
    p_record ->> 'payloadHash', p_record ->> 'artifactHash', p_record
  )
  ON CONFLICT (logical_identity_hash) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count = 1 THEN RETURN 'INSERTED'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.market_cause_evidence
    WHERE logical_identity_hash = p_record ->> 'logicalIdentityHash' AND payload_json = p_record
  ) THEN RETURN 'REPLAY'; END IF;
  RAISE EXCEPTION 'market cause identity conflict' USING ERRCODE = '23505';
END
$_$;


ALTER FUNCTION public.append_market_cause_evidence(p_record jsonb) OWNER TO flyway;


CREATE FUNCTION public.append_market_source_entitlement(p_record jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  inserted_count integer;
BEGIN
  PERFORM public.validate_cross_market_fixture_payload(
    p_record,
    jsonb_build_object(
      'activationStatus', true,
      'attributionRequired', true,
      'category', true,
      'contractExpiry', true,
      'decisionAuthority', true,
      'deletionOwner', true,
      'derivedDataAllowed', true,
      'embeddingAllowed', true,
      'endpointIdentityHash', true,
      'entitlementVersion', true,
      'externalLlmAllowed', true,
      'logicalIdentityHash', true,
      'machineFetchAllowed', true,
      'materializationDeclaration', jsonb_build_object(
        'derivedPayloadProduced', true,
        'embedded', true,
        'externalLlmProcessed', true,
        'nonDisplayUsed', true,
        'rawStored', true
      ),
      'nonDisplayAllowed', true,
      'projectionRetentionMaxDays', true,
      'providerCallsAllowed', true,
      'rawRetentionMaxHours', true,
      'rawStoreAllowed', true,
      'region', true,
      'sourceFamily', true,
      'sourceId', true
    )
  );
  IF p_record ->> 'logicalIdentityHash' !~ '^[0-9a-f]{64}$'
     OR p_record ->> 'activationStatus' <> 'CANDIDATE_DISABLED'
     OR (p_record ->> 'providerCallsAllowed')::boolean
     OR (p_record ->> 'machineFetchAllowed')::boolean
     OR (p_record ->> 'rawStoreAllowed')::boolean
     OR (p_record ->> 'embeddingAllowed')::boolean
     OR (p_record ->> 'externalLlmAllowed')::boolean THEN
    RAISE EXCEPTION 'cross-market entitlement must remain disabled'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.market_source_entitlements (
    logical_identity_hash,
    source_id,
    source_family,
    category,
    activation_status,
    provider_calls_allowed,
    decision_authority,
    contract_expiry,
    record_hash,
    payload_json
  ) VALUES (
    p_record ->> 'logicalIdentityHash',
    p_record ->> 'sourceId',
    p_record ->> 'sourceFamily',
    p_record ->> 'category',
    p_record ->> 'activationStatus',
    (p_record ->> 'providerCallsAllowed')::boolean,
    p_record ->> 'decisionAuthority',
    (p_record ->> 'contractExpiry')::timestamptz,
    encode(digest(convert_to(p_record::text, 'UTF8'), 'sha256'), 'hex'),
    p_record
  )
  ON CONFLICT (logical_identity_hash) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count = 1 THEN
    RETURN 'INSERTED';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.market_source_entitlements
    WHERE logical_identity_hash = p_record ->> 'logicalIdentityHash'
      AND payload_json = p_record
  ) THEN
    RETURN 'REPLAY';
  END IF;
  RAISE EXCEPTION 'cross-market entitlement identity conflict'
    USING ERRCODE = '23505';
END
$_$;


ALTER FUNCTION public.append_market_source_entitlement(p_record jsonb) OWNER TO flyway;


CREATE FUNCTION public.append_owned_foreign_news_sentiment(p_owner_user_id text, p_record jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  payload jsonb;
  inserted_count integer;
  has_available_lane boolean;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_market_writer'
     OR p_owner_user_id !~ '^[A-Za-z0-9._:-]{3,128}$'
     OR jsonb_typeof(p_record) <> 'object'
     OR NOT (p_record ?& ARRAY['artifactHash', 'logicalIdentityHash', 'payload', 'payloadHash'])
     OR (SELECT count(*) FROM jsonb_object_keys(p_record)) <> 4
     OR jsonb_typeof(p_record -> 'artifactHash') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'logicalIdentityHash') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'payloadHash') IS DISTINCT FROM 'string'
     OR p_record ->> 'logicalIdentityHash' !~ '^[0-9a-f]{64}$'
     OR p_record ->> 'payloadHash' !~ '^[0-9a-f]{64}$'
     OR p_record ->> 'artifactHash' !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_record -> 'payload') <> 'object'
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'foreign-news writer arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  payload := p_record -> 'payload';
  IF NOT (payload ?& ARRAY[
      'allowedUses', 'articleMetadataStored', 'asOf', 'contractId', 'decisionAuthority', 'lanes',
      'rawProviderDataStored', 'riskDecisionHashIncluded', 's5FeatureEligible',
      'schemaVersion', 'status', 'symbol'
    ])
    OR (SELECT count(*) FROM jsonb_object_keys(payload)) <> 12
    OR payload -> 'allowedUses' <> '["EXPLANATION_ONLY"]'::jsonb
    OR jsonb_typeof(payload -> 'articleMetadataStored') IS DISTINCT FROM 'boolean'
    OR payload -> 'articleMetadataStored' IS DISTINCT FROM 'false'::jsonb
    OR jsonb_typeof(payload -> 'asOf') IS DISTINCT FROM 'string'
    OR jsonb_typeof(payload -> 'contractId') IS DISTINCT FROM 'string'
    OR payload ->> 'contractId' <> 'foreign-news-sentiment-v1'
    OR jsonb_typeof(payload -> 'decisionAuthority') IS DISTINCT FROM 'string'
    OR payload ->> 'decisionAuthority' <> 'NONE'
    OR jsonb_typeof(payload -> 'rawProviderDataStored') IS DISTINCT FROM 'boolean'
    OR payload -> 'rawProviderDataStored' IS DISTINCT FROM 'false'::jsonb
    OR jsonb_typeof(payload -> 'riskDecisionHashIncluded') IS DISTINCT FROM 'boolean'
    OR payload -> 'riskDecisionHashIncluded' IS DISTINCT FROM 'false'::jsonb
    OR jsonb_typeof(payload -> 's5FeatureEligible') IS DISTINCT FROM 'boolean'
    OR payload -> 's5FeatureEligible' IS DISTINCT FROM 'false'::jsonb
    OR jsonb_typeof(payload -> 'schemaVersion') IS DISTINCT FROM 'number'
    OR payload -> 'schemaVersion' IS DISTINCT FROM '1'::jsonb
    OR jsonb_typeof(payload -> 'symbol') IS DISTINCT FROM 'string'
    OR payload ->> 'symbol' !~ '^[0-9A-Z._:-]{1,20}$'
    OR jsonb_typeof(payload -> 'status') IS DISTINCT FROM 'string'
    OR payload ->> 'status' NOT IN ('AVAILABLE', 'ABSTAIN')
    OR NOT public.foreign_news_lane_states_are_safe(payload -> 'lanes') THEN
    RAISE EXCEPTION 'foreign-news sanitized payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  BEGIN
    PERFORM (payload ->> 'asOf')::timestamptz;
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'foreign-news as-of is invalid'
      USING ERRCODE = '22023';
  END;
  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(payload -> 'lanes') AS lane
    WHERE lane ->> 'state' = 'AVAILABLE'
  ) INTO has_available_lane;
  IF (payload ->> 'status' = 'AVAILABLE') IS DISTINCT FROM has_available_lane THEN
    RAISE EXCEPTION 'foreign-news availability does not match lanes'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.foreign_news_sentiment_aggregates (
    logical_identity_hash, owner_user_id, symbol, as_of, status, lane_states,
    payload_hash, artifact_hash, payload_json
  ) VALUES (
    p_record ->> 'logicalIdentityHash', p_owner_user_id, payload ->> 'symbol',
    (payload ->> 'asOf')::timestamptz, payload ->> 'status', payload -> 'lanes',
    p_record ->> 'payloadHash', p_record ->> 'artifactHash', payload
  ) ON CONFLICT (logical_identity_hash) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count = 1 THEN
    RETURN 'INSERTED';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.foreign_news_sentiment_aggregates AS aggregate
    WHERE aggregate.logical_identity_hash = p_record ->> 'logicalIdentityHash'
      AND aggregate.owner_user_id = p_owner_user_id
      AND aggregate.payload_json = payload
      AND aggregate.payload_hash = p_record ->> 'payloadHash'
      AND aggregate.artifact_hash = p_record ->> 'artifactHash'
  ) THEN
    RETURN 'REPLAY';
  END IF;
  RAISE EXCEPTION 'foreign-news aggregate identity conflict'
    USING ERRCODE = '23505';
END
$_$;


ALTER FUNCTION public.append_owned_foreign_news_sentiment(p_owner_user_id text, p_record jsonb) OWNER TO flyway;


CREATE FUNCTION public.append_s48_runtime_sanitized_projection(p_record jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  evaluated_at_value timestamptz;
  projection_hash_value text;
  inserted_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_market_writer'
     OR jsonb_typeof(p_record) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'S4.8 runtime writer arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT (p_record ?& ARRAY[
       'artifactHash', 'contractId', 'decisionAuthority', 'evaluatedAt', 'ingestionMode',
       'logicalIdentityHash', 'orderAuthority', 'payloadHash', 'projectionHash',
       'providerPhysicalCalls', 'rawProviderDataStored', 'reason', 'retryCount',
       'riskSignalOrderAuthority', 'schemaVersion', 'sourceFamily', 'sourceId', 'status'
     ])
     OR (SELECT count(*) FROM jsonb_object_keys(p_record)) <> 18
     OR jsonb_typeof(p_record -> 'artifactHash') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'contractId') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'decisionAuthority') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'ingestionMode') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'logicalIdentityHash') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'orderAuthority') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'payloadHash') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'reason') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'riskSignalOrderAuthority') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'sourceFamily') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'sourceId') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'status') IS DISTINCT FROM 'string'
     OR NOT COALESCE(p_record ->> 'artifactHash' ~ '^[0-9a-f]{64}$', false)
     OR NOT COALESCE(p_record ->> 'logicalIdentityHash' ~ '^[0-9a-f]{64}$', false)
     OR NOT COALESCE(p_record ->> 'payloadHash' ~ '^[0-9a-f]{64}$', false)
     OR p_record ->> 'contractId' IS DISTINCT FROM 's4-8-runtime-lane.v1'
     OR p_record ->> 'decisionAuthority' IS DISTINCT FROM 'NONE'
     OR p_record ->> 'orderAuthority' IS DISTINCT FROM 'NONE'
     OR p_record ->> 'riskSignalOrderAuthority' IS DISTINCT FROM 'NONE'
     OR jsonb_typeof(p_record -> 'schemaVersion') IS DISTINCT FROM 'number'
     OR p_record -> 'schemaVersion' IS DISTINCT FROM '1'::jsonb
     OR jsonb_typeof(p_record -> 'providerPhysicalCalls') IS DISTINCT FROM 'number'
     OR p_record -> 'providerPhysicalCalls' IS DISTINCT FROM '0'::jsonb
     OR jsonb_typeof(p_record -> 'rawProviderDataStored') IS DISTINCT FROM 'boolean'
     OR p_record -> 'rawProviderDataStored' IS DISTINCT FROM 'false'::jsonb
     OR jsonb_typeof(p_record -> 'retryCount') IS DISTINCT FROM 'number'
     OR p_record -> 'retryCount' IS DISTINCT FROM '0'::jsonb
     OR jsonb_typeof(p_record -> 'evaluatedAt') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_record -> 'projectionHash') NOT IN ('null', 'string') THEN
    RAISE EXCEPTION 'S4.8 runtime writer arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  IF p_record -> 'projectionHash' = 'null'::jsonb THEN
    projection_hash_value := NULL;
  ELSE
    projection_hash_value := p_record ->> 'projectionHash';
  END IF;
  BEGIN
    evaluated_at_value := (p_record ->> 'evaluatedAt')::timestamptz;
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'S4.8 runtime evaluated-at is invalid'
      USING ERRCODE = '22023';
  END;
  IF NOT public.s48_runtime_source_pair_is_valid(
      p_record ->> 'sourceFamily', p_record ->> 'sourceId'
    )
    OR NOT public.s48_runtime_state_is_safe(
      p_record ->> 'sourceFamily', p_record ->> 'ingestionMode', p_record ->> 'status',
      p_record ->> 'reason', projection_hash_value
    ) THEN
    RAISE EXCEPTION 'S4.8 runtime sanitized payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.s48_runtime_sanitized_projections (
    logical_identity_hash, source_family, source_id, evaluated_at, ingestion_mode, status,
    reason, projection_hash, payload_hash, artifact_hash, payload_json
  ) VALUES (
    p_record ->> 'logicalIdentityHash', p_record ->> 'sourceFamily', p_record ->> 'sourceId',
    evaluated_at_value, p_record ->> 'ingestionMode', p_record ->> 'status',
    p_record ->> 'reason', projection_hash_value, p_record ->> 'payloadHash',
    p_record ->> 'artifactHash', p_record
  ) ON CONFLICT (logical_identity_hash) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count = 1 THEN
    RETURN 'INSERTED';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.s48_runtime_sanitized_projections AS projection
    WHERE projection.logical_identity_hash = p_record ->> 'logicalIdentityHash'
      AND projection.payload_json = p_record
      AND projection.payload_hash = p_record ->> 'payloadHash'
      AND projection.artifact_hash = p_record ->> 'artifactHash'
  ) THEN
    RETURN 'REPLAY';
  END IF;
  RAISE EXCEPTION 'S4.8 runtime sanitized projection identity conflict'
    USING ERRCODE = '23505';
END
$_$;


ALTER FUNCTION public.append_s48_runtime_sanitized_projection(p_record jsonb) OWNER TO flyway;


CREATE FUNCTION public.apply_stored_order_fills(requested_payload jsonb, requested_capability_token text) RETURNS TABLE(operation_outcome text, order_id text, brokerage_mode text, status text, filled_quantity bigint, leaves_quantity bigint, unfilled_terminated_quantity bigint, average_fill_price_krw bigint, reconciliation_status text, reconciled_at timestamp with time zone, applied_event_count integer, has_more boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  requested_actor_user_id text;
  requested_actor_role text;
  requested_security_version bigint;
  requested_request_id text;
  requested_order_id text;
  requested_reconciled_at timestamptz;
  requested_audit_log_id text;
  requested_outbox_event_id text;
  requested_expected_final jsonb;
  stored_actor record;
  stored_order record;
  observation record;
  current_status text;
  current_filled bigint;
  current_leaves bigint;
  current_unfilled_terminated bigint;
  current_average bigint;
  current_notional numeric;
  delta_quantity bigint;
  next_average bigint;
  next_event_seq integer;
  transition_outcome text;
  transition_reason text;
  transition_status text;
  transition_event_type text;
  transition_event_status text;
  transition_payload jsonb;
  event_count integer := 0;
  invalid_count integer := 0;
  observation_count bigint;
  observed_fill_quantity bigint;
  recomputed_average bigint;
  provider_final_average bigint;
  conservation_matches boolean;
  remaining boolean;
  final_reconciliation_status text;
  final_reconciled_at timestamptz;
  actual_final jsonb;
  reference_payload jsonb;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  IF requested_payload IS NULL
     OR jsonb_typeof(requested_payload) <> 'object'
     OR NOT requested_payload ?& ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'requestId', 'orderId',
       'reconciledAt', 'auditLogId', 'outboxEventId', 'expectedFinal'
     ]
     OR requested_payload - ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'requestId', 'orderId',
       'reconciledAt', 'auditLogId', 'outboxEventId', 'expectedFinal'
     ] <> '{}'::jsonb
     OR jsonb_typeof(requested_payload -> 'expectedFinal') <> 'object' THEN
    RETURN QUERY
    SELECT
      'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
      NULL::bigint, NULL::bigint, NULL::bigint, NULL::bigint,
      NULL::text, NULL::timestamptz, NULL::integer, NULL::boolean;
    RETURN;
  END IF;

  requested_actor_user_id := requested_payload ->> 'actorUserId';
  requested_actor_role := requested_payload ->> 'actorRole';
  requested_security_version := (requested_payload ->> 'securityVersion')::bigint;
  requested_request_id := requested_payload ->> 'requestId';
  requested_order_id := requested_payload ->> 'orderId';
  requested_reconciled_at := (requested_payload ->> 'reconciledAt')::timestamptz;
  requested_audit_log_id := requested_payload ->> 'auditLogId';
  requested_outbox_event_id := requested_payload ->> 'outboxEventId';
  requested_expected_final := requested_payload -> 'expectedFinal';

  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id
  FOR SHARE;
  IF NOT FOUND
     OR stored_actor.status <> 'ACTIVE'
     OR stored_actor.role <> 'ADMIN'
     OR requested_actor_role <> 'ADMIN'
     OR stored_actor.security_version <> requested_security_version THEN
    RETURN QUERY
    SELECT
      'ACTOR_UNAUTHORIZED'::text, NULL::text, NULL::text, NULL::text,
      NULL::bigint, NULL::bigint, NULL::bigint, NULL::bigint,
      NULL::text, NULL::timestamptz, NULL::integer, NULL::boolean;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('order-fill:' || requested_order_id, 3301)
  );
  SELECT stored.*
  INTO stored_order
  FROM public.orders stored
  WHERE stored.order_id = requested_order_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY
    SELECT
      'ORDER_NOT_FOUND'::text, NULL::text, NULL::text, NULL::text,
      NULL::bigint, NULL::bigint, NULL::bigint, NULL::bigint,
      NULL::text, NULL::timestamptz, NULL::integer, NULL::boolean;
    RETURN;
  END IF;

  SELECT event.event_status
  INTO current_status
  FROM public.order_events event
  WHERE event.order_id = requested_order_id
    AND event.event_status IS NOT NULL
  ORDER BY event.event_seq DESC
  LIMIT 1;
  current_status := COALESCE(current_status, stored_order.status);
  current_filled := stored_order.filled_quantity;
  current_leaves := stored_order.leaves_quantity;
  current_unfilled_terminated := stored_order.unfilled_terminated_quantity;
  current_average := stored_order.average_fill_price_krw;
  IF stored_order.brokerage_mode = 'KIS_MOCK' THEN
    SELECT COALESCE(
      sum(
        applied_observation.fill_quantity::numeric
        * applied_observation.fill_price_krw::numeric
      ) FILTER (
        WHERE applied_receipt.outcome = 'APPLIED'
          AND applied_observation.exec_type IN ('PARTIAL_FILL', 'FILL')
      ),
      0
    )
    INTO current_notional
    FROM public.order_fill_application_receipts applied_receipt
    JOIN public.order_fill_observations applied_observation
      ON applied_observation.observation_id = applied_receipt.observation_id
    WHERE applied_receipt.order_id = requested_order_id;
  ELSE
    current_notional :=
      current_filled::numeric * COALESCE(current_average, 0)::numeric;
  END IF;
  SELECT COALESCE(max(event.event_seq), 0) + 1
  INTO next_event_seq
  FROM public.order_events event
  WHERE event.order_id = requested_order_id;

  IF stored_order.brokerage_mode = 'KIS_MOCK' THEN
    FOR observation IN
      SELECT source.*
      FROM public.order_fill_observations source
      WHERE source.order_id = requested_order_id
        AND source.completeness = 'COMPLETE'
        AND source.observed_at <= requested_reconciled_at
        AND source.received_at <= requested_reconciled_at
        AND NOT EXISTS (
          SELECT 1
          FROM public.order_fill_application_receipts receipt
          WHERE receipt.observation_id = source.observation_id
        )
      ORDER BY source.observed_at, source.observation_id
      LIMIT 200
    LOOP
      transition_outcome := NULL;
      transition_reason := NULL;
      transition_status := current_status;
      transition_event_type := NULL;
      transition_event_status := NULL;
      IF current_status IN ('FILLED', 'CANCELLED', 'REJECTED') THEN
        transition_outcome := 'INVALID';
        transition_reason := 'TERMINAL_STATE';
      ELSIF observation.cumulative_quantity < current_filled THEN
        transition_outcome := 'INVALID';
        transition_reason := 'NON_MONOTONIC_CUM_QTY';
      ELSIF observation.cumulative_quantity > stored_order.quantity THEN
        transition_outcome := 'INVALID';
        transition_reason := 'CUM_QTY_OVERFLOW';
      ELSIF current_status = 'CANCEL_REQUESTED'
            AND observation.exec_type = 'PARTIAL_FILL' THEN
        transition_outcome := 'INVALID';
        transition_reason := 'CANCEL_REQUESTED_PARTIAL_FILL';
      ELSIF observation.exec_type IN ('PARTIAL_FILL', 'FILL') THEN
        IF observation.cumulative_quantity = current_filled THEN
          transition_outcome := 'DUPLICATE';
        ELSE
          delta_quantity := observation.cumulative_quantity - current_filled;
          IF observation.fill_quantity <> delta_quantity THEN
            transition_outcome := 'INVALID';
            transition_reason := 'INVALID_QUANTITY';
          ELSIF observation.fill_price_krw IS NULL OR observation.fill_price_krw <= 0 THEN
            transition_outcome := 'INVALID';
            transition_reason := 'INVALID_FILL_PRICE';
          ELSIF observation.leaves_quantity <>
                stored_order.quantity - observation.cumulative_quantity
                OR (
                  observation.exec_type = 'PARTIAL_FILL'
                  AND observation.leaves_quantity = 0
                )
                OR (
                  observation.exec_type = 'FILL'
                  AND observation.leaves_quantity <> 0
                ) THEN
            transition_outcome := 'INVALID';
            transition_reason := 'INVALID_LEAVES_QUANTITY';
          ELSE
            current_notional :=
              current_notional
              + observation.fill_price_krw::numeric * delta_quantity::numeric;
            next_average :=
              trunc(
                current_notional / observation.cumulative_quantity::numeric
              )::bigint;
            current_filled := observation.cumulative_quantity;
            current_leaves := observation.leaves_quantity;
            current_unfilled_terminated := 0;
            current_average := next_average;
            transition_status :=
              CASE WHEN current_leaves = 0 THEN 'FILLED' ELSE 'PARTIALLY_FILLED' END;
            transition_outcome := 'APPLIED';
            transition_event_type :=
              CASE
                WHEN transition_status = 'FILLED' THEN 'MOCK_ORDER_FILLED'
                ELSE 'MOCK_ORDER_PARTIALLY_FILLED'
              END;
            transition_event_status := transition_status;
          END IF;
        END IF;
      ELSIF observation.exec_type IN ('CANCELLED', 'REJECTED') THEN
        IF observation.fill_quantity <> 0
           OR observation.fill_price_krw IS NOT NULL
           OR observation.cumulative_quantity <> current_filled
           OR observation.leaves_quantity <> 0 THEN
          transition_outcome := 'INVALID';
          transition_reason := 'INVALID_QUANTITY';
        ELSE
          current_leaves := 0;
          current_unfilled_terminated := stored_order.quantity - current_filled;
          transition_status := observation.exec_type;
          transition_outcome := 'APPLIED';
          transition_event_type :=
            CASE
              WHEN observation.exec_type = 'CANCELLED' THEN 'MOCK_ORDER_CANCELLED'
              ELSE 'MOCK_ORDER_REJECTED'
            END;
          transition_event_status := transition_status;
        END IF;
      END IF;

      INSERT INTO public.order_fill_application_receipts (
        receipt_id, observation_id, order_id, outcome, invalid_reason, applied_at
      )
      VALUES (
        'ofr_' || substr(
          encode(sha256(convert_to('receipt:' || observation.observation_id, 'UTF8')), 'hex'),
          1,
          32
        ),
        observation.observation_id,
        requested_order_id,
        transition_outcome,
        transition_reason,
        requested_reconciled_at
      );

      IF transition_outcome IN ('APPLIED', 'INVALID') THEN
        IF transition_outcome = 'INVALID' THEN
          transition_event_type := 'INVALID_TRANSITION';
          transition_event_status := NULL;
          invalid_count := invalid_count + 1;
        ELSE
          current_status := transition_status;
        END IF;
        transition_payload :=
          CASE
            WHEN transition_outcome = 'INVALID' THEN
              jsonb_build_object(
                'orderId', requested_order_id,
                'brokerageMode', 'KIS_MOCK',
                'execRefHash', observation.provider_exec_ref_hash,
                'observationId', observation.observation_id,
                'reason', transition_reason
              )
            ELSE
              jsonb_build_object(
                'orderId', requested_order_id,
                'brokerageMode', 'KIS_MOCK',
                'status', transition_event_status,
                'execRefHash', observation.provider_exec_ref_hash,
                'fillQuantity', observation.fill_quantity,
                'fillPriceKrw', observation.fill_price_krw,
                'filledAt', observation.observed_at::text
              )
          END;
        INSERT INTO public.order_events (
          order_event_id, order_id, event_type, event_status, payload_json,
          created_at, event_seq
        )
        VALUES (
          'oev_' || substr(
            encode(sha256(convert_to('fill-event:' || observation.observation_id, 'UTF8')), 'hex'),
            1,
            32
          ),
          requested_order_id,
          transition_event_type,
          transition_event_status,
          transition_payload,
          observation.observed_at,
          next_event_seq
        );
        next_event_seq := next_event_seq + 1;
        event_count := event_count + 1;
      END IF;
    END LOOP;
  END IF;

  IF stored_order.brokerage_mode = 'INTERNAL_PAPER' THEN
    SELECT
      count(*),
      COALESCE(sum((paper.payload_json ->> 'fillQuantity')::bigint), 0),
      CASE
        WHEN count(*) = 0 THEN NULL
        ELSE trunc(
          sum(
            (paper.payload_json ->> 'fillQuantity')::numeric
            * (paper.payload_json ->> 'fillPriceKrw')::numeric
          )
          / sum((paper.payload_json ->> 'fillQuantity')::numeric)
        )::bigint
      END
    INTO observation_count, observed_fill_quantity, recomputed_average
    FROM public.paper_order_events paper
    WHERE paper.order_id = requested_order_id;
    provider_final_average := recomputed_average;
  ELSE
    SELECT
      count(*),
      COALESCE(
        sum(aggregate_observation.fill_quantity)
          FILTER (WHERE aggregate_observation.exec_type IN ('PARTIAL_FILL', 'FILL')),
        0
      ),
      CASE
        WHEN COALESCE(
          sum(aggregate_observation.fill_quantity)
            FILTER (WHERE aggregate_observation.exec_type IN ('PARTIAL_FILL', 'FILL')),
          0
        ) = 0 THEN NULL
        ELSE trunc(
          sum(
            aggregate_observation.fill_quantity::numeric
            * aggregate_observation.fill_price_krw::numeric
          ) FILTER (WHERE aggregate_observation.exec_type IN ('PARTIAL_FILL', 'FILL'))
          / sum(aggregate_observation.fill_quantity::numeric)
            FILTER (WHERE aggregate_observation.exec_type IN ('PARTIAL_FILL', 'FILL'))
        )::bigint
      END
    INTO observation_count, observed_fill_quantity, recomputed_average
    FROM public.order_fill_observations aggregate_observation
    WHERE aggregate_observation.order_id = requested_order_id
      AND aggregate_observation.observed_at <= requested_reconciled_at
      AND aggregate_observation.received_at <= requested_reconciled_at;
    SELECT final_observation.average_fill_price_krw
    INTO provider_final_average
    FROM public.order_fill_observations final_observation
    WHERE final_observation.order_id = requested_order_id
      AND final_observation.exec_type IN ('PARTIAL_FILL', 'FILL')
      AND final_observation.observed_at <= requested_reconciled_at
      AND final_observation.received_at <= requested_reconciled_at
    ORDER BY
      final_observation.cumulative_quantity DESC,
      final_observation.observed_at DESC,
      final_observation.observation_id DESC
    LIMIT 1;
  END IF;

  conservation_matches :=
    current_filled + current_leaves + current_unfilled_terminated
      = stored_order.quantity;
  IF observation_count = 0 THEN
    final_reconciliation_status := 'NOT_APPLICABLE';
    final_reconciled_at := NULL;
  ELSIF observed_fill_quantity = current_filled
        AND conservation_matches
        AND recomputed_average IS NOT DISTINCT FROM current_average
        AND provider_final_average IS NOT DISTINCT FROM recomputed_average THEN
    final_reconciliation_status := 'MATCHED';
    final_reconciled_at := requested_reconciled_at;
  ELSE
    final_reconciliation_status := 'MISMATCH';
    final_reconciled_at := requested_reconciled_at;
  END IF;

  UPDATE public.orders stored
  SET status = current_status,
      filled_quantity = current_filled,
      leaves_quantity = current_leaves,
      unfilled_terminated_quantity = current_unfilled_terminated,
      average_fill_price_krw = current_average,
      reconciliation_status = final_reconciliation_status,
      reconciled_at = final_reconciled_at,
      updated_at = GREATEST(stored.updated_at, requested_reconciled_at)
  WHERE stored.order_id = requested_order_id;

  SELECT EXISTS (
    SELECT 1
    FROM public.order_fill_observations remaining_observation
    WHERE remaining_observation.order_id = requested_order_id
      AND remaining_observation.completeness = 'COMPLETE'
      AND remaining_observation.observed_at <= requested_reconciled_at
      AND remaining_observation.received_at <= requested_reconciled_at
      AND NOT EXISTS (
        SELECT 1
        FROM public.order_fill_application_receipts receipt
        WHERE receipt.observation_id = remaining_observation.observation_id
      )
  )
  INTO remaining;

  actual_final :=
    jsonb_build_object(
      'status', current_status,
      'filledQuantity', current_filled,
      'leavesQuantity', current_leaves,
      'unfilledTerminatedQuantity', current_unfilled_terminated,
      'fillNotionalKrw', current_notional,
      'averageFillPriceKrw', current_average,
      'reconciliationStatus', final_reconciliation_status,
      'appliedEventCount', event_count,
      'hasMore', remaining
    );
  IF actual_final <> requested_expected_final THEN
    RAISE EXCEPTION 'S3.3 reconciliation logic divergence'
      USING ERRCODE = 'P0001';
  END IF;

  reference_payload :=
    jsonb_build_object(
      'orderId', requested_order_id,
      'brokerageMode', stored_order.brokerage_mode,
      'reconciliationStatus', final_reconciliation_status,
      'appliedEventCount', event_count,
      'invalidEventCount', invalid_count,
      'hasMore', remaining,
      'checkedAt', final_reconciled_at
    );
  INSERT INTO public.audit_logs (
    audit_log_id, user_id, actor_role, action, target_type, target_id,
    request_id, payload_json, created_at
  )
  VALUES (
    requested_audit_log_id, requested_actor_user_id, requested_actor_role,
    'ORDER_RECONCILED', 'ORDER_RECONCILIATION', requested_order_id,
    requested_request_id, reference_payload, requested_reconciled_at
  );
  INSERT INTO public.event_outbox (
    event_id, event_type, aggregate_type, aggregate_id, partition_key,
    payload_json, schema_version, status, retry_count, created_at, updated_at
  )
  VALUES (
    requested_outbox_event_id, 'brokerage.order-reconciled.v1',
    'ORDER', requested_order_id, requested_order_id, reference_payload,
    '1.0.0', 'PENDING', 0, requested_reconciled_at, requested_reconciled_at
  );

  RETURN QUERY
  SELECT
    'APPLIED'::text,
    requested_order_id,
    stored_order.brokerage_mode,
    current_status,
    current_filled,
    current_leaves,
    current_unfilled_terminated,
    current_average,
    final_reconciliation_status,
    final_reconciled_at,
    event_count,
    remaining;
END
$$;


ALTER FUNCTION public.apply_stored_order_fills(requested_payload jsonb, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.assert_brokerage_database_capability(requested_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF requested_token IS NULL
     OR octet_length(requested_token) < 32
     OR NOT EXISTS (
       SELECT 1
       FROM public.brokerage_db_capability_keys capability
       WHERE capability.capability_id = 'S3_1_RUNTIME'
         AND capability.token_sha256 =
           encode(sha256(convert_to(requested_token, 'UTF8')), 'hex')
     ) THEN
    RAISE EXCEPTION 'S3.1 brokerage database capability denied'
      USING ERRCODE = '42501';
  END IF;
END
$$;


ALTER FUNCTION public.assert_brokerage_database_capability(requested_token text) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_vertex_evidence_manifest_is_valid(p_evidence_manifest jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  evidence_item jsonb;
  expected_ordinal integer := 1;
  seen_chunk_ids text[] := ARRAY[]::text[];
BEGIN
  IF jsonb_typeof(p_evidence_manifest) <> 'array'
     OR jsonb_array_length(p_evidence_manifest) NOT BETWEEN 1 AND 5
     OR octet_length(p_evidence_manifest::text) > 2048 THEN
    RETURN false;
  END IF;

  FOR evidence_item IN SELECT value FROM jsonb_array_elements(p_evidence_manifest)
  LOOP
    IF jsonb_typeof(evidence_item) <> 'object'
       OR NOT (evidence_item ?& ARRAY['ordinal', 'citationId', 'chunkRevisionId', 'canonicalTextSha256'])
       OR EXISTS (
         SELECT 1
         FROM jsonb_object_keys(evidence_item) AS key_name
         WHERE key_name NOT IN ('ordinal', 'citationId', 'chunkRevisionId', 'canonicalTextSha256')
       )
       OR jsonb_typeof(evidence_item -> 'ordinal') <> 'number'
       OR evidence_item ->> 'ordinal' <> expected_ordinal::text
       OR jsonb_typeof(evidence_item -> 'citationId') <> 'string'
       OR evidence_item ->> 'citationId' <> ('cit_' || expected_ordinal::text)
       OR jsonb_typeof(evidence_item -> 'chunkRevisionId') <> 'string'
       OR evidence_item ->> 'chunkRevisionId' !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR jsonb_typeof(evidence_item -> 'canonicalTextSha256') <> 'string'
       OR evidence_item ->> 'canonicalTextSha256' !~ '^[0-9a-f]{64}$'
       OR evidence_item ->> 'chunkRevisionId' = ANY(seen_chunk_ids) THEN
      RETURN false;
    END IF;
    seen_chunk_ids := array_append(seen_chunk_ids, evidence_item ->> 'chunkRevisionId');
    expected_ordinal := expected_ordinal + 1;
  END LOOP;
  RETURN true;
END
$_$;


ALTER FUNCTION public.rag_v2_immutable_vertex_evidence_manifest_is_valid(p_evidence_manifest jsonb) OWNER TO flyway;

SET default_tablespace = '';

SET default_table_access_method = heap;


CREATE TABLE public.rag_v2_immutable_vertex_usage_reservations (
    usage_event_id text NOT NULL,
    owner_user_id text NOT NULL,
    request_id text NOT NULL,
    question_fingerprint_hmac text NOT NULL,
    packet_sha256 text NOT NULL,
    nonce_sha256 text NOT NULL,
    processor_set_sha256 text NOT NULL,
    provider text DEFAULT 'VERTEX_AI'::text NOT NULL,
    operation text DEFAULT 'GENERATE_CONTENT'::text NOT NULL,
    model_id text DEFAULT 'gemini-3.5-flash'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    input_token_cap integer NOT NULL,
    output_token_cap integer NOT NULL,
    input_byte_cap integer NOT NULL,
    cost_cap_microusd bigint NOT NULL,
    input_microusd_per_token bigint NOT NULL,
    output_microusd_per_token bigint NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    scope_claim_id text NOT NULL,
    consent_event_id text NOT NULL,
    policy_sha256 text NOT NULL,
    answer_mode text NOT NULL,
    token_physical_call_cap integer DEFAULT 1 NOT NULL,
    generate_content_physical_call_cap integer DEFAULT 1 NOT NULL,
    evidence_manifest jsonb NOT NULL,
    authentication_mode text NOT NULL,
    CONSTRAINT rag_v2_immutable_vertex_usage_reservation_cap_check CHECK ((((input_token_cap >= 1) AND (input_token_cap <= 120000)) AND ((output_token_cap >= 1) AND (output_token_cap <= 32768)) AND ((input_byte_cap >= 1) AND (input_byte_cap <= 60000)) AND ((cost_cap_microusd >= 1) AND (cost_cap_microusd <= 1000000000)) AND ((input_microusd_per_token >= 1) AND (input_microusd_per_token <= 1000000)) AND ((output_microusd_per_token >= 1) AND (output_microusd_per_token <= 1000000)) AND ((((input_token_cap)::bigint * input_microusd_per_token) + ((output_token_cap)::bigint * output_microusd_per_token)) <= cost_cap_microusd))),
    CONSTRAINT rag_v2_immutable_vertex_usage_reservation_evidence_manifest_che CHECK (public.rag_v2_immutable_vertex_evidence_manifest_is_valid(evidence_manifest)),
    CONSTRAINT rag_v2_immutable_vertex_usage_reservation_hash_check CHECK (((question_fingerprint_hmac ~ '^[0-9a-f]{64}$'::text) AND (packet_sha256 ~ '^[0-9a-f]{64}$'::text) AND (nonce_sha256 ~ '^[0-9a-f]{64}$'::text) AND (processor_set_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT rag_v2_immutable_vertex_usage_reservation_id_check CHECK ((usage_event_id ~ '^rgr_vgu_[0-9a-f]{32}$'::text)),
    CONSTRAINT rag_v2_immutable_vertex_usage_reservation_owner_check CHECK ((owner_user_id ~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'::text)),
    CONSTRAINT rag_v2_immutable_vertex_usage_reservation_provider_check CHECK (((provider = 'VERTEX_AI'::text) AND (operation = 'GENERATE_CONTENT'::text) AND (model_id = 'gemini-3.5-flash'::text))),
    CONSTRAINT rag_v2_immutable_vertex_usage_reservation_request_check CHECK ((request_id ~ '^req_[A-Za-z0-9_-]{12,96}$'::text)),
    CONSTRAINT rag_v2_immutable_vertex_usage_reservation_service_account_bindi CHECK (((authentication_mode = 'SERVICE_ACCOUNT_OAUTH'::text) AND (token_physical_call_cap = 1) AND (generate_content_physical_call_cap = 1)))
);

ALTER TABLE ONLY public.rag_v2_immutable_vertex_usage_reservations FORCE ROW LEVEL SECURITY;


ALTER TABLE public.rag_v2_immutable_vertex_usage_reservations OWNER TO flyway;


CREATE FUNCTION public.assert_rag_v2_immutable_vertex_reservation_is_current(p_reservation public.rag_v2_immutable_vertex_usage_reservations) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  effective_consent public.rag_v2_immutable_consent_events%ROWTYPE;
  scope_row public.rag_v2_retrieval_scope_claims%ROWTYPE;
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  owner_bundle public.rag_v2_immutable_bundles%ROWTYPE;
  evidence_item jsonb;
  evidence_row record;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_reservation.owner_user_id
     OR p_reservation.expires_at <= statement_timestamp()
     OR NOT public.rag_v2_immutable_vertex_evidence_manifest_is_valid(p_reservation.evidence_manifest) THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex reservation is not current'
      USING ERRCODE = '55000';
  END IF;

  -- public/owner activation과 owner consent writer가 동일 lock을 쓰므로 claim commit이 새 outbound authorization point다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-bundle-activation', 0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-consent|' || p_reservation.owner_user_id, 0)
  );
  PERFORM set_config('app.actor_user_id', p_reservation.owner_user_id, true);
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);

  SELECT * INTO effective_consent
  FROM public.rag_v2_immutable_consent_events AS event
  WHERE event.owner_user_id = p_reservation.owner_user_id
    AND event.public_consent_event_id IS NOT NULL
    AND event.policy_digest IS NOT NULL
    AND event.processor_set_digest IS NOT NULL
  ORDER BY event.created_at DESC, event.consent_event_id DESC
  LIMIT 1;
  IF NOT FOUND
     OR effective_consent.action <> 'GRANT'
     OR effective_consent.public_consent_event_id IS DISTINCT FROM p_reservation.consent_event_id
     OR effective_consent.policy_digest IS DISTINCT FROM p_reservation.policy_sha256
     OR effective_consent.processor_set_digest IS DISTINCT FROM p_reservation.processor_set_sha256 THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex consent is not currently granted'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO scope_row
  FROM public.rag_v2_retrieval_scope_claims AS scope
  WHERE scope.scope_claim_id = p_reservation.scope_claim_id
    AND scope.owner_user_id = p_reservation.owner_user_id
    AND scope.session_id = p_reservation.request_id
    AND scope.expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex retrieval scope is unavailable'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers AS pointer
  WHERE pointer.state_id = 'default'
    AND pointer.state = 'ACTIVE'
    AND pointer.pointer_version = scope_row.public_pointer_version
    AND pointer.exact30_generation_id = scope_row.exact30_generation_id
    AND pointer.oa112_generation_id = scope_row.oa112_generation_id
    AND pointer.embedding_profile_id = scope_row.embedding_profile_id;
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_component_generations AS exact_generation
       JOIN public.rag_v2_immutable_component_generations AS oa_generation
         ON oa_generation.component_generation_id = scope_row.oa112_generation_id
        AND oa_generation.component_scope = 'OA112'
        AND oa_generation.owner_user_id IS NULL
        AND oa_generation.embedding_profile_id = scope_row.embedding_profile_id
        AND oa_generation.state = 'ACTIVE'
        AND oa_generation.evaluation_status = 'PASSED'
       WHERE exact_generation.component_generation_id = scope_row.exact30_generation_id
         AND exact_generation.component_scope = 'EXACT30'
         AND exact_generation.owner_user_id IS NULL
         AND exact_generation.embedding_profile_id = scope_row.embedding_profile_id
         AND exact_generation.state = 'ACTIVE'
         AND exact_generation.evaluation_status = 'PASSED'
     ) THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex public retrieval scope changed'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO owner_pointer
  FROM public.rag_v2_immutable_owner_bundle_pointers AS pointer
  WHERE pointer.owner_user_id = p_reservation.owner_user_id;
  IF scope_row.owner_private_generation_id IS NULL THEN
    IF NOT public.rag_v2_immutable_empty_owner_scope_is_current(
      p_reservation.owner_user_id,
      scope_row.owner_pointer_version,
      scope_row.exact30_generation_id,
      scope_row.oa112_generation_id,
      scope_row.embedding_profile_id
    ) THEN
      RAISE EXCEPTION 'immutable Pre-S5 Vertex owner retrieval scope changed'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    IF NOT FOUND
       OR owner_pointer.state <> 'READY'
       OR owner_pointer.active_bundle_id IS DISTINCT FROM scope_row.owner_bundle_id
       OR owner_pointer.bundle_version <> scope_row.owner_pointer_version THEN
      RAISE EXCEPTION 'immutable Pre-S5 Vertex owner bundle scope changed'
        USING ERRCODE = '55000';
    END IF;
    SELECT * INTO owner_bundle
    FROM public.rag_v2_immutable_bundles AS bundle
    WHERE bundle.bundle_id = scope_row.owner_bundle_id
      AND bundle.owner_user_id = p_reservation.owner_user_id
      AND bundle.state = 'ACTIVE'
      AND bundle.evaluation_status = 'PASSED'
      AND bundle.owner_private_generation_id = scope_row.owner_private_generation_id
      AND bundle.exact30_generation_id = scope_row.exact30_generation_id
      AND bundle.oa112_generation_id = scope_row.oa112_generation_id
      AND bundle.embedding_profile_id = scope_row.embedding_profile_id;
    IF NOT FOUND
       OR NOT EXISTS (
         SELECT 1
         FROM public.rag_v2_immutable_component_generations AS generation
         WHERE generation.component_generation_id = scope_row.owner_private_generation_id
           AND generation.component_scope = 'OWNER_PRIVATE'
           AND generation.owner_user_id = p_reservation.owner_user_id
           AND generation.embedding_profile_id = scope_row.embedding_profile_id
           AND generation.state = 'ACTIVE'
           AND generation.evaluation_status = 'PASSED'
       ) THEN
      RAISE EXCEPTION 'immutable Pre-S5 Vertex owner component scope changed'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  FOR evidence_item IN SELECT value FROM jsonb_array_elements(p_reservation.evidence_manifest)
  LOOP
    SELECT
      source.source_scope,
      source.owner_user_id,
      membership.component_generation_id,
      chunk.canonical_text_sha256
    INTO evidence_row
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_chunks AS chunk
      ON chunk.chunk_id = membership.chunk_id
     AND chunk.source_revision_id = membership.source_revision_id
     AND chunk.source_scope = membership.component_scope
     AND chunk.owner_partition_key = membership.owner_partition_key
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
     AND source.source_scope = membership.component_scope
     AND source.owner_partition_key = membership.owner_partition_key
    WHERE membership.chunk_id = evidence_item ->> 'chunkRevisionId'
      AND chunk.canonical_text_sha256 = evidence_item ->> 'canonicalTextSha256'
      AND source.retrieval_topics && scope_row.allowed_topics
      AND source.external_processing_eligible
      AND source.external_embedding_allowed
      AND source.external_generation_allowed
      AND EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_generation_embeddings AS embedding
        WHERE embedding.component_generation_id = membership.component_generation_id
          AND embedding.chunk_id = membership.chunk_id
          AND embedding.component_scope = membership.component_scope
          AND embedding.owner_partition_key = membership.owner_partition_key
          AND embedding.embedding_profile_id = scope_row.embedding_profile_id
      )
      AND (
        (source.source_scope = 'EXACT30'
          AND source.owner_user_id IS NULL
          AND membership.component_generation_id = scope_row.exact30_generation_id)
        OR (source.source_scope = 'OA112'
          AND source.owner_user_id IS NULL
          AND membership.component_generation_id = scope_row.oa112_generation_id)
        OR (source.source_scope = 'OWNER_PRIVATE'
          AND source.owner_user_id = p_reservation.owner_user_id
          AND scope_row.owner_private_generation_id IS NOT NULL
          AND membership.component_generation_id = scope_row.owner_private_generation_id)
      );
    IF NOT FOUND THEN
      RAISE EXCEPTION 'immutable Pre-S5 Vertex evidence is no longer externally eligible'
        USING ERRCODE = '55000';
    END IF;
  END LOOP;
END
$$;


ALTER FUNCTION public.assert_rag_v2_immutable_vertex_reservation_is_current(p_reservation public.rag_v2_immutable_vertex_usage_reservations) OWNER TO flyway;


CREATE FUNCTION public.authorize_async_replay(p_packet_hash text, p_actor_user_id text, p_security_version bigint, p_replay_batch_id text, p_target_kind text, p_target_ids text[], p_expected_count integer, p_reason_code text, p_execute_authorized boolean, p_issued_at timestamp with time zone, p_expires_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF session_user <> 'decision_replay_authorizer' OR p_packet_hash !~ '^sha256:[0-9a-f]{64}$'
     OR p_replay_batch_id !~ '^replay_[0-9a-f]{32}$' OR p_target_kind NOT IN ('EVENT','JOB')
     OR cardinality(p_target_ids) NOT BETWEEN 1 AND 100
     OR cardinality(p_target_ids)<>(SELECT count(DISTINCT value) FROM unnest(p_target_ids) value)
     OR p_expected_count<>cardinality(p_target_ids) OR p_reason_code !~ '^[A-Z][A-Z0-9_]{2,63}$'
     OR p_issued_at>statement_timestamp()+interval '5 seconds'
     OR p_expires_at<=statement_timestamp() OR p_expires_at>p_issued_at+interval '5 minutes'
     OR NOT EXISTS (SELECT 1 FROM public.users actor WHERE actor.user_id=p_actor_user_id
       AND actor.status='ACTIVE' AND actor.role='ADMIN' AND actor.security_version=p_security_version) THEN
    RAISE EXCEPTION 'invalid replay authorization' USING ERRCODE='42501';
  END IF;
  INSERT INTO public.async_replay_authorization(packet_hash,actor_user_id,actor_security_version,replay_batch_id,
    target_kind,target_ids,expected_count,reason_code,execute_authorized,issued_at,expires_at)
  VALUES (p_packet_hash,p_actor_user_id,p_security_version,p_replay_batch_id,p_target_kind,p_target_ids,
    p_expected_count,p_reason_code,p_execute_authorized,p_issued_at,p_expires_at)
  ON CONFLICT DO NOTHING;
  IF FOUND THEN RETURN true; END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.async_replay_authorization authz
    WHERE authz.packet_hash=p_packet_hash AND authz.actor_user_id=p_actor_user_id
      AND authz.actor_security_version=p_security_version AND authz.replay_batch_id=p_replay_batch_id
      AND authz.target_kind=p_target_kind AND authz.target_ids=p_target_ids
      AND authz.expected_count=p_expected_count AND authz.reason_code=p_reason_code
      AND authz.execute_authorized=p_execute_authorized AND authz.issued_at=p_issued_at
      AND authz.expires_at=p_expires_at AND authz.consumed_at IS NULL
      AND authz.expires_at>statement_timestamp()
  );
END
$_$;


ALTER FUNCTION public.authorize_async_replay(p_packet_hash text, p_actor_user_id text, p_security_version bigint, p_replay_batch_id text, p_target_kind text, p_target_ids text[], p_expected_count integer, p_reason_code text, p_execute_authorized boolean, p_issued_at timestamp with time zone, p_expires_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.authorize_s4_9_runtime_voyage_query(p_owner_user_id text, p_scope_claim_id text, p_question_sha256 text) RETURNS TABLE(authorization_id text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  claim_row public.rag_v2_retrieval_scope_claims%ROWTYPE;
  consent_row public.rag_v2_immutable_consent_events%ROWTYPE;
  generated_authorization_id text;
  authorization_expires_at timestamptz;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_scope_claim_id !~ '^rvs_[0-9a-f]{32}$'
     OR p_question_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'S4.9 Voyage query authorization arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- FORCE RLS owner policy를 definer 내부에서도 같은 authenticated actor에 고정한다.
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  SELECT * INTO claim_row
  FROM public.rag_v2_retrieval_scope_claims AS claim
  WHERE claim.scope_claim_id = p_scope_claim_id
    AND claim.owner_user_id = p_owner_user_id
    AND claim.embedding_profile_id = 'voyage_context_4_1024_v1'
    AND claim.expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'S4.9 Voyage query scope is unavailable' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO consent_row
  FROM public.rag_v2_immutable_consent_events AS consent
  WHERE consent.owner_user_id = p_owner_user_id
    AND consent.public_consent_event_id IS NOT NULL
    AND consent.policy_digest IS NOT NULL
    AND consent.processor_set_digest IS NOT NULL
  ORDER BY consent.created_at DESC, consent.consent_event_id DESC
  LIMIT 1;
  IF NOT FOUND OR consent_row.action <> 'GRANT' THEN
    RAISE EXCEPTION 'S4.9 Voyage query requires effective consent' USING ERRCODE = '55000';
  END IF;

  generated_authorization_id :=
    's49_vqa_' || substr(
      encode(
        digest(
          gen_random_bytes(32) || convert_to(
            concat_ws(E'\n', p_owner_user_id, p_scope_claim_id, p_question_sha256, statement_timestamp()::text),
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ),
      1,
      32
    );
  authorization_expires_at := least(claim_row.expires_at, statement_timestamp() + interval '2 minutes');

  INSERT INTO public.s4_9_voyage_query_authorizations (
    authorization_id, owner_user_id, scope_claim_id, question_sha256,
    consent_event_id, policy_digest, processor_set_digest, expires_at
  ) VALUES (
    generated_authorization_id, p_owner_user_id, p_scope_claim_id, p_question_sha256,
    consent_row.public_consent_event_id, consent_row.policy_digest,
    consent_row.processor_set_digest, authorization_expires_at
  );

  RETURN QUERY SELECT generated_authorization_id, authorization_expires_at;
END
$_$;


ALTER FUNCTION public.authorize_s4_9_runtime_voyage_query(p_owner_user_id text, p_scope_claim_id text, p_question_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.authorized_rag_v2_retrieval_rows(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[]) RETURNS TABLE(canonical_content text, canonical_content_sha256 text, canonical_https_url text, chunk_id text, document_id text, embedding_profile_id text, external_processing_eligible boolean, generation_id text, heading_path text[], locator jsonb, candidate_owner_user_id text, policy_version bigint, sanitized_display_name text, scope_claim_id text, session_id text, source_id text, source_revision_id text, source_scope text, citation_title text, retrieval_topics text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR NOT public.rag_v2_immutable_retrieval_topics_are_valid(p_topics) THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval row arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH scope AS (
    SELECT *
    FROM public.resolve_rag_v2_retrieval_scope_v2(p_scope_claim_id, p_owner_user_id, p_session_id)
  )
  SELECT
    chunk.canonical_text,
    chunk.canonical_text_sha256,
    source.canonical_https_url,
    chunk.chunk_id,
    source.document_id,
    CASE
      WHEN source.source_scope = 'OWNER_PRIVATE' THEN scope.owner_embedding_profile_id
      ELSE scope.embedding_profile_id
    END,
    source.external_processing_eligible,
    membership.component_generation_id,
    chunk.heading_path,
    chunk.locator,
    source.owner_user_id,
    scope.policy_version,
    source.sanitized_display_name,
    scope.scope_claim_id,
    scope.session_id,
    source.source_id,
    source.source_revision_id,
    source.source_scope,
    source.citation_title,
    source.retrieval_topics
  FROM scope
  JOIN public.rag_v2_immutable_generation_memberships AS membership
    ON membership.component_generation_id = ANY(
      ARRAY[
        scope.exact30_generation_id,
        scope.oa112_generation_id,
        scope.owner_private_generation_id
      ]::text[]
    )
  JOIN public.rag_v2_immutable_chunks AS chunk
    ON chunk.chunk_id = membership.chunk_id
   AND chunk.source_revision_id = membership.source_revision_id
   AND chunk.source_scope = membership.component_scope
   AND chunk.owner_partition_key = membership.owner_partition_key
  JOIN public.rag_v2_immutable_source_revisions AS source
    ON source.source_revision_id = membership.source_revision_id
   AND source.source_scope = membership.component_scope
   AND source.owner_partition_key = membership.owner_partition_key
  JOIN public.rag_v2_immutable_generation_embeddings AS embedding
    ON embedding.component_generation_id = membership.component_generation_id
   AND embedding.chunk_id = membership.chunk_id
   AND embedding.component_scope = membership.component_scope
   AND embedding.owner_partition_key = membership.owner_partition_key
   AND embedding.embedding_profile_id = CASE
     WHEN membership.component_scope = 'OWNER_PRIVATE' THEN scope.owner_embedding_profile_id
     ELSE scope.embedding_profile_id
   END
  WHERE p_topics <@ scope.allowed_topics
    AND source.retrieval_topics && p_topics
    AND (
      (
        source.source_scope IN ('EXACT30', 'OA112')
        AND source.owner_user_id IS NULL
        AND source.citation_title IS NOT NULL
        AND source.sanitized_display_name IS NULL
        AND public.rag_v2_immutable_public_https_url_is_valid(source.canonical_https_url)
      )
      OR (
        source.source_scope = 'OWNER_PRIVATE'
        AND source.owner_user_id = scope.owner_user_id
        AND source.citation_title IS NULL
        AND source.sanitized_display_name IS NOT NULL
        AND source.canonical_https_url IS NULL
      )
    )
    AND (
      source.source_scope <> 'OA112'
      OR EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_oa_source_cards AS card
        WHERE card.source_revision_id = source.source_revision_id
          AND card.source_id = source.source_id
          AND card.active_oa112_eligible
          AND card.canonical_https_url = source.canonical_https_url
      )
    );
END;
$$;


ALTER FUNCTION public.authorized_rag_v2_retrieval_rows(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[]) OWNER TO flyway;


CREATE FUNCTION public.bind_claimed_outbox_payload_hash(p_event_id text, p_claim_token uuid, p_payload_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE changed integer;
BEGIN
  IF session_user <> 'decision_app' THEN RAISE EXCEPTION 'outbox hash bind role denied' USING ERRCODE='42501'; END IF;
  IF p_payload_hash !~ '^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'invalid outbox payload hash' USING ERRCODE='22023'; END IF;
  UPDATE public.event_outbox SET transport_payload_hash=p_payload_hash,updated_at=statement_timestamp()
  WHERE event_id=p_event_id AND claim_token=p_claim_token AND status IN ('PENDING','FAILED')
    AND lease_expires_at>statement_timestamp()
    AND (transport_payload_hash IS NULL OR transport_payload_hash=p_payload_hash);
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN changed=1;
END
$_$;


ALTER FUNCTION public.bind_claimed_outbox_payload_hash(p_event_id text, p_claim_token uuid, p_payload_hash text) OWNER TO flyway;


CREATE FUNCTION public.canonicalize_rag_v2_immutable_retrieval_citations(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_citations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  claim_row public.rag_v2_retrieval_scope_claims%ROWTYPE;
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  owner_bundle public.rag_v2_immutable_bundles%ROWTYPE;
  citation_item jsonb;
  candidate record;
  expected_ordinal integer := 1;
  seen_chunk_ids text[] := ARRAY[]::text[];
  output jsonb := '[]'::jsonb;
  requested_generation_id text;
  requested_kind text;
  requested_chunk_id text;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$'
     OR p_scope_claim_id !~ '^rvs_[0-9a-f]{32}$'
     OR jsonb_typeof(p_citations) <> 'array'
     OR jsonb_array_length(p_citations) NOT BETWEEN 1 AND 5
     OR octet_length(p_citations::text) > 16384 THEN
    RAISE EXCEPTION 'immutable RAG v2 citation recheck arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);
  SELECT * INTO claim_row
  FROM public.rag_v2_retrieval_scope_claims AS scope
  WHERE scope.scope_claim_id = p_scope_claim_id
    AND scope.owner_user_id = p_owner_user_id
    AND scope.session_id = p_session_id
    AND scope.expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope is absent or expired'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers AS pointer
  WHERE pointer.state_id = 'default'
    AND pointer.state = 'ACTIVE'
    AND pointer.pointer_version = claim_row.public_pointer_version
    AND pointer.exact30_generation_id = claim_row.exact30_generation_id
    AND pointer.oa112_generation_id = claim_row.oa112_generation_id
    AND pointer.embedding_profile_id = claim_row.embedding_profile_id;
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_component_generations AS exact_generation
       JOIN public.rag_v2_immutable_component_generations AS oa_generation
         ON oa_generation.component_generation_id = claim_row.oa112_generation_id
        AND oa_generation.component_scope = 'OA112'
        AND oa_generation.owner_user_id IS NULL
        AND oa_generation.embedding_profile_id = claim_row.embedding_profile_id
        AND oa_generation.state = 'ACTIVE'
        AND oa_generation.evaluation_status = 'PASSED'
       WHERE exact_generation.component_generation_id = claim_row.exact30_generation_id
         AND exact_generation.component_scope = 'EXACT30'
         AND exact_generation.owner_user_id IS NULL
         AND exact_generation.embedding_profile_id = claim_row.embedding_profile_id
         AND exact_generation.state = 'ACTIVE'
         AND exact_generation.evaluation_status = 'PASSED'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public retrieval scope changed'
      USING ERRCODE = '55000';
  END IF;

  IF NOT claim_row.owner_scope_authorized THEN
    IF claim_row.owner_private_generation_id IS NOT NULL
       OR claim_row.owner_bundle_id IS NOT NULL
       OR claim_row.owner_embedding_profile_id IS NOT NULL
       OR claim_row.owner_pointer_version <> 0 THEN
      RAISE EXCEPTION 'S4.9 MCP public retrieval scope is invalid'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    SELECT * INTO owner_pointer
    FROM public.rag_v2_immutable_owner_bundle_pointers AS pointer
    WHERE pointer.owner_user_id = p_owner_user_id;
    IF claim_row.owner_private_generation_id IS NULL THEN
      IF NOT public.rag_v2_immutable_empty_owner_scope_is_current(
        p_owner_user_id,
        claim_row.owner_pointer_version,
        claim_row.exact30_generation_id,
        claim_row.oa112_generation_id,
        claim_row.embedding_profile_id
      ) THEN
        RAISE EXCEPTION 'immutable RAG v2 owner retrieval scope changed'
          USING ERRCODE = '55000';
      END IF;
    ELSE
    IF NOT FOUND
       OR owner_pointer.state <> 'READY'
       OR owner_pointer.active_bundle_id IS DISTINCT FROM claim_row.owner_bundle_id
       OR owner_pointer.bundle_version <> claim_row.owner_pointer_version THEN
      RAISE EXCEPTION 'immutable RAG v2 owner bundle scope changed'
        USING ERRCODE = '55000';
    END IF;
    SELECT * INTO owner_bundle
    FROM public.rag_v2_immutable_bundles AS bundle
    WHERE bundle.bundle_id = claim_row.owner_bundle_id
      AND bundle.owner_user_id = p_owner_user_id
      AND bundle.state = 'ACTIVE'
      AND bundle.evaluation_status = 'PASSED'
      AND bundle.owner_private_generation_id = claim_row.owner_private_generation_id
      AND bundle.exact30_generation_id = claim_row.exact30_generation_id
      AND bundle.oa112_generation_id = claim_row.oa112_generation_id
      AND bundle.embedding_profile_id = claim_row.embedding_profile_id;
    IF NOT FOUND
       OR NOT EXISTS (
         SELECT 1
         FROM public.rag_v2_immutable_component_generations AS generation
         WHERE generation.component_generation_id = claim_row.owner_private_generation_id
           AND generation.component_scope = 'OWNER_PRIVATE'
           AND generation.owner_user_id = p_owner_user_id
           AND generation.embedding_profile_id = claim_row.owner_embedding_profile_id
           AND generation.state = 'ACTIVE'
           AND generation.evaluation_status = 'PASSED'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 owner component scope changed'
        USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;

  FOR citation_item IN SELECT value FROM jsonb_array_elements(p_citations)
  LOOP
    IF jsonb_typeof(citation_item) <> 'object'
       OR NOT (citation_item ?& ARRAY[
         'ordinal', 'citationId', 'sourceId', 'sourceRevisionId',
         'chunkRevisionId', 'generationId', 'citationKind'
       ])
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(citation_item) AS key_name
         WHERE key_name NOT IN (
           'ordinal', 'citationId', 'sourceId', 'sourceRevisionId',
           'chunkRevisionId', 'generationId', 'citationKind'
         )
       )
       OR jsonb_typeof(citation_item -> 'ordinal') <> 'number'
       OR citation_item ->> 'ordinal' <> expected_ordinal::text
       OR jsonb_typeof(citation_item -> 'citationId') <> 'string'
       OR citation_item ->> 'citationId' <> ('cit_' || expected_ordinal::text)
       OR jsonb_typeof(citation_item -> 'sourceId') <> 'string'
       OR citation_item ->> 'sourceId' !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
       OR jsonb_typeof(citation_item -> 'sourceRevisionId') <> 'string'
       OR citation_item ->> 'sourceRevisionId' !~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'
       OR jsonb_typeof(citation_item -> 'chunkRevisionId') <> 'string'
       OR citation_item ->> 'chunkRevisionId' !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR jsonb_typeof(citation_item -> 'generationId') <> 'string'
       OR citation_item ->> 'generationId' !~ '^rgr_[0-9a-f]{32}$'
       OR jsonb_typeof(citation_item -> 'citationKind') <> 'string'
       OR citation_item ->> 'citationKind' NOT IN ('PUBLIC_WEB', 'LOCAL_DOCUMENT') THEN
      RAISE EXCEPTION 'immutable RAG v2 citation receipt is invalid'
        USING ERRCODE = '22023';
    END IF;

    requested_generation_id := citation_item ->> 'generationId';
    requested_kind := citation_item ->> 'citationKind';
    requested_chunk_id := citation_item ->> 'chunkRevisionId';
    IF requested_chunk_id = ANY(seen_chunk_ids) THEN
      RAISE EXCEPTION 'immutable RAG v2 citation chunk is duplicated'
        USING ERRCODE = '22023';
    END IF;
    seen_chunk_ids := array_append(seen_chunk_ids, requested_chunk_id);

    SELECT
      source.source_id,
      source.source_revision_id,
      source.source_scope,
      source.owner_user_id,
      source.document_id,
      source.sanitized_display_name,
      source.citation_title,
      source.canonical_https_url,
      source.retrieval_topics,
      chunk.chunk_id,
      chunk.locator,
      membership.component_generation_id
    INTO candidate
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_chunks AS chunk
      ON chunk.chunk_id = membership.chunk_id
     AND chunk.source_revision_id = membership.source_revision_id
     AND chunk.source_scope = membership.component_scope
     AND chunk.owner_partition_key = membership.owner_partition_key
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
     AND source.source_scope = membership.component_scope
     AND source.owner_partition_key = membership.owner_partition_key
    WHERE membership.component_generation_id = requested_generation_id
      AND membership.chunk_id = requested_chunk_id
      AND membership.source_revision_id = citation_item ->> 'sourceRevisionId'
      AND source.source_id = citation_item ->> 'sourceId'
      AND membership.component_generation_id = ANY(
        ARRAY[
          claim_row.exact30_generation_id,
          claim_row.oa112_generation_id,
          claim_row.owner_private_generation_id
        ]::text[]
      )
      AND source.retrieval_topics && claim_row.allowed_topics
      AND EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_generation_embeddings AS embedding
        WHERE embedding.component_generation_id = membership.component_generation_id
          AND embedding.chunk_id = membership.chunk_id
          AND embedding.component_scope = membership.component_scope
          AND embedding.owner_partition_key = membership.owner_partition_key
          AND embedding.embedding_profile_id = CASE
            WHEN membership.component_scope = 'OWNER_PRIVATE' THEN claim_row.owner_embedding_profile_id
            ELSE claim_row.embedding_profile_id
          END
      );
    IF NOT FOUND THEN
      RAISE EXCEPTION 'immutable RAG v2 citation is outside the active scope'
        USING ERRCODE = '55000';
    END IF;

    IF candidate.source_scope IN ('EXACT30', 'OA112') THEN
      IF requested_kind <> 'PUBLIC_WEB'
         OR candidate.owner_user_id IS NOT NULL
         OR candidate.sanitized_display_name IS NOT NULL
         OR candidate.citation_title IS NULL
         OR char_length(candidate.citation_title) NOT BETWEEN 1 AND 500
         OR NOT public.rag_v2_immutable_public_https_url_is_valid(candidate.canonical_https_url)
         OR (
           candidate.source_scope = 'EXACT30'
           AND candidate.component_generation_id <> claim_row.exact30_generation_id
         )
         OR (
           candidate.source_scope = 'OA112'
           AND (
             candidate.component_generation_id <> claim_row.oa112_generation_id
             OR NOT EXISTS (
               SELECT 1
               FROM public.rag_v2_immutable_oa_source_cards AS card
               WHERE card.source_revision_id = candidate.source_revision_id
                 AND card.source_id = candidate.source_id
                 AND card.active_oa112_eligible
                 AND card.canonical_https_url = candidate.canonical_https_url
             )
           )
         ) THEN
        RAISE EXCEPTION 'immutable RAG v2 public citation is invalid'
          USING ERRCODE = '55000';
      END IF;
      output := output || jsonb_build_array(
        jsonb_build_object(
          'citationKind', 'PUBLIC_WEB',
          'citationId', citation_item ->> 'citationId',
          'sourceId', candidate.source_id,
          'sourceRevisionId', candidate.source_revision_id,
          'chunkRevisionId', candidate.chunk_id,
          'generationId', candidate.component_generation_id,
          'title', candidate.citation_title,
          'canonicalUrl', candidate.canonical_https_url,
          'locator', candidate.locator
        )
      );
    ELSE
      IF requested_kind <> 'LOCAL_DOCUMENT'
         OR candidate.source_scope <> 'OWNER_PRIVATE'
         OR candidate.owner_user_id <> p_owner_user_id
         OR candidate.component_generation_id IS DISTINCT FROM claim_row.owner_private_generation_id
         OR candidate.citation_title IS NOT NULL
         OR candidate.canonical_https_url IS NOT NULL
         OR candidate.document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
         OR candidate.sanitized_display_name IS NULL
         OR char_length(candidate.sanitized_display_name) NOT BETWEEN 1 AND 160
         OR candidate.sanitized_display_name ~ '[/\\:]' THEN
        RAISE EXCEPTION 'immutable RAG v2 owner citation is invalid'
          USING ERRCODE = '55000';
      END IF;
      output := output || jsonb_build_array(
        jsonb_build_object(
          'citationKind', 'LOCAL_DOCUMENT',
          'citationId', citation_item ->> 'citationId',
          'sourceId', candidate.source_id,
          'sourceRevisionId', candidate.source_revision_id,
          'chunkRevisionId', candidate.chunk_id,
          'generationId', candidate.component_generation_id,
          'documentId', candidate.document_id,
          'displayName', candidate.sanitized_display_name,
          'locator', candidate.locator
        )
      );
    END IF;
    expected_ordinal := expected_ordinal + 1;
  END LOOP;
  RETURN output;
END
$_$;


ALTER FUNCTION public.canonicalize_rag_v2_immutable_retrieval_citations(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_citations jsonb) OWNER TO flyway;


CREATE FUNCTION public.canonicalize_s4_9_strong_llm_citations_v2(p_owner_user_id text, p_request_id text, p_session_id text, p_scope_claim_id text, p_citations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  item jsonb;
  canonical_one jsonb;
  source_row public.s4_9_grounding_source_nodes%ROWTYPE;
  output jsonb := '[]'::jsonb;
  expected_ordinal integer := 1;
  seen_keys text[] := ARRAY[]::text[];
  receipt_key text;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_request_id !~ '^req_[A-Za-z0-9_-]{12,96}$'
     OR jsonb_typeof(p_citations) <> 'array' OR jsonb_array_length(p_citations) NOT BETWEEN 1 AND 5
     OR octet_length(p_citations::text) > 32768 THEN
    RAISE EXCEPTION 'S4.9 v2 citation arguments are invalid' USING ERRCODE = '22023';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_citations)
  LOOP
    IF jsonb_typeof(item) <> 'object'
       OR item ->> 'ordinal' <> expected_ordinal::text
       OR item ->> 'citationId' <> ('cit_' || expected_ordinal::text)
       OR item ->> 'citationKind' NOT IN ('PUBLIC_WEB','LOCAL_DOCUMENT') THEN
      RAISE EXCEPTION 'S4.9 v2 citation order is invalid' USING ERRCODE = '22023';
    END IF;

    IF item ? 'provenanceResultId' THEN
      IF NOT (item ?& ARRAY['sourceId','title','canonicalUrl','locator'])
         OR item ->> 'citationKind' <> 'PUBLIC_WEB'
         OR NOT (
           item ->> 'provenanceResultId' ~ '^google_[1-9][0-9]{0,2}$'
           OR item ->> 'provenanceResultId' ~ '^searxng_[0-9a-f]{24}$'
           OR item ->> 'provenanceResultId' ~ '^user_[0-9a-f]{24}$'
           OR item ->> 'provenanceResultId' ~ '^link_[0-9a-f]{24}$'
         )
         OR item ->> 'sourceId' !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
         OR jsonb_typeof(item -> 'locator') <> 'object'
         OR NOT (item -> 'locator' ? 'section') THEN
        RAISE EXCEPTION 'S4.9 web citation receipt is invalid' USING ERRCODE = '22023';
      END IF;
      SELECT * INTO source_row FROM public.s4_9_grounding_source_nodes AS source
      WHERE source.owner_user_id = p_owner_user_id AND source.request_id = p_request_id
        AND source.result_id = item ->> 'provenanceResultId'
        AND (
          (source.source_type = 'GOOGLE_GROUNDING' AND source.result_id ~ '^google_[1-9][0-9]{0,2}$')
          OR (source.source_type = 'SEARXNG_RESULT' AND source.result_id ~ '^searxng_[0-9a-f]{24}$')
          OR (source.source_type = 'USER_ROOT' AND source.result_id ~ '^user_[0-9a-f]{24}$')
          OR (source.source_type = 'DISCOVERED_LINK' AND source.result_id ~ '^link_[0-9a-f]{24}$')
        )
        AND source.title = item ->> 'title'
        AND source.canonical_url = item ->> 'canonicalUrl'
        AND source.domain = item -> 'locator' ->> 'section'
        AND EXISTS (
          SELECT 1 FROM public.s4_9_grounding_support_edges AS edge
          WHERE edge.owner_user_id = p_owner_user_id AND edge.request_id = p_request_id
            AND edge.source_node_id = source.source_node_id
        );
      IF NOT FOUND THEN
        RAISE EXCEPTION 'S4.9 web citation is outside grounded provenance' USING ERRCODE = '55000';
      END IF;
      receipt_key := 'web:' || source_row.source_node_id;
      canonical_one := jsonb_build_object(
        'citationKind','PUBLIC_WEB', 'citationId',item ->> 'citationId',
        'sourceId',item ->> 'sourceId', 'title',source_row.title,
        'canonicalUrl',source_row.canonical_url, 'locator',jsonb_build_object('section',source_row.domain)
      );
    ELSE
      IF EXISTS (
        SELECT 1 FROM jsonb_object_keys(item) AS key_name
        WHERE key_name NOT IN (
          'ordinal','citationId','sourceId','sourceRevisionId','chunkRevisionId','generationId','citationKind'
        )
      ) THEN
        RAISE EXCEPTION 'S4.9 canonical citation receipt is invalid' USING ERRCODE = '22023';
      END IF;
      canonical_one := public.canonicalize_rag_v2_immutable_retrieval_citations(
        p_owner_user_id, p_session_id, p_scope_claim_id,
        jsonb_build_array(
          jsonb_build_object(
            'ordinal',1, 'citationId','cit_1', 'sourceId',item ->> 'sourceId',
            'sourceRevisionId',item ->> 'sourceRevisionId',
            'chunkRevisionId',item ->> 'chunkRevisionId', 'generationId',item ->> 'generationId',
            'citationKind',item ->> 'citationKind'
          )
        )
      ) -> 0;
      receipt_key := 'canonical:' || (canonical_one ->> 'chunkRevisionId');
      canonical_one := canonical_one || jsonb_build_object('citationId',item ->> 'citationId');
    END IF;
    IF receipt_key = ANY(seen_keys) THEN
      RAISE EXCEPTION 'S4.9 v2 citation is duplicated' USING ERRCODE = '22023';
    END IF;
    seen_keys := array_append(seen_keys, receipt_key);
    output := output || jsonb_build_array(canonical_one);
    expected_ordinal := expected_ordinal + 1;
  END LOOP;
  RETURN output;
END
$_$;


ALTER FUNCTION public.canonicalize_s4_9_strong_llm_citations_v2(p_owner_user_id text, p_request_id text, p_session_id text, p_scope_claim_id text, p_citations jsonb) OWNER TO flyway;


CREATE FUNCTION public.claim_async_job_by_event(p_worker text, p_event_id text, p_event_type text, p_job_id text, p_payload_hash text, p_partition_key text) RETURNS TABLE(job_id text, job_type text, payload_json jsonb, claim_token uuid, attempt_count integer, hard_deadline_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
#variable_conflict use_column
DECLARE candidate public.async_job%ROWTYPE; claimed public.async_job%ROWTYPE;
BEGIN
  IF session_user <> 'decision_worker' THEN RAISE EXCEPTION 'Kafka async claim role denied' USING ERRCODE='42501'; END IF;
  IF p_worker !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$' OR p_event_id !~ '^evt_[A-Za-z0-9_-]{8,96}$'
     OR p_job_id !~ '^job_[A-Za-z0-9_-]{8,96}$' OR p_payload_hash !~ '^sha256:[0-9a-f]{64}$'
     OR p_partition_key !~ '^hmac-sha256:[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'invalid Kafka async claim' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.event_outbox source
    WHERE source.event_id=p_event_id AND source.event_type=p_event_type
      AND source.aggregate_type='ASYNC_JOB' AND source.aggregate_id=p_job_id
      AND source.partition_key=p_partition_key AND source.schema_version='1.0.0'
      AND source.transport_payload_hash=p_payload_hash
      AND source.status IN ('PENDING','FAILED','PUBLISHED')
  ) THEN RAISE EXCEPTION 'Kafka event is not bound to outbox' USING ERRCODE='42501'; END IF;
  SELECT item.* INTO candidate
  FROM public.async_job item
  WHERE item.job_id=p_job_id
    AND (
      (item.status IN ('REQUESTED','FAILED') AND item.next_attempt_at<=statement_timestamp()
        AND (item.lease_expires_at IS NULL OR item.lease_expires_at<=statement_timestamp()))
      OR (item.status='RUNNING' AND item.lease_expires_at<=statement_timestamp())
    )
  FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN RETURN; END IF;

  IF candidate.status='RUNNING' THEN
    UPDATE public.async_job item
    SET status='FAILED',claim_token=NULL,claimed_by=NULL,lease_expires_at=NULL,heartbeat_at=NULL,
      error_code='LEASE_EXPIRED',error_class='CONTRACT_VIOLATION',error_message='LEASE_EXPIRED',
      next_attempt_at=statement_timestamp(),updated_at=statement_timestamp()
    WHERE item.job_id=candidate.job_id;
    candidate.status := 'FAILED';
  END IF;

  IF candidate.attempt_count>=3
     OR (candidate.hard_deadline_at IS NOT NULL AND candidate.hard_deadline_at<=statement_timestamp()) THEN
    IF candidate.status='REQUESTED' THEN
      UPDATE public.async_job item
      SET status='FAILED',error_code='HARD_DEADLINE_EXCEEDED',error_class='CONTRACT_VIOLATION',
        error_message='HARD_DEADLINE_EXCEEDED',updated_at=statement_timestamp()
      WHERE item.job_id=candidate.job_id;
    END IF;
    UPDATE public.async_job item
    SET status='NEEDS_REVIEW',claim_token=NULL,claimed_by=NULL,lease_expires_at=NULL,heartbeat_at=NULL,
      error_code=coalesce(item.error_code,'LEASE_EXPIRED'),
      error_class=coalesce(item.error_class,'CONTRACT_VIOLATION'),
      error_message=coalesce(item.error_message,'LEASE_EXPIRED'),updated_at=statement_timestamp()
    WHERE item.job_id=candidate.job_id AND item.status='FAILED';
    RETURN;
  END IF;

  UPDATE public.async_job item
  SET status='RUNNING',claim_token=gen_random_uuid(),claimed_by=p_worker,
    lease_expires_at=statement_timestamp()+interval '5 minutes',heartbeat_at=statement_timestamp(),
    hard_deadline_at=coalesce(item.hard_deadline_at,statement_timestamp()+interval '15 minutes'),
    attempt_count=item.attempt_count+1,error_code=NULL,error_class=NULL,error_message=NULL,
    started_at=coalesce(item.started_at,statement_timestamp()),updated_at=statement_timestamp()
  WHERE item.job_id=candidate.job_id
  RETURNING item.* INTO claimed;
  RETURN QUERY SELECT claimed.job_id,claimed.job_type,claimed.payload_json,claimed.claim_token,
    claimed.attempt_count,claimed.hard_deadline_at;
END
$_$;


ALTER FUNCTION public.claim_async_job_by_event(p_worker text, p_event_id text, p_event_type text, p_job_id text, p_payload_hash text, p_partition_key text) OWNER TO flyway;


CREATE FUNCTION public.claim_async_job_by_id(p_worker text, p_job_id text) RETURNS TABLE(job_id text, job_type text, payload_json jsonb, claim_token uuid, attempt_count integer, hard_deadline_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF session_user <> 'decision_worker' THEN
    RAISE EXCEPTION 'async job claim role denied' USING ERRCODE = '42501';
  END IF;
  IF p_worker !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$'
     OR p_job_id !~ '^job_[A-Za-z0-9_-]{8,96}$' THEN
    RAISE EXCEPTION 'invalid async claim request' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH candidate AS (
    SELECT item.job_id
    FROM public.async_job item
    WHERE item.job_id = p_job_id
      AND item.status IN ('REQUESTED', 'FAILED')
      AND item.attempt_count < 3
      AND item.next_attempt_at <= statement_timestamp()
      AND (item.lease_expires_at IS NULL OR item.lease_expires_at <= statement_timestamp())
    FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE public.async_job item
    SET status = 'RUNNING', claim_token = gen_random_uuid(), claimed_by = p_worker,
        lease_expires_at = statement_timestamp() + interval '5 minutes',
        heartbeat_at = statement_timestamp(), hard_deadline_at = statement_timestamp() + interval '15 minutes',
        attempt_count = item.attempt_count + 1,
        started_at = COALESCE(item.started_at, statement_timestamp()), updated_at = statement_timestamp()
    FROM candidate
    WHERE item.job_id = candidate.job_id
    RETURNING item.*
  )
  SELECT claimed.job_id, claimed.job_type, claimed.payload_json, claimed.claim_token,
         claimed.attempt_count, claimed.hard_deadline_at
  FROM claimed;
END
$_$;


ALTER FUNCTION public.claim_async_job_by_id(p_worker text, p_job_id text) OWNER TO flyway;


CREATE FUNCTION public.claim_async_jobs(p_worker text, p_limit integer DEFAULT 100) RETURNS TABLE(job_id text, job_type text, payload_json jsonb, claim_token uuid, attempt_count integer, hard_deadline_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF session_user <> 'decision_worker' THEN
    RAISE EXCEPTION 'async job claim role denied' USING ERRCODE = '42501';
  END IF;
  IF p_worker !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$' OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'invalid async claim request' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH candidates AS (
    SELECT item.job_id
    FROM public.async_job item
    WHERE item.status IN ('REQUESTED', 'FAILED') AND item.attempt_count < 3
      AND item.next_attempt_at <= statement_timestamp()
      AND (item.lease_expires_at IS NULL OR item.lease_expires_at <= statement_timestamp())
    ORDER BY item.next_attempt_at, item.created_at, item.job_id
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ), claimed AS (
    UPDATE public.async_job item
    SET status = 'RUNNING', claim_token = gen_random_uuid(), claimed_by = p_worker,
        lease_expires_at = statement_timestamp() + interval '5 minutes',
        heartbeat_at = statement_timestamp(), hard_deadline_at = statement_timestamp() + interval '15 minutes',
        attempt_count = item.attempt_count + 1,
        started_at = COALESCE(item.started_at, statement_timestamp()), updated_at = statement_timestamp()
    FROM candidates
    WHERE item.job_id = candidates.job_id
    RETURNING item.*
  )
  SELECT claimed.job_id, claimed.job_type, claimed.payload_json, claimed.claim_token,
         claimed.attempt_count, claimed.hard_deadline_at
  FROM claimed
  ORDER BY claimed.next_attempt_at, claimed.created_at, claimed.job_id;
END
$_$;


ALTER FUNCTION public.claim_async_jobs(p_worker text, p_limit integer) OWNER TO flyway;


CREATE FUNCTION public.claim_db_async_outbox(p_worker text, p_limit integer DEFAULT 100) RETURNS TABLE(event_id text, event_type text, aggregate_type text, aggregate_id text, partition_key text, payload_json jsonb, outbox_schema_version text, kafka_schema_version integer, topic_name text, claim_token uuid, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'DB async outbox claim role denied' USING ERRCODE = '42501';
  END IF;
  IF p_worker !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$' OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'invalid DB async outbox claim request' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH candidates AS (
    SELECT item.event_id
    FROM public.event_outbox item
    JOIN public.async_event_registry registry
      ON registry.event_type = item.event_type
     AND registry.outbox_schema_version = item.schema_version
     AND registry.enabled
    WHERE item.event_type IN (
        'artifact.ingest-requested.v1',
        'rag.index-requested.v1',
        'model.eval-requested.v1'
      )
      AND item.status IN ('PENDING', 'FAILED')
      AND item.retry_count < 3
      AND item.next_attempt_at <= statement_timestamp()
      AND (item.lease_expires_at IS NULL OR item.lease_expires_at <= statement_timestamp())
    ORDER BY item.next_attempt_at, item.created_at, item.event_id
    FOR UPDATE OF item SKIP LOCKED
    LIMIT p_limit
  ), claimed AS (
    UPDATE public.event_outbox item
    SET claim_token = gen_random_uuid(), claimed_by = p_worker,
        lease_expires_at = statement_timestamp() + interval '30 seconds',
        updated_at = statement_timestamp()
    FROM candidates
    WHERE item.event_id = candidates.event_id
    RETURNING item.*
  )
  SELECT claimed.event_id, claimed.event_type, claimed.aggregate_type, claimed.aggregate_id,
         claimed.partition_key, claimed.payload_json, claimed.schema_version,
         registry.kafka_schema_version, registry.topic_name, claimed.claim_token,
         claimed.retry_count + 1
  FROM claimed
  JOIN public.async_event_registry registry ON registry.event_type = claimed.event_type
  ORDER BY claimed.next_attempt_at, claimed.created_at, claimed.event_id;
END
$_$;


ALTER FUNCTION public.claim_db_async_outbox(p_worker text, p_limit integer) OWNER TO flyway;


CREATE FUNCTION public.claim_dlq_outbox(p_worker text, p_limit integer DEFAULT 100) RETURNS TABLE(storage_event_id text, event_id text, event_type text, aggregate_type text, aggregate_id text, partition_key text, payload_json jsonb, occurred_at timestamp with time zone, outbox_schema_version text, kafka_schema_version integer, topic_name text, claim_token uuid, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF session_user <> 'decision_app' THEN RAISE EXCEPTION 'DLQ outbox claim role denied' USING ERRCODE='42501'; END IF;
  IF p_worker !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$' OR p_limit<1 OR p_limit>100 THEN
    RAISE EXCEPTION 'invalid DLQ claim request' USING ERRCODE='22023';
  END IF;
  RETURN QUERY
  WITH candidates AS (
    SELECT item.event_id FROM public.event_outbox item JOIN public.async_event_registry registry
      ON registry.event_type=item.event_type AND registry.outbox_schema_version=item.schema_version
    WHERE item.status='DLQ_REQUESTED' AND item.retry_count<3 AND item.next_attempt_at<=statement_timestamp()
      AND (item.lease_expires_at IS NULL OR item.lease_expires_at<=statement_timestamp())
    ORDER BY item.next_attempt_at,item.created_at,item.event_id FOR UPDATE OF item SKIP LOCKED LIMIT p_limit
  ), claimed AS (
    UPDATE public.event_outbox item SET claim_token=gen_random_uuid(),claimed_by=p_worker,
      lease_expires_at=statement_timestamp()+interval '30 seconds',updated_at=statement_timestamp()
    FROM candidates WHERE item.event_id=candidates.event_id RETURNING item.*
  )
  SELECT claimed.event_id,
    'evt_dlq_'||substr(encode(public.digest(claimed.event_id,'sha256'),'hex'),1,32),
    claimed.event_type,claimed.aggregate_type,claimed.aggregate_id,claimed.partition_key,
    jsonb_build_object(
      'eventId',claimed.event_id,'eventType',claimed.event_type,
      'payloadHash',coalesce(claimed.transport_payload_hash,claimed.payload_json->>'payloadHash',
        'sha256:'||encode(public.digest(claimed.payload_json::text,'sha256'),'hex')),
      'failureCode',coalesce(claimed.failure_code,'ASYNC_TERMINAL_FAILURE'),
      'sourceTopic',claimed.event_type,'attempt',least(3,claimed.retry_count+1)
    ),claimed.created_at,claimed.schema_version,registry.kafka_schema_version,
    regexp_replace(registry.topic_name,'\.v1$','.dlq.v1'),claimed.claim_token,least(3,claimed.retry_count+1)
  FROM claimed JOIN public.async_event_registry registry ON registry.event_type=claimed.event_type
  ORDER BY claimed.next_attempt_at,claimed.created_at,claimed.event_id;
END
$_$;


ALTER FUNCTION public.claim_dlq_outbox(p_worker text, p_limit integer) OWNER TO flyway;


CREATE FUNCTION public.claim_event_outbox(p_worker text, p_limit integer DEFAULT 100) RETURNS TABLE(event_id text, event_type text, aggregate_type text, aggregate_id text, partition_key text, payload_json jsonb, occurred_at timestamp with time zone, outbox_schema_version text, kafka_schema_version integer, topic_name text, claim_token uuid, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'outbox claim role denied' USING ERRCODE = '42501';
  END IF;
  IF p_worker !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$' OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'invalid outbox claim request' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT item.event_id
    FROM public.event_outbox item
    JOIN public.async_event_registry registry
      ON registry.event_type = item.event_type
     AND registry.outbox_schema_version = item.schema_version
     AND registry.enabled
    WHERE item.status IN ('PENDING', 'FAILED')
      AND item.retry_count < 3
      AND item.next_attempt_at <= statement_timestamp()
      AND (item.lease_expires_at IS NULL OR item.lease_expires_at <= statement_timestamp())
    ORDER BY item.next_attempt_at, item.created_at, item.event_id
    FOR UPDATE OF item SKIP LOCKED
    LIMIT p_limit
  ), claimed AS (
    UPDATE public.event_outbox item
    SET claim_token = gen_random_uuid(),
        claimed_by = p_worker,
        lease_expires_at = statement_timestamp() + interval '30 seconds',
        updated_at = statement_timestamp()
    FROM candidates
    WHERE item.event_id = candidates.event_id
    RETURNING item.*
  )
  SELECT claimed.event_id, claimed.event_type, claimed.aggregate_type, claimed.aggregate_id,
         claimed.partition_key, claimed.payload_json, claimed.created_at, claimed.schema_version,
         registry.kafka_schema_version, registry.topic_name, claimed.claim_token,
         claimed.retry_count + 1
  FROM claimed
  JOIN public.async_event_registry registry ON registry.event_type = claimed.event_type
  ORDER BY claimed.next_attempt_at, claimed.created_at, claimed.event_id;
END
$_$;


ALTER FUNCTION public.claim_event_outbox(p_worker text, p_limit integer) OWNER TO flyway;


CREATE FUNCTION public.claim_rag_answer(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text, p_claim_ttl_seconds integer) RETURNS TABLE(outcome text, answer_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  inserted_rows integer;
  existing_claim public.rag_answer_claims%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_scope_hmac !~ '^[0-9a-f]{64}$'
     OR p_request_fingerprint !~ '^[0-9a-f]{64}$'
     OR p_claim_ttl_seconds NOT BETWEEN 30 AND 300
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'RAG answer claim arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.rag_answer_claims (
    scope_hmac,
    owner_user_id,
    request_fingerprint,
    state,
    pending_expires_at
  )
  VALUES (
    p_scope_hmac,
    p_owner_user_id,
    p_request_fingerprint,
    'PENDING',
    transaction_timestamp() + make_interval(secs => p_claim_ttl_seconds)
  )
  ON CONFLICT (scope_hmac) DO NOTHING;
  GET DIAGNOSTICS inserted_rows = ROW_COUNT;

  IF inserted_rows = 1 THEN
    INSERT INTO public.rag_answer_claim_transitions (
      scope_hmac, owner_user_id, from_state, to_state, provider_attempts
    )
    VALUES (p_scope_hmac, p_owner_user_id, NULL, 'PENDING', 0);
    RETURN QUERY SELECT 'CLAIMED'::text, NULL::text;
    RETURN;
  END IF;

  SELECT claim.*
  INTO existing_claim
  FROM public.rag_answer_claims AS claim
  WHERE claim.scope_hmac = p_scope_hmac
    AND claim.owner_user_id = p_owner_user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG answer claim owner mismatch'
      USING ERRCODE = '42501';
  END IF;
  IF existing_claim.request_fingerprint <> p_request_fingerprint THEN
    RETURN QUERY SELECT 'CONFLICT'::text, NULL::text;
    RETURN;
  END IF;
  IF existing_claim.state = 'COMPLETE' THEN
    IF existing_claim.answer_id IS NOT NULL
       AND EXISTS (
         SELECT 1
         FROM public.rag_answer_history AS history
         WHERE history.answer_id = existing_claim.answer_id
           AND history.owner_user_id = p_owner_user_id
           AND history.expires_at > statement_timestamp()
       ) THEN
      RETURN QUERY SELECT 'REPLAY'::text, existing_claim.answer_id;
    ELSE
      RETURN QUERY SELECT 'RESULT_UNAVAILABLE'::text, NULL::text;
    END IF;
    RETURN;
  END IF;
  IF existing_claim.state = 'PENDING'
     AND existing_claim.pending_expires_at <= statement_timestamp() THEN
    UPDATE public.rag_answer_claims
    SET state = 'UNKNOWN_AFTER_PROVIDER',
        updated_at = transaction_timestamp()
    WHERE scope_hmac = p_scope_hmac;
    INSERT INTO public.rag_answer_claim_transitions (
      scope_hmac, owner_user_id, from_state, to_state, provider_attempts
    )
    VALUES (
      p_scope_hmac,
      p_owner_user_id,
      'PENDING',
      'UNKNOWN_AFTER_PROVIDER',
      existing_claim.provider_attempts
    );
    RETURN QUERY SELECT 'UNKNOWN_AFTER_PROVIDER'::text, NULL::text;
    RETURN;
  END IF;
  RETURN QUERY
  SELECT
    CASE existing_claim.state
      WHEN 'PENDING' THEN 'IN_PROGRESS'
      ELSE existing_claim.state
    END,
    NULL::text;
END
$_$;


ALTER FUNCTION public.claim_rag_answer(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text, p_claim_ttl_seconds integer) OWNER TO flyway;


CREATE FUNCTION public.claim_rag_v2_immutable_vertex_generate_content_attempt(p_usage_event_id text, p_owner_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  reservation public.rag_v2_immutable_vertex_usage_reservations%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_usage_event_id !~ '^rgr_vgu_[0-9a-f]{32}$'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$' THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex generate claim arguments are invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO reservation
  FROM public.rag_v2_immutable_vertex_usage_reservations
  WHERE usage_event_id = p_usage_event_id AND owner_user_id = p_owner_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR reservation.expires_at <= statement_timestamp()
     OR reservation.authentication_mode <> 'SERVICE_ACCOUNT_OAUTH'
     OR reservation.token_physical_call_cap <> 1
     OR reservation.generate_content_physical_call_cap <> 1
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_vertex_usage_token_attempts
       WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_token_call_count = 1
     )
     OR EXISTS (SELECT 1 FROM public.rag_v2_immutable_vertex_usage_generate_content_attempts WHERE usage_event_id = p_usage_event_id)
     OR EXISTS (SELECT 1 FROM public.rag_v2_immutable_vertex_usage_outcomes WHERE usage_event_id = p_usage_event_id) THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex generate claim is unavailable' USING ERRCODE = '55000';
  END IF;
  PERFORM public.assert_rag_v2_immutable_vertex_reservation_is_current(reservation);
  INSERT INTO public.rag_v2_immutable_vertex_usage_generate_content_attempts (
    usage_event_id, state, physical_generate_content_call_count
  ) VALUES (p_usage_event_id, 'ATTEMPTED', 1);
END
$_$;


