CREATE FUNCTION public.commit_and_stage_rag_v2_immutable_voyage_document_batch(p_payload jsonb) RETURNS TABLE(batch_plan_sha256 text, batch_id text, state text, batch_reused boolean, completed_batch_count integer, staged_vector_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  usage_payload jsonb;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(p_payload)) <> 6
     OR NOT (p_payload ?& ARRAY['schemaVersion','plan','batch','packetSha256','vectors','usage'])
     OR jsonb_typeof(p_payload -> 'usage') <> 'object' THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch atomic payload is invalid'
      USING ERRCODE = '22023';
  END IF;
  usage_payload := p_payload -> 'usage';
  IF (SELECT count(*) FROM jsonb_object_keys(usage_payload)) <> 4
     OR NOT (usage_payload ?& ARRAY[
       'usageEventId','expectedInputTokens','providerTotalTokens','actualCostMicrousd'
     ])
     OR usage_payload ->> 'usageEventId' !~ '^rgr_vou_[0-9a-f]{32}$'
     OR (usage_payload ->> 'expectedInputTokens')::integer
        <> (p_payload -> 'batch' ->> 'tokenCount')::integer
     OR (usage_payload ->> 'providerTotalTokens')::integer NOT BETWEEN 0 AND 110000
     OR (usage_payload ->> 'actualCostMicrousd')::bigint NOT BETWEEN 0 AND 1000000000 THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch usage payload is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_voyage_document_batch_attempts AS attempt
    WHERE attempt.usage_event_id = usage_payload ->> 'usageEventId'
      AND attempt.batch_plan_sha256 = p_payload -> 'plan' ->> 'batchPlanSha256'
      AND attempt.batch_id = p_payload -> 'batch' ->> 'batchId'
      AND attempt.batch_manifest_sha256 = p_payload -> 'batch' ->> 'batchManifestSha256'
      AND attempt.packet_sha256 = p_payload ->> 'packetSha256'
      AND attempt.state = 'CLAIMED'
  ) THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch attempt is absent' USING ERRCODE = '55000';
  END IF;
  PERFORM public.commit_rag_v2_immutable_voyage_usage_with_tokenizer(
    usage_payload ->> 'usageEventId',
    (usage_payload ->> 'expectedInputTokens')::integer,
    (usage_payload ->> 'providerTotalTokens')::integer,
    (usage_payload ->> 'actualCostMicrousd')::bigint
  );
  RETURN QUERY
  SELECT staged.batch_plan_sha256, staged.batch_id, staged.state, staged.batch_reused,
         staged.completed_batch_count, staged.staged_vector_count
  FROM public.stage_rag_v2_immutable_voyage_document_batch(p_payload - 'usage') AS staged;
  UPDATE public.rag_v2_immutable_voyage_document_batch_attempts AS attempt
  SET state = 'COMMITTED', terminal_at = transaction_timestamp()
  WHERE attempt.usage_event_id = usage_payload ->> 'usageEventId'
    AND attempt.state = 'CLAIMED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch attempt commit conflicts'
      USING ERRCODE = '55000';
  END IF;
END
$_$;


ALTER FUNCTION public.commit_and_stage_rag_v2_immutable_voyage_document_batch(p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.commit_and_stage_rag_v2_immutable_voyage_evaluation_batch(p_payload jsonb) RETURNS TABLE(component_scope text, staged_vector_count integer, batch_reused boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  expected_count integer;
  vector_item jsonb;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(p_payload)) <> 10
     OR NOT (p_payload ?& ARRAY[
       'schemaVersion','scopeClaimSha256','componentScope','queryManifestSha256','usageEventId',
       'packetSha256','expectedInputTokens','providerTotalTokens','actualCostMicrousd','vectors'
     ])
     OR p_payload ->> 'schemaVersion' <> 'pre-s5-voyage-evaluation-batch-stage/v1'
     OR p_payload ->> 'scopeClaimSha256' !~ '^[0-9a-f]{64}$'
     OR p_payload ->> 'componentScope' NOT IN ('EXACT30','OA112')
     OR p_payload ->> 'queryManifestSha256' !~ '^[0-9a-f]{64}$'
     OR p_payload ->> 'usageEventId' !~ '^rgr_vqu_[0-9a-f]{32}$'
     OR p_payload ->> 'packetSha256' !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_payload -> 'vectors') <> 'array' THEN
    RAISE EXCEPTION 'Pre-S5 Voyage evaluation stage payload is invalid' USING ERRCODE = '22023';
  END IF;
  expected_count := CASE p_payload ->> 'componentScope' WHEN 'EXACT30' THEN 10 ELSE 112 END;
  IF jsonb_array_length(p_payload -> 'vectors') <> expected_count
     OR (p_payload ->> 'expectedInputTokens')::integer NOT BETWEEN 1 AND 8192
     OR (p_payload ->> 'providerTotalTokens')::integer NOT BETWEEN 0 AND 8192
     OR (p_payload ->> 'actualCostMicrousd')::bigint NOT BETWEEN 0 AND 1000000000
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_evaluation_batch_attempts AS attempt
       WHERE attempt.scope_claim_sha256 = p_payload ->> 'scopeClaimSha256'
         AND attempt.component_scope = p_payload ->> 'componentScope'
         AND attempt.query_manifest_sha256 = p_payload ->> 'queryManifestSha256'
         AND attempt.usage_event_id = p_payload ->> 'usageEventId'
         AND attempt.packet_sha256 = p_payload ->> 'packetSha256'
         AND attempt.state = 'CLAIMED'
     ) THEN
    RAISE EXCEPTION 'Pre-S5 Voyage evaluation stage is unavailable' USING ERRCODE = '55000';
  END IF;
  PERFORM public.commit_rag_v2_immutable_voyage_query_usage_with_tokenizer(
    p_payload ->> 'usageEventId',
    (p_payload ->> 'expectedInputTokens')::integer,
    (p_payload ->> 'providerTotalTokens')::integer,
    (p_payload ->> 'actualCostMicrousd')::bigint
  );
  FOR vector_item IN SELECT value FROM jsonb_array_elements(p_payload -> 'vectors') LOOP
    IF (SELECT count(*) FROM jsonb_object_keys(vector_item)) <> 3
       OR NOT (vector_item ?& ARRAY['querySha256','vectorSha256','embedding'])
       OR vector_item ->> 'querySha256' !~ '^[0-9a-f]{64}$'
       OR vector_item ->> 'vectorSha256' !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(vector_item -> 'embedding') <> 'array'
       OR jsonb_array_length(vector_item -> 'embedding') <> 1024 THEN
      RAISE EXCEPTION 'Pre-S5 Voyage evaluation vector payload is invalid' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.rag_v2_immutable_voyage_evaluation_batch_vectors (
      scope_claim_sha256, component_scope, query_manifest_sha256, query_sha256,
      vector_sha256, embedding
    ) VALUES (
      p_payload ->> 'scopeClaimSha256', p_payload ->> 'componentScope',
      p_payload ->> 'queryManifestSha256', vector_item ->> 'querySha256',
      vector_item ->> 'vectorSha256', (vector_item -> 'embedding')::text::vector
    );
  END LOOP;
  UPDATE public.rag_v2_immutable_voyage_evaluation_batch_attempts
  SET state = 'COMMITTED', terminal_at = transaction_timestamp()
  WHERE usage_event_id = p_payload ->> 'usageEventId' AND state = 'CLAIMED';
  IF NOT FOUND OR (
    SELECT count(*) FROM public.rag_v2_immutable_voyage_evaluation_batch_vectors AS staged_vector
    WHERE staged_vector.scope_claim_sha256 = p_payload ->> 'scopeClaimSha256'
      AND staged_vector.component_scope = p_payload ->> 'componentScope'
  ) <> expected_count THEN
    RAISE EXCEPTION 'Pre-S5 Voyage evaluation stage cardinality conflicts' USING ERRCODE = '55000';
  END IF;
  RETURN QUERY SELECT p_payload ->> 'componentScope', expected_count, false;
END
$_$;


ALTER FUNCTION public.commit_and_stage_rag_v2_immutable_voyage_evaluation_batch(p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.commit_async_work(p_event_id text, p_event_type text, p_consumer_name text, p_payload_hash text, p_job_id text, p_claim_token uuid, p_result_ref text, p_completion_event_id text, p_partition_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
#variable_conflict use_column
DECLARE item public.async_job%ROWTYPE; existing_hash text; completion_type text; existing_status text;
BEGIN
  IF session_user <> 'decision_worker' THEN RAISE EXCEPTION 'async work commit role denied' USING ERRCODE='42501'; END IF;
  IF p_event_id !~ '^evt_[A-Za-z0-9_-]{8,96}$' OR p_consumer_name !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$'
     OR p_payload_hash !~ '^sha256:[0-9a-f]{64}$' OR p_result_ref !~ '^[A-Za-z][A-Za-z0-9_-]{7,127}$'
     OR p_completion_event_id !~ '^evt_[A-Za-z0-9_-]{8,96}$' OR p_partition_key !~ '^hmac-sha256:[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'invalid async work commit' USING ERRCODE='22023';
  END IF;
  SELECT payload_hash INTO existing_hash FROM public.processed_event
  WHERE event_id=p_event_id AND consumer_name=p_consumer_name FOR UPDATE;
  IF FOUND THEN
    IF existing_hash IS DISTINCT FROM p_payload_hash THEN
      UPDATE public.processed_event SET payload_hash_conflict=true
      WHERE event_id=p_event_id AND consumer_name=p_consumer_name;
      RETURN 'PAYLOAD_CONFLICT';
    END IF;
    SELECT status INTO existing_status FROM public.async_job WHERE job_id=p_job_id;
    IF existing_status='COMPLETED' AND EXISTS (
      SELECT 1 FROM public.async_materialization_receipt WHERE event_id=p_event_id AND job_id=p_job_id
    ) THEN RETURN 'DUPLICATE'; END IF;
    RAISE EXCEPTION 'processed event exists without completed claim' USING ERRCODE='40001';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.event_outbox source
    WHERE source.event_id=p_event_id AND source.event_type=p_event_type
      AND source.aggregate_type='ASYNC_JOB' AND source.aggregate_id=p_job_id
      AND source.partition_key=p_partition_key AND source.schema_version='1.0.0'
      AND coalesce(source.transport_payload_hash,
        'sha256:'||encode(public.digest(source.payload_json::text,'sha256'),'hex'))=p_payload_hash
      AND source.status IN ('PENDING','FAILED','PUBLISHED')
  ) THEN RAISE EXCEPTION 'async event/outbox binding conflict' USING ERRCODE='42501'; END IF;
  SELECT * INTO item FROM public.async_job
  WHERE job_id=p_job_id AND claim_token=p_claim_token AND status='RUNNING'
    AND lease_expires_at>statement_timestamp() AND hard_deadline_at>statement_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'async work claim conflict' USING ERRCODE='40001'; END IF;
  completion_type:=CASE p_event_type WHEN 'rag.index-requested.v1' THEN 'rag.index-completed.v1'
    WHEN 'artifact.ingest-requested.v1' THEN 'artifact.ingested.v1'
    WHEN 'model.eval-requested.v1' THEN 'model.eval-completed.v1' ELSE NULL END;
  IF completion_type IS NULL
     OR (p_event_type='rag.index-requested.v1' AND item.job_type<>'RAG_INDEX')
     OR (p_event_type='artifact.ingest-requested.v1' AND item.job_type<>'ARTIFACT_INGEST')
     OR (p_event_type='model.eval-requested.v1' AND item.job_type<>'MODEL_EVAL') THEN
    RAISE EXCEPTION 'async event and job type conflict' USING ERRCODE='22023';
  END IF;
  IF (item.job_type='RAG_INDEX' AND (
      coalesce(item.payload_json->>'sourceId','') !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
      OR coalesce(item.payload_json->>'sourceRevisionId','') !~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'
      OR coalesce(item.payload_json->>'importTicketId','') !~ '^rti_[0-9a-f]{32}$'))
     OR (item.job_type='ARTIFACT_INGEST' AND (coalesce(item.payload_json->>'artifactId','') !~ '^artifact_[A-Za-z0-9_-]{8,96}$'
      OR coalesce(item.payload_json->>'contentHash','') !~ '^sha256:[0-9a-f]{64}$'))
     OR (item.job_type='MODEL_EVAL' AND (coalesce(item.payload_json->>'runId','') !~ '^(run|demo)_[A-Za-z0-9_-]{8,96}$'
      OR coalesce(item.payload_json->>'contentHash','') !~ '^sha256:[0-9a-f]{64}$')) THEN
    RAISE EXCEPTION 'async work references are invalid' USING ERRCODE='22023';
  END IF;
  IF item.job_type='RAG_INDEX' AND NOT EXISTS (
    SELECT 1 FROM public.rag_v2_immutable_source_revisions source
    JOIN public.rag_v2_immutable_import_tickets ticket ON ticket.owner_user_id=source.owner_user_id
      AND ticket.ticket_hash=encode(public.digest(item.payload_json->>'importTicketId','sha256'),'hex')
      AND ticket.state='CONSUMED' AND ticket.embedding_profile_id='bge_m3_local_1024_v1'
    WHERE source.source_revision_id=item.payload_json->>'sourceRevisionId'
      AND source.source_id=item.payload_json->>'sourceId' AND source.owner_user_id=item.requested_by
      AND source.source_scope='OWNER_PRIVATE' AND source.local_processing_allowed
      AND item.payload_json->>'ownerRef'=item.requested_by
      AND item.payload_json->>'profileId'='bge_m3_local_1024_v1'
  ) THEN RAISE EXCEPTION 'RAG async request lacks consumed local owner evidence' USING ERRCODE='42501'; END IF;
  INSERT INTO public.processed_event(event_id,consumer_name,payload_hash)
  VALUES (p_event_id,p_consumer_name,p_payload_hash);
  INSERT INTO public.async_materialization_receipt(
    result_ref,event_id,job_id,job_type,source_revision_id,artifact_id,run_id,content_hash
  ) VALUES (p_result_ref,p_event_id,p_job_id,item.job_type,item.payload_json->>'sourceRevisionId',
    item.payload_json->>'artifactId',item.payload_json->>'runId',item.payload_json->>'contentHash');
  UPDATE public.async_job SET status='COMPLETED',result_json=jsonb_build_object('resultRef',p_result_ref),
    completed_at=statement_timestamp(),claim_token=NULL,claimed_by=NULL,lease_expires_at=NULL,
    error_code=NULL,error_class=NULL,error_message=NULL,updated_at=statement_timestamp()
  WHERE job_id=p_job_id AND claim_token=p_claim_token;
  INSERT INTO public.event_outbox(event_id,event_type,aggregate_type,aggregate_id,partition_key,payload_json,schema_version)
  VALUES (p_completion_event_id,completion_type,'ASYNC_JOB',p_job_id,p_partition_key,
    jsonb_build_object('jobId',p_job_id,'resultRef',p_result_ref),'1.0.0');
  RETURN 'COMPLETED';
END
$_$;


ALTER FUNCTION public.commit_async_work(p_event_id text, p_event_type text, p_consumer_name text, p_payload_hash text, p_job_id text, p_claim_token uuid, p_result_ref text, p_completion_event_id text, p_partition_key text) OWNER TO flyway;


CREATE FUNCTION public.commit_rag_v2_immutable_vertex_usage(p_usage_event_id text, p_owner_user_id text, p_prompt_token_count integer, p_candidate_token_count integer, p_total_token_count integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  reservation public.rag_v2_immutable_vertex_usage_reservations%ROWTYPE;
  calculated_cost bigint;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_usage_event_id !~ '^rgr_vgu_[0-9a-f]{32}$'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_prompt_token_count NOT BETWEEN 0 AND 120000
     OR p_candidate_token_count NOT BETWEEN 0 AND 32768
     OR p_total_token_count NOT BETWEEN p_prompt_token_count + p_candidate_token_count AND 152768
     OR p_total_token_count - p_prompt_token_count - p_candidate_token_count NOT BETWEEN 0 AND 32768 THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex usage commit arguments are invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO reservation
  FROM public.rag_v2_immutable_vertex_usage_reservations
  WHERE usage_event_id = p_usage_event_id AND owner_user_id = p_owner_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR reservation.authentication_mode <> 'SERVICE_ACCOUNT_OAUTH'
     OR reservation.token_physical_call_cap <> 1
     OR reservation.generate_content_physical_call_cap <> 1
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_vertex_usage_token_attempts
       WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_token_call_count = 1
     )
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_vertex_usage_generate_content_attempts
       WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_generate_content_call_count = 1
     )
     OR EXISTS (SELECT 1 FROM public.rag_v2_immutable_vertex_usage_outcomes WHERE usage_event_id = p_usage_event_id)
     OR p_prompt_token_count > reservation.input_token_cap
     OR p_candidate_token_count > reservation.output_token_cap
     OR p_total_token_count - p_prompt_token_count > reservation.output_token_cap THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex usage commit is unavailable' USING ERRCODE = '55000';
  END IF;
  -- hidden thought token도 output 단가로 보수적으로 과금해 승인 cost cap을 우회하지 못하게 한다.
  calculated_cost := p_prompt_token_count::bigint * reservation.input_microusd_per_token
    + (p_total_token_count - p_prompt_token_count)::bigint * reservation.output_microusd_per_token;
  IF calculated_cost > reservation.cost_cap_microusd THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex usage commit exceeds the approved cost cap' USING ERRCODE = '55000';
  END IF;
  INSERT INTO public.rag_v2_immutable_vertex_usage_outcomes (
    usage_event_id, packet_sha256, state, physical_token_call_count, physical_generate_content_call_count,
    prompt_token_count, candidate_token_count, total_token_count, actual_cost_microusd
  ) VALUES (
    p_usage_event_id, reservation.packet_sha256, 'COMMITTED', 1, 1,
    p_prompt_token_count, p_candidate_token_count, p_total_token_count, calculated_cost
  );
END
$_$;


ALTER FUNCTION public.commit_rag_v2_immutable_vertex_usage(p_usage_event_id text, p_owner_user_id text, p_prompt_token_count integer, p_candidate_token_count integer, p_total_token_count integer) OWNER TO flyway;


CREATE FUNCTION public.commit_rag_v2_immutable_voyage_query_usage(p_usage_event_id text, p_provider_total_tokens integer, p_actual_cost_microusd bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  reservation rag_v2_immutable_voyage_query_usage_reservations%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_usage_event_id !~ '^rgr_vqu_[0-9a-f]{32}$'
     OR p_provider_total_tokens NOT BETWEEN 0 AND 8192
     OR p_actual_cost_microusd NOT BETWEEN 0 AND 1000000000 THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage query usage commit arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO reservation
  FROM public.rag_v2_immutable_voyage_query_usage_reservations
  WHERE usage_event_id = p_usage_event_id
  FOR UPDATE;
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_query_usage_attempts
       WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_call_count = 1
     )
     OR EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_query_usage_outcomes
       WHERE usage_event_id = p_usage_event_id
     )
     OR p_provider_total_tokens > reservation.token_cap
     OR p_actual_cost_microusd <> p_provider_total_tokens::bigint * reservation.input_microusd_per_token
     OR p_actual_cost_microusd > reservation.cost_cap_microusd THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage query usage commit is unavailable'
      USING ERRCODE = '55000';
  END IF;
  INSERT INTO public.rag_v2_immutable_voyage_query_usage_outcomes (
    usage_event_id, packet_sha256, state, provider_total_tokens, actual_cost_microusd
  ) VALUES (
    p_usage_event_id, reservation.packet_sha256, 'COMMITTED',
    p_provider_total_tokens, p_actual_cost_microusd
  );
END
$_$;


ALTER FUNCTION public.commit_rag_v2_immutable_voyage_query_usage(p_usage_event_id text, p_provider_total_tokens integer, p_actual_cost_microusd bigint) OWNER TO flyway;


CREATE FUNCTION public.commit_rag_v2_immutable_voyage_query_usage_with_tokenizer(p_usage_event_id text, p_expected_input_tokens integer, p_provider_total_tokens integer, p_actual_cost_microusd bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  reservation rag_v2_immutable_voyage_query_usage_reservations%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_usage_event_id IS NULL OR p_usage_event_id !~ '^rgr_vqu_[0-9a-f]{32}$'
     OR p_expected_input_tokens IS NULL OR p_expected_input_tokens NOT BETWEEN 1 AND 8192
     OR p_provider_total_tokens IS NULL OR p_provider_total_tokens NOT BETWEEN 0 AND 8192
     OR p_actual_cost_microusd IS NULL OR p_actual_cost_microusd NOT BETWEEN 0 AND 1000000000 THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage query tokenizer usage commit arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO reservation
  FROM public.rag_v2_immutable_voyage_query_usage_reservations
  WHERE usage_event_id = p_usage_event_id
  FOR UPDATE;
  IF NOT FOUND
     OR reservation.official_tokenizer_sha256 IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_query_usage_attempts
       WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_call_count = 1
     )
     OR EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_query_usage_outcomes
       WHERE usage_event_id = p_usage_event_id
     )
     OR p_expected_input_tokens > reservation.token_cap
     OR p_provider_total_tokens > reservation.token_cap
     OR p_actual_cost_microusd <> p_provider_total_tokens::bigint * reservation.input_microusd_per_token
     OR p_actual_cost_microusd > reservation.cost_cap_microusd THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage query tokenizer usage commit is unavailable'
      USING ERRCODE = '55000';
  END IF;
  INSERT INTO public.rag_v2_immutable_voyage_query_usage_outcomes (
    usage_event_id, packet_sha256, state, expected_input_tokens, provider_total_tokens, actual_cost_microusd
  ) VALUES (
    p_usage_event_id, reservation.packet_sha256, 'COMMITTED',
    p_expected_input_tokens, p_provider_total_tokens, p_actual_cost_microusd
  );
END
$_$;


ALTER FUNCTION public.commit_rag_v2_immutable_voyage_query_usage_with_tokenizer(p_usage_event_id text, p_expected_input_tokens integer, p_provider_total_tokens integer, p_actual_cost_microusd bigint) OWNER TO flyway;


CREATE FUNCTION public.commit_rag_v2_immutable_voyage_usage(p_usage_event_id text, p_provider_total_tokens integer, p_actual_cost_microusd bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  reservation rag_v2_immutable_voyage_usage_reservations%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_usage_event_id !~ '^rgr_vou_[0-9a-f]{32}$'
     OR p_provider_total_tokens NOT BETWEEN 0 AND 120000
     OR p_actual_cost_microusd NOT BETWEEN 0 AND 1000000000 THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage usage commit arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO reservation
  FROM public.rag_v2_immutable_voyage_usage_reservations
  WHERE usage_event_id = p_usage_event_id
  FOR UPDATE;
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_usage_attempts
       WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_call_count = 1
     )
     OR EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_usage_outcomes
       WHERE usage_event_id = p_usage_event_id
     )
     OR p_provider_total_tokens > reservation.token_cap
     OR p_actual_cost_microusd <> p_provider_total_tokens::bigint * reservation.input_microusd_per_token
     OR p_actual_cost_microusd > reservation.cost_cap_microusd THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage usage commit is unavailable'
      USING ERRCODE = '55000';
  END IF;
  INSERT INTO public.rag_v2_immutable_voyage_usage_outcomes (
    usage_event_id, packet_sha256, state, provider_total_tokens, actual_cost_microusd
  ) VALUES (
    p_usage_event_id, reservation.packet_sha256, 'COMMITTED',
    p_provider_total_tokens, p_actual_cost_microusd
  );
END
$_$;


ALTER FUNCTION public.commit_rag_v2_immutable_voyage_usage(p_usage_event_id text, p_provider_total_tokens integer, p_actual_cost_microusd bigint) OWNER TO flyway;


CREATE FUNCTION public.commit_rag_v2_immutable_voyage_usage_with_tokenizer(p_usage_event_id text, p_expected_input_tokens integer, p_provider_total_tokens integer, p_actual_cost_microusd bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  reservation rag_v2_immutable_voyage_usage_reservations%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_usage_event_id IS NULL OR p_usage_event_id !~ '^rgr_vou_[0-9a-f]{32}$'
     OR p_expected_input_tokens IS NULL OR p_expected_input_tokens NOT BETWEEN 1 AND 120000
     OR p_provider_total_tokens IS NULL OR p_provider_total_tokens NOT BETWEEN 0 AND 120000
     OR p_actual_cost_microusd IS NULL OR p_actual_cost_microusd NOT BETWEEN 0 AND 1000000000 THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage tokenizer usage commit arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO reservation
  FROM public.rag_v2_immutable_voyage_usage_reservations
  WHERE usage_event_id = p_usage_event_id
  FOR UPDATE;
  IF NOT FOUND
     OR reservation.official_tokenizer_sha256 IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_usage_attempts
       WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_call_count = 1
     )
     OR EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_voyage_usage_outcomes
       WHERE usage_event_id = p_usage_event_id
     )
     OR p_expected_input_tokens > reservation.token_cap
     OR p_provider_total_tokens > reservation.token_cap
     OR p_actual_cost_microusd <> p_provider_total_tokens::bigint * reservation.input_microusd_per_token
     OR p_actual_cost_microusd > reservation.cost_cap_microusd THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage tokenizer usage commit is unavailable'
      USING ERRCODE = '55000';
  END IF;
  INSERT INTO public.rag_v2_immutable_voyage_usage_outcomes (
    usage_event_id, packet_sha256, state, expected_input_tokens, provider_total_tokens, actual_cost_microusd
  ) VALUES (
    p_usage_event_id, reservation.packet_sha256, 'COMMITTED',
    p_expected_input_tokens, p_provider_total_tokens, p_actual_cost_microusd
  );
END
$_$;


ALTER FUNCTION public.commit_rag_v2_immutable_voyage_usage_with_tokenizer(p_usage_event_id text, p_expected_input_tokens integer, p_provider_total_tokens integer, p_actual_cost_microusd bigint) OWNER TO flyway;


CREATE FUNCTION public.complete_async_job(p_job_id text, p_claim_token uuid, p_result jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE changed integer;
BEGIN
  IF session_user <> 'decision_worker' THEN
    RAISE EXCEPTION 'async completion role denied' USING ERRCODE = '42501';
  END IF;
  IF p_result IS NULL OR jsonb_typeof(p_result) <> 'object' OR octet_length(p_result::text) > 32768 THEN
    RAISE EXCEPTION 'invalid async result' USING ERRCODE = '22023';
  END IF;
  UPDATE public.async_job
  SET status = 'COMPLETED', result_json = p_result, completed_at = statement_timestamp(),
      claim_token = NULL, claimed_by = NULL, lease_expires_at = NULL,
      error_code = NULL, error_class = NULL, error_message = NULL, updated_at = statement_timestamp()
  WHERE job_id = p_job_id AND claim_token = p_claim_token AND status = 'RUNNING'
    AND lease_expires_at > statement_timestamp() AND hard_deadline_at > statement_timestamp();
  GET DIAGNOSTICS changed = ROW_COUNT;
  RETURN changed = 1;
END
$$;


ALTER FUNCTION public.complete_async_job(p_job_id text, p_claim_token uuid, p_result jsonb) OWNER TO flyway;


CREATE FUNCTION public.complete_dlq_outbox(p_event_id text, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE changed integer;
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'DLQ completion role denied' USING ERRCODE = '42501';
  END IF;
  UPDATE public.event_outbox
  SET status = 'PUBLISHED', published_at = statement_timestamp(), claim_token = NULL,
      claimed_by = NULL, lease_expires_at = NULL, updated_at = statement_timestamp()
  WHERE event_id = p_event_id AND claim_token = p_claim_token
    AND status = 'DLQ_REQUESTED' AND lease_expires_at > statement_timestamp();
  GET DIAGNOSTICS changed = ROW_COUNT;
  RETURN changed = 1;
END
$$;


ALTER FUNCTION public.complete_dlq_outbox(p_event_id text, p_claim_token uuid) OWNER TO flyway;


CREATE FUNCTION public.complete_event_outbox(p_event_id text, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  changed integer;
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'outbox completion role denied' USING ERRCODE = '42501';
  END IF;
  UPDATE public.event_outbox
  SET status = 'PUBLISHED', published_at = statement_timestamp(), claim_token = NULL,
      claimed_by = NULL, lease_expires_at = NULL, failure_code = NULL,
      error_class = NULL, last_error = NULL, updated_at = statement_timestamp()
  WHERE event_id = p_event_id
    AND claim_token = p_claim_token
    AND status IN ('PENDING', 'FAILED')
    AND lease_expires_at > statement_timestamp();
  GET DIAGNOSTICS changed = ROW_COUNT;
  RETURN changed = 1;
END
$$;


ALTER FUNCTION public.complete_event_outbox(p_event_id text, p_claim_token uuid) OWNER TO flyway;


CREATE FUNCTION public.complete_rag_answer(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text, p_answer_id text, p_answer_mode text, p_generation_status text, p_citation_coverage double precision, p_retrieval_failure boolean, p_guardrail_flags text[], p_kek_version text, p_wrap_nonce bytea, p_wrapped_dek bytea, p_wrap_tag bytea, p_question_nonce bytea, p_question_ciphertext bytea, p_question_tag bytea, p_answer_nonce bytea, p_answer_ciphertext bytea, p_answer_tag bytea, p_created_at timestamp with time zone, p_provider_attempts integer, p_citations jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  citation_count integer;
  valid_citation_count integer;
  locked_claim public.rag_answer_claims%ROWTYPE;
BEGIN
  citation_count :=
    CASE
      WHEN jsonb_typeof(p_citations) = 'array' THEN jsonb_array_length(p_citations)
      ELSE -1
    END;
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_scope_hmac !~ '^[0-9a-f]{64}$'
     OR p_request_fingerprint !~ '^[0-9a-f]{64}$'
     OR p_answer_id !~ '^rag_ans_[0-9a-f]{32}$'
     OR p_answer_mode NOT IN ('CONCISE', 'DETAILED')
     OR p_generation_status NOT IN (
       'ANSWERED',
       'RETRIEVAL_ONLY',
       'RETRIEVAL_FAILURE',
       'BLOCKED_SENSITIVE',
       'BLOCKED_ADVICE',
       'GENERATION_UNAVAILABLE'
     )
     OR p_citation_coverage IS NULL
     OR p_citation_coverage NOT BETWEEN 0.0 AND 1.0
     OR p_guardrail_flags IS NULL
     OR cardinality(p_guardrail_flags) NOT BETWEEN 0 AND 8
     OR EXISTS (
       SELECT 1 FROM unnest(p_guardrail_flags) AS flag
       WHERE flag !~ '^[A-Z0-9_]{1,64}$'
     )
     OR p_kek_version !~ '^kek-v[1-9][0-9]{0,8}$'
     OR octet_length(p_wrap_nonce) <> 12
     OR octet_length(p_wrapped_dek) <> 32
     OR octet_length(p_wrap_tag) <> 16
     OR octet_length(p_question_nonce) <> 12
     OR octet_length(p_question_ciphertext) NOT BETWEEN 1 AND 8192
     OR octet_length(p_question_tag) <> 16
     OR octet_length(p_answer_nonce) <> 12
     OR octet_length(p_answer_ciphertext) NOT BETWEEN 0 AND 8192
     OR octet_length(p_answer_tag) <> 16
     OR p_created_at IS NULL
     OR p_created_at > transaction_timestamp() + interval '5 seconds'
     OR p_created_at < transaction_timestamp() - interval '5 minutes'
     OR p_provider_attempts NOT BETWEEN 0 AND 1
     OR citation_count NOT BETWEEN 0 AND 5
     OR (p_generation_status = 'ANSWERED' AND citation_count = 0)
     OR (p_generation_status <> 'ANSWERED' AND citation_count <> 0)
     OR (
       p_generation_status = 'ANSWERED'
       AND (p_citation_coverage <> 1.0 OR p_retrieval_failure)
     )
     OR (
       p_generation_status = 'RETRIEVAL_FAILURE'
       AND (p_citation_coverage <> 0.0 OR NOT p_retrieval_failure)
     )
     OR (
       p_generation_status NOT IN ('ANSWERED', 'RETRIEVAL_FAILURE')
       AND (p_citation_coverage <> 0.0 OR p_retrieval_failure)
     ) THEN
    RAISE EXCEPTION 'RAG answer completion arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT claim.*
  INTO locked_claim
  FROM public.rag_answer_claims AS claim
  WHERE claim.scope_hmac = p_scope_hmac
    AND claim.owner_user_id = p_owner_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR locked_claim.request_fingerprint <> p_request_fingerprint
     OR locked_claim.state <> 'PENDING'
     OR locked_claim.provider_attempts <> p_provider_attempts THEN
    RAISE EXCEPTION 'RAG answer claim cannot be completed'
      USING ERRCODE = '55000';
  END IF;

  SELECT count(*)::integer
  INTO valid_citation_count
  FROM jsonb_array_elements(p_citations) AS item(value)
  JOIN public.rag_sources AS source
    ON source.source_id = item.value ->> 'sourceId'
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = item.value ->> 'sourceRevisionId'
   AND revision.source_id = source.source_id
   AND revision.access_level = 'PUBLIC'
   AND revision.tier = 'PROJECT'
  JOIN public.rag_source_card_verifications AS verification
    ON verification.source_revision_id = revision.source_revision_id
   AND verification.card_metadata_hash = revision.metadata_hash
   AND verification.status = 'VERIFIED'
  JOIN public.rag_embedding_policy_state AS policy
    ON policy.state_id = 'default'
   AND policy.active_generation_id = item.value ->> 'generationId'
  JOIN public.rag_corpus_generations AS generation
    ON generation.corpus_generation_id = policy.active_generation_id
   AND generation.embedding_profile_id = policy.effective_profile_id
   AND generation.status = 'ACTIVE'
   AND generation.evaluation_status = 'PASSED'
  JOIN public.rag_chunk_revisions AS chunk
    ON chunk.chunk_revision_id = item.value ->> 'chunkRevisionId'
   AND chunk.source_revision_id = revision.source_revision_id
   AND chunk.access_level = 'PUBLIC'
   AND chunk.tier = 'PROJECT'
  JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = generation.corpus_generation_id
   AND membership.embedding_profile_id = generation.embedding_profile_id
   AND membership.chunk_revision_id = chunk.chunk_revision_id
  WHERE jsonb_typeof(item.value) = 'object'
    AND (
      SELECT count(*)
      FROM jsonb_object_keys(item.value)
    ) = 9
    AND item.value ?& ARRAY[
      'ordinal',
      'citationId',
      'sourceId',
      'sourceRevisionId',
      'chunkRevisionId',
      'generationId',
      'title',
      'sectionTitle',
      'canonicalUrl'
    ]
    AND (item.value ->> 'ordinal') ~ '^[1-5]$'
    AND (item.value ->> 'citationId') ~ '^cit_[1-5]$'
    AND (item.value ->> 'chunkRevisionId') ~ '^rag_chk_[0-9a-f]{32}$'
    AND (item.value ->> 'ordinal')::integer BETWEEN 1 AND citation_count
    AND item.value ->> 'citationId' =
        'cit_' || (item.value ->> 'ordinal')
    AND item.value ->> 'title' = revision.title
    AND item.value ->> 'sectionTitle' =
        chunk.heading_path[cardinality(chunk.heading_path)]
    AND item.value ->> 'canonicalUrl' = revision.canonical_url
    AND octet_length(item.value ->> 'title') BETWEEN 1 AND 1024
    AND octet_length(item.value ->> 'sectionTitle') BETWEEN 1 AND 512
    AND (item.value ->> 'canonicalUrl') ~ '^https://'
    AND octet_length(item.value ->> 'canonicalUrl') BETWEEN 9 AND 2048;
  IF valid_citation_count <> citation_count THEN
    RAISE EXCEPTION 'RAG citation access recheck failed'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.rag_answer_history (
    answer_id,
    owner_user_id,
    answer_mode,
    generation_status,
    citation_coverage,
    retrieval_failure,
    guardrail_flags,
    citation_count,
    kek_version,
    wrap_nonce,
    wrapped_dek,
    wrap_tag,
    question_nonce,
    question_ciphertext,
    question_tag,
    answer_nonce,
    answer_ciphertext,
    answer_tag,
    created_at,
    expires_at
  )
  VALUES (
    p_answer_id,
    p_owner_user_id,
    p_answer_mode,
    p_generation_status,
    p_citation_coverage,
    p_retrieval_failure,
    p_guardrail_flags,
    citation_count,
    p_kek_version,
    p_wrap_nonce,
    p_wrapped_dek,
    p_wrap_tag,
    p_question_nonce,
    p_question_ciphertext,
    p_question_tag,
    p_answer_nonce,
    p_answer_ciphertext,
    p_answer_tag,
    p_created_at,
    p_created_at + interval '30 days'
  );

  INSERT INTO public.rag_answer_citations (
    answer_id,
    ordinal,
    citation_id,
    source_id,
    source_revision_id,
    chunk_revision_id,
    generation_id,
    title,
    section_title,
    canonical_url
  )
  SELECT
    p_answer_id,
    (item.value ->> 'ordinal')::integer,
    item.value ->> 'citationId',
    item.value ->> 'sourceId',
    item.value ->> 'sourceRevisionId',
    item.value ->> 'chunkRevisionId',
    item.value ->> 'generationId',
    item.value ->> 'title',
    item.value ->> 'sectionTitle',
    item.value ->> 'canonicalUrl'
  FROM jsonb_array_elements(p_citations) AS item(value)
  ORDER BY (item.value ->> 'ordinal')::integer;

  UPDATE public.rag_answer_claims
  SET state = 'COMPLETE',
      answer_id = p_answer_id,
      updated_at = transaction_timestamp()
  WHERE scope_hmac = p_scope_hmac;
  INSERT INTO public.rag_answer_claim_transitions (
    scope_hmac, owner_user_id, from_state, to_state, provider_attempts
  )
  VALUES (
    p_scope_hmac,
    p_owner_user_id,
    'PENDING',
    'COMPLETE',
    p_provider_attempts
  );
END
$_$;


ALTER FUNCTION public.complete_rag_answer(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text, p_answer_id text, p_answer_mode text, p_generation_status text, p_citation_coverage double precision, p_retrieval_failure boolean, p_guardrail_flags text[], p_kek_version text, p_wrap_nonce bytea, p_wrapped_dek bytea, p_wrap_tag bytea, p_question_nonce bytea, p_question_ciphertext bytea, p_question_tag bytea, p_answer_nonce bytea, p_answer_ciphertext bytea, p_answer_tag bytea, p_created_at timestamp with time zone, p_provider_attempts integer, p_citations jsonb) OWNER TO flyway;


CREATE FUNCTION public.complete_rag_v2_owner_voyage_import(p_owner_user_id text, p_plan_sha256 text, p_packet_sha256 text, p_items jsonb, p_expected_input_tokens integer, p_provider_total_tokens integer, p_actual_cost_microusd bigint) RETURNS TABLE(component_generation_id text, document_count integer, chunk_count integer, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  attempt public.rag_v2_owner_voyage_import_attempts%ROWTYPE;
  item jsonb;
  staged record;
  completed_documents integer := 0;
  completed_chunks integer := 0;
  last_generation_id text := NULL;
  provided_ticket_set_sha256 text;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR jsonb_typeof(p_items) <> 'array'
     OR p_expected_input_tokens NOT BETWEEN 1 AND 55000
     OR p_provider_total_tokens NOT BETWEEN 1 AND 120000
     OR p_actual_cost_microusd < 0 THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage completion arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO attempt
  FROM public.rag_v2_owner_voyage_import_attempts
  WHERE plan_sha256 = p_plan_sha256
    AND owner_user_id = p_owner_user_id
    AND packet_sha256 = p_packet_sha256
    AND state = 'ATTEMPTED'
  FOR UPDATE;
  IF NOT FOUND
     OR attempt.expected_input_tokens <> p_expected_input_tokens
     OR jsonb_array_length(p_items) <> attempt.document_count THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage attempt is not completable'
      USING ERRCODE = '55000';
  END IF;
  SELECT encode(
    digest(
      coalesce(
        string_agg((value ->> 'importTicketId') || E'\n', '' ORDER BY ordinal),
        ''
      ),
      'sha256'
    ),
    'hex'
  )
  INTO provided_ticket_set_sha256
  FROM jsonb_array_elements(p_items) WITH ORDINALITY AS values(value, ordinal);
  IF provided_ticket_set_sha256 IS DISTINCT FROM attempt.ticket_set_sha256 THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage ticket set drifted'
      USING ERRCODE = '55000';
  END IF;

  PERFORM set_config('app.rag_v2_owner_voyage_completion', 'enabled', true);
  FOR item IN SELECT value FROM jsonb_array_elements(p_items) WITH ORDINALITY AS values(value, ordinal) ORDER BY ordinal
  LOOP
    IF jsonb_typeof(item) <> 'object'
       OR item ->> 'importTicketId' !~ '^rti_[0-9a-f]{32}$'
       OR jsonb_typeof(item -> 'stagingPayload') <> 'object' THEN
      RAISE EXCEPTION 'immutable RAG v2 owner Voyage completion item is invalid'
        USING ERRCODE = '22023';
    END IF;
    SELECT * INTO staged
    FROM public.stage_rag_v2_immutable_owner_document_v3(
      p_owner_user_id,
      item ->> 'importTicketId',
      item -> 'stagingPayload'
    );
    IF staged.state <> 'STAGED' OR staged.source_count <> 1 OR staged.chunk_count < 1 THEN
      RAISE EXCEPTION 'immutable RAG v2 owner Voyage staging was incomplete'
        USING ERRCODE = '23514';
    END IF;
    last_generation_id := staged.component_generation_id;
    completed_documents := completed_documents + 1;
    completed_chunks := completed_chunks + staged.chunk_count;
  END LOOP;
  IF completed_documents <> attempt.document_count OR completed_chunks <> attempt.chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage completion cardinality drifted'
      USING ERRCODE = '23514';
  END IF;
  UPDATE public.rag_v2_owner_voyage_import_attempts
  SET state = 'COMMITTED', provider_total_tokens = p_provider_total_tokens,
      actual_cost_microusd = p_actual_cost_microusd, completed_at = clock_timestamp()
  WHERE plan_sha256 = p_plan_sha256 AND state = 'ATTEMPTED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage usage commit conflicted'
      USING ERRCODE = '40001';
  END IF;
  RETURN QUERY SELECT last_generation_id, completed_documents, completed_chunks, 'STAGED';
END;
$_$;


ALTER FUNCTION public.complete_rag_v2_owner_voyage_import(p_owner_user_id text, p_plan_sha256 text, p_packet_sha256 text, p_items jsonb, p_expected_input_tokens integer, p_provider_total_tokens integer, p_actual_cost_microusd bigint) OWNER TO flyway;


CREATE FUNCTION public.consume_actor_request_capability(p_token text, p_actor_user_id text, p_security_version bigint, p_required_role text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE changed integer;
BEGIN
  IF (session_user <> 'decision_app' AND NOT EXISTS (
        SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolsuper
      )) OR p_token !~ '^cap_[0-9a-f]{64}$'
     OR p_required_role IS NOT NULL AND p_required_role <> 'ADMIN' THEN
    RAISE EXCEPTION 'actor capability denied' USING ERRCODE = '42501';
  END IF;
  UPDATE public.actor_request_capability capability
  SET consumed_at = statement_timestamp()
  WHERE capability.token_hash = 'sha256:' || encode(public.digest(p_token, 'sha256'), 'hex')
    AND capability.actor_user_id = p_actor_user_id
    AND capability.actor_security_version = p_security_version
    AND (p_required_role IS NULL OR capability.actor_role = p_required_role)
    AND capability.consumed_at IS NULL
    AND capability.expires_at > statement_timestamp()
    AND EXISTS (
      SELECT 1 FROM public.users actor
      WHERE actor.user_id = capability.actor_user_id
        AND actor.status = 'ACTIVE'
        AND actor.role = capability.actor_role
        AND actor.security_version = capability.actor_security_version
    );
  GET DIAGNOSTICS changed = ROW_COUNT;
  RETURN changed = 1;
END
$_$;


ALTER FUNCTION public.consume_actor_request_capability(p_token text, p_actor_user_id text, p_security_version bigint, p_required_role text) OWNER TO flyway;


CREATE FUNCTION public.consume_current_actor_capability(p_capability text, p_actor_user_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE current_security_version bigint;
BEGIN
  IF session_user <> 'decision_app' AND NOT EXISTS (
    SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolsuper
  ) THEN
    RAISE EXCEPTION 'principle capability role denied' USING ERRCODE='42501';
  END IF;
  SELECT actor.security_version INTO current_security_version
  FROM public.users actor WHERE actor.user_id=p_actor_user_id;
  IF NOT FOUND THEN RETURN false; END IF;
  RETURN public.consume_actor_request_capability(
    p_capability,p_actor_user_id,current_security_version,NULL
  );
END
$$;


ALTER FUNCTION public.consume_current_actor_capability(p_capability text, p_actor_user_id text) OWNER TO flyway;


CREATE FUNCTION public.consume_rag_v2_immutable_import_ticket(p_owner_user_id text, p_ticket_id text, p_operation text, p_policy_version text, p_materialization_run_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  ticket_digest text;
  consumed boolean := false;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_ticket_id !~ '^rti_[0-9a-f]{32}$'
     OR p_operation <> 'OWNER_IMPORT'
     OR p_policy_version <> 'RAG_V2_OWNER_DOCUMENT_V1'
     OR p_materialization_run_id !~ '^rgr_run_[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 import ticket consume arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  ticket_digest := encode(digest(p_ticket_id, 'sha256'), 'hex');
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-ticket|' || ticket_digest, 0)
  );
  -- writer는 owner/JWT를 보유하지 않으며, one-time capability가 owner scope를 재검증한 뒤에만 actor를 좁힌다.
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  IF NOT EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_materialization_runs AS run
    JOIN public.users AS owner
      ON owner.user_id = run.owner_user_id
    WHERE run.materialization_run_id = p_materialization_run_id
      AND run.owner_user_id = p_owner_user_id
      AND run.component_scope = 'OWNER_PRIVATE'
      AND run.state IN ('OPEN', 'STAGED')
      AND owner.status = 'ACTIVE'
  ) THEN
    RETURN false;
  END IF;
  UPDATE public.rag_v2_immutable_import_tickets
  SET state = 'CONSUMED',
      consumed_at = clock_timestamp(),
      consumer_run_id = p_materialization_run_id
  WHERE ticket_hash = ticket_digest
    AND owner_user_id = p_owner_user_id
    AND operation = p_operation
    AND policy_version = p_policy_version
    AND state = 'ISSUED'
    AND consumed_at IS NULL
    AND expires_at > statement_timestamp()
  RETURNING true INTO consumed;
  RETURN coalesce(consumed, false);
END;
$_$;


ALTER FUNCTION public.consume_rag_v2_immutable_import_ticket(p_owner_user_id text, p_ticket_id text, p_operation text, p_policy_version text, p_materialization_run_id text) OWNER TO flyway;


CREATE FUNCTION public.consume_rag_v2_immutable_import_ticket_v2(p_owner_user_id text, p_ticket_id text, p_operation text, p_policy_version text, p_embedding_profile_id text, p_materialization_run_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  ticket_digest text;
  consumed boolean := false;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_ticket_id !~ '^rti_[0-9a-f]{32}$'
     OR p_operation <> 'OWNER_IMPORT'
     OR p_policy_version <> 'RAG_V2_OWNER_DOCUMENT_V2'
     OR p_embedding_profile_id NOT IN ('bge_m3_local_1024_v1', 'voyage_context_4_1024_v1')
     OR p_materialization_run_id !~ '^rgr_run_[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 import ticket v2 consume arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  ticket_digest := encode(digest(p_ticket_id, 'sha256'), 'hex');
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-ticket|' || ticket_digest, 0)
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  IF NOT EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_materialization_runs AS run
    JOIN public.rag_v2_immutable_component_generations AS generation
      ON generation.component_generation_id = run.component_generation_id
    WHERE run.materialization_run_id = p_materialization_run_id
      AND run.owner_user_id = p_owner_user_id
      AND run.component_scope = 'OWNER_PRIVATE'
      AND run.state IN ('OPEN', 'STAGED')
      AND generation.embedding_profile_id = p_embedding_profile_id
  ) THEN
    RETURN false;
  END IF;
  UPDATE public.rag_v2_immutable_import_tickets
  SET state = 'CONSUMED', consumed_at = clock_timestamp(),
      consumer_run_id = p_materialization_run_id
  WHERE ticket_hash = ticket_digest
    AND owner_user_id = p_owner_user_id
    AND operation = p_operation
    AND policy_version = p_policy_version
    AND embedding_profile_id = p_embedding_profile_id
    AND state = 'ISSUED'
    AND consumed_at IS NULL
    AND expires_at > statement_timestamp()
  RETURNING true INTO consumed;
  RETURN coalesce(consumed, false);
END;
$_$;


ALTER FUNCTION public.consume_rag_v2_immutable_import_ticket_v2(p_owner_user_id text, p_ticket_id text, p_operation text, p_policy_version text, p_embedding_profile_id text, p_materialization_run_id text) OWNER TO flyway;


CREATE FUNCTION public.consume_s4_9_mcp_oauth_code_hash(p_code_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app' OR p_code_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'S4.9 authorization code hash is invalid' USING ERRCODE = '22023';
  END IF;
  UPDATE public.s4_9_mcp_oauth_authorization_codes
  SET consumed_at = transaction_timestamp()
  WHERE code_sha256 = p_code_sha256 AND consumed_at IS NULL;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.s4_9_mcp_oauth_authorization_codes WHERE code_sha256 = p_code_sha256) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'S4.9 authorization code hash is unavailable' USING ERRCODE = '55000';
  END IF;
END
$_$;


ALTER FUNCTION public.consume_s4_9_mcp_oauth_code_hash(p_code_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.consume_s4_9_validation_and_save_history(p_receipt_sha256 text, p_owner_user_id text, p_oauth_client_id text, p_answer_id text, p_draft_sha256 text, p_kek_version text, p_wrap_nonce bytea, p_wrapped_dek bytea, p_wrap_tag bytea, p_question_nonce bytea, p_question_ciphertext bytea, p_question_tag bytea, p_answer_nonce bytea, p_answer_ciphertext bytea, p_answer_tag bytea, p_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE receipt_row public.s4_9_answer_validation_receipts%ROWTYPE;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_receipt_sha256 !~ '^[0-9a-f]{64}$' OR p_draft_sha256 !~ '^[0-9a-f]{64}$'
     OR p_answer_id !~ '^rag_[A-Za-z0-9_-]{12,96}$'
     OR p_created_at NOT BETWEEN transaction_timestamp() - interval '60 seconds' AND transaction_timestamp() + interval '60 seconds'
     OR p_kek_version !~ '^kek-v[1-9][0-9]{0,8}$' OR octet_length(p_wrap_nonce) <> 12
     OR octet_length(p_wrapped_dek) <> 32 OR octet_length(p_wrap_tag) <> 16
     OR octet_length(p_question_nonce) <> 12 OR octet_length(p_question_ciphertext) NOT BETWEEN 1 AND 8192
     OR octet_length(p_question_tag) <> 16 OR octet_length(p_answer_nonce) <> 12
     OR octet_length(p_answer_ciphertext) NOT BETWEEN 1 AND 8192 OR octet_length(p_answer_tag) <> 16 THEN
    RAISE EXCEPTION 'S4.9 saved history arguments are invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO receipt_row FROM public.s4_9_answer_validation_receipts r
  WHERE r.receipt_sha256 = p_receipt_sha256 AND r.owner_user_id = p_owner_user_id
    AND r.oauth_client_id = p_oauth_client_id AND r.draft_sha256 = p_draft_sha256
    AND r.expires_at > statement_timestamp() AND r.consumed_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'S4.9 validation receipt is unavailable' USING ERRCODE = '55000';
  END IF;
  UPDATE public.s4_9_answer_validation_receipts SET consumed_at = transaction_timestamp()
  WHERE receipt_sha256 = p_receipt_sha256;
  INSERT INTO public.s4_9_saved_answer_history (
    answer_id, owner_user_id, oauth_client_id, receipt_sha256, research_context_id,
    source_set_sha256, validation_status, kek_version, wrap_nonce, wrapped_dek, wrap_tag,
    question_nonce, question_ciphertext, question_tag, answer_nonce, answer_ciphertext, answer_tag,
    created_at, expires_at
  ) VALUES (
    p_answer_id, p_owner_user_id, p_oauth_client_id, p_receipt_sha256, receipt_row.research_context_id,
    receipt_row.source_set_sha256, receipt_row.validation_status, p_kek_version, p_wrap_nonce, p_wrapped_dek, p_wrap_tag,
    p_question_nonce, p_question_ciphertext, p_question_tag, p_answer_nonce, p_answer_ciphertext, p_answer_tag,
    p_created_at, p_created_at + interval '30 days'
  );
END
$_$;


ALTER FUNCTION public.consume_s4_9_validation_and_save_history(p_receipt_sha256 text, p_owner_user_id text, p_oauth_client_id text, p_answer_id text, p_draft_sha256 text, p_kek_version text, p_wrap_nonce bytea, p_wrapped_dek bytea, p_wrap_tag bytea, p_question_nonce bytea, p_question_ciphertext bytea, p_question_tag bytea, p_answer_nonce bytea, p_answer_ciphertext bytea, p_answer_tag bytea, p_created_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.create_async_job(p_job_id text, p_job_type text, p_requested_by text, p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF session_user <> 'decision_app' THEN RAISE EXCEPTION 'async job create role denied' USING ERRCODE='42501'; END IF;
  IF p_job_id !~ '^job_[A-Za-z0-9_-]{8,96}$'
     OR p_job_type NOT IN ('RAG_INDEX','ARTIFACT_INGEST','MODEL_EVAL')
     OR p_requested_by !~ '^usr_[A-Za-z0-9_-]{8,64}$'
     OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>32768
     OR p_payload->>'jobId' IS DISTINCT FROM p_job_id
     OR p_payload->>'ownerRef' IS DISTINCT FROM p_requested_by
     OR EXISTS (SELECT 1 FROM jsonb_each(p_payload) item
                WHERE jsonb_typeof(item.value)<>'string' OR octet_length(item.value#>>'{}')>2048)
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key
                WHERE key NOT IN ('jobId','ownerRef','sourceId','sourceRevisionId','importTicketId','profileId',
                                  'artifactId','runId','contentHash')) THEN
    RAISE EXCEPTION 'invalid async job request' USING ERRCODE='22023';
  END IF;
  IF (p_job_type='RAG_INDEX' AND (
        coalesce(p_payload->>'sourceId','') !~ '^src_[A-Za-z0-9_-]{3,96}$'
        OR coalesce(p_payload->>'sourceRevisionId','') !~ '^srv_[A-Za-z0-9_-]{3,96}$'
        OR coalesce(p_payload->>'importTicketId','') !~ '^rti_[0-9a-f]{32}$'
        OR coalesce(p_payload->>'profileId','') NOT IN ('bge_m3_local_1024_v1','voyage_context_4_1024_v1')
        OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key
                   WHERE key NOT IN ('jobId','ownerRef','sourceId','sourceRevisionId','importTicketId','profileId'))
      ))
     OR (p_job_type='ARTIFACT_INGEST' AND (
        coalesce(p_payload->>'artifactId','') !~ '^artifact_[A-Za-z0-9_-]{8,96}$'
        OR coalesce(p_payload->>'contentHash','') !~ '^sha256:[0-9a-f]{64}$'
        OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key
                   WHERE key NOT IN ('jobId','ownerRef','artifactId','contentHash'))
      ))
     OR (p_job_type='MODEL_EVAL' AND (
        coalesce(p_payload->>'runId','') !~ '^(run|demo)_[A-Za-z0-9_-]{8,96}$'
        OR coalesce(p_payload->>'contentHash','') !~ '^sha256:[0-9a-f]{64}$'
        OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key
                   WHERE key NOT IN ('jobId','ownerRef','runId','contentHash'))
      )) THEN
    RAISE EXCEPTION 'async job schema mismatch' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users actor
                 WHERE actor.user_id=p_requested_by AND actor.status='ACTIVE') THEN RETURN false; END IF;
  INSERT INTO public.async_job(job_id,job_type,status,requested_by,payload_json,next_attempt_at)
  VALUES (p_job_id,p_job_type,'REQUESTED',p_requested_by,p_payload,statement_timestamp());
  RETURN true;
EXCEPTION WHEN unique_violation THEN RETURN false;
END
$_$;


ALTER FUNCTION public.create_async_job(p_job_id text, p_job_type text, p_requested_by text, p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.create_async_request_authorized(p_capability text, p_event_id text, p_event_type text, p_partition_key text, p_job_id text, p_job_type text, p_requested_by text, p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE security_version bigint;
BEGIN
  SELECT actor.security_version INTO security_version FROM public.users actor WHERE actor.user_id=p_requested_by;
  IF NOT FOUND OR NOT public.consume_actor_request_capability(p_capability,p_requested_by,security_version,NULL) THEN
    RAISE EXCEPTION 'async actor capability denied' USING ERRCODE='42501';
  END IF;
  IF NOT public.create_async_job(p_job_id,p_job_type,p_requested_by,p_payload)
     OR NOT public.append_async_request_outbox(p_event_id,p_event_type,p_job_id,p_partition_key,p_payload) THEN
    RAISE EXCEPTION 'async request creation conflict' USING ERRCODE='40001';
  END IF;
  RETURN true;
END
$$;


ALTER FUNCTION public.create_async_request_authorized(p_capability text, p_event_id text, p_event_type text, p_partition_key text, p_job_id text, p_job_type text, p_requested_by text, p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.create_mock_order(requested_payload jsonb, requested_capability_token text) RETURNS TABLE(operation_outcome text, projection_canonical_json text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  requested_actor_user_id text;
  requested_actor_role text;
  requested_security_version bigint;
  requested_request_id text;
  requested_decision_id text;
  requested_order_id text;
  requested_scope_hash text;
  requested_owner_scope_hash text;
  requested_request_hash text;
  requested_account_id text;
  requested_account_scope_hash text;
  requested_symbol text;
  requested_side text;
  requested_order_type text;
  requested_quantity bigint;
  requested_submitted_price bigint;
  requested_result_json text;
  requested_warnings_accepted boolean;
  requested_observed_generation bigint;
  requested_submitted_at timestamptz;
  requested_created_at timestamptz;
  requested_order_event_id text;
  requested_audit_log_id text;
  requested_outbox_event_id text;
  stored_actor record;
  stored_gate record;
  stored_decision record;
  stored_request_hash text;
  stored_result_json text;
  reference_payload jsonb;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  IF requested_payload IS NULL
     OR jsonb_typeof(requested_payload) <> 'object'
     OR NOT requested_payload ?& ARRAY[
       'actorUserId',
       'actorRole',
       'securityVersion',
       'requestId',
       'decisionId',
       'orderId',
       'observedKillSwitchGeneration',
       'idempotencyScopeHash',
       'idempotencyOwnerScopeHash',
       'requestHash',
       'accountId',
       'accountScopeHash',
       'symbol',
       'side',
       'orderType',
       'quantity',
       'submittedPriceKrw',
       'orderIntent',
       'resultCanonicalJson',
       'warningsAccepted',
       'submittedAt',
       'createdAt',
       'orderEventId',
       'auditLogId',
       'outboxEventId'
     ]
     OR requested_payload - ARRAY[
       'actorUserId',
       'actorRole',
       'securityVersion',
       'requestId',
       'decisionId',
       'orderId',
       'observedKillSwitchGeneration',
       'idempotencyScopeHash',
       'idempotencyOwnerScopeHash',
       'requestHash',
       'accountId',
       'accountScopeHash',
       'symbol',
       'side',
       'orderType',
       'quantity',
       'submittedPriceKrw',
       'orderIntent',
       'resultCanonicalJson',
       'warningsAccepted',
       'submittedAt',
       'createdAt',
       'orderEventId',
       'auditLogId',
       'outboxEventId'
     ] <> '{}'::jsonb THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;

  requested_actor_user_id := requested_payload ->> 'actorUserId';
  requested_actor_role := requested_payload ->> 'actorRole';
  requested_security_version := (requested_payload ->> 'securityVersion')::bigint;
  requested_request_id := requested_payload ->> 'requestId';
  requested_decision_id := requested_payload ->> 'decisionId';
  requested_order_id := requested_payload ->> 'orderId';
  requested_observed_generation := (requested_payload ->> 'observedKillSwitchGeneration')::bigint;
  requested_scope_hash := requested_payload ->> 'idempotencyScopeHash';
  requested_owner_scope_hash := requested_payload ->> 'idempotencyOwnerScopeHash';
  requested_request_hash := requested_payload ->> 'requestHash';
  requested_account_id := requested_payload ->> 'accountId';
  requested_account_scope_hash := requested_payload ->> 'accountScopeHash';
  requested_symbol := requested_payload ->> 'symbol';
  requested_side := requested_payload ->> 'side';
  requested_order_type := requested_payload ->> 'orderType';
  requested_quantity := (requested_payload ->> 'quantity')::bigint;
  requested_submitted_price :=
    CASE
      WHEN jsonb_typeof(requested_payload -> 'submittedPriceKrw') = 'null' THEN NULL
      ELSE (requested_payload ->> 'submittedPriceKrw')::bigint
    END;
  requested_result_json := requested_payload ->> 'resultCanonicalJson';
  requested_warnings_accepted := (requested_payload ->> 'warningsAccepted')::boolean;
  requested_submitted_at := (requested_payload ->> 'submittedAt')::timestamptz;
  requested_created_at := (requested_payload ->> 'createdAt')::timestamptz;
  requested_order_event_id := requested_payload ->> 'orderEventId';
  requested_audit_log_id := requested_payload ->> 'auditLogId';
  requested_outbox_event_id := requested_payload ->> 'outboxEventId';

  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id
  FOR SHARE;
  IF NOT FOUND
     OR stored_actor.status <> 'ACTIVE'
     OR stored_actor.role <> requested_actor_role
     OR stored_actor.security_version <> requested_security_version THEN
    RETURN QUERY SELECT 'ACTOR_UNAUTHORIZED'::text, NULL::text;
    RETURN;
  END IF;

  -- direct table 권한이 없는 SECURITY DEFINER 경계 안에서만 Decision FORCE RLS owner를 설정한다.
  PERFORM set_config('app.actor_user_id', requested_actor_user_id, true);

  PERFORM pg_advisory_xact_lock(
    hashtextextended('mock-order:idempotency:' || requested_scope_hash, 3101)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('mock-order:decision:' || requested_decision_id, 3101)
  );

  SELECT gate.active, gate.generation
  INTO stored_gate
  FROM public.risk_kill_switch gate
  WHERE gate.kill_switch_id = 'GLOBAL'
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'BROKERAGE_UNAVAILABLE'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_gate.active
     OR stored_gate.generation <> requested_observed_generation THEN
    RETURN QUERY SELECT 'RISK_BLOCKED'::text, NULL::text;
    RETURN;
  END IF;

  SELECT stored.request_hash, stored.result_canonical_json
  INTO stored_request_hash, stored_result_json
  FROM public.orders stored
  WHERE stored.idempotency_scope_hash = requested_scope_hash
    AND stored.idempotency_owner_scope_hash = requested_owner_scope_hash
  LIMIT 1;
  IF FOUND THEN
    IF stored_request_hash = requested_request_hash THEN
      RETURN QUERY SELECT 'REPLAY'::text, stored_result_json;
    ELSE
      RETURN QUERY SELECT 'IDEMPOTENCY_CONFLICT'::text, NULL::text;
    END IF;
    RETURN;
  END IF;

  SELECT
    decision.evaluation_id,
    decision.portfolio_source,
    decision.outcome,
    decision.can_submit_order,
    decision.enforcement_action,
    decision.valid_until,
    artifact.snapshot_artifact_canonical_json,
    artifact.snapshot_artifact_canonical_json::jsonb #>> '{portfolio,ownerScopeHash}' AS owner_scope_hash,
    EXISTS (
      SELECT 1
      FROM public.decision_invalidations invalidation
      WHERE invalidation.decision_id = decision.decision_id
    ) AS invalidated,
    EXISTS (
      SELECT 1
      FROM public.orders consumed
      WHERE consumed.decision_id = decision.decision_id
    ) AS consumed
  INTO stored_decision
  FROM public.decisions decision
  JOIN public.decision_artifacts artifact
    ON artifact.decision_id = decision.decision_id
   AND artifact.evaluation_id = decision.evaluation_id
  WHERE decision.user_id = requested_actor_user_id
    AND decision.decision_id = requested_decision_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'DECISION_NOT_FOUND'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_decision.invalidated
     OR NOT stored_decision.can_submit_order
     OR stored_decision.outcome NOT IN ('ALLOW', 'WARN')
     OR (
       stored_decision.enforcement_action <> 'NONE'
       AND NOT requested_warnings_accepted
     ) THEN
    RETURN QUERY SELECT 'RISK_BLOCKED'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_decision.consumed THEN
    RETURN QUERY SELECT 'DECISION_CONFLICT'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_decision.portfolio_source <> 'KIS_MOCK'
     OR stored_decision.owner_scope_hash <> requested_account_scope_hash
     OR requested_account_id <> 'acct_' || left(requested_account_scope_hash, 32)
     OR stored_decision.snapshot_artifact_canonical_json::jsonb -> 'orderIntent'
       <> requested_payload -> 'orderIntent' THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;
  -- app service clock은 요청 metadata일 뿐이다. 주문 소비 직전 DB live clock으로 expiry를 최종 판정한다.
  IF NOT stored_decision.valid_until > pg_catalog.clock_timestamp() THEN
    RETURN QUERY SELECT 'DECISION_EXPIRED'::text, NULL::text;
    RETURN;
  END IF;

  INSERT INTO public.orders (
    order_id, user_id, account_id, account_scope_hash, decision_id,
    decision_evaluation_id, brokerage_mode, idempotency_scope_hash,
    idempotency_owner_scope_hash, request_hash, symbol, side, order_type,
    quantity, submitted_price_krw, status, order_intent_json,
    result_canonical_json, acknowledged_by, acknowledged_at, submitted_at,
    created_at, updated_at
  )
  VALUES (
    requested_order_id, requested_actor_user_id, requested_account_id,
    requested_account_scope_hash, requested_decision_id,
    stored_decision.evaluation_id, 'KIS_MOCK', requested_scope_hash,
    requested_owner_scope_hash, requested_request_hash, requested_symbol,
    requested_side, requested_order_type, requested_quantity,
    requested_submitted_price, 'SUBMITTED', requested_payload -> 'orderIntent',
    requested_result_json, requested_actor_user_id, requested_created_at,
    requested_submitted_at, requested_created_at, requested_created_at
  );

  INSERT INTO public.order_events (
    order_event_id, order_id, event_type, event_status, payload_json,
    created_at, event_seq
  )
  VALUES (
    requested_order_event_id, requested_order_id, 'MOCK_ORDER_SUBMITTED',
    'SUBMITTED',
    jsonb_build_object(
      'orderId', requested_order_id,
      'brokerageMode', 'KIS_MOCK',
      'status', 'SUBMITTED'
    ),
    requested_created_at,
    1
  );

  reference_payload :=
    jsonb_build_object(
      'orderId', requested_order_id,
      'decisionId', requested_decision_id,
      'evaluationId', stored_decision.evaluation_id,
      'brokerageMode', 'KIS_MOCK',
      'status', 'SUBMITTED',
      'idempotencyScopeHash', requested_scope_hash
    );
  INSERT INTO public.audit_logs (
    audit_log_id, user_id, actor_role, action, target_type, target_id,
    request_id, payload_json, created_at
  )
  VALUES (
    requested_audit_log_id, requested_actor_user_id, requested_actor_role,
    'MOCK_ORDER_SUBMITTED', 'ORDER', requested_order_id,
    requested_request_id, reference_payload, requested_created_at
  );
  INSERT INTO public.event_outbox (
    event_id, event_type, aggregate_type, aggregate_id, partition_key,
    payload_json, schema_version, status, retry_count, created_at, updated_at
  )
  VALUES (
    requested_outbox_event_id, 'brokerage.mock-order-submitted.v1', 'ORDER',
    requested_order_id, requested_order_id, reference_payload, '1.0.0',
    'PENDING', 0, requested_created_at, requested_created_at
  );

  RETURN QUERY SELECT 'CREATED'::text, requested_result_json;
EXCEPTION
  WHEN unique_violation THEN
    RETURN QUERY SELECT 'DECISION_CONFLICT'::text, NULL::text;
END
$$;


ALTER FUNCTION public.create_mock_order(requested_payload jsonb, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.create_paper_order(requested_payload jsonb, requested_capability_token text) RETURNS TABLE(operation_outcome text, projection_canonical_json text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  requested_actor_user_id text;
  requested_actor_role text;
  requested_security_version bigint;
  requested_request_id text;
  requested_decision_id text;
  requested_order_id text;
  requested_scope_hash text;
  requested_owner_scope_hash text;
  requested_request_hash text;
  requested_account_id text;
  requested_account_scope_hash text;
  requested_quote_observation_id text;
  requested_symbol text;
  requested_side text;
  requested_order_type text;
  requested_quantity bigint;
  requested_submitted_price bigint;
  requested_result_json text;
  requested_warnings_accepted boolean;
  requested_observed_generation bigint;
  requested_status text;
  requested_fill_price bigint;
  requested_fill_amount bigint;
  requested_price_basis text;
  requested_slippage_bps integer;
  requested_fee_model text;
  requested_quote_observed_at timestamptz;
  requested_price_max_age_seconds integer;
  requested_submitted_at timestamptz;
  requested_created_at timestamptz;
  requested_order_event_id text;
  requested_paper_event_id text;
  requested_audit_log_id text;
  requested_outbox_event_id text;
  stored_actor record;
  stored_gate record;
  stored_decision record;
  stored_account record;
  stored_position record;
  stored_quote record;
  stored_request_hash text;
  stored_result_json text;
  base_price bigint;
  computed_fill_price numeric;
  computed_fill_amount numeric;
  before_cash bigint;
  after_cash bigint;
  before_quantity bigint;
  after_quantity bigint;
  before_average_price bigint;
  after_average_price bigint;
  before_market_value bigint;
  after_market_value bigint;
  next_paper_event_seq integer;
  order_event_type text;
  reference_payload jsonb;
  ledger_payload jsonb;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  IF requested_payload IS NULL
     OR jsonb_typeof(requested_payload) <> 'object'
     OR NOT requested_payload ?& ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'requestId',
       'decisionId', 'orderId', 'observedKillSwitchGeneration',
       'idempotencyScopeHash', 'idempotencyOwnerScopeHash', 'requestHash',
       'accountId', 'accountScopeHash', 'quoteObservationId', 'symbol',
       'side', 'orderType', 'quantity', 'submittedPriceKrw', 'orderIntent',
       'resultCanonicalJson', 'warningsAccepted', 'status', 'fillPriceKrw',
       'fillAmountKrw', 'priceBasis', 'slippageBps', 'feeModel',
       'quoteObservedAt', 'priceMaxAgeSeconds', 'submittedAt', 'createdAt',
       'orderEventId', 'paperEventId', 'auditLogId', 'outboxEventId'
     ]
     OR requested_payload - ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'requestId',
       'decisionId', 'orderId', 'observedKillSwitchGeneration',
       'idempotencyScopeHash', 'idempotencyOwnerScopeHash', 'requestHash',
       'accountId', 'accountScopeHash', 'quoteObservationId', 'symbol',
       'side', 'orderType', 'quantity', 'submittedPriceKrw', 'orderIntent',
       'resultCanonicalJson', 'warningsAccepted', 'status', 'fillPriceKrw',
       'fillAmountKrw', 'priceBasis', 'slippageBps', 'feeModel',
       'quoteObservedAt', 'priceMaxAgeSeconds', 'submittedAt', 'createdAt',
       'orderEventId', 'paperEventId', 'auditLogId', 'outboxEventId'
     ] <> '{}'::jsonb THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;

  BEGIN
    requested_actor_user_id := requested_payload ->> 'actorUserId';
    requested_actor_role := requested_payload ->> 'actorRole';
    requested_security_version := (requested_payload ->> 'securityVersion')::bigint;
    requested_request_id := requested_payload ->> 'requestId';
    requested_decision_id := requested_payload ->> 'decisionId';
    requested_order_id := requested_payload ->> 'orderId';
    requested_observed_generation := (requested_payload ->> 'observedKillSwitchGeneration')::bigint;
    requested_scope_hash := requested_payload ->> 'idempotencyScopeHash';
    requested_owner_scope_hash := requested_payload ->> 'idempotencyOwnerScopeHash';
    requested_request_hash := requested_payload ->> 'requestHash';
    requested_account_id := requested_payload ->> 'accountId';
    requested_account_scope_hash := requested_payload ->> 'accountScopeHash';
    requested_quote_observation_id := requested_payload ->> 'quoteObservationId';
    requested_symbol := requested_payload ->> 'symbol';
    requested_side := requested_payload ->> 'side';
    requested_order_type := requested_payload ->> 'orderType';
    requested_quantity := (requested_payload ->> 'quantity')::bigint;
    requested_submitted_price :=
      CASE WHEN jsonb_typeof(requested_payload -> 'submittedPriceKrw') = 'null'
        THEN NULL ELSE (requested_payload ->> 'submittedPriceKrw')::bigint END;
    requested_result_json := requested_payload ->> 'resultCanonicalJson';
    requested_warnings_accepted := (requested_payload ->> 'warningsAccepted')::boolean;
    requested_status := requested_payload ->> 'status';
    requested_fill_price :=
      CASE WHEN jsonb_typeof(requested_payload -> 'fillPriceKrw') = 'null'
        THEN NULL ELSE (requested_payload ->> 'fillPriceKrw')::bigint END;
    requested_fill_amount :=
      CASE WHEN jsonb_typeof(requested_payload -> 'fillAmountKrw') = 'null'
        THEN NULL ELSE (requested_payload ->> 'fillAmountKrw')::bigint END;
    requested_price_basis :=
      CASE WHEN jsonb_typeof(requested_payload -> 'priceBasis') = 'null'
        THEN NULL ELSE requested_payload ->> 'priceBasis' END;
    requested_slippage_bps := (requested_payload ->> 'slippageBps')::integer;
    requested_fee_model :=
      CASE WHEN jsonb_typeof(requested_payload -> 'feeModel') = 'null'
        THEN NULL ELSE requested_payload ->> 'feeModel' END;
    requested_quote_observed_at := (requested_payload ->> 'quoteObservedAt')::timestamptz;
    requested_price_max_age_seconds := (requested_payload ->> 'priceMaxAgeSeconds')::integer;
    requested_submitted_at := (requested_payload ->> 'submittedAt')::timestamptz;
    requested_created_at := (requested_payload ->> 'createdAt')::timestamptz;
    requested_order_event_id := requested_payload ->> 'orderEventId';
    requested_paper_event_id :=
      CASE WHEN jsonb_typeof(requested_payload -> 'paperEventId') = 'null'
        THEN NULL ELSE requested_payload ->> 'paperEventId' END;
    requested_audit_log_id := requested_payload ->> 'auditLogId';
    requested_outbox_event_id := requested_payload ->> 'outboxEventId';
  EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN
      RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
      RETURN;
  END;

  IF requested_order_id !~ '^ord_paper_[0-9a-f]{32}$'
     OR requested_scope_hash !~ '^[0-9a-f]{64}$'
     OR requested_owner_scope_hash !~ '^[0-9a-f]{64}$'
     OR requested_request_hash !~ '^[0-9a-f]{64}$'
     OR requested_account_id !~ '^acct_[0-9a-f]{32}$'
     OR requested_account_scope_hash !~ '^[0-9a-f]{64}$'
     OR requested_side NOT IN ('BUY', 'SELL')
     OR requested_order_type NOT IN ('MARKET', 'LIMIT')
     OR requested_quantity <= 0
     OR requested_status NOT IN ('ACCEPTED', 'FILLED')
     OR requested_price_max_age_seconds NOT BETWEEN 1 AND 300
     OR jsonb_typeof(requested_payload -> 'orderIntent') <> 'object'
     OR jsonb_typeof(requested_result_json::jsonb) <> 'object' THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;

  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id
  FOR SHARE;
  IF NOT FOUND
     OR stored_actor.status <> 'ACTIVE'
     OR stored_actor.role <> requested_actor_role
     OR stored_actor.security_version <> requested_security_version THEN
    RETURN QUERY SELECT 'ACTOR_UNAUTHORIZED'::text, NULL::text;
    RETURN;
  END IF;

  PERFORM set_config('app.actor_user_id', requested_actor_user_id, true);
  PERFORM pg_advisory_xact_lock(
    hashtextextended('paper-order:idempotency:' || requested_scope_hash, 3201)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('paper-order:decision:' || requested_decision_id, 3201)
  );

  SELECT gate.active, gate.generation
  INTO stored_gate
  FROM public.risk_kill_switch gate
  WHERE gate.kill_switch_id = 'GLOBAL'
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'BROKERAGE_UNAVAILABLE'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_gate.active OR stored_gate.generation <> requested_observed_generation THEN
    RETURN QUERY SELECT 'RISK_BLOCKED'::text, NULL::text;
    RETURN;
  END IF;

  SELECT stored.request_hash, stored.result_canonical_json
  INTO stored_request_hash, stored_result_json
  FROM public.orders stored
  WHERE stored.idempotency_scope_hash = requested_scope_hash
    AND stored.idempotency_owner_scope_hash = requested_owner_scope_hash
  LIMIT 1;
  IF FOUND THEN
    IF stored_request_hash = requested_request_hash THEN
      RETURN QUERY SELECT 'REPLAY'::text, stored_result_json;
    ELSE
      RETURN QUERY SELECT 'IDEMPOTENCY_CONFLICT'::text, NULL::text;
    END IF;
    RETURN;
  END IF;

  SELECT
    decision.evaluation_id,
    decision.portfolio_source,
    decision.outcome,
    decision.can_submit_order,
    decision.enforcement_action,
    decision.valid_until,
    artifact.snapshot_artifact_canonical_json,
    artifact.snapshot_artifact_canonical_json::jsonb #>> '{portfolio,ownerScopeHash}' AS owner_scope_hash,
    EXISTS (
      SELECT 1
      FROM public.decision_invalidations invalidation
      WHERE invalidation.decision_id = decision.decision_id
    ) AS invalidated,
    EXISTS (
      SELECT 1
      FROM public.orders consumed
      WHERE consumed.decision_id = decision.decision_id
    ) AS consumed
  INTO stored_decision
  FROM public.decisions decision
  JOIN public.decision_artifacts artifact
    ON artifact.decision_id = decision.decision_id
   AND artifact.evaluation_id = decision.evaluation_id
  WHERE decision.user_id = requested_actor_user_id
    AND decision.decision_id = requested_decision_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'DECISION_NOT_FOUND'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_decision.invalidated
     OR NOT stored_decision.can_submit_order
     OR stored_decision.outcome NOT IN ('ALLOW', 'WARN')
     OR (
       stored_decision.enforcement_action <> 'NONE'
       AND NOT requested_warnings_accepted
     ) THEN
    RETURN QUERY SELECT 'RISK_BLOCKED'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_decision.consumed THEN
    RETURN QUERY SELECT 'DECISION_CONFLICT'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_decision.portfolio_source <> 'INTERNAL_PAPER'
     OR stored_decision.owner_scope_hash <> requested_account_scope_hash
     OR stored_decision.snapshot_artifact_canonical_json::jsonb -> 'orderIntent'
       <> requested_payload -> 'orderIntent' THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;
  IF NOT stored_decision.valid_until > pg_catalog.clock_timestamp() THEN
    RETURN QUERY SELECT 'DECISION_EXPIRED'::text, NULL::text;
    RETURN;
  END IF;

  SELECT
    account.account_id,
    account.user_id,
    account.owner_scope_hash,
    account.status,
    account.cash_balance,
    account.updated_at
  INTO stored_account
  FROM public.paper_accounts account
  WHERE account.account_id = requested_account_id
    AND account.user_id = requested_actor_user_id
    AND account.owner_scope_hash = requested_account_scope_hash
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'DECISION_NOT_FOUND'::text, NULL::text;
    RETURN;
  END IF;
  IF stored_account.status <> 'ACTIVE' THEN
    RETURN QUERY SELECT 'BROKERAGE_UNAVAILABLE'::text, NULL::text;
    RETURN;
  END IF;

  SELECT
    quote.observation_id,
    quote.symbol,
    quote.price_krw,
    quote.previous_close_krw,
    quote.completeness,
    quote.observed_at
  INTO stored_quote
  FROM public.market_quote_observations quote
  WHERE quote.observation_id = requested_quote_observation_id
    AND quote.symbol = requested_symbol
    AND quote.source = 'KIS_MOCK';
  IF NOT FOUND
     OR stored_quote.completeness <> 'COMPLETE'
     OR stored_quote.observed_at <> requested_quote_observed_at THEN
    RETURN QUERY SELECT 'BROKERAGE_UNAVAILABLE'::text, NULL::text;
    RETURN;
  END IF;
  IF requested_created_at > stored_quote.observed_at
       + make_interval(secs => requested_price_max_age_seconds)
     OR stored_quote.observed_at > requested_created_at THEN
    RETURN QUERY SELECT 'DATA_STALE'::text, NULL::text;
    RETURN;
  END IF;

  IF stored_quote.price_krw IS NOT NULL THEN
    base_price := stored_quote.price_krw;
    IF requested_price_basis <> 'LAST_QUOTE' THEN
      RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
      RETURN;
    END IF;
  ELSIF stored_quote.previous_close_krw IS NOT NULL THEN
    base_price := stored_quote.previous_close_krw;
    IF requested_price_basis <> 'PREVIOUS_CLOSE' THEN
      RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
      RETURN;
    END IF;
  ELSE
    RETURN QUERY SELECT 'BROKERAGE_UNAVAILABLE'::text, NULL::text;
    RETURN;
  END IF;

  IF requested_status = 'ACCEPTED' THEN
    IF requested_order_type <> 'LIMIT'
       OR requested_fill_price IS NOT NULL
       OR requested_fill_amount IS NOT NULL
       OR requested_slippage_bps <> 0
       OR requested_fee_model IS NOT NULL
       OR requested_paper_event_id IS NOT NULL
       OR (
         requested_side = 'BUY'
         AND base_price <= requested_submitted_price
       )
       OR (
         requested_side = 'SELL'
         AND base_price >= requested_submitted_price
       ) THEN
      RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
      RETURN;
    END IF;
  ELSE
    IF requested_fill_price IS NULL
       OR requested_fill_amount IS NULL
       OR requested_paper_event_id IS NULL
       OR requested_fee_model <> 'NONE_V1' THEN
      RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
      RETURN;
    END IF;
    IF requested_order_type = 'MARKET' THEN
      IF requested_slippage_bps NOT BETWEEN 0 AND 100 THEN
        RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
        RETURN;
      END IF;
      IF requested_side = 'BUY' THEN
        computed_fill_price :=
          ceil((base_price::numeric * (10000 + requested_slippage_bps)) / 10000);
      ELSE
        computed_fill_price :=
          floor((base_price::numeric * (10000 - requested_slippage_bps)) / 10000);
      END IF;
    ELSE
      IF requested_slippage_bps <> 0
         OR requested_submitted_price IS NULL
         OR (
           requested_side = 'BUY'
           AND base_price > requested_submitted_price
         )
         OR (
           requested_side = 'SELL'
           AND base_price < requested_submitted_price
         ) THEN
        RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
        RETURN;
      END IF;
      computed_fill_price :=
        CASE
          WHEN requested_side = 'BUY'
            THEN least(base_price, requested_submitted_price)
          ELSE greatest(base_price, requested_submitted_price)
        END;
    END IF;
    IF computed_fill_price <= 0 THEN
      RETURN QUERY SELECT 'BROKERAGE_UNAVAILABLE'::text, NULL::text;
      RETURN;
    END IF;
    computed_fill_amount := requested_quantity::numeric * computed_fill_price;
    IF computed_fill_price > 9223372036854775807
       OR computed_fill_amount > 9223372036854775807
       OR requested_fill_price <> computed_fill_price::bigint
       OR requested_fill_amount <> computed_fill_amount::bigint THEN
      RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
      RETURN;
    END IF;
  END IF;

  -- canonical response도 DB가 다시 계산한 mode/status/fill과 일치해야 replay가 신뢰 가능하다.
  IF requested_result_json::jsonb ->> 'orderId' <> requested_order_id
     OR requested_result_json::jsonb ->> 'accountId' <> requested_account_id
     OR requested_result_json::jsonb ->> 'brokerageMode' <> 'INTERNAL_PAPER'
     OR requested_result_json::jsonb ->> 'status' <> requested_status THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;

  IF requested_status = 'FILLED' THEN
    SELECT
      position.position_id,
      position.quantity,
      position.average_price,
      position.market_value
    INTO stored_position
    FROM public.paper_positions position
    WHERE position.account_id = requested_account_id
      AND position.symbol = requested_symbol
    FOR UPDATE;
    before_cash := stored_account.cash_balance;
    before_quantity := COALESCE(stored_position.quantity, 0);
    before_average_price := COALESCE(stored_position.average_price, 0);
    before_market_value := COALESCE(stored_position.market_value, 0);
    IF requested_side = 'BUY' THEN
      IF before_cash < requested_fill_amount THEN
        RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
        RETURN;
      END IF;
      after_cash := before_cash - requested_fill_amount;
      after_quantity := before_quantity + requested_quantity;
      IF after_quantity < before_quantity THEN
        RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
        RETURN;
      END IF;
      computed_fill_amount :=
        before_quantity::numeric * before_average_price
        + requested_quantity::numeric * requested_fill_price;
      IF computed_fill_amount > 9223372036854775807 THEN
        RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
        RETURN;
      END IF;
      after_average_price := floor(computed_fill_amount / after_quantity)::bigint;
    ELSE
      IF before_quantity < requested_quantity THEN
        RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
        RETURN;
      END IF;
      IF before_cash::numeric + requested_fill_amount > 9223372036854775807 THEN
        RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
        RETURN;
      END IF;
      after_cash := before_cash + requested_fill_amount;
      after_quantity := before_quantity - requested_quantity;
      after_average_price :=
        CASE WHEN after_quantity = 0 THEN 0 ELSE before_average_price END;
    END IF;
    computed_fill_amount := after_quantity::numeric * requested_fill_price;
    IF computed_fill_amount > 9223372036854775807 THEN
      RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
      RETURN;
    END IF;
    after_market_value := computed_fill_amount::bigint;

    UPDATE public.paper_accounts
    SET cash_balance = after_cash,
        updated_at = requested_created_at
    WHERE account_id = requested_account_id;
    IF stored_position.position_id IS NULL THEN
      INSERT INTO public.paper_positions (
        position_id, account_id, symbol, quantity, average_price,
        market_value, updated_at
      )
      VALUES (
        'ppos_' || substr(encode(sha256(convert_to(
          requested_account_id || ':' || requested_symbol, 'UTF8'
        )), 'hex'), 1, 32),
        requested_account_id,
        requested_symbol,
        after_quantity,
        after_average_price,
        after_market_value,
        requested_created_at
      );
    ELSE
      UPDATE public.paper_positions
      SET quantity = after_quantity,
          average_price = after_average_price,
          market_value = after_market_value,
          updated_at = requested_created_at
      WHERE position_id = stored_position.position_id;
    END IF;
  END IF;

  INSERT INTO public.orders (
    order_id, user_id, account_id, account_scope_hash, decision_id,
    decision_evaluation_id, brokerage_mode, idempotency_scope_hash,
    idempotency_owner_scope_hash, request_hash, symbol, side, order_type,
    quantity, submitted_price_krw, status, order_intent_json,
    result_canonical_json, acknowledged_by, acknowledged_at, submitted_at,
    created_at, updated_at
  )
  VALUES (
    requested_order_id, requested_actor_user_id, requested_account_id,
    requested_account_scope_hash, requested_decision_id,
    stored_decision.evaluation_id, 'INTERNAL_PAPER', requested_scope_hash,
    requested_owner_scope_hash, requested_request_hash, requested_symbol,
    requested_side, requested_order_type, requested_quantity,
    requested_submitted_price, requested_status, requested_payload -> 'orderIntent',
    requested_result_json, requested_actor_user_id, requested_created_at,
    requested_submitted_at, requested_created_at, requested_created_at
  );

  order_event_type :=
    CASE WHEN requested_status = 'FILLED'
      THEN 'PAPER_ORDER_FILLED' ELSE 'PAPER_ORDER_ACCEPTED' END;
  INSERT INTO public.order_events (
    order_event_id, order_id, event_type, event_status, payload_json,
    created_at, event_seq
  )
  VALUES (
    requested_order_event_id,
    requested_order_id,
    order_event_type,
    requested_status,
    jsonb_build_object(
      'orderId', requested_order_id,
      'brokerageMode', 'INTERNAL_PAPER',
      'status', requested_status
    ),
    requested_created_at,
    1
  );

  IF requested_status = 'FILLED' THEN
    SELECT COALESCE(max(event.event_seq), 0) + 1
    INTO next_paper_event_seq
    FROM public.paper_order_events event
    WHERE event.account_id = requested_account_id;
    ledger_payload :=
      jsonb_build_object(
        'orderId', requested_order_id,
        'symbol', requested_symbol,
        'side', requested_side,
        'fillQuantity', requested_quantity,
        'fillPriceKrw', requested_fill_price,
        'fillAmountKrw', requested_fill_amount,
        'priceBasis', requested_price_basis,
        'slippageBps', requested_slippage_bps,
        'feeModel', requested_fee_model,
        'observedAt', requested_quote_observed_at::text,
        'beforeCashKrw', before_cash,
        'afterCashKrw', after_cash,
        'beforeQuantity', before_quantity,
        'afterQuantity', after_quantity,
        'beforeAveragePriceKrw', before_average_price,
        'afterAveragePriceKrw', after_average_price,
        'beforeMarketValueKrw', before_market_value,
        'afterMarketValueKrw', after_market_value
      );
    INSERT INTO public.paper_order_events (
      paper_order_event_id, account_id, order_id, event_type, payload_json,
      created_at, event_seq
    )
    VALUES (
      requested_paper_event_id, requested_account_id, requested_order_id,
      'PAPER_ORDER_FILLED', ledger_payload, requested_created_at,
      next_paper_event_seq
    );
    reference_payload :=
      jsonb_build_object(
        'orderId', requested_order_id,
        'decisionId', requested_decision_id,
        'evaluationId', stored_decision.evaluation_id,
        'brokerageMode', 'INTERNAL_PAPER',
        'status', 'FILLED',
        'idempotencyScopeHash', requested_scope_hash,
        'fillPriceKrw', requested_fill_price,
        'fillQuantity', requested_quantity,
        'priceBasis', requested_price_basis,
        'slippageBps', requested_slippage_bps,
        'feeModel', requested_fee_model
      );
  ELSE
    reference_payload :=
      jsonb_build_object(
        'orderId', requested_order_id,
        'decisionId', requested_decision_id,
        'evaluationId', stored_decision.evaluation_id,
        'brokerageMode', 'INTERNAL_PAPER',
        'status', 'ACCEPTED',
        'idempotencyScopeHash', requested_scope_hash
      );
  END IF;

  INSERT INTO public.audit_logs (
    audit_log_id, user_id, actor_role, action, target_type, target_id,
    request_id, payload_json, created_at
  )
  VALUES (
    requested_audit_log_id, requested_actor_user_id, requested_actor_role,
    CASE WHEN requested_status = 'FILLED'
      THEN 'PAPER_ORDER_FILLED' ELSE 'PAPER_ORDER_ACCEPTED' END,
    'ORDER', requested_order_id, requested_request_id, reference_payload,
    requested_created_at
  );
  INSERT INTO public.event_outbox (
    event_id, event_type, aggregate_type, aggregate_id, partition_key,
    payload_json, schema_version, status, retry_count, created_at, updated_at
  )
  VALUES (
    requested_outbox_event_id,
    CASE WHEN requested_status = 'FILLED'
      THEN 'brokerage.paper-order-filled.v1'
      ELSE 'brokerage.paper-order-accepted.v1' END,
    'ORDER', requested_order_id, requested_order_id, reference_payload,
    '1.0.0', 'PENDING', 0, requested_created_at, requested_created_at
  );
  RETURN QUERY SELECT 'CREATED'::text, requested_result_json;
EXCEPTION
  WHEN unique_violation THEN
    RETURN QUERY SELECT 'DECISION_CONFLICT'::text, NULL::text;
END
$_$;


ALTER FUNCTION public.create_paper_order(requested_payload jsonb, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.create_rag_retrieval_scope_claim(p_owner_user_id text, p_session_id text, p_allowed_topics text[]) RETURNS TABLE(scope_claim_id text, owner_user_id text, session_id text, allowed_topics text[], active_generation_id text, effective_profile_id text, policy_version bigint, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  generated_claim_id text;
  selected_generation_id text;
  selected_profile_id text;
  selected_policy_version bigint;
  selected_expiry timestamptz;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR p_owner_user_id IS NULL
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$'
     OR p_allowed_topics IS NULL
     OR cardinality(p_allowed_topics) NOT BETWEEN 1 AND 6
     OR cardinality(ARRAY(SELECT DISTINCT unnest(p_allowed_topics)))
        <> cardinality(p_allowed_topics)
     OR NOT (
       p_allowed_topics <@ ARRAY[
         'API',
         'DATA',
         'FINANCIAL_ENGINEERING',
         'METHODOLOGY',
         'PRODUCT_RISK',
         'RISK'
       ]::text[]
     )
     OR NOT EXISTS (
       SELECT 1
       FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'RAG retrieval scope claim arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    state.active_generation_id,
    state.effective_profile_id,
    state.version
  INTO
    selected_generation_id,
    selected_profile_id,
    selected_policy_version
  FROM public.rag_embedding_policy_state AS state
  JOIN public.rag_corpus_generations AS generation
    ON generation.corpus_generation_id = state.active_generation_id
   AND generation.embedding_profile_id = state.effective_profile_id
   AND generation.status = 'ACTIVE'
   AND generation.evaluation_status = 'PASSED'
  WHERE state.state_id = 'default'
  FOR SHARE OF state, generation;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG retrieval has no active verified generation'
      USING ERRCODE = '55000';
  END IF;

  generated_claim_id :=
    'rag_scope_' ||
    substr(
      encode(
        digest(
          gen_random_bytes(32) ||
          convert_to(
            concat_ws(
              E'\n',
              p_owner_user_id,
              p_session_id,
              selected_generation_id,
              selected_profile_id,
              selected_policy_version::text,
              clock_timestamp()::text
            ),
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ),
      1,
      32
    );
  selected_expiry := transaction_timestamp() + interval '2 minutes';

  INSERT INTO public.rag_retrieval_scope_claims (
    scope_claim_id,
    owner_user_id,
    session_id,
    allowed_topics,
    active_generation_id,
    effective_profile_id,
    policy_version,
    expires_at
  )
  VALUES (
    generated_claim_id,
    p_owner_user_id,
    p_session_id,
    ARRAY(
      SELECT topic
      FROM unnest(p_allowed_topics) AS topic
      ORDER BY convert_to(topic, 'UTF8')
    ),
    selected_generation_id,
    selected_profile_id,
    selected_policy_version,
    selected_expiry
  );

  RETURN QUERY
  SELECT
    generated_claim_id,
    p_owner_user_id,
    p_session_id,
    ARRAY(
      SELECT topic
      FROM unnest(p_allowed_topics) AS topic
      ORDER BY convert_to(topic, 'UTF8')
    ),
    selected_generation_id,
    selected_profile_id,
    selected_policy_version,
    selected_expiry;
END
$_$;


ALTER FUNCTION public.create_rag_retrieval_scope_claim(p_owner_user_id text, p_session_id text, p_allowed_topics text[]) OWNER TO flyway;


CREATE FUNCTION public.cross_market_fixture_payload_keys_are_allowed(p_value jsonb, p_key_profile jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  record_key text;
  nested_profile jsonb;
BEGIN
  IF jsonb_typeof(p_value) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_key_profile) IS DISTINCT FROM 'object' THEN
    RETURN false;
  END IF;

  FOR record_key IN SELECT jsonb_object_keys(p_value)
  LOOP
    nested_profile := p_key_profile -> record_key;
    IF nested_profile IS NULL THEN
      RETURN false;
    END IF;
    IF jsonb_typeof(nested_profile) = 'object'
       AND NOT public.cross_market_fixture_payload_keys_are_allowed(
         p_value -> record_key,
         nested_profile
       ) THEN
      RETURN false;
    END IF;
    IF jsonb_typeof(nested_profile) <> 'object'
       AND NOT public.cross_market_fixture_value_is_safe(p_value -> record_key) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END
$$;


ALTER FUNCTION public.cross_market_fixture_payload_keys_are_allowed(p_value jsonb, p_key_profile jsonb) OWNER TO flyway;


CREATE FUNCTION public.cross_market_fixture_value_is_safe(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  WITH RECURSIVE nested_value(value) AS (
    SELECT p_value
    UNION ALL
    SELECT child.value
    FROM nested_value AS parent
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(parent.value) = 'array' THEN parent.value
        ELSE '[]'::jsonb
      END
    ) AS child(value)
  )
  SELECT NOT EXISTS (
    SELECT 1
    FROM nested_value
    WHERE jsonb_typeof(value) = 'object'
  )
$$;


ALTER FUNCTION public.cross_market_fixture_value_is_safe(p_value jsonb) OWNER TO flyway;


CREATE FUNCTION public.current_market_data_manifest_head(candidate_session_date date) RETURNS TABLE(manifest_sha256 character, session_date date)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT manifests.manifest_sha256, manifests.session_date
    FROM market_data_manifests AS manifests
    WHERE manifests.status = 'ACCEPTED'
      AND manifests.session_date < candidate_session_date
    ORDER BY manifests.session_date DESC,
             manifests.generation DESC,
             manifests.created_at DESC,
             manifests.manifest_sha256 DESC
    LIMIT 1
$$;


ALTER FUNCTION public.current_market_data_manifest_head(candidate_session_date date) OWNER TO flyway;


CREATE FUNCTION public.current_s5_signal_batch_clock() RETURNS TABLE(session_date date, as_of timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT clock.session_date, clock.as_of
  FROM public.s5_signal_batch_clock_at(statement_timestamp()) clock
  WHERE current_user = 'flyway'
    AND session_user IN ('decision_app','decision_signal_admin','decision_signal_scheduler')
$$;


ALTER FUNCTION public.current_s5_signal_batch_clock() OWNER TO flyway;


CREATE FUNCTION public.delete_owned_rag_history(p_owner_user_id text, p_answer_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_answer_id !~ '^rag_ans_[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'RAG history delete arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  DELETE FROM public.rag_answer_history
  WHERE answer_id = p_answer_id
    AND owner_user_id = p_owner_user_id;
END
$_$;


ALTER FUNCTION public.delete_owned_rag_history(p_owner_user_id text, p_answer_id text) OWNER TO flyway;


CREATE FUNCTION public.delete_owned_rag_v2_history(p_owner_user_id text, p_answer_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_answer_id !~ '^rag_[A-Za-z0-9_-]{12,96}$' THEN
    RAISE EXCEPTION 'RAG v2 history delete arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.rag_v2_answer_history AS history
  WHERE history.owner_user_id = p_owner_user_id
    AND history.answer_id = p_answer_id;
END
