ALTER FUNCTION public.delete_owned_rag_v2_history(p_owner_user_id text, p_answer_id text) OWNER TO flyway;


CREATE FUNCTION public.delete_owner_rag_v2_document(p_owner_user_id text, p_document_id text, p_deletion_receipt_id text, p_reason_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  target_generation text;
  deleted_document_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
     OR p_deletion_receipt_id !~ '^rag_v2_del_[0-9a-f]{32}$'
     OR p_reason_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'RAG v2 document delete arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT document.owner_generation_id
  INTO target_generation
  FROM public.rag_v2_owner_documents AS document
  WHERE document.owner_user_id = p_owner_user_id
    AND document.document_id = p_document_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  PERFORM 1
  FROM public.rag_v2_owner_private_generation_pointers AS pointer
  WHERE pointer.owner_user_id = p_owner_user_id
  FOR UPDATE;

  DELETE FROM public.rag_v2_owner_document_embeddings AS embedding
  WHERE embedding.owner_user_id = p_owner_user_id
    AND embedding.chunk_id IN (
      SELECT chunk.chunk_id
      FROM public.rag_v2_owner_document_chunks AS chunk
      WHERE chunk.owner_user_id = p_owner_user_id
        AND chunk.document_id = p_document_id
    );

  DELETE FROM public.rag_v2_owner_document_chunks AS chunk
  WHERE chunk.owner_user_id = p_owner_user_id
    AND chunk.document_id = p_document_id;

  DELETE FROM public.rag_v2_owner_documents AS document
  WHERE document.owner_user_id = p_owner_user_id
    AND document.document_id = p_document_id;
  GET DIAGNOSTICS deleted_document_count = ROW_COUNT;

  INSERT INTO public.rag_v2_document_deletion_receipts (
    deletion_receipt_id,
    owner_user_id,
    document_id,
    deleted_generation_id,
    reason_hash,
    content_hash_was_removed
  )
  VALUES (
    p_deletion_receipt_id,
    p_owner_user_id,
    p_document_id,
    target_generation,
    p_reason_hash,
    true
  );

  UPDATE public.rag_v2_owner_private_generation_pointers AS pointer
  SET private_overlay_state = 'ABSENT',
      active_private_generation_id = NULL,
      progress_percent = 0,
      failure_code = NULL,
      generation_version = pointer.generation_version + 1,
      updated_at = transaction_timestamp()
  WHERE pointer.owner_user_id = p_owner_user_id
    AND pointer.active_private_generation_id IS NOT DISTINCT FROM target_generation;

  RETURN deleted_document_count = 1;
END
$_$;


ALTER FUNCTION public.delete_owner_rag_v2_document(p_owner_user_id text, p_document_id text, p_deletion_receipt_id text, p_reason_hash text) OWNER TO flyway;


CREATE FUNCTION public.delete_rag_v2_immutable_owner_document(p_owner_user_id text, p_document_id text, p_replacement_bundle_id text, p_expected_active_bundle_id text, p_expected_bundle_version bigint, p_activation_receipt_id text, p_deletion_receipt_id text, p_reason_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  target_source_count integer;
  target_chunk_count integer;
  target_embedding_count integer;
  target_run_count integer;
  target_source_revision_ids text[] := ARRAY[]::text[];
  target_chunk_ids text[] := ARRAY[]::text[];
  target_generation_ids text[] := ARRAY[]::text[];
  is_replaced_active boolean;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
     OR p_deletion_receipt_id !~ '^rgr_del_[0-9a-f]{32}$'
     OR p_reason_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 document deletion arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  is_replaced_active := p_replacement_bundle_id IS NOT NULL
    OR p_expected_active_bundle_id IS NOT NULL
    OR p_expected_bundle_version IS NOT NULL
    OR p_activation_receipt_id IS NOT NULL;
  IF is_replaced_active
     AND (
       p_replacement_bundle_id IS NULL
       OR p_expected_active_bundle_id IS NULL
       OR p_expected_bundle_version IS NULL
       OR p_activation_receipt_id IS NULL
       OR p_replacement_bundle_id !~ '^rgb_[0-9a-f]{32}$'
       OR p_expected_active_bundle_id !~ '^rgb_[0-9a-f]{32}$'
       OR p_expected_bundle_version < 1
       OR p_activation_receipt_id !~ '^rgr_act_[0-9a-f]{32}$'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 deletion mode arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- owner document writer가 source/run INSERT 뒤 activation까지 같은 transaction에서 진행해도
  -- deadlock이 나지 않도록 document lock을 먼저, global activation lock을 다음에 잡는다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'rag-v2-immutable-owner-document|' || p_owner_user_id || '|' || p_document_id,
      0
    )
  );
  -- deletion와 public/owner activation은 같은 lock을 공유해 stale pointer와 partial hard-delete를 막는다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-bundle-activation', 0)
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  SELECT
    COUNT(*)::integer,
    coalesce(array_agg(source.source_revision_id ORDER BY source.source_revision_id), ARRAY[]::text[])
  INTO target_source_count, target_source_revision_ids
  FROM public.rag_v2_immutable_source_revisions AS source
  WHERE source.owner_user_id = p_owner_user_id
    AND source.source_scope = 'OWNER_PRIVATE'
    AND source.document_id = p_document_id;
  SELECT COUNT(*)::integer
  INTO target_run_count
  FROM public.rag_v2_immutable_materialization_runs AS run
  WHERE run.owner_user_id = p_owner_user_id
    AND run.component_scope = 'OWNER_PRIVATE'
    AND run.document_id = p_document_id;
  IF target_source_count = 0 THEN
    IF target_run_count = 0 THEN
      RETURN false;
    END IF;
    IF is_replaced_active THEN
      RAISE EXCEPTION 'immutable RAG v2 replacement deletion requires a materialized document'
        USING ERRCODE = '23514';
    END IF;
    -- 첫 source가 아직 없더라도 owner가 삭제를 요청한 run은 재개 불가 상태와 tombstone으로
    -- 닫는다. 그렇지 않으면 stale writer가 첫 source를 뒤늦게 삽입해 document를 되살릴 수 있다.
    UPDATE public.rag_v2_immutable_materialization_runs
    SET component_generation_id = NULL,
        state = CASE WHEN state IN ('OPEN', 'STAGED') THEN 'FAILED' ELSE state END,
        failure_code = CASE WHEN state IN ('OPEN', 'STAGED') THEN 'OWNER_DELETED' ELSE failure_code END,
        completed_at = CASE WHEN state IN ('OPEN', 'STAGED') THEN clock_timestamp() ELSE completed_at END
    WHERE owner_user_id = p_owner_user_id
      AND component_scope = 'OWNER_PRIVATE'
      AND document_id = p_document_id;
    INSERT INTO public.rag_v2_immutable_deletion_receipts (
      deletion_receipt_id,
      owner_user_id,
      document_id,
      deletion_kind,
      replacement_bundle_id,
      activation_receipt_id,
      reason_hash,
      deleted_source_revision_count,
      deleted_chunk_count,
      deleted_embedding_count,
      affected_materialization_run_count
    )
    VALUES (
      p_deletion_receipt_id,
      p_owner_user_id,
      p_document_id,
      'UNMATERIALIZED_RUN',
      NULL,
      NULL,
      p_reason_hash,
      0,
      0,
      0,
      target_run_count
    );
    INSERT INTO public.rag_v2_immutable_owner_document_deletion_tombstones (
      owner_user_id,
      document_id,
      deletion_receipt_id
    )
    VALUES (
      p_owner_user_id,
      p_document_id,
      p_deletion_receipt_id
    );
    RETURN true;
  END IF;

  SELECT
    COUNT(*)::integer,
    coalesce(array_agg(chunk.chunk_id ORDER BY chunk.chunk_id), ARRAY[]::text[])
  INTO target_chunk_count, target_chunk_ids
  FROM public.rag_v2_immutable_chunks AS chunk
  WHERE chunk.owner_user_id = p_owner_user_id
    AND chunk.source_scope = 'OWNER_PRIVATE'
    AND chunk.source_revision_id = ANY(target_source_revision_ids);

  SELECT coalesce(
    array_agg(DISTINCT candidate.component_generation_id)
      FILTER (WHERE candidate.component_generation_id IS NOT NULL),
    ARRAY[]::text[]
  )
  INTO target_generation_ids
  FROM (
    SELECT membership.component_generation_id
    FROM public.rag_v2_immutable_generation_memberships AS membership
    WHERE membership.owner_user_id = p_owner_user_id
      AND membership.component_scope = 'OWNER_PRIVATE'
      AND membership.source_revision_id = ANY(target_source_revision_ids)
    UNION
    SELECT run.component_generation_id
    FROM public.rag_v2_immutable_source_receipts AS receipt
    JOIN public.rag_v2_immutable_materialization_runs AS run
      ON run.materialization_run_id = receipt.materialization_run_id
     AND run.owner_user_id = receipt.owner_user_id
    WHERE receipt.owner_user_id = p_owner_user_id
      AND receipt.source_scope = 'OWNER_PRIVATE'
      AND receipt.source_revision_id = ANY(target_source_revision_ids)
    UNION
    SELECT run.component_generation_id
    FROM public.rag_v2_immutable_chunk_receipts AS receipt
    JOIN public.rag_v2_immutable_materialization_runs AS run
      ON run.materialization_run_id = receipt.materialization_run_id
     AND run.owner_user_id = receipt.owner_user_id
    WHERE receipt.owner_user_id = p_owner_user_id
      AND receipt.source_scope = 'OWNER_PRIVATE'
      AND (
        receipt.source_revision_id = ANY(target_source_revision_ids)
        OR receipt.chunk_id = ANY(target_chunk_ids)
      )
  ) AS candidate;

  IF is_replaced_active AND EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_bundles AS bundle
    JOIN public.rag_v2_immutable_generation_memberships AS membership
      ON membership.component_generation_id = bundle.owner_private_generation_id
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    WHERE bundle.bundle_id = p_replacement_bundle_id
      AND bundle.owner_user_id = p_owner_user_id
      AND source.owner_user_id = p_owner_user_id
      AND source.document_id = p_document_id
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 replacement bundle still contains the deleted document'
      USING ERRCODE = '23514';
  END IF;
  -- deletion은 old component generation 전체를 hard-delete한다. 따라서 replacement는 삭제 대상이
  -- 아닌 기존 membership을 빠짐없이 다시 가리켜야 하며, 한 문서 삭제로 다른 owner 문서가 검색에서
  -- 사라지는 partial replacement를 허용하지 않는다.
  IF is_replaced_active AND EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_generation_memberships AS surviving_membership
    JOIN public.rag_v2_immutable_source_revisions AS surviving_source
      ON surviving_source.source_revision_id = surviving_membership.source_revision_id
    WHERE surviving_membership.component_generation_id = ANY(target_generation_ids)
      AND surviving_membership.owner_user_id = p_owner_user_id
      AND surviving_membership.component_scope = 'OWNER_PRIVATE'
      AND surviving_source.owner_user_id = p_owner_user_id
      AND surviving_source.source_scope = 'OWNER_PRIVATE'
      AND surviving_source.document_id <> p_document_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_bundles AS replacement_bundle
        JOIN public.rag_v2_immutable_generation_memberships AS replacement_membership
          ON replacement_membership.component_generation_id = replacement_bundle.owner_private_generation_id
        WHERE replacement_bundle.bundle_id = p_replacement_bundle_id
          AND replacement_bundle.owner_user_id = p_owner_user_id
          AND replacement_membership.owner_user_id = p_owner_user_id
          AND replacement_membership.component_scope = 'OWNER_PRIVATE'
          AND replacement_membership.source_revision_id = surviving_membership.source_revision_id
          AND replacement_membership.chunk_id = surviving_membership.chunk_id
      )
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 replacement bundle omits a surviving owner document membership'
      USING ERRCODE = '23514';
  END IF;
  IF is_replaced_active THEN
    -- CAS activation succeeds atomically with deletion; any later error rolls the pointer back with the old artifacts intact.
    PERFORM activate_rag_v2_immutable_owner_bundle(
      p_owner_user_id,
      p_replacement_bundle_id,
      p_expected_active_bundle_id,
      p_expected_bundle_version,
      p_activation_receipt_id,
      'OWNER_DELETE_REPLACEMENT'
    );
  ELSIF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_bundles AS bundle
    WHERE bundle.owner_user_id = p_owner_user_id
      AND bundle.owner_private_generation_id = ANY(target_generation_ids)
  )
  OR EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_component_generations AS generation
    WHERE generation.component_generation_id = ANY(target_generation_ids)
      AND (
        generation.owner_user_id IS DISTINCT FROM p_owner_user_id
        OR generation.component_scope <> 'OWNER_PRIVATE'
        OR generation.state NOT IN ('STAGING', 'FAILED')
      )
  )
  OR EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    WHERE membership.component_generation_id = ANY(target_generation_ids)
      AND source.document_id IS DISTINCT FROM p_document_id
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 staged deletion still has a bundle, active generation, or foreign document reference'
      USING ERRCODE = '23514';
  END IF;

  SELECT COUNT(*) INTO target_embedding_count
  FROM public.rag_v2_immutable_generation_embeddings
  WHERE component_generation_id = ANY(target_generation_ids);

  -- replacement pointer activation has completed above. 어느 mode든 active pointer가 삭제 대상
  -- generation을 가리키면 hard-delete 전에 중단해 active evidence를 남기거나 끊지 않는다.
  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_owner_bundle_pointers AS pointer
    JOIN public.rag_v2_immutable_bundles AS bundle
      ON bundle.bundle_id = pointer.active_bundle_id
     AND bundle.owner_user_id = pointer.owner_user_id
    WHERE pointer.owner_user_id = p_owner_user_id
      AND bundle.owner_private_generation_id = ANY(target_generation_ids)
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner pointer still references a deletion target'
      USING ERRCODE = '23514';
  END IF;

  -- replacement mode는 old bundle을, staging mode는 앞의 unreferenced check를 통과한 zero bundle을
  -- 제거한다. 이후 receipt/run은 hash ledger로 남기되 subject identity만 NULL로 scrub한다.
  DELETE FROM public.rag_v2_immutable_bundles
  WHERE owner_user_id = p_owner_user_id
    AND owner_private_generation_id = ANY(target_generation_ids);
  DELETE FROM public.rag_v2_immutable_embedding_cache
  WHERE owner_user_id = p_owner_user_id
    AND source_revision_id = ANY(target_source_revision_ids);
  UPDATE public.rag_v2_immutable_embedding_receipts
  SET component_generation_id = NULL,
      chunk_id = NULL
  WHERE owner_user_id = p_owner_user_id
    AND source_scope = 'OWNER_PRIVATE'
    AND (
      component_generation_id = ANY(target_generation_ids)
      OR chunk_id = ANY(target_chunk_ids)
    );
  UPDATE public.rag_v2_immutable_chunk_receipts
  SET source_revision_id = NULL,
      chunk_id = NULL
  WHERE owner_user_id = p_owner_user_id
    AND source_scope = 'OWNER_PRIVATE'
    AND (
      source_revision_id = ANY(target_source_revision_ids)
      OR chunk_id = ANY(target_chunk_ids)
    );
  UPDATE public.rag_v2_immutable_source_receipts
  SET source_revision_id = NULL
  WHERE owner_user_id = p_owner_user_id
    AND source_scope = 'OWNER_PRIVATE'
    AND source_revision_id = ANY(target_source_revision_ids);
  UPDATE public.rag_v2_immutable_materialization_runs
  SET component_generation_id = NULL,
      state = CASE WHEN state IN ('OPEN', 'STAGED') THEN 'FAILED' ELSE state END,
      failure_code = CASE WHEN state IN ('OPEN', 'STAGED') THEN 'OWNER_DELETED' ELSE failure_code END,
      completed_at = CASE WHEN state IN ('OPEN', 'STAGED') THEN clock_timestamp() ELSE completed_at END
  WHERE owner_user_id = p_owner_user_id
    AND component_scope = 'OWNER_PRIVATE'
    AND (
      component_generation_id = ANY(target_generation_ids)
      OR document_id = p_document_id
    );
  DELETE FROM public.rag_v2_immutable_generation_embeddings
  WHERE component_generation_id = ANY(target_generation_ids);
  DELETE FROM public.rag_v2_immutable_generation_memberships
  WHERE component_generation_id = ANY(target_generation_ids);
  DELETE FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = ANY(target_generation_ids);
  DELETE FROM public.rag_v2_immutable_chunks
  WHERE owner_user_id = p_owner_user_id
    AND source_scope = 'OWNER_PRIVATE'
    AND source_revision_id = ANY(target_source_revision_ids);
  DELETE FROM public.rag_v2_immutable_source_revisions
  WHERE owner_user_id = p_owner_user_id
    AND source_scope = 'OWNER_PRIVATE'
    AND document_id = p_document_id;
  INSERT INTO public.rag_v2_immutable_deletion_receipts (
    deletion_receipt_id,
    owner_user_id,
    document_id,
    deletion_kind,
    replacement_bundle_id,
    activation_receipt_id,
    reason_hash,
    deleted_source_revision_count,
    deleted_chunk_count,
    deleted_embedding_count,
    affected_materialization_run_count
  )
  VALUES (
    p_deletion_receipt_id,
    p_owner_user_id,
    p_document_id,
    CASE WHEN is_replaced_active THEN 'REPLACED_ACTIVE' ELSE 'UNREFERENCED_STAGING' END,
    p_replacement_bundle_id,
    p_activation_receipt_id,
    p_reason_hash,
    target_source_count,
    target_chunk_count,
    target_embedding_count,
    target_run_count
  );
  INSERT INTO public.rag_v2_immutable_owner_document_deletion_tombstones (
    owner_user_id,
    document_id,
    deletion_receipt_id
  )
  VALUES (
    p_owner_user_id,
    p_document_id,
    p_deletion_receipt_id
  );
  RETURN true;
END;
$_$;


ALTER FUNCTION public.delete_rag_v2_immutable_owner_document(p_owner_user_id text, p_document_id text, p_replacement_bundle_id text, p_expected_active_bundle_id text, p_expected_bundle_version bigint, p_activation_receipt_id text, p_deletion_receipt_id text, p_reason_hash text) OWNER TO flyway;


CREATE FUNCTION public.delete_rag_v2_immutable_owner_document_with_ticket(p_owner_user_id text, p_document_id text, p_ticket_id text, p_activation_receipt_id text, p_deletion_receipt_id text, p_reason_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  ticket_digest text;
  ticket_record public.rag_v2_immutable_owner_delete_tickets%ROWTYPE;
  deletion_result boolean;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
     OR p_ticket_id !~ '^rtd_[0-9a-f]{32}$'
     OR p_activation_receipt_id !~ '^rgr_act_[0-9a-f]{32}$'
     OR p_deletion_receipt_id !~ '^rgr_del_[0-9a-f]{32}$'
     OR p_reason_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 owner delete ticket consume arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  ticket_digest := encode(digest(p_ticket_id, 'sha256'), 'hex');
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-owner-delete-ticket|' || ticket_digest, 0)
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  SELECT *
  INTO ticket_record
  FROM public.rag_v2_immutable_owner_delete_tickets
  WHERE ticket_hash = ticket_digest
  FOR UPDATE;
  IF NOT FOUND
     OR ticket_record.owner_user_id IS DISTINCT FROM p_owner_user_id
     OR ticket_record.document_id IS DISTINCT FROM p_document_id
     OR ticket_record.operation <> 'OWNER_DELETE'
     OR ticket_record.policy_version <> 'RAG_V2_OWNER_DOCUMENT_DELETE_V1' THEN
    RAISE EXCEPTION 'immutable RAG v2 owner delete ticket is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF ticket_record.state = 'CONSUMED' THEN
    RETURN ticket_record.consumer_result = 'DELETED';
  END IF;
  IF ticket_record.state <> 'ISSUED'
     OR ticket_record.expires_at <= statement_timestamp() THEN
    RAISE EXCEPTION 'immutable RAG v2 owner delete ticket is expired'
      USING ERRCODE = '23514';
  END IF;

  -- V25 handles unreferenced/staged rows.  Active owner graph deletion intentionally falls
  -- through only on its typed replacement-required constraint to V33, inside this same xact.
  BEGIN
    deletion_result := public.delete_rag_v2_immutable_owner_document(
      p_owner_user_id,
      p_document_id,
      NULL,
      NULL,
      NULL,
      NULL,
      p_deletion_receipt_id,
      p_reason_hash
    );
  EXCEPTION
    WHEN SQLSTATE '23514' THEN
      deletion_result := public.replace_and_delete_rag_v2_immutable_owner_document(
        p_owner_user_id,
        p_document_id,
        p_activation_receipt_id,
        p_deletion_receipt_id,
        p_reason_hash
      );
  END;

  UPDATE public.rag_v2_immutable_owner_delete_tickets
  SET state = 'CONSUMED',
      consumed_at = clock_timestamp(),
      consumer_deletion_receipt_id = CASE WHEN deletion_result THEN p_deletion_receipt_id ELSE NULL END,
      consumer_result = CASE WHEN deletion_result THEN 'DELETED' ELSE 'ABSENT' END
  WHERE ticket_hash = ticket_digest
    AND state = 'ISSUED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 owner delete ticket consumption conflicted'
      USING ERRCODE = '40001';
  END IF;
  RETURN deletion_result;
END;
$_$;


ALTER FUNCTION public.delete_rag_v2_immutable_owner_document_with_ticket(p_owner_user_id text, p_document_id text, p_ticket_id text, p_activation_receipt_id text, p_deletion_receipt_id text, p_reason_hash text) OWNER TO flyway;


CREATE FUNCTION public.enforce_brokerage_evidence_writer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  -- brokerage ORDER evidence는 SECURITY DEFINER 함수가 원자 order write와 함께 만들 때만 신뢰한다.
  IF NOT pg_has_role(current_user, 'flyway', 'USAGE') THEN
    RAISE EXCEPTION 'S3.1 brokerage evidence writer denied'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.enforce_brokerage_evidence_writer() OWNER TO flyway;


CREATE FUNCTION public.enforce_exact_observation_replay() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  primary_identity text;
  unique_identity jsonb;
  primary_lock bigint;
  unique_lock bigint;
  existing_row jsonb;
  incoming_row jsonb := to_jsonb(NEW) - 'created_at';
BEGIN
  IF TG_TABLE_NAME = 'portfolio_position_observations' THEN
    primary_identity := NEW.balance_observation_id || ':' || NEW.symbol;
    unique_identity := jsonb_build_object(
      'balance_observation_id', NEW.balance_observation_id,
      'symbol', NEW.symbol
    );
  ELSIF TG_TABLE_NAME = 'market_quote_observations' THEN
    primary_identity := NEW.observation_id;
    unique_identity := jsonb_build_object(
      'symbol', NEW.symbol,
      'source', NEW.source,
      'observed_at', NEW.observed_at,
      'artifact_hash', NEW.artifact_hash
    );
  ELSIF TG_TABLE_NAME = 'instrument_catalog_observations' THEN
    primary_identity := NEW.observation_id;
    unique_identity := jsonb_build_object(
      'symbol', NEW.symbol,
      'catalog_version', NEW.catalog_version,
      'artifact_hash', NEW.artifact_hash
    );
  ELSIF TG_TABLE_NAME = 'portfolio_balance_observations' THEN
    primary_identity := NEW.observation_id;
    unique_identity := jsonb_build_object(
      'owner_user_id', NEW.owner_user_id,
      'account_scope_hash', NEW.account_scope_hash,
      'source', NEW.source,
      'observed_at', NEW.observed_at,
      'artifact_hash', NEW.artifact_hash
    );
  ELSIF TG_TABLE_NAME = 'deterministic_risk_observations' THEN
    primary_identity := NEW.observation_id;
    unique_identity := jsonb_build_object(
      'owner_user_id', NEW.owner_user_id,
      'owner_scope_hash', NEW.owner_scope_hash,
      'portfolio_source', NEW.portfolio_source,
      'observed_at', NEW.observed_at,
      'artifact_hash', NEW.artifact_hash
    );
  ELSIF TG_TABLE_NAME = 'daily_order_count_observations' THEN
    primary_identity := NEW.observation_id;
    unique_identity := jsonb_build_object(
      'owner_user_id', NEW.owner_user_id,
      'owner_scope_hash', NEW.owner_scope_hash,
      'portfolio_source', NEW.portfolio_source,
      'trading_date', NEW.trading_date,
      'covered_through', NEW.covered_through,
      'artifact_hash', NEW.artifact_hash
    );
  ELSIF TG_TABLE_NAME = 'corporation_registry_observations' THEN
    primary_identity := NEW.observation_id;
    unique_identity := jsonb_build_object(
      'symbol', NEW.symbol,
      'corp_code', NEW.corp_code,
      'observed_at', NEW.observed_at,
      'artifact_hash', NEW.artifact_hash
    );
  ELSE
    RAISE EXCEPTION 'unsupported exact replay table'
      USING ERRCODE = '55000';
  END IF;

  primary_lock := hashtextextended(
    TG_TABLE_NAME || ':primary:' || primary_identity,
    23004401
  );
  unique_lock := hashtextextended(
    TG_TABLE_NAME || ':unique:' || unique_identity::text,
    23004401
  );
  PERFORM pg_advisory_xact_lock(least(primary_lock, unique_lock));
  IF primary_lock <> unique_lock THEN
    PERFORM pg_advisory_xact_lock(greatest(primary_lock, unique_lock));
  END IF;

  IF TG_TABLE_NAME = 'portfolio_position_observations' THEN
    EXECUTE format(
      'SELECT to_jsonb(candidate) - ''created_at''
         FROM public.%I candidate
        WHERE to_jsonb(candidate) @> $1',
      TG_TABLE_NAME
    )
    INTO existing_row
    USING unique_identity;
  ELSE
    EXECUTE format(
      'SELECT to_jsonb(candidate) - ''created_at''
         FROM public.%I candidate
        WHERE candidate.observation_id = $1
           OR to_jsonb(candidate) @> $2
        LIMIT 1',
      TG_TABLE_NAME
    )
    INTO existing_row
    USING primary_identity, unique_identity;
  END IF;

  IF existing_row IS NULL THEN
    RETURN NEW;
  END IF;
  IF existing_row = incoming_row THEN
    RETURN NULL;
  END IF;
  RAISE EXCEPTION 'observation replay conflicts with immutable stored row'
    USING ERRCODE = '23505';
END
$_$;


ALTER FUNCTION public.enforce_exact_observation_replay() OWNER TO flyway;


CREATE FUNCTION public.enforce_market_data_daily_chain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    prior_manifest_sha256 text;
BEGIN
    IF NEW.manifest_kind <> 'DAILY' THEN
        RETURN NEW;
    END IF;

    -- Serialize the small append-only chain independently from application process locks.
    PERFORM pg_advisory_xact_lock(hashtextextended('market-data-daily-chain-v1', 0));

    SELECT manifest_sha256 INTO prior_manifest_sha256
    FROM market_data_manifests
    WHERE status = 'ACCEPTED'
      AND session_date < NEW.session_date
    ORDER BY session_date DESC, generation DESC, created_at DESC, manifest_sha256 DESC
    LIMIT 1;

    IF prior_manifest_sha256 IS NULL
       OR NEW.previous_manifest_sha256 IS DISTINCT FROM prior_manifest_sha256 THEN
        RAISE EXCEPTION 'NEEDS_HUMAN: previous accepted market-data manifest is not the DB head';
    END IF;

    IF NEW.generation = 1 AND EXISTS (
        SELECT 1
        FROM market_data_manifests
        WHERE status = 'ACCEPTED'
          AND manifest_kind = 'DAILY'
          AND session_date > NEW.session_date
    ) THEN
        RAISE EXCEPTION 'NEEDS_HUMAN: daily market-data sessions must append forward';
    END IF;

    RETURN NEW;
END
$$;


ALTER FUNCTION public.enforce_market_data_daily_chain() OWNER TO flyway;


CREATE FUNCTION public.enforce_market_data_manifest_append() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    existing market_data_manifests%ROWTYPE;
    prior market_data_manifests%ROWTYPE;
BEGIN
    SELECT * INTO existing
    FROM market_data_manifests
    WHERE manifest_sha256 = NEW.manifest_sha256;
    IF FOUND THEN
        IF existing.session_date = NEW.session_date
           AND existing.generation = NEW.generation
           AND existing.archive_sha256 = NEW.archive_sha256 THEN
            RETURN NULL;
        END IF;
        RAISE EXCEPTION 'NEEDS_HUMAN: manifest sha identity conflicts with stored bytes';
    END IF;

    SELECT * INTO existing
    FROM market_data_manifests
    WHERE session_date = NEW.session_date
      AND generation = NEW.generation;
    IF FOUND THEN
        RAISE EXCEPTION 'NEEDS_HUMAN: same session generation has a different manifest sha';
    END IF;

    IF NEW.generation > 1 THEN
        SELECT * INTO prior
        FROM market_data_manifests
        WHERE manifest_sha256 = NEW.supersedes_sha256
          AND session_date = NEW.session_date
          AND generation = NEW.generation - 1
          AND status = 'ACCEPTED';
        IF NOT FOUND THEN
            RAISE EXCEPTION 'NEEDS_HUMAN: correction does not supersede the accepted prior generation';
        END IF;
    END IF;
    RETURN NEW;
END
$$;


ALTER FUNCTION public.enforce_market_data_manifest_append() OWNER TO flyway;


CREATE FUNCTION public.evaluate_rag_v2_immutable_public_bge_component(p_component_generation_id text, p_evaluation jsonb) RETURNS TABLE(component_generation_id text, state text, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  generation_record public.rag_v2_immutable_component_generations%ROWTYPE;
  submitted_evaluation_digest text;
  submitted_exact_top5_hit_rate double precision;
  submitted_track_recall_at5 double precision;
  submitted_citation_coverage double precision;
  submitted_direct_advice_block_rate double precision;
  submitted_cross_owner_leak_count integer;
  submitted_mixed_profile_row_count integer;
  submitted_owner_delete_residual_row_count integer;
  submitted_warm_p95_millis double precision;
  submitted_provider_physical_call_count integer;
  observed_source_total integer;
  observed_chunk_total integer;
  observed_embedding_total integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_component_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_evaluation IS NULL
     OR jsonb_typeof(p_evaluation) <> 'object'
     OR octet_length(p_evaluation::text) NOT BETWEEN 2 AND 8192
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_evaluation) AS evaluation_key
       WHERE evaluation_key NOT IN (
         'citationCoverage', 'crossOwnerLeakCount', 'directAdviceBlockRate', 'evaluationDigest',
         'exactTop5HitRate', 'mixedProfileRowCount', 'ownerDeleteResidualRowCount',
         'providerPhysicalCallCount', 'schemaVersion', 'trackRecallAt5', 'warmP95Millis'
       )
     )
     OR NOT (p_evaluation ?& ARRAY[
       'citationCoverage', 'crossOwnerLeakCount', 'directAdviceBlockRate', 'evaluationDigest',
       'exactTop5HitRate', 'mixedProfileRowCount', 'ownerDeleteResidualRowCount',
       'providerPhysicalCallCount', 'schemaVersion', 'trackRecallAt5', 'warmP95Millis'
     ])
     OR jsonb_typeof(p_evaluation -> 'schemaVersion') <> 'number'
     OR p_evaluation ->> 'schemaVersion' <> '1'
     OR jsonb_typeof(p_evaluation -> 'evaluationDigest') <> 'string'
     OR EXISTS (
       SELECT 1
       FROM jsonb_each(p_evaluation) AS field(key, value)
       WHERE field.key NOT IN ('schemaVersion', 'evaluationDigest')
         AND jsonb_typeof(field.value) <> 'number'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_each(p_evaluation) AS field(key, value)
       WHERE field.key IN (
         'crossOwnerLeakCount', 'mixedProfileRowCount', 'ownerDeleteResidualRowCount',
         'providerPhysicalCallCount'
       )
         AND field.value::text !~ '^(0|[1-9][0-9]*)$'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE evaluation arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  submitted_evaluation_digest := p_evaluation ->> 'evaluationDigest';
  submitted_exact_top5_hit_rate := (p_evaluation ->> 'exactTop5HitRate')::double precision;
  submitted_track_recall_at5 := (p_evaluation ->> 'trackRecallAt5')::double precision;
  submitted_citation_coverage := (p_evaluation ->> 'citationCoverage')::double precision;
  submitted_direct_advice_block_rate := (p_evaluation ->> 'directAdviceBlockRate')::double precision;
  submitted_cross_owner_leak_count := (p_evaluation ->> 'crossOwnerLeakCount')::integer;
  submitted_mixed_profile_row_count := (p_evaluation ->> 'mixedProfileRowCount')::integer;
  submitted_owner_delete_residual_row_count := (p_evaluation ->> 'ownerDeleteResidualRowCount')::integer;
  submitted_warm_p95_millis := (p_evaluation ->> 'warmP95Millis')::double precision;
  submitted_provider_physical_call_count := (p_evaluation ->> 'providerPhysicalCallCount')::integer;
  IF submitted_evaluation_digest IS NULL
     OR submitted_evaluation_digest !~ '^[0-9a-f]{64}$'
     OR submitted_exact_top5_hit_rate <> 1.0
     OR submitted_track_recall_at5 < 0.80
     OR submitted_citation_coverage < 0.80
     OR submitted_direct_advice_block_rate <> 1.0
     OR submitted_cross_owner_leak_count <> 0
     OR submitted_mixed_profile_row_count <> 0
     OR submitted_owner_delete_residual_row_count <> 0
     OR submitted_warm_p95_millis <= 0
     OR submitted_warm_p95_millis >= 8000
     OR submitted_provider_physical_call_count <> 0 THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE evaluation thresholds failed'
      USING ERRCODE = '23514';
  END IF;
  SELECT * INTO generation_record
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = p_component_generation_id
  FOR UPDATE;
  IF NOT FOUND
     OR generation_record.owner_user_id IS NOT NULL
     OR generation_record.component_scope NOT IN ('EXACT30', 'OA112')
     OR generation_record.embedding_profile_id <> 'bge_m3_local_1024_v1' THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE component was not found'
      USING ERRCODE = '23514';
  END IF;
  IF public.rag_v2_immutable_public_bge_component_hashes_are_valid(
    p_component_generation_id
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE component hash projection is invalid'
      USING ERRCODE = '23514';
  END IF;
  IF generation_record.state = 'EVALUATED'
     AND generation_record.evaluation_status = 'PASSED' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.rag_v2_immutable_public_component_evaluations AS evaluation
      WHERE evaluation.component_generation_id = p_component_generation_id
        AND evaluation.evaluation_digest = submitted_evaluation_digest
        AND evaluation.exact_top5_hit_rate = submitted_exact_top5_hit_rate
        AND evaluation.track_recall_at5 = submitted_track_recall_at5
        AND evaluation.citation_coverage = submitted_citation_coverage
        AND evaluation.direct_advice_block_rate = submitted_direct_advice_block_rate
        AND evaluation.cross_owner_leak_count = submitted_cross_owner_leak_count
        AND evaluation.mixed_profile_row_count = submitted_mixed_profile_row_count
        AND evaluation.owner_delete_residual_row_count = submitted_owner_delete_residual_row_count
        AND evaluation.warm_p95_millis = submitted_warm_p95_millis
        AND evaluation.provider_physical_call_count = submitted_provider_physical_call_count
    ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public BGE evaluation conflicts'
        USING ERRCODE = '23505';
    END IF;
    RETURN QUERY SELECT p_component_generation_id, 'EVALUATED',
      generation_record.actual_source_count, generation_record.actual_chunk_count;
    RETURN;
  END IF;
  IF generation_record.state <> 'STAGING'
     OR generation_record.evaluation_status <> 'PENDING'
     OR generation_record.actual_source_count <> generation_record.expected_source_count
     OR generation_record.actual_chunk_count <> generation_record.expected_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE component is not complete'
      USING ERRCODE = '23514';
  END IF;
  SELECT COUNT(DISTINCT membership.source_revision_id)::integer, COUNT(*)::integer, COUNT(embedding.chunk_id)::integer
  INTO observed_source_total, observed_chunk_total, observed_embedding_total
  FROM public.rag_v2_immutable_generation_memberships AS membership
  LEFT JOIN public.rag_v2_immutable_generation_embeddings AS embedding
    ON embedding.component_generation_id = membership.component_generation_id
   AND embedding.chunk_id = membership.chunk_id
   AND embedding.component_scope = membership.component_scope
  WHERE membership.component_generation_id = p_component_generation_id
    AND membership.component_scope = generation_record.component_scope;
  IF observed_source_total <> generation_record.expected_source_count
     OR observed_chunk_total <> generation_record.expected_chunk_count
     OR observed_embedding_total <> generation_record.expected_chunk_count
     OR (generation_record.component_scope = 'OA112' AND EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_generation_memberships AS membership
       JOIN public.rag_v2_immutable_source_revisions AS source
         ON source.source_revision_id = membership.source_revision_id
       LEFT JOIN public.rag_v2_immutable_oa_source_cards AS card
         ON card.source_revision_id = source.source_revision_id
        AND card.source_scope = 'OA112'
       WHERE membership.component_generation_id = p_component_generation_id
         AND (
           source.oa_track_id IS NULL
           OR source.reserve_source
           OR NOT source.machine_fetch_allowed
           OR NOT source.local_processing_allowed
           OR NOT source.external_embedding_allowed
           OR NOT source.external_generation_allowed
           OR card.source_revision_id IS NULL
           OR NOT card.active_oa112_eligible
         )
     )) THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE persisted component is invalid'
      USING ERRCODE = '23514';
  END IF;
  INSERT INTO public.rag_v2_immutable_public_component_evaluations (
    component_generation_id, component_scope, embedding_profile_id, evaluation_digest,
    exact_top5_hit_rate, track_recall_at5, citation_coverage, direct_advice_block_rate,
    cross_owner_leak_count, mixed_profile_row_count, owner_delete_residual_row_count,
    warm_p95_millis, provider_physical_call_count
  ) VALUES (
    p_component_generation_id, generation_record.component_scope, 'bge_m3_local_1024_v1', submitted_evaluation_digest,
    submitted_exact_top5_hit_rate, submitted_track_recall_at5, submitted_citation_coverage, submitted_direct_advice_block_rate,
    submitted_cross_owner_leak_count, submitted_mixed_profile_row_count, submitted_owner_delete_residual_row_count,
    submitted_warm_p95_millis, submitted_provider_physical_call_count
  );
  UPDATE public.rag_v2_immutable_component_generations
  SET state = 'EVALUATED', evaluation_status = 'PASSED', evaluated_at = clock_timestamp()
  WHERE component_generation_id = p_component_generation_id
    AND state = 'STAGING'
    AND evaluation_status = 'PENDING';
  UPDATE public.rag_v2_immutable_materialization_runs
  SET state = 'EVALUATED', completed_at = clock_timestamp()
  WHERE component_generation_id = p_component_generation_id
    AND owner_user_id IS NULL
    AND component_scope = generation_record.component_scope
    AND state = 'STAGED';
  RETURN QUERY SELECT p_component_generation_id, 'EVALUATED', observed_source_total, observed_chunk_total;
END;
$_$;


ALTER FUNCTION public.evaluate_rag_v2_immutable_public_bge_component(p_component_generation_id text, p_evaluation jsonb) OWNER TO flyway;


CREATE FUNCTION public.evaluate_rag_v2_immutable_public_voyage_component(p_component_generation_id text, p_evaluation jsonb) RETURNS TABLE(component_generation_id text, state text, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  generation_scope text;
  expected_query_count integer;
  submitted_scope_claim_sha256 text;
  observed_committed_query_count integer;
  observed_distinct_query_count integer;
  observed_unresolved_attempt_count integer;
  evaluated_row record;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_component_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_evaluation IS NULL
     OR jsonb_typeof(p_evaluation) <> 'object'
     OR NOT (p_evaluation ? 'evaluationScopeClaimSha256')
     OR jsonb_typeof(p_evaluation -> 'evaluationScopeClaimSha256') <> 'string'
     OR p_evaluation ->> 'evaluationScopeClaimSha256' !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage evaluation usage binding is invalid'
      USING ERRCODE = '22023';
  END IF;

  submitted_scope_claim_sha256 := p_evaluation ->> 'evaluationScopeClaimSha256';
  SELECT generation.component_scope INTO generation_scope
  FROM public.rag_v2_immutable_component_generations AS generation
  WHERE generation.component_generation_id = p_component_generation_id
    AND generation.owner_user_id IS NULL
    AND generation.embedding_profile_id = 'voyage_context_4_1024_v1'
  FOR UPDATE;
  IF generation_scope NOT IN ('EXACT30', 'OA112') THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage evaluation component is unavailable'
      USING ERRCODE = '23514';
  END IF;
  expected_query_count := CASE generation_scope WHEN 'EXACT30' THEN 1 WHEN 'OA112' THEN 1 ELSE -1 END;

  SELECT
    COUNT(*) FILTER (WHERE outcome.state = 'COMMITTED')::integer,
    COUNT(DISTINCT reservation.query_sha256) FILTER (WHERE outcome.state = 'COMMITTED')::integer,
    COUNT(*) FILTER (
      WHERE outcome.usage_event_id IS NULL OR outcome.state <> 'COMMITTED'
    )::integer
  INTO
    observed_committed_query_count,
    observed_distinct_query_count,
    observed_unresolved_attempt_count
  FROM public.rag_v2_immutable_voyage_query_usage_reservations AS reservation
  JOIN public.rag_v2_immutable_voyage_query_usage_attempts AS attempt
    ON attempt.usage_event_id = reservation.usage_event_id
   AND attempt.state = 'ATTEMPTED'
   AND attempt.physical_call_count = 1
  LEFT JOIN public.rag_v2_immutable_voyage_query_usage_outcomes AS outcome
    ON outcome.usage_event_id = reservation.usage_event_id
  WHERE reservation.scope_claim_sha256 = submitted_scope_claim_sha256
    AND reservation.evaluation_component_scope = generation_scope;

  IF observed_committed_query_count <> expected_query_count
     OR observed_distinct_query_count <> expected_query_count
     OR observed_unresolved_attempt_count <> 0 THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage evaluation query ledger is incomplete'
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO evaluated_row
  FROM public.evaluate_rag_v2_immutable_public_voyage_component_v45_unlinked(
    p_component_generation_id,
    p_evaluation - 'evaluationScopeClaimSha256'
  );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage evaluation transition returned no receipt'
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.rag_v2_immutable_public_voyage_component_evaluations AS evaluation
  SET evaluation_scope_claim_sha256 = submitted_scope_claim_sha256
  WHERE evaluation.component_generation_id = p_component_generation_id
    AND (
      evaluation.evaluation_scope_claim_sha256 IS NULL
      OR evaluation.evaluation_scope_claim_sha256 = submitted_scope_claim_sha256
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage evaluation scope conflicts'
      USING ERRCODE = '23505';
  END IF;

  RETURN QUERY
  SELECT
    evaluated_row.component_generation_id,
    evaluated_row.state,
    evaluated_row.source_count,
    evaluated_row.chunk_count;
END;
$_$;


ALTER FUNCTION public.evaluate_rag_v2_immutable_public_voyage_component(p_component_generation_id text, p_evaluation jsonb) OWNER TO flyway;


CREATE FUNCTION public.evaluate_rag_v2_immutable_public_voyage_component_v45_unlinked(p_component_generation_id text, p_evaluation jsonb) RETURNS TABLE(component_generation_id text, state text, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  generation_record public.rag_v2_immutable_component_generations%ROWTYPE;
  submitted_evaluation_digest text;
  submitted_exact_top5_hit_rate double precision;
  submitted_track_recall_at5 double precision;
  submitted_citation_coverage double precision;
  submitted_direct_advice_block_rate double precision;
  submitted_cross_owner_leak_count integer;
  submitted_mixed_profile_row_count integer;
  submitted_owner_delete_residual_row_count integer;
  submitted_warm_p95_millis double precision;
  submitted_provider_physical_call_count integer;
  observed_source_total integer;
  observed_chunk_total integer;
  observed_embedding_total integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_component_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_evaluation IS NULL
     OR jsonb_typeof(p_evaluation) <> 'object'
     OR octet_length(p_evaluation::text) NOT BETWEEN 2 AND 8192
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_evaluation) AS evaluation_key
       WHERE evaluation_key NOT IN (
         'citationCoverage', 'crossOwnerLeakCount', 'directAdviceBlockRate', 'evaluationDigest',
         'exactTop5HitRate', 'mixedProfileRowCount', 'ownerDeleteResidualRowCount',
         'providerPhysicalCallCount', 'schemaVersion', 'trackRecallAt5', 'warmP95Millis'
       )
     )
     OR NOT (p_evaluation ?& ARRAY[
       'citationCoverage', 'crossOwnerLeakCount', 'directAdviceBlockRate', 'evaluationDigest',
       'exactTop5HitRate', 'mixedProfileRowCount', 'ownerDeleteResidualRowCount',
       'providerPhysicalCallCount', 'schemaVersion', 'trackRecallAt5', 'warmP95Millis'
     ])
     OR jsonb_typeof(p_evaluation -> 'schemaVersion') <> 'number'
     OR p_evaluation ->> 'schemaVersion' <> '1'
     OR jsonb_typeof(p_evaluation -> 'evaluationDigest') <> 'string'
     OR EXISTS (
       SELECT 1
       FROM jsonb_each(p_evaluation) AS field(key, value)
       WHERE field.key NOT IN ('schemaVersion', 'evaluationDigest')
         AND jsonb_typeof(field.value) <> 'number'
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_each(p_evaluation) AS field(key, value)
       WHERE field.key IN (
         'crossOwnerLeakCount', 'mixedProfileRowCount', 'ownerDeleteResidualRowCount',
         'providerPhysicalCallCount'
       )
         AND field.value::text !~ '^(0|[1-9][0-9]*)$'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage evaluation arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  submitted_evaluation_digest := p_evaluation ->> 'evaluationDigest';
  submitted_exact_top5_hit_rate := (p_evaluation ->> 'exactTop5HitRate')::double precision;
  submitted_track_recall_at5 := (p_evaluation ->> 'trackRecallAt5')::double precision;
  submitted_citation_coverage := (p_evaluation ->> 'citationCoverage')::double precision;
  submitted_direct_advice_block_rate := (p_evaluation ->> 'directAdviceBlockRate')::double precision;
  submitted_cross_owner_leak_count := (p_evaluation ->> 'crossOwnerLeakCount')::integer;
  submitted_mixed_profile_row_count := (p_evaluation ->> 'mixedProfileRowCount')::integer;
  submitted_owner_delete_residual_row_count := (p_evaluation ->> 'ownerDeleteResidualRowCount')::integer;
  submitted_warm_p95_millis := (p_evaluation ->> 'warmP95Millis')::double precision;
  submitted_provider_physical_call_count := (p_evaluation ->> 'providerPhysicalCallCount')::integer;
  -- Voyage vector space는 같은 profile의 query embedding으로만 평가한다. Exact-30 fixture는
  -- 10개, OA112 manifest는 112개의 packet-bound one-shot query를 요구하므로, 0을 강제하면
  -- 실제 profile evaluation을 BGE나 임의 local vector로 대체하게 된다.
  SELECT * INTO generation_record
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = p_component_generation_id
  FOR UPDATE;
  IF NOT FOUND
     OR generation_record.owner_user_id IS NOT NULL
     OR generation_record.component_scope NOT IN ('EXACT30', 'OA112')
     OR generation_record.embedding_profile_id <> 'voyage_context_4_1024_v1' THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage component was not found'
      USING ERRCODE = '23514';
  END IF;
  IF submitted_evaluation_digest IS NULL
     OR submitted_evaluation_digest !~ '^[0-9a-f]{64}$'
     OR submitted_exact_top5_hit_rate <> 1.0
     OR submitted_track_recall_at5 < 0.80
     OR submitted_citation_coverage < 0.80
     OR submitted_direct_advice_block_rate <> 1.0
     OR submitted_cross_owner_leak_count <> 0
     OR submitted_mixed_profile_row_count <> 0
     OR submitted_owner_delete_residual_row_count <> 0
     OR submitted_warm_p95_millis <= 0
     OR submitted_warm_p95_millis >= 8000
     OR submitted_provider_physical_call_count <> (
       CASE generation_record.component_scope
         WHEN 'EXACT30' THEN 1
         WHEN 'OA112' THEN 1
         ELSE -1
       END
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage evaluation thresholds failed'
      USING ERRCODE = '23514';
  END IF;
  IF public.rag_v2_immutable_public_voyage_component_hashes_are_valid(
    p_component_generation_id
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage component hash projection is invalid'
      USING ERRCODE = '23514';
  END IF;
  IF generation_record.state = 'EVALUATED'
     AND generation_record.evaluation_status = 'PASSED' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.rag_v2_immutable_public_voyage_component_evaluations AS evaluation
      WHERE evaluation.component_generation_id = p_component_generation_id
        AND evaluation.evaluation_digest = submitted_evaluation_digest
        AND evaluation.exact_top5_hit_rate = submitted_exact_top5_hit_rate
        AND evaluation.track_recall_at5 = submitted_track_recall_at5
        AND evaluation.citation_coverage = submitted_citation_coverage
        AND evaluation.direct_advice_block_rate = submitted_direct_advice_block_rate
        AND evaluation.cross_owner_leak_count = submitted_cross_owner_leak_count
        AND evaluation.mixed_profile_row_count = submitted_mixed_profile_row_count
        AND evaluation.owner_delete_residual_row_count = submitted_owner_delete_residual_row_count
        AND evaluation.warm_p95_millis = submitted_warm_p95_millis
        AND evaluation.provider_physical_call_count = submitted_provider_physical_call_count
    ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage evaluation conflicts'
        USING ERRCODE = '23505';
    END IF;
    RETURN QUERY SELECT p_component_generation_id, 'EVALUATED',
      generation_record.actual_source_count, generation_record.actual_chunk_count;
    RETURN;
  END IF;
  IF generation_record.state <> 'STAGING'
     OR generation_record.evaluation_status <> 'PENDING'
     OR generation_record.actual_source_count <> generation_record.expected_source_count
     OR generation_record.actual_chunk_count <> generation_record.expected_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage component is not complete'
      USING ERRCODE = '23514';
  END IF;
  SELECT COUNT(DISTINCT membership.source_revision_id)::integer, COUNT(*)::integer, COUNT(embedding.chunk_id)::integer
  INTO observed_source_total, observed_chunk_total, observed_embedding_total
  FROM public.rag_v2_immutable_generation_memberships AS membership
  LEFT JOIN public.rag_v2_immutable_generation_embeddings AS embedding
    ON embedding.component_generation_id = membership.component_generation_id
   AND embedding.chunk_id = membership.chunk_id
   AND embedding.component_scope = membership.component_scope
  WHERE membership.component_generation_id = p_component_generation_id
    AND membership.component_scope = generation_record.component_scope;
  IF observed_source_total <> generation_record.expected_source_count
     OR observed_chunk_total <> generation_record.expected_chunk_count
     OR observed_embedding_total <> generation_record.expected_chunk_count
     OR (generation_record.component_scope = 'OA112' AND EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_generation_memberships AS membership
       JOIN public.rag_v2_immutable_source_revisions AS source
         ON source.source_revision_id = membership.source_revision_id
       LEFT JOIN public.rag_v2_immutable_oa_source_cards AS card
         ON card.source_revision_id = source.source_revision_id
        AND card.source_scope = 'OA112'
       WHERE membership.component_generation_id = p_component_generation_id
         AND (
           source.oa_track_id IS NULL
           OR source.reserve_source
           OR NOT source.machine_fetch_allowed
           OR NOT source.local_processing_allowed
           OR NOT source.external_embedding_allowed
           OR NOT source.external_generation_allowed
           OR card.source_revision_id IS NULL
           OR NOT card.active_oa112_eligible
         )
     )) THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage persisted component is invalid'
      USING ERRCODE = '23514';
  END IF;
  INSERT INTO public.rag_v2_immutable_public_voyage_component_evaluations (
    component_generation_id, component_scope, embedding_profile_id, evaluation_digest,
    exact_top5_hit_rate, track_recall_at5, citation_coverage, direct_advice_block_rate,
    cross_owner_leak_count, mixed_profile_row_count, owner_delete_residual_row_count,
    warm_p95_millis, provider_physical_call_count
  ) VALUES (
    p_component_generation_id, generation_record.component_scope, 'voyage_context_4_1024_v1', submitted_evaluation_digest,
    submitted_exact_top5_hit_rate, submitted_track_recall_at5, submitted_citation_coverage, submitted_direct_advice_block_rate,
    submitted_cross_owner_leak_count, submitted_mixed_profile_row_count, submitted_owner_delete_residual_row_count,
    submitted_warm_p95_millis, submitted_provider_physical_call_count
  );
  UPDATE public.rag_v2_immutable_component_generations
  SET state = 'EVALUATED', evaluation_status = 'PASSED', evaluated_at = clock_timestamp()
  WHERE component_generation_id = p_component_generation_id
    AND state = 'STAGING'
    AND evaluation_status = 'PENDING';
  UPDATE public.rag_v2_immutable_materialization_runs
  SET state = 'EVALUATED', completed_at = clock_timestamp()
  WHERE component_generation_id = p_component_generation_id
    AND owner_user_id IS NULL
    AND component_scope = generation_record.component_scope
    AND state = 'STAGED';
  RETURN QUERY SELECT p_component_generation_id, 'EVALUATED', observed_source_total, observed_chunk_total;
END;
$_$;


ALTER FUNCTION public.evaluate_rag_v2_immutable_public_voyage_component_v45_unlinked(p_component_generation_id text, p_evaluation jsonb) OWNER TO flyway;


CREATE FUNCTION public.fail_async_job(p_job_id text, p_claim_token uuid, p_error_code text, p_error_class text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE current_attempt integer; next_status text;
BEGIN
  IF session_user <> 'decision_worker' THEN RAISE EXCEPTION 'async failure role denied' USING ERRCODE='42501'; END IF;
  IF p_error_code !~ '^[A-Z][A-Z0-9_]{2,63}$' OR p_error_class !~ '^[A-Z][A-Z0-9_]{2,63}$' THEN
    RAISE EXCEPTION 'invalid async failure' USING ERRCODE='22023';
  END IF;
  SELECT attempt_count INTO current_attempt FROM public.async_job
  WHERE job_id=p_job_id AND claim_token=p_claim_token AND status='RUNNING'
    AND lease_expires_at>statement_timestamp() AND hard_deadline_at>statement_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RETURN 'CONFLICT'; END IF;
  next_status:=CASE WHEN current_attempt>=3 THEN 'NEEDS_REVIEW' ELSE 'FAILED' END;
  UPDATE public.async_job SET status=next_status,claim_token=NULL,claimed_by=NULL,lease_expires_at=NULL,
    error_code=p_error_code,error_class=p_error_class,error_message=p_error_code,
    next_attempt_at=statement_timestamp()+CASE current_attempt WHEN 1 THEN interval '1 second' ELSE interval '5 seconds' END,
    completed_at=CASE WHEN next_status='NEEDS_REVIEW' THEN statement_timestamp() ELSE completed_at END,
    updated_at=statement_timestamp()
  WHERE job_id=p_job_id AND claim_token=p_claim_token;
  RETURN next_status;
END
$_$;


ALTER FUNCTION public.fail_async_job(p_job_id text, p_claim_token uuid, p_error_code text, p_error_class text) OWNER TO flyway;


CREATE FUNCTION public.fail_async_work(p_job_id text, p_claim_token uuid, p_dlq_event_id text, p_event_id text, p_event_type text, p_payload_hash text, p_source_topic text, p_attempt integer, p_failure_code text, p_partition_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE next_status text;
BEGIN
  IF session_user <> 'decision_worker' THEN
    RAISE EXCEPTION 'async failure role denied' USING ERRCODE = '42501';
  END IF;
  next_status := public.fail_async_job(
    p_job_id, p_claim_token, p_failure_code, 'RETRYABLE_TRANSIENT'
  );
  IF next_status = 'NEEDS_REVIEW' THEN
    PERFORM public.record_kafka_poison(
      p_dlq_event_id, p_event_id, p_event_type, p_payload_hash, p_source_topic,
      p_attempt, p_failure_code, p_partition_key
    );
  END IF;
  RETURN next_status;
END
$$;


ALTER FUNCTION public.fail_async_work(p_job_id text, p_claim_token uuid, p_dlq_event_id text, p_event_id text, p_event_type text, p_payload_hash text, p_source_topic text, p_attempt integer, p_failure_code text, p_partition_key text) OWNER TO flyway;


CREATE FUNCTION public.fail_dlq_outbox(p_event_id text, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE changed integer;
BEGIN
  IF session_user <> 'decision_app' THEN RAISE EXCEPTION 'DLQ failure role denied' USING ERRCODE='42501'; END IF;
  UPDATE public.event_outbox SET retry_count=retry_count+1,claim_token=NULL,claimed_by=NULL,
    lease_expires_at=NULL,next_attempt_at=statement_timestamp()+
      CASE retry_count WHEN 0 THEN interval '1 second' ELSE interval '5 seconds' END,updated_at=statement_timestamp()
  WHERE event_id=p_event_id AND claim_token=p_claim_token AND status='DLQ_REQUESTED'
    AND retry_count<3 AND lease_expires_at>statement_timestamp();
  GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed=1;
END
$$;


ALTER FUNCTION public.fail_dlq_outbox(p_event_id text, p_claim_token uuid) OWNER TO flyway;


CREATE FUNCTION public.fail_event_outbox(p_event_id text, p_claim_token uuid, p_failure_code text, p_error_class text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  current_attempt integer;
  next_status text;
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'outbox failure role denied' USING ERRCODE = '42501';
  END IF;
  IF p_failure_code !~ '^[A-Z][A-Z0-9_]{2,63}$' OR p_error_class !~ '^[A-Z][A-Z0-9_]{2,63}$' THEN
    RAISE EXCEPTION 'invalid bounded outbox failure' USING ERRCODE = '22023';
  END IF;

  SELECT retry_count + 1 INTO current_attempt
  FROM public.event_outbox
  WHERE event_id = p_event_id AND claim_token = p_claim_token
    AND status IN ('PENDING', 'FAILED') AND lease_expires_at > statement_timestamp()
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 'CONFLICT';
  END IF;
  next_status := CASE WHEN current_attempt >= 3 THEN 'DLQ_REQUESTED' ELSE 'FAILED' END;

  UPDATE public.event_outbox
  SET status = next_status, retry_count = current_attempt, claim_token = NULL, claimed_by = NULL,
      lease_expires_at = NULL, failure_code = p_failure_code, error_class = p_error_class,
      last_error = p_failure_code,
      next_attempt_at = statement_timestamp() + CASE current_attempt WHEN 1 THEN interval '1 second' ELSE interval '5 seconds' END,
      updated_at = statement_timestamp()
  WHERE event_id = p_event_id AND claim_token = p_claim_token;
  RETURN next_status;
END
$_$;


ALTER FUNCTION public.fail_event_outbox(p_event_id text, p_claim_token uuid, p_failure_code text, p_error_class text) OWNER TO flyway;


CREATE FUNCTION public.fail_rag_answer_before_provider(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id THEN
    RAISE EXCEPTION 'RAG failed claim actor binding is invalid'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.rag_answer_claims
  SET state = 'FAILED_BEFORE_PROVIDER',
      updated_at = transaction_timestamp()
  WHERE scope_hmac = p_scope_hmac
    AND owner_user_id = p_owner_user_id
    AND request_fingerprint = p_request_fingerprint
    AND state = 'PENDING'
    AND provider_attempts = 0;
  IF FOUND THEN
    INSERT INTO public.rag_answer_claim_transitions (
      scope_hmac, owner_user_id, from_state, to_state, provider_attempts
    )
    VALUES (
      p_scope_hmac,
      p_owner_user_id,
      'PENDING',
      'FAILED_BEFORE_PROVIDER',
      0
    );
  END IF;
END
$$;


ALTER FUNCTION public.fail_rag_answer_before_provider(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text) OWNER TO flyway;


CREATE FUNCTION public.fail_rag_v2_owner_voyage_import_unknown_billing(p_owner_user_id text, p_plan_sha256 text, p_packet_sha256 text, p_response_validation_leaf text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR (p_response_validation_leaf IS NOT NULL AND p_response_validation_leaf NOT IN (
       'STATUS', 'BODY_SIZE_OR_TYPE', 'BODY_UTF8_OR_JSON', 'ENVELOPE_REQUIRED_FIELDS',
       'MODEL', 'USAGE', 'GROUP_COUNT', 'GROUP_FIELDS_OR_INDEX', 'CHUNK_COUNT',
       'CHUNK_FIELDS_OR_INDEX', 'CHUNK_TEXT', 'VECTOR_DIMENSION', 'VECTOR_NUMBER',
       'VECTOR_FINITE', 'VECTOR_NORM', 'COST_CAP'
     )) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage failure receipt is invalid'
      USING ERRCODE = '22023';
  END IF;
  UPDATE public.rag_v2_owner_voyage_import_attempts
  SET state = 'UNKNOWN_BILLING', response_validation_leaf = p_response_validation_leaf,
      completed_at = clock_timestamp()
  WHERE owner_user_id = p_owner_user_id
    AND plan_sha256 = p_plan_sha256
    AND packet_sha256 = p_packet_sha256
    AND (
      state = 'ATTEMPTED'
      OR (
        state = 'UNKNOWN_BILLING'
        AND response_validation_leaf IS NULL
        AND p_response_validation_leaf IS NOT NULL
      )
    );
  RETURN FOUND;
END;
$$;


ALTER FUNCTION public.fail_rag_v2_owner_voyage_import_unknown_billing(p_owner_user_id text, p_plan_sha256 text, p_packet_sha256 text, p_response_validation_leaf text) OWNER TO flyway;


CREATE FUNCTION public.finalize_rag_embedding_staging(p_generation_id text, p_materialization_run_id text, p_expected_writer_role text, p_expected_row_count integer, p_expected_staging_hash text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  generation_status text;
  generation_profile text;
  generation_expected_row_count integer;
  staged_row_count bigint;
  distinct_chunk_count bigint;
  invalid_membership_count bigint;
  invalid_vector_count bigint;
  computed_staging_hash text;
  inserted_row_count integer;
BEGIN
  -- SECURITY DEFINER의 current_user는 flyway이고 실제 caller는 session_user로 별도 검증한다.
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_expected_writer_role <> session_user
     OR p_generation_id !~ '^rag_gen_[0-9a-f]{32}$'
     OR octet_length(p_materialization_run_id) <> 40
     OR p_materialization_run_id !~ '^rag_mat_[0-9a-f]{32}$'
     OR p_expected_row_count NOT BETWEEN 1 AND 10000
     OR p_expected_staging_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'RAG embedding staging finalize caller or argument is invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    generation.status,
    generation.embedding_profile_id,
    generation.expected_chunk_count
  INTO
    generation_status,
    generation_profile,
    generation_expected_row_count
  FROM public.rag_corpus_generations AS generation
  WHERE generation.corpus_generation_id = p_generation_id
  FOR UPDATE;
  IF NOT FOUND
     OR generation_status <> 'MATERIALIZING'
     OR generation_expected_row_count <> p_expected_row_count THEN
    RAISE EXCEPTION 'RAG embedding staging finalize generation is not bounded'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    count(*),
    count(DISTINCT staging.chunk_revision_id),
    count(*) FILTER (
      WHERE membership.chunk_revision_id IS NULL
         OR staging.embedding_profile_id IS DISTINCT FROM generation_profile
         OR staging.writer_role::text IS DISTINCT FROM p_expected_writer_role
         OR staging.embedding_input_hash IS DISTINCT FROM membership.embedding_input_hash
         OR staging.context_set_hash IS DISTINCT FROM membership.context_set_hash
    ),
    count(*) FILTER (
      WHERE vector_dims(staging.embedding) <> 1024
         OR vector_norm(staging.embedding)::text IN ('NaN', 'Infinity', '-Infinity')
         OR abs(vector_norm(staging.embedding)::double precision - 1.0) > 0.00001
    ),
    encode(
      digest(
        coalesce(
          string_agg(
            staging.staging_row_hash,
            ''
            ORDER BY convert_to(staging.chunk_revision_id, 'UTF8')
          ),
          ''
        ),
        'sha256'
      ),
      'hex'
    )
  INTO
    staged_row_count,
    distinct_chunk_count,
    invalid_membership_count,
    invalid_vector_count,
    computed_staging_hash
  FROM public.rag_embedding_staging AS staging
  LEFT JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = staging.generation_id
   AND membership.chunk_revision_id = staging.chunk_revision_id
   AND membership.embedding_profile_id = staging.embedding_profile_id
  WHERE staging.generation_id = p_generation_id
    AND staging.materialization_run_id = p_materialization_run_id;

  IF staged_row_count <> p_expected_row_count
     OR distinct_chunk_count <> p_expected_row_count
     OR invalid_membership_count <> 0
     OR invalid_vector_count <> 0
     OR computed_staging_hash IS DISTINCT FROM p_expected_staging_hash THEN
    RAISE EXCEPTION 'RAG embedding staging finalize validation failed'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.rag_chunk_embeddings (
    chunk_embedding_id,
    corpus_generation_id,
    chunk_revision_id,
    embedding_profile_id,
    vector_space,
    embedding_input_hash,
    context_set_hash,
    embedding
  )
  SELECT
    'rag_emb_' ||
      substr(
        encode(
          digest(
            concat_ws(
              E'\n',
              staging.generation_id,
              staging.chunk_revision_id,
              staging.embedding_profile_id,
              staging.embedding_input_hash,
              coalesce(staging.context_set_hash, '')
            ),
            'sha256'
          ),
          'hex'
        ),
        1,
        32
      ),
    staging.generation_id,
    staging.chunk_revision_id,
    staging.embedding_profile_id,
    staging.embedding_profile_id,
    staging.embedding_input_hash,
    staging.context_set_hash,
    staging.embedding
  FROM public.rag_embedding_staging AS staging
  WHERE staging.generation_id = p_generation_id
    AND staging.materialization_run_id = p_materialization_run_id
    AND staging.writer_role::text = p_expected_writer_role
  ORDER BY convert_to(staging.chunk_revision_id, 'UTF8')
  ON CONFLICT ON CONSTRAINT rag_chunk_embeddings_identity_unique DO NOTHING;
  GET DIAGNOSTICS inserted_row_count = ROW_COUNT;
  IF inserted_row_count <> p_expected_row_count THEN
    RAISE EXCEPTION 'RAG embedding staging finalize encountered an existing final identity'
      USING ERRCODE = '23505';
  END IF;

  UPDATE public.rag_corpus_generations AS generation
  SET actual_chunk_count = p_expected_row_count
  WHERE generation.corpus_generation_id = p_generation_id
    AND generation.status = 'MATERIALIZING'
    AND generation.actual_chunk_count = 0;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG embedding staging finalize generation counter drifted'
      USING ERRCODE = '23514';
  END IF;

  DELETE FROM public.rag_embedding_staging AS staging
  WHERE staging.generation_id = p_generation_id
    AND staging.materialization_run_id = p_materialization_run_id
    AND staging.writer_role::text = p_expected_writer_role;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG embedding staging finalize cleanup failed'
      USING ERRCODE = '23514';
  END IF;
  RETURN inserted_row_count;
END
$_$;


ALTER FUNCTION public.finalize_rag_embedding_staging(p_generation_id text, p_materialization_run_id text, p_expected_writer_role text, p_expected_row_count integer, p_expected_staging_hash text) OWNER TO flyway;


CREATE FUNCTION public.finalize_rag_embedding_staging_v2(p_generation_id text, p_materialization_run_id text, p_expected_writer_role text, p_expected_row_count integer, p_expected_staging_hash text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  generation_status text;
  generation_profile text;
  generation_expected_row_count integer;
  staged_row_count bigint;
  distinct_chunk_count bigint;
  invalid_membership_count bigint;
  invalid_vector_count bigint;
  computed_staging_hash text;
  inserted_row_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_expected_writer_role <> session_user
     OR p_generation_id !~ '^rag_gen_[0-9a-f]{32}$'
     OR octet_length(p_materialization_run_id) <> 40
     OR p_materialization_run_id !~ '^rag_mat_[0-9a-f]{32}$'
     OR p_expected_row_count NOT BETWEEN 1 AND 10000
     OR p_expected_staging_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'RAG full generation finalize caller or argument is invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    generation.status,
    generation.embedding_profile_id,
    generation.expected_chunk_count
  INTO
    generation_status,
    generation_profile,
    generation_expected_row_count
  FROM public.rag_corpus_generations AS generation
  WHERE generation.corpus_generation_id = p_generation_id
  FOR UPDATE;
  IF NOT FOUND
     OR generation_status <> 'MATERIALIZING'
     OR generation_profile <> 'bge_m3_local_1024_v1'
     OR generation_expected_row_count <> p_expected_row_count THEN
    RAISE EXCEPTION 'RAG full generation finalize target is not bounded'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    count(*),
    count(DISTINCT staging.chunk_revision_id),
    count(*) FILTER (
      WHERE membership.chunk_revision_id IS NULL
         OR staging.embedding_profile_id IS DISTINCT FROM generation_profile
         OR staging.writer_role::text IS DISTINCT FROM p_expected_writer_role
         OR staging.embedding_input_hash IS DISTINCT FROM membership.embedding_input_hash
         OR staging.context_set_hash IS DISTINCT FROM membership.context_set_hash
    ),
    count(*) FILTER (
      WHERE vector_dims(staging.embedding) <> 1024
         OR vector_norm(staging.embedding)::text IN ('NaN', 'Infinity', '-Infinity')
         OR abs(vector_norm(staging.embedding)::double precision - 1.0) > 0.00001
    ),
    encode(
      digest(
        coalesce(
          string_agg(
            staging.staging_row_hash,
            ''
            ORDER BY convert_to(staging.chunk_revision_id, 'UTF8')
          ),
          ''
        ),
        'sha256'
      ),
      'hex'
    )
  INTO
    staged_row_count,
    distinct_chunk_count,
    invalid_membership_count,
    invalid_vector_count,
    computed_staging_hash
  FROM public.rag_embedding_staging AS staging
  LEFT JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = staging.generation_id
   AND membership.chunk_revision_id = staging.chunk_revision_id
   AND membership.embedding_profile_id = staging.embedding_profile_id
  WHERE staging.generation_id = p_generation_id
    AND staging.materialization_run_id = p_materialization_run_id;

  IF staged_row_count <> p_expected_row_count
     OR distinct_chunk_count <> p_expected_row_count
     OR invalid_membership_count <> 0
     OR invalid_vector_count <> 0
     OR computed_staging_hash IS DISTINCT FROM p_expected_staging_hash THEN
    RAISE EXCEPTION 'RAG full generation finalize validation failed'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.rag_chunk_embeddings (
    chunk_embedding_id,
    corpus_generation_id,
    chunk_revision_id,
    embedding_profile_id,
    vector_space,
    embedding_input_hash,
    context_set_hash,
    embedding,
    materialization_row_hash
  )
  SELECT
    'rag_emb_' ||
      substr(
        encode(
          digest(
            concat_ws(
              E'\n',
              staging.generation_id,
              staging.chunk_revision_id,
              staging.embedding_profile_id,
              staging.embedding_input_hash,
              coalesce(staging.context_set_hash, '')
            ),
            'sha256'
          ),
          'hex'
        ),
        1,
        32
      ),
    staging.generation_id,
    staging.chunk_revision_id,
    staging.embedding_profile_id,
    staging.embedding_profile_id,
    staging.embedding_input_hash,
    staging.context_set_hash,
    staging.embedding,
    staging.staging_row_hash
  FROM public.rag_embedding_staging AS staging
  WHERE staging.generation_id = p_generation_id
    AND staging.materialization_run_id = p_materialization_run_id
    AND staging.writer_role::text = p_expected_writer_role
  ORDER BY convert_to(staging.chunk_revision_id, 'UTF8')
  ON CONFLICT ON CONSTRAINT rag_chunk_embeddings_identity_unique DO NOTHING;
  GET DIAGNOSTICS inserted_row_count = ROW_COUNT;
  IF inserted_row_count <> p_expected_row_count THEN
    RAISE EXCEPTION 'RAG full generation finalize encountered an existing final identity'
      USING ERRCODE = '23505';
  END IF;

  UPDATE public.rag_corpus_generations AS generation
  SET actual_chunk_count = p_expected_row_count
  WHERE generation.corpus_generation_id = p_generation_id
    AND generation.status = 'MATERIALIZING'
    AND generation.actual_chunk_count = 0;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG full generation finalize counter drifted'
      USING ERRCODE = '23514';
  END IF;

  DELETE FROM public.rag_embedding_staging AS staging
  WHERE staging.generation_id = p_generation_id
    AND staging.materialization_run_id = p_materialization_run_id
    AND staging.writer_role::text = p_expected_writer_role;
  GET DIAGNOSTICS staged_row_count = ROW_COUNT;
  IF staged_row_count <> p_expected_row_count THEN
    RAISE EXCEPTION 'RAG full generation finalize cleanup failed'
      USING ERRCODE = '23514';
  END IF;
  RETURN inserted_row_count;
END
$_$;


