CREATE FUNCTION public.find_decision_idempotency_result(requested_scope_hash text, requested_owner_scope_hash text, requested_at timestamp with time zone) RETURNS TABLE(generation integer, request_hash text, result_canonical_json text, expires_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT
    result.generation,
    result.request_hash,
    result.result_canonical_json,
    result.expires_at
  FROM public.decision_idempotency_results result
  WHERE
    result.scope_hash = requested_scope_hash
    AND result.owner_scope_hash = requested_owner_scope_hash
    AND result.expires_at > requested_at
  ORDER BY result.generation DESC
  LIMIT 1
$$;


ALTER FUNCTION public.find_decision_idempotency_result(requested_scope_hash text, requested_owner_scope_hash text, requested_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.find_mock_order_idempotency_result(requested_scope_hash text, requested_owner_scope_hash text, requested_now timestamp with time zone, requested_capability_token text) RETURNS TABLE(request_hash text, result_canonical_json text, expires_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  RETURN QUERY
  SELECT
    stored.request_hash,
    stored.result_canonical_json,
    stored.created_at + interval '24 hours'
  FROM public.orders stored
  WHERE stored.idempotency_scope_hash = requested_scope_hash
    AND stored.idempotency_owner_scope_hash = requested_owner_scope_hash
    AND stored.created_at + interval '24 hours' > requested_now
  LIMIT 1;
END
$$;


ALTER FUNCTION public.find_mock_order_idempotency_result(requested_scope_hash text, requested_owner_scope_hash text, requested_now timestamp with time zone, requested_capability_token text) OWNER TO flyway;


