CREATE FUNCTION public.foreign_news_lane_states_are_safe(p_lanes jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT
    jsonb_typeof(p_lanes) = 'array'
    AND jsonb_array_length(p_lanes) = 4
    AND p_lanes -> 0 = jsonb_build_object(
      'laneId', 'FINNHUB_PERSONAL_LOCAL',
      'state', p_lanes -> 0 ->> 'state'
    )
    AND p_lanes -> 1 = jsonb_build_object(
      'laneId', 'SEC_OFFICIAL',
      'state', p_lanes -> 1 ->> 'state'
    )
    AND p_lanes -> 2 = jsonb_build_object(
      'laneId', 'FED_OFFICIAL',
      'state', p_lanes -> 2 ->> 'state'
    )
    AND p_lanes -> 3 = jsonb_build_object(
      'laneId', 'GDELT_OFFLINE_REFERENCE',
      'state', p_lanes -> 3 ->> 'state'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_lanes) AS lane
      WHERE jsonb_typeof(lane) <> 'object'
         OR lane ->> 'state' IS NULL
         OR lane ->> 'state' NOT IN ('AVAILABLE', 'ABSTAIN', 'NOT_ACTIVATED')
    )
$$;


ALTER FUNCTION public.foreign_news_lane_states_are_safe(p_lanes jsonb) OWNER TO flyway;


CREATE FUNCTION public.guard_async_job_s7_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.job_id IS DISTINCT FROM OLD.job_id
     OR NEW.job_type IS DISTINCT FROM OLD.job_type
     OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
     OR NEW.payload_json IS DISTINCT FROM OLD.payload_json
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'async job immutable identity cannot change' USING ERRCODE = '42501';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (
      (OLD.status = 'REQUESTED' AND NEW.status IN ('RUNNING', 'FAILED'))
      OR (OLD.status = 'RUNNING' AND NEW.status IN ('COMPLETED', 'FAILED'))
      OR (OLD.status = 'FAILED' AND NEW.status IN ('RUNNING', 'NEEDS_REVIEW'))
    ) THEN
      RAISE EXCEPTION 'invalid async job transition' USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.async_job_transition_audit(job_id, previous_status, next_status, attempt_count, failure_code)
    VALUES (OLD.job_id, OLD.status, NEW.status, NEW.attempt_count, NEW.error_code);
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_async_job_s7_update() OWNER TO flyway;


CREATE FUNCTION public.guard_event_outbox_s7_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.event_id IS DISTINCT FROM OLD.event_id
     OR NEW.event_type IS DISTINCT FROM OLD.event_type
     OR NEW.aggregate_type IS DISTINCT FROM OLD.aggregate_type
     OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id
     OR NEW.partition_key IS DISTINCT FROM OLD.partition_key
     OR NEW.payload_json IS DISTINCT FROM OLD.payload_json
     OR NEW.schema_version IS DISTINCT FROM OLD.schema_version
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'event outbox immutable identity cannot change' USING ERRCODE = '42501';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (
      (OLD.status IN ('PENDING', 'FAILED') AND NEW.status IN ('PUBLISHED', 'FAILED', 'DLQ_REQUESTED'))
      OR (OLD.status = 'DLQ_REQUESTED' AND NEW.status = 'PUBLISHED')
    ) THEN
      RAISE EXCEPTION 'invalid event outbox transition' USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.event_outbox_transition_audit(event_id, previous_status, next_status, failure_code)
    VALUES (OLD.event_id, OLD.status, NEW.status, NEW.failure_code);
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_event_outbox_s7_update() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_chunk_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  authoritative_topic text;
  authoritative_access_level text;
  authoritative_tier text;
  authoritative_source_type text;
  authoritative_processing text;
  ingest_status text;
  ingest_expected_chunk_count integer;
BEGIN
  SELECT
    source.topic,
    revision.access_level,
    revision.tier,
    source.source_type,
    revision.initial_processing,
    ingest.status,
    ingest.expected_chunk_count
  INTO
    authoritative_topic,
    authoritative_access_level,
    authoritative_tier,
    authoritative_source_type,
    authoritative_processing,
    ingest_status,
    ingest_expected_chunk_count
  FROM public.rag_source_revisions AS revision
  JOIN public.rag_sources AS source
    ON source.source_id = revision.source_id
  JOIN public.rag_ingest_runs AS ingest
    ON ingest.ingest_run_id = NEW.ingest_run_id
   AND ingest.source_revision_id = revision.source_revision_id
  WHERE revision.source_revision_id = NEW.source_revision_id
  FOR UPDATE OF ingest;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG chunk source revision authority is missing'
      USING ERRCODE = '23503';
  END IF;
  IF ingest_status <> 'RUNNING'
     OR NEW.chunk_seq > ingest_expected_chunk_count THEN
    RAISE EXCEPTION 'RAG chunks can append only to the bounded RUNNING ingest'
      USING ERRCODE = '23514';
  END IF;
  IF authoritative_source_type <> 'PROJECT_SOURCE_CARD'
     OR authoritative_tier <> 'PROJECT'
     OR authoritative_processing <> 'PROJECT_AUTHORED_CARD' THEN
    RAISE EXCEPTION 'RAG chunks require project-authored card lineage'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.topic IS DISTINCT FROM authoritative_topic
     OR NEW.access_level IS DISTINCT FROM authoritative_access_level
     OR NEW.tier IS DISTINCT FROM authoritative_tier THEN
    RAISE EXCEPTION 'RAG chunk scope must match its source revision authority'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_rag_chunk_scope() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_embedding_staging() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  generation_status text;
  generation_profile text;
BEGIN
  IF session_user <> 'decision_rag_writer' THEN
    RAISE EXCEPTION 'RAG embedding staging requires the dedicated writer role'
      USING ERRCODE = '42501';
  END IF;
  NEW.writer_role := session_user;

  SELECT generation.status, generation.embedding_profile_id
  INTO generation_status, generation_profile
  FROM public.rag_corpus_generations AS generation
  WHERE generation.corpus_generation_id = NEW.generation_id
  FOR UPDATE;
  IF NOT FOUND
     OR generation_status <> 'MATERIALIZING'
     OR generation_profile IS DISTINCT FROM NEW.embedding_profile_id THEN
    RAISE EXCEPTION 'RAG embedding staging generation is not open'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.rag_generation_chunks AS membership
    WHERE membership.corpus_generation_id = NEW.generation_id
      AND membership.chunk_revision_id = NEW.chunk_revision_id
      AND membership.embedding_profile_id = NEW.embedding_profile_id
      AND membership.embedding_input_hash = NEW.embedding_input_hash
      AND membership.context_set_hash IS NOT DISTINCT FROM NEW.context_set_hash
  ) THEN
    RAISE EXCEPTION 'RAG embedding staging membership or input hash drifted'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_rag_embedding_staging() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_generation_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  membership_count bigint;
  embedding_count bigint;
  embedded_chunk_count bigint;
BEGIN
  IF NEW.status IN ('MATERIALIZED', 'ACTIVE') THEN
    IF TG_OP = 'INSERT' THEN
      RAISE EXCEPTION 'RAG generation must be materialized before activation'
        USING ERRCODE = '23514';
    END IF;
    IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
      RETURN NEW;
    END IF;

    SELECT
      count(*),
      count(embedding.chunk_embedding_id),
      count(DISTINCT embedding.chunk_revision_id)
    INTO membership_count, embedding_count, embedded_chunk_count
    FROM public.rag_generation_chunks AS membership
    LEFT JOIN public.rag_chunk_embeddings AS embedding
      ON embedding.corpus_generation_id = membership.corpus_generation_id
     AND embedding.chunk_revision_id = membership.chunk_revision_id
     AND embedding.embedding_profile_id = membership.embedding_profile_id
     AND embedding.embedding_input_hash = membership.embedding_input_hash
     AND embedding.context_set_hash IS NOT DISTINCT FROM membership.context_set_hash
    WHERE membership.corpus_generation_id = NEW.corpus_generation_id
      AND membership.embedding_profile_id = NEW.embedding_profile_id;

    IF NEW.actual_chunk_count <> NEW.expected_chunk_count
       OR membership_count <> NEW.expected_chunk_count
       OR embedding_count <> NEW.expected_chunk_count
       OR embedded_chunk_count <> NEW.expected_chunk_count THEN
      RAISE EXCEPTION 'RAG generation materialization graph is incomplete'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'ACTIVE'
       AND (
         NEW.evaluation_status <> 'PASSED'
         OR NEW.evaluated_at IS NULL
         OR NEW.activated_at IS NULL
       ) THEN
      RAISE EXCEPTION 'RAG generation activation gate is incomplete'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_rag_generation_activation() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_generation_materialization() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  generation_status text;
  membership_ingest_status text;
  membership_source_type text;
  membership_tier text;
BEGIN
  IF TG_TABLE_NAME = 'rag_generation_chunks' THEN
    SELECT ingest.status, source.source_type, revision.tier
    INTO membership_ingest_status, membership_source_type, membership_tier
    FROM public.rag_chunk_revisions AS chunk
    JOIN public.rag_ingest_runs AS ingest
      ON ingest.ingest_run_id = chunk.ingest_run_id
     AND ingest.source_revision_id = chunk.source_revision_id
    JOIN public.rag_source_revisions AS revision
      ON revision.source_revision_id = chunk.source_revision_id
    JOIN public.rag_sources AS source
      ON source.source_id = revision.source_id
    WHERE chunk.chunk_revision_id = NEW.chunk_revision_id
    FOR UPDATE OF ingest;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'RAG generation chunk lineage is missing'
        USING ERRCODE = '23503';
    END IF;
    IF membership_ingest_status <> 'SUCCEEDED'
       OR membership_source_type <> 'PROJECT_SOURCE_CARD'
       OR membership_tier <> 'PROJECT' THEN
      RAISE EXCEPTION 'RAG generation membership requires succeeded project-card ingest'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  SELECT generation.status
  INTO generation_status
  FROM public.rag_corpus_generations AS generation
  WHERE generation.corpus_generation_id = NEW.corpus_generation_id
    AND generation.embedding_profile_id = NEW.embedding_profile_id
  FOR UPDATE;

  IF generation_status IS DISTINCT FROM 'MATERIALIZING' THEN
    RAISE EXCEPTION 'RAG generation is not open for materialization'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_rag_generation_materialization() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_generation_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'REGISTERED'
       OR NEW.actual_chunk_count <> 0
       OR NEW.evaluation_status <> 'PENDING'
       OR NEW.evaluated_at IS NOT NULL
       OR NEW.activated_at IS NOT NULL
       OR NEW.failed_at IS NOT NULL
       OR NEW.disabled_at IS NOT NULL
       OR NEW.failure_class IS NOT NULL THEN
      RAISE EXCEPTION 'RAG generation must start in a clean REGISTERED state'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status IN ('FAILED_FINAL', 'DISABLED') THEN
    RAISE EXCEPTION 'RAG generation terminal state is immutable'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.status IS NOT DISTINCT FROM NEW.status
     AND OLD.status <> 'MATERIALIZING' THEN
    RAISE EXCEPTION 'RAG generation state receipt cannot be rewritten in place'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.status IS DISTINCT FROM NEW.status
     AND NOT (
       (OLD.status = 'REGISTERED' AND NEW.status IN ('PLANNED', 'DISABLED'))
       OR
       (OLD.status = 'PLANNED' AND NEW.status IN ('MATERIALIZING', 'FAILED_FINAL', 'DISABLED'))
       OR
       (OLD.status = 'MATERIALIZING' AND NEW.status IN ('MATERIALIZED', 'FAILED_FINAL', 'DISABLED'))
       OR
       (OLD.status = 'MATERIALIZED' AND NEW.status IN ('EVAL_PASSED', 'FAILED_FINAL', 'DISABLED'))
       OR
       (OLD.status = 'EVAL_PASSED' AND NEW.status IN ('ACTIVE', 'DISABLED'))
       OR
       (OLD.status = 'ACTIVE' AND NEW.status = 'DISABLED')
     ) THEN
    RAISE EXCEPTION 'RAG generation status transition is not allowed'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status IN ('REGISTERED', 'PLANNED', 'MATERIALIZING', 'MATERIALIZED')
     AND (
       NEW.evaluation_status <> 'PENDING'
       OR NEW.evaluated_at IS NOT NULL
       OR NEW.activated_at IS NOT NULL
       OR NEW.failed_at IS NOT NULL
       OR NEW.disabled_at IS NOT NULL
       OR NEW.failure_class IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'RAG pre-evaluation generation cannot carry terminal receipt'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'EVAL_PASSED'
     AND (
       NEW.evaluation_status <> 'PASSED'
       OR NEW.evaluated_at IS NULL
       OR NEW.activated_at IS NOT NULL
       OR NEW.failed_at IS NOT NULL
       OR NEW.disabled_at IS NOT NULL
       OR NEW.failure_class IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'RAG EVAL_PASSED generation receipt is incomplete'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'ACTIVE'
     AND (
       NEW.evaluation_status <> 'PASSED'
       OR NEW.evaluated_at IS NULL
       OR NEW.activated_at IS NULL
       OR NEW.failed_at IS NOT NULL
       OR NEW.disabled_at IS NOT NULL
       OR NEW.failure_class IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'RAG ACTIVE generation receipt is incomplete'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'FAILED_FINAL'
     AND (
       NEW.evaluation_status <> 'FAILED'
       OR NEW.failed_at IS NULL
       OR NEW.failure_class IS NULL
       OR NEW.activated_at IS NOT NULL
       OR NEW.disabled_at IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'RAG FAILED_FINAL generation receipt is incomplete'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'DISABLED'
     AND (
       NEW.disabled_at IS NULL
       OR NEW.failed_at IS NOT NULL
       OR NEW.failure_class IS NOT NULL
       OR NEW.actual_chunk_count IS DISTINCT FROM OLD.actual_chunk_count
       OR NEW.evaluation_status IS DISTINCT FROM OLD.evaluation_status
       OR NEW.evaluated_at IS DISTINCT FROM OLD.evaluated_at
       OR NEW.activated_at IS DISTINCT FROM OLD.activated_at
     ) THEN
    RAISE EXCEPTION 'RAG DISABLED generation must preserve prior materialization and exposure receipts'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_rag_generation_transition() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_ingest_run_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  ingest_source_type text;
  ingest_source_tier text;
  persisted_chunk_count integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'PLANNED'
       OR NEW.started_at IS NOT NULL
       OR NEW.completed_at IS NOT NULL
       OR NEW.actual_chunk_count IS NOT NULL
       OR NEW.failure_class IS NOT NULL THEN
      RAISE EXCEPTION 'RAG ingest run must start in a clean PLANNED state'
        USING ERRCODE = '23514';
    END IF;
    SELECT source.source_type, revision.tier
    INTO ingest_source_type, ingest_source_tier
    FROM public.rag_source_revisions AS revision
    JOIN public.rag_sources AS source
      ON source.source_id = revision.source_id
    WHERE revision.source_revision_id = NEW.source_revision_id
    FOR KEY SHARE OF source, revision;
    IF NOT FOUND
       OR ingest_source_type <> 'PROJECT_SOURCE_CARD'
       OR ingest_source_tier <> 'PROJECT' THEN
      RAISE EXCEPTION 'RAG ingest accepts verified project-card lineage only'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status IN ('SUCCEEDED', 'FAILED') THEN
    RAISE EXCEPTION 'RAG ingest terminal state is immutable'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.status IS DISTINCT FROM NEW.status
     AND NOT (
       (OLD.status = 'PLANNED' AND NEW.status = 'RUNNING')
       OR
       (OLD.status = 'RUNNING' AND NEW.status IN ('SUCCEEDED', 'FAILED'))
     ) THEN
    RAISE EXCEPTION 'RAG ingest status transition is not allowed'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'PLANNED'
     AND (
       NEW.started_at IS NOT NULL
       OR NEW.completed_at IS NOT NULL
       OR NEW.actual_chunk_count IS NOT NULL
       OR NEW.failure_class IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'RAG PLANNED ingest state cannot carry execution receipt'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'RUNNING'
     AND (
       NEW.started_at IS NULL
       OR NEW.completed_at IS NOT NULL
       OR NEW.actual_chunk_count IS NOT NULL
       OR NEW.failure_class IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'RAG RUNNING ingest state requires only a start receipt'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status IN ('SUCCEEDED', 'FAILED') THEN
    SELECT count(*)::integer
    INTO persisted_chunk_count
    FROM public.rag_chunk_revisions AS chunk
    WHERE chunk.ingest_run_id = NEW.ingest_run_id;
    IF NEW.actual_chunk_count IS DISTINCT FROM persisted_chunk_count THEN
      RAISE EXCEPTION 'RAG ingest terminal count must match persisted chunks'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'SUCCEEDED'
       AND persisted_chunk_count <> NEW.expected_chunk_count THEN
      RAISE EXCEPTION 'RAG ingest success requires every expected chunk'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_rag_ingest_run_transition() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_source_revision_locator() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  original_locator record;
  latest_revision_seq integer;
  parent_source_type text;
  parent_retired_at timestamptz;
BEGIN
  -- source identity row lock이 같은 source의 revision append를 직렬화해 sequence gap을 막는다.
  SELECT source.source_type, source.retired_at
  INTO parent_source_type, parent_retired_at
  FROM public.rag_sources AS source
  WHERE source.source_id = NEW.source_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG source identity must exist before its revision'
      USING ERRCODE = '23503';
  END IF;
  IF parent_retired_at IS NOT NULL THEN
    RAISE EXCEPTION 'RAG source revision cannot append to a retired source'
      USING ERRCODE = '23514';
  END IF;
  IF parent_source_type = 'UPSTREAM_REFERENCE'
     AND (
       NEW.tier <> 'OFFICIAL'
       OR NEW.access_level <> 'PUBLIC'
       OR NEW.license_decision NOT LIKE 'REFERENCE_ONLY_%'
       OR NEW.retention_mode <> 'REFERENCE_METADATA_ONLY'
       OR NEW.external_processing_allowed
       OR NEW.initial_processing <> 'REFERENCE_ONLY'
     ) THEN
    RAISE EXCEPTION 'RAG upstream revision metadata crossed the reference-only boundary'
      USING ERRCODE = '23514';
  END IF;
  IF parent_source_type = 'PROJECT_SOURCE_CARD'
     AND (
       NEW.tier <> 'PROJECT'
       OR NEW.license_decision
          <> CASE
               WHEN NEW.access_level = 'PUBLIC' THEN 'PROJECT_AUTHORED_PUBLIC'
               ELSE 'PROJECT_AUTHORED_INTERNAL'
             END
       OR NEW.retention_mode <> 'PROJECT_CARD'
       OR (
         NEW.external_processing_allowed
         AND (
           NEW.registry_version <> 's4-7c-source-card-v2'
           OR NEW.access_level <> 'PUBLIC'
           OR position(
             'approvalId=AUTH_EXTERNAL_PROCESSING_30_PROJECT_CARDS_20260731' IN NEW.license_note
           ) = 0
         )
       )
       OR NEW.initial_processing <> 'PROJECT_AUTHORED_CARD'
     ) THEN
    RAISE EXCEPTION 'RAG project-card revision metadata crossed the authored-card boundary'
      USING ERRCODE = '23514';
  END IF;

  -- INSERT ... ON CONFLICT DO NOTHING 재실행은 exact immutable row일 때만 idempotent하게 통과시킨다.
  IF EXISTS (
    SELECT 1
    FROM public.rag_source_revisions AS existing
    WHERE existing.source_revision_id = NEW.source_revision_id
      AND existing.source_id = NEW.source_id
      AND existing.revision_seq = NEW.revision_seq
      AND existing.metadata_hash = NEW.metadata_hash
      AND existing.locator_sha256 = NEW.locator_sha256
  ) THEN
    RETURN NEW;
  END IF;

  SELECT
    revision.canonical_url,
    revision.allowed_origin,
    revision.allowed_path,
    revision.locator_sha256
  INTO original_locator
  FROM public.rag_source_revisions AS revision
  WHERE revision.source_id = NEW.source_id
  ORDER BY revision.revision_seq
  LIMIT 1
  FOR SHARE;

  IF NOT FOUND THEN
    IF NEW.revision_seq <> 1 THEN
      RAISE EXCEPTION 'RAG source revisions must start at sequence 1'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  SELECT max(revision.revision_seq)
  INTO latest_revision_seq
  FROM public.rag_source_revisions AS revision
  WHERE revision.source_id = NEW.source_id;

  IF NEW.revision_seq <> latest_revision_seq + 1 THEN
    RAISE EXCEPTION 'RAG source revisions must append the next sequence'
      USING ERRCODE = '23514';
  END IF;

  IF original_locator.canonical_url IS DISTINCT FROM NEW.canonical_url
     OR original_locator.allowed_origin IS DISTINCT FROM NEW.allowed_origin
     OR original_locator.allowed_path IS DISTINCT FROM NEW.allowed_path
     OR original_locator.locator_sha256 IS DISTINCT FROM NEW.locator_sha256 THEN
    RAISE EXCEPTION 'RAG source locator movement requires a new source sequence ID'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.guard_rag_source_revision_locator() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_v2_immutable_external_exact30_voyage_component_hash_t() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.component_scope = 'EXACT30'
     AND NEW.embedding_profile_id = 'voyage_context_4_1024_v1'
     AND NEW.state IN ('EVALUATED', 'ACTIVE')
     AND EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_external_exact30_voyage_component_manifests AS manifest
       WHERE manifest.component_generation_id = NEW.component_generation_id
     )
     AND public.rag_v2_immutable_external_exact30_voyage_component_hashes_are_valid(
       NEW.component_generation_id
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage component hash transition is invalid'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.guard_rag_v2_immutable_external_exact30_voyage_component_hash_t() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_v2_immutable_external_exact30_voyage_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  generation_profile_id text;
  staged_source public.rag_v2_immutable_source_revisions%ROWTYPE;
BEGIN
  IF NEW.owner_user_id IS NOT NULL OR NEW.component_scope <> 'EXACT30' THEN
    RETURN NEW;
  END IF;
  SELECT generation.embedding_profile_id
  INTO generation_profile_id
  FROM public.rag_v2_immutable_component_generations AS generation
  WHERE generation.component_generation_id = NEW.component_generation_id
    AND generation.component_scope = 'EXACT30'
    AND generation.owner_user_id IS NULL;
  IF generation_profile_id IS DISTINCT FROM 'voyage_context_4_1024_v1' THEN
    RETURN NEW;
  END IF;
  SELECT * INTO staged_source
  FROM public.rag_v2_immutable_source_revisions AS source
  WHERE source.source_revision_id = NEW.source_revision_id;
  IF NOT FOUND
     OR staged_source.owner_user_id IS NOT NULL
     OR staged_source.source_scope <> 'EXACT30'
     OR NOT staged_source.external_processing_eligible
     OR staged_source.machine_fetch_allowed
     OR NOT staged_source.local_processing_allowed
     OR NOT staged_source.external_embedding_allowed
     OR NOT staged_source.external_generation_allowed
     OR public.rag_v2_immutable_external_exact30_voyage_source_is_approved(
       staged_source.source_id,
       staged_source.canonical_https_url,
       staged_source.raw_content_sha256,
       staged_source.exact30_source_card_sha256,
       staged_source.canonical_text_sha256
     ) IS NOT TRUE
     OR staged_source.source_revision_id <> public.rag_v2_immutable_external_exact30_voyage_source_revision_id(
       staged_source.source_id,
       staged_source.raw_content_sha256,
       staged_source.exact30_source_card_sha256
     )
     OR staged_source.document_id <> public.rag_v2_immutable_external_exact30_voyage_document_id(
       staged_source.source_id,
       staged_source.source_revision_id
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage membership source is invalid'
      USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_generation_memberships AS membership
       JOIN public.rag_v2_immutable_source_revisions AS existing_source
         ON existing_source.source_revision_id = membership.source_revision_id
       WHERE membership.component_generation_id = NEW.component_generation_id
         AND membership.component_scope = 'EXACT30'
         AND membership.owner_user_id IS NULL
         AND existing_source.source_id = staged_source.source_id
         AND existing_source.source_revision_id <> NEW.source_revision_id
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage duplicate source is invalid'
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_generation_memberships AS membership
       WHERE membership.component_generation_id = NEW.component_generation_id
         AND membership.component_scope = 'EXACT30'
         AND membership.owner_user_id IS NULL
         AND membership.source_revision_id = NEW.source_revision_id
     )
     AND EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_external_exact30_source_allowlist AS required_source
       WHERE pg_catalog.convert_to(required_source.source_id, 'UTF8')
             < pg_catalog.convert_to(staged_source.source_id, 'UTF8')
         AND NOT EXISTS (
           SELECT 1
           FROM public.rag_v2_immutable_generation_memberships AS membership
           JOIN public.rag_v2_immutable_source_revisions AS existing_source
             ON existing_source.source_revision_id = membership.source_revision_id
           WHERE membership.component_generation_id = NEW.component_generation_id
             AND membership.component_scope = 'EXACT30'
             AND membership.owner_user_id IS NULL
             AND existing_source.source_id = required_source.source_id
         )
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage canonical source order is invalid'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.guard_rag_v2_immutable_external_exact30_voyage_membership() OWNER TO flyway;


CREATE FUNCTION public.guard_rag_v2_immutable_external_exact30_voyage_source_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.owner_user_id IS NULL
     AND NEW.source_scope = 'EXACT30'
     AND NEW.external_processing_eligible
     AND NOT NEW.machine_fetch_allowed
     AND NEW.local_processing_allowed
     AND NEW.external_embedding_allowed
     AND NEW.external_generation_allowed THEN
    IF public.rag_v2_immutable_external_exact30_voyage_source_is_approved(
         NEW.source_id,
         NEW.canonical_https_url,
         NEW.raw_content_sha256,
         NEW.exact30_source_card_sha256,
         NEW.canonical_text_sha256
       ) IS NOT TRUE
       OR NEW.source_revision_id <> public.rag_v2_immutable_external_exact30_voyage_source_revision_id(
         NEW.source_id,
         NEW.raw_content_sha256,
         NEW.exact30_source_card_sha256
       )
       OR NEW.document_id <> public.rag_v2_immutable_external_exact30_voyage_document_id(
         NEW.source_id,
         NEW.source_revision_id
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage source identity is invalid'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.guard_rag_v2_immutable_external_exact30_voyage_source_identity() OWNER TO flyway;


