CREATE FUNCTION public.ingest_signal_v2_exact(p_contract_version text, p_producer text, p_source_workspace text, p_symbol text, p_session_date date, p_as_of timestamp with time zone, p_timeframe text, p_status text, p_reason text, p_signal text, p_confidence numeric, p_predicted_return numeric, p_evaluation_id text, p_model_version text, p_model_report_id text, p_artifact_sha256 text, p_payload_sha256 text, p_provenance_sha256 text, p_fixture boolean, p_provenance_class text, p_payload_canonical_text text) RETURNS TABLE(outcome text, signal_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  computed_identity text;
  computed_payload text;
  existing_payload text;
  generated_signal_id text;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR p_contract_version <> 'signal-v2-runtime-v1'
     OR p_symbol !~ '^[0-9A-Z._:-]{1,20}$'
     OR p_evaluation_id !~ '^[A-Za-z0-9._:-]{1,128}$'
     OR octet_length(p_payload_canonical_text) NOT BETWEEN 2 AND 65536
     OR p_payload_canonical_text::jsonb IS NULL THEN
    RAISE EXCEPTION 'Signal v2 ingest arguments are invalid' USING ERRCODE = '22023';
  END IF;

  computed_identity := encode(
    digest(
      convert_to(
        concat_ws(E'\n', 'signal-v2-identity-v1', p_contract_version, p_producer,
          p_source_workspace, p_symbol, p_timeframe, p_evaluation_id),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  computed_payload := encode(digest(convert_to(p_payload_canonical_text, 'UTF8'), 'sha256'), 'hex');
  IF computed_payload <> p_payload_sha256 THEN
    RAISE EXCEPTION 'Signal v2 payload digest mismatch' USING ERRCODE = '22023';
  END IF;

  -- 같은 logical identity의 concurrent replay/conflict를 한 transaction 순서로 직렬화한다.
  PERFORM pg_advisory_xact_lock(hashtextextended(computed_identity, 0));
  SELECT stored.payload_sha256 INTO existing_payload
  FROM public.ingested_signals AS stored
  WHERE stored.logical_identity_sha256 = computed_identity
  FOR SHARE;
  IF FOUND THEN
    IF existing_payload = computed_payload THEN
      RETURN QUERY SELECT 'REPLAYED'::text, stored.signal_id
      FROM public.ingested_signals AS stored
      WHERE stored.logical_identity_sha256 = computed_identity;
      RETURN;
    END IF;
    RAISE EXCEPTION 'Signal v2 logical identity payload conflict' USING ERRCODE = '23505';
  END IF;

  generated_signal_id := 'sigv2_' || substr(computed_identity, 1, 24);
  INSERT INTO public.ingested_signals (
    signal_id, producer, source_workspace, symbol, as_of, timeframe, confidence,
    predicted_return, feature_summary_json, payload_json, contract_version, status,
    reason, signal, evaluation_id, model_version, model_report_id, artifact_sha256,
    payload_sha256, provenance_sha256, logical_identity_sha256, fixture,
    provenance_class, payload_canonical_text, artifact_verified, session_date
  ) VALUES (
    generated_signal_id, p_producer, p_source_workspace, p_symbol, p_as_of, p_timeframe,
    p_confidence, p_predicted_return, '[]'::jsonb, p_payload_canonical_text::jsonb,
    p_contract_version, p_status, p_reason, p_signal, p_evaluation_id, p_model_version,
    p_model_report_id, p_artifact_sha256, computed_payload, p_provenance_sha256,
    computed_identity, p_fixture, p_provenance_class, p_payload_canonical_text, true,
    p_session_date
  );
  RETURN QUERY SELECT 'INSERTED'::text, generated_signal_id;
END
$_$;


ALTER FUNCTION public.ingest_signal_v2_exact(p_contract_version text, p_producer text, p_source_workspace text, p_symbol text, p_session_date date, p_as_of timestamp with time zone, p_timeframe text, p_status text, p_reason text, p_signal text, p_confidence numeric, p_predicted_return numeric, p_evaluation_id text, p_model_version text, p_model_report_id text, p_artifact_sha256 text, p_payload_sha256 text, p_provenance_sha256 text, p_fixture boolean, p_provenance_class text, p_payload_canonical_text text) OWNER TO flyway;


CREATE FUNCTION public.initialize_order_fill_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT pg_has_role(current_user, 'flyway', 'USAGE') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.brokerage_mode = 'INTERNAL_PAPER' AND NEW.status = 'FILLED' THEN
      NEW.filled_quantity := NEW.quantity;
      NEW.leaves_quantity := 0;
      NEW.unfilled_terminated_quantity := 0;
      NEW.average_fill_price_krw :=
        (NEW.result_canonical_json::jsonb #>> '{fill,priceKrw}')::bigint;
    ELSE
      NEW.filled_quantity := 0;
      NEW.leaves_quantity := NEW.quantity;
      NEW.unfilled_terminated_quantity := 0;
      NEW.average_fill_price_krw := NULL;
    END IF;
    NEW.reconciliation_status := 'NOT_APPLICABLE';
    NEW.reconciled_at := NULL;
  ELSIF OLD.status <> NEW.status
        AND NEW.status IN ('CANCELLED', 'REJECTED')
        AND NEW.filled_quantity = OLD.filled_quantity
        AND NEW.leaves_quantity = OLD.leaves_quantity THEN
    NEW.leaves_quantity := 0;
    NEW.unfilled_terminated_quantity := NEW.quantity - NEW.filled_quantity;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.initialize_order_fill_projection() OWNER TO flyway;


CREATE FUNCTION public.insert_principle_audit_authorized(p_capability text, p_actor_user_id text, p_request_id text, p_action text, p_principle_id text, p_new_version integer, p_changed_fields text[], p_created_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE actor_role text; changed integer;
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN
    RAISE EXCEPTION 'principle audit capability denied' USING ERRCODE='42501';
  END IF;
  IF p_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
     OR p_action NOT IN ('PRINCIPLE_CREATED','PRINCIPLE_UPDATED','PRINCIPLE_ARCHIVED','PRINCIPLE_REACTIVATED')
     OR p_new_version<1 OR p_changed_fields IS NULL OR cardinality(p_changed_fields) NOT BETWEEN 1 AND 5
     OR NOT EXISTS (SELECT 1 FROM public.principles item
       WHERE item.principle_id=p_principle_id AND item.user_id=p_actor_user_id) THEN
    RAISE EXCEPTION 'invalid principle audit insert' USING ERRCODE='22023';
  END IF;
  SELECT actor.role INTO actor_role FROM public.users actor WHERE actor.user_id=p_actor_user_id;
  INSERT INTO public.audit_logs(audit_log_id,user_id,actor_role,action,target_type,target_id,request_id,payload_json,created_at)
  VALUES ('aud_'||replace(gen_random_uuid()::text,'-',''),p_actor_user_id,actor_role,p_action,'PRINCIPLE',
    p_principle_id,p_request_id,jsonb_build_object('principleId',p_principle_id,
      'newVersion',p_new_version,'changedFields',to_jsonb(p_changed_fields)),p_created_at);
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN changed=1;
END
$_$;


ALTER FUNCTION public.insert_principle_audit_authorized(p_capability text, p_actor_user_id text, p_request_id text, p_action text, p_principle_id text, p_new_version integer, p_changed_fields text[], p_created_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.insert_principle_authorized(p_capability text, p_actor_user_id text, p_principle_id text, p_preset_id text, p_title text, p_mode text, p_status text, p_version integer, p_created_at timestamp with time zone, p_updated_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE changed integer;
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN
    RAISE EXCEPTION 'principle actor capability denied' USING ERRCODE='42501';
  END IF;
  IF p_principle_id !~ '^prc_[0-9a-f]{32}$' OR p_preset_id !~ '^[a-z][a-z0-9_-]{2,63}$'
     OR char_length(p_title) NOT BETWEEN 1 AND 120 OR p_mode NOT IN ('GUIDE','STRICT')
     OR p_status NOT IN ('ACTIVE','ARCHIVED') OR p_version<>1 OR p_created_at<>p_updated_at
     OR NOT EXISTS (SELECT 1 FROM public.principle_presets preset
       WHERE preset.preset_id=p_preset_id AND preset.is_active) THEN
    RAISE EXCEPTION 'invalid principle insert' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.principles(principle_id,user_id,preset_id,title,mode,status,current_version,created_at,updated_at)
  VALUES (p_principle_id,p_actor_user_id,p_preset_id,p_title,p_mode,p_status,p_version,p_created_at,p_updated_at);
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN changed=1;
END
$_$;


ALTER FUNCTION public.insert_principle_authorized(p_capability text, p_actor_user_id text, p_principle_id text, p_preset_id text, p_title text, p_mode text, p_status text, p_version integer, p_created_at timestamp with time zone, p_updated_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.insert_principle_version_authorized(p_capability text, p_actor_user_id text, p_version_id text, p_principle_id text, p_version integer, p_preset_id text, p_title text, p_mode text, p_status text, p_rules_json jsonb, p_changed_fields text[], p_created_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE changed integer;
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN
    RAISE EXCEPTION 'principle version capability denied' USING ERRCODE='42501';
  END IF;
  IF p_version_id !~ '^pvr_[0-9a-f]{32}$' OR p_version<1
     OR NOT EXISTS (SELECT 1 FROM public.principles item
       WHERE item.principle_id=p_principle_id AND item.user_id=p_actor_user_id)
     OR p_changed_fields IS NULL OR cardinality(p_changed_fields) NOT BETWEEN 1 AND 5 THEN
    RAISE EXCEPTION 'invalid principle version insert' USING ERRCODE='22023';
