ALTER FUNCTION public.insert_principle_version_authorized(p_capability text, p_actor_user_id text, p_version_id text, p_principle_id text, p_version integer, p_preset_id text, p_title text, p_mode text, p_status text, p_rules_json jsonb, p_changed_fields text[], p_created_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.invalidate_unused_decisions_for_kill_switch(requested_source_generation bigint, requested_invalidated_at timestamp with time zone, requested_request_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  inserted_count integer;
BEGIN
  IF requested_source_generation IS NULL
     OR requested_source_generation <= 0
     OR requested_request_id IS NULL
     OR char_length(requested_request_id) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'S2.4 invalid kill switch invalidation request';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.risk_kill_switch gate
    WHERE gate.kill_switch_id = 'GLOBAL'
      AND gate.active
      AND gate.generation = requested_source_generation
      AND gate.changed_at = requested_invalidated_at
      AND gate.request_id = requested_request_id
  ) THEN
    RAISE EXCEPTION 'S2.4 kill switch generation is not current and active';
  END IF;

  INSERT INTO public.decision_invalidations (
    invalidation_id,
    decision_id,
    evaluation_id,
    owner_user_id,
    reason_class,
    source_generation,
    invalidated_at,
    request_id
  )
  SELECT
    'dinv_' || pg_catalog.md5(decision.decision_id || ':' || requested_source_generation::text),
    decision.decision_id,
    decision.evaluation_id,
    decision.user_id,
    'KILL_SWITCH_ACTIVATED',
    requested_source_generation,
    requested_invalidated_at,
    requested_request_id
  FROM public.decisions decision
  WHERE decision.valid_until > requested_invalidated_at
    AND NOT EXISTS (
      SELECT 1
      FROM public.orders consumed
      WHERE consumed.decision_id = decision.decision_id
    )
  ON CONFLICT (decision_id, reason_class) DO NOTHING;

  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  RETURN inserted_count;
END
$$;


ALTER FUNCTION public.invalidate_unused_decisions_for_kill_switch(requested_source_generation bigint, requested_invalidated_at timestamp with time zone, requested_request_id text) OWNER TO flyway;


CREATE FUNCTION public.issue_actor_request_capability(p_actor_user_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE token text; actor record;
BEGIN
  IF session_user <> 'decision_identity' THEN
    RAISE EXCEPTION 'actor capability issuer role denied' USING ERRCODE = '42501';
  END IF;
  SELECT role, status, security_version INTO actor
  FROM public.users WHERE user_id = p_actor_user_id FOR SHARE;
  IF NOT FOUND OR actor.status <> 'ACTIVE' OR actor.role NOT IN ('USER', 'ADMIN') THEN
    RETURN NULL;
  END IF;
  DELETE FROM public.actor_request_capability expired
  WHERE expired.token_hash IN (
    SELECT candidate.token_hash
    FROM public.actor_request_capability candidate
    WHERE candidate.expires_at <= statement_timestamp()
    ORDER BY candidate.expires_at
    LIMIT 100
  );
  token := 'cap_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  INSERT INTO public.actor_request_capability(
    token_hash, actor_user_id, actor_role, actor_security_version, expires_at
  ) VALUES (
    'sha256:' || encode(public.digest(token, 'sha256'), 'hex'),
    p_actor_user_id, actor.role, actor.security_version, statement_timestamp() + interval '15 seconds'
  );
  RETURN token;
END
$$;


ALTER FUNCTION public.issue_actor_request_capability(p_actor_user_id text) OWNER TO flyway;


CREATE FUNCTION public.issue_rag_rpc_scope(p_owner_user_id text, p_session_id text, p_allowed_topics_json jsonb) RETURNS TABLE(scope_claim_id text, policy_id text, policy_version bigint, active_generation_id text, effective_profile_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR jsonb_typeof(p_allowed_topics_json) IS DISTINCT FROM 'array'
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_allowed_topics_json) AS item
       WHERE jsonb_typeof(item) IS DISTINCT FROM 'string'
     ) THEN
    RAISE EXCEPTION 'RAG RPC scope arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH issued AS MATERIALIZED (
    SELECT claim.*
    FROM public.create_rag_retrieval_scope_claim(
      p_owner_user_id,
      p_session_id,
      ARRAY(
        SELECT jsonb_array_elements_text(p_allowed_topics_json)
      )
    ) AS claim
  )
  SELECT
    issued.scope_claim_id,
    state.policy_id,
    issued.policy_version,
    issued.active_generation_id,
    issued.effective_profile_id
  FROM issued
  JOIN public.rag_embedding_policy_state AS state
    ON state.state_id = 'default'
   AND state.version = issued.policy_version
   AND state.active_generation_id = issued.active_generation_id
   AND state.effective_profile_id = issued.effective_profile_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG RPC scope policy changed during issuance'
      USING ERRCODE = '40001';
  END IF;
END
$$;


ALTER FUNCTION public.issue_rag_rpc_scope(p_owner_user_id text, p_session_id text, p_allowed_topics_json jsonb) OWNER TO flyway;


CREATE FUNCTION public.issue_rag_v2_immutable_import_ticket(p_owner_user_id text, p_ticket_id text, p_operation text, p_policy_version text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  issued_at timestamptz := clock_timestamp();
  ticket_digest text;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_ticket_id !~ '^rti_[0-9a-f]{32}$'
     OR p_operation <> 'OWNER_IMPORT'
     OR p_policy_version <> 'RAG_V2_OWNER_DOCUMENT_V1'
     OR NOT EXISTS (
       SELECT 1
       FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 import ticket arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  ticket_digest := encode(digest(p_ticket_id, 'sha256'), 'hex');
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-ticket|' || ticket_digest, 0)
  );
  INSERT INTO public.rag_v2_immutable_import_tickets (
    ticket_hash,
    owner_user_id,
    operation,
    policy_version,
    state,
    issued_at,
    expires_at
  )
  VALUES (
    ticket_digest,
    p_owner_user_id,
    p_operation,
    p_policy_version,
    'ISSUED',
    issued_at,
    issued_at + interval '5 minutes'
  );
  RETURN issued_at + interval '5 minutes';
END;
$_$;


ALTER FUNCTION public.issue_rag_v2_immutable_import_ticket(p_owner_user_id text, p_ticket_id text, p_operation text, p_policy_version text) OWNER TO flyway;


CREATE FUNCTION public.issue_rag_v2_immutable_import_ticket_v2(p_owner_user_id text, p_ticket_id text, p_operation text, p_policy_version text, p_embedding_profile_id text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  issued_at timestamptz := clock_timestamp();
  ticket_digest text;
  active_owner_profile text;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_ticket_id !~ '^rti_[0-9a-f]{32}$'
     OR p_operation <> 'OWNER_IMPORT'
     OR p_policy_version <> 'RAG_V2_OWNER_DOCUMENT_V2'
     OR p_embedding_profile_id NOT IN ('bge_m3_local_1024_v1', 'voyage_context_4_1024_v1')
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 import ticket v2 arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-owner-library|' || p_owner_user_id, 0)
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  SELECT bundle.owner_embedding_profile_id
  INTO active_owner_profile
  FROM public.rag_v2_immutable_owner_bundle_pointers AS pointer
  JOIN public.rag_v2_immutable_bundles AS bundle
    ON bundle.bundle_id = pointer.active_bundle_id
   AND bundle.owner_user_id = pointer.owner_user_id
  WHERE pointer.owner_user_id = p_owner_user_id
    AND pointer.state = 'READY'
    AND bundle.state = 'ACTIVE';
  IF active_owner_profile IS NOT NULL
     AND active_owner_profile IS DISTINCT FROM p_embedding_profile_id THEN
    RAISE EXCEPTION 'immutable RAG v2 owner library profile is locked'
      USING ERRCODE = '22023';
  END IF;

  ticket_digest := encode(digest(p_ticket_id, 'sha256'), 'hex');
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-ticket|' || ticket_digest, 0)
  );
  INSERT INTO public.rag_v2_immutable_import_tickets (
    ticket_hash, owner_user_id, operation, policy_version,
    embedding_profile_id, state, issued_at, expires_at
  ) VALUES (
    ticket_digest, p_owner_user_id, p_operation, p_policy_version,
    p_embedding_profile_id, 'ISSUED', issued_at, issued_at + interval '5 minutes'
  );
  RETURN issued_at + interval '5 minutes';
END;
$_$;


ALTER FUNCTION public.issue_rag_v2_immutable_import_ticket_v2(p_owner_user_id text, p_ticket_id text, p_operation text, p_policy_version text, p_embedding_profile_id text) OWNER TO flyway;


