CREATE FUNCTION public.issue_rag_v2_retrieval_scope(p_owner_user_id text, p_session_id text, p_allowed_topics text[]) RETURNS TABLE(scope_claim_id text, owner_user_id text, session_id text, exact30_generation_id text, oa112_generation_id text, owner_private_generation_id text, embedding_profile_id text, policy_version bigint, allowed_topics text[], expires_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT
    issued.scope_claim_id,
    issued.owner_user_id,
    issued.session_id,
    issued.exact30_generation_id,
    issued.oa112_generation_id,
    issued.owner_private_generation_id,
    issued.embedding_profile_id,
    issued.policy_version,
    issued.allowed_topics,
    issued.expires_at
  FROM public.issue_rag_v2_retrieval_scope_v2(
    p_owner_user_id,
    p_session_id,
    p_allowed_topics
  ) AS issued;
$$;


ALTER FUNCTION public.issue_rag_v2_retrieval_scope(p_owner_user_id text, p_session_id text, p_allowed_topics text[]) OWNER TO flyway;


CREATE FUNCTION public.issue_rag_v2_retrieval_scope_v2(p_owner_user_id text, p_session_id text, p_allowed_topics text[]) RETURNS TABLE(scope_claim_id text, owner_user_id text, session_id text, exact30_generation_id text, oa112_generation_id text, owner_private_generation_id text, embedding_profile_id text, owner_embedding_profile_id text, policy_version bigint, allowed_topics text[], expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  owner_bundle public.rag_v2_immutable_bundles%ROWTYPE;
  exact_generation public.rag_v2_immutable_component_generations%ROWTYPE;
  oa_generation public.rag_v2_immutable_component_generations%ROWTYPE;
  owner_generation public.rag_v2_immutable_component_generations%ROWTYPE;
  generated_scope_claim_id text;
  claim_created_at timestamptz := transaction_timestamp();
  claim_expires_at timestamptz := transaction_timestamp() + interval '2 minutes';
  selected_owner_generation_id text := NULL;
  selected_owner_bundle_id text := NULL;
  selected_owner_profile text := NULL;
  selected_owner_pointer_version bigint := 0;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$'
     OR NOT public.rag_v2_immutable_retrieval_topics_are_valid(p_allowed_topics)
     OR NOT EXISTS (
       SELECT 1
       FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);
  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers
  WHERE state_id = 'default';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 public bundle is not active'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO exact_generation
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = public_pointer.exact30_generation_id
    AND component_scope = 'EXACT30'
    AND owner_user_id IS NULL
    AND embedding_profile_id = public_pointer.embedding_profile_id
    AND state = 'ACTIVE'
    AND evaluation_status = 'PASSED';
  SELECT * INTO oa_generation
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = public_pointer.oa112_generation_id
    AND component_scope = 'OA112'
    AND owner_user_id IS NULL
    AND embedding_profile_id = public_pointer.embedding_profile_id
    AND state = 'ACTIVE'
    AND evaluation_status = 'PASSED';
  IF NOT FOUND OR exact_generation.component_generation_id IS NULL OR oa_generation.component_generation_id IS NULL THEN
    RAISE EXCEPTION 'immutable RAG v2 active public components are invalid'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO owner_pointer
  FROM public.rag_v2_immutable_owner_bundle_pointers
  WHERE owner_user_id = p_owner_user_id;
  IF FOUND AND owner_pointer.state IN ('BUILDING', 'FAILED') THEN
    RAISE EXCEPTION 'immutable RAG v2 owner overlay is not ready'
      USING ERRCODE = '55000';
  END IF;
  IF FOUND AND owner_pointer.state = 'READY' THEN
    SELECT * INTO owner_bundle
    FROM public.rag_v2_immutable_bundles
    WHERE bundle_id = owner_pointer.active_bundle_id
      AND owner_user_id = p_owner_user_id
      AND state = 'ACTIVE';
    IF NOT FOUND
       OR owner_bundle.exact30_generation_id IS DISTINCT FROM public_pointer.exact30_generation_id
       OR owner_bundle.oa112_generation_id IS DISTINCT FROM public_pointer.oa112_generation_id
       OR owner_bundle.embedding_profile_id IS DISTINCT FROM public_pointer.embedding_profile_id THEN
      RAISE EXCEPTION 'immutable RAG v2 owner bundle is not pinned to public base'
        USING ERRCODE = '55000';
    END IF;
    selected_owner_profile := owner_bundle.owner_embedding_profile_id;
    IF selected_owner_profile IS NOT NULL THEN
      SELECT * INTO owner_generation
      FROM public.rag_v2_immutable_component_generations
      WHERE component_generation_id = owner_bundle.owner_private_generation_id
        AND component_scope = 'OWNER_PRIVATE'
        AND owner_user_id = p_owner_user_id
        AND embedding_profile_id = selected_owner_profile
        AND state = 'ACTIVE'
        AND evaluation_status = 'PASSED';
      IF NOT FOUND OR owner_generation.actual_chunk_count < 1 THEN
        RAISE EXCEPTION 'immutable RAG v2 owner component is invalid'
          USING ERRCODE = '55000';
      END IF;
      selected_owner_generation_id := owner_generation.component_generation_id;
      selected_owner_bundle_id := owner_bundle.bundle_id;
    END IF;
    selected_owner_pointer_version := owner_pointer.bundle_version;
  ELSIF FOUND AND owner_pointer.state <> 'ABSENT' THEN
    RAISE EXCEPTION 'immutable RAG v2 owner pointer state is invalid'
      USING ERRCODE = '55000';
  ELSIF FOUND THEN
    selected_owner_pointer_version := owner_pointer.bundle_version;
  END IF;

  generated_scope_claim_id :=
    'rvs_' || substr(
      encode(
        digest(
          gen_random_bytes(32) || convert_to(
            concat_ws(
              E'\n',
              p_owner_user_id,
              p_session_id,
              public_pointer.exact30_generation_id,
              public_pointer.oa112_generation_id,
              coalesce(selected_owner_generation_id, ''),
              public_pointer.embedding_profile_id,
              coalesce(selected_owner_profile, ''),
              claim_created_at::text
            ),
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ),
      1,
      32
    );
  INSERT INTO public.rag_v2_retrieval_scope_claims (
    scope_claim_id,
    owner_user_id,
    session_id,
    allowed_topics,
    exact30_generation_id,
    oa112_generation_id,
    owner_private_generation_id,
    owner_bundle_id,
    embedding_profile_id,
    owner_embedding_profile_id,
    public_pointer_version,
    owner_pointer_version,
    policy_version,
    created_at,
    expires_at
  ) VALUES (
    generated_scope_claim_id,
    p_owner_user_id,
    p_session_id,
    p_allowed_topics,
    public_pointer.exact30_generation_id,
    public_pointer.oa112_generation_id,
    selected_owner_generation_id,
    selected_owner_bundle_id,
    public_pointer.embedding_profile_id,
    selected_owner_profile,
    public_pointer.pointer_version,
    selected_owner_pointer_version,
    1,
    claim_created_at,
    claim_expires_at
  );
  RETURN QUERY
  SELECT
    generated_scope_claim_id,
    p_owner_user_id,
    p_session_id,
    public_pointer.exact30_generation_id,
    public_pointer.oa112_generation_id,
    selected_owner_generation_id,
    public_pointer.embedding_profile_id,
    selected_owner_profile,
    1::bigint,
    p_allowed_topics,
    claim_expires_at;
END;
$_$;


ALTER FUNCTION public.issue_rag_v2_retrieval_scope_v2(p_owner_user_id text, p_session_id text, p_allowed_topics text[]) OWNER TO flyway;


CREATE FUNCTION public.issue_rag_v2_retrieval_scope_v3(p_owner_user_id text, p_session_id text, p_allowed_topics text[]) RETURNS TABLE(scope_claim_id text, owner_user_id text, session_id text, exact30_generation_id text, oa112_generation_id text, owner_private_generation_id text, embedding_profile_id text, owner_embedding_profile_id text, policy_version bigint, allowed_topics text[], expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  issued record;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope caller is invalid'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO STRICT issued
  FROM public.issue_rag_v2_retrieval_scope_v2(
    p_owner_user_id,
    p_session_id,
    p_allowed_topics
  );

  RETURN QUERY
  UPDATE public.rag_v2_retrieval_scope_claims AS claim
  SET expires_at = claim.created_at + interval '5 minutes'
  WHERE claim.scope_claim_id = issued.scope_claim_id
    AND claim.owner_user_id = p_owner_user_id
    AND claim.session_id = p_session_id
    AND claim.expires_at = claim.created_at + interval '2 minutes'
  RETURNING
    claim.scope_claim_id,
    claim.owner_user_id,
    claim.session_id,
    claim.exact30_generation_id,
    claim.oa112_generation_id,
    claim.owner_private_generation_id,
    claim.embedding_profile_id,
    claim.owner_embedding_profile_id,
    claim.policy_version,
    claim.allowed_topics,
    claim.expires_at;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 provider retrieval scope extension failed'
      USING ERRCODE = '55000';
  END IF;
END;
$$;


ALTER FUNCTION public.issue_rag_v2_retrieval_scope_v3(p_owner_user_id text, p_session_id text, p_allowed_topics text[]) OWNER TO flyway;


CREATE FUNCTION public.issue_s4_9_answer_validation_receipt(p_receipt_sha256 text, p_owner_user_id text, p_oauth_client_id text, p_research_context_id text, p_source_set_sha256 text, p_draft_sha256 text, p_validation_status text, p_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_receipt_sha256 !~ '^[0-9a-f]{64}$' OR p_source_set_sha256 !~ '^[0-9a-f]{64}$'
     OR p_draft_sha256 !~ '^[0-9a-f]{64}$' OR p_research_context_id !~ '^s49_ctx_[0-9a-f]{32}$'
     OR p_validation_status NOT IN ('VALID','VALID_WITH_WARNINGS')
     OR p_expires_at <= transaction_timestamp() OR p_expires_at > transaction_timestamp() + interval '5 minutes'
     OR NOT EXISTS (SELECT 1 FROM public.s4_9_mcp_oauth_clients c
                    WHERE c.client_id = p_oauth_client_id AND c.status = 'ACTIVE') THEN
    RAISE EXCEPTION 'S4.9 validation receipt arguments are invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.s4_9_answer_validation_receipts (
    receipt_sha256, owner_user_id, oauth_client_id, research_context_id, source_set_sha256,
    draft_sha256, validation_status, expires_at
  ) VALUES (
    p_receipt_sha256, p_owner_user_id, p_oauth_client_id, p_research_context_id, p_source_set_sha256,
    p_draft_sha256, p_validation_status, p_expires_at
  );
END
$_$;


ALTER FUNCTION public.issue_s4_9_answer_validation_receipt(p_receipt_sha256 text, p_owner_user_id text, p_oauth_client_id text, p_research_context_id text, p_source_set_sha256 text, p_draft_sha256 text, p_validation_status text, p_expires_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.issue_s4_9_mcp_retrieval_scope(p_owner_user_id text, p_session_id text, p_allowed_topics text[], p_include_owner boolean) RETURNS TABLE(scope_claim_id text, owner_user_id text, session_id text, exact30_generation_id text, oa112_generation_id text, owner_private_generation_id text, embedding_profile_id text, owner_embedding_profile_id text, policy_version bigint, allowed_topics text[], expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  issued record;
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  generated_scope_claim_id text;
  claim_created_at timestamptz := transaction_timestamp();
  claim_expires_at timestamptz := transaction_timestamp() + interval '15 minutes';
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$'
     OR NOT public.rag_v2_immutable_retrieval_topics_are_valid(p_allowed_topics)
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'S4.9 MCP retrieval scope arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  IF p_include_owner THEN
    SELECT * INTO STRICT issued
    FROM public.issue_rag_v2_retrieval_scope_v2(
      p_owner_user_id,
      p_session_id,
      p_allowed_topics
    );

    RETURN QUERY
    UPDATE public.rag_v2_retrieval_scope_claims AS claim
    SET expires_at = claim.created_at + interval '15 minutes',
        owner_scope_authorized = true
    WHERE claim.scope_claim_id = issued.scope_claim_id
      AND claim.owner_user_id = p_owner_user_id
      AND claim.session_id = p_session_id
      AND claim.expires_at = claim.created_at + interval '2 minutes'
    RETURNING
      claim.scope_claim_id,
      claim.owner_user_id,
      claim.session_id,
      claim.exact30_generation_id,
      claim.oa112_generation_id,
      claim.owner_private_generation_id,
      claim.embedding_profile_id,
      claim.owner_embedding_profile_id,
      claim.policy_version,
      claim.allowed_topics,
      claim.expires_at;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'S4.9 MCP owner retrieval scope extension failed'
        USING ERRCODE = '55000';
    END IF;
    RETURN;
  END IF;

  -- 공개 전용 분기는 owner pointer/bundle/component table을 전혀 읽지 않는다.
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);
  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers AS pointer
  WHERE pointer.state_id = 'default'
    AND pointer.state = 'ACTIVE';
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_component_generations AS exact_generation
       JOIN public.rag_v2_immutable_component_generations AS oa_generation
         ON oa_generation.component_generation_id = public_pointer.oa112_generation_id
        AND oa_generation.component_scope = 'OA112'
        AND oa_generation.owner_user_id IS NULL
        AND oa_generation.embedding_profile_id = public_pointer.embedding_profile_id
        AND oa_generation.state = 'ACTIVE'
        AND oa_generation.evaluation_status = 'PASSED'
       WHERE exact_generation.component_generation_id = public_pointer.exact30_generation_id
         AND exact_generation.component_scope = 'EXACT30'
         AND exact_generation.owner_user_id IS NULL
         AND exact_generation.embedding_profile_id = public_pointer.embedding_profile_id
         AND exact_generation.state = 'ACTIVE'
         AND exact_generation.evaluation_status = 'PASSED'
     ) THEN
    RAISE EXCEPTION 'S4.9 MCP public bundle is not active'
      USING ERRCODE = '55000';
  END IF;

  generated_scope_claim_id :=
    'rvs_' || substr(
      encode(
        digest(
          gen_random_bytes(32) || convert_to(
            concat_ws(
              E'\n',
              p_owner_user_id,
              p_session_id,
              public_pointer.exact30_generation_id,
              public_pointer.oa112_generation_id,
              public_pointer.embedding_profile_id,
              claim_created_at::text
            ),
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ),
      1,
      32
    );

  INSERT INTO public.rag_v2_retrieval_scope_claims (
    scope_claim_id, owner_user_id, session_id, allowed_topics,
    exact30_generation_id, oa112_generation_id, owner_private_generation_id,
    owner_bundle_id, embedding_profile_id, owner_embedding_profile_id,
    public_pointer_version, owner_pointer_version, owner_scope_authorized,
    policy_version, created_at, expires_at
  ) VALUES (
    generated_scope_claim_id, p_owner_user_id, p_session_id, p_allowed_topics,
    public_pointer.exact30_generation_id, public_pointer.oa112_generation_id, NULL,
    NULL, public_pointer.embedding_profile_id, NULL,
    public_pointer.pointer_version, 0, false,
    1, claim_created_at, claim_expires_at
  );

  RETURN QUERY SELECT
    generated_scope_claim_id,
    p_owner_user_id,
    p_session_id,
    public_pointer.exact30_generation_id,
    public_pointer.oa112_generation_id,
    NULL::text,
    public_pointer.embedding_profile_id,
    NULL::text,
    1::bigint,
    p_allowed_topics,
    claim_expires_at;
END;
$_$;


