CREATE FUNCTION public.json_text_depth_within(p_value text, p_max_depth integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE position integer; current_char text; in_string boolean:=false; escaped boolean:=false; depth integer:=0;
BEGIN
  IF p_max_depth NOT BETWEEN 1 AND 16 THEN RETURN false; END IF;
  FOR position IN 1..char_length(p_value) LOOP
    current_char:=substr(p_value,position,1);
    IF in_string THEN
      IF escaped THEN escaped:=false;
      ELSIF current_char='\\' THEN escaped:=true;
      ELSIF current_char='"' THEN in_string:=false;
      END IF;
    ELSIF current_char='"' THEN in_string:=true;
    ELSIF current_char IN ('{','[') THEN depth:=depth+1;IF depth>p_max_depth THEN RETURN false;END IF;
    ELSIF current_char IN ('}',']') THEN depth:=depth-1;IF depth<0 THEN RETURN false;END IF;
    END IF;
  END LOOP;
  RETURN NOT in_string AND NOT escaped AND depth=0;
END
$$;


ALTER FUNCTION public.json_text_depth_within(p_value text, p_max_depth integer) OWNER TO flyway;


CREATE FUNCTION public.list_artifact_ingest_status(p_actor_user_id text, p_security_version bigint) RETURNS TABLE(artifact_id text, file_name text, producer text, run_id text, file_hash text, schema_version text, status text, last_ingested_at timestamp with time zone, duplicate boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor_role text; actor_status text; actor_version bigint;
BEGIN
  IF session_user <> 'decision_app' THEN RAISE EXCEPTION 'artifact status read denied' USING ERRCODE='42501'; END IF;
  SELECT role,users.status,security_version INTO actor_role,actor_status,actor_version
    FROM public.users WHERE user_id=p_actor_user_id FOR SHARE;
  IF NOT FOUND OR actor_role<>'ADMIN' OR actor_status<>'ACTIVE' OR actor_version<>p_security_version THEN RETURN; END IF;
  INSERT INTO public.artifact_ingest_admin_read_audit(actor_user_id) VALUES (p_actor_user_id);
  RETURN QUERY SELECT item.artifact_id,item.file_name,item.producer,item.run_id,item.file_hash,item.schema_version,
    item.status,item.last_ingested_at,item.duplicate
  FROM public.artifact_ingest_projection item ORDER BY item.last_ingested_at DESC,item.artifact_id LIMIT 100;
END
$$;


