CREATE FUNCTION public.list_owned_principle_versions_authorized(p_capability text, p_actor_user_id text, p_principle_id text, p_limit integer, p_sort text, p_after_version integer) RETURNS TABLE(principle_id text, version integer, preset_id text, title text, mode text, status text, rules_json text, changed_fields text[], created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN RETURN; END IF;
  IF p_limit NOT BETWEEN 1 AND 101 OR p_sort NOT IN ('VERSION_ASC','VERSION_DESC') THEN
    RAISE EXCEPTION 'invalid principle history query' USING ERRCODE='22023';
  END IF;
  RETURN QUERY SELECT version.principle_id,version.version,version.preset_id,version.title,
    version.mode,version.status,version.rules_json::text,version.changed_fields,version.created_at
  FROM public.principle_versions version JOIN public.principles item
    ON item.principle_id=version.principle_id AND item.user_id=p_actor_user_id
  WHERE version.principle_id=p_principle_id AND (
    p_after_version IS NULL OR (p_sort='VERSION_ASC' AND version.version>p_after_version)
    OR (p_sort='VERSION_DESC' AND version.version<p_after_version)
  )
  ORDER BY CASE WHEN p_sort='VERSION_ASC' THEN version.version END ASC,
    CASE WHEN p_sort='VERSION_DESC' THEN version.version END DESC
  LIMIT p_limit;
END
$$;


ALTER FUNCTION public.list_owned_principle_versions_authorized(p_capability text, p_actor_user_id text, p_principle_id text, p_limit integer, p_sort text, p_after_version integer) OWNER TO flyway;


CREATE FUNCTION public.list_owned_principles_authorized(p_capability text, p_actor_user_id text, p_limit integer, p_sort text, p_after_updated_at timestamp with time zone, p_after_principle_id text) RETURNS TABLE(principle_id text, preset_id text, title text, mode text, status text, current_version integer, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN RETURN; END IF;
  IF p_limit NOT BETWEEN 1 AND 101 OR p_sort NOT IN ('UPDATED_AT_ASC','UPDATED_AT_DESC')
     OR ((p_after_updated_at IS NULL)<>(p_after_principle_id IS NULL)) THEN
    RAISE EXCEPTION 'invalid principle list query' USING ERRCODE='22023';
  END IF;
  RETURN QUERY SELECT item.principle_id,item.preset_id,item.title,item.mode,item.status,
    item.current_version,item.created_at,item.updated_at
  FROM public.principles item
  WHERE item.user_id=p_actor_user_id AND (
    p_after_updated_at IS NULL OR
    (p_sort='UPDATED_AT_ASC' AND (item.updated_at,item.principle_id)>(p_after_updated_at,p_after_principle_id)) OR
    (p_sort='UPDATED_AT_DESC' AND (item.updated_at,item.principle_id)<(p_after_updated_at,p_after_principle_id))
  )
  ORDER BY
    CASE WHEN p_sort='UPDATED_AT_ASC' THEN item.updated_at END ASC,
    CASE WHEN p_sort='UPDATED_AT_ASC' THEN item.principle_id END ASC,
    CASE WHEN p_sort='UPDATED_AT_DESC' THEN item.updated_at END DESC,
    CASE WHEN p_sort='UPDATED_AT_DESC' THEN item.principle_id END DESC
  LIMIT p_limit;
END
$$;


ALTER FUNCTION public.list_owned_principles_authorized(p_capability text, p_actor_user_id text, p_limit integer, p_sort text, p_after_updated_at timestamp with time zone, p_after_principle_id text) OWNER TO flyway;


CREATE FUNCTION public.load_rag_v2_immutable_voyage_document_batch_vectors(p_batch_plan_sha256 text) RETURNS TABLE(batch_id text, chunk_id text, embedding public.vector)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_batch_plan_sha256 IS NULL
     OR p_batch_plan_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch resume is unavailable' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_voyage_document_batch_attempts AS attempt
    WHERE attempt.batch_plan_sha256 = p_batch_plan_sha256
      AND attempt.state = 'CLAIMED'
  ) THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch has an active attempt'
      USING ERRCODE = '55000';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.rag_v2_immutable_voyage_document_batch_plans AS plan
    WHERE plan.batch_plan_sha256 = p_batch_plan_sha256
  ) THEN
    RETURN;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.rag_v2_immutable_voyage_document_batch_plans AS plan
    WHERE plan.batch_plan_sha256 = p_batch_plan_sha256 AND plan.state IN ('STAGING','COMPLETE')
  ) THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch resume state is invalid' USING ERRCODE = '55000';
  END IF;
  RETURN QUERY
  SELECT vector_row.batch_id, vector_row.chunk_id, vector_row.embedding
  FROM public.rag_v2_immutable_voyage_document_batch_vectors AS vector_row
  JOIN public.rag_v2_immutable_voyage_document_batches AS batch
    ON batch.batch_id = vector_row.batch_id
   AND batch.batch_plan_sha256 = vector_row.batch_plan_sha256
   AND batch.state = 'COMMITTED'
  WHERE vector_row.batch_plan_sha256 = p_batch_plan_sha256
  ORDER BY batch.batch_ordinal, vector_row.chunk_id;
END
$_$;


ALTER FUNCTION public.load_rag_v2_immutable_voyage_document_batch_vectors(p_batch_plan_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.load_rag_v2_immutable_voyage_evaluation_batch_vectors(p_scope_claim_sha256 text, p_component_scope text, p_query_manifest_sha256 text) RETURNS TABLE(query_sha256 text, embedding public.vector)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  attempt_state text;
  expected_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_scope_claim_sha256 !~ '^[0-9a-f]{64}$'
     OR p_component_scope NOT IN ('EXACT30','OA112')
     OR p_query_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Pre-S5 Voyage evaluation resume arguments are invalid' USING ERRCODE = '22023';
  END IF;
  SELECT state INTO attempt_state
  FROM public.rag_v2_immutable_voyage_evaluation_batch_attempts
  WHERE scope_claim_sha256 = p_scope_claim_sha256 AND component_scope = p_component_scope;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  IF attempt_state <> 'COMMITTED' OR NOT EXISTS (
    SELECT 1 FROM public.rag_v2_immutable_voyage_evaluation_batch_attempts
    WHERE scope_claim_sha256 = p_scope_claim_sha256
      AND component_scope = p_component_scope
      AND query_manifest_sha256 = p_query_manifest_sha256
  ) THEN
    RAISE EXCEPTION 'Pre-S5 Voyage evaluation batch is terminal or drifted' USING ERRCODE = '55000';
  END IF;
  expected_count := CASE p_component_scope WHEN 'EXACT30' THEN 10 ELSE 112 END;
  IF (SELECT count(*) FROM public.rag_v2_immutable_voyage_evaluation_batch_vectors
      WHERE scope_claim_sha256 = p_scope_claim_sha256 AND component_scope = p_component_scope)
     <> expected_count THEN
    RAISE EXCEPTION 'Pre-S5 Voyage evaluation resume cardinality conflicts' USING ERRCODE = '55000';
  END IF;
  RETURN QUERY
  SELECT vector_row.query_sha256, vector_row.embedding
  FROM public.rag_v2_immutable_voyage_evaluation_batch_vectors AS vector_row
  WHERE vector_row.scope_claim_sha256 = p_scope_claim_sha256
    AND vector_row.component_scope = p_component_scope
  ORDER BY vector_row.query_sha256;
END
$_$;


ALTER FUNCTION public.load_rag_v2_immutable_voyage_evaluation_batch_vectors(p_scope_claim_sha256 text, p_component_scope text, p_query_manifest_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.lock_active_owned_principle_authorized(p_capability text, p_actor_user_id text, p_principle_id text, p_principle_version integer, p_principle_version_id text, p_mode text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE locked_id text;
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN
    RAISE EXCEPTION 'principle lock capability denied' USING ERRCODE='42501';
  END IF;
  SELECT item.principle_id INTO locked_id
  FROM public.principles item
  JOIN public.principle_versions version_item
    ON version_item.principle_id=item.principle_id AND version_item.version=item.current_version
  WHERE item.principle_id=p_principle_id AND item.user_id=p_actor_user_id
    AND item.status='ACTIVE' AND item.current_version=p_principle_version
    AND version_item.principle_version_id=p_principle_version_id
    AND version_item.status='ACTIVE' AND version_item.mode=p_mode
  FOR SHARE OF item;
  RETURN locked_id IS NOT NULL;
END
$$;


ALTER FUNCTION public.lock_active_owned_principle_authorized(p_capability text, p_actor_user_id text, p_principle_id text, p_principle_version integer, p_principle_version_id text, p_mode text) OWNER TO flyway;


CREATE FUNCTION public.mark_rag_answer_unknown_after_provider(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  attempts integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id THEN
    RAISE EXCEPTION 'RAG unknown claim actor binding is invalid'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.rag_answer_claims
  SET state = 'UNKNOWN_AFTER_PROVIDER',
      updated_at = transaction_timestamp()
  WHERE scope_hmac = p_scope_hmac
    AND owner_user_id = p_owner_user_id
    AND request_fingerprint = p_request_fingerprint
    AND state = 'PENDING'
  RETURNING provider_attempts INTO attempts;
  IF FOUND THEN
    INSERT INTO public.rag_answer_claim_transitions (
      scope_hmac, owner_user_id, from_state, to_state, provider_attempts
    )
    VALUES (
      p_scope_hmac,
      p_owner_user_id,
      'PENDING',
      'UNKNOWN_AFTER_PROVIDER',
      attempts
    );
  END IF;
END
$$;


ALTER FUNCTION public.mark_rag_answer_unknown_after_provider(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text) OWNER TO flyway;


CREATE FUNCTION public.mark_rag_provider_attempt(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text, p_usage_event_id text, p_provider_usage_hmac text, p_provider text, p_context_citations jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  context_count integer;
  valid_context_count integer;
  distinct_context_count integer;
BEGIN
  context_count :=
    CASE
      WHEN jsonb_typeof(p_context_citations) = 'array'
        THEN jsonb_array_length(p_context_citations)
      ELSE -1
    END;
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_usage_event_id !~ '^rpu_[0-9a-f]{32}$'
     OR p_provider_usage_hmac !~ '^[0-9a-f]{64}$'
     OR p_provider NOT IN ('GEMINI', 'OPENAI')
     OR context_count NOT BETWEEN 1 AND 5 THEN
    RAISE EXCEPTION 'RAG provider attempt arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-consent-v1|' || p_owner_user_id, 0)
  );
  IF coalesce(
    (
      SELECT event.action = 'GRANT'
      FROM public.rag_consent_events AS event
      WHERE event.owner_user_id = p_owner_user_id
        AND event.consent_type = 'EXTERNAL_AI_RAG_V1'
        AND event.policy_version = 'EXTERNAL_AI_RAG_V1'
      ORDER BY event.consent_sequence DESC
      LIMIT 1
    ),
    false
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'RAG provider attempt requires effective consent'
      USING ERRCODE = '42501';
  END IF;
  SELECT
    count(*)::integer,
    count(DISTINCT item.value ->> 'chunkRevisionId')::integer
  INTO valid_context_count, distinct_context_count
  FROM jsonb_array_elements(p_context_citations) AS item(value)
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = item.value ->> 'sourceRevisionId'
   AND revision.access_level = 'PUBLIC'
   AND revision.tier = 'PROJECT'
   AND revision.initial_processing = 'PROJECT_AUTHORED_CARD'
   AND revision.external_processing_allowed
  JOIN public.rag_sources AS source
    ON source.source_id = revision.source_id
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  JOIN public.rag_source_card_verifications AS verification
    ON verification.source_revision_id = revision.source_revision_id
   AND verification.card_metadata_hash = revision.metadata_hash
   AND verification.status = 'VERIFIED'
  JOIN public.rag_chunk_revisions AS chunk
    ON chunk.chunk_revision_id = item.value ->> 'chunkRevisionId'
   AND chunk.source_revision_id = revision.source_revision_id
   AND chunk.access_level = 'PUBLIC'
   AND chunk.tier = 'PROJECT'
  JOIN public.rag_embedding_policy_state AS policy
    ON policy.state_id = 'default'
   AND policy.active_generation_id = item.value ->> 'generationId'
  JOIN public.rag_corpus_generations AS generation
    ON generation.corpus_generation_id = policy.active_generation_id
   AND generation.embedding_profile_id = policy.effective_profile_id
   AND generation.status = 'ACTIVE'
   AND generation.evaluation_status = 'PASSED'
  JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = generation.corpus_generation_id
   AND membership.embedding_profile_id = generation.embedding_profile_id
   AND membership.chunk_revision_id = chunk.chunk_revision_id
  WHERE jsonb_typeof(item.value) = 'object'
    AND (
      SELECT count(*)
      FROM jsonb_object_keys(item.value)
    ) = 3
    AND item.value ?& ARRAY[
      'sourceRevisionId',
      'chunkRevisionId',
      'generationId'
    ]
    AND (item.value ->> 'sourceRevisionId') ~ '^src_rev_[0-9a-f]{32}$'
    AND (item.value ->> 'chunkRevisionId') ~ '^rag_chk_[0-9a-f]{32}$';
  IF valid_context_count <> context_count
     OR distinct_context_count <> context_count THEN
    RAISE EXCEPTION 'RAG provider context is not externally processable'
      USING ERRCODE = '42501';
  END IF;
  UPDATE public.rag_answer_claims
  SET provider_attempts = 1,
      updated_at = transaction_timestamp()
  WHERE scope_hmac = p_scope_hmac
    AND owner_user_id = p_owner_user_id
    AND request_fingerprint = p_request_fingerprint
    AND state = 'PENDING'
    AND provider_attempts = 0
    AND pending_expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG provider attempt claim is not sendable'
      USING ERRCODE = '55000';
  END IF;
  INSERT INTO public.rag_provider_usage_ledger (
    usage_event_id,
    scope_hmac,
    owner_user_id,
    provider_usage_hmac,
    provider,
    physical_attempt
  )
  VALUES (
    p_usage_event_id,
    p_scope_hmac,
    p_owner_user_id,
    p_provider_usage_hmac,
    p_provider,
    1
  );
END
$_$;


ALTER FUNCTION public.mark_rag_provider_attempt(p_owner_user_id text, p_scope_hmac text, p_request_fingerprint text, p_usage_event_id text, p_provider_usage_hmac text, p_provider text, p_context_citations jsonb) OWNER TO flyway;


CREATE FUNCTION public.mark_rag_v2_immutable_vertex_usage_unknown_billing(p_usage_event_id text, p_owner_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  reservation public.rag_v2_immutable_vertex_usage_reservations%ROWTYPE;
  token_count integer := 0;
  generate_count integer := 0;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_usage_event_id !~ '^rgr_vgu_[0-9a-f]{32}$'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$' THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex unknown billing arguments are invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO reservation
  FROM public.rag_v2_immutable_vertex_usage_reservations
  WHERE usage_event_id = p_usage_event_id AND owner_user_id = p_owner_user_id
  FOR UPDATE;
  IF NOT FOUND
     OR reservation.authentication_mode <> 'SERVICE_ACCOUNT_OAUTH'
     OR reservation.token_physical_call_cap <> 1
     OR reservation.generate_content_physical_call_cap <> 1
     OR EXISTS (SELECT 1 FROM public.rag_v2_immutable_vertex_usage_outcomes WHERE usage_event_id = p_usage_event_id) THEN
    RAISE EXCEPTION 'immutable Pre-S5 Vertex unknown billing is unavailable' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.rag_v2_immutable_vertex_usage_token_attempts
    WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_token_call_count = 1
  ) THEN
    token_count := 1;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.rag_v2_immutable_vertex_usage_generate_content_attempts
    WHERE usage_event_id = p_usage_event_id AND state = 'ATTEMPTED' AND physical_generate_content_call_count = 1
  ) THEN
    generate_count := 1;
  END IF;
  INSERT INTO public.rag_v2_immutable_vertex_usage_outcomes (
    usage_event_id, packet_sha256, state, physical_token_call_count, physical_generate_content_call_count,
    prompt_token_count, candidate_token_count, total_token_count, actual_cost_microusd
  ) VALUES (
    p_usage_event_id, reservation.packet_sha256, 'UNKNOWN_BILLING', token_count, generate_count,
    NULL, NULL, NULL, NULL
  );
END
$_$;


ALTER FUNCTION public.mark_rag_v2_immutable_vertex_usage_unknown_billing(p_usage_event_id text, p_owner_user_id text) OWNER TO flyway;


CREATE FUNCTION public.mark_rag_v2_immutable_voyage_document_batch_unknown_billing(p_usage_event_id text, p_batch_plan_sha256 text, p_batch_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_rag_writer' THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch unknown outcome is unavailable'
      USING ERRCODE = '55000';
  END IF;
  PERFORM public.mark_rag_v2_immutable_voyage_usage_unknown_billing(p_usage_event_id);
  UPDATE public.rag_v2_immutable_voyage_document_batch_attempts
  SET state = 'UNKNOWN_BILLING', terminal_at = transaction_timestamp()
  WHERE usage_event_id = p_usage_event_id
    AND batch_plan_sha256 = p_batch_plan_sha256
    AND batch_id = p_batch_id
    AND state = 'CLAIMED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch unknown outcome conflicts'
      USING ERRCODE = '55000';
  END IF;
END
$$;


ALTER FUNCTION public.mark_rag_v2_immutable_voyage_document_batch_unknown_billing(p_usage_event_id text, p_batch_plan_sha256 text, p_batch_id text) OWNER TO flyway;


