CREATE FUNCTION public.prepare_rag_v2_immutable_owner_overlay(p_owner_user_id text, p_excluded_document_id text DEFAULT NULL::text) RETURNS TABLE(bundle_id text, owner_private_generation_id text, expected_active_bundle_id text, expected_bundle_version bigint, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  owner_pointer_exists boolean := false;
  existing_generation public.rag_v2_immutable_component_generations%ROWTYPE;
  existing_bundle public.rag_v2_immutable_bundles%ROWTYPE;
  selected_source_revision_ids text[] := ARRAY[]::text[];
  selected_source_count integer := 0;
  selected_chunk_count integer := 0;
  selected_embedding_count integer := 0;
  selected_profile_count integer := 0;
  selected_owner_profile text := NULL;
  effective_owner_profile text;
  overlay_manifest_hash text;
  overlay_generation_hash text;
  overlay_generation_id text;
  overlay_bundle_hash text;
  overlay_bundle_id text;
  evaluation_timestamp timestamptz := clock_timestamp();
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR (p_excluded_document_id IS NOT NULL AND p_excluded_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$')
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS owner
       WHERE owner.user_id = p_owner_user_id
         AND owner.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner overlay arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- active document 삭제의 replacement 조립은 V25 delete와 같은 document→global lock 순서를
  -- 따라야 한다. 그렇지 않으면 구형 direct delete가 document lock을 보유한 채 global lock을
  -- 기다리는 경우와 교착될 수 있다.
  IF p_excluded_document_id IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'rag-v2-immutable-owner-document|' || p_owner_user_id || '|' || p_excluded_document_id,
        0
      )
    );
  END IF;
  -- owner activation과 같은 advisory lock으로 public pointer refresh와 overlay assembly를
  -- 직렬화한다. 이 function은 pointer를 update하지 않아 direct table capability를 넓히지 않는다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-bundle-activation', 0)
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  PERFORM set_config('app.rag_admin_maintenance', 'owner_bundle_activation', true);

  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers
  WHERE state_id = 'default';
  IF NOT FOUND
     OR public_pointer.state <> 'ACTIVE'
     OR public_pointer.embedding_profile_id NOT IN ('bge_m3_local_1024_v1', 'voyage_context_4_1024_v1')
     OR public_pointer.exact30_generation_id IS NULL
     OR public_pointer.oa112_generation_id IS NULL THEN
    RAISE EXCEPTION 'immutable RAG v2 public base is not active'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO owner_pointer
  FROM public.rag_v2_immutable_owner_bundle_pointers
  WHERE owner_user_id = p_owner_user_id;
  owner_pointer_exists := FOUND;

  -- V28/V30 document generation은 source 하나만 STAGED로 남긴다. 그 complete receipts만
  -- aggregate 대상으로 사용하고, metadata 없는 legacy row는 조용히 누락시키지 않고 거부한다.
  SELECT coalesce(
    array_agg(source.source_revision_id ORDER BY source.source_revision_id COLLATE "C"),
    ARRAY[]::text[]
  )
  INTO selected_source_revision_ids
  FROM public.rag_v2_immutable_source_revisions AS source
  JOIN public.rag_v2_immutable_materialization_runs AS run
    ON run.owner_user_id = source.owner_user_id
   AND run.component_scope = 'OWNER_PRIVATE'
   AND run.document_id = source.document_id
  JOIN public.rag_v2_immutable_component_generations AS staging_generation
    ON staging_generation.component_generation_id = run.component_generation_id
   AND staging_generation.owner_user_id = source.owner_user_id
   AND staging_generation.component_scope = 'OWNER_PRIVATE'
  WHERE source.owner_user_id = p_owner_user_id
    AND source.source_scope = 'OWNER_PRIVATE'
    AND (p_excluded_document_id IS NULL OR source.document_id <> p_excluded_document_id)
    AND run.state = 'STAGED'
    AND staging_generation.state = 'STAGING'
    AND staging_generation.evaluation_status = 'PENDING';

  SELECT count(DISTINCT staging_generation.embedding_profile_id)::integer,
         min(staging_generation.embedding_profile_id)
  INTO selected_profile_count, selected_owner_profile
  FROM public.rag_v2_immutable_source_revisions AS source
  JOIN public.rag_v2_immutable_materialization_runs AS run
    ON run.owner_user_id = source.owner_user_id
   AND run.component_scope = 'OWNER_PRIVATE'
   AND run.document_id = source.document_id
   AND run.state = 'STAGED'
  JOIN public.rag_v2_immutable_component_generations AS staging_generation
    ON staging_generation.component_generation_id = run.component_generation_id
   AND staging_generation.owner_user_id = source.owner_user_id
   AND staging_generation.component_scope = 'OWNER_PRIVATE'
   AND staging_generation.state = 'STAGING'
   AND staging_generation.evaluation_status = 'PENDING'
  WHERE source.source_revision_id = ANY(selected_source_revision_ids);
  IF selected_profile_count > 1 THEN
    RAISE EXCEPTION 'immutable RAG v2 owner library contains mixed profiles'
      USING ERRCODE = '23514';
  END IF;
  effective_owner_profile := coalesce(selected_owner_profile, public_pointer.embedding_profile_id);

  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_source_revisions AS source
    WHERE source.owner_user_id = p_owner_user_id
      AND source.source_scope = 'OWNER_PRIVATE'
      AND (p_excluded_document_id IS NULL OR source.document_id <> p_excluded_document_id)
      AND NOT (source.source_revision_id = ANY(selected_source_revision_ids))
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner overlay has an incomplete or historical source'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_source_revisions AS source
    WHERE source.source_revision_id = ANY(selected_source_revision_ids)
      AND (
        source.sanitized_display_name IS NULL
        OR char_length(source.sanitized_display_name) NOT BETWEEN 1 AND 160
        OR source.sanitized_display_name <> btrim(source.sanitized_display_name)
        OR source.sanitized_display_name ~ '[[:cntrl:]]'
        OR position('/' IN source.sanitized_display_name) > 0
        OR position(E'\\' IN source.sanitized_display_name) > 0
        OR position(':' IN source.sanitized_display_name) > 0
        OR source.canonical_https_url IS NOT NULL
        OR NOT source.local_processing_allowed
        OR (
          selected_owner_profile = 'bge_m3_local_1024_v1'
          AND (
            source.external_processing_eligible
            OR source.external_embedding_allowed
            OR source.external_generation_allowed
          )
        )
        OR (
          selected_owner_profile = 'voyage_context_4_1024_v1'
          AND (
            NOT source.external_processing_eligible
            OR NOT source.external_embedding_allowed
            OR NOT source.external_generation_allowed
          )
        )
        OR NOT public.rag_v2_immutable_retrieval_topics_are_valid(source.retrieval_topics)
      )
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner overlay citation metadata is invalid'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_source_revisions AS source
    LEFT JOIN public.rag_v2_immutable_materialization_runs AS run
      ON run.owner_user_id = source.owner_user_id
     AND run.component_scope = 'OWNER_PRIVATE'
     AND run.document_id = source.document_id
     AND run.state = 'STAGED'
    LEFT JOIN public.rag_v2_immutable_component_generations AS staging_generation
      ON staging_generation.component_generation_id = run.component_generation_id
     AND staging_generation.owner_user_id = source.owner_user_id
     AND staging_generation.component_scope = 'OWNER_PRIVATE'
    WHERE source.source_revision_id = ANY(selected_source_revision_ids)
      AND (
        run.materialization_run_id IS NULL
        OR staging_generation.component_generation_id IS NULL
        OR staging_generation.state <> 'STAGING'
        OR staging_generation.evaluation_status <> 'PENDING'
        OR staging_generation.expected_source_count <> 1
        OR staging_generation.actual_source_count <> 1
        OR staging_generation.expected_chunk_count < 1
        OR staging_generation.actual_chunk_count <> staging_generation.expected_chunk_count
        OR (
          SELECT count(*)
          FROM public.rag_v2_immutable_generation_memberships AS membership
          WHERE membership.component_generation_id = staging_generation.component_generation_id
            AND membership.source_revision_id = source.source_revision_id
            AND membership.owner_user_id = p_owner_user_id
            AND membership.component_scope = 'OWNER_PRIVATE'
        ) <> staging_generation.actual_chunk_count
        OR (
          SELECT count(*)
          FROM public.rag_v2_immutable_generation_embeddings AS embedding
          JOIN public.rag_v2_immutable_generation_memberships AS membership
            ON membership.component_generation_id = embedding.component_generation_id
           AND membership.chunk_id = embedding.chunk_id
          WHERE embedding.component_generation_id = staging_generation.component_generation_id
            AND membership.source_revision_id = source.source_revision_id
            AND embedding.owner_user_id = p_owner_user_id
            AND embedding.component_scope = 'OWNER_PRIVATE'
            AND embedding.embedding_profile_id = selected_owner_profile
        ) <> staging_generation.actual_chunk_count
      )
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner overlay source receipts are incomplete'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*)::integer
  INTO selected_source_count
  FROM public.rag_v2_immutable_source_revisions AS source
  WHERE source.source_revision_id = ANY(selected_source_revision_ids);
  SELECT count(*)::integer
  INTO selected_chunk_count
  FROM public.rag_v2_immutable_generation_memberships AS membership
  JOIN public.rag_v2_immutable_source_revisions AS source
    ON source.source_revision_id = membership.source_revision_id
  JOIN public.rag_v2_immutable_materialization_runs AS run
    ON run.component_generation_id = membership.component_generation_id
   AND run.owner_user_id = p_owner_user_id
   AND run.component_scope = 'OWNER_PRIVATE'
   AND run.document_id = source.document_id
   AND run.state = 'STAGED'
  WHERE source.source_revision_id = ANY(selected_source_revision_ids)
    AND membership.owner_user_id = p_owner_user_id
    AND membership.component_scope = 'OWNER_PRIVATE'
    AND membership.component_generation_id = run.component_generation_id;
  IF (selected_source_count = 0 AND selected_chunk_count <> 0)
     OR (selected_source_count > 0 AND selected_chunk_count < selected_source_count) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner overlay cardinality is invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT encode(
    digest(
      coalesce(
        string_agg(
          source.source_revision_id || '|' || source.canonical_text_sha256 || '|' ||
          encode(digest(source.sanitized_display_name, 'sha256'), 'hex') || '|' ||
          encode(digest(array_to_string(source.retrieval_topics, E'\x1f'), 'sha256'), 'hex'),
          E'\n' ORDER BY source.source_revision_id COLLATE "C"
        ),
        ''
      ),
      'sha256'
    ),
    'hex'
  )
  INTO overlay_manifest_hash
  FROM public.rag_v2_immutable_source_revisions AS source
  WHERE source.source_revision_id = ANY(selected_source_revision_ids);
  overlay_generation_hash := encode(
    digest(
      'rag-v2-owner-overlay-generation|'
      || p_owner_user_id || '|' || effective_owner_profile || '|' || overlay_manifest_hash,
      'sha256'
    ),
    'hex'
  );
  overlay_generation_id := 'rgr_' || substr(overlay_generation_hash, 1, 32);
  overlay_bundle_hash := encode(
    digest(
      'rag-v2-owner-overlay-bundle|'
      || p_owner_user_id || '|' || public_pointer.exact30_generation_id || '|'
      || public_pointer.oa112_generation_id || '|' || overlay_generation_id || '|'
      || public_pointer.embedding_profile_id || '|' || coalesce(selected_owner_profile, '') || '|' || overlay_manifest_hash,
      'sha256'
    ),
    'hex'
  );
  overlay_bundle_id := 'rgb_' || substr(overlay_bundle_hash, 1, 32);

  SELECT * INTO existing_generation
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = overlay_generation_id
  FOR UPDATE;
  IF FOUND THEN
    IF existing_generation.owner_user_id IS DISTINCT FROM p_owner_user_id
       OR existing_generation.component_scope <> 'OWNER_PRIVATE'
       OR existing_generation.embedding_profile_id <> effective_owner_profile
       OR existing_generation.state NOT IN ('EVALUATED', 'ACTIVE', 'SUPERSEDED')
       OR existing_generation.evaluation_status <> 'PASSED'
       OR existing_generation.generation_hash <> overlay_generation_hash
       OR existing_generation.manifest_hash <> overlay_manifest_hash
       OR existing_generation.expected_source_count <> selected_source_count
       OR existing_generation.actual_source_count <> selected_source_count
       OR existing_generation.expected_chunk_count <> selected_chunk_count
       OR existing_generation.actual_chunk_count <> selected_chunk_count THEN
      RAISE EXCEPTION 'immutable RAG v2 owner overlay generation identity conflicted'
        USING ERRCODE = '23505';
    END IF;
    -- 동일한 content-addressed identity가 과거 activation에서 supersede된 경우에만
    -- 다시 평가 상태로 돌린다. 위 exact projection 검증을 통과하지 못한 row는 재활성화하지 않는다.
    IF existing_generation.state = 'SUPERSEDED' THEN
      UPDATE public.rag_v2_immutable_component_generations
      SET state = 'EVALUATED',
          evaluated_at = evaluation_timestamp
      WHERE component_generation_id = overlay_generation_id
        AND owner_user_id = p_owner_user_id
        AND component_scope = 'OWNER_PRIVATE'
        AND state = 'SUPERSEDED'
        AND evaluation_status = 'PASSED';
      IF NOT FOUND THEN
        RAISE EXCEPTION 'immutable RAG v2 owner overlay generation reuse transition failed'
          USING ERRCODE = '40001';
      END IF;
    END IF;
  ELSE
    INSERT INTO public.rag_v2_immutable_component_generations (
      component_generation_id,
      owner_user_id,
      component_scope,
      embedding_profile_id,
      state,
      evaluation_status,
      expected_source_count,
      expected_chunk_count,
      actual_source_count,
      actual_chunk_count,
      generation_hash,
      manifest_hash
    ) VALUES (
      overlay_generation_id,
      p_owner_user_id,
      'OWNER_PRIVATE',
      effective_owner_profile,
      'STAGING',
      'PENDING',
      selected_source_count,
      selected_chunk_count,
      0,
      0,
      overlay_generation_hash,
      overlay_manifest_hash
    );
    INSERT INTO public.rag_v2_immutable_generation_memberships (
      component_generation_id,
      chunk_id,
      source_revision_id,
      owner_user_id,
      component_scope,
      ordinal
    )
    SELECT
      overlay_generation_id,
      membership.chunk_id,
      membership.source_revision_id,
      p_owner_user_id,
      'OWNER_PRIVATE',
      row_number() OVER (
        ORDER BY source.source_revision_id COLLATE "C", chunk.chunk_ordinal, membership.chunk_id COLLATE "C"
      )::integer
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_chunks AS chunk
      ON chunk.chunk_id = membership.chunk_id
     AND chunk.source_revision_id = membership.source_revision_id
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    JOIN public.rag_v2_immutable_materialization_runs AS run
      ON run.component_generation_id = membership.component_generation_id
     AND run.owner_user_id = p_owner_user_id
     AND run.component_scope = 'OWNER_PRIVATE'
     AND run.document_id = source.document_id
     AND run.state = 'STAGED'
    WHERE source.source_revision_id = ANY(selected_source_revision_ids)
      AND membership.owner_user_id = p_owner_user_id
      AND membership.component_scope = 'OWNER_PRIVATE'
      AND membership.component_generation_id = run.component_generation_id;
    INSERT INTO public.rag_v2_immutable_generation_embeddings (
      component_generation_id,
      chunk_id,
      owner_user_id,
      component_scope,
      embedding_profile_id,
      embedding_input_hash,
      context_set_hash,
      embedding
    )
    SELECT
      overlay_generation_id,
      embedding.chunk_id,
      p_owner_user_id,
      'OWNER_PRIVATE',
      effective_owner_profile,
      embedding.embedding_input_hash,
      embedding.context_set_hash,
      embedding.embedding
    FROM public.rag_v2_immutable_generation_embeddings AS embedding
    JOIN public.rag_v2_immutable_generation_memberships AS membership
      ON membership.component_generation_id = embedding.component_generation_id
     AND membership.chunk_id = embedding.chunk_id
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    JOIN public.rag_v2_immutable_materialization_runs AS run
      ON run.component_generation_id = membership.component_generation_id
     AND run.owner_user_id = p_owner_user_id
     AND run.component_scope = 'OWNER_PRIVATE'
     AND run.document_id = source.document_id
     AND run.state = 'STAGED'
    WHERE source.source_revision_id = ANY(selected_source_revision_ids)
      AND embedding.owner_user_id = p_owner_user_id
      AND embedding.component_scope = 'OWNER_PRIVATE'
      AND embedding.embedding_profile_id = effective_owner_profile;
    SELECT count(*)::integer
    INTO selected_embedding_count
    FROM public.rag_v2_immutable_generation_embeddings AS embedding
    WHERE embedding.component_generation_id = overlay_generation_id
      AND embedding.owner_user_id = p_owner_user_id
      AND embedding.component_scope = 'OWNER_PRIVATE'
      AND embedding.embedding_profile_id = effective_owner_profile;
    IF selected_embedding_count <> selected_chunk_count THEN
      RAISE EXCEPTION 'immutable RAG v2 owner overlay embedding copy is incomplete'
        USING ERRCODE = '23514';
    END IF;
    UPDATE public.rag_v2_immutable_component_generations
    SET actual_source_count = selected_source_count,
        actual_chunk_count = selected_chunk_count,
        state = 'EVALUATED',
        evaluation_status = 'PASSED',
        evaluated_at = evaluation_timestamp
    WHERE component_generation_id = overlay_generation_id
      AND owner_user_id = p_owner_user_id
      AND state = 'STAGING'
      AND evaluation_status = 'PENDING';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'immutable RAG v2 owner overlay evaluation transition failed'
        USING ERRCODE = '40001';
    END IF;
  END IF;

  SELECT * INTO existing_bundle
  FROM public.rag_v2_immutable_bundles
  WHERE bundle_id = overlay_bundle_id
  FOR UPDATE;
  IF FOUND THEN
    IF existing_bundle.owner_user_id IS DISTINCT FROM p_owner_user_id
       OR existing_bundle.exact30_generation_id IS DISTINCT FROM public_pointer.exact30_generation_id
       OR existing_bundle.oa112_generation_id IS DISTINCT FROM public_pointer.oa112_generation_id
       OR existing_bundle.owner_private_generation_id IS DISTINCT FROM overlay_generation_id
       OR existing_bundle.embedding_profile_id IS DISTINCT FROM public_pointer.embedding_profile_id
       OR existing_bundle.owner_embedding_profile_id IS DISTINCT FROM selected_owner_profile
       OR existing_bundle.state NOT IN ('EVALUATED', 'ACTIVE', 'SUPERSEDED')
       OR existing_bundle.evaluation_status <> 'PASSED'
       OR existing_bundle.bundle_hash <> overlay_bundle_hash THEN
      RAISE EXCEPTION 'immutable RAG v2 owner overlay bundle identity conflicted'
        USING ERRCODE = '23505';
    END IF;
    -- generation과 같은 exact bundle identity만 재평가해 pointer activation의 정상 입력으로 복구한다.
    IF existing_bundle.state = 'SUPERSEDED' THEN
      UPDATE public.rag_v2_immutable_bundles
      SET state = 'EVALUATED',
          evaluated_at = evaluation_timestamp
      WHERE bundle_id = overlay_bundle_id
        AND owner_user_id = p_owner_user_id
        AND state = 'SUPERSEDED'
        AND evaluation_status = 'PASSED';
      IF NOT FOUND THEN
        RAISE EXCEPTION 'immutable RAG v2 owner overlay bundle reuse transition failed'
          USING ERRCODE = '40001';
      END IF;
    END IF;
  ELSE
    INSERT INTO public.rag_v2_immutable_bundles (
      bundle_id,
      owner_user_id,
      exact30_generation_id,
      oa112_generation_id,
      owner_private_generation_id,
      embedding_profile_id,
      owner_embedding_profile_id,
      state,
      evaluation_status,
      bundle_hash,
      evaluated_at
    ) VALUES (
      overlay_bundle_id,
      p_owner_user_id,
      public_pointer.exact30_generation_id,
      public_pointer.oa112_generation_id,
      overlay_generation_id,
      public_pointer.embedding_profile_id,
      selected_owner_profile,
      'EVALUATED',
      'PASSED',
      overlay_bundle_hash,
      evaluation_timestamp
    );
  END IF;

  PERFORM set_config('app.rag_admin_maintenance', '', true);
  RETURN QUERY
  SELECT
    overlay_bundle_id,
    overlay_generation_id,
    CASE WHEN owner_pointer_exists THEN owner_pointer.active_bundle_id ELSE NULL END,
    CASE WHEN owner_pointer_exists THEN owner_pointer.bundle_version ELSE 0::bigint END,
    selected_source_count,
    selected_chunk_count;
END;
$_$;


ALTER FUNCTION public.prepare_rag_v2_immutable_owner_overlay(p_owner_user_id text, p_excluded_document_id text) OWNER TO flyway;


CREATE FUNCTION public.prepare_rag_v2_immutable_public_base_activation(p_exact30_generation_id text, p_oa112_generation_id text) RETURNS TABLE(expected_pointer_version bigint, activation_required boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  pointer_record public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_exact30_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_oa112_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_exact30_generation_id = p_oa112_generation_id THEN
    RAISE EXCEPTION 'immutable RAG v2 public activation prepare arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- V25 public pointer RLS의 기존 maintenance marker만 사용해 direct table grant를 만들지 않는다.
  PERFORM set_config('app.rag_admin_maintenance', 'public_base_activation', true);
  -- prepare와 V25 activation이 같은 transaction에서 호출될 때 stale version/lock reordering을 닫는다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-bundle-activation', 0)
  );
  SELECT *
  INTO pointer_record
  FROM public.rag_v2_immutable_public_bundle_pointers
  WHERE state_id = 'default'
  FOR UPDATE;
  IF NOT FOUND
     OR pointer_record.state NOT IN ('NOT_MATERIALIZED', 'ACTIVE', 'FAILED')
     OR pointer_record.pointer_version < 1 THEN
    RAISE EXCEPTION 'immutable RAG v2 public activation prepare pointer is unavailable'
      USING ERRCODE = '40001';
  END IF;

  -- Same active pair is an idempotent local operator success. No previous pointer IDs are returned.
  RETURN QUERY
  SELECT
    pointer_record.pointer_version,
    NOT (
      pointer_record.state = 'ACTIVE'
      AND pointer_record.exact30_generation_id IS NOT DISTINCT FROM p_exact30_generation_id
      AND pointer_record.oa112_generation_id IS NOT DISTINCT FROM p_oa112_generation_id
    );
END;
$_$;


ALTER FUNCTION public.prepare_rag_v2_immutable_public_base_activation(p_exact30_generation_id text, p_oa112_generation_id text) OWNER TO flyway;


CREATE FUNCTION public.prune_market_data_macro(p_as_of date, p_apply boolean DEFAULT false) RETURNS TABLE(candidate_rows bigint, deleted_rows bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    candidate_count bigint;
    removed_count bigint := 0;
BEGIN
    IF NOT pg_has_role(session_user, 'decision_market_retention_admin', 'MEMBER') THEN
        RAISE EXCEPTION 'market-data retention authority is required';
    END IF;
    SELECT count(*) INTO candidate_count
    FROM market_data_macro
    WHERE observation_date < p_as_of - 365
       OR entitlement_expires_at < p_as_of;
    IF p_apply THEN
        DELETE FROM market_data_macro
        WHERE observation_date < p_as_of - 365
           OR entitlement_expires_at < p_as_of;
        GET DIAGNOSTICS removed_count = ROW_COUNT;
    END IF;
    RETURN QUERY SELECT candidate_count, removed_count;
END
$$;


ALTER FUNCTION public.prune_market_data_macro(p_as_of date, p_apply boolean) OWNER TO flyway;


CREATE FUNCTION public.publish_active_signal_batch(p_signal_batch_id text, p_expected_signal_batch_id text, p_expected_batch_manifest_sha256 text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  active_model text;
  current_batch text;
  next_generation bigint;
  publication_digest text;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_signal_scheduler'
     OR p_expected_batch_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'S5 scheduler actor is invalid' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('s5-signal-active-pointer-v1', 0));
  SELECT model_release_id INTO active_model
  FROM public.active_signal_model_release WHERE singleton FOR SHARE;
  SELECT signal_batch_id, generation INTO current_batch, next_generation
  FROM public.active_signal_batch WHERE singleton FOR UPDATE;
  -- DB commit 뒤 operator 응답이 끊긴 경우 같은 manifest-bound target은 publication을 늘리지 않고 replay한다.
  IF current_batch = p_signal_batch_id AND EXISTS (
    SELECT 1 FROM public.signal_batches batch
    JOIN public.signal_model_releases release USING (model_release_id)
    WHERE batch.signal_batch_id = p_signal_batch_id
      AND batch.model_release_id = active_model
      AND batch.batch_manifest_sha256 = p_expected_batch_manifest_sha256
      AND batch.status = 'FINALIZED' AND release.lifecycle_status = 'ACCEPTED'
      AND EXISTS (
        SELECT 1 FROM public.signal_batch_publications publication
        WHERE publication.signal_batch_id = batch.signal_batch_id
          AND publication.generation = next_generation
      )
  ) THEN
    RETURN next_generation;
  END IF;
  IF active_model IS NULL OR current_batch IS DISTINCT FROM NULLIF(p_expected_signal_batch_id, '') THEN
    RAISE EXCEPTION 'S5 scheduler pointer CAS conflict' USING ERRCODE = '40001';
  END IF;
  -- drift suspension과 publication을 release row lock으로 직렬화한다.
  PERFORM 1 FROM public.signal_model_releases
  WHERE model_release_id = active_model AND lifecycle_status = 'ACCEPTED'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'S5 scheduler model release is not accepted' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.signal_batches batch
    JOIN public.signal_model_releases release USING (model_release_id)
    JOIN public.current_s5_signal_batch_clock() current_clock
      ON current_clock.session_date = batch.session_date AND current_clock.as_of = batch.as_of
    WHERE batch.signal_batch_id = p_signal_batch_id AND batch.model_release_id = active_model
      AND batch.status = 'FINALIZED' AND batch.row_count = 31
      AND batch.batch_purpose = 'DAILY'
      AND batch.batch_manifest_sha256 = p_expected_batch_manifest_sha256
      AND release.lifecycle_status = 'ACCEPTED'
      AND NOT EXISTS (
        SELECT 1 FROM public.signal_batch_publications publication
        WHERE publication.signal_batch_id = batch.signal_batch_id
      )
      AND (SELECT count(*) FROM public.signal_batch_members member
           WHERE member.signal_batch_id = batch.signal_batch_id AND member.status = 'AVAILABLE') = 31
  ) THEN
    RAISE EXCEPTION 'S5 scheduler batch is invalid' USING ERRCODE = '22023';
  END IF;
  next_generation := next_generation + 1;
  UPDATE public.active_signal_batch SET signal_batch_id = p_signal_batch_id,
    generation = next_generation, published_at = clock_timestamp() WHERE singleton;
  publication_digest := encode(digest(convert_to(concat_ws(E'\n',
    's5-batch-publication-v1', p_signal_batch_id, next_generation::text, 'DAILY_PUBLISH'),
    'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.signal_batch_publications(
    publication_id, signal_batch_id, model_release_id, generation, reason, actor_role
  ) VALUES (
    'sbp-' || substr(publication_digest, 1, 24), p_signal_batch_id, active_model,
    next_generation, 'DAILY_PUBLISH', session_user
  );
  RETURN next_generation;
END
$_$;


ALTER FUNCTION public.publish_active_signal_batch(p_signal_batch_id text, p_expected_signal_batch_id text, p_expected_batch_manifest_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.purge_expired_rag_history(p_limit integer) RETURNS TABLE(deleted_count integer, oldest_expired_lag_seconds bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  oldest_expired timestamptz;
  removed_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR p_limit NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'RAG purge arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  WITH targets AS (
    SELECT history.answer_id
    FROM public.rag_answer_history AS history
    WHERE history.expires_at <= statement_timestamp()
    ORDER BY history.expires_at, history.answer_id
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  ),
  deleted AS (
    DELETE FROM public.rag_answer_history AS history
    USING targets
    WHERE history.answer_id = targets.answer_id
    RETURNING 1
  )
  SELECT count(*)::integer
  INTO removed_count
  FROM deleted;

  SELECT min(history.expires_at)
  INTO oldest_expired
  FROM public.rag_answer_history AS history
  WHERE history.expires_at <= statement_timestamp();

  RETURN QUERY
  SELECT
    removed_count,
    CASE
      WHEN oldest_expired IS NULL THEN 0::bigint
      ELSE greatest(
        0,
        extract(epoch FROM statement_timestamp() - oldest_expired)::bigint
      )
    END;
END
$$;


ALTER FUNCTION public.purge_expired_rag_history(p_limit integer) OWNER TO flyway;


CREATE FUNCTION public.purge_rag_embedding_staging(p_generation_id text, p_materialization_run_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  deleted_row_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_generation_id !~ '^rag_gen_[0-9a-f]{32}$'
     OR octet_length(p_materialization_run_id) <> 40
     OR p_materialization_run_id !~ '^rag_mat_[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'RAG embedding staging purge caller or argument is invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.rag_corpus_generations AS generation
  WHERE generation.corpus_generation_id = p_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG embedding staging purge generation is missing'
      USING ERRCODE = '23503';
  END IF;

  DELETE FROM public.rag_embedding_staging AS staging
  WHERE staging.generation_id = p_generation_id
    AND staging.materialization_run_id = p_materialization_run_id
    AND staging.writer_role = session_user::name;
  GET DIAGNOSTICS deleted_row_count = ROW_COUNT;
  RETURN deleted_row_count;
END
$_$;


ALTER FUNCTION public.purge_rag_embedding_staging(p_generation_id text, p_materialization_run_id text) OWNER TO flyway;


CREATE FUNCTION public.quarantine_async_job(p_job_id text, p_claim_token uuid, p_error_code text, p_error_class text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE changed integer;
BEGIN
  IF session_user <> 'decision_worker' THEN RAISE EXCEPTION 'async quarantine role denied' USING ERRCODE='42501'; END IF;
  IF p_error_code !~ '^[A-Z][A-Z0-9_]{2,63}$' OR p_error_class !~ '^[A-Z][A-Z0-9_]{2,63}$' THEN
    RAISE EXCEPTION 'invalid async quarantine' USING ERRCODE='22023';
  END IF;
  UPDATE public.async_job SET status='NEEDS_REVIEW',claim_token=NULL,claimed_by=NULL,lease_expires_at=NULL,
    error_code=p_error_code,error_class=p_error_class,error_message=p_error_code,updated_at=statement_timestamp()
  WHERE job_id=p_job_id AND claim_token=p_claim_token AND status='RUNNING'
    AND lease_expires_at>statement_timestamp() AND hard_deadline_at>statement_timestamp();
  GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed=1;
END
$_$;


ALTER FUNCTION public.quarantine_async_job(p_job_id text, p_claim_token uuid, p_error_code text, p_error_class text) OWNER TO flyway;


CREATE FUNCTION public.quarantine_async_work(p_job_id text, p_claim_token uuid, p_dlq_event_id text, p_event_id text, p_event_type text, p_payload_hash text, p_source_topic text, p_attempt integer, p_failure_code text, p_partition_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF session_user <> 'decision_worker' THEN
    RAISE EXCEPTION 'async quarantine role denied' USING ERRCODE = '42501';
  END IF;
  IF NOT public.quarantine_async_job(
    p_job_id, p_claim_token, p_failure_code, 'CONTRACT_VIOLATION'
  ) THEN
    RETURN false;
  END IF;
  PERFORM public.record_kafka_poison(
    p_dlq_event_id, p_event_id, p_event_type, p_payload_hash, p_source_topic,
    p_attempt, p_failure_code, p_partition_key
  );
  RETURN true;
END
$$;


ALTER FUNCTION public.quarantine_async_work(p_job_id text, p_claim_token uuid, p_dlq_event_id text, p_event_id text, p_event_type text, p_payload_hash text, p_source_topic text, p_attempt integer, p_failure_code text, p_partition_key text) OWNER TO flyway;


CREATE FUNCTION public.quarantine_claimed_outbox(p_event_id text, p_claim_token uuid, p_failure_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE changed integer;
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'outbox quarantine role denied' USING ERRCODE = '42501';
  END IF;
  IF p_failure_code !~ '^[A-Z][A-Z0-9_]{2,63}$' THEN
    RAISE EXCEPTION 'invalid quarantine failure' USING ERRCODE = '22023';
  END IF;
  UPDATE public.event_outbox
  SET status = 'DLQ_REQUESTED', claim_token = NULL, claimed_by = NULL, lease_expires_at = NULL,
      failure_code = p_failure_code, error_class = 'CONTRACT_VIOLATION',
      last_error = p_failure_code, updated_at = statement_timestamp()
  WHERE event_id = p_event_id AND claim_token = p_claim_token
    AND status IN ('PENDING', 'FAILED') AND lease_expires_at > statement_timestamp();
  GET DIAGNOSTICS changed = ROW_COUNT;
  RETURN changed = 1;
END
$_$;


ALTER FUNCTION public.quarantine_claimed_outbox(p_event_id text, p_claim_token uuid, p_failure_code text) OWNER TO flyway;


CREATE FUNCTION public.quarantine_unknown_outbox(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  changed integer;
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'outbox quarantine role denied' USING ERRCODE = '42501';
  END IF;
  IF p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'invalid quarantine limit' USING ERRCODE = '22023';
  END IF;
  WITH candidates AS (
    SELECT item.event_id
    FROM public.event_outbox item
    LEFT JOIN public.async_event_registry registry
      ON registry.event_type = item.event_type
     AND registry.outbox_schema_version = item.schema_version
     AND registry.enabled
    WHERE item.status IN ('PENDING', 'FAILED') AND registry.event_type IS NULL
    ORDER BY item.created_at, item.event_id
    FOR UPDATE OF item SKIP LOCKED
    LIMIT p_limit
  )
  UPDATE public.event_outbox item
  SET status = 'DLQ_REQUESTED', failure_code = 'UNREGISTERED_EVENT', error_class = 'CONTRACT_VIOLATION',
      last_error = 'UNREGISTERED_EVENT', claim_token = NULL, claimed_by = NULL,
      lease_expires_at = NULL, updated_at = statement_timestamp()
  FROM candidates
  WHERE item.event_id = candidates.event_id;
  GET DIAGNOSTICS changed = ROW_COUNT;
  RETURN changed;
END
$$;


ALTER FUNCTION public.quarantine_unknown_outbox(p_limit integer) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_document_ir_blocks_are_valid(p_blocks jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  block jsonb;
  cell jsonb;
  item jsonb;
  key text;
  block_type text;
  locator jsonb;
BEGIN
  IF jsonb_typeof(p_blocks) <> 'array'
     OR jsonb_array_length(p_blocks) NOT BETWEEN 1 AND 50000 THEN
    RETURN false;
  END IF;

  FOR block IN SELECT value FROM jsonb_array_elements(p_blocks)
  LOOP
    IF jsonb_typeof(block) <> 'object'
       OR NOT (block ? 'blockType')
       OR block ->> 'blockType' NOT IN ('HEADING', 'PARAGRAPH', 'LIST', 'TABLE', 'FORMULA', 'CAPTION') THEN
      RETURN false;
    END IF;
    block_type := block ->> 'blockType';
    locator := block -> 'locator';
    IF NOT public.rag_v2_immutable_locator_is_valid(locator) THEN
      RETURN false;
    END IF;
    IF jsonb_typeof(block -> 'readingOrder') <> 'number'
       OR block ->> 'readingOrder' !~ '^[0-9]+$'
       OR NOT (block ? 'ocrConfidence')
       OR jsonb_typeof(block -> 'ocrConfidence') NOT IN ('null', 'number') THEN
      RETURN false;
    END IF;
    IF jsonb_typeof(block -> 'ocrConfidence') = 'number'
       AND (block ->> 'ocrConfidence')::double precision NOT BETWEEN 0 AND 1 THEN
      RETURN false;
    END IF;

    FOR key IN SELECT jsonb_object_keys(block)
    LOOP
      IF block_type = 'HEADING' AND key <> ALL (ARRAY['blockType', 'locator', 'readingOrder', 'ocrConfidence', 'level', 'text']) THEN
        RETURN false;
      ELSIF block_type = 'PARAGRAPH' AND key <> ALL (ARRAY['blockType', 'locator', 'readingOrder', 'ocrConfidence', 'text']) THEN
        RETURN false;
      ELSIF block_type = 'CAPTION' AND key <> ALL (ARRAY['blockType', 'locator', 'readingOrder', 'ocrConfidence', 'text', 'targetReadingOrder']) THEN
        RETURN false;
      ELSIF block_type = 'LIST' AND key <> ALL (ARRAY['blockType', 'locator', 'readingOrder', 'ocrConfidence', 'items', 'ordered']) THEN
        RETURN false;
      ELSIF block_type = 'TABLE' AND key <> ALL (ARRAY['blockType', 'locator', 'readingOrder', 'ocrConfidence', 'cells', 'rowCount', 'columnCount']) THEN
        RETURN false;
      ELSIF block_type = 'FORMULA' AND key <> ALL (ARRAY['blockType', 'locator', 'readingOrder', 'ocrConfidence', 'normalizedFormula', 'sourceText']) THEN
        RETURN false;
      END IF;
    END LOOP;

    IF block_type = 'HEADING' THEN
      IF jsonb_typeof(block -> 'level') <> 'number'
         OR block ->> 'level' !~ '^[1-6]$'
         OR jsonb_typeof(block -> 'text') <> 'string'
         OR char_length(block ->> 'text') NOT BETWEEN 1 AND 65536 THEN
        RETURN false;
      END IF;
    ELSIF block_type = 'PARAGRAPH' THEN
      IF jsonb_typeof(block -> 'text') <> 'string'
         OR char_length(block ->> 'text') NOT BETWEEN 1 AND 65536 THEN
        RETURN false;
      END IF;
    ELSIF block_type = 'CAPTION' THEN
      IF jsonb_typeof(block -> 'text') <> 'string'
         OR char_length(block ->> 'text') NOT BETWEEN 1 AND 65536
         OR jsonb_typeof(block -> 'targetReadingOrder') <> 'number'
         OR block ->> 'targetReadingOrder' !~ '^[0-9]+$' THEN
        RETURN false;
      END IF;
    ELSIF block_type = 'LIST' THEN
      IF jsonb_typeof(block -> 'items') <> 'array'
         OR jsonb_array_length(block -> 'items') NOT BETWEEN 1 AND 1000
         OR jsonb_typeof(block -> 'ordered') <> 'boolean' THEN
        RETURN false;
      END IF;
      FOR item IN SELECT value FROM jsonb_array_elements(block -> 'items')
      LOOP
        IF jsonb_typeof(item) <> 'string'
           OR char_length(item #>> '{}') NOT BETWEEN 1 AND 65536 THEN
          RETURN false;
        END IF;
      END LOOP;
    ELSIF block_type = 'TABLE' THEN
      IF jsonb_typeof(block -> 'cells') <> 'array'
         OR jsonb_array_length(block -> 'cells') NOT BETWEEN 1 AND 50000
         OR jsonb_typeof(block -> 'rowCount') <> 'number'
         OR jsonb_typeof(block -> 'columnCount') <> 'number'
         OR block ->> 'rowCount' !~ '^[1-9][0-9]*$'
         OR block ->> 'columnCount' !~ '^[1-9][0-9]*$'
         OR (block ->> 'rowCount')::integer > 50000
         OR (block ->> 'columnCount')::integer > 256
         OR (block ->> 'rowCount')::integer * (block ->> 'columnCount')::integer > 50000 THEN
        RETURN false;
      END IF;
      FOR cell IN SELECT value FROM jsonb_array_elements(block -> 'cells')
      LOOP
        IF jsonb_typeof(cell) <> 'object'
           OR EXISTS (
             SELECT 1 FROM jsonb_object_keys(cell) AS cell_key
             WHERE cell_key NOT IN ('row', 'column', 'rowSpan', 'columnSpan', 'text')
           )
           OR jsonb_typeof(cell -> 'row') <> 'number'
           OR jsonb_typeof(cell -> 'column') <> 'number'
           OR jsonb_typeof(cell -> 'rowSpan') <> 'number'
           OR jsonb_typeof(cell -> 'columnSpan') <> 'number'
           OR jsonb_typeof(cell -> 'text') <> 'string'
           OR cell ->> 'row' !~ '^[0-9]+$'
           OR cell ->> 'column' !~ '^[0-9]+$'
           OR cell ->> 'rowSpan' !~ '^[1-9][0-9]*$'
           OR cell ->> 'columnSpan' !~ '^[1-9][0-9]*$'
           OR (cell ->> 'row')::integer >= (block ->> 'rowCount')::integer
           OR (cell ->> 'column')::integer >= (block ->> 'columnCount')::integer
           OR (cell ->> 'row')::integer + (cell ->> 'rowSpan')::integer > (block ->> 'rowCount')::integer
           OR (cell ->> 'column')::integer + (cell ->> 'columnSpan')::integer > (block ->> 'columnCount')::integer
           OR char_length(cell ->> 'text') NOT BETWEEN 1 AND 65536 THEN
          RETURN false;
        END IF;
      END LOOP;
    ELSE
      IF jsonb_typeof(block -> 'normalizedFormula') <> 'string'
         OR jsonb_typeof(block -> 'sourceText') <> 'string'
         OR char_length(block ->> 'normalizedFormula') NOT BETWEEN 1 AND 65536
         OR char_length(block ->> 'sourceText') NOT BETWEEN 1 AND 65536 THEN
        RETURN false;
      END IF;
    END IF;
  END LOOP;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_blocks) AS block_value
    GROUP BY block_value ->> 'readingOrder'
    HAVING COUNT(*) > 1
  ) THEN
    RETURN false;
  END IF;
  RETURN true;
END;
$_$;


ALTER FUNCTION public.rag_v2_immutable_document_ir_blocks_are_valid(p_blocks jsonb) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_document_ir_structure_is_valid(p_document_ir jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  language_tag jsonb;
  parser_evidence jsonb;
  ocr_evidence jsonb;
  safety jsonb;
  ocr_backend text;
BEGIN
  IF jsonb_typeof(p_document_ir) <> 'object'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_document_ir) AS root_key
       WHERE root_key NOT IN (
         'contractId', 'documentIrVersion', 'sourceId', 'sourceRevisionId', 'mimeType',
         'rawContentSha256', 'normalizedContentSha256', 'languageTags', 'extractionMode',
         'parserEvidence', 'blocks', 'safetyClassification'
       )
     )
     OR NOT (p_document_ir ?& ARRAY[
       'contractId', 'documentIrVersion', 'sourceId', 'sourceRevisionId', 'mimeType',
       'rawContentSha256', 'normalizedContentSha256', 'languageTags', 'extractionMode',
       'parserEvidence', 'blocks', 'safetyClassification'
     ])
     OR p_document_ir ->> 'contractId' <> 'rag-document-ir-v1'
     OR jsonb_typeof(p_document_ir -> 'documentIrVersion') <> 'number'
     OR p_document_ir ->> 'documentIrVersion' <> '1'
     OR jsonb_typeof(p_document_ir -> 'sourceId') <> 'string'
     OR p_document_ir ->> 'sourceId' !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
     OR jsonb_typeof(p_document_ir -> 'sourceRevisionId') <> 'string'
     OR p_document_ir ->> 'sourceRevisionId' !~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_document_ir ->> 'mimeType' NOT IN (
       'application/pdf',
       'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
       'application/vnd.openxmlformats-officedocument.presentationml.presentation',
       'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
       'text/html', 'text/markdown', 'text/plain', 'image/png', 'image/jpeg', 'image/tiff'
     )
     OR jsonb_typeof(p_document_ir -> 'rawContentSha256') <> 'string'
     OR p_document_ir ->> 'rawContentSha256' !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_document_ir -> 'normalizedContentSha256') <> 'string'
     OR p_document_ir ->> 'normalizedContentSha256' !~ '^[0-9a-f]{64}$'
     OR p_document_ir ->> 'extractionMode' NOT IN ('NATIVE', 'MIXED', 'OCR')
     OR NOT public.rag_v2_immutable_document_ir_blocks_are_valid(p_document_ir -> 'blocks') THEN
    RETURN false;
  END IF;

  IF jsonb_typeof(p_document_ir -> 'languageTags') <> 'array'
     OR jsonb_array_length(p_document_ir -> 'languageTags') NOT BETWEEN 1 AND 10 THEN
    RETURN false;
  END IF;
  FOR language_tag IN SELECT value FROM jsonb_array_elements(p_document_ir -> 'languageTags')
  LOOP
    IF jsonb_typeof(language_tag) <> 'string'
       OR language_tag #>> '{}' !~ '^[a-z]{2,3}(-[A-Z]{2})?$' THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(p_document_ir -> 'languageTags') AS tags(value)
    GROUP BY value
    HAVING COUNT(*) > 1
  ) THEN
    RETURN false;
  END IF;

  parser_evidence := p_document_ir -> 'parserEvidence';
  IF jsonb_typeof(parser_evidence) <> 'object'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(parser_evidence) AS parser_key
       WHERE parser_key NOT IN ('parserBackend', 'parserVersion', 'parserArtifactSha256', 'ocr')
     )
     OR NOT (parser_evidence ?& ARRAY['parserBackend', 'parserVersion', 'parserArtifactSha256', 'ocr'])
     OR jsonb_typeof(parser_evidence -> 'parserBackend') <> 'string'
     OR char_length(parser_evidence ->> 'parserBackend') NOT BETWEEN 1 AND 128
     OR jsonb_typeof(parser_evidence -> 'parserVersion') <> 'string'
     OR char_length(parser_evidence ->> 'parserVersion') NOT BETWEEN 1 AND 128
     OR jsonb_typeof(parser_evidence -> 'parserArtifactSha256') <> 'string'
     OR parser_evidence ->> 'parserArtifactSha256' !~ '^[0-9a-f]{64}$' THEN
    RETURN false;
  END IF;
  ocr_evidence := parser_evidence -> 'ocr';
  IF jsonb_typeof(ocr_evidence) <> 'object'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(ocr_evidence) AS ocr_key
       WHERE ocr_key NOT IN ('backend', 'backendVersion', 'modelSha256')
     )
     OR NOT (ocr_evidence ?& ARRAY['backend', 'backendVersion', 'modelSha256']) THEN
    RETURN false;
  END IF;
  ocr_backend := ocr_evidence ->> 'backend';
  IF jsonb_typeof(ocr_evidence -> 'backend') <> 'string'
     OR ocr_backend NOT IN ('NOT_USED', 'PADDLE_STRUCTURED', 'PADDLE_VL', 'UNLIMITED_GGUF') THEN
    RETURN false;
  END IF;
  IF ocr_backend = 'NOT_USED' THEN
    IF jsonb_typeof(ocr_evidence -> 'backendVersion') <> 'null'
       OR jsonb_typeof(ocr_evidence -> 'modelSha256') <> 'null' THEN
      RETURN false;
    END IF;
  ELSIF jsonb_typeof(ocr_evidence -> 'backendVersion') <> 'string'
     OR char_length(ocr_evidence ->> 'backendVersion') NOT BETWEEN 1 AND 128
     OR jsonb_typeof(ocr_evidence -> 'modelSha256') <> 'string'
     OR ocr_evidence ->> 'modelSha256' !~ '^[0-9a-f]{64}$' THEN
    RETURN false;
  END IF;

  safety := p_document_ir -> 'safetyClassification';
  IF jsonb_typeof(safety) <> 'object'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(safety) AS safety_key
       WHERE safety_key NOT IN ('externalLlmEligible', 'piiDetected', 'promptInjectionDetected', 'secretDetected')
     )
     OR NOT (safety ?& ARRAY['externalLlmEligible', 'piiDetected', 'promptInjectionDetected', 'secretDetected']) THEN
    RETURN false;
  END IF;
  FOR language_tag IN SELECT value FROM jsonb_each(safety)
  LOOP
    IF jsonb_typeof(language_tag) <> 'boolean' THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END;
$_$;


ALTER FUNCTION public.rag_v2_immutable_document_ir_structure_is_valid(p_document_ir jsonb) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_empty_owner_scope_is_current(p_owner_user_id text, p_owner_pointer_version bigint, p_exact30_generation_id text, p_oa112_generation_id text, p_embedding_profile_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  bundle public.rag_v2_immutable_bundles%ROWTYPE;
BEGIN
  IF p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_owner_pointer_version < 0
     OR p_exact30_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_oa112_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR p_exact30_generation_id = p_oa112_generation_id
     OR p_embedding_profile_id NOT IN ('bge_m3_local_1024_v1', 'voyage_context_4_1024_v1') THEN
    RETURN false;
  END IF;

  SELECT * INTO pointer
  FROM public.rag_v2_immutable_owner_bundle_pointers AS current_pointer
  WHERE current_pointer.owner_user_id = p_owner_user_id;
  IF NOT FOUND THEN
    RETURN p_owner_pointer_version = 0;
  END IF;
  IF pointer.bundle_version <> p_owner_pointer_version THEN
    RETURN false;
  END IF;
  IF pointer.state = 'ABSENT' THEN
    RETURN pointer.active_bundle_id IS NULL;
  END IF;
  IF pointer.state <> 'READY' OR pointer.active_bundle_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT * INTO bundle
  FROM public.rag_v2_immutable_bundles AS current_bundle
  WHERE current_bundle.bundle_id = pointer.active_bundle_id
    AND current_bundle.owner_user_id = p_owner_user_id
    AND current_bundle.state = 'ACTIVE'
    AND current_bundle.evaluation_status = 'PASSED'
    AND current_bundle.owner_embedding_profile_id IS NULL
    AND current_bundle.exact30_generation_id = p_exact30_generation_id
    AND current_bundle.oa112_generation_id = p_oa112_generation_id
    AND current_bundle.embedding_profile_id = p_embedding_profile_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF bundle.owner_private_generation_id IS NULL THEN
    RETURN true;
  END IF;

  RETURN NOT EXISTS (
           SELECT 1
           FROM public.rag_v2_immutable_source_revisions AS source
           WHERE source.owner_user_id = p_owner_user_id
             AND source.source_scope = 'OWNER_PRIVATE'
         )
    AND EXISTS (
      SELECT 1
      FROM public.rag_v2_immutable_component_generations AS generation
      WHERE generation.component_generation_id = bundle.owner_private_generation_id
        AND generation.owner_user_id = p_owner_user_id
        AND generation.component_scope = 'OWNER_PRIVATE'
        AND generation.embedding_profile_id = p_embedding_profile_id
        AND generation.state = 'ACTIVE'
        AND generation.evaluation_status = 'PASSED'
        AND generation.expected_source_count = 0
        AND generation.actual_source_count = 0
        AND generation.expected_chunk_count = 0
        AND generation.actual_chunk_count = 0
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.rag_v2_immutable_generation_memberships AS membership
      WHERE membership.component_generation_id = bundle.owner_private_generation_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.rag_v2_immutable_generation_embeddings AS embedding
      WHERE embedding.component_generation_id = bundle.owner_private_generation_id
    );
END
$_$;


ALTER FUNCTION public.rag_v2_immutable_empty_owner_scope_is_current(p_owner_user_id text, p_owner_pointer_version bigint, p_exact30_generation_id text, p_oa112_generation_id text, p_embedding_profile_id text) OWNER TO flyway;


