CREATE FUNCTION public.rag_v2_immutable_locator_is_valid(p_locator jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  locator_key text;
  locator_value text;
BEGIN
  IF jsonb_typeof(p_locator) <> 'object'
     OR (SELECT COUNT(*) FROM jsonb_object_keys(p_locator)) <> 1 THEN
    RETURN false;
  END IF;
  FOR locator_key IN SELECT jsonb_object_keys(p_locator)
  LOOP
    IF locator_key IN ('page', 'slide') THEN
      IF jsonb_typeof(p_locator -> locator_key) <> 'number'
         OR p_locator ->> locator_key !~ '^[1-9][0-9]*$' THEN
        RETURN false;
      END IF;
    ELSIF locator_key IN ('sheet', 'section') THEN
      locator_value := p_locator ->> locator_key;
      IF jsonb_typeof(p_locator -> locator_key) <> 'string'
         OR char_length(locator_value) < 1
         OR char_length(locator_value) > (CASE WHEN locator_key = 'sheet' THEN 128 ELSE 300 END)
         OR locator_value ~ '[[:cntrl:]]'
         OR locator_value ~ '(^/|^\\\\|^[A-Za-z]:[\\\\/]|^[A-Za-z][A-Za-z0-9+.-]*://|[\\\\/]|(^|[\\\\/])\\.\\.?([\\\\/]|$))' THEN
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END;
$_$;


ALTER FUNCTION public.rag_v2_immutable_locator_is_valid(p_locator jsonb) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_oa_source_card_v4_is_valid(p_card jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  nested_key text;
  author_value jsonb;
BEGIN
  IF jsonb_typeof(p_card) <> 'object'
     OR EXISTS (
       SELECT 1
       FROM jsonb_object_keys(p_card) AS root_key
       WHERE root_key NOT IN (
         'accessEvidence', 'activeOa112Eligible', 'authors', 'canonicalUrl', 'canonicalUrlSha256',
         'contractId', 'identifier', 'licenseEvidenceDigest', 'mimeType', 'permissions',
         'rawContentSha256', 'revision', 'revisionDate', 'schemaVersion', 'sourceId', 'sourceKind', 'title'
       )
     )
     OR NOT (p_card ?& ARRAY[
       'accessEvidence', 'activeOa112Eligible', 'authors', 'canonicalUrl', 'canonicalUrlSha256',
       'contractId', 'identifier', 'licenseEvidenceDigest', 'mimeType', 'permissions',
       'rawContentSha256', 'revision', 'revisionDate', 'schemaVersion', 'sourceId', 'sourceKind', 'title'
     ])
     OR jsonb_typeof(p_card -> 'contractId') <> 'string'
     OR p_card ->> 'contractId' <> 'rag-source-card-v4'
     OR jsonb_typeof(p_card -> 'schemaVersion') <> 'number'
     OR p_card ->> 'schemaVersion' <> '4'
     OR jsonb_typeof(p_card -> 'sourceKind') <> 'string'
     OR p_card ->> 'sourceKind' <> 'OPEN_ACCESS_DOCUMENT'
     OR jsonb_typeof(p_card -> 'activeOa112Eligible') <> 'boolean'
     OR jsonb_typeof(p_card -> 'title') <> 'string'
     OR char_length(p_card ->> 'title') NOT BETWEEN 1 AND 500
     OR jsonb_typeof(p_card -> 'canonicalUrl') <> 'string'
     OR NOT public.rag_v2_immutable_public_https_url_is_valid(p_card ->> 'canonicalUrl')
     OR jsonb_typeof(p_card -> 'canonicalUrlSha256') <> 'string'
     OR p_card ->> 'canonicalUrlSha256' <> encode(public.digest(p_card ->> 'canonicalUrl', 'sha256'), 'hex')
     OR jsonb_typeof(p_card -> 'licenseEvidenceDigest') <> 'string'
     OR p_card ->> 'licenseEvidenceDigest' !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_card -> 'rawContentSha256') <> 'string'
     OR p_card ->> 'rawContentSha256' !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_card -> 'revision') <> 'string'
     OR char_length(p_card ->> 'revision') NOT BETWEEN 1 AND 128
     OR jsonb_typeof(p_card -> 'revisionDate') <> 'string'
     OR p_card ->> 'revisionDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     OR jsonb_typeof(p_card -> 'sourceId') <> 'string'
     OR p_card ->> 'sourceId' !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
     OR jsonb_typeof(p_card -> 'mimeType') <> 'string'
     OR p_card ->> 'mimeType' NOT IN ('application/pdf', 'text/html', 'text/plain') THEN
    RETURN false;
  END IF;

  IF jsonb_typeof(p_card -> 'authors') <> 'array'
     OR jsonb_array_length(p_card -> 'authors') NOT BETWEEN 1 AND 50 THEN
    RETURN false;
  END IF;
  FOR author_value IN SELECT value FROM jsonb_array_elements(p_card -> 'authors')
  LOOP
    IF jsonb_typeof(author_value) <> 'string'
       OR char_length(author_value #>> '{}') NOT BETWEEN 1 AND 300
       OR btrim(author_value #>> '{}') = ''
       OR author_value #>> '{}' ~ '[[:cntrl:]]' THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(p_card -> 'authors') AS authors(value)
    GROUP BY value
    HAVING COUNT(*) > 1
  ) THEN
    RETURN false;
  END IF;

  IF jsonb_typeof(p_card -> 'identifier') <> 'object'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_card -> 'identifier') AS identifier_key
       WHERE identifier_key NOT IN ('scheme', 'value')
     )
     OR NOT ((p_card -> 'identifier') ?& ARRAY['scheme', 'value'])
     OR jsonb_typeof(p_card -> 'identifier' -> 'scheme') <> 'string'
     OR p_card -> 'identifier' ->> 'scheme' NOT IN ('DOI', 'ISBN', 'ARXIV')
     OR jsonb_typeof(p_card -> 'identifier' -> 'value') <> 'string'
     OR char_length(p_card -> 'identifier' ->> 'value') NOT BETWEEN 1 AND 256 THEN
    RETURN false;
  END IF;

  IF jsonb_typeof(p_card -> 'permissions') <> 'object'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_card -> 'permissions') AS permission_key
       WHERE permission_key NOT IN (
         'machineFetchAllowed', 'localProcessingAllowed', 'externalEmbeddingAllowed', 'externalGenerationAllowed'
       )
     )
     OR NOT ((p_card -> 'permissions') ?& ARRAY[
       'machineFetchAllowed', 'localProcessingAllowed', 'externalEmbeddingAllowed', 'externalGenerationAllowed'
     ]) THEN
    RETURN false;
  END IF;
  FOR nested_key IN SELECT jsonb_object_keys(p_card -> 'permissions')
  LOOP
    IF jsonb_typeof(p_card -> 'permissions' -> nested_key) <> 'boolean' THEN
      RETURN false;
    END IF;
  END LOOP;

  IF jsonb_typeof(p_card -> 'accessEvidence') <> 'object'
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_card -> 'accessEvidence') AS evidence_key
       WHERE evidence_key NOT IN ('accessCheckedAt', 'accessEvidenceDigest', 'verificationState')
     )
     OR NOT ((p_card -> 'accessEvidence') ?& ARRAY['accessCheckedAt', 'accessEvidenceDigest', 'verificationState'])
     OR jsonb_typeof(p_card -> 'accessEvidence' -> 'accessCheckedAt') <> 'string'
     OR p_card -> 'accessEvidence' ->> 'accessCheckedAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?Z$'
     OR jsonb_typeof(p_card -> 'accessEvidence' -> 'accessEvidenceDigest') <> 'string'
     OR p_card -> 'accessEvidence' ->> 'accessEvidenceDigest' !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_card -> 'accessEvidence' -> 'verificationState') <> 'string'
     OR p_card -> 'accessEvidence' ->> 'verificationState' <> 'VERIFIED' THEN
    RETURN false;
  END IF;

  RETURN p_card ->> 'activeOa112Eligible' = 'false'
    OR (
      p_card -> 'permissions' ->> 'machineFetchAllowed' = 'true'
      AND p_card -> 'permissions' ->> 'localProcessingAllowed' = 'true'
      AND p_card -> 'permissions' ->> 'externalEmbeddingAllowed' = 'true'
      AND p_card -> 'permissions' ->> 'externalGenerationAllowed' = 'true'
    );
END;
$_$;


ALTER FUNCTION public.rag_v2_immutable_oa_source_card_v4_is_valid(p_card jsonb) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_public_bge_component_hashes_are_valid(p_component_generation_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  generation_record public.rag_v2_immutable_component_generations%ROWTYPE;
  manifest_record public.rag_v2_immutable_public_component_manifests%ROWTYPE;
  observed_member_digests text[];
  observed_source_total integer;
  observed_chunk_total integer;
  expected_manifest_hash text;
  expected_generation_hash text;
BEGIN
  SELECT * INTO generation_record
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = p_component_generation_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  SELECT * INTO manifest_record
  FROM public.rag_v2_immutable_public_component_manifests
  WHERE component_generation_id = p_component_generation_id;
  IF NOT FOUND
     OR generation_record.owner_user_id IS NOT NULL
     OR generation_record.component_scope NOT IN ('EXACT30', 'OA112')
     OR generation_record.embedding_profile_id <> 'bge_m3_local_1024_v1'
     OR manifest_record.component_scope <> generation_record.component_scope
     OR manifest_record.embedding_profile_id <> generation_record.embedding_profile_id
     OR manifest_record.manifest_hash <> generation_record.manifest_hash
     OR manifest_record.generation_hash <> generation_record.generation_hash THEN
    RETURN false;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM (
      SELECT DISTINCT membership.source_revision_id
      FROM public.rag_v2_immutable_generation_memberships AS membership
      WHERE membership.component_generation_id = p_component_generation_id
        AND membership.component_scope = generation_record.component_scope
    ) AS selected_source
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = selected_source.source_revision_id
    WHERE source.owner_user_id IS NOT NULL
       OR source.source_scope <> generation_record.component_scope
       OR (
         generation_record.component_scope = 'EXACT30'
         AND public.rag_v2_immutable_exact30_source_is_approved(
           source.source_id,
           source.canonical_https_url,
           source.raw_content_sha256,
           source.exact30_source_card_sha256
         ) IS NOT TRUE
       )
       OR (
         SELECT count(*)
         FROM public.rag_v2_immutable_generation_memberships AS source_membership
         WHERE source_membership.component_generation_id = p_component_generation_id
           AND source_membership.component_scope = generation_record.component_scope
           AND source_membership.source_revision_id = source.source_revision_id
       ) <> (
         SELECT count(*)
         FROM public.rag_v2_immutable_chunks AS source_chunk
         WHERE source_chunk.source_revision_id = source.source_revision_id
           AND source_chunk.source_scope = generation_record.component_scope
           AND source_chunk.owner_user_id IS NULL
       )
  ) THEN
    RETURN false;
  END IF;
  SELECT
    array_agg(
      public.rag_v2_immutable_public_bge_source_member_digest(selected_source.source_revision_id, generation_record.component_scope)
      ORDER BY pg_catalog.convert_to(selected_source.source_id, 'UTF8')
    ),
    count(*)::integer,
    coalesce(sum(selected_source.chunk_count), 0)::integer
  INTO observed_member_digests, observed_source_total, observed_chunk_total
  FROM (
    SELECT source.source_revision_id, source.source_id, count(membership.chunk_id)::integer AS chunk_count
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    WHERE membership.component_generation_id = p_component_generation_id
      AND membership.component_scope = generation_record.component_scope
    GROUP BY source.source_revision_id, source.source_id
  ) AS selected_source;
  IF observed_member_digests IS NULL
     OR array_position(observed_member_digests, NULL) IS NOT NULL
     OR observed_source_total <> generation_record.expected_source_count
     OR observed_chunk_total <> generation_record.expected_chunk_count
     OR observed_member_digests IS DISTINCT FROM manifest_record.member_digests THEN
    RETURN false;
  END IF;
  expected_manifest_hash := public.rag_v2_immutable_public_bge_manifest_hash(
    generation_record.component_scope,
    manifest_record.member_digests
  );
  expected_generation_hash := public.rag_v2_immutable_public_bge_generation_hash(
    generation_record.component_scope,
    generation_record.expected_source_count,
    generation_record.expected_chunk_count,
    expected_manifest_hash
  );
  RETURN expected_manifest_hash = generation_record.manifest_hash
    AND expected_generation_hash = generation_record.generation_hash
    AND p_component_generation_id = 'rgr_' || substr(expected_generation_hash, 1, 32);
END;
$$;


ALTER FUNCTION public.rag_v2_immutable_public_bge_component_hashes_are_valid(p_component_generation_id text) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_public_bge_generation_hash(p_component_scope text, p_expected_source_count integer, p_expected_chunk_count integer, p_manifest_hash text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
BEGIN
  IF p_component_scope NOT IN ('EXACT30', 'OA112')
     OR p_expected_source_count <> (CASE p_component_scope WHEN 'EXACT30' THEN 30 ELSE 112 END)
     OR p_expected_chunk_count < p_expected_source_count
     OR p_manifest_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE generation hash arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN encode(public.digest(convert_to(
    '{"componentScope":' || pg_catalog.to_json(p_component_scope)::text ||
    ',"embeddingProfileId":"bge_m3_local_1024_v1","expectedChunkCount":' ||
    p_expected_chunk_count::text || ',"expectedSourceCount":' || p_expected_source_count::text ||
    ',"manifestHash":' || pg_catalog.to_json(p_manifest_hash)::text || ',"schemaVersion":1}',
    'UTF8'
  ), 'sha256'), 'hex');
END;
$_$;


ALTER FUNCTION public.rag_v2_immutable_public_bge_generation_hash(p_component_scope text, p_expected_source_count integer, p_expected_chunk_count integer, p_manifest_hash text) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_public_bge_manifest_hash(p_component_scope text, p_member_digests text[]) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  encoded_members text;
BEGIN
  IF p_component_scope NOT IN ('EXACT30', 'OA112')
     OR cardinality(p_member_digests) <> (CASE p_component_scope WHEN 'EXACT30' THEN 30 ELSE 112 END)
     OR array_ndims(p_member_digests) <> 1
     OR array_position(p_member_digests, NULL) IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM unnest(p_member_digests) AS member_digest
       WHERE member_digest !~ '^[0-9a-f]{64}$'
     )
     OR cardinality(p_member_digests) <> (
       SELECT count(DISTINCT member_digest) FROM unnest(p_member_digests) AS member_digest
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE member digest manifest is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT string_agg(pg_catalog.to_json(member_digest)::text, ',' ORDER BY ordinal)
  INTO encoded_members
  FROM unnest(p_member_digests) WITH ORDINALITY AS digest_row(member_digest, ordinal);
  RETURN encode(public.digest(convert_to(
    '{"componentScope":' || pg_catalog.to_json(p_component_scope)::text ||
    ',"embeddingProfileId":"bge_m3_local_1024_v1","members":[' || encoded_members ||
    '],"schemaVersion":1}',
    'UTF8'
  ), 'sha256'), 'hex');
END;
$_$;


ALTER FUNCTION public.rag_v2_immutable_public_bge_manifest_hash(p_component_scope text, p_member_digests text[]) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_public_bge_source_member_digest(p_source_revision_id text, p_component_scope text) RETURNS text
    LANGUAGE plpgsql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  source_record public.rag_v2_immutable_source_revisions%ROWTYPE;
  encoded_chunks text;
  joined_canonical_text text;
BEGIN
  SELECT * INTO source_record
  FROM public.rag_v2_immutable_source_revisions
  WHERE source_revision_id = p_source_revision_id
    AND source_scope = p_component_scope
    AND owner_user_id IS NULL;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT
    string_agg(
      '{"canonicalTextSha256":' || pg_catalog.to_json(chunk.canonical_text_sha256)::text ||
      ',"chunkId":' || pg_catalog.to_json(chunk.chunk_id)::text ||
      ',"chunkOrdinal":' || chunk.chunk_ordinal::text || '}',
      ',' ORDER BY chunk.chunk_ordinal
    ),
    string_agg(
      chunk.canonical_text,
      pg_catalog.chr(10) || pg_catalog.chr(10) ORDER BY chunk.chunk_ordinal
    )
  INTO encoded_chunks, joined_canonical_text
  FROM public.rag_v2_immutable_chunks AS chunk
  WHERE chunk.source_revision_id = p_source_revision_id
    AND chunk.source_scope = p_component_scope
    AND chunk.owner_user_id IS NULL;
  IF encoded_chunks IS NULL OR joined_canonical_text IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN encode(public.digest(convert_to(
    '{"canonicalTextSha256":' || pg_catalog.to_json(encode(
      public.digest(convert_to(joined_canonical_text, 'UTF8'), 'sha256'), 'hex'
    ))::text || ',"chunks":[' || encoded_chunks || '],"documentId":' ||
    pg_catalog.to_json(source_record.document_id)::text || ',"rawContentSha256":' ||
    pg_catalog.to_json(source_record.raw_content_sha256)::text || ',"sourceId":' ||
    pg_catalog.to_json(source_record.source_id)::text || ',"sourceRevisionId":' ||
    pg_catalog.to_json(source_record.source_revision_id)::text || ',"sourceRevisionSha256":' ||
    pg_catalog.to_json(source_record.source_revision_sha256)::text || '}',
    'UTF8'
  ), 'sha256'), 'hex');
END;
$$;


ALTER FUNCTION public.rag_v2_immutable_public_bge_source_member_digest(p_source_revision_id text, p_component_scope text) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_public_https_url_is_valid(p_url text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  host_name text;
BEGIN
  IF octet_length(p_url) NOT BETWEEN 9 AND 2048
     OR p_url !~ '^https://[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)+(/[^[:space:]#]*)?(\?[^[:space:]#]*)?$' THEN
    RETURN false;
  END IF;
  host_name := lower(substring(p_url FROM '^https://([^/]+)'));
  IF host_name IS NULL
     OR host_name ~ '^[0-9.]+$'
     OR host_name = 'localhost'
     OR host_name LIKE 'localhost.%'
     OR host_name LIKE '%.localhost'
     OR host_name LIKE '%.local'
     OR host_name LIKE '%.internal'
     OR host_name LIKE '%.home.arpa'
     OR host_name LIKE '%.test' THEN
    RETURN false;
  END IF;
  RETURN true;
END;
$_$;


ALTER FUNCTION public.rag_v2_immutable_public_https_url_is_valid(p_url text) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_public_voyage_component_hashes_are_valid(p_component_generation_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  generation_record public.rag_v2_immutable_component_generations%ROWTYPE;
  manifest_record public.rag_v2_immutable_public_voyage_component_manifests%ROWTYPE;
  observed_member_digests text[];
  observed_source_total integer;
  observed_chunk_total integer;
  expected_manifest_hash text;
  expected_generation_hash text;
BEGIN
  SELECT * INTO generation_record
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = p_component_generation_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  SELECT * INTO manifest_record
  FROM public.rag_v2_immutable_public_voyage_component_manifests
  WHERE component_generation_id = p_component_generation_id;
  IF NOT FOUND
     OR generation_record.owner_user_id IS NOT NULL
     OR generation_record.component_scope NOT IN ('EXACT30', 'OA112')
     OR generation_record.embedding_profile_id <> 'voyage_context_4_1024_v1'
     OR manifest_record.component_scope <> generation_record.component_scope
     OR manifest_record.embedding_profile_id <> generation_record.embedding_profile_id
     OR manifest_record.manifest_hash <> generation_record.manifest_hash
     OR manifest_record.generation_hash <> generation_record.generation_hash THEN
    RETURN false;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM (
      SELECT DISTINCT membership.source_revision_id
      FROM public.rag_v2_immutable_generation_memberships AS membership
      WHERE membership.component_generation_id = p_component_generation_id
        AND membership.component_scope = generation_record.component_scope
    ) AS selected_source
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = selected_source.source_revision_id
    WHERE source.owner_user_id IS NOT NULL
       OR source.source_scope <> generation_record.component_scope
       OR (
         generation_record.component_scope = 'EXACT30'
         AND (
           NOT source.external_processing_eligible
           OR source.machine_fetch_allowed
           OR NOT source.local_processing_allowed
           OR NOT source.external_embedding_allowed
           OR NOT source.external_generation_allowed
           OR public.rag_v2_immutable_external_exact30_voyage_source_is_approved(
             source.source_id,
             source.canonical_https_url,
             source.raw_content_sha256,
             source.exact30_source_card_sha256
           ) IS NOT TRUE
         )
       )
       OR (
         SELECT count(*)
         FROM public.rag_v2_immutable_generation_memberships AS source_membership
         WHERE source_membership.component_generation_id = p_component_generation_id
           AND source_membership.component_scope = generation_record.component_scope
           AND source_membership.source_revision_id = source.source_revision_id
       ) <> (
         SELECT count(*)
         FROM public.rag_v2_immutable_chunks AS source_chunk
         WHERE source_chunk.source_revision_id = source.source_revision_id
           AND source_chunk.source_scope = generation_record.component_scope
           AND source_chunk.owner_user_id IS NULL
       )
  ) THEN
    RETURN false;
  END IF;
  SELECT
    array_agg(
      public.rag_v2_immutable_public_voyage_source_member_digest(
        p_component_generation_id,
        selected_source.source_revision_id
      )
      ORDER BY pg_catalog.convert_to(selected_source.source_id, 'UTF8')
    ),
    count(*)::integer,
    coalesce(sum(selected_source.chunk_count), 0)::integer
  INTO observed_member_digests, observed_source_total, observed_chunk_total
  FROM (
    SELECT source.source_revision_id, source.source_id, count(membership.chunk_id)::integer AS chunk_count
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
    WHERE membership.component_generation_id = p_component_generation_id
      AND membership.component_scope = generation_record.component_scope
    GROUP BY source.source_revision_id, source.source_id
  ) AS selected_source;
  IF observed_member_digests IS NULL
     OR array_position(observed_member_digests, NULL) IS NOT NULL
     OR observed_source_total <> generation_record.expected_source_count
     OR observed_chunk_total <> generation_record.expected_chunk_count
     OR observed_member_digests IS DISTINCT FROM manifest_record.member_digests THEN
    RETURN false;
  END IF;
  expected_manifest_hash := public.rag_v2_immutable_public_voyage_manifest_hash(
    generation_record.component_scope,
    manifest_record.member_digests
  );
  expected_generation_hash := public.rag_v2_immutable_public_voyage_generation_hash(
    generation_record.component_scope,
    generation_record.expected_source_count,
    generation_record.expected_chunk_count,
    expected_manifest_hash
  );
  RETURN expected_manifest_hash = generation_record.manifest_hash
    AND expected_generation_hash = generation_record.generation_hash
    AND p_component_generation_id = 'rgr_' || substr(expected_generation_hash, 1, 32);
END;
$$;


