CREATE FUNCTION public.rag_v2_immutable_public_voyage_manifest_hash(p_component_scope text, p_member_digests text[]) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  encoded_members text;
BEGIN
  IF p_component_scope NOT IN ('EXACT30', 'OA112')
     OR cardinality(p_member_digests) <> (CASE p_component_scope WHEN 'EXACT30' THEN 30 ELSE 112 END)
     OR array_ndims(p_member_digests) <> 1
     OR array_position(p_member_digests, NULL) IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM unnest(p_member_digests) AS member_digest
       WHERE member_digest !~ '^[0-9a-f]{64}$'
     )
     OR cardinality(p_member_digests) <> (
       SELECT count(DISTINCT member_digest) FROM unnest(p_member_digests) AS member_digest
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage member digest manifest is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT string_agg(pg_catalog.to_json(member_digest)::text, ',' ORDER BY ordinal)
  INTO encoded_members
  FROM unnest(p_member_digests) WITH ORDINALITY AS digest_row(member_digest, ordinal);
  RETURN encode(public.digest(convert_to(
    '{"componentScope":' || pg_catalog.to_json(p_component_scope)::text ||
    ',"embeddingProfileId":"voyage_context_4_1024_v1","members":[' || encoded_members ||
    '],"schemaVersion":1}',
    'UTF8'
  ), 'sha256'), 'hex');
END;
$_$;


ALTER FUNCTION public.rag_v2_immutable_public_voyage_manifest_hash(p_component_scope text, p_member_digests text[]) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_public_voyage_source_member_digest(p_component_generation_id text, p_source_revision_id text) RETURNS text
    LANGUAGE plpgsql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  source_record public.rag_v2_immutable_source_revisions%ROWTYPE;
  oa_card_record public.rag_v2_immutable_oa_source_cards%ROWTYPE;
  encoded_chunks text;
  joined_canonical_text text;
BEGIN
  SELECT source.* INTO source_record
  FROM public.rag_v2_immutable_source_revisions AS source
  JOIN public.rag_v2_immutable_component_generations AS generation
    ON generation.component_generation_id = p_component_generation_id
  WHERE source.source_revision_id = p_source_revision_id
    AND source.source_scope = generation.component_scope
    AND source.owner_user_id IS NULL
    AND generation.owner_user_id IS NULL
    AND generation.embedding_profile_id = 'voyage_context_4_1024_v1';
  IF NOT FOUND
     OR source_record.source_scope NOT IN ('EXACT30', 'OA112')
     OR NOT source_record.external_processing_eligible
     OR (source_record.source_scope = 'EXACT30' AND (
       source_record.machine_fetch_allowed
       OR NOT source_record.local_processing_allowed
       OR NOT source_record.external_embedding_allowed
       OR NOT source_record.external_generation_allowed
       OR public.rag_v2_immutable_external_exact30_voyage_source_is_approved(
         source_record.source_id,
         source_record.canonical_https_url,
         source_record.raw_content_sha256,
         source_record.exact30_source_card_sha256
       ) IS NOT TRUE
     ))
     OR (source_record.source_scope = 'OA112' AND (
       NOT source_record.machine_fetch_allowed
       OR NOT source_record.local_processing_allowed
       OR NOT source_record.external_embedding_allowed
       OR NOT source_record.external_generation_allowed
       OR source_record.oa_track_id IS NULL
       OR source_record.reserve_source
     )) THEN
    RETURN NULL;
  END IF;

  IF source_record.source_scope = 'OA112' THEN
    SELECT * INTO oa_card_record
    FROM public.rag_v2_immutable_oa_source_cards AS card
    WHERE card.source_revision_id = p_source_revision_id
      AND card.source_scope = 'OA112'
      AND card.source_id = source_record.source_id
      AND card.active_oa112_eligible
      AND card.raw_content_sha256 = source_record.raw_content_sha256
      AND card.canonical_https_url = source_record.canonical_https_url
      AND card.license_evidence_sha256 = source_record.license_evidence_sha256
      AND card.access_evidence_sha256 = source_record.access_evidence_sha256
      AND card.machine_fetch_allowed
      AND card.local_processing_allowed
      AND card.external_embedding_allowed
      AND card.external_generation_allowed;
    IF NOT FOUND THEN
      RETURN NULL;
    END IF;
  END IF;

  SELECT
    string_agg(
      '{"canonicalTextSha256":' || pg_catalog.to_json(chunk.canonical_text_sha256)::text ||
      ',"chunkId":' || pg_catalog.to_json(chunk.chunk_id)::text ||
      ',"chunkOrdinal":' || chunk.chunk_ordinal::text ||
      ',"contextSetHash":' || pg_catalog.to_json(embedding.context_set_hash)::text ||
      ',"embeddingInputHash":' || pg_catalog.to_json(embedding.embedding_input_hash)::text || '}',
      ',' ORDER BY chunk.chunk_ordinal
    ),
    string_agg(
      chunk.canonical_text,
      pg_catalog.chr(10) || pg_catalog.chr(10) ORDER BY chunk.chunk_ordinal
    )
  INTO encoded_chunks, joined_canonical_text
  FROM public.rag_v2_immutable_generation_memberships AS membership
  JOIN public.rag_v2_immutable_chunks AS chunk
    ON chunk.chunk_id = membership.chunk_id
   AND chunk.source_revision_id = membership.source_revision_id
   AND chunk.source_scope = membership.component_scope
   AND chunk.owner_user_id IS NULL
  JOIN public.rag_v2_immutable_generation_embeddings AS embedding
    ON embedding.component_generation_id = membership.component_generation_id
   AND embedding.chunk_id = membership.chunk_id
   AND embedding.component_scope = membership.component_scope
   AND embedding.owner_user_id IS NULL
   AND embedding.embedding_profile_id = 'voyage_context_4_1024_v1'
  WHERE membership.component_generation_id = p_component_generation_id
    AND membership.component_scope = source_record.source_scope
    AND membership.source_revision_id = p_source_revision_id;
  IF encoded_chunks IS NULL OR joined_canonical_text IS NULL THEN
    RETURN NULL;
  END IF;
  IF source_record.source_scope = 'EXACT30' THEN
    RETURN encode(public.digest(convert_to(
      '{"canonicalTextSha256":' || pg_catalog.to_json(encode(
        public.digest(convert_to(joined_canonical_text, 'UTF8'), 'sha256'), 'hex'
      ))::text || ',"chunks":[' || encoded_chunks || '],"documentId":' ||
      pg_catalog.to_json(source_record.document_id)::text || ',"rawContentSha256":' ||
      pg_catalog.to_json(source_record.raw_content_sha256)::text || ',"sourceCardSha256":' ||
      pg_catalog.to_json(source_record.exact30_source_card_sha256)::text || ',"sourceId":' ||
      pg_catalog.to_json(source_record.source_id)::text || ',"sourceRevisionId":' ||
      pg_catalog.to_json(source_record.source_revision_id)::text || ',"sourceRevisionSha256":' ||
      pg_catalog.to_json(source_record.source_revision_sha256)::text || '}',
      'UTF8'
    ), 'sha256'), 'hex');
  END IF;
  RETURN encode(public.digest(convert_to(
    '{"accessEvidenceSha256":' || pg_catalog.to_json(source_record.access_evidence_sha256)::text ||
    ',"canonicalTextSha256":' || pg_catalog.to_json(encode(
      public.digest(convert_to(joined_canonical_text, 'UTF8'), 'sha256'), 'hex'
    ))::text || ',"chunks":[' || encoded_chunks || '],"documentId":' ||
    pg_catalog.to_json(source_record.document_id)::text || ',"licenseEvidenceSha256":' ||
    pg_catalog.to_json(source_record.license_evidence_sha256)::text || ',"oaTrackId":' ||
    pg_catalog.to_json(source_record.oa_track_id)::text || ',"rawContentSha256":' ||
    pg_catalog.to_json(source_record.raw_content_sha256)::text || ',"sourceId":' ||
    pg_catalog.to_json(source_record.source_id)::text || ',"sourceRevisionId":' ||
    pg_catalog.to_json(source_record.source_revision_id)::text || ',"sourceRevisionSha256":' ||
    pg_catalog.to_json(source_record.source_revision_sha256)::text || '}',
    'UTF8'
  ), 'sha256'), 'hex');
END;
$$;


ALTER FUNCTION public.rag_v2_immutable_public_voyage_source_member_digest(p_component_generation_id text, p_source_revision_id text) OWNER TO flyway;


CREATE FUNCTION public.rag_v2_immutable_retrieval_topics_are_valid(p_topics text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT cardinality(p_topics) BETWEEN 1 AND 6
    AND p_topics <@ ARRAY[
      'API', 'DATA', 'FINANCIAL_ENGINEERING', 'METHODOLOGY', 'PRODUCT_RISK', 'RISK'
    ]::text[]
    AND cardinality(p_topics) = cardinality(
      ARRAY(SELECT DISTINCT topic FROM unnest(p_topics) AS values(topic))
    )
$$;


ALTER FUNCTION public.rag_v2_immutable_retrieval_topics_are_valid(p_topics text[]) OWNER TO flyway;


CREATE FUNCTION public.read_active_owned_principle_snapshot_authorized(p_capability text, p_actor_user_id text, p_principle_id text) RETURNS TABLE(principle_id text, principle_version_id text, version integer, mode text, status text, rules_json text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN RETURN; END IF;
  RETURN QUERY
  SELECT item.principle_id,version_item.principle_version_id,version_item.version,
    version_item.mode,version_item.status,version_item.rules_json::text
  FROM public.principles item
  JOIN public.principle_versions version_item
    ON version_item.principle_id=item.principle_id AND version_item.version=item.current_version
  WHERE item.principle_id=p_principle_id AND item.user_id=p_actor_user_id
    AND item.status='ACTIVE' AND version_item.status='ACTIVE';
END
$$;


ALTER FUNCTION public.read_active_owned_principle_snapshot_authorized(p_capability text, p_actor_user_id text, p_principle_id text) OWNER TO flyway;


CREATE FUNCTION public.read_active_rag_chunks(p_topic text, p_limit integer) RETURNS TABLE(chunk_revision_id text, source_id text, title text, heading_path text[], canonical_content text, canonical_content_hash text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 30
     OR p_topic IS NULL OR char_length(p_topic) < 1 OR char_length(p_topic) > 128 THEN
    RAISE EXCEPTION 'RAG retrieval projection bounds invalid' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    chunk.chunk_revision_id,
    source.source_id,
    revision.title,
    chunk.heading_path,
    chunk.canonical_content,
    chunk.canonical_content_hash
  FROM public.rag_embedding_policy_state AS policy_state
  JOIN public.rag_corpus_generations AS generation
    ON generation.corpus_generation_id = policy_state.active_generation_id
   AND generation.embedding_profile_id = policy_state.effective_profile_id
   AND generation.status = 'ACTIVE'
   AND generation.evaluation_status = 'PASSED'
  JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = generation.corpus_generation_id
   AND membership.embedding_profile_id = generation.embedding_profile_id
  JOIN public.rag_chunk_revisions AS chunk
    ON chunk.chunk_revision_id = membership.chunk_revision_id
   AND chunk.access_level = 'PUBLIC'
   AND chunk.topic = p_topic
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = chunk.source_revision_id
   AND revision.access_level = 'PUBLIC'
  JOIN public.rag_sources AS source
    ON source.source_id = revision.source_id
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  ORDER BY membership.ordinal
  LIMIT p_limit;
END
$$;


ALTER FUNCTION public.read_active_rag_chunks(p_topic text, p_limit integer) OWNER TO flyway;


CREATE FUNCTION public.read_async_job_status(p_actor_user_id text, p_security_version bigint, p_job_id text) RETURNS TABLE(job_id text, job_type text, status text, requested_at timestamp with time zone, started_at timestamp with time zone, completed_at timestamp with time zone, source_id text, artifact_id text, result_ref text, error_code text, error_class text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor_role text; actor_status text; actor_security_version bigint;
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'async status role denied' USING ERRCODE = '42501';
  END IF;
  SELECT role, users.status, security_version INTO actor_role, actor_status, actor_security_version
  FROM public.users WHERE user_id = p_actor_user_id FOR SHARE;
  IF NOT FOUND OR actor_status <> 'ACTIVE' OR actor_role <> 'ADMIN'
     OR actor_security_version <> p_security_version THEN
    RETURN;
  END IF;
  INSERT INTO public.async_job_admin_read_audit(actor_user_id, target_owner_user_id, job_id, read_kind)
  SELECT p_actor_user_id, item.requested_by, item.job_id, 'DETAIL'
  FROM public.async_job item
  WHERE item.job_id = p_job_id AND item.requested_by IS DISTINCT FROM p_actor_user_id;
  RETURN QUERY
  SELECT item.job_id, item.job_type, item.status, item.created_at, item.started_at, item.completed_at,
         item.payload_json ->> 'sourceId', item.payload_json ->> 'artifactId', item.result_json ->> 'resultRef',
         item.error_code, item.error_class
  FROM public.async_job item
  WHERE item.job_id = p_job_id
  LIMIT 1;
END
$$;


ALTER FUNCTION public.read_async_job_status(p_actor_user_id text, p_security_version bigint, p_job_id text) OWNER TO flyway;


CREATE FUNCTION public.read_async_job_status_authorized(p_capability text, p_actor_user_id text, p_security_version bigint, p_job_id text) RETURNS TABLE(job_id text, job_type text, status text, requested_at timestamp with time zone, started_at timestamp with time zone, completed_at timestamp with time zone, source_id text, artifact_id text, result_ref text, error_code text, error_class text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.consume_actor_request_capability(p_capability,p_actor_user_id,p_security_version,'ADMIN') THEN RETURN; END IF;
  RETURN QUERY SELECT * FROM public.read_async_job_status(p_actor_user_id,p_security_version,p_job_id);
END
$$;


