CREATE FUNCTION public.read_decision_audit_projection() RETURNS TABLE(audit_log_id text, decision_id text, action text, request_id text, created_at timestamp with time zone, payload_json jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT
    audit.audit_log_id,
    audit.target_id AS decision_id,
    audit.action,
    audit.request_id,
    audit.created_at,
    jsonb_build_object(
      'evaluationId', audit.payload_json -> 'evaluationId',
      'decisionId', audit.payload_json -> 'decisionId',
      'outcome', audit.payload_json -> 'outcome',
      'principleVersionId', audit.payload_json -> 'principleVersionId',
      'semanticInputHash', audit.payload_json -> 'semanticInputHash',
      'snapshotArtifactHash', audit.payload_json -> 'snapshotArtifactHash'
    ) AS payload_json
  FROM public.audit_logs audit
  JOIN public.decisions decision
    ON decision.decision_id = audit.target_id
  WHERE
    audit.action = 'DECISION_EVALUATED'
    AND audit.target_type = 'DECISION'
    AND decision.user_id = current_setting('app.actor_user_id', true)
    AND audit.target_id = current_setting('app.requested_decision_id', true)
  ORDER BY audit.created_at DESC, audit.audit_log_id
  LIMIT 1
$$;


ALTER FUNCTION public.read_decision_audit_projection() OWNER TO flyway;


CREATE FUNCTION public.read_decision_owner_projection() RETURNS TABLE(decision_id text, evaluation_id text, owner_user_id text, principle_id text, principle_version_id text, principle_version integer, portfolio_source text, mode text, outcome text, can_submit_order boolean, enforcement_action text, created_at timestamp with time zone, evaluation_as_of timestamp with time zone, valid_until timestamp with time zone, result_schema_version text, snapshot_schema_version text, catalog_version integer, readiness_policy_version text, mapping_versions_json jsonb, semantic_input_hash text, snapshot_artifact_hash text, result_json jsonb, result_canonical_json text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT
    decision.decision_id,
    decision.evaluation_id,
    decision.user_id AS owner_user_id,
    decision.principle_id,
    decision.principle_version_id,
    decision.principle_version,
    decision.portfolio_source,
    decision.mode,
    decision.outcome,
    decision.can_submit_order,
    decision.enforcement_action,
    decision.created_at,
    decision.evaluation_as_of,
    decision.valid_until,
    decision.result_schema_version,
    decision.snapshot_schema_version,
    decision.catalog_version,
    decision.readiness_policy_version,
    decision.mapping_versions_json,
    decision.semantic_input_hash,
    decision.snapshot_artifact_hash,
    decision.result_json,
    artifact.result_canonical_json
  FROM public.decisions decision
  JOIN public.decision_artifacts artifact
    ON artifact.decision_id = decision.decision_id
  WHERE
    decision.user_id = current_setting('app.actor_user_id', true)
    AND decision.decision_id = current_setting('app.requested_decision_id', true)
  LIMIT 1
$$;


ALTER FUNCTION public.read_decision_owner_projection() OWNER TO flyway;


CREATE FUNCTION public.read_decision_usability() RETURNS TABLE(decision_id text, evaluation_id text, valid_until timestamp with time zone, invalidated boolean, invalidation_reason_class text, consumed_by_order_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT
    decision.decision_id,
    decision.evaluation_id,
    decision.valid_until,
    invalidation.invalidation_id IS NOT NULL AS invalidated,
    invalidation.reason_class AS invalidation_reason_class,
    consumed.order_id AS consumed_by_order_id
  FROM public.decisions decision
  LEFT JOIN LATERAL (
    SELECT entry.invalidation_id, entry.reason_class
    FROM public.decision_invalidations entry
    WHERE entry.decision_id = decision.decision_id
    ORDER BY entry.invalidated_at DESC, entry.invalidation_id DESC
    LIMIT 1
  ) invalidation ON true
  LEFT JOIN public.orders consumed
    ON consumed.decision_id = decision.decision_id
  WHERE decision.user_id = current_setting('app.actor_user_id', true)
    AND decision.decision_id = current_setting('app.requested_decision_id', true)
  LIMIT 1
$$;


ALTER FUNCTION public.read_decision_usability() OWNER TO flyway;


CREATE FUNCTION public.read_demo_credentials() RETURNS TABLE(user_id text, username text, password_hash text, role text, status text, security_version bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF session_user <> 'decision_auth' AND NOT EXISTS (
    SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolsuper
  ) THEN RAISE EXCEPTION 'credential reader role denied' USING ERRCODE='42501'; END IF;
  RETURN QUERY SELECT item.user_id,item.username,item.password_hash,item.role,item.status,item.security_version
  FROM public.users item WHERE item.user_id IN ('usr_demo_user','usr_demo_admin') ORDER BY item.user_id;
END
$$;


ALTER FUNCTION public.read_demo_credentials() OWNER TO flyway;


CREATE FUNCTION public.read_effective_rag_consent(p_owner_user_id text) RETURNS TABLE(granted boolean, policy_version text, recorded_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id THEN
    RAISE EXCEPTION 'RAG consent actor binding is invalid'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    coalesce(latest.action = 'GRANT', false),
    latest.policy_version,
    latest.created_at
  FROM (SELECT 1) AS singleton
  LEFT JOIN LATERAL (
    SELECT event.action, event.policy_version, event.created_at
    FROM public.rag_consent_events AS event
    WHERE event.owner_user_id = p_owner_user_id
      AND event.consent_type = 'EXTERNAL_AI_RAG_V1'
    ORDER BY event.consent_sequence DESC
    LIMIT 1
  ) AS latest ON true;
END
$$;


ALTER FUNCTION public.read_effective_rag_consent(p_owner_user_id text) OWNER TO flyway;


CREATE FUNCTION public.read_financial_engineering_snapshot(p_symbol text, p_evaluation_as_of timestamp with time zone) RETURNS TABLE(snapshot_id text, schema_version integer, symbol text, session_date date, as_of timestamp with time zone, available_at timestamp with time zone, source_manifest_hash text, config_hash text, numeric_payload_hash text, artifact_hash text, availability text, quality text, staleness text, numeric_payload jsonb, explanatory_payload jsonb, report_artifact_hash text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT s.snapshot_id, s.schema_version, s.symbol, s.session_date, s.as_of,
         s.available_at, s.source_manifest_hash, s.config_hash,
         s.numeric_payload_hash, s.artifact_hash, s.availability, s.quality,
         s.staleness, s.numeric_payload, s.explanatory_payload,
         r.report_artifact_hash, s.created_at
  FROM public.financial_engineering_snapshots s
  JOIN public.financial_engineering_report_manifests r ON r.snapshot_id = s.snapshot_id
  WHERE session_user = 'decision_app'
    AND s.symbol = p_symbol
    AND s.available_at <= p_evaluation_as_of
    AND r.complete
  ORDER BY s.available_at DESC, s.created_at DESC
  LIMIT 1
$$;


ALTER FUNCTION public.read_financial_engineering_snapshot(p_symbol text, p_evaluation_as_of timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.read_kill_switch_audit_projection() RETURNS TABLE(audit_log_id text, action text, request_id text, created_at timestamp with time zone, payload_json jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT
    audit.audit_log_id,
    audit.action,
    audit.request_id,
    audit.created_at,
    jsonb_build_object(
      'generation', audit.payload_json -> 'generation',
      'previousActive', audit.payload_json -> 'previousActive',
      'nextActive', audit.payload_json -> 'nextActive',
      'reasonClass', audit.payload_json -> 'reasonClass',
      'changedBy', audit.payload_json -> 'changedBy',
      'changedByRole', audit.payload_json -> 'changedByRole',
      'correlationId', audit.payload_json -> 'correlationId',
      'invalidatedDecisionCount', audit.payload_json -> 'invalidatedDecisionCount'
    )
  FROM public.audit_logs audit
  WHERE audit.action = 'KILL_SWITCH_CHANGED'
    AND audit.target_type = 'KILL_SWITCH'
    AND EXISTS (
      SELECT 1
      FROM public.users actor
      WHERE actor.user_id = current_setting('app.actor_user_id', true)
        AND actor.status = 'ACTIVE'
        AND actor.role = 'ADMIN'
    )
  ORDER BY audit.created_at DESC, audit.audit_log_id DESC
  LIMIT 100
$$;


ALTER FUNCTION public.read_kill_switch_audit_projection() OWNER TO flyway;


