CREATE FUNCTION public.read_latest_s48_runtime_sanitized_projection(p_source_id text) RETURNS TABLE(payload_json jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR p_source_id NOT IN (
       'S48_CORE6_KIS', 'S48_CORE6_OPENDART', 'S48_CORE6_SEC_EDGAR', 'S48_CORE6_KRX',
       'S48_CORE6_KOFIA', 'S48_CORE6_ECOS', 'S48_OPTIONAL3_FINNHUB',
       'S48_OPTIONAL3_TWELVE_DATA', 'S48_OPTIONAL3_MASSIVE'
     ) THEN
    RAISE EXCEPTION 'S4.8 runtime reader arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT projection.payload_json
  FROM public.s48_runtime_sanitized_projections AS projection
  WHERE projection.source_id = p_source_id
  ORDER BY projection.evaluated_at DESC, projection.logical_identity_hash DESC
  LIMIT 1;
END
$$;


ALTER FUNCTION public.read_latest_s48_runtime_sanitized_projection(p_source_id text) OWNER TO flyway;


CREATE FUNCTION public.read_mock_order_decision(requested_actor_user_id text, requested_decision_id text, requested_capability_token text) RETURNS TABLE(decision_id text, evaluation_id text, portfolio_source text, outcome text, mode text, can_submit_order boolean, enforcement_action text, valid_until timestamp with time zone, snapshot_artifact_canonical_json text, portfolio_owner_scope_hash text, invalidated boolean, invalidation_reason_class text, consumed_by_order_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  -- decisions는 FORCE RLS이므로 capability 검증 뒤 함수 인자로 받은 owner를 transaction-local로 고정한다.
  PERFORM set_config('app.actor_user_id', requested_actor_user_id, true);
  RETURN QUERY
  SELECT
    decision.decision_id,
    decision.evaluation_id,
    decision.portfolio_source,
    decision.outcome,
    decision.mode,
    decision.can_submit_order,
    decision.enforcement_action,
    decision.valid_until,
    artifact.snapshot_artifact_canonical_json,
    artifact.snapshot_artifact_canonical_json::jsonb #>> '{portfolio,ownerScopeHash}',
    invalidation.invalidation_id IS NOT NULL,
    invalidation.reason_class,
    consumed.order_id
  FROM public.decisions decision
  JOIN public.decision_artifacts artifact
    ON artifact.decision_id = decision.decision_id
   AND artifact.evaluation_id = decision.evaluation_id
  LEFT JOIN LATERAL (
    SELECT entry.invalidation_id, entry.reason_class
    FROM public.decision_invalidations entry
    WHERE entry.decision_id = decision.decision_id
    ORDER BY entry.invalidated_at DESC, entry.invalidation_id DESC
    LIMIT 1
  ) invalidation ON true
  LEFT JOIN public.orders consumed
    ON consumed.decision_id = decision.decision_id
  WHERE decision.user_id = requested_actor_user_id
    AND decision.decision_id = requested_decision_id
    AND EXISTS (
      SELECT 1
      FROM public.users actor
      WHERE actor.user_id = requested_actor_user_id
        AND actor.status = 'ACTIVE'
    )
  LIMIT 1;
END
$$;


ALTER FUNCTION public.read_mock_order_decision(requested_actor_user_id text, requested_decision_id text, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.read_mock_order_owner_projection(requested_actor_user_id text, requested_order_id text, requested_capability_token text) RETURNS TABLE(order_id text, account_id text, brokerage_mode text, status text, submitted_at timestamp with time zone, decision_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  RETURN QUERY
  SELECT
    stored.order_id,
    stored.account_id,
    stored.brokerage_mode,
    COALESCE(latest_event.event_status, stored.status),
    stored.submitted_at,
    stored.decision_id
  FROM public.orders stored
  LEFT JOIN LATERAL (
    SELECT event.event_status
    FROM public.order_events event
    WHERE event.order_id = stored.order_id
      AND event.event_status IS NOT NULL
    ORDER BY event.event_seq DESC
    LIMIT 1
  ) latest_event ON true
  WHERE stored.user_id = requested_actor_user_id
    AND stored.order_id = requested_order_id
    AND EXISTS (
      SELECT 1
      FROM public.users actor
      WHERE actor.user_id = requested_actor_user_id
        AND actor.status = 'ACTIVE'
    )
  LIMIT 1;
END
$$;


ALTER FUNCTION public.read_mock_order_owner_projection(requested_actor_user_id text, requested_order_id text, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.read_order_reconciliation_state(requested_payload jsonb, requested_capability_token text) RETURNS TABLE(operation_outcome text, state_json text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  requested_actor_user_id text;
  requested_actor_role text;
  requested_security_version bigint;
  requested_order_id text;
  requested_reconciled_at timestamptz;
  stored_actor record;
  stored_order record;
  current_status text;
  observations jsonb;
  remaining boolean;
  observation_count bigint;
  observed_fill_quantity bigint;
  recomputed_average bigint;
  provider_final_average bigint;
  fill_notional numeric;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  IF requested_payload IS NULL
     OR jsonb_typeof(requested_payload) <> 'object'
     OR NOT requested_payload ?& ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'orderId', 'reconciledAt'
     ]
     OR requested_payload - ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'orderId', 'reconciledAt'
     ] <> '{}'::jsonb THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;
  requested_actor_user_id := requested_payload ->> 'actorUserId';
  requested_actor_role := requested_payload ->> 'actorRole';
  requested_security_version := (requested_payload ->> 'securityVersion')::bigint;
  requested_order_id := requested_payload ->> 'orderId';
  requested_reconciled_at := (requested_payload ->> 'reconciledAt')::timestamptz;

  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id
  FOR SHARE;
  IF NOT FOUND
     OR stored_actor.status <> 'ACTIVE'
     OR stored_actor.role <> 'ADMIN'
     OR requested_actor_role <> 'ADMIN'
     OR stored_actor.security_version <> requested_security_version THEN
    RETURN QUERY SELECT 'ACTOR_UNAUTHORIZED'::text, NULL::text;
    RETURN;
  END IF;

  SELECT stored.*
  INTO stored_order
  FROM public.orders stored
  WHERE stored.order_id = requested_order_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'ORDER_NOT_FOUND'::text, NULL::text;
    RETURN;
  END IF;

  SELECT event.event_status
  INTO current_status
  FROM public.order_events event
  WHERE event.order_id = requested_order_id
    AND event.event_status IS NOT NULL
  ORDER BY event.event_seq DESC
  LIMIT 1;
  current_status := COALESCE(current_status, stored_order.status);

  IF stored_order.brokerage_mode = 'KIS_MOCK' THEN
    SELECT COALESCE(
      sum(
        applied_observation.fill_quantity::numeric
        * applied_observation.fill_price_krw::numeric
      ) FILTER (
        WHERE applied_receipt.outcome = 'APPLIED'
          AND applied_observation.exec_type IN ('PARTIAL_FILL', 'FILL')
      ),
      0
    )
    INTO fill_notional
    FROM public.order_fill_application_receipts applied_receipt
    JOIN public.order_fill_observations applied_observation
      ON applied_observation.observation_id = applied_receipt.observation_id
    WHERE applied_receipt.order_id = requested_order_id;
  ELSE
    fill_notional :=
      stored_order.filled_quantity::numeric
      * COALESCE(stored_order.average_fill_price_krw, 0)::numeric;
  END IF;

  IF stored_order.brokerage_mode = 'KIS_MOCK' THEN
    SELECT COALESCE(jsonb_agg(candidate.item ORDER BY candidate.observed_at, candidate.observation_id), '[]'::jsonb)
    INTO observations
    FROM (
      SELECT
        observation.observed_at,
        observation.observation_id,
        jsonb_build_object(
          'observationId', observation.observation_id,
          'providerExecRefHash', observation.provider_exec_ref_hash,
          'execType', observation.exec_type,
          'fillQuantity', observation.fill_quantity,
          'fillPriceKrw', observation.fill_price_krw,
          'cumulativeQuantity', observation.cumulative_quantity,
          'leavesQuantity', observation.leaves_quantity,
          'averageFillPriceKrw', observation.average_fill_price_krw,
          'observedAt', observation.observed_at::text
        ) AS item
      FROM public.order_fill_observations observation
      WHERE observation.order_id = requested_order_id
        AND observation.completeness = 'COMPLETE'
        AND observation.observed_at <= requested_reconciled_at
        AND observation.received_at <= requested_reconciled_at
        AND NOT EXISTS (
          SELECT 1
          FROM public.order_fill_application_receipts receipt
          WHERE receipt.observation_id = observation.observation_id
        )
      ORDER BY observation.observed_at, observation.observation_id
      LIMIT 200
    ) candidate;
    SELECT count(*) > 200
    INTO remaining
    FROM public.order_fill_observations observation
    WHERE observation.order_id = requested_order_id
      AND observation.completeness = 'COMPLETE'
      AND observation.observed_at <= requested_reconciled_at
      AND observation.received_at <= requested_reconciled_at
      AND NOT EXISTS (
        SELECT 1
        FROM public.order_fill_application_receipts receipt
        WHERE receipt.observation_id = observation.observation_id
      );
  ELSE
    observations := '[]'::jsonb;
    remaining := false;
  END IF;

  IF stored_order.brokerage_mode = 'INTERNAL_PAPER' THEN
    SELECT
      count(*),
      COALESCE(sum((paper.payload_json ->> 'fillQuantity')::bigint), 0),
      CASE
        WHEN count(*) = 0 THEN NULL
        ELSE trunc(
          sum(
            (paper.payload_json ->> 'fillQuantity')::numeric
            * (paper.payload_json ->> 'fillPriceKrw')::numeric
          )
          / sum((paper.payload_json ->> 'fillQuantity')::numeric)
        )::bigint
      END
    INTO observation_count, observed_fill_quantity, recomputed_average
    FROM public.paper_order_events paper
    WHERE paper.order_id = requested_order_id;
    provider_final_average := recomputed_average;
  ELSE
    SELECT
      count(*),
      COALESCE(
        sum(aggregate_observation.fill_quantity)
          FILTER (WHERE aggregate_observation.exec_type IN ('PARTIAL_FILL', 'FILL')),
        0
      ),
      CASE
        WHEN COALESCE(
          sum(aggregate_observation.fill_quantity)
            FILTER (WHERE aggregate_observation.exec_type IN ('PARTIAL_FILL', 'FILL')),
          0
        ) = 0 THEN NULL
        ELSE trunc(
          sum(
            aggregate_observation.fill_quantity::numeric
            * aggregate_observation.fill_price_krw::numeric
          ) FILTER (WHERE aggregate_observation.exec_type IN ('PARTIAL_FILL', 'FILL'))
          / sum(aggregate_observation.fill_quantity::numeric)
            FILTER (WHERE aggregate_observation.exec_type IN ('PARTIAL_FILL', 'FILL'))
        )::bigint
      END
    INTO observation_count, observed_fill_quantity, recomputed_average
    FROM public.order_fill_observations aggregate_observation
    WHERE aggregate_observation.order_id = requested_order_id
      AND aggregate_observation.observed_at <= requested_reconciled_at
      AND aggregate_observation.received_at <= requested_reconciled_at;
    SELECT final_observation.average_fill_price_krw
    INTO provider_final_average
    FROM public.order_fill_observations final_observation
    WHERE final_observation.order_id = requested_order_id
      AND final_observation.exec_type IN ('PARTIAL_FILL', 'FILL')
      AND final_observation.observed_at <= requested_reconciled_at
      AND final_observation.received_at <= requested_reconciled_at
    ORDER BY
      final_observation.cumulative_quantity DESC,
      final_observation.observed_at DESC,
      final_observation.observation_id DESC
    LIMIT 1;
  END IF;

  RETURN QUERY
  SELECT
    'READY'::text,
    jsonb_build_object(
      'orderId', stored_order.order_id,
      'brokerageMode', stored_order.brokerage_mode,
      'status', current_status,
      'quantity', stored_order.quantity,
      'filledQuantity', stored_order.filled_quantity,
      'leavesQuantity', stored_order.leaves_quantity,
      'unfilledTerminatedQuantity', stored_order.unfilled_terminated_quantity,
      'fillNotionalKrw', fill_notional,
      'averageFillPriceKrw', stored_order.average_fill_price_krw,
      'reconciliationStatus', stored_order.reconciliation_status,
      'observationCount', observation_count,
      'observedFillQuantity', observed_fill_quantity,
      'recomputedAverageFillPriceKrw', recomputed_average,
      'providerFinalAverageFillPriceKrw', provider_final_average,
      'observations', observations,
      'hasMore', remaining
    )::text;
END
$$;


ALTER FUNCTION public.read_order_reconciliation_state(requested_payload jsonb, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.read_owned_foreign_news_sentiment(p_owner_user_id text, p_symbol text) RETURNS TABLE(payload_json jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_symbol !~ '^[0-9A-Z._:-]{1,20}$'
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'foreign-news owner read arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT aggregate.payload_json
  FROM public.foreign_news_sentiment_aggregates AS aggregate
  WHERE aggregate.owner_user_id = p_owner_user_id
    AND aggregate.symbol = p_symbol
  ORDER BY aggregate.as_of DESC, aggregate.logical_identity_hash DESC
  LIMIT 1;
END
$_$;


ALTER FUNCTION public.read_owned_foreign_news_sentiment(p_owner_user_id text, p_symbol text) OWNER TO flyway;


CREATE FUNCTION public.read_owned_order_fills(requested_payload jsonb, requested_capability_token text) RETURNS TABLE(operation_outcome text, page_json text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  requested_actor_user_id text;
  requested_actor_role text;
  requested_security_version bigint;
  requested_account_id text;
  requested_brokerage_mode text;
  requested_from timestamptz;
  requested_to timestamptz;
  requested_last_filled_at timestamptz;
  requested_last_order_id text;
  requested_last_exec_ref_hash text;
  stored_actor record;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  IF requested_payload IS NULL
     OR jsonb_typeof(requested_payload) <> 'object'
     OR NOT requested_payload ?& ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'accountId',
       'brokerageMode', 'fromInclusive', 'toExclusive', 'lastFilledAt',
       'lastOrderId', 'lastExecRefHash'
     ]
     OR requested_payload - ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'accountId',
       'brokerageMode', 'fromInclusive', 'toExclusive', 'lastFilledAt',
       'lastOrderId', 'lastExecRefHash'
     ] <> '{}'::jsonb THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;
  requested_actor_user_id := requested_payload ->> 'actorUserId';
  requested_actor_role := requested_payload ->> 'actorRole';
  requested_security_version := (requested_payload ->> 'securityVersion')::bigint;
  requested_account_id := requested_payload ->> 'accountId';
  requested_brokerage_mode := requested_payload ->> 'brokerageMode';
  requested_from := (requested_payload ->> 'fromInclusive')::timestamptz;
  requested_to := (requested_payload ->> 'toExclusive')::timestamptz;
  requested_last_filled_at :=
    NULLIF(requested_payload ->> 'lastFilledAt', '')::timestamptz;
  requested_last_order_id := NULLIF(requested_payload ->> 'lastOrderId', '');
  requested_last_exec_ref_hash :=
    NULLIF(requested_payload ->> 'lastExecRefHash', '');

  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id;
  IF NOT FOUND
     OR stored_actor.status <> 'ACTIVE'
     OR stored_actor.role <> requested_actor_role
     OR stored_actor.security_version <> requested_security_version THEN
    RETURN QUERY SELECT 'ACTOR_UNAUTHORIZED'::text, NULL::text;
    RETURN;
  END IF;
  IF requested_brokerage_mode NOT IN ('KIS_MOCK', 'INTERNAL_PAPER')
     OR requested_to <= requested_from
     OR requested_to - requested_from > interval '31 days'
     OR (
       (requested_last_filled_at IS NULL)::integer
       + (requested_last_order_id IS NULL)::integer
       + (requested_last_exec_ref_hash IS NULL)::integer
     ) NOT IN (0, 3) THEN
    RETURN QUERY SELECT 'VALIDATION_ERROR'::text, NULL::text;
    RETURN;
  END IF;

  IF requested_brokerage_mode = 'KIS_MOCK'
     AND NOT EXISTS (
       SELECT 1
       FROM public.orders owned
       WHERE owned.user_id = requested_actor_user_id
         AND owned.account_id = requested_account_id
         AND owned.brokerage_mode = 'KIS_MOCK'
     ) THEN
    RETURN QUERY SELECT 'ACCOUNT_NOT_FOUND'::text, NULL::text;
    RETURN;
  END IF;
  IF requested_brokerage_mode = 'INTERNAL_PAPER'
     AND NOT EXISTS (
       SELECT 1
       FROM public.paper_accounts account
       WHERE account.user_id = requested_actor_user_id
         AND account.account_id = requested_account_id
     ) THEN
    RETURN QUERY SELECT 'ACCOUNT_NOT_FOUND'::text, NULL::text;
    RETURN;
  END IF;

  RETURN QUERY
  WITH candidate AS (
    SELECT source.*
    FROM (
      SELECT
        stored.order_id,
        stored.brokerage_mode,
        stored.symbol,
        stored.side,
        observation.fill_quantity,
        observation.fill_price_krw,
        observation.fill_quantity * observation.fill_price_krw AS fill_amount_krw,
        observation.observed_at AS filled_at,
        observation.provider_exec_ref_hash AS exec_ref_hash
      FROM public.orders stored
      JOIN public.order_fill_observations observation
        ON observation.order_id = stored.order_id
      JOIN public.order_fill_application_receipts receipt
        ON receipt.observation_id = observation.observation_id
       AND receipt.outcome = 'APPLIED'
      WHERE requested_brokerage_mode = 'KIS_MOCK'
        AND stored.brokerage_mode = 'KIS_MOCK'
        AND stored.user_id = requested_actor_user_id
        AND stored.account_id = requested_account_id
        AND observation.exec_type IN ('PARTIAL_FILL', 'FILL')
        AND observation.observed_at >= requested_from
        AND observation.observed_at < requested_to
      UNION ALL
      SELECT
        stored.order_id,
        stored.brokerage_mode,
        stored.symbol,
        stored.side,
        (paper.payload_json ->> 'fillQuantity')::bigint,
        (paper.payload_json ->> 'fillPriceKrw')::bigint,
        (paper.payload_json ->> 'fillAmountKrw')::bigint,
        paper.created_at,
        encode(
          sha256(convert_to('paper-fill:' || stored.order_id, 'UTF8')),
          'hex'
        )
      FROM public.orders stored
      JOIN public.paper_order_events paper ON paper.order_id = stored.order_id
      WHERE requested_brokerage_mode = 'INTERNAL_PAPER'
        AND stored.brokerage_mode = 'INTERNAL_PAPER'
        AND stored.user_id = requested_actor_user_id
        AND stored.account_id = requested_account_id
        AND paper.created_at >= requested_from
        AND paper.created_at < requested_to
    ) source
    WHERE requested_last_filled_at IS NULL
       OR (source.filled_at, source.order_id, source.exec_ref_hash)
          < (
            requested_last_filled_at,
            requested_last_order_id,
            requested_last_exec_ref_hash
          )
    ORDER BY source.filled_at DESC, source.order_id DESC, source.exec_ref_hash DESC
    LIMIT 51
  )
  SELECT
    'READY'::text,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'orderId', candidate.order_id,
          'brokerageMode', candidate.brokerage_mode,
          'symbol', candidate.symbol,
          'side', candidate.side,
          'fillQuantity', candidate.fill_quantity,
          'fillPriceKrw', candidate.fill_price_krw,
          'fillAmountKrw', candidate.fill_amount_krw,
          'filledAt', candidate.filled_at::text,
          'execRefHash', candidate.exec_ref_hash
        )
        ORDER BY candidate.filled_at DESC, candidate.order_id DESC, candidate.exec_ref_hash DESC
      ),
      '[]'::jsonb
    )::text
  FROM candidate;
END
$$;


ALTER FUNCTION public.read_owned_order_fills(requested_payload jsonb, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.read_owned_principle_authorized(p_capability text, p_actor_user_id text, p_principle_id text) RETURNS TABLE(principle_id text, user_id text, preset_id text, title text, mode text, status text, current_version integer, created_at timestamp with time zone, updated_at timestamp with time zone, rules_json text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN RETURN; END IF;
  RETURN QUERY SELECT item.principle_id,item.user_id,item.preset_id,item.title,item.mode,item.status,
    item.current_version,item.created_at,item.updated_at,version.rules_json::text
  FROM public.principles item JOIN public.principle_versions version
    ON version.principle_id=item.principle_id AND version.version=item.current_version
  WHERE item.principle_id=p_principle_id AND item.user_id=p_actor_user_id;
END
$$;


ALTER FUNCTION public.read_owned_principle_authorized(p_capability text, p_actor_user_id text, p_principle_id text) OWNER TO flyway;


CREATE FUNCTION public.read_paper_balance_projection(requested_actor_user_id text, requested_account_id text, requested_capability_token text) RETURNS TABLE(account_id text, cash_krw bigint, total_equity_krw bigint, positions_json jsonb, as_of timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  RETURN QUERY
  SELECT
    account.account_id,
    account.cash_balance,
    account.cash_balance + COALESCE(sum(position.market_value), 0)::bigint,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'symbol', position.symbol,
          'quantity', position.quantity,
          'marketValueKrw', position.market_value,
          'averagePriceKrw', position.average_price
        )
        ORDER BY position.symbol
      ) FILTER (WHERE position.position_id IS NOT NULL),
      '[]'::jsonb
    ),
    GREATEST(account.updated_at, COALESCE(max(position.updated_at), account.updated_at))
  FROM public.paper_accounts account
  LEFT JOIN public.paper_positions position
    ON position.account_id = account.account_id
  WHERE account.account_id = requested_account_id
    AND account.user_id = requested_actor_user_id
    AND account.status = 'ACTIVE'
    AND EXISTS (
      SELECT 1
      FROM public.users actor
      WHERE actor.user_id = requested_actor_user_id
        AND actor.status = 'ACTIVE'
    )
  GROUP BY account.account_id, account.cash_balance, account.updated_at
  LIMIT 1;
END
$$;


ALTER FUNCTION public.read_paper_balance_projection(requested_actor_user_id text, requested_account_id text, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.read_paper_order_context(requested_actor_user_id text, requested_decision_id text, requested_capability_token text) RETURNS TABLE(decision_id text, evaluation_id text, portfolio_source text, outcome text, mode text, can_submit_order boolean, enforcement_action text, valid_until timestamp with time zone, snapshot_artifact_canonical_json text, portfolio_owner_scope_hash text, invalidated boolean, consumed_by_order_id text, account_id text, account_status text, quote_observation_id text, quote_price_krw bigint, quote_previous_close_krw bigint, quote_completeness text, quote_observed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  PERFORM set_config('app.actor_user_id', requested_actor_user_id, true);
  RETURN QUERY
  SELECT
    decision.decision_id,
    decision.evaluation_id,
    decision.portfolio_source,
    decision.outcome,
    decision.mode,
    decision.can_submit_order,
    decision.enforcement_action,
    decision.valid_until,
    artifact.snapshot_artifact_canonical_json,
    artifact.snapshot_artifact_canonical_json::jsonb #>> '{portfolio,ownerScopeHash}',
    EXISTS (
      SELECT 1
      FROM public.decision_invalidations invalidation
      WHERE invalidation.decision_id = decision.decision_id
    ),
    consumed.order_id,
    account.account_id,
    account.status,
    quote.observation_id,
    quote.price_krw,
    quote.previous_close_krw,
    quote.completeness,
    quote.observed_at
  FROM public.decisions decision
  JOIN public.decision_artifacts artifact
    ON artifact.decision_id = decision.decision_id
   AND artifact.evaluation_id = decision.evaluation_id
  LEFT JOIN public.paper_accounts account
    ON account.user_id = decision.user_id
   AND account.owner_scope_hash =
     artifact.snapshot_artifact_canonical_json::jsonb #>> '{portfolio,ownerScopeHash}'
  LEFT JOIN public.orders consumed
    ON consumed.decision_id = decision.decision_id
  LEFT JOIN LATERAL (
    SELECT
      stored.observation_id,
      stored.price_krw,
      stored.previous_close_krw,
      stored.completeness,
      stored.observed_at
    FROM public.market_quote_observations stored
    WHERE stored.symbol =
      artifact.snapshot_artifact_canonical_json::jsonb #>> '{orderIntent,symbol}'
      AND stored.source = 'KIS_MOCK'
    ORDER BY stored.observed_at DESC, stored.received_at DESC, stored.observation_id
    LIMIT 1
  ) quote ON true
  WHERE decision.user_id = requested_actor_user_id
    AND decision.decision_id = requested_decision_id
    AND EXISTS (
      SELECT 1
      FROM public.users actor
      WHERE actor.user_id = requested_actor_user_id
        AND actor.status = 'ACTIVE'
    )
  LIMIT 1;
END
$$;


ALTER FUNCTION public.read_paper_order_context(requested_actor_user_id text, requested_decision_id text, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.read_production_signal_v2(p_symbol text) RETURNS TABLE(producer text, source_workspace text, symbol text, session_date date, as_of timestamp with time zone, timeframe text, status text, reason text, signal text, confidence numeric, predicted_return numeric, model_version text, model_report_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
  SELECT stored.producer, stored.source_workspace, stored.symbol, stored.session_date,
    stored.as_of, stored.timeframe, stored.status, stored.reason, stored.signal,
    stored.confidence, stored.predicted_return, stored.model_version, stored.model_report_id
  FROM public.signal_v2_production_pointers pointer
  JOIN public.ingested_signals stored ON stored.logical_identity_sha256 = pointer.logical_identity_sha256
  WHERE current_user = 'flyway' AND session_user = 'decision_app'
    AND p_symbol ~ '^[0-9A-Z._:-]{1,20}$' AND stored.symbol = p_symbol
    AND stored.producer <> 'LIGHTGBM' AND stored.fixture = false
    AND stored.provenance_class = 'PRODUCTION' AND stored.artifact_verified
  UNION ALL
  SELECT 'LIGHTGBM'::text, 'decision-platform'::text, member.symbol, batch.session_date,
    CASE WHEN release.lifecycle_status = 'ACCEPTED' THEN member.as_of ELSE NULL END,
    '1d'::text,
    CASE WHEN release.lifecycle_status = 'ACCEPTED' THEN 'AVAILABLE' ELSE 'ABSTAIN' END,
    CASE WHEN release.lifecycle_status = 'SUSPENDED' THEN 'ARTIFACT_DRIFT' ELSE NULL END,
    CASE WHEN release.lifecycle_status = 'ACCEPTED' THEN member.signal ELSE NULL END,
    CASE WHEN release.lifecycle_status = 'ACCEPTED' THEN member.confidence ELSE NULL END,
    NULL::numeric,
    CASE WHEN release.lifecycle_status = 'ACCEPTED' THEN member.model_version ELSE NULL END,
    CASE WHEN release.lifecycle_status = 'ACCEPTED' THEN member.model_report_id ELSE NULL END
  FROM public.active_signal_model_release active_model
  JOIN public.signal_model_releases release USING (model_release_id)
  JOIN public.active_signal_batch active_batch ON active_batch.singleton
  JOIN public.signal_batches batch ON batch.signal_batch_id = active_batch.signal_batch_id
    AND batch.model_release_id = active_model.model_release_id
  JOIN public.signal_batch_members member ON member.signal_batch_id = batch.signal_batch_id
  WHERE current_user = 'flyway' AND session_user = 'decision_app'
    AND active_model.singleton AND member.symbol = p_symbol
  ORDER BY producer
$_$;


ALTER FUNCTION public.read_production_signal_v2(p_symbol text) OWNER TO flyway;


CREATE FUNCTION public.read_rag_activation_state() RETURNS TABLE(active_generation_id text, policy_version bigint, policy_id text, effective_profile_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_rag_admin' THEN
    RAISE EXCEPTION 'RAG activation state requires the dedicated admin role'
      USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT
    state.active_generation_id,
    state.version,
    state.policy_id,
    state.effective_profile_id
  FROM public.rag_embedding_policy_state AS state
  WHERE state.state_id = 'default';
END
$$;


ALTER FUNCTION public.read_rag_activation_state() OWNER TO flyway;


CREATE FUNCTION public.read_rag_generation_embeddings_for_verification(p_generation_id text, p_expected_corpus_hash text, p_expected_row_count integer) RETURNS TABLE(chunk_revision_id text, embedding_text text, materialization_row_hash text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  generation_row_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_generation_id !~ '^rag_gen_[0-9a-f]{32}$'
     OR p_expected_corpus_hash !~ '^[0-9a-f]{64}$'
     OR p_expected_row_count NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION 'RAG generation verification caller or argument is invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT generation.actual_chunk_count
  INTO generation_row_count
  FROM public.rag_corpus_generations AS generation
  WHERE generation.corpus_generation_id = p_generation_id
    AND generation.corpus_hash = p_expected_corpus_hash
    AND generation.embedding_profile_id = 'bge_m3_local_1024_v1'
    AND generation.status IN ('MATERIALIZED', 'EVAL_PASSED', 'ACTIVE')
    AND generation.actual_chunk_count = p_expected_row_count;
  IF NOT FOUND OR generation_row_count <> p_expected_row_count THEN
    RAISE EXCEPTION 'RAG generation verification target is not complete'
      USING ERRCODE = '23514';
  END IF;

  RETURN QUERY
  SELECT
    embedding.chunk_revision_id,
    embedding.embedding::text,
    embedding.materialization_row_hash
  FROM public.rag_chunk_embeddings AS embedding
  WHERE embedding.corpus_generation_id = p_generation_id
    AND embedding.embedding_profile_id = 'bge_m3_local_1024_v1'
    AND embedding.materialization_row_hash IS NOT NULL
  ORDER BY convert_to(embedding.chunk_revision_id, 'UTF8')
  LIMIT p_expected_row_count + 1;
END
$_$;


ALTER FUNCTION public.read_rag_generation_embeddings_for_verification(p_generation_id text, p_expected_corpus_hash text, p_expected_row_count integer) OWNER TO flyway;


CREATE FUNCTION public.read_rag_history_citations(p_owner_user_id text, p_answer_id text) RETURNS TABLE(ordinal integer, citation_id text, source_id text, source_revision_id text, chunk_revision_id text, generation_id text, title text, section_title text, canonical_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_answer_id !~ '^rag_ans_[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'RAG history citation arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  SELECT
    citation.ordinal,
    citation.citation_id,
    citation.source_id,
    citation.source_revision_id,
    citation.chunk_revision_id,
    citation.generation_id,
    citation.title,
    citation.section_title,
    citation.canonical_url
  FROM public.rag_answer_history AS history
  JOIN public.rag_answer_citations AS citation
    ON citation.answer_id = history.answer_id
  JOIN public.rag_sources AS source
    ON source.source_id = citation.source_id
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = citation.source_revision_id
   AND revision.source_id = source.source_id
   AND revision.access_level = 'PUBLIC'
   AND revision.tier = 'PROJECT'
  JOIN public.rag_source_card_verifications AS verification
    ON verification.source_revision_id = revision.source_revision_id
   AND verification.card_metadata_hash = revision.metadata_hash
   AND verification.status = 'VERIFIED'
  JOIN public.rag_embedding_policy_state AS policy
    ON policy.state_id = 'default'
   AND policy.active_generation_id = citation.generation_id
  JOIN public.rag_corpus_generations AS generation
    ON generation.corpus_generation_id = policy.active_generation_id
   AND generation.embedding_profile_id = policy.effective_profile_id
   AND generation.status = 'ACTIVE'
   AND generation.evaluation_status = 'PASSED'
  WHERE history.answer_id = p_answer_id
    AND history.owner_user_id = p_owner_user_id
    AND history.expires_at > statement_timestamp()
    AND EXISTS (
      SELECT 1
      FROM public.rag_generation_chunks AS membership
      JOIN public.rag_chunk_revisions AS chunk
        ON chunk.chunk_revision_id = membership.chunk_revision_id
       AND chunk.chunk_revision_id = citation.chunk_revision_id
       AND chunk.source_revision_id = revision.source_revision_id
       AND chunk.access_level = 'PUBLIC'
       AND chunk.tier = 'PROJECT'
      WHERE membership.corpus_generation_id = generation.corpus_generation_id
        AND membership.embedding_profile_id = generation.embedding_profile_id
        AND citation.section_title =
            chunk.heading_path[cardinality(chunk.heading_path)]
    )
  ORDER BY citation.ordinal
  LIMIT 5;
END
$_$;


ALTER FUNCTION public.read_rag_history_citations(p_owner_user_id text, p_answer_id text) OWNER TO flyway;


CREATE FUNCTION public.read_rag_history_detail(p_owner_user_id text, p_answer_id text) RETURNS TABLE(answer_id text, owner_user_id text, answer_mode text, generation_status text, citation_coverage double precision, retrieval_failure boolean, guardrail_flags text[], citation_count integer, kek_version text, wrap_nonce bytea, wrapped_dek bytea, wrap_tag bytea, question_nonce bytea, question_ciphertext bytea, question_tag bytea, answer_nonce bytea, answer_ciphertext bytea, answer_tag bytea, created_at timestamp with time zone, expires_at timestamp with time zone, helpful boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_answer_id !~ '^rag_ans_[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'RAG history detail arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  SELECT
    history.answer_id,
    history.owner_user_id,
    history.answer_mode,
    history.generation_status,
    history.citation_coverage,
    history.retrieval_failure,
    history.guardrail_flags,
    history.citation_count,
    history.kek_version,
    history.wrap_nonce,
    history.wrapped_dek,
    history.wrap_tag,
    history.question_nonce,
    history.question_ciphertext,
    history.question_tag,
    history.answer_nonce,
    history.answer_ciphertext,
    history.answer_tag,
    history.created_at,
    history.expires_at,
    feedback.helpful
  FROM public.rag_answer_history AS history
  LEFT JOIN public.rag_answer_feedback AS feedback
    ON feedback.answer_id = history.answer_id
   AND feedback.owner_user_id = p_owner_user_id
  WHERE history.answer_id = p_answer_id
    AND history.owner_user_id = p_owner_user_id
    AND history.expires_at > statement_timestamp()
  LIMIT 1;
END
$_$;


ALTER FUNCTION public.read_rag_history_detail(p_owner_user_id text, p_answer_id text) OWNER TO flyway;


CREATE FUNCTION public.read_rag_history_metadata(p_owner_user_id text, p_before_created_at timestamp with time zone, p_before_answer_id text, p_limit integer) RETURNS TABLE(answer_id text, created_at timestamp with time zone, expires_at timestamp with time zone, answer_mode text, generation_status text, helpful boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_limit NOT BETWEEN 1 AND 51
     OR (p_before_created_at IS NULL) <> (p_before_answer_id IS NULL)
     OR (
       p_before_answer_id IS NOT NULL
       AND p_before_answer_id !~ '^rag_ans_[0-9a-f]{32}$'
     ) THEN
    RAISE EXCEPTION 'RAG history metadata arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  SELECT
    history.answer_id,
    history.created_at,
    history.expires_at,
    history.answer_mode,
    history.generation_status,
    feedback.helpful
  FROM public.rag_answer_history AS history
  LEFT JOIN public.rag_answer_feedback AS feedback
    ON feedback.answer_id = history.answer_id
   AND feedback.owner_user_id = p_owner_user_id
  WHERE history.owner_user_id = p_owner_user_id
    AND history.expires_at > statement_timestamp()
    AND (
      p_before_created_at IS NULL
      OR (history.created_at, history.answer_id) <
         (p_before_created_at, p_before_answer_id)
    )
  ORDER BY history.created_at DESC, history.answer_id DESC
  LIMIT p_limit;
END
$_$;


ALTER FUNCTION public.read_rag_history_metadata(p_owner_user_id text, p_before_created_at timestamp with time zone, p_before_answer_id text, p_limit integer) OWNER TO flyway;


CREATE FUNCTION public.read_rag_source_registry(p_actor_user_id text) RETURNS TABLE(source_id text, title text, institution text, topic text, attribution text, canonical_url text, last_checked_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_actor_user_id IS NULL
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_actor_user_id
     OR NOT EXISTS (
       SELECT 1
       FROM public.users AS authenticated_user
       WHERE authenticated_user.user_id = p_actor_user_id
         AND authenticated_user.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'RAG source projection actor mismatch' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH active_sources AS (
    SELECT DISTINCT ON (source.source_id)
      source.source_id,
      revision.title,
      source.institution,
      source.topic,
      revision.attribution,
      revision.canonical_url,
      latest_check.checked_at AS last_checked_at
    FROM public.rag_embedding_policy_state AS policy_state
    JOIN public.rag_corpus_generations AS generation
      ON generation.corpus_generation_id = policy_state.active_generation_id
     AND generation.embedding_profile_id = policy_state.effective_profile_id
     AND generation.status = 'ACTIVE'
     AND generation.evaluation_status = 'PASSED'
    JOIN public.rag_generation_chunks AS membership
      ON membership.corpus_generation_id = generation.corpus_generation_id
     AND membership.embedding_profile_id = generation.embedding_profile_id
    JOIN public.rag_chunk_revisions AS chunk
      ON chunk.chunk_revision_id = membership.chunk_revision_id
     AND chunk.access_level = 'PUBLIC'
    JOIN public.rag_source_revisions AS revision
      ON revision.source_revision_id = chunk.source_revision_id
     AND revision.access_level = 'PUBLIC'
    JOIN public.rag_sources AS source
      ON source.source_id = revision.source_id
     AND source.source_type = 'PROJECT_SOURCE_CARD'
     AND source.retired_at IS NULL
    LEFT JOIN LATERAL (
      SELECT source_check.checked_at
      FROM public.rag_source_checks AS source_check
      WHERE source_check.source_revision_id = revision.source_revision_id
      ORDER BY source_check.checked_at DESC, source_check.source_check_id DESC
      LIMIT 1
    ) AS latest_check ON true
    ORDER BY source.source_id, revision.revision_seq DESC
  )
  SELECT
    active_sources.source_id,
    active_sources.title,
    active_sources.institution,
    active_sources.topic,
    active_sources.attribution,
    active_sources.canonical_url,
    active_sources.last_checked_at
  FROM active_sources
  ORDER BY active_sources.source_id
  LIMIT 30;
END
$$;


ALTER FUNCTION public.read_rag_source_registry(p_actor_user_id text) OWNER TO flyway;


CREATE FUNCTION public.read_rag_v2_corpus_status(p_owner_user_id text) RETURNS TABLE(state text, public_corpus_version text, private_overlay_state text, progress_percent integer, failure_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  public_ready boolean := false;
  public_pointer_found boolean := false;
  owner_state text := 'ABSENT';
  owner_ready boolean := true;
  public_version text := 'immutable-v2-0';
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 corpus status arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- FORCE RLS public pointer policy allows this bounded status read only through the same
  -- transaction-local marker used by immutable retrieval capability functions.
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);
  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers AS public_pointer_row
  WHERE public_pointer_row.state_id = 'default'
    AND public_pointer_row.state = 'ACTIVE';
  public_pointer_found := FOUND;
  IF FOUND THEN
    public_version := 'immutable-v2-' || public_pointer.pointer_version::text;
    -- V25 activation atomically validates exact/OA cardinality, rights, profile and evaluation
    -- before it can set the pointer ACTIVE. V29 resolver repeats the component-level check when
    -- issuing a capability; status itself only follows this immutable activation receipt.
    public_ready := true;
  END IF;

  SELECT * INTO owner_pointer
  FROM public.rag_v2_immutable_owner_bundle_pointers AS owner_pointer_row
  WHERE owner_pointer_row.owner_user_id = p_owner_user_id;
  IF FOUND THEN
    owner_state := owner_pointer.state;
    IF owner_pointer.state = 'READY' THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_bundles AS bundle
        JOIN public.rag_v2_immutable_component_generations AS owner_generation
          ON owner_generation.component_generation_id = bundle.owner_private_generation_id
         AND owner_generation.component_scope = 'OWNER_PRIVATE'
         AND owner_generation.owner_user_id = p_owner_user_id
         AND owner_generation.embedding_profile_id = bundle.embedding_profile_id
         AND owner_generation.state = 'ACTIVE'
         AND owner_generation.evaluation_status = 'PASSED'
        WHERE bundle.bundle_id = owner_pointer.active_bundle_id
          AND bundle.owner_user_id = p_owner_user_id
          AND bundle.state = 'ACTIVE'
          AND bundle.evaluation_status = 'PASSED'
          AND bundle.exact30_generation_id IS NOT DISTINCT FROM public_pointer.exact30_generation_id
          AND bundle.oa112_generation_id IS NOT DISTINCT FROM public_pointer.oa112_generation_id
          AND bundle.embedding_profile_id IS NOT DISTINCT FROM public_pointer.embedding_profile_id
      ) INTO owner_ready;
      IF NOT owner_ready THEN
        owner_state := 'FAILED';
      END IF;
    ELSIF owner_pointer.state NOT IN ('ABSENT', 'BUILDING', 'FAILED') THEN
      owner_state := 'FAILED';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    CASE
      WHEN owner_state = 'FAILED' THEN 'FAILED'
      WHEN public_ready AND owner_state IN ('ABSENT', 'READY') THEN 'FULL_READY'
      WHEN owner_state = 'BUILDING' THEN 'BUILDING'
      ELSE 'CORE_READY'
    END,
    public_version,
    owner_state,
    CASE
      WHEN public_ready AND owner_state IN ('ABSENT', 'READY') THEN 100
      WHEN owner_state = 'BUILDING' THEN 50
      ELSE 0
    END,
    CASE
      WHEN owner_state = 'FAILED' THEN 'OWNER_OVERLAY_FAILED'
      WHEN public_pointer_found AND NOT public_ready THEN 'IMMUTABLE_PUBLIC_BUNDLE_INVALID'
      ELSE NULL
    END;
END
$$;


