CREATE FUNCTION public.read_rag_v2_vertex_generation_evidence(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_citations jsonb) RETURNS TABLE(ordinal integer, citation_id text, chunk_revision_id text, canonical_content text, canonical_content_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  canonical_citations jsonb;
  claim_row public.rag_v2_retrieval_scope_claims%ROWTYPE;
  citation_item jsonb;
  candidate record;
  output_ordinal integer := 0;
  total_content_bytes integer := 0;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$'
     OR p_scope_claim_id !~ '^rvs_[0-9a-f]{32}$'
     OR jsonb_typeof(p_citations) <> 'array'
     OR jsonb_array_length(p_citations) NOT BETWEEN 1 AND 5
     OR octet_length(p_citations::text) > 16384 THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex evidence arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  canonical_citations := public.canonicalize_rag_v2_immutable_retrieval_citations(
    p_owner_user_id,
    p_session_id,
    p_scope_claim_id,
    p_citations
  );
  SELECT * INTO claim_row
  FROM public.rag_v2_retrieval_scope_claims AS scope
  WHERE scope.scope_claim_id = p_scope_claim_id
    AND scope.owner_user_id = p_owner_user_id
    AND scope.session_id = p_session_id
    AND scope.expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex evidence scope disappeared'
      USING ERRCODE = '55000';
  END IF;

  FOR citation_item IN SELECT value FROM jsonb_array_elements(canonical_citations)
  LOOP
    SELECT
      chunk.canonical_text,
      chunk.canonical_text_sha256
    INTO candidate
    FROM public.rag_v2_immutable_generation_memberships AS membership
    JOIN public.rag_v2_immutable_chunks AS chunk
      ON chunk.chunk_id = membership.chunk_id
     AND chunk.source_revision_id = membership.source_revision_id
     AND chunk.source_scope = membership.component_scope
     AND chunk.owner_partition_key = membership.owner_partition_key
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
     AND source.source_scope = membership.component_scope
     AND source.owner_partition_key = membership.owner_partition_key
    WHERE membership.component_generation_id = citation_item ->> 'generationId'
      AND membership.chunk_id = citation_item ->> 'chunkRevisionId'
      AND membership.source_revision_id = citation_item ->> 'sourceRevisionId'
      AND source.source_id = citation_item ->> 'sourceId'
      AND membership.component_generation_id = ANY(
        ARRAY[
          claim_row.exact30_generation_id,
          claim_row.oa112_generation_id,
          claim_row.owner_private_generation_id
        ]::text[]
      )
      AND source.retrieval_topics && claim_row.allowed_topics
      AND source.external_processing_eligible
      AND (
        (source.source_scope IN ('EXACT30', 'OA112') AND source.owner_user_id IS NULL)
        OR (source.source_scope = 'OWNER_PRIVATE' AND source.owner_user_id = p_owner_user_id)
      )
      AND EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_generation_embeddings AS embedding
        WHERE embedding.component_generation_id = membership.component_generation_id
          AND embedding.chunk_id = membership.chunk_id
          AND embedding.component_scope = membership.component_scope
          AND embedding.owner_partition_key = membership.owner_partition_key
          AND embedding.embedding_profile_id = CASE
            WHEN membership.component_scope = 'OWNER_PRIVATE' THEN claim_row.owner_embedding_profile_id
            ELSE claim_row.embedding_profile_id
          END
      );
    IF NOT FOUND
       OR candidate.canonical_text IS NULL
       OR candidate.canonical_text_sha256 !~ '^[0-9a-f]{64}$'
       OR octet_length(candidate.canonical_text) NOT BETWEEN 1 AND 16384 THEN
      RAISE EXCEPTION 'immutable RAG v2 Vertex evidence is not externally eligible'
        USING ERRCODE = '55000';
    END IF;

    total_content_bytes := total_content_bytes + octet_length(candidate.canonical_text);
    IF total_content_bytes > 60000 THEN
      RAISE EXCEPTION 'immutable RAG v2 Vertex evidence exceeds the bounded input cap'
        USING ERRCODE = '22023';
    END IF;
    output_ordinal := output_ordinal + 1;
    ordinal := output_ordinal;
    citation_id := citation_item ->> 'citationId';
    chunk_revision_id := citation_item ->> 'chunkRevisionId';
    canonical_content := candidate.canonical_text;
    canonical_content_sha256 := candidate.canonical_text_sha256;
    RETURN NEXT;
  END LOOP;
  IF output_ordinal NOT BETWEEN 1 AND 5 THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex evidence is empty'
      USING ERRCODE = '55000';
  END IF;
END
$_$;


ALTER FUNCTION public.read_rag_v2_vertex_generation_evidence(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_citations jsonb) OWNER TO flyway;


CREATE FUNCTION public.read_rag_v2_vertex_prepared_scope(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_allowed_topics text[]) RETURNS TABLE(scope_claim_id text, exact30_generation_id text, oa112_generation_id text, owner_private_generation_id text, embedding_profile_id text, policy_version bigint, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  claim_row public.rag_v2_retrieval_scope_claims%ROWTYPE;
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  owner_bundle public.rag_v2_immutable_bundles%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$'
     OR p_scope_claim_id !~ '^rvs_[0-9a-f]{32}$'
     OR NOT public.rag_v2_immutable_retrieval_topics_are_valid(p_allowed_topics) THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);
  SELECT * INTO claim_row
  FROM public.rag_v2_retrieval_scope_claims AS scope
  WHERE scope.scope_claim_id = p_scope_claim_id
    AND scope.owner_user_id = p_owner_user_id
    AND scope.session_id = p_session_id
    AND scope.allowed_topics = p_allowed_topics
    AND scope.expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope is absent or expired'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers AS pointer
  WHERE pointer.state_id = 'default'
    AND pointer.state = 'ACTIVE'
    AND pointer.pointer_version = claim_row.public_pointer_version
    AND pointer.exact30_generation_id = claim_row.exact30_generation_id
    AND pointer.oa112_generation_id = claim_row.oa112_generation_id
    AND pointer.embedding_profile_id = claim_row.embedding_profile_id;
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_component_generations AS exact_generation
       JOIN public.rag_v2_immutable_component_generations AS oa_generation
         ON oa_generation.component_generation_id = claim_row.oa112_generation_id
        AND oa_generation.component_scope = 'OA112'
        AND oa_generation.owner_user_id IS NULL
        AND oa_generation.embedding_profile_id = claim_row.embedding_profile_id
        AND oa_generation.state = 'ACTIVE'
        AND oa_generation.evaluation_status = 'PASSED'
       WHERE exact_generation.component_generation_id = claim_row.exact30_generation_id
         AND exact_generation.component_scope = 'EXACT30'
         AND exact_generation.owner_user_id IS NULL
         AND exact_generation.embedding_profile_id = claim_row.embedding_profile_id
         AND exact_generation.state = 'ACTIVE'
         AND exact_generation.evaluation_status = 'PASSED'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope public pointer changed'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO owner_pointer
  FROM public.rag_v2_immutable_owner_bundle_pointers AS pointer
  WHERE pointer.owner_user_id = p_owner_user_id;
  IF claim_row.owner_private_generation_id IS NULL THEN
    IF (FOUND AND (owner_pointer.state <> 'ABSENT' OR owner_pointer.bundle_version <> claim_row.owner_pointer_version))
       OR (NOT FOUND AND claim_row.owner_pointer_version <> 0) THEN
      RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope owner pointer changed'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    IF NOT FOUND
       OR owner_pointer.state <> 'READY'
       OR owner_pointer.active_bundle_id IS DISTINCT FROM claim_row.owner_bundle_id
       OR owner_pointer.bundle_version <> claim_row.owner_pointer_version THEN
      RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope owner bundle changed'
        USING ERRCODE = '55000';
    END IF;
    SELECT * INTO owner_bundle
    FROM public.rag_v2_immutable_bundles AS bundle
    WHERE bundle.bundle_id = claim_row.owner_bundle_id
      AND bundle.owner_user_id = p_owner_user_id
      AND bundle.owner_private_generation_id = claim_row.owner_private_generation_id
      AND bundle.exact30_generation_id = claim_row.exact30_generation_id
      AND bundle.oa112_generation_id = claim_row.oa112_generation_id
      AND bundle.embedding_profile_id = claim_row.embedding_profile_id
      AND bundle.state = 'ACTIVE';
    IF NOT FOUND
       OR NOT EXISTS (
         SELECT 1
         FROM public.rag_v2_immutable_component_generations AS owner_generation
         WHERE owner_generation.component_generation_id = claim_row.owner_private_generation_id
           AND owner_generation.component_scope = 'OWNER_PRIVATE'
           AND owner_generation.owner_user_id = p_owner_user_id
           AND owner_generation.embedding_profile_id = claim_row.embedding_profile_id
           AND owner_generation.state = 'ACTIVE'
           AND owner_generation.evaluation_status = 'PASSED'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope owner component changed'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    claim_row.scope_claim_id,
    claim_row.exact30_generation_id,
    claim_row.oa112_generation_id,
    claim_row.owner_private_generation_id,
    claim_row.embedding_profile_id,
    claim_row.policy_version,
    claim_row.expires_at;
END
$_$;


ALTER FUNCTION public.read_rag_v2_vertex_prepared_scope(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_allowed_topics text[]) OWNER TO flyway;


CREATE FUNCTION public.read_rag_v2_vertex_prepared_scope_v2(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_allowed_topics text[]) RETURNS TABLE(scope_claim_id text, exact30_generation_id text, oa112_generation_id text, owner_private_generation_id text, embedding_profile_id text, owner_embedding_profile_id text, policy_version bigint, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  claim_row public.rag_v2_retrieval_scope_claims%ROWTYPE;
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  owner_bundle public.rag_v2_immutable_bundles%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$'
     OR p_scope_claim_id !~ '^rvs_[0-9a-f]{32}$'
     OR NOT public.rag_v2_immutable_retrieval_topics_are_valid(p_allowed_topics) THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);
  SELECT * INTO claim_row
  FROM public.rag_v2_retrieval_scope_claims AS scope
  WHERE scope.scope_claim_id = p_scope_claim_id
    AND scope.owner_user_id = p_owner_user_id
    AND scope.session_id = p_session_id
    AND scope.allowed_topics = p_allowed_topics
    AND scope.expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope is absent or expired'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers AS pointer
  WHERE pointer.state_id = 'default'
    AND pointer.state = 'ACTIVE'
    AND pointer.pointer_version = claim_row.public_pointer_version
    AND pointer.exact30_generation_id = claim_row.exact30_generation_id
    AND pointer.oa112_generation_id = claim_row.oa112_generation_id
    AND pointer.embedding_profile_id = claim_row.embedding_profile_id;
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_component_generations AS exact_generation
       JOIN public.rag_v2_immutable_component_generations AS oa_generation
         ON oa_generation.component_generation_id = claim_row.oa112_generation_id
        AND oa_generation.component_scope = 'OA112'
        AND oa_generation.owner_user_id IS NULL
        AND oa_generation.embedding_profile_id = claim_row.embedding_profile_id
        AND oa_generation.state = 'ACTIVE'
        AND oa_generation.evaluation_status = 'PASSED'
       WHERE exact_generation.component_generation_id = claim_row.exact30_generation_id
         AND exact_generation.component_scope = 'EXACT30'
         AND exact_generation.owner_user_id IS NULL
         AND exact_generation.embedding_profile_id = claim_row.embedding_profile_id
         AND exact_generation.state = 'ACTIVE'
         AND exact_generation.evaluation_status = 'PASSED'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope public pointer changed'
      USING ERRCODE = '55000';
  END IF;

  IF NOT claim_row.owner_scope_authorized THEN
    IF claim_row.owner_private_generation_id IS NOT NULL
       OR claim_row.owner_bundle_id IS NOT NULL
       OR claim_row.owner_embedding_profile_id IS NOT NULL
       OR claim_row.owner_pointer_version <> 0 THEN
      RAISE EXCEPTION 'S4.9 MCP public prepared scope is invalid'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    SELECT * INTO owner_pointer
    FROM public.rag_v2_immutable_owner_bundle_pointers AS pointer
    WHERE pointer.owner_user_id = p_owner_user_id;
    IF claim_row.owner_private_generation_id IS NULL THEN
      IF (
        FOUND
        AND owner_pointer.bundle_version = claim_row.owner_pointer_version
        AND (
          owner_pointer.state = 'ABSENT'
          OR (
            owner_pointer.state = 'READY'
            AND EXISTS (
              SELECT 1
              FROM public.rag_v2_immutable_bundles AS empty_bundle
              JOIN public.rag_v2_immutable_component_generations AS empty_generation
                ON empty_generation.component_generation_id = empty_bundle.owner_private_generation_id
               AND empty_generation.owner_user_id = empty_bundle.owner_user_id
              WHERE empty_bundle.bundle_id = owner_pointer.active_bundle_id
                AND empty_bundle.owner_user_id = p_owner_user_id
                AND empty_bundle.state = 'ACTIVE'
                AND empty_bundle.owner_embedding_profile_id IS NULL
                AND empty_generation.actual_source_count = 0
                AND empty_generation.actual_chunk_count = 0
            )
          )
        )
      ) THEN
        NULL;
      ELSIF (FOUND OR claim_row.owner_pointer_version <> 0) THEN
        RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope owner pointer changed'
          USING ERRCODE = '55000';
      END IF;
    ELSE
      IF NOT FOUND
         OR owner_pointer.state <> 'READY'
         OR owner_pointer.active_bundle_id IS DISTINCT FROM claim_row.owner_bundle_id
         OR owner_pointer.bundle_version <> claim_row.owner_pointer_version THEN
        RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope owner bundle changed'
          USING ERRCODE = '55000';
      END IF;
      SELECT * INTO owner_bundle
      FROM public.rag_v2_immutable_bundles AS bundle
      WHERE bundle.bundle_id = claim_row.owner_bundle_id
        AND bundle.owner_user_id = p_owner_user_id
        AND bundle.owner_private_generation_id = claim_row.owner_private_generation_id
        AND bundle.exact30_generation_id = claim_row.exact30_generation_id
        AND bundle.oa112_generation_id = claim_row.oa112_generation_id
        AND bundle.embedding_profile_id = claim_row.embedding_profile_id
        AND bundle.owner_embedding_profile_id = claim_row.owner_embedding_profile_id
        AND bundle.state = 'ACTIVE';
      IF NOT FOUND
         OR NOT EXISTS (
           SELECT 1
           FROM public.rag_v2_immutable_component_generations AS owner_generation
           WHERE owner_generation.component_generation_id = claim_row.owner_private_generation_id
             AND owner_generation.component_scope = 'OWNER_PRIVATE'
             AND owner_generation.owner_user_id = p_owner_user_id
             AND owner_generation.embedding_profile_id = claim_row.owner_embedding_profile_id
             AND owner_generation.state = 'ACTIVE'
             AND owner_generation.evaluation_status = 'PASSED'
         ) THEN
        RAISE EXCEPTION 'immutable RAG v2 Vertex prepared scope owner component changed'
          USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    claim_row.scope_claim_id,
    claim_row.exact30_generation_id,
    claim_row.oa112_generation_id,
    claim_row.owner_private_generation_id,
    claim_row.embedding_profile_id,
    claim_row.owner_embedding_profile_id,
    claim_row.policy_version,
    claim_row.expires_at;
END
$_$;


ALTER FUNCTION public.read_rag_v2_vertex_prepared_scope_v2(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_allowed_topics text[]) OWNER TO flyway;


CREATE FUNCTION public.read_stream_metric_status(p_actor_user_id text, p_security_version bigint) RETURNS TABLE(last_updated_at timestamp with time zone, pipeline_health text, stale_signal_ratio numeric, allow_count bigint, warn_count bigint, hold_count bigint, block_count bigint, failed_job_count bigint, dlq_event_count bigint, decision_status text, decision_observed_at timestamp with time zone, signal_status text, signal_observed_at timestamp with time zone, failed_status text, failed_observed_at timestamp with time zone, dlq_status text, dlq_observed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  actor_role text; actor_status text; actor_security_version bigint;
BEGIN
  IF session_user <> 'decision_app' THEN
    RAISE EXCEPTION 'stream metric reader role denied' USING ERRCODE = '42501';
  END IF;
  SELECT role, users.status, security_version INTO actor_role, actor_status, actor_security_version
  FROM public.users WHERE user_id = p_actor_user_id FOR SHARE;
  IF NOT FOUND OR actor_status <> 'ACTIVE' OR actor_role <> 'ADMIN'
     OR actor_security_version <> p_security_version THEN
    RETURN;
  END IF;
  INSERT INTO public.stream_metric_admin_read_audit(actor_user_id, read_kind)
  VALUES (p_actor_user_id, 'LATEST');
  RETURN QUERY
  WITH latest AS (
    SELECT DISTINCT ON (snapshot_kind) *
    FROM public.stream_metric_snapshot
    WHERE snapshot_kind <> 'LEGACY_FULL'
    ORDER BY snapshot_kind, observed_at DESC, snapshot_id DESC
  ), values_by_kind AS (
    SELECT
      max(item.observed_at) AS updated_at,
      max(item.stale_signal_ratio) FILTER (WHERE item.snapshot_kind = 'SIGNAL_FRESHNESS') AS signal_ratio,
      max((item.decision_distribution_json ->> 'ALLOW')::bigint)
        FILTER (WHERE item.snapshot_kind = 'DECISION_DISTRIBUTION') AS allows,
      max((item.decision_distribution_json ->> 'WARN')::bigint)
        FILTER (WHERE item.snapshot_kind = 'DECISION_DISTRIBUTION') AS warns,
      max((item.decision_distribution_json ->> 'HOLD')::bigint)
        FILTER (WHERE item.snapshot_kind = 'DECISION_DISTRIBUTION') AS holds,
      max((item.decision_distribution_json ->> 'BLOCK')::bigint)
        FILTER (WHERE item.snapshot_kind = 'DECISION_DISTRIBUTION') AS blocks,
      max(item.failed_job_count) FILTER (WHERE item.snapshot_kind = 'FAILED_JOBS') AS faileds,
      max(item.dlq_event_count) FILTER (WHERE item.snapshot_kind = 'DLQ_EVENTS') AS dlqs,
      max(item.component_status) FILTER (WHERE item.snapshot_kind = 'DECISION_DISTRIBUTION') AS decision_state,
      max(item.observed_at) FILTER (WHERE item.snapshot_kind = 'DECISION_DISTRIBUTION') AS decision_at,
      max(item.component_status) FILTER (WHERE item.snapshot_kind = 'SIGNAL_FRESHNESS') AS signal_state,
      max(item.observed_at) FILTER (WHERE item.snapshot_kind = 'SIGNAL_FRESHNESS') AS signal_at,
      max(item.component_status) FILTER (WHERE item.snapshot_kind = 'FAILED_JOBS') AS failed_state,
      max(item.observed_at) FILTER (WHERE item.snapshot_kind = 'FAILED_JOBS') AS failed_at,
      max(item.component_status) FILTER (WHERE item.snapshot_kind = 'DLQ_EVENTS') AS dlq_state,
      max(item.observed_at) FILTER (WHERE item.snapshot_kind = 'DLQ_EVENTS') AS dlq_at
    FROM latest item
  )
  SELECT updated_at,
    CASE
      WHEN decision_state IS NULL OR signal_state IS NULL OR failed_state IS NULL OR dlq_state IS NULL
        OR signal_state = 'UNAVAILABLE' THEN 'UNAVAILABLE'
      WHEN coalesce(signal_ratio, 0) > 0 OR coalesce(faileds, 0) > 0 OR coalesce(dlqs, 0) > 0 THEN 'DEGRADED'
      ELSE 'OK'
    END,
    signal_ratio, coalesce(allows, 0), coalesce(warns, 0), coalesce(holds, 0), coalesce(blocks, 0),
    coalesce(faileds, 0), coalesce(dlqs, 0),
    coalesce(decision_state, 'UNAVAILABLE'), decision_at,
    coalesce(signal_state, 'UNAVAILABLE'), signal_at,
    coalesce(failed_state, 'UNAVAILABLE'), failed_at,
    coalesce(dlq_state, 'UNAVAILABLE'), dlq_at
  FROM values_by_kind;
END
$$;


ALTER FUNCTION public.read_stream_metric_status(p_actor_user_id text, p_security_version bigint) OWNER TO flyway;


CREATE FUNCTION public.read_stream_metric_status_authorized(p_capability text, p_actor_user_id text, p_security_version bigint) RETURNS TABLE(last_updated_at timestamp with time zone, pipeline_health text, stale_signal_ratio numeric, allow_count bigint, warn_count bigint, hold_count bigint, block_count bigint, failed_job_count bigint, dlq_event_count bigint, decision_status text, decision_observed_at timestamp with time zone, signal_status text, signal_observed_at timestamp with time zone, failed_status text, failed_observed_at timestamp with time zone, dlq_status text, dlq_observed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.consume_actor_request_capability(p_capability,p_actor_user_id,p_security_version,'ADMIN') THEN RETURN; END IF;
  RETURN QUERY SELECT * FROM public.read_stream_metric_status(p_actor_user_id,p_security_version);
END
$$;


ALTER FUNCTION public.read_stream_metric_status_authorized(p_capability text, p_actor_user_id text, p_security_version bigint) OWNER TO flyway;


CREATE FUNCTION public.read_user_actor(p_user_id text) RETURNS TABLE(user_id text, username text, role text, status text, security_version bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF (session_user <> 'decision_auth' AND NOT EXISTS (
       SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolsuper
     )) OR p_user_id !~ '^usr_[A-Za-z0-9_-]{4,96}$' THEN
    RAISE EXCEPTION 'actor reader denied' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT item.user_id,item.username,item.role,item.status,item.security_version
  FROM public.users item WHERE item.user_id=p_user_id;
END
$_$;


