CREATE FUNCTION public.rebuild_paper_state(requested_account_id text, requested_capability_token text) RETURNS TABLE(operation_outcome text, event_count bigint, rebuilt_cash_krw bigint, stored_cash_krw bigint, positions_match boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  stored_cash bigint;
  count_events bigint;
  final_cash bigint;
  cash_chain_matches boolean;
  position_chain_matches boolean;
  final_positions_match boolean;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  SELECT account.cash_balance
  INTO stored_cash
  FROM public.paper_accounts account
  WHERE account.account_id = requested_account_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'NOT_FOUND'::text, 0::bigint, NULL::bigint, NULL::bigint, false;
    RETURN;
  END IF;
  SELECT count(*), (array_agg(
    (event.payload_json ->> 'afterCashKrw')::bigint
    ORDER BY event.event_seq DESC
  ))[1]
  INTO count_events, final_cash
  FROM public.paper_order_events event
  WHERE event.account_id = requested_account_id;
  IF count_events = 0 THEN
    RETURN QUERY SELECT 'NO_EVENTS'::text, 0::bigint, NULL::bigint, stored_cash, false;
    RETURN;
  END IF;

  SELECT bool_and(
    previous_after IS NULL
    OR previous_after = before_cash
  )
  INTO cash_chain_matches
  FROM (
    SELECT
      (event.payload_json ->> 'beforeCashKrw')::bigint AS before_cash,
      lag((event.payload_json ->> 'afterCashKrw')::bigint)
        OVER (ORDER BY event.event_seq) AS previous_after
    FROM public.paper_order_events event
    WHERE event.account_id = requested_account_id
  ) chain;

  SELECT bool_and(
    previous_quantity IS NULL
    OR (
      previous_quantity = before_quantity
      AND previous_average = before_average
      AND previous_market_value = before_market_value
    )
  )
  INTO position_chain_matches
  FROM (
    SELECT
      (event.payload_json ->> 'beforeQuantity')::bigint AS before_quantity,
      (event.payload_json ->> 'beforeAveragePriceKrw')::bigint AS before_average,
      (event.payload_json ->> 'beforeMarketValueKrw')::bigint AS before_market_value,
      lag((event.payload_json ->> 'afterQuantity')::bigint)
        OVER (PARTITION BY event.payload_json ->> 'symbol' ORDER BY event.event_seq)
        AS previous_quantity,
      lag((event.payload_json ->> 'afterAveragePriceKrw')::bigint)
        OVER (PARTITION BY event.payload_json ->> 'symbol' ORDER BY event.event_seq)
        AS previous_average,
      lag((event.payload_json ->> 'afterMarketValueKrw')::bigint)
        OVER (PARTITION BY event.payload_json ->> 'symbol' ORDER BY event.event_seq)
        AS previous_market_value
    FROM public.paper_order_events event
    WHERE event.account_id = requested_account_id
  ) chain;

  WITH ranked AS (
    SELECT
      event.payload_json ->> 'symbol' AS symbol,
      (event.payload_json ->> 'afterQuantity')::bigint AS quantity,
      (event.payload_json ->> 'afterAveragePriceKrw')::bigint AS average_price,
      (event.payload_json ->> 'afterMarketValueKrw')::bigint AS market_value,
      row_number() OVER (
        PARTITION BY event.payload_json ->> 'symbol'
        ORDER BY event.event_seq DESC
      ) AS rank
    FROM public.paper_order_events event
    WHERE event.account_id = requested_account_id
  ),
  rebuilt AS (
    SELECT symbol, quantity, average_price, market_value
    FROM ranked
    WHERE rank = 1
  )
  SELECT
    NOT EXISTS (
      SELECT symbol, quantity, average_price, market_value
      FROM rebuilt
      EXCEPT
      SELECT position.symbol, position.quantity, position.average_price, position.market_value
      FROM public.paper_positions position
      WHERE position.account_id = requested_account_id
    )
    AND NOT EXISTS (
      SELECT position.symbol, position.quantity, position.average_price, position.market_value
      FROM public.paper_positions position
      WHERE position.account_id = requested_account_id
      EXCEPT
      SELECT symbol, quantity, average_price, market_value
      FROM rebuilt
    )
  INTO final_positions_match;

  RETURN QUERY
  SELECT
    CASE
      WHEN final_cash = stored_cash
       AND cash_chain_matches
       AND position_chain_matches
       AND final_positions_match
      THEN 'MATCHED'
      ELSE 'MISMATCH'
    END,
    count_events,
    final_cash,
    stored_cash,
    final_positions_match AND position_chain_matches;
END
$$;


ALTER FUNCTION public.rebuild_paper_state(requested_account_id text, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.recheck_rag_rpc_citations(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_policy_id text, p_policy_version bigint, p_active_generation_id text, p_effective_profile_id text, p_citations jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  citation_count integer;
  valid_citation_count integer;
BEGIN
  citation_count :=
    CASE
      WHEN jsonb_typeof(p_citations) = 'array' THEN jsonb_array_length(p_citations)
      ELSE -1
    END;
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_session_id !~ '^[A-Za-z0-9._:-]{16,128}$'
     OR p_scope_claim_id !~ '^rag_scope_[0-9a-f]{32}$'
     OR p_active_generation_id !~ '^rag_gen_[0-9a-f]{32}$'
     OR p_policy_version < 1
     OR citation_count NOT BETWEEN 0 AND 5
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_retrieval_scope_claims AS claim
       JOIN public.rag_embedding_policy_state AS state
         ON state.state_id = 'default'
        AND state.policy_id = p_policy_id
        AND state.version = p_policy_version
        AND state.active_generation_id = p_active_generation_id
        AND state.effective_profile_id = p_effective_profile_id
       JOIN public.rag_corpus_generations AS generation
         ON generation.corpus_generation_id = state.active_generation_id
        AND generation.embedding_profile_id = state.effective_profile_id
        AND generation.status = 'ACTIVE'
        AND generation.evaluation_status = 'PASSED'
       WHERE claim.scope_claim_id = p_scope_claim_id
         AND claim.owner_user_id = p_owner_user_id
         AND claim.session_id = p_session_id
         AND claim.active_generation_id = p_active_generation_id
         AND claim.effective_profile_id = p_effective_profile_id
         AND claim.policy_version = p_policy_version
         AND claim.expires_at > statement_timestamp()
     ) THEN
    RAISE EXCEPTION 'RAG RPC scope recheck failed'
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::integer
  INTO valid_citation_count
  FROM jsonb_array_elements(p_citations) AS item(value)
  JOIN public.rag_sources AS source
    ON source.source_id = item.value ->> 'sourceId'
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = item.value ->> 'sourceRevisionId'
   AND revision.source_id = source.source_id
   AND revision.access_level = 'PUBLIC'
   AND revision.tier = 'PROJECT'
  JOIN public.rag_source_card_verifications AS verification
    ON verification.source_revision_id = revision.source_revision_id
   AND verification.card_metadata_hash = revision.metadata_hash
   AND verification.status = 'VERIFIED'
  JOIN public.rag_chunk_revisions AS chunk
    ON chunk.chunk_revision_id = item.value ->> 'chunkRevisionId'
   AND chunk.source_revision_id = revision.source_revision_id
   AND chunk.access_level = 'PUBLIC'
   AND chunk.tier = 'PROJECT'
  JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = p_active_generation_id
   AND membership.embedding_profile_id = p_effective_profile_id
   AND membership.chunk_revision_id = chunk.chunk_revision_id
  JOIN public.rag_retrieval_scope_claims AS claim
    ON claim.scope_claim_id = p_scope_claim_id
   AND chunk.topic = ANY(claim.allowed_topics)
  WHERE jsonb_typeof(item.value) = 'object'
    AND (SELECT count(*) FROM jsonb_object_keys(item.value)) = 9
    AND item.value ?& ARRAY[
      'ordinal', 'citationId', 'sourceId', 'sourceRevisionId', 'chunkRevisionId',
      'generationId', 'title', 'sectionTitle', 'canonicalUrl'
    ]
    AND (item.value ->> 'ordinal')::integer BETWEEN 1 AND citation_count
    AND item.value ->> 'citationId' = 'cit_' || (item.value ->> 'ordinal')
    AND item.value ->> 'generationId' = p_active_generation_id
    AND item.value ->> 'title' = revision.title
    AND item.value ->> 'sectionTitle' = chunk.heading_path[cardinality(chunk.heading_path)]
    AND item.value ->> 'canonicalUrl' = revision.canonical_url;

  IF valid_citation_count <> citation_count THEN
    RAISE EXCEPTION 'RAG RPC citation access recheck failed'
      USING ERRCODE = '42501';
  END IF;
END
$_$;


ALTER FUNCTION public.recheck_rag_rpc_citations(p_owner_user_id text, p_session_id text, p_scope_claim_id text, p_policy_id text, p_policy_version bigint, p_active_generation_id text, p_effective_profile_id text, p_citations jsonb) OWNER TO flyway;


CREATE FUNCTION public.record_kafka_poison(p_event_id text, p_event_type text, p_payload_hash text, p_source_topic text, p_source_partition integer, p_source_offset bigint, p_attempt integer, p_failure_code text, p_partition_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
#variable_conflict use_column
DECLARE existing public.kafka_poison_receipt%ROWTYPE; dlq_event_id text;
BEGIN
  IF session_user <> 'decision_worker' THEN RAISE EXCEPTION 'Kafka poison role denied' USING ERRCODE='42501'; END IF;
  IF p_event_id !~ '^evt_[A-Za-z0-9_-]{8,96}$' OR p_payload_hash !~ '^sha256:[0-9a-f]{64}$'
     OR p_source_topic<>p_event_type OR p_source_partition NOT BETWEEN 0 AND 1023 OR p_source_offset<0
     OR p_attempt NOT BETWEEN 1 AND 3 OR p_failure_code !~ '^[A-Z][A-Z0-9_]{2,63}$'
     OR p_partition_key !~ '^hmac-sha256:[0-9a-f]{64}$'
     OR NOT EXISTS (SELECT 1 FROM public.async_event_registry registry
       WHERE registry.event_type=p_event_type AND registry.topic_name=p_source_topic AND registry.enabled) THEN
    RAISE EXCEPTION 'invalid Kafka poison record' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('s7-kafka-poison-admission',0));
  SELECT * INTO existing FROM public.kafka_poison_receipt receipt
  WHERE receipt.source_topic=p_source_topic AND receipt.source_partition=p_source_partition
    AND receipt.source_offset=p_source_offset FOR UPDATE;
  IF FOUND THEN
    IF existing.event_id=p_event_id AND existing.payload_hash=p_payload_hash
       AND existing.failure_code=p_failure_code THEN RETURN false; END IF;
    RAISE EXCEPTION 'Kafka poison identity conflict' USING ERRCODE='23505';
  END IF;
  IF (SELECT count(*) FROM public.kafka_poison_receipt
      WHERE recorded_at>=statement_timestamp()-interval '1 hour')>=1000
     OR (SELECT count(*) FROM public.kafka_poison_receipt
      WHERE source_topic=p_source_topic AND source_partition=p_source_partition
        AND recorded_at>=statement_timestamp()-interval '1 hour')>=100
     OR (SELECT count(*) FROM public.event_outbox WHERE status='DLQ_REQUESTED')>=1000 THEN
    RAISE EXCEPTION 'Kafka poison admission exhausted' USING ERRCODE='54000';
  END IF;
  INSERT INTO public.kafka_poison_receipt(source_topic,source_partition,source_offset,event_id,payload_hash,failure_code)
  VALUES (p_source_topic,p_source_partition,p_source_offset,p_event_id,p_payload_hash,p_failure_code);
  dlq_event_id:='evt_dlq_'||substr(encode(public.digest(
    p_source_topic||'|'||p_source_partition::text||'|'||p_source_offset::text,'sha256'),'hex'),1,32);
  INSERT INTO public.event_outbox(event_id,event_type,aggregate_type,aggregate_id,partition_key,
    payload_json,schema_version,status,failure_code,error_class,last_error)
  VALUES (dlq_event_id,p_event_type,'ASYNC_DLQ',p_event_id,p_partition_key,
    jsonb_build_object('eventId',p_event_id,'eventType',p_event_type,'payloadHash',p_payload_hash,
      'failureCode',p_failure_code,'sourceTopic',p_source_topic,'attempt',p_attempt),
    '1.0.0','DLQ_REQUESTED',p_failure_code,'CONTRACT_VIOLATION',p_failure_code);
  RETURN true;
END
$_$;


ALTER FUNCTION public.record_kafka_poison(p_event_id text, p_event_type text, p_payload_hash text, p_source_topic text, p_source_partition integer, p_source_offset bigint, p_attempt integer, p_failure_code text, p_partition_key text) OWNER TO flyway;


CREATE FUNCTION public.record_mock_order_provider_outcome(requested_payload jsonb, requested_capability_token text) RETURNS TABLE(operation_outcome text, order_id text, account_id text, brokerage_mode text, status text, submitted_at timestamp with time zone, decision_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  requested_actor_user_id text;
  requested_actor_role text;
  requested_security_version bigint;
  requested_request_id text;
  requested_order_id text;
  requested_status text;
  requested_provider_ref_hash text;
  requested_tr_id text;
  requested_received_at timestamptz;
  requested_order_event_id text;
  stored_actor record;
  stored_order record;
  current_status text;
  expected_tr_id text;
  next_event_seq integer;
  next_event_type text;
  event_payload jsonb;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  IF requested_payload IS NULL
     OR jsonb_typeof(requested_payload) <> 'object'
     OR NOT requested_payload ?& ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'requestId',
       'orderId', 'status', 'providerOrderRefHash', 'trId',
       'receivedAt', 'orderEventId'
     ]
     OR requested_payload - ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'requestId',
       'orderId', 'status', 'providerOrderRefHash', 'trId',
       'receivedAt', 'orderEventId'
     ] <> '{}'::jsonb THEN
    RETURN QUERY
    SELECT 'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;

  IF jsonb_typeof(requested_payload -> 'actorUserId') <> 'string'
     OR jsonb_typeof(requested_payload -> 'actorRole') <> 'string'
     OR jsonb_typeof(requested_payload -> 'securityVersion') <> 'number'
     OR (requested_payload ->> 'securityVersion') !~ '^[0-9]{1,18}$'
     OR jsonb_typeof(requested_payload -> 'requestId') <> 'string'
     OR jsonb_typeof(requested_payload -> 'orderId') <> 'string'
     OR jsonb_typeof(requested_payload -> 'status') <> 'string'
     OR jsonb_typeof(requested_payload -> 'providerOrderRefHash')
       NOT IN ('string', 'null')
     OR jsonb_typeof(requested_payload -> 'trId') NOT IN ('string', 'null')
     OR jsonb_typeof(requested_payload -> 'receivedAt') <> 'string'
     OR jsonb_typeof(requested_payload -> 'orderEventId') <> 'string' THEN
    RETURN QUERY
    SELECT 'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;

  BEGIN
    requested_actor_user_id := requested_payload ->> 'actorUserId';
    requested_actor_role := requested_payload ->> 'actorRole';
    requested_security_version := (requested_payload ->> 'securityVersion')::bigint;
    requested_request_id := requested_payload ->> 'requestId';
    requested_order_id := requested_payload ->> 'orderId';
    requested_status := requested_payload ->> 'status';
    requested_provider_ref_hash := requested_payload ->> 'providerOrderRefHash';
    requested_tr_id := requested_payload ->> 'trId';
    requested_received_at := (requested_payload ->> 'receivedAt')::timestamptz;
    requested_order_event_id := requested_payload ->> 'orderEventId';
  EXCEPTION
    WHEN invalid_text_representation
      OR invalid_datetime_format
      OR datetime_field_overflow
      OR numeric_value_out_of_range THEN
      RETURN QUERY
      SELECT 'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
             NULL::text, NULL::timestamptz, NULL::text;
      RETURN;
  END;

  IF requested_actor_user_id !~ '^[A-Za-z0-9._:-]{1,128}$'
     OR requested_actor_role NOT IN ('USER', 'ADMIN')
     OR requested_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$'
     OR requested_order_id !~ '^ord_mock_[0-9a-f]{32}$'
     OR requested_order_event_id !~ '^oev_[0-9a-f]{32}$'
     OR requested_status NOT IN (
       'ACCEPTED', 'REJECTED', 'PENDING_RECONCILIATION', 'CANCELLED'
     ) THEN
    RETURN QUERY
    SELECT 'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;

  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id
  FOR SHARE;
  IF NOT FOUND
     OR stored_actor.status <> 'ACTIVE'
     OR stored_actor.role <> requested_actor_role
     OR stored_actor.security_version <> requested_security_version THEN
    RETURN QUERY
    SELECT 'ACTOR_UNAUTHORIZED'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('mock-order:provider-outcome:' || requested_order_id, 3301)
  );
  SELECT
    stored.order_id,
    stored.account_id,
    stored.brokerage_mode,
    stored.status,
    stored.submitted_at,
    stored.decision_id,
    stored.side
  INTO stored_order
  FROM public.orders stored
  WHERE stored.order_id = requested_order_id
    AND stored.user_id = requested_actor_user_id
    AND stored.brokerage_mode = 'KIS_MOCK'
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY
    SELECT 'ORDER_NOT_FOUND'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;

  SELECT event.event_status
  INTO current_status
  FROM public.order_events event
  WHERE event.order_id = requested_order_id
    AND event.event_status IS NOT NULL
  ORDER BY event.event_seq DESC
  LIMIT 1;
  current_status := COALESCE(current_status, stored_order.status);
  IF NOT (
    (current_status = 'SUBMITTED' AND requested_status IN (
      'ACCEPTED', 'REJECTED', 'PENDING_RECONCILIATION'
    ))
    OR (current_status = 'CANCEL_REQUESTED' AND requested_status = 'CANCELLED')
  ) THEN
    RETURN QUERY
    SELECT 'ORDER_CONFLICT'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;

  expected_tr_id :=
    CASE stored_order.side
      WHEN 'BUY' THEN 'VTTC0012U'
      WHEN 'SELL' THEN 'VTTC0011U'
      ELSE NULL
    END;
  IF requested_status = 'ACCEPTED' THEN
    IF requested_provider_ref_hash IS NULL
       OR requested_provider_ref_hash !~ '^[0-9a-f]{64}$'
       OR requested_tr_id IS DISTINCT FROM expected_tr_id THEN
      RETURN QUERY
      SELECT 'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
             NULL::text, NULL::timestamptz, NULL::text;
      RETURN;
    END IF;
  ELSIF requested_provider_ref_hash IS NOT NULL OR requested_tr_id IS NOT NULL THEN
    RETURN QUERY
    SELECT 'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;
  IF requested_received_at < stored_order.submitted_at
     OR requested_received_at > pg_catalog.clock_timestamp() + interval '5 minutes' THEN
    RETURN QUERY
    SELECT 'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;

  next_event_type :=
    CASE requested_status
      WHEN 'ACCEPTED' THEN 'MOCK_ORDER_ACCEPTED'
      WHEN 'REJECTED' THEN 'MOCK_ORDER_REJECTED'
      WHEN 'PENDING_RECONCILIATION' THEN 'MOCK_ORDER_PROVIDER_PENDING'
      WHEN 'CANCELLED' THEN 'MOCK_ORDER_CANCELLED'
    END;
  event_payload :=
    CASE requested_status
      WHEN 'ACCEPTED' THEN
        jsonb_build_object(
          'orderId', requested_order_id,
          'brokerageMode', 'KIS_MOCK',
          'status', requested_status,
          'providerOrderRefHash', requested_provider_ref_hash,
          'trId', requested_tr_id,
          'receivedAt', requested_received_at::text
        )
      ELSE
        jsonb_build_object(
          'orderId', requested_order_id,
          'brokerageMode', 'KIS_MOCK',
          'status', requested_status,
          'receivedAt', requested_received_at::text
        )
    END;

  SELECT COALESCE(max(event.event_seq), 0) + 1
  INTO next_event_seq
  FROM public.order_events event
  WHERE event.order_id = requested_order_id;
  INSERT INTO public.order_events (
    order_event_id, order_id, event_type, event_status, payload_json,
    created_at, event_seq
  )
  VALUES (
    requested_order_event_id, requested_order_id, next_event_type,
    requested_status, event_payload, requested_received_at, next_event_seq
  );

  UPDATE public.orders stored
  SET status = requested_status,
      provider_order_ref_hash =
        CASE
          WHEN requested_status = 'ACCEPTED' THEN requested_provider_ref_hash
          ELSE stored.provider_order_ref_hash
        END,
      provider_tr_id =
        CASE
          WHEN requested_status = 'ACCEPTED' THEN requested_tr_id
          ELSE stored.provider_tr_id
        END,
      provider_received_at =
        CASE
          WHEN requested_status = 'ACCEPTED' THEN requested_received_at
          ELSE stored.provider_received_at
        END,
      result_canonical_json =
        jsonb_set(
          stored.result_canonical_json::jsonb,
          '{status}',
          to_jsonb(requested_status)
        )::text,
      updated_at = GREATEST(stored.updated_at, requested_received_at)
  WHERE stored.order_id = requested_order_id;

  RETURN QUERY
  SELECT
    'APPLIED'::text,
    stored_order.order_id,
    stored_order.account_id,
    stored_order.brokerage_mode,
    requested_status,
    stored_order.submitted_at,
    stored_order.decision_id;
END
$_$;


ALTER FUNCTION public.record_mock_order_provider_outcome(requested_payload jsonb, requested_capability_token text) OWNER TO flyway;


CREATE FUNCTION public.record_rag_consent_event(p_owner_user_id text, p_consent_event_id text, p_action text, p_policy_version text) RETURNS TABLE(consent_event_id text, consent_type text, action text, policy_version text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_consent_event_id !~ '^cns_[0-9a-f]{32}$'
     OR p_action NOT IN ('GRANT', 'REVOKE')
     OR p_policy_version <> 'EXTERNAL_AI_RAG_V1'
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'RAG consent arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- consent event와 provider-attempt claim은 owner별 transaction lock을 공유해 revoke ordering을 고정한다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-consent-v1|' || p_owner_user_id, 0)
  );
  RETURN QUERY
  INSERT INTO public.rag_consent_events (
    consent_event_id,
    owner_user_id,
    consent_type,
    action,
    policy_version,
    created_at
  )
  VALUES (
    p_consent_event_id,
    p_owner_user_id,
    'EXTERNAL_AI_RAG_V1',
    p_action,
    p_policy_version,
    clock_timestamp()
  )
  RETURNING
    rag_consent_events.consent_event_id,
    rag_consent_events.consent_type,
    rag_consent_events.action,
    rag_consent_events.policy_version,
    rag_consent_events.created_at;
END
$_$;


ALTER FUNCTION public.record_rag_consent_event(p_owner_user_id text, p_consent_event_id text, p_action text, p_policy_version text) OWNER TO flyway;


CREATE FUNCTION public.record_rag_v2_bge_public_execution_supersession(p_exact30_component_generation_id text, p_oa112_component_generation_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_component_generations
       WHERE component_generation_id = p_exact30_component_generation_id
         AND component_scope = 'EXACT30'
         AND embedding_profile_id = 'bge_m3_local_1024_v1'
         AND state <> 'ACTIVE'
     )
     OR NOT EXISTS (
       SELECT 1 FROM public.rag_v2_immutable_component_generations
       WHERE component_generation_id = p_oa112_component_generation_id
         AND component_scope = 'OA112'
         AND embedding_profile_id = 'bge_m3_local_1024_v1'
         AND state <> 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'BGE public execution supersession arguments are invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.rag_v2_immutable_bge_public_execution_supersessions (
    marker, exact30_component_generation_id, oa112_component_generation_id
  ) VALUES (
    'TERMINALLY_SUPERSEDED_NO_FURTHER_BGE_RUN',
    p_exact30_component_generation_id,
    p_oa112_component_generation_id
  ) ON CONFLICT (marker) DO NOTHING;
  IF NOT EXISTS (
    SELECT 1 FROM public.rag_v2_immutable_bge_public_execution_supersessions
    WHERE marker = 'TERMINALLY_SUPERSEDED_NO_FURTHER_BGE_RUN'
      AND exact30_component_generation_id = p_exact30_component_generation_id
      AND oa112_component_generation_id = p_oa112_component_generation_id
  ) THEN
    RAISE EXCEPTION 'BGE public execution supersession conflicts' USING ERRCODE = '23505';
  END IF;
END
$$;


ALTER FUNCTION public.record_rag_v2_bge_public_execution_supersession(p_exact30_component_generation_id text, p_oa112_component_generation_id text) OWNER TO flyway;


CREATE FUNCTION public.record_rag_v2_immutable_consent(p_owner_user_id text, p_consent_event_id text, p_action text, p_disclosure_digest text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  recorded_at timestamptz;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_consent_event_id !~ '^cns_v2_[0-9a-f]{32}$'
     OR p_action NOT IN ('GRANT', 'REVOKE')
     OR p_disclosure_digest !~ '^[0-9a-f]{64}$'
     OR NOT EXISTS (
       SELECT 1
       FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 consent arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-consent|' || p_owner_user_id, 0)
  );
  recorded_at := clock_timestamp();
  INSERT INTO public.rag_v2_immutable_consent_events (
    consent_event_id,
    owner_user_id,
    action,
    policy_version,
    disclosure_digest,
    created_at
  )
  VALUES (
    p_consent_event_id,
    p_owner_user_id,
    p_action,
    'EXTERNAL_AI_RAG_V2',
    p_disclosure_digest,
    recorded_at
  );
  RETURN recorded_at;
END;
$_$;


ALTER FUNCTION public.record_rag_v2_immutable_consent(p_owner_user_id text, p_consent_event_id text, p_action text, p_disclosure_digest text) OWNER TO flyway;


CREATE FUNCTION public.record_rag_v2_immutable_consent_v2(p_owner_user_id text, p_internal_consent_event_id text, p_public_consent_event_id text, p_action text, p_disclosure_digest text, p_policy_digest text, p_processor_set_digest text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  recorded_at timestamptz;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_internal_consent_event_id !~ '^cns_v2_[0-9a-f]{32}$'
     OR p_public_consent_event_id !~ '^rce_[A-Za-z0-9_-]{12,96}$'
     OR p_action NOT IN ('GRANT', 'REVOKE')
     OR p_disclosure_digest !~ '^[0-9a-f]{64}$'
     OR p_policy_digest !~ '^[0-9a-f]{64}$'
     OR p_processor_set_digest !~ '^[0-9a-f]{64}$'
     OR NOT EXISTS (
       SELECT 1
       FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id
         AND actor.status = 'ACTIVE'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 consent control-plane arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-consent|' || p_owner_user_id, 0)
  );
  recorded_at := clock_timestamp();
  INSERT INTO public.rag_v2_immutable_consent_events (
    consent_event_id,
    owner_user_id,
    action,
    policy_version,
    disclosure_digest,
    public_consent_event_id,
    policy_digest,
    processor_set_digest,
    created_at
  )
  VALUES (
    p_internal_consent_event_id,
    p_owner_user_id,
    p_action,
    'EXTERNAL_AI_RAG_V2',
    p_disclosure_digest,
    p_public_consent_event_id,
    p_policy_digest,
    p_processor_set_digest,
    recorded_at
  );
  RETURN recorded_at;
END;
$_$;


ALTER FUNCTION public.record_rag_v2_immutable_consent_v2(p_owner_user_id text, p_internal_consent_event_id text, p_public_consent_event_id text, p_action text, p_disclosure_digest text, p_policy_digest text, p_processor_set_digest text) OWNER TO flyway;


CREATE FUNCTION public.record_s4_9_grounding_provenance(p_owner_user_id text, p_request_id text, p_sources jsonb, p_supports jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  item jsonb;
  source_count integer := 0;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_request_id !~ '^req_[A-Za-z0-9_-]{12,96}$'
     OR jsonb_typeof(p_sources) <> 'array' OR jsonb_array_length(p_sources) NOT BETWEEN 1 AND 5
     OR jsonb_typeof(p_supports) <> 'array' OR jsonb_array_length(p_supports) NOT BETWEEN 1 AND 64
     OR octet_length(p_sources::text) > 32768 OR octet_length(p_supports::text) > 65536 THEN
    RAISE EXCEPTION 'S4.9 grounding provenance arguments are invalid' USING ERRCODE = '22023';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_sources)
  LOOP
    IF jsonb_typeof(item) <> 'object'
       OR NOT (item ?& ARRAY['sourceNodeId','resultId','citationId','title','canonicalUrl','domain','chunkIndex'])
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(item) AS key_name
         WHERE key_name NOT IN ('sourceNodeId','resultId','citationId','title','canonicalUrl','domain','chunkIndex')
       )
       OR item ->> 'sourceNodeId' !~ '^s49_src_[0-9a-f]{32}$'
       OR item ->> 'resultId' !~ '^google_[1-9][0-9]{0,2}$'
       OR item ->> 'citationId' !~ '^cit_[1-5]$'
       OR jsonb_typeof(item -> 'chunkIndex') <> 'number'
       OR (item ->> 'chunkIndex')::integer NOT BETWEEN 0 AND 127
       OR char_length(item ->> 'title') NOT BETWEEN 1 AND 500
       OR item ->> 'canonicalUrl' !~ '^https://'
       OR octet_length(item ->> 'canonicalUrl') NOT BETWEEN 9 AND 2048
       OR char_length(item ->> 'domain') NOT BETWEEN 1 AND 253 THEN
      RAISE EXCEPTION 'S4.9 grounding source is invalid' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.s4_9_grounding_source_nodes(
      source_node_id, owner_user_id, request_id, result_id, citation_id, source_type,
      title, canonical_url, domain, chunk_index
    ) VALUES (
      item ->> 'sourceNodeId', p_owner_user_id, p_request_id, item ->> 'resultId',
      item ->> 'citationId', 'GOOGLE_GROUNDING', item ->> 'title', item ->> 'canonicalUrl',
      item ->> 'domain', (item ->> 'chunkIndex')::integer
    );
    source_count := source_count + 1;
  END LOOP;

  FOR item IN SELECT value FROM jsonb_array_elements(p_supports)
  LOOP
    IF jsonb_typeof(item) <> 'object'
       OR NOT (item ?& ARRAY['supportId','segmentSha256','startIndex','endIndex','chunkIndices'])
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(item) AS key_name
         WHERE key_name NOT IN ('supportId','segmentSha256','startIndex','endIndex','chunkIndices')
       )
       OR item ->> 'supportId' !~ '^s49_sup_[0-9a-f]{32}$'
       OR item ->> 'segmentSha256' !~ '^[0-9a-f]{64}$'
       OR jsonb_typeof(item -> 'startIndex') <> 'number'
       OR jsonb_typeof(item -> 'endIndex') <> 'number'
       OR (item ->> 'startIndex')::integer < 0
       OR (item ->> 'endIndex')::integer <= (item ->> 'startIndex')::integer
       OR jsonb_typeof(item -> 'chunkIndices') <> 'array'
       OR jsonb_array_length(item -> 'chunkIndices') NOT BETWEEN 1 AND 5
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(item -> 'chunkIndices') AS chunk(value)
         WHERE jsonb_typeof(chunk.value) <> 'number' OR (chunk.value #>> '{}')::integer NOT BETWEEN 0 AND 127
       ) THEN
      RAISE EXCEPTION 'S4.9 grounding support is invalid' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.s4_9_grounding_support_segments(
      support_id, owner_user_id, request_id, segment_sha256, start_index, end_index, chunk_indices
    ) VALUES (
      item ->> 'supportId', p_owner_user_id, p_request_id, item ->> 'segmentSha256',
      (item ->> 'startIndex')::integer, (item ->> 'endIndex')::integer,
      ARRAY(SELECT (value #>> '{}')::integer FROM jsonb_array_elements(item -> 'chunkIndices'))
    );
    INSERT INTO public.s4_9_grounding_support_edges(support_id, source_node_id, owner_user_id, request_id)
    SELECT item ->> 'supportId', source.source_node_id, p_owner_user_id, p_request_id
    FROM public.s4_9_grounding_source_nodes AS source
    WHERE source.owner_user_id = p_owner_user_id AND source.request_id = p_request_id
      AND source.chunk_index = ANY(
        ARRAY(SELECT (value #>> '{}')::integer FROM jsonb_array_elements(item -> 'chunkIndices'))
      );
    IF NOT FOUND THEN
      RAISE EXCEPTION 'S4.9 grounding support has no source edge' USING ERRCODE = '22023';
    END IF;
  END LOOP;
  IF source_count <> jsonb_array_length(p_sources) THEN
    RAISE EXCEPTION 'S4.9 grounding source count changed' USING ERRCODE = '55000';
  END IF;
END
$_$;


ALTER FUNCTION public.record_s4_9_grounding_provenance(p_owner_user_id text, p_request_id text, p_sources jsonb, p_supports jsonb) OWNER TO flyway;


CREATE FUNCTION public.record_s4_9_read_provenance(p_owner_user_id text, p_request_id text, p_source_node_id text, p_result_id text, p_citation_id text, p_source_type text, p_title text, p_canonical_url text, p_domain text, p_content_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  support_id text := 's49_sup_' || substring(p_source_node_id from 9 for 32);
  chunk_index integer := substring(p_citation_id from 5)::integer - 1;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_request_id !~ '^req_[A-Za-z0-9_-]{12,96}$'
     OR p_source_node_id !~ '^s49_src_[0-9a-f]{32}$'
     OR p_result_id !~ '^[a-z][A-Za-z0-9_-]{2,95}$'
     OR p_citation_id !~ '^cit_[1-5]$'
     OR p_source_type NOT IN ('SEARXNG_RESULT','USER_ROOT','DISCOVERED_LINK')
     OR char_length(p_title) NOT BETWEEN 1 AND 500
     OR p_canonical_url !~ '^https://' OR octet_length(p_canonical_url) NOT BETWEEN 9 AND 2048
     OR char_length(p_domain) NOT BETWEEN 1 AND 253
     OR p_content_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'S4.9 read provenance arguments are invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.s4_9_grounding_source_nodes(
    source_node_id,owner_user_id,request_id,result_id,citation_id,source_type,title,
    canonical_url,domain,chunk_index,content_sha256
  ) VALUES (
    p_source_node_id,p_owner_user_id,p_request_id,p_result_id,p_citation_id,p_source_type,p_title,
    p_canonical_url,p_domain,chunk_index,p_content_sha256
  );
  INSERT INTO public.s4_9_grounding_support_segments(
    support_id,owner_user_id,request_id,segment_sha256,start_index,end_index,chunk_indices
  ) VALUES (support_id,p_owner_user_id,p_request_id,p_content_sha256,0,64,ARRAY[chunk_index]);
  INSERT INTO public.s4_9_grounding_support_edges(support_id,source_node_id,owner_user_id,request_id)
  VALUES (support_id,p_source_node_id,p_owner_user_id,p_request_id);
END
$_$;


ALTER FUNCTION public.record_s4_9_read_provenance(p_owner_user_id text, p_request_id text, p_source_node_id text, p_result_id text, p_citation_id text, p_source_type text, p_title text, p_canonical_url text, p_domain text, p_content_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.record_s4_9_search_attempt(p_search_attempt_id text, p_owner_user_id text, p_request_id text, p_backend text, p_outcome text, p_result_count integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_search_attempt_id !~ '^s49_sra_[0-9a-f]{32}$'
     OR p_request_id !~ '^req_[A-Za-z0-9_-]{12,96}$'
     OR p_backend NOT IN ('VERTEX_GOOGLE','SEARXNG')
     OR p_outcome NOT IN ('COMMITTED','NO_RESULTS','SEARCH_UNAVAILABLE','UNKNOWN_BILLING')
     OR p_result_count NOT BETWEEN 0 AND 128 THEN
    RAISE EXCEPTION 'S4.9 search attempt arguments are invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.s4_9_search_attempts(
    search_attempt_id,owner_user_id,request_id,backend,outcome,result_count
  ) VALUES (p_search_attempt_id,p_owner_user_id,p_request_id,p_backend,p_outcome,p_result_count);
END
$_$;


ALTER FUNCTION public.record_s4_9_search_attempt(p_search_attempt_id text, p_owner_user_id text, p_request_id text, p_backend text, p_outcome text, p_result_count integer) OWNER TO flyway;


CREATE FUNCTION public.record_s4_9_strong_llm_usage(p_usage_event_id text, p_owner_user_id text, p_request_id text, p_provider text, p_model_id text, p_answer_basis text, p_outcome text, p_tool_round_count integer, p_search_call_count integer, p_read_call_count integer, p_prompt_token_count integer, p_output_token_count integer, p_evidence_set_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR p_usage_event_id !~ '^s49_llu_[0-9a-f]{32}$'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_request_id !~ '^req_[A-Za-z0-9_-]{12,96}$'
     OR p_provider <> 'VERTEX_AI'
     OR p_model_id !~ '^[a-z][a-z0-9.-]{2,127}$'
     OR p_outcome NOT IN ('COMMITTED','REJECTED','UNKNOWN_BILLING')
     OR p_tool_round_count NOT BETWEEN 0 AND 3
     OR p_search_call_count NOT BETWEEN 0 AND 3
     OR p_read_call_count NOT BETWEEN 0 AND 8
     OR p_evidence_set_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT EXISTS (
       SELECT 1 FROM public.users AS actor
       WHERE actor.user_id = p_owner_user_id AND actor.status = 'ACTIVE' AND actor.security_version > 0
     ) THEN
    RAISE EXCEPTION 'S4.9 Strong LLM usage arguments are invalid' USING ERRCODE = '22023';
  END IF;
  IF p_outcome = 'COMMITTED' THEN
    IF p_answer_basis NOT IN ('EVIDENCE','MODEL_KNOWLEDGE','INSUFFICIENT_EVIDENCE')
       OR p_prompt_token_count NOT BETWEEN 0 AND 500000
       OR p_output_token_count NOT BETWEEN 0 AND 100000 THEN
      RAISE EXCEPTION 'S4.9 committed usage shape is invalid' USING ERRCODE = '22023';
    END IF;
  ELSE
    IF p_answer_basis IS NOT NULL OR p_prompt_token_count IS NOT NULL OR p_output_token_count IS NOT NULL THEN
      RAISE EXCEPTION 'S4.9 non-committed usage must be content-free' USING ERRCODE = '22023';
    END IF;
  END IF;
  INSERT INTO public.s4_9_strong_llm_usage_ledger (
    usage_event_id, owner_user_id, request_id, provider, model_id, answer_basis, outcome,
    tool_round_count, search_call_count, read_call_count, prompt_token_count, output_token_count,
    evidence_set_sha256
  ) VALUES (
    p_usage_event_id, p_owner_user_id, p_request_id, p_provider, p_model_id, p_answer_basis, p_outcome,
    p_tool_round_count, p_search_call_count, p_read_call_count, p_prompt_token_count, p_output_token_count,
    p_evidence_set_sha256
  );
END
$_$;


ALTER FUNCTION public.record_s4_9_strong_llm_usage(p_usage_event_id text, p_owner_user_id text, p_request_id text, p_provider text, p_model_id text, p_answer_basis text, p_outcome text, p_tool_round_count integer, p_search_call_count integer, p_read_call_count integer, p_prompt_token_count integer, p_output_token_count integer, p_evidence_set_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.record_s4_9_strong_llm_usage_v2(p_usage_event_id text, p_owner_user_id text, p_request_id text, p_model_id text, p_answer_basis text, p_outcome text, p_tool_round_count integer, p_search_call_count integer, p_read_call_count integer, p_prompt_token_count integer, p_output_token_count integer, p_evidence_set_sha256 text, p_vertex_generate_call_count integer, p_google_grounding_query_count integer, p_search_backend text, p_evidence_validation_mode text, p_failure_leaf text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_usage_event_id !~ '^s49_llu_[0-9a-f]{32}$'
     OR p_request_id !~ '^req_[A-Za-z0-9_-]{12,96}$'
     OR p_model_id !~ '^[a-z][a-z0-9.-]{2,127}$'
     OR p_outcome NOT IN ('COMMITTED','REJECTED','UNKNOWN_BILLING')
     OR p_tool_round_count NOT BETWEEN 0 AND 3
     OR p_search_call_count NOT BETWEEN 0 AND 3 OR p_read_call_count NOT BETWEEN 0 AND 8
     OR p_vertex_generate_call_count NOT BETWEEN 0 AND 4
     OR p_google_grounding_query_count NOT BETWEEN 0 AND 128
     OR p_search_backend NOT IN ('NONE','VERTEX_GOOGLE','SEARXNG')
     OR p_evidence_validation_mode NOT IN ('CANONICAL_EXACT','GOOGLE_GROUNDING','MIXED','NONE')
     OR p_evidence_set_sha256 !~ '^[0-9a-f]{64}$'
     OR (p_failure_leaf IS NOT NULL AND p_failure_leaf !~ '^[A-Z0-9_]{3,96}$') THEN
    RAISE EXCEPTION 'S4.9 Strong LLM v2 usage is invalid' USING ERRCODE = '22023';
  END IF;
  IF p_outcome = 'COMMITTED' THEN
    IF p_answer_basis NOT IN ('EVIDENCE','MODEL_KNOWLEDGE','INSUFFICIENT_EVIDENCE')
       OR p_prompt_token_count NOT BETWEEN 0 AND 500000 OR p_output_token_count NOT BETWEEN 0 AND 100000
       OR p_failure_leaf IS NOT NULL THEN
      RAISE EXCEPTION 'S4.9 committed v2 usage is invalid' USING ERRCODE = '22023';
    END IF;
  ELSE
    IF p_answer_basis IS NOT NULL OR p_prompt_token_count IS NOT NULL OR p_output_token_count IS NOT NULL
       OR p_failure_leaf IS NULL THEN
      RAISE EXCEPTION 'S4.9 failed v2 usage is invalid' USING ERRCODE = '22023';
    END IF;
  END IF;
  INSERT INTO public.s4_9_strong_llm_usage_ledger(
    usage_event_id, owner_user_id, request_id, provider, model_id, answer_basis, outcome,
    tool_round_count, search_call_count, read_call_count, prompt_token_count, output_token_count,
    evidence_set_sha256, usage_schema_version, vertex_generate_call_count,
    google_grounding_query_count, search_backend, evidence_validation_mode, failure_leaf
  ) VALUES (
    p_usage_event_id, p_owner_user_id, p_request_id, 'VERTEX_AI', p_model_id, p_answer_basis, p_outcome,
    p_tool_round_count, p_search_call_count, p_read_call_count, p_prompt_token_count, p_output_token_count,
    p_evidence_set_sha256, 2, p_vertex_generate_call_count,
    p_google_grounding_query_count, p_search_backend, p_evidence_validation_mode, p_failure_leaf
  );
END
$_$;


ALTER FUNCTION public.record_s4_9_strong_llm_usage_v2(p_usage_event_id text, p_owner_user_id text, p_request_id text, p_model_id text, p_answer_basis text, p_outcome text, p_tool_round_count integer, p_search_call_count integer, p_read_call_count integer, p_prompt_token_count integer, p_output_token_count integer, p_evidence_set_sha256 text, p_vertex_generate_call_count integer, p_google_grounding_query_count integer, p_search_backend text, p_evidence_validation_mode text, p_failure_leaf text) OWNER TO flyway;


CREATE FUNCTION public.record_s4_9_web_evidence_metadata(p_evidence_id text, p_owner_user_id text, p_oauth_client_id text, p_research_context_id text, p_canonical_url text, p_title text, p_section_locator text, p_retrieved_at timestamp with time zone, p_content_sha256 text, p_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_evidence_id !~ '^s49_web_[0-9a-f]{32}$' OR p_research_context_id !~ '^s49_ctx_[0-9a-f]{32}$'
     OR p_canonical_url !~ '^https://' OR octet_length(p_canonical_url) NOT BETWEEN 9 AND 2048
     OR char_length(p_title) NOT BETWEEN 1 AND 500 OR p_content_sha256 !~ '^[0-9a-f]{64}$'
     OR p_retrieved_at NOT BETWEEN transaction_timestamp() - interval '60 seconds' AND transaction_timestamp() + interval '60 seconds'
     OR p_expires_at <= p_retrieved_at OR p_expires_at > p_retrieved_at + interval '24 hours'
     OR (p_oauth_client_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.s4_9_mcp_oauth_clients c WHERE c.client_id = p_oauth_client_id AND c.status = 'ACTIVE'
     )) THEN
    RAISE EXCEPTION 'S4.9 web evidence metadata is invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.s4_9_web_evidence_metadata (
    evidence_id, owner_user_id, oauth_client_id, research_context_id, canonical_url, title,
    section_locator, retrieved_at, content_sha256, expires_at
  ) VALUES (
    p_evidence_id, p_owner_user_id, p_oauth_client_id, p_research_context_id, p_canonical_url, p_title,
    p_section_locator, p_retrieved_at, p_content_sha256, p_expires_at
  ) ON CONFLICT (evidence_id) DO NOTHING;
END
$_$;


ALTER FUNCTION public.record_s4_9_web_evidence_metadata(p_evidence_id text, p_owner_user_id text, p_oauth_client_id text, p_research_context_id text, p_canonical_url text, p_title text, p_section_locator text, p_retrieved_at timestamp with time zone, p_content_sha256 text, p_expires_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.register_rag_verified_source_card(p_source_revision_id text, p_source_id text, p_card_id text, p_card_metadata_hash text, p_verified_at timestamp with time zone, p_public_topics text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  inserted_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_source_revision_id !~ '^src_rev_[0-9a-f]{32}$'
     OR p_source_id !~ '^src_project_[a-z0-9_]+_[0-9]{3}$'
     OR p_card_id !~ '^card_[a-z0-9][a-z0-9_]{1,127}_[0-9]{3}$'
     OR p_card_id IS DISTINCT FROM regexp_replace(p_source_id, '^src_project_', 'card_')
     OR p_card_metadata_hash !~ '^[0-9a-f]{64}$'
     OR p_verified_at IS NULL
     OR p_verified_at > transaction_timestamp() + interval '1 minute'
     OR p_public_topics IS NULL
     OR cardinality(p_public_topics) NOT BETWEEN 1 AND 5
     OR cardinality(ARRAY(SELECT DISTINCT unnest(p_public_topics)))
        <> cardinality(p_public_topics)
     OR NOT (
       p_public_topics <@ ARRAY[
         'API',
         'DATA',
         'FINANCIAL_ENGINEERING',
         'METHODOLOGY',
         'PRODUCT_RISK',
         'RISK'
       ]::text[]
     )
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_source_revisions AS revision
       JOIN public.rag_sources AS source
         ON source.source_id = revision.source_id
        AND source.source_type = 'PROJECT_SOURCE_CARD'
        AND source.retired_at IS NULL
       WHERE revision.source_revision_id = p_source_revision_id
         AND revision.source_id = p_source_id
         AND revision.tier = 'PROJECT'
         AND revision.access_level = 'PUBLIC'
         AND revision.initial_processing = 'PROJECT_AUTHORED_CARD'
         AND (
           (
             revision.registry_version = 's4-7b-source-card-v2'
             AND NOT revision.external_processing_allowed
           )
           OR
           (
             revision.registry_version = 's4-7c-source-card-v2'
             AND revision.external_processing_allowed
             AND position(
               'approvalId=AUTH_EXTERNAL_PROCESSING_30_PROJECT_CARDS_20260731' IN revision.license_note
             ) > 0
           )
         )
         AND revision.metadata_hash = p_card_metadata_hash
     ) THEN
    RAISE EXCEPTION 'RAG verified source-card registration is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.rag_source_card_verifications (
    source_revision_id,
    card_id,
    status,
    card_metadata_hash,
    verified_at
  )
  VALUES (
    p_source_revision_id,
    p_card_id,
    'VERIFIED',
    p_card_metadata_hash,
    p_verified_at
  )
  ON CONFLICT (source_revision_id) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;

  IF inserted_count = 0
     AND NOT EXISTS (
       SELECT 1
       FROM public.rag_source_card_verifications AS verification
       WHERE verification.source_revision_id = p_source_revision_id
         AND verification.card_id = p_card_id
         AND verification.status = 'VERIFIED'
         AND verification.card_metadata_hash = p_card_metadata_hash
         AND verification.verified_at = p_verified_at
     ) THEN
    RAISE EXCEPTION 'RAG verified source-card identity drifted'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.rag_source_public_topics (source_id, public_topic)
  SELECT p_source_id, topic
  FROM unnest(p_public_topics) AS topic
  ORDER BY convert_to(topic, 'UTF8')
  ON CONFLICT DO NOTHING;

  IF (
    SELECT array_agg(topic.public_topic ORDER BY convert_to(topic.public_topic, 'UTF8'))
    FROM public.rag_source_public_topics AS topic
    WHERE topic.source_id = p_source_id
  ) IS DISTINCT FROM (
    SELECT array_agg(topic ORDER BY convert_to(topic, 'UTF8'))
    FROM unnest(p_public_topics) AS topic
  ) THEN
    RAISE EXCEPTION 'RAG verified source-card public topic identity drifted'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.rag_source_exact_identifiers (
    source_id,
    identifier,
    identifier_kind
  )
  SELECT approved.source_id, approved.identifier, approved.identifier_kind
  FROM (
    VALUES
      ('src_project_kis_current_price_snapshot_001', 'FHKST01010100', 'KIS_TR_ID'),
      ('src_project_kis_adjusted_price_001', 'FHKST03010100', 'KIS_TR_ID'),
      ('src_project_gold_futures_etf_132030_001', '132030', 'SYMBOL')
  ) AS approved(source_id, identifier, identifier_kind)
  WHERE approved.source_id = p_source_id
  ON CONFLICT DO NOTHING;

  IF EXISTS (
    SELECT 1
    FROM (
      VALUES
        ('src_project_kis_current_price_snapshot_001', 'FHKST01010100', 'KIS_TR_ID'),
        ('src_project_kis_adjusted_price_001', 'FHKST03010100', 'KIS_TR_ID'),
        ('src_project_gold_futures_etf_132030_001', '132030', 'SYMBOL')
    ) AS approved(source_id, identifier, identifier_kind)
    WHERE approved.source_id = p_source_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.rag_source_exact_identifiers AS exact_identifier
        WHERE exact_identifier.source_id = approved.source_id
          AND exact_identifier.identifier = approved.identifier
          AND exact_identifier.identifier_kind = approved.identifier_kind
      )
  ) THEN
    RAISE EXCEPTION 'RAG exact identifier identity drifted'
      USING ERRCODE = '23514';
  END IF;
  RETURN inserted_count;
END
$_$;


