CREATE FUNCTION public.replace_and_delete_rag_v2_immutable_owner_document(p_owner_user_id text, p_document_id text, p_activation_receipt_id text, p_deletion_receipt_id text, p_reason_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  replacement record;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
     OR p_activation_receipt_id !~ '^rgr_act_[0-9a-f]{32}$'
     OR p_deletion_receipt_id !~ '^rgr_del_[0-9a-f]{32}$'
     OR p_reason_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 active owner deletion arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  -- V31 acquires the target document lock before the shared global activation lock. V25 sees
  -- the same xact locks reentrantly, so replacement activation and old graph hard-delete commit
  -- together or both roll back.
  SELECT * INTO replacement
  FROM public.prepare_rag_v2_immutable_owner_overlay(p_owner_user_id, p_document_id);
  IF NOT FOUND
     OR replacement.bundle_id IS NULL
     OR replacement.bundle_id !~ '^rgb_[0-9a-f]{32}$'
     OR replacement.expected_active_bundle_id IS NULL
     OR replacement.expected_active_bundle_id !~ '^rgb_[0-9a-f]{32}$'
     OR replacement.expected_bundle_version IS NULL
     OR replacement.expected_bundle_version < 1 THEN
    RAISE EXCEPTION 'immutable RAG v2 active owner deletion replacement is not ready'
      USING ERRCODE = '23514';
  END IF;

  RETURN public.delete_rag_v2_immutable_owner_document(
    p_owner_user_id,
    p_document_id,
    replacement.bundle_id,
    replacement.expected_active_bundle_id,
    replacement.expected_bundle_version,
    p_activation_receipt_id,
    p_deletion_receipt_id,
    p_reason_hash
  );
END;
$_$;


ALTER FUNCTION public.replace_and_delete_rag_v2_immutable_owner_document(p_owner_user_id text, p_document_id text, p_activation_receipt_id text, p_deletion_receipt_id text, p_reason_hash text) OWNER TO flyway;


CREATE FUNCTION public.replay_async_work(p_actor_user_id text, p_security_version bigint, p_replay_batch_id text, p_target_kind text, p_target_ids text[], p_expected_count integer, p_reason_code text, p_packet_hash text, p_execute boolean) RETURNS TABLE(target_id text, source_job_id text, source_event_id text, new_job_id text, new_event_id text, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actual integer; resolved record; generated_job_id text; generated_event_id text; authorized integer;
BEGIN
  IF session_user <> 'decision_replay' THEN RAISE EXCEPTION 'async replay role denied' USING ERRCODE='42501'; END IF;
  UPDATE public.async_replay_authorization AS authz SET consumed_at=statement_timestamp()
  WHERE authz.packet_hash=p_packet_hash AND authz.actor_user_id=p_actor_user_id
    AND authz.actor_security_version=p_security_version AND authz.replay_batch_id=p_replay_batch_id
    AND authz.target_kind=p_target_kind AND authz.target_ids=p_target_ids
    AND authz.expected_count=p_expected_count AND authz.reason_code=p_reason_code
    AND authz.execute_authorized=p_execute AND authz.consumed_at IS NULL
    AND authz.issued_at<=statement_timestamp() AND authz.expires_at>statement_timestamp()
    AND EXISTS (SELECT 1 FROM public.users actor WHERE actor.user_id=p_actor_user_id
      AND actor.status='ACTIVE' AND actor.role='ADMIN' AND actor.security_version=p_security_version);
  GET DIAGNOSTICS authorized=ROW_COUNT;
  IF authorized<>1 THEN RAISE EXCEPTION 'replay authorization unavailable' USING ERRCODE='42501'; END IF;
  CREATE TEMP TABLE pg_temp.s7_replay_targets ON COMMIT DROP AS
    SELECT requested.target_id,job.job_id source_job_id,event.event_id source_event_id,job.job_type,
      job.requested_by,job.payload_json,event.event_type,event.aggregate_type,event.partition_key,event.schema_version
    FROM unnest(p_target_ids) requested(target_id)
    JOIN public.async_job job ON ((p_target_kind='JOB' AND job.job_id=requested.target_id) OR
      (p_target_kind='EVENT' AND EXISTS (SELECT 1 FROM public.event_outbox lookup
        WHERE lookup.event_id=requested.target_id AND lookup.aggregate_id=job.job_id)))
    JOIN LATERAL (SELECT candidate.* FROM public.event_outbox candidate WHERE candidate.aggregate_id=job.job_id
      AND candidate.event_type IN ('rag.index-requested.v1','artifact.ingest-requested.v1','model.eval-requested.v1')
      AND (p_target_kind='JOB' OR candidate.event_id=requested.target_id)
      ORDER BY candidate.created_at,candidate.event_id LIMIT 1) event ON true
    WHERE job.status IN ('FAILED','NEEDS_REVIEW') OR event.status IN ('FAILED','DLQ_REQUESTED');
  SELECT count(*) INTO actual FROM pg_temp.s7_replay_targets;
  INSERT INTO public.async_replay_audit(replay_batch_id,actor_user_id,actor_security_version,target_kind,
    expected_count,actual_count,dry_run,outcome,reason_code,packet_hash)
  VALUES (p_replay_batch_id,p_actor_user_id,p_security_version,p_target_kind,p_expected_count,actual,NOT p_execute,
    CASE WHEN actual<>p_expected_count THEN 'COUNT_MISMATCH' WHEN p_execute THEN 'EXECUTED' ELSE 'DRY_RUN' END,
    p_reason_code,p_packet_hash);
  IF actual<>p_expected_count THEN
    RETURN QUERY SELECT requested.target_id,NULL::text,NULL::text,NULL::text,NULL::text,'COUNT_MISMATCH'::text
    FROM unnest(p_target_ids) requested(target_id) ORDER BY requested.target_id; RETURN;
  END IF;
  FOR resolved IN SELECT * FROM pg_temp.s7_replay_targets ORDER BY target_id LOOP
    generated_job_id:=CASE WHEN p_execute THEN 'job_'||replace(gen_random_uuid()::text,'-','') ELSE NULL END;
    generated_event_id:=CASE WHEN p_execute THEN 'evt_'||replace(gen_random_uuid()::text,'-','') ELSE NULL END;
    IF p_execute THEN
      resolved.payload_json:=jsonb_set(resolved.payload_json,'{jobId}',to_jsonb(generated_job_id),true)
        ||jsonb_build_object('replayOf',resolved.source_event_id);
      INSERT INTO public.async_job(job_id,job_type,status,requested_by,payload_json,next_attempt_at)
      VALUES (generated_job_id,resolved.job_type,'REQUESTED',resolved.requested_by,resolved.payload_json,statement_timestamp());
      INSERT INTO public.event_outbox(event_id,event_type,aggregate_type,aggregate_id,partition_key,payload_json,schema_version,next_attempt_at)
      VALUES (generated_event_id,resolved.event_type,resolved.aggregate_type,generated_job_id,resolved.partition_key,
        resolved.payload_json,resolved.schema_version,statement_timestamp());
    END IF;
    INSERT INTO public.async_replay_item_audit(replay_batch_id,target_id,source_job_id,source_event_id,new_job_id,new_event_id)
    VALUES (p_replay_batch_id,resolved.target_id,resolved.source_job_id,resolved.source_event_id,generated_job_id,generated_event_id);
    target_id:=resolved.target_id;source_job_id:=resolved.source_job_id;source_event_id:=resolved.source_event_id;
    new_job_id:=generated_job_id;new_event_id:=generated_event_id;
    outcome:=CASE WHEN p_execute THEN 'EXECUTED' ELSE 'DRY_RUN' END;RETURN NEXT;
  END LOOP;
END
$$;


ALTER FUNCTION public.replay_async_work(p_actor_user_id text, p_security_version bigint, p_replay_batch_id text, p_target_kind text, p_target_ids text[], p_expected_count integer, p_reason_code text, p_packet_hash text, p_execute boolean) OWNER TO flyway;


CREATE FUNCTION public.request_mock_order_cancel(requested_payload jsonb, requested_capability_token text) RETURNS TABLE(operation_outcome text, order_id text, account_id text, brokerage_mode text, status text, submitted_at timestamp with time zone, decision_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  requested_actor_user_id text;
  requested_actor_role text;
  requested_security_version bigint;
  requested_request_id text;
  requested_order_id text;
  requested_cancelled_at timestamptz;
  requested_order_event_id text;
  terminal_order_event_id text;
  requested_audit_log_id text;
  requested_outbox_event_id text;
  stored_actor record;
  stored_order record;
  current_status text;
  next_event_seq integer;
  target_status text;
  target_event_type text;
  target_action text;
  target_outbox_type text;
  reference_payload jsonb;
BEGIN
  PERFORM public.assert_brokerage_database_capability(requested_capability_token);
  IF requested_payload IS NULL
     OR jsonb_typeof(requested_payload) <> 'object'
     OR NOT requested_payload ?& ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'requestId',
       'orderId', 'cancelledAt', 'orderEventId', 'auditLogId', 'outboxEventId'
     ]
     OR requested_payload - ARRAY[
       'actorUserId', 'actorRole', 'securityVersion', 'requestId',
       'orderId', 'cancelledAt', 'orderEventId', 'auditLogId', 'outboxEventId'
     ] <> '{}'::jsonb THEN
    RETURN QUERY
    SELECT 'VALIDATION_ERROR'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;
  requested_actor_user_id := requested_payload ->> 'actorUserId';
  requested_actor_role := requested_payload ->> 'actorRole';
  requested_security_version := (requested_payload ->> 'securityVersion')::bigint;
  requested_request_id := requested_payload ->> 'requestId';
  requested_order_id := requested_payload ->> 'orderId';
  requested_cancelled_at := (requested_payload ->> 'cancelledAt')::timestamptz;
  requested_order_event_id := requested_payload ->> 'orderEventId';
  terminal_order_event_id := requested_order_event_id;
  requested_audit_log_id := requested_payload ->> 'auditLogId';
  requested_outbox_event_id := requested_payload ->> 'outboxEventId';

  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id
  FOR SHARE;
  IF NOT FOUND
     OR stored_actor.status <> 'ACTIVE'
     OR stored_actor.role <> requested_actor_role
     OR stored_actor.security_version <> requested_security_version THEN
    RETURN QUERY
    SELECT 'ACTOR_UNAUTHORIZED'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('brokerage-order:cancel:' || requested_order_id, 3201)
  );
  SELECT
    stored.order_id,
    stored.account_id,
    stored.brokerage_mode,
    stored.status,
    stored.submitted_at,
    stored.decision_id
  INTO stored_order
  FROM public.orders stored
  WHERE stored.order_id = requested_order_id
    AND stored.user_id = requested_actor_user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY
    SELECT 'ORDER_NOT_FOUND'::text, NULL::text, NULL::text, NULL::text,
           NULL::text, NULL::timestamptz, NULL::text;
    RETURN;
  END IF;
  SELECT event.event_status
  INTO current_status
  FROM public.order_events event
  WHERE event.order_id = requested_order_id
    AND event.event_status IS NOT NULL
  ORDER BY event.event_seq DESC
  LIMIT 1;
  current_status := COALESCE(current_status, stored_order.status);

  IF stored_order.brokerage_mode = 'INTERNAL_PAPER' THEN
    IF current_status <> 'ACCEPTED' THEN
      RETURN QUERY
      SELECT 'ORDER_CONFLICT'::text, NULL::text, NULL::text, NULL::text,
             NULL::text, NULL::timestamptz, NULL::text;
      RETURN;
    END IF;
    target_status := 'CANCELLED';
    target_event_type := 'PAPER_ORDER_CANCELLED';
    target_action := 'PAPER_ORDER_CANCELLED';
    target_outbox_type := 'brokerage.paper-order-cancelled.v1';
  ELSE
    IF current_status NOT IN ('SUBMITTED', 'ACCEPTED', 'PARTIALLY_FILLED') THEN
      RETURN QUERY
      SELECT 'ORDER_CONFLICT'::text, NULL::text, NULL::text, NULL::text,
             NULL::text, NULL::timestamptz, NULL::text;
      RETURN;
    END IF;
    target_status := 'CANCEL_REQUESTED';
    target_event_type := 'MOCK_ORDER_CANCEL_REQUESTED';
    target_action := 'MOCK_ORDER_CANCEL_REQUESTED';
    target_outbox_type := 'brokerage.mock-order-cancel-requested.v1';
  END IF;

  SELECT COALESCE(max(event.event_seq), 0) + 1
  INTO next_event_seq
  FROM public.order_events event
  WHERE event.order_id = requested_order_id;

  IF stored_order.brokerage_mode = 'INTERNAL_PAPER' THEN
    INSERT INTO public.order_events (
      order_event_id, order_id, event_type, event_status, payload_json,
      created_at, event_seq
    )
    VALUES (
      requested_order_event_id, requested_order_id,
      'PAPER_ORDER_CANCEL_REQUESTED', 'CANCEL_REQUESTED',
      jsonb_build_object(
        'orderId', requested_order_id,
        'brokerageMode', stored_order.brokerage_mode,
        'status', 'CANCEL_REQUESTED'
      ),
      requested_cancelled_at,
      next_event_seq
    );
    next_event_seq := next_event_seq + 1;
    -- 단일 cancel 입력에서도 두 append-only 이벤트가 충돌하지 않도록 확정 ID를 결정적으로 분리한다.
    terminal_order_event_id :=
      'oev_' || substr(
        encode(
          sha256(convert_to(requested_order_event_id || ':paper-cancelled', 'UTF8')),
          'hex'
        ),
        1,
        32
      );
  END IF;

  INSERT INTO public.order_events (
    order_event_id, order_id, event_type, event_status, payload_json,
    created_at, event_seq
  )
  VALUES (
    terminal_order_event_id, requested_order_id, target_event_type,
    target_status,
    jsonb_build_object(
      'orderId', requested_order_id,
      'brokerageMode', stored_order.brokerage_mode,
      'status', target_status
    ),
    requested_cancelled_at,
    next_event_seq
  );
  reference_payload :=
    jsonb_build_object(
      'orderId', requested_order_id,
      'decisionId', stored_order.decision_id,
      'brokerageMode', stored_order.brokerage_mode,
      'status', target_status,
      'requestedByRole', requested_actor_role,
      'requestedAt', requested_cancelled_at::text
    );
  INSERT INTO public.audit_logs (
    audit_log_id, user_id, actor_role, action, target_type, target_id,
    request_id, payload_json, created_at
  )
  VALUES (
    requested_audit_log_id, requested_actor_user_id, requested_actor_role,
    target_action, 'ORDER', requested_order_id, requested_request_id,
    reference_payload, requested_cancelled_at
  );
  INSERT INTO public.event_outbox (
    event_id, event_type, aggregate_type, aggregate_id, partition_key,
    payload_json, schema_version, status, retry_count, created_at, updated_at
  )
  VALUES (
    requested_outbox_event_id, target_outbox_type, 'ORDER',
    requested_order_id, requested_order_id, reference_payload,
    '1.0.0', 'PENDING', 0, requested_cancelled_at, requested_cancelled_at
  );
  RETURN QUERY
  SELECT
    target_status,
    stored_order.order_id,
    stored_order.account_id,
    stored_order.brokerage_mode,
    target_status,
    stored_order.submitted_at,
    stored_order.decision_id;
END
$$;


