     OR p_nonce_sha256 IS NULL OR p_nonce_sha256 !~ '^[0-9a-f]{64}$'
     OR p_bundle_manifest_sha256 IS NULL OR p_bundle_manifest_sha256 !~ '^[0-9a-f]{64}$'
     OR p_rate_evidence_sha256 IS NULL OR p_rate_evidence_sha256 !~ '^[0-9a-f]{64}$'
     OR p_official_tokenizer_sha256 IS NULL OR p_official_tokenizer_sha256 !~ '^[0-9a-f]{64}$'
     OR p_expires_at IS NULL OR p_expires_at <= statement_timestamp()
     OR p_expires_at > statement_timestamp() + interval '5 minutes'
     OR p_token_cap IS NULL OR p_token_cap NOT BETWEEN 1 AND 120000
     OR p_byte_cap IS NULL OR p_byte_cap NOT BETWEEN 1 AND 4194304
     OR p_cost_cap_microusd IS NULL OR p_cost_cap_microusd NOT BETWEEN 1 AND 1000000000
     OR p_input_microusd_per_token IS NULL OR p_input_microusd_per_token NOT BETWEEN 1 AND 1000000
     OR p_token_cap::bigint * p_input_microusd_per_token > p_cost_cap_microusd THEN
    RAISE EXCEPTION 'immutable Pre-S5 Voyage tokenizer usage reservation arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-voyage-usage-reservation|' || p_packet_sha256, 0)
  );
  INSERT INTO public.rag_v2_immutable_voyage_usage_reservations (
    usage_event_id, packet_sha256, nonce_sha256, bundle_manifest_sha256, rate_evidence_sha256,
    official_tokenizer_sha256, expires_at, token_cap, byte_cap, cost_cap_microusd,
    input_microusd_per_token
  ) VALUES (
    p_usage_event_id, p_packet_sha256, p_nonce_sha256, p_bundle_manifest_sha256, p_rate_evidence_sha256,
    p_official_tokenizer_sha256, p_expires_at, p_token_cap, p_byte_cap, p_cost_cap_microusd,
    p_input_microusd_per_token
  );
  RETURN QUERY SELECT p_usage_event_id, p_expires_at;
END
$_$;


ALTER FUNCTION public.reserve_rag_v2_immutable_voyage_usage_with_tokenizer(p_usage_event_id text, p_packet_sha256 text, p_nonce_sha256 text, p_bundle_manifest_sha256 text, p_rate_evidence_sha256 text, p_official_tokenizer_sha256 text, p_expires_at timestamp with time zone, p_token_cap integer, p_byte_cap integer, p_cost_cap_microusd bigint, p_input_microusd_per_token bigint) OWNER TO flyway;


CREATE FUNCTION public.reserve_rag_v2_owner_voyage_import(p_owner_user_id text, p_plan_sha256 text, p_packet_sha256 text, p_approval_manifest_sha256 text, p_nonce_sha256 text, p_ticket_set_sha256 text, p_ticket_ids text[], p_document_count integer, p_chunk_count integer, p_expected_input_tokens integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  provided_ticket_set_sha256 text;
  authorized_ticket_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
     OR p_packet_sha256 !~ '^[0-9a-f]{64}$'
     OR p_approval_manifest_sha256 !~ '^[0-9a-f]{64}$'
     OR p_nonce_sha256 !~ '^[0-9a-f]{64}$'
     OR p_ticket_set_sha256 !~ '^[0-9a-f]{64}$'
     OR p_ticket_ids IS NULL
     OR cardinality(p_ticket_ids) IS DISTINCT FROM p_document_count
     OR EXISTS (
       SELECT 1 FROM unnest(p_ticket_ids) AS ticket_id
       WHERE ticket_id !~ '^rti_[0-9a-f]{32}$'
     )
     OR (
       SELECT count(DISTINCT ticket_id)
       FROM unnest(p_ticket_ids) AS ticket_id
     ) <> p_document_count
     OR p_document_count NOT BETWEEN 1 AND 1000
     OR p_chunk_count NOT BETWEEN p_document_count AND 16000
     OR p_expected_input_tokens NOT BETWEEN 1 AND 55000 THEN
    RAISE EXCEPTION 'OWNER_VOYAGE_IMPORT_TOO_LARGE'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-owner-library|' || p_owner_user_id, 0)
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  provided_ticket_set_sha256 := encode(
    digest(array_to_string(p_ticket_ids, E'\n') || E'\n', 'sha256'),
    'hex'
  );
  IF provided_ticket_set_sha256 IS DISTINCT FROM p_ticket_set_sha256 THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage ticket set is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT count(*)::integer
  INTO authorized_ticket_count
  FROM public.rag_v2_immutable_import_tickets AS ticket
  WHERE ticket.owner_user_id = p_owner_user_id
    AND ticket.operation = 'OWNER_IMPORT'
    AND ticket.policy_version = 'RAG_V2_OWNER_DOCUMENT_V2'
    AND ticket.embedding_profile_id = 'voyage_context_4_1024_v1'
    AND ticket.state = 'ISSUED'
    AND ticket.consumed_at IS NULL
    AND ticket.expires_at > statement_timestamp()
    AND ticket.ticket_hash = ANY (
      ARRAY(
        SELECT encode(digest(ticket_id, 'sha256'), 'hex')
        FROM unnest(p_ticket_ids) AS ticket_id
      )
    );
  IF authorized_ticket_count <> p_document_count THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage ticket authorization is absent'
      USING ERRCODE = '42501';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_source_revisions AS source
    JOIN public.rag_v2_immutable_materialization_runs AS run
      ON run.owner_user_id = source.owner_user_id
     AND run.document_id = source.document_id
     AND run.component_scope = 'OWNER_PRIVATE'
    JOIN public.rag_v2_immutable_component_generations AS generation
      ON generation.component_generation_id = run.component_generation_id
    WHERE source.owner_user_id = p_owner_user_id
      AND source.source_scope = 'OWNER_PRIVATE'
      AND generation.embedding_profile_id <> 'voyage_context_4_1024_v1'
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner library profile is locked'
      USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_consent_events AS consent
    WHERE consent.owner_user_id = p_owner_user_id
      AND consent.public_consent_event_id IS NOT NULL
      AND consent.policy_digest IS NOT NULL
      AND consent.processor_set_digest IS NOT NULL
      AND consent.action = 'GRANT'
      AND NOT EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_consent_events AS newer
        WHERE newer.owner_user_id = consent.owner_user_id
          AND newer.public_consent_event_id IS NOT NULL
          AND (newer.created_at, newer.consent_event_id) > (consent.created_at, consent.consent_event_id)
      )
  ) OR EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_owner_bundle_pointers AS pointer
    JOIN public.rag_v2_immutable_bundles AS bundle
      ON bundle.bundle_id = pointer.active_bundle_id
     AND bundle.owner_user_id = pointer.owner_user_id
    WHERE pointer.owner_user_id = p_owner_user_id
      AND pointer.state = 'READY'
      AND bundle.owner_embedding_profile_id IS NOT NULL
      AND bundle.owner_embedding_profile_id IS DISTINCT FROM 'voyage_context_4_1024_v1'
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage authorization is absent'
      USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.rag_v2_owner_voyage_import_attempts (
    plan_sha256, owner_user_id, packet_sha256, approval_manifest_sha256,
    nonce_sha256, ticket_set_sha256, document_count, chunk_count,
    expected_input_tokens, state
  ) VALUES (
    p_plan_sha256, p_owner_user_id, p_packet_sha256, p_approval_manifest_sha256,
    p_nonce_sha256, p_ticket_set_sha256, p_document_count, p_chunk_count,
    p_expected_input_tokens, 'ATTEMPTED'
  );
  RETURN true;
END;
$_$;


ALTER FUNCTION public.reserve_rag_v2_owner_voyage_import(p_owner_user_id text, p_plan_sha256 text, p_packet_sha256 text, p_approval_manifest_sha256 text, p_nonce_sha256 text, p_ticket_set_sha256 text, p_ticket_ids text[], p_document_count integer, p_chunk_count integer, p_expected_input_tokens integer) OWNER TO flyway;


CREATE FUNCTION public.reserve_s4_9_google_grounding_budget(p_reservation_id text, p_owner_user_id text, p_request_id text, p_billing_account_fingerprint text, p_billing_period_start date, p_reserve_count integer, p_soft_cap integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  budget_row public.s4_9_google_grounding_monthly_budget%ROWTYPE;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_reservation_id !~ '^s49_gbr_[0-9a-f]{32}$'
     OR p_request_id !~ '^req_[A-Za-z0-9_-]{12,96}$'
     OR p_billing_account_fingerprint !~ '^[0-9a-f]{64}$'
     OR p_reserve_count NOT BETWEEN 1 AND 8 OR p_soft_cap NOT BETWEEN 1 AND 5000
     OR NOT EXISTS (SELECT 1 FROM public.users u WHERE u.user_id = p_owner_user_id AND u.status = 'ACTIVE') THEN
    RAISE EXCEPTION 'S4.9 Google budget reservation is invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.s4_9_google_grounding_monthly_budget(
    billing_account_fingerprint, billing_period_start
  ) VALUES (p_billing_account_fingerprint, p_billing_period_start)
  ON CONFLICT DO NOTHING;
  SELECT * INTO budget_row FROM public.s4_9_google_grounding_monthly_budget
  WHERE billing_account_fingerprint = p_billing_account_fingerprint
    AND billing_period_start = p_billing_period_start
  FOR UPDATE;
  IF budget_row.observed_query_count + budget_row.reserved_query_count
       + budget_row.unknown_query_count + p_reserve_count > p_soft_cap THEN
    RETURN false;
  END IF;
  UPDATE public.s4_9_google_grounding_monthly_budget
  SET reserved_query_count = reserved_query_count + p_reserve_count,
      updated_at = transaction_timestamp()
  WHERE billing_account_fingerprint = p_billing_account_fingerprint
    AND billing_period_start = p_billing_period_start;
  INSERT INTO public.s4_9_google_grounding_reservations(
    reservation_id, owner_user_id, request_id, billing_account_fingerprint,
    billing_period_start, reserved_query_count, state
  ) VALUES (
    p_reservation_id, p_owner_user_id, p_request_id, p_billing_account_fingerprint,
    p_billing_period_start, p_reserve_count, 'RESERVED'
  );
  RETURN true;
END
$_$;


ALTER FUNCTION public.reserve_s4_9_google_grounding_budget(p_reservation_id text, p_owner_user_id text, p_request_id text, p_billing_account_fingerprint text, p_billing_period_start date, p_reserve_count integer, p_soft_cap integer) OWNER TO flyway;


CREATE FUNCTION public.reserve_s4_9_runtime_voyage_query_usage(p_scope_claim_id text, p_question_sha256 text, p_official_tokenizer_sha256 text) RETURNS TABLE(usage_event_id text, packet_sha256 text, nonce_sha256 text, rate_evidence_sha256 text, expires_at timestamp with time zone, token_cap integer, byte_cap integer, cost_cap_microusd bigint, input_microusd_per_token bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  authorization_row public.s4_9_voyage_query_authorizations%ROWTYPE;
  active_tokenizer_sha256 text;
  generated_usage_event_id text;
  generated_packet_sha256 text;
  generated_nonce_sha256 text;
  generated_rate_evidence_sha256 text;
  reservation_expires_at timestamptz;
  fixed_token_cap constant integer := 8192;
  fixed_byte_cap constant integer := 4194304;
  fixed_cost_cap_microusd constant bigint := 8192;
  fixed_input_microusd_per_token constant bigint := 1;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_scope_claim_id !~ '^rvs_[0-9a-f]{32}$'
     OR p_question_sha256 !~ '^[0-9a-f]{64}$'
     OR p_official_tokenizer_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'S4.9 Voyage query reservation arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO authorization_row
  FROM public.s4_9_voyage_query_authorizations AS authorized_query
  WHERE authorized_query.scope_claim_id = p_scope_claim_id
    AND authorized_query.question_sha256 = p_question_sha256
    AND authorized_query.expires_at > statement_timestamp()
  FOR UPDATE;
  IF NOT FOUND OR EXISTS (
    SELECT 1 FROM public.s4_9_voyage_query_usage_links AS link
    WHERE link.authorization_id = authorization_row.authorization_id
  ) THEN
    RAISE EXCEPTION 'S4.9 Voyage query authorization is unavailable' USING ERRCODE = '55000';
  END IF;

  -- query writer는 owner ID를 입력으로 받지 않으므로 one-shot authorization의 owner를 RLS actor로 복원한다.
  PERFORM set_config('app.actor_user_id', authorization_row.owner_user_id, true);
  IF NOT EXISTS (
    SELECT 1 FROM public.rag_v2_retrieval_scope_claims AS claim
    WHERE claim.scope_claim_id = p_scope_claim_id
      AND claim.owner_user_id = authorization_row.owner_user_id
      AND claim.embedding_profile_id = 'voyage_context_4_1024_v1'
      AND claim.expires_at > statement_timestamp()
  ) THEN
    RAISE EXCEPTION 'S4.9 Voyage query scope is unavailable' USING ERRCODE = '55000';
  END IF;

  SELECT plan.official_tokenizer_sha256 INTO active_tokenizer_sha256
  FROM public.rag_v2_immutable_voyage_document_batch_plans AS plan
  WHERE plan.state = 'COMPLETE'
    AND plan.embedding_profile_id = 'voyage_context_4_1024_v1'
  ORDER BY plan.completed_at DESC, plan.created_at DESC
  LIMIT 1;
  IF active_tokenizer_sha256 IS DISTINCT FROM p_official_tokenizer_sha256 THEN
    RAISE EXCEPTION 'S4.9 Voyage query tokenizer is unavailable' USING ERRCODE = '55000';
  END IF;

  generated_packet_sha256 := encode(
    digest(convert_to('s4.9-runtime-voyage-query-packet-v1' || authorization_row.authorization_id, 'UTF8'), 'sha256'),
    'hex'
  );
  generated_nonce_sha256 := encode(digest(gen_random_bytes(32), 'sha256'), 'hex');
  generated_rate_evidence_sha256 := encode(
    digest(convert_to('s4.9-runtime-voyage-query-conservative-cap-v1', 'UTF8'), 'sha256'),
    'hex'
  );
  generated_usage_event_id :=
    'rgr_vqu_' || substr(
      encode(
        digest(
          convert_to(
            authorization_row.authorization_id || generated_packet_sha256 || generated_nonce_sha256,
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ),
      1,
      32
    );
  reservation_expires_at := least(authorization_row.expires_at, statement_timestamp() + interval '2 minutes');

  INSERT INTO public.rag_v2_immutable_voyage_query_usage_reservations (
    usage_event_id, packet_sha256, nonce_sha256, query_sha256, scope_claim_sha256,
    rate_evidence_sha256, official_tokenizer_sha256, evaluation_component_scope,
    expires_at, token_cap, byte_cap, cost_cap_microusd, input_microusd_per_token
  ) VALUES (
    generated_usage_event_id, generated_packet_sha256, generated_nonce_sha256, p_question_sha256,
    encode(digest(convert_to(p_scope_claim_id, 'UTF8'), 'sha256'), 'hex'),
    generated_rate_evidence_sha256, p_official_tokenizer_sha256, 'RUNTIME',
    reservation_expires_at, fixed_token_cap, fixed_byte_cap,
    fixed_cost_cap_microusd, fixed_input_microusd_per_token
  );
  INSERT INTO public.s4_9_voyage_query_usage_links (authorization_id, usage_event_id)
  VALUES (authorization_row.authorization_id, generated_usage_event_id);

  RETURN QUERY SELECT
    generated_usage_event_id,
    generated_packet_sha256,
    generated_nonce_sha256,
    generated_rate_evidence_sha256,
    reservation_expires_at,
    fixed_token_cap,
    fixed_byte_cap,
    fixed_cost_cap_microusd,
    fixed_input_microusd_per_token;
END
$_$;


ALTER FUNCTION public.reserve_s4_9_runtime_voyage_query_usage(p_scope_claim_id text, p_question_sha256 text, p_official_tokenizer_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.resolve_completed_async_event(p_event_id text, p_event_type text, p_job_id text, p_payload_hash text, p_partition_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF session_user <> 'decision_worker' THEN RAISE EXCEPTION 'async duplicate role denied' USING ERRCODE='42501'; END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.event_outbox source
    JOIN public.async_job job ON job.job_id=source.aggregate_id
    JOIN public.processed_event processed ON processed.event_id=source.event_id
      AND processed.consumer_name='python-async-worker-v1' AND processed.payload_hash=p_payload_hash
      AND NOT processed.payload_hash_conflict
    JOIN public.async_materialization_receipt receipt ON receipt.event_id=source.event_id AND receipt.job_id=job.job_id
    WHERE source.event_id=p_event_id AND source.event_type=p_event_type
      AND source.aggregate_type='ASYNC_JOB' AND source.aggregate_id=p_job_id
      AND source.partition_key=p_partition_key AND source.schema_version='1.0.0'
      AND coalesce(source.transport_payload_hash,
        'sha256:'||encode(public.digest(source.payload_json::text,'sha256'),'hex'))=p_payload_hash
      AND job.status='COMPLETED'
  );
END
$$;


ALTER FUNCTION public.resolve_completed_async_event(p_event_id text, p_event_type text, p_job_id text, p_payload_hash text, p_partition_key text) OWNER TO flyway;


CREATE FUNCTION public.resolve_rag_v2_retrieval_scope(p_scope_claim_id text, p_owner_user_id text, p_session_id text) RETURNS TABLE(scope_claim_id text, owner_user_id text, session_id text, allowed_topics text[], exact30_generation_id text, oa112_generation_id text, owner_private_generation_id text, embedding_profile_id text, policy_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  claim_row public.rag_v2_retrieval_scope_claims%ROWTYPE;
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  owner_bundle public.rag_v2_immutable_bundles%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_scope_claim_id !~ '^rvs_[0-9a-f]{32}$'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$' THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope resolution arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);

  SELECT * INTO claim_row
  FROM public.rag_v2_retrieval_scope_claims
  WHERE scope_claim_id = p_scope_claim_id
    AND owner_user_id = p_owner_user_id
    AND session_id = p_session_id
    AND expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope is absent or expired'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers
  WHERE state_id = 'default'
    AND state = 'ACTIVE'
    AND pointer_version = claim_row.public_pointer_version
    AND exact30_generation_id = claim_row.exact30_generation_id
    AND oa112_generation_id = claim_row.oa112_generation_id
    AND embedding_profile_id = claim_row.embedding_profile_id;
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_component_generations AS exact_generation
       JOIN public.rag_v2_immutable_component_generations AS oa_generation
         ON oa_generation.component_generation_id = claim_row.oa112_generation_id
        AND oa_generation.component_scope = 'OA112'
        AND oa_generation.owner_user_id IS NULL
        AND oa_generation.embedding_profile_id = claim_row.embedding_profile_id
        AND oa_generation.state = 'ACTIVE'
        AND oa_generation.evaluation_status = 'PASSED'
       WHERE exact_generation.component_generation_id = claim_row.exact30_generation_id
         AND exact_generation.component_scope = 'EXACT30'
         AND exact_generation.owner_user_id IS NULL
         AND exact_generation.embedding_profile_id = claim_row.embedding_profile_id
         AND exact_generation.state = 'ACTIVE'
         AND exact_generation.evaluation_status = 'PASSED'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope public pointer changed'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO owner_pointer
  FROM public.rag_v2_immutable_owner_bundle_pointers
  WHERE owner_user_id = p_owner_user_id;
  IF claim_row.owner_private_generation_id IS NULL THEN
    IF (FOUND AND (owner_pointer.state <> 'ABSENT' OR owner_pointer.bundle_version <> claim_row.owner_pointer_version))
       OR (NOT FOUND AND claim_row.owner_pointer_version <> 0) THEN
      RAISE EXCEPTION 'immutable RAG v2 retrieval scope owner pointer changed'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    IF NOT FOUND
       OR owner_pointer.state <> 'READY'
       OR owner_pointer.active_bundle_id IS DISTINCT FROM claim_row.owner_bundle_id
       OR owner_pointer.bundle_version <> claim_row.owner_pointer_version THEN
      RAISE EXCEPTION 'immutable RAG v2 retrieval scope owner bundle changed'
        USING ERRCODE = '55000';
    END IF;
    SELECT * INTO owner_bundle
    FROM public.rag_v2_immutable_bundles
    WHERE bundle_id = claim_row.owner_bundle_id
      AND owner_user_id = p_owner_user_id
      AND owner_private_generation_id = claim_row.owner_private_generation_id
      AND exact30_generation_id = claim_row.exact30_generation_id
      AND oa112_generation_id = claim_row.oa112_generation_id
      AND embedding_profile_id = claim_row.embedding_profile_id
      AND state = 'ACTIVE';
    IF NOT FOUND
       OR NOT EXISTS (
         SELECT 1
         FROM public.rag_v2_immutable_component_generations AS owner_generation
         WHERE owner_generation.component_generation_id = claim_row.owner_private_generation_id
           AND owner_generation.component_scope = 'OWNER_PRIVATE'
           AND owner_generation.owner_user_id = p_owner_user_id
           AND owner_generation.embedding_profile_id = claim_row.embedding_profile_id
           AND owner_generation.state = 'ACTIVE'
           AND owner_generation.evaluation_status = 'PASSED'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 retrieval scope owner component changed'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    claim_row.scope_claim_id,
    claim_row.owner_user_id,
    claim_row.session_id,
    claim_row.allowed_topics,
    claim_row.exact30_generation_id,
    claim_row.oa112_generation_id,
    claim_row.owner_private_generation_id,
    claim_row.embedding_profile_id,
    claim_row.policy_version;
END;
$_$;


ALTER FUNCTION public.resolve_rag_v2_retrieval_scope(p_scope_claim_id text, p_owner_user_id text, p_session_id text) OWNER TO flyway;


CREATE FUNCTION public.resolve_rag_v2_retrieval_scope_v2(p_scope_claim_id text, p_owner_user_id text, p_session_id text) RETURNS TABLE(scope_claim_id text, owner_user_id text, session_id text, allowed_topics text[], exact30_generation_id text, oa112_generation_id text, owner_private_generation_id text, embedding_profile_id text, owner_embedding_profile_id text, policy_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  claim_row public.rag_v2_retrieval_scope_claims%ROWTYPE;
  public_pointer public.rag_v2_immutable_public_bundle_pointers%ROWTYPE;
  owner_pointer public.rag_v2_immutable_owner_bundle_pointers%ROWTYPE;
  owner_bundle public.rag_v2_immutable_bundles%ROWTYPE;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_scope_claim_id !~ '^rvs_[0-9a-f]{32}$'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_session_id IS NULL
     OR char_length(p_session_id) NOT BETWEEN 16 AND 128
     OR p_session_id !~ '^[A-Za-z0-9._:-]+$' THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope resolution arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  PERFORM set_config('app.rag_v2_retrieval_scope', 'enabled', true);

  SELECT * INTO claim_row
  FROM public.rag_v2_retrieval_scope_claims
  WHERE scope_claim_id = p_scope_claim_id
    AND owner_user_id = p_owner_user_id
    AND session_id = p_session_id
    AND expires_at > statement_timestamp();
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope is absent or expired'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO public_pointer
  FROM public.rag_v2_immutable_public_bundle_pointers
  WHERE state_id = 'default'
    AND state = 'ACTIVE'
    AND pointer_version = claim_row.public_pointer_version
    AND exact30_generation_id = claim_row.exact30_generation_id
    AND oa112_generation_id = claim_row.oa112_generation_id
    AND embedding_profile_id = claim_row.embedding_profile_id;
  IF NOT FOUND
     OR NOT EXISTS (
       SELECT 1
       FROM public.rag_v2_immutable_component_generations AS exact_generation
       JOIN public.rag_v2_immutable_component_generations AS oa_generation
         ON oa_generation.component_generation_id = claim_row.oa112_generation_id
        AND oa_generation.component_scope = 'OA112'
        AND oa_generation.owner_user_id IS NULL
        AND oa_generation.embedding_profile_id = claim_row.embedding_profile_id
        AND oa_generation.state = 'ACTIVE'
        AND oa_generation.evaluation_status = 'PASSED'
       WHERE exact_generation.component_generation_id = claim_row.exact30_generation_id
         AND exact_generation.component_scope = 'EXACT30'
         AND exact_generation.owner_user_id IS NULL
         AND exact_generation.embedding_profile_id = claim_row.embedding_profile_id
         AND exact_generation.state = 'ACTIVE'
         AND exact_generation.evaluation_status = 'PASSED'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 retrieval scope public pointer changed'
      USING ERRCODE = '55000';
  END IF;

  IF NOT claim_row.owner_scope_authorized THEN
    IF claim_row.owner_private_generation_id IS NOT NULL
       OR claim_row.owner_bundle_id IS NOT NULL
       OR claim_row.owner_embedding_profile_id IS NOT NULL
       OR claim_row.owner_pointer_version <> 0 THEN
      RAISE EXCEPTION 'S4.9 MCP public retrieval scope is invalid'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    SELECT * INTO owner_pointer
    FROM public.rag_v2_immutable_owner_bundle_pointers
    WHERE owner_user_id = p_owner_user_id;
    IF claim_row.owner_private_generation_id IS NULL THEN
    IF (
      FOUND
      AND owner_pointer.bundle_version = claim_row.owner_pointer_version
      AND (
        owner_pointer.state = 'ABSENT'
        OR (
          owner_pointer.state = 'READY'
          AND EXISTS (
            SELECT 1
            FROM public.rag_v2_immutable_bundles AS empty_bundle
            JOIN public.rag_v2_immutable_component_generations AS empty_generation
              ON empty_generation.component_generation_id = empty_bundle.owner_private_generation_id
             AND empty_generation.owner_user_id = empty_bundle.owner_user_id
            WHERE empty_bundle.bundle_id = owner_pointer.active_bundle_id
              AND empty_bundle.owner_user_id = p_owner_user_id
              AND empty_bundle.state = 'ACTIVE'
              AND empty_bundle.owner_embedding_profile_id IS NULL
              AND empty_generation.actual_source_count = 0
              AND empty_generation.actual_chunk_count = 0
          )
        )
      )
    ) THEN
      NULL;
    ELSIF (FOUND OR claim_row.owner_pointer_version <> 0) THEN
      RAISE EXCEPTION 'immutable RAG v2 retrieval scope owner pointer changed'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    IF NOT FOUND
       OR owner_pointer.state <> 'READY'
       OR owner_pointer.active_bundle_id IS DISTINCT FROM claim_row.owner_bundle_id
       OR owner_pointer.bundle_version <> claim_row.owner_pointer_version THEN
      RAISE EXCEPTION 'immutable RAG v2 retrieval scope owner bundle changed'
        USING ERRCODE = '55000';
    END IF;
    SELECT * INTO owner_bundle
    FROM public.rag_v2_immutable_bundles
    WHERE bundle_id = claim_row.owner_bundle_id
      AND owner_user_id = p_owner_user_id
      AND owner_private_generation_id = claim_row.owner_private_generation_id
      AND exact30_generation_id = claim_row.exact30_generation_id
      AND oa112_generation_id = claim_row.oa112_generation_id
      AND embedding_profile_id = claim_row.embedding_profile_id
      AND owner_embedding_profile_id IS NOT DISTINCT FROM claim_row.owner_embedding_profile_id
      AND state = 'ACTIVE';
    IF NOT FOUND
       OR NOT EXISTS (
         SELECT 1
         FROM public.rag_v2_immutable_component_generations AS owner_generation
         WHERE owner_generation.component_generation_id = claim_row.owner_private_generation_id
           AND owner_generation.component_scope = 'OWNER_PRIVATE'
           AND owner_generation.owner_user_id = p_owner_user_id
           AND owner_generation.embedding_profile_id = claim_row.owner_embedding_profile_id
           AND owner_generation.state = 'ACTIVE'
           AND owner_generation.evaluation_status = 'PASSED'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 retrieval scope owner component changed'
        USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    claim_row.scope_claim_id,
    claim_row.owner_user_id,
    claim_row.session_id,
    claim_row.allowed_topics,
    claim_row.exact30_generation_id,
    claim_row.oa112_generation_id,
    claim_row.owner_private_generation_id,
    claim_row.embedding_profile_id,
    claim_row.owner_embedding_profile_id,
    claim_row.policy_version;
END;
$_$;


ALTER FUNCTION public.resolve_rag_v2_retrieval_scope_v2(p_scope_claim_id text, p_owner_user_id text, p_session_id text) OWNER TO flyway;


CREATE FUNCTION public.retire_rag_source_for_relocation(previous_source_id text, replacement_source_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  previous_source record;
  replacement_source record;
  previous_sequence integer;
  replacement_sequence integer;
  retired boolean;
BEGIN
  IF previous_source_id IS NULL
     OR replacement_source_id IS NULL
     OR previous_source_id !~ '^src_[a-z0-9]+_[a-z0-9_]+_[0-9]{3}$'
     OR replacement_source_id !~ '^src_[a-z0-9]+_[a-z0-9_]+_[0-9]{3}$'
     OR previous_source_id = replacement_source_id THEN
    RAISE EXCEPTION 'RAG source relocation identity is invalid'
      USING ERRCODE = '22023';
  END IF;

  -- 반대 순서의 동시 relocation도 같은 lock order를 사용해 교착을 피한다.
  PERFORM 1
  FROM public.rag_sources AS source
  WHERE source.source_id IN (previous_source_id, replacement_source_id)
  ORDER BY source.source_id
  FOR UPDATE;

  SELECT
    source.source_type,
    source.institution,
    source.topic,
    source.owner_identity,
    source.retired_at
  INTO previous_source
  FROM public.rag_sources AS source
  WHERE source.source_id = previous_source_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG relocation previous source is missing'
      USING ERRCODE = '23503';
  END IF;

  SELECT
    source.source_type,
    source.institution,
    source.topic,
    source.owner_identity,
    source.retired_at
  INTO replacement_source
  FROM public.rag_sources AS source
  WHERE source.source_id = replacement_source_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RAG relocation replacement source is missing'
      USING ERRCODE = '23503';
  END IF;

  previous_sequence := right(previous_source_id, 3)::integer;
  replacement_sequence := right(replacement_source_id, 3)::integer;
  IF left(previous_source_id, char_length(previous_source_id) - 3)
       IS DISTINCT FROM
       left(replacement_source_id, char_length(replacement_source_id) - 3)
     OR replacement_sequence <> previous_sequence + 1
     OR previous_source.source_type IS DISTINCT FROM replacement_source.source_type
     OR previous_source.institution IS DISTINCT FROM replacement_source.institution
     OR previous_source.topic IS DISTINCT FROM replacement_source.topic
     OR previous_source.owner_identity IS DISTINCT FROM replacement_source.owner_identity
     OR replacement_source.retired_at IS NOT NULL THEN
    RAISE EXCEPTION 'RAG relocation requires the next matching active source identity'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.rag_source_revisions AS revision
    WHERE revision.source_id = replacement_source_id
      AND revision.revision_seq = 1
  ) THEN
    RAISE EXCEPTION 'RAG relocation replacement revision is missing'
      USING ERRCODE = '23503';
  END IF;

  IF previous_source.retired_at IS NOT NULL THEN
    RETURN false;
  END IF;

  UPDATE public.rag_sources AS source
  SET retired_at = transaction_timestamp()
  WHERE source.source_id = previous_source_id
    AND source.retired_at IS NULL;
  retired := FOUND;
  RETURN retired;
END
$_$;


ALTER FUNCTION public.retire_rag_source_for_relocation(previous_source_id text, replacement_source_id text) OWNER TO flyway;


CREATE FUNCTION public.revalidate_kill_switch_admin(requested_actor_user_id text, requested_security_version bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  stored_actor_role text;
  stored_actor_status text;
  stored_security_version bigint;
BEGIN
  SELECT actor.role, actor.status, actor.security_version
  INTO stored_actor_role, stored_actor_status, stored_security_version
  FROM public.users actor
  WHERE actor.user_id = requested_actor_user_id
  FOR SHARE;

  IF NOT FOUND
     OR stored_actor_status <> 'ACTIVE'
     OR stored_security_version <> requested_security_version THEN
    RETURN 'UNAUTHORIZED';
  END IF;
  IF stored_actor_role <> 'ADMIN' THEN
    RETURN 'FORBIDDEN';
  END IF;
  RETURN 'AUTHORIZED';
END
$$;


ALTER FUNCTION public.revalidate_kill_switch_admin(requested_actor_user_id text, requested_security_version bigint) OWNER TO flyway;


CREATE FUNCTION public.revoke_s4_9_mcp_refresh_token_family(p_token_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE family text;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app' OR p_token_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'S4.9 refresh token hash is invalid' USING ERRCODE = '22023';
  END IF;
  SELECT token_family_id INTO family FROM public.s4_9_mcp_oauth_refresh_tokens
  WHERE token_sha256 = p_token_sha256 FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'S4.9 refresh token hash is unavailable' USING ERRCODE = '55000';
  END IF;
  UPDATE public.s4_9_mcp_oauth_refresh_tokens
  SET revoked_at = coalesce(revoked_at, transaction_timestamp())
  WHERE token_family_id = family;
END
$_$;


ALTER FUNCTION public.revoke_s4_9_mcp_refresh_token_family(p_token_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.rotate_s4_9_mcp_refresh_token_hash(p_token_sha256 text, p_client_id text, p_owner_user_id text, p_security_version bigint, p_resource_uri text, p_scopes text[], p_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE family_id text;
DECLARE previous_hash text;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR p_token_sha256 !~ '^[0-9a-f]{64}$' OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_security_version <= 0 OR p_expires_at <= transaction_timestamp()
     OR p_expires_at > transaction_timestamp() + interval '7 days 1 minute'
     OR NOT p_scopes <@ ARRAY['mcp:rag.public','mcp:rag.owner','mcp:web.read','mcp:answer.validate','mcp:history.write']::text[] THEN
    RAISE EXCEPTION 'S4.9 refresh token hash is invalid' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.s4_9_mcp_oauth_refresh_tokens WHERE token_sha256 = p_token_sha256) THEN
    RETURN;
  END IF;
  family_id := 'mrf_' || substr(encode(digest(p_client_id || ':' || p_owner_user_id, 'sha256'), 'hex'), 1, 32);
  SELECT token_sha256 INTO previous_hash FROM public.s4_9_mcp_oauth_refresh_tokens
  WHERE token_family_id = family_id AND rotated_at IS NULL AND revoked_at IS NULL FOR UPDATE;
  IF FOUND THEN
    UPDATE public.s4_9_mcp_oauth_refresh_tokens SET rotated_at = transaction_timestamp()
    WHERE token_sha256 = previous_hash;
  END IF;
  INSERT INTO public.s4_9_mcp_oauth_refresh_tokens (
    token_sha256, token_family_id, client_id, owner_user_id, security_version,
    resource_uri, scopes, previous_token_sha256, expires_at
  ) VALUES (
    p_token_sha256, family_id, p_client_id, p_owner_user_id, p_security_version,
    p_resource_uri, p_scopes, previous_hash, p_expires_at
  );
END
$_$;


ALTER FUNCTION public.rotate_s4_9_mcp_refresh_token_hash(p_token_sha256 text, p_client_id text, p_owner_user_id text, p_security_version bigint, p_resource_uri text, p_scopes text[], p_expires_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.s48_runtime_source_pair_is_valid(p_source_family text, p_source_id text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (p_source_family = 'KIS' AND p_source_id = 'S48_CORE6_KIS')
    OR (p_source_family = 'OPENDART' AND p_source_id = 'S48_CORE6_OPENDART')
    OR (p_source_family = 'SEC_EDGAR' AND p_source_id = 'S48_CORE6_SEC_EDGAR')
    OR (p_source_family = 'KRX' AND p_source_id = 'S48_CORE6_KRX')
    OR (p_source_family = 'KOFIA' AND p_source_id = 'S48_CORE6_KOFIA')
    OR (p_source_family = 'ECOS' AND p_source_id = 'S48_CORE6_ECOS')
    OR (p_source_family = 'FINNHUB_OPTIONAL3' AND p_source_id = 'S48_OPTIONAL3_FINNHUB')
    OR (p_source_family = 'TWELVE_DATA' AND p_source_id = 'S48_OPTIONAL3_TWELVE_DATA')
    OR (p_source_family = 'MASSIVE' AND p_source_id = 'S48_OPTIONAL3_MASSIVE'),
    false
  )
$$;


ALTER FUNCTION public.s48_runtime_source_pair_is_valid(p_source_family text, p_source_id text) OWNER TO flyway;


CREATE FUNCTION public.s48_runtime_state_is_safe(p_source_family text, p_ingestion_mode text, p_status text, p_reason text, p_projection_hash text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
  SELECT COALESCE(
    (
      p_source_family IN ('OPENDART', 'ECOS')
      AND p_ingestion_mode = 'REUSE_AUTHORIZED_PROJECTION'
      AND (
        (
          p_status = 'AVAILABLE'
          AND p_reason = 'AUTHORIZED_PROJECTION_AVAILABLE'
          AND p_projection_hash ~ '^[0-9a-f]{64}$'
        )
        OR (
          p_status = 'ABSTAIN'
          AND p_reason = 'REUSE_AUTHORIZED_PROJECTION_NOT_AVAILABLE'
          AND p_projection_hash IS NULL
        )
      )
    )
    OR (
      p_source_family IN ('KIS', 'SEC_EDGAR', 'KRX')
      AND p_ingestion_mode = 'DIRECT_READ_PROBE'
      AND (
        (
          p_status = 'AVAILABLE'
          AND p_reason = 'COMPLETE_DIRECT_PROBE_SET_AVAILABLE'
          AND p_projection_hash ~ '^[0-9a-f]{64}$'
        )
        OR (
          p_status = 'ABSTAIN'
          AND p_reason IN ('APPROVAL_PACKET_REQUIRED', 'DIRECT_PROBE_RECEIPT_SET_INCOMPLETE')
          AND p_projection_hash IS NULL
        )
      )
    )
    OR (
      p_source_family = 'KOFIA'
      AND p_ingestion_mode = 'DIRECT_READ_PROBE'
      AND p_status = 'BLOCKED'
      AND p_reason = 'BLOCKED_NO_CREDENTIAL_OR_APPROVAL'
      AND p_projection_hash IS NULL
    )
    OR (
      p_source_family IN ('FINNHUB_OPTIONAL3', 'TWELVE_DATA', 'MASSIVE')
      AND p_ingestion_mode = 'DIRECT_READ_PROBE'
      AND p_status = 'BLOCKED'
      AND p_reason = 'BLOCKED_NO_CREDENTIAL_OR_ENTITLEMENT'
      AND p_projection_hash IS NULL
    ),
    false
  )
$_$;


ALTER FUNCTION public.s48_runtime_state_is_safe(p_source_family text, p_ingestion_mode text, p_status text, p_reason text, p_projection_hash text) OWNER TO flyway;


CREATE FUNCTION public.s5_signal_batch_clock_at(p_now timestamp with time zone) RETURNS TABLE(session_date date, as_of timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT prior_session.session_date,
    (next_session.session_date + time '08:10') AT TIME ZONE 'Asia/Seoul'
  FROM public.trading_sessions prior_session
  JOIN LATERAL (
    SELECT candidate.session_date
    FROM public.trading_sessions candidate
    WHERE candidate.exchange_mic = 'XKRX' AND candidate.is_open
      AND candidate.has_conflict = false
      AND candidate.session_date > prior_session.session_date
    ORDER BY candidate.session_date
    LIMIT 1
  ) next_session ON true
  WHERE prior_session.exchange_mic = 'XKRX' AND prior_session.is_open
    AND prior_session.has_conflict = false
    AND (next_session.session_date + time '08:10') AT TIME ZONE 'Asia/Seoul'
      <= p_now
  ORDER BY prior_session.session_date DESC
  LIMIT 1
$$;


ALTER FUNCTION public.s5_signal_batch_clock_at(p_now timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.search_authorized_rag_dense(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_embedding public.vector) RETURNS TABLE(rank_no integer, chunk_revision_id text, source_revision_id text, source_id text, card_id text, title text, heading_path text[], canonical_content text, canonical_content_hash text, topic text, public_topics text[], access_level text, tier text, source_status text, scope_claim_id text, owner_user_id text, session_id text, generation_id text, embedding_profile_id text, policy_version bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_topics IS NULL
     OR cardinality(p_topics) NOT BETWEEN 1 AND 6
     OR cardinality(ARRAY(SELECT DISTINCT unnest(p_topics))) <> cardinality(p_topics)
     OR NOT (
       p_topics <@ ARRAY[
         'API', 'DATA', 'FINANCIAL_ENGINEERING', 'METHODOLOGY', 'PRODUCT_RISK', 'RISK'
       ]::text[]
     )
     OR p_query_embedding IS NULL
     OR vector_dims(p_query_embedding) <> 1024
     OR vector_norm(p_query_embedding)::text IN ('NaN', 'Infinity', '-Infinity')
     OR abs(vector_norm(p_query_embedding)::double precision - 1.0) > 0.00001 THEN
    RAISE EXCEPTION 'RAG dense retrieval arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    row_number() OVER (
      ORDER BY
        embedding.embedding <=> p_query_embedding,
        membership.ordinal,
        convert_to(source.source_id, 'UTF8'),
        convert_to(chunk.chunk_revision_id, 'UTF8')
    )::integer,
    chunk.chunk_revision_id,
    revision.source_revision_id,
    source.source_id,
    verification.card_id,
    revision.title,
    chunk.heading_path,
    chunk.canonical_content,
    chunk.canonical_content_hash,
    chunk.topic,
    ARRAY(
      SELECT selected_topic.public_topic
      FROM public.rag_source_public_topics AS selected_topic
      WHERE selected_topic.source_id = source.source_id
      ORDER BY convert_to(selected_topic.public_topic, 'UTF8')
    ),
    chunk.access_level,
    chunk.tier,
    verification.status,
    claim.scope_claim_id,
    claim.owner_user_id,
    claim.session_id,
    claim.active_generation_id,
    claim.effective_profile_id,
    claim.policy_version
  FROM public.rag_retrieval_scope_claims AS claim
  JOIN public.rag_embedding_policy_state AS policy_state
    ON policy_state.state_id = 'default'
   AND policy_state.active_generation_id = claim.active_generation_id
   AND policy_state.effective_profile_id = claim.effective_profile_id
   AND policy_state.version = claim.policy_version
  JOIN public.rag_corpus_generations AS generation
    ON generation.corpus_generation_id = policy_state.active_generation_id
   AND generation.embedding_profile_id = policy_state.effective_profile_id
   AND generation.status = 'ACTIVE'
   AND generation.evaluation_status = 'PASSED'
  JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = claim.active_generation_id
   AND membership.embedding_profile_id = claim.effective_profile_id
  JOIN public.rag_chunk_embeddings AS embedding
    ON embedding.corpus_generation_id = membership.corpus_generation_id
   AND embedding.chunk_revision_id = membership.chunk_revision_id
   AND embedding.embedding_profile_id = membership.embedding_profile_id
  JOIN public.rag_chunk_revisions AS chunk
    ON chunk.chunk_revision_id = membership.chunk_revision_id
   AND chunk.access_level = 'PUBLIC'
   AND chunk.tier = 'PROJECT'
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = chunk.source_revision_id
   AND revision.access_level = 'PUBLIC'
   AND revision.tier = 'PROJECT'
  JOIN public.rag_source_card_verifications AS verification
    ON verification.source_revision_id = revision.source_revision_id
   AND verification.card_metadata_hash = revision.metadata_hash
   AND verification.status = 'VERIFIED'
  JOIN public.rag_sources AS source
    ON source.source_id = revision.source_id
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  WHERE claim.scope_claim_id = p_scope_claim_id
    AND claim.owner_user_id = p_owner_user_id
    AND claim.session_id = p_session_id
    AND claim.expires_at > statement_timestamp()
    AND p_topics <@ claim.allowed_topics
    AND EXISTS (
      SELECT 1
      FROM public.rag_source_public_topics AS topic
      WHERE topic.source_id = source.source_id
        AND topic.public_topic = ANY(claim.allowed_topics)
        AND topic.public_topic = ANY(p_topics)
    )
    AND embedding.embedding <=> p_query_embedding <= 0.55
  ORDER BY
    embedding.embedding <=> p_query_embedding,
    membership.ordinal,
    convert_to(source.source_id, 'UTF8'),
    convert_to(chunk.chunk_revision_id, 'UTF8')
  LIMIT 30;
END
$$;


ALTER FUNCTION public.search_authorized_rag_dense(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_embedding public.vector) OWNER TO flyway;


CREATE FUNCTION public.search_authorized_rag_exact(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_identifiers text[]) RETURNS TABLE(rank_no integer, chunk_revision_id text, source_revision_id text, source_id text, card_id text, title text, heading_path text[], canonical_content text, canonical_content_hash text, topic text, public_topics text[], access_level text, tier text, source_status text, scope_claim_id text, owner_user_id text, session_id text, generation_id text, embedding_profile_id text, policy_version bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_topics IS NULL
     OR cardinality(p_topics) NOT BETWEEN 1 AND 6
     OR cardinality(ARRAY(SELECT DISTINCT unnest(p_topics))) <> cardinality(p_topics)
     OR NOT (
       p_topics <@ ARRAY[
         'API', 'DATA', 'FINANCIAL_ENGINEERING', 'METHODOLOGY', 'PRODUCT_RISK', 'RISK'
       ]::text[]
     )
     OR p_identifiers IS NULL
     OR cardinality(p_identifiers) NOT BETWEEN 0 AND 16
     OR EXISTS (
       SELECT 1
       FROM unnest(p_identifiers) AS identifier
       WHERE octet_length(identifier) NOT BETWEEN 1 AND 128
     ) THEN
    RAISE EXCEPTION 'RAG exact retrieval arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    row_number() OVER (
      ORDER BY
        CASE
          WHEN source.source_id = ANY(p_identifiers) THEN 0
          WHEN EXISTS (
            SELECT 1
            FROM public.rag_source_exact_identifiers AS exact_identifier
            WHERE exact_identifier.source_id = source.source_id
              AND exact_identifier.identifier = ANY(p_identifiers)
              AND exact_identifier.identifier_kind = 'KIS_TR_ID'
          ) THEN 1
          WHEN EXISTS (
            SELECT 1
            FROM public.rag_source_exact_identifiers AS exact_identifier
            WHERE exact_identifier.source_id = source.source_id
              AND exact_identifier.identifier = ANY(p_identifiers)
              AND exact_identifier.identifier_kind = 'SYMBOL'
          ) THEN 2
          ELSE 3
        END,
        membership.ordinal,
        convert_to(source.source_id, 'UTF8'),
        convert_to(chunk.chunk_revision_id, 'UTF8')
    )::integer,
    chunk.chunk_revision_id,
    revision.source_revision_id,
    source.source_id,
    verification.card_id,
    revision.title,
    chunk.heading_path,
    chunk.canonical_content,
    chunk.canonical_content_hash,
    chunk.topic,
    ARRAY(
      SELECT selected_topic.public_topic
      FROM public.rag_source_public_topics AS selected_topic
      WHERE selected_topic.source_id = source.source_id
      ORDER BY convert_to(selected_topic.public_topic, 'UTF8')
    ),
    chunk.access_level,
    chunk.tier,
    verification.status,
    claim.scope_claim_id,
    claim.owner_user_id,
    claim.session_id,
    claim.active_generation_id,
    claim.effective_profile_id,
    claim.policy_version
  FROM public.rag_retrieval_scope_claims AS claim
  JOIN public.rag_embedding_policy_state AS policy_state
    ON policy_state.state_id = 'default'
   AND policy_state.active_generation_id = claim.active_generation_id
   AND policy_state.effective_profile_id = claim.effective_profile_id
   AND policy_state.version = claim.policy_version
  JOIN public.rag_corpus_generations AS generation
    ON generation.corpus_generation_id = policy_state.active_generation_id
   AND generation.embedding_profile_id = policy_state.effective_profile_id
   AND generation.status = 'ACTIVE'
   AND generation.evaluation_status = 'PASSED'
  JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = claim.active_generation_id
   AND membership.embedding_profile_id = claim.effective_profile_id
  JOIN public.rag_chunk_embeddings AS embedding
    ON embedding.corpus_generation_id = membership.corpus_generation_id
   AND embedding.chunk_revision_id = membership.chunk_revision_id
   AND embedding.embedding_profile_id = membership.embedding_profile_id
  JOIN public.rag_chunk_revisions AS chunk
    ON chunk.chunk_revision_id = membership.chunk_revision_id
   AND chunk.access_level = 'PUBLIC'
   AND chunk.tier = 'PROJECT'
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = chunk.source_revision_id
   AND revision.access_level = 'PUBLIC'
   AND revision.tier = 'PROJECT'
  JOIN public.rag_source_card_verifications AS verification
    ON verification.source_revision_id = revision.source_revision_id
   AND verification.card_metadata_hash = revision.metadata_hash
   AND verification.status = 'VERIFIED'
  JOIN public.rag_sources AS source
    ON source.source_id = revision.source_id
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  WHERE claim.scope_claim_id = p_scope_claim_id
    AND claim.owner_user_id = p_owner_user_id
    AND claim.session_id = p_session_id
    AND claim.expires_at > statement_timestamp()
    AND p_topics <@ claim.allowed_topics
    AND EXISTS (
      SELECT 1
      FROM public.rag_source_public_topics AS topic
      WHERE topic.source_id = source.source_id
        AND topic.public_topic = ANY(claim.allowed_topics)
        AND topic.public_topic = ANY(p_topics)
    )
    AND EXISTS (
      SELECT 1
      FROM unnest(p_identifiers) AS identifier
      WHERE source.source_id = identifier
         OR EXISTS (
           SELECT 1
           FROM public.rag_source_exact_identifiers AS exact_identifier
           WHERE exact_identifier.source_id = source.source_id
             AND exact_identifier.identifier = identifier
         )
         OR strpos(lower(revision.title), lower(identifier)) > 0
         OR strpos(lower(chunk.canonical_content), lower(identifier)) > 0
    )
  ORDER BY
    CASE
      WHEN source.source_id = ANY(p_identifiers) THEN 0
      WHEN EXISTS (
        SELECT 1
        FROM public.rag_source_exact_identifiers AS exact_identifier
        WHERE exact_identifier.source_id = source.source_id
          AND exact_identifier.identifier = ANY(p_identifiers)
          AND exact_identifier.identifier_kind = 'KIS_TR_ID'
      ) THEN 1
      WHEN EXISTS (
        SELECT 1
        FROM public.rag_source_exact_identifiers AS exact_identifier
        WHERE exact_identifier.source_id = source.source_id
          AND exact_identifier.identifier = ANY(p_identifiers)
          AND exact_identifier.identifier_kind = 'SYMBOL'
      ) THEN 2
      ELSE 3
    END,
    membership.ordinal,
    convert_to(source.source_id, 'UTF8'),
    convert_to(chunk.chunk_revision_id, 'UTF8')
  LIMIT 30;
END
$$;


ALTER FUNCTION public.search_authorized_rag_exact(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_identifiers text[]) OWNER TO flyway;


CREATE FUNCTION public.search_authorized_rag_lexical(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_text text) RETURNS TABLE(rank_no integer, chunk_revision_id text, source_revision_id text, source_id text, card_id text, title text, heading_path text[], canonical_content text, canonical_content_hash text, topic text, public_topics text[], access_level text, tier text, source_status text, scope_claim_id text, owner_user_id text, session_id text, generation_id text, embedding_profile_id text, policy_version bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_topics IS NULL
     OR cardinality(p_topics) NOT BETWEEN 1 AND 6
     OR cardinality(ARRAY(SELECT DISTINCT unnest(p_topics))) <> cardinality(p_topics)
     OR NOT (
       p_topics <@ ARRAY[
         'API', 'DATA', 'FINANCIAL_ENGINEERING', 'METHODOLOGY', 'PRODUCT_RISK', 'RISK'
       ]::text[]
     )
     OR p_query_text IS NULL
     OR octet_length(p_query_text) NOT BETWEEN 1 AND 12288 THEN
    RAISE EXCEPTION 'RAG lexical retrieval arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    row_number() OVER (
      ORDER BY
        lexical.score DESC,
        membership.ordinal,
        convert_to(source.source_id, 'UTF8'),
        convert_to(chunk.chunk_revision_id, 'UTF8')
    )::integer,
    chunk.chunk_revision_id,
    revision.source_revision_id,
    source.source_id,
    verification.card_id,
    revision.title,
    chunk.heading_path,
    chunk.canonical_content,
    chunk.canonical_content_hash,
    chunk.topic,
    ARRAY(
      SELECT selected_topic.public_topic
      FROM public.rag_source_public_topics AS selected_topic
      WHERE selected_topic.source_id = source.source_id
      ORDER BY convert_to(selected_topic.public_topic, 'UTF8')
    ),
    chunk.access_level,
    chunk.tier,
    verification.status,
    claim.scope_claim_id,
    claim.owner_user_id,
    claim.session_id,
    claim.active_generation_id,
    claim.effective_profile_id,
    claim.policy_version
  FROM public.rag_retrieval_scope_claims AS claim
  JOIN public.rag_embedding_policy_state AS policy_state
    ON policy_state.state_id = 'default'
   AND policy_state.active_generation_id = claim.active_generation_id
   AND policy_state.effective_profile_id = claim.effective_profile_id
   AND policy_state.version = claim.policy_version
  JOIN public.rag_corpus_generations AS generation
    ON generation.corpus_generation_id = policy_state.active_generation_id
   AND generation.embedding_profile_id = policy_state.effective_profile_id
   AND generation.status = 'ACTIVE'
   AND generation.evaluation_status = 'PASSED'
  JOIN public.rag_generation_chunks AS membership
    ON membership.corpus_generation_id = claim.active_generation_id
   AND membership.embedding_profile_id = claim.effective_profile_id
  JOIN public.rag_chunk_embeddings AS embedding
    ON embedding.corpus_generation_id = membership.corpus_generation_id
   AND embedding.chunk_revision_id = membership.chunk_revision_id
   AND embedding.embedding_profile_id = membership.embedding_profile_id
  JOIN public.rag_chunk_revisions AS chunk
    ON chunk.chunk_revision_id = membership.chunk_revision_id
   AND chunk.access_level = 'PUBLIC'
   AND chunk.tier = 'PROJECT'
  JOIN public.rag_source_revisions AS revision
    ON revision.source_revision_id = chunk.source_revision_id
   AND revision.access_level = 'PUBLIC'
   AND revision.tier = 'PROJECT'
  JOIN public.rag_source_card_verifications AS verification
    ON verification.source_revision_id = revision.source_revision_id
   AND verification.card_metadata_hash = revision.metadata_hash
   AND verification.status = 'VERIFIED'
  JOIN public.rag_sources AS source
    ON source.source_id = revision.source_id
   AND source.source_type = 'PROJECT_SOURCE_CARD'
   AND source.retired_at IS NULL
  CROSS JOIN LATERAL (
    SELECT similarity(
      lower(
        concat_ws(
          ' ',
          source.source_id,
          revision.title,
          source.topic,
          chunk.canonical_content
        )
      ),
      lower(p_query_text)
    ) AS score
  ) AS lexical
  WHERE claim.scope_claim_id = p_scope_claim_id
    AND claim.owner_user_id = p_owner_user_id
    AND claim.session_id = p_session_id
    AND claim.expires_at > statement_timestamp()
    AND p_topics <@ claim.allowed_topics
    AND EXISTS (
      SELECT 1
      FROM public.rag_source_public_topics AS topic
      WHERE topic.source_id = source.source_id
        AND topic.public_topic = ANY(claim.allowed_topics)
        AND topic.public_topic = ANY(p_topics)
    )
    AND lexical.score >= 0.05
  ORDER BY
    lexical.score DESC,
    membership.ordinal,
    convert_to(source.source_id, 'UTF8'),
    convert_to(chunk.chunk_revision_id, 'UTF8')
  LIMIT 30;
END
$$;


ALTER FUNCTION public.search_authorized_rag_lexical(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_text text) OWNER TO flyway;


CREATE FUNCTION public.search_authorized_rag_v2_dense(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_embedding public.vector) RETURNS TABLE(rank_no integer, canonical_content text, canonical_content_sha256 text, canonical_https_url text, chunk_id text, document_id text, embedding_profile_id text, external_processing_eligible boolean, generation_id text, heading_path text[], locator jsonb, candidate_owner_user_id text, policy_version bigint, sanitized_display_name text, scope_claim_id text, session_id text, source_id text, source_revision_id text, source_scope text, citation_title text, retrieval_topics text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_query_embedding IS NULL
     OR vector_dims(p_query_embedding) <> 1024
     OR vector_norm(p_query_embedding)::text IN ('NaN', 'Infinity', '-Infinity')
     OR abs(vector_norm(p_query_embedding)::double precision - 1.0) > 0.00001 THEN
    RAISE EXCEPTION 'immutable RAG v2 dense retrieval arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH scope AS (
    SELECT *
    FROM public.resolve_rag_v2_retrieval_scope(p_scope_claim_id, p_owner_user_id, p_session_id)
  ), candidates AS (
    SELECT
      rows.*,
      embedding.embedding <=> p_query_embedding AS dense_distance
    FROM scope
    JOIN public.rag_v2_immutable_generation_memberships AS membership
      ON membership.component_generation_id = ANY(
        ARRAY[
          scope.exact30_generation_id,
          scope.oa112_generation_id,
          scope.owner_private_generation_id
        ]::text[]
      )
    JOIN public.rag_v2_immutable_chunks AS chunk
      ON chunk.chunk_id = membership.chunk_id
     AND chunk.source_revision_id = membership.source_revision_id
     AND chunk.source_scope = membership.component_scope
     AND chunk.owner_partition_key = membership.owner_partition_key
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
     AND source.source_scope = membership.component_scope
     AND source.owner_partition_key = membership.owner_partition_key
    JOIN public.rag_v2_immutable_generation_embeddings AS embedding
      ON embedding.component_generation_id = membership.component_generation_id
     AND embedding.chunk_id = membership.chunk_id
     AND embedding.component_scope = membership.component_scope
     AND embedding.owner_partition_key = membership.owner_partition_key
     AND embedding.embedding_profile_id = scope.embedding_profile_id
    CROSS JOIN LATERAL (
      SELECT
        chunk.canonical_text AS canonical_content,
        chunk.canonical_text_sha256 AS canonical_content_sha256,
        source.canonical_https_url,
        chunk.chunk_id,
        source.document_id,
        scope.embedding_profile_id,
        source.external_processing_eligible,
        membership.component_generation_id AS generation_id,
        chunk.heading_path,
        chunk.locator,
        source.owner_user_id AS candidate_owner_user_id,
        scope.policy_version,
        source.sanitized_display_name,
        scope.scope_claim_id,
        scope.session_id,
        source.source_id,
        source.source_revision_id,
        source.source_scope,
        source.citation_title,
        source.retrieval_topics
    ) AS rows
    WHERE p_topics <@ scope.allowed_topics
      AND source.retrieval_topics && p_topics
      AND (
        (
          source.source_scope IN ('EXACT30', 'OA112')
          AND source.owner_user_id IS NULL
          AND source.citation_title IS NOT NULL
          AND source.sanitized_display_name IS NULL
          AND public.rag_v2_immutable_public_https_url_is_valid(source.canonical_https_url)
        )
        OR (
          source.source_scope = 'OWNER_PRIVATE'
          AND source.owner_user_id = scope.owner_user_id
          AND source.citation_title IS NULL
          AND source.sanitized_display_name IS NOT NULL
          AND source.canonical_https_url IS NULL
        )
      )
      AND (
        source.source_scope <> 'OA112'
        OR EXISTS (
          SELECT 1
          FROM public.rag_v2_immutable_oa_source_cards AS card
          WHERE card.source_revision_id = source.source_revision_id
            AND card.source_id = source.source_id
            AND card.active_oa112_eligible
            AND card.canonical_https_url = source.canonical_https_url
        )
      )
  )
  SELECT
    row_number() OVER (
      ORDER BY dense_distance, source_id COLLATE "C", chunk_id COLLATE "C"
    )::integer,
    canonical_content,
    canonical_content_sha256,
    canonical_https_url,
    chunk_id,
    document_id,
    embedding_profile_id,
    external_processing_eligible,
    generation_id,
    heading_path,
    locator,
    candidate_owner_user_id,
    policy_version,
    sanitized_display_name,
    scope_claim_id,
    session_id,
    source_id,
    source_revision_id,
    source_scope,
    citation_title,
    retrieval_topics
  FROM candidates
  WHERE dense_distance <= 0.55
  ORDER BY dense_distance, source_id COLLATE "C", chunk_id COLLATE "C"
  LIMIT 30;
END;
$$;


ALTER FUNCTION public.search_authorized_rag_v2_dense(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_embedding public.vector) OWNER TO flyway;


CREATE FUNCTION public.search_authorized_rag_v2_dense_v2(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_embedding public.vector, p_owner_query_embedding public.vector) RETURNS TABLE(rank_no integer, canonical_content text, canonical_content_sha256 text, canonical_https_url text, chunk_id text, document_id text, embedding_profile_id text, external_processing_eligible boolean, generation_id text, heading_path text[], locator jsonb, candidate_owner_user_id text, policy_version bigint, sanitized_display_name text, scope_claim_id text, session_id text, source_id text, source_revision_id text, source_scope text, citation_title text, retrieval_topics text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_query_embedding IS NULL
     OR vector_dims(p_query_embedding) <> 1024
     OR vector_norm(p_query_embedding)::text IN ('NaN', 'Infinity', '-Infinity')
     OR abs(vector_norm(p_query_embedding)::double precision - 1.0) > 0.00001
     OR (
       p_owner_query_embedding IS NOT NULL
       AND (
         vector_dims(p_owner_query_embedding) <> 1024
         OR vector_norm(p_owner_query_embedding)::text IN ('NaN', 'Infinity', '-Infinity')
         OR abs(vector_norm(p_owner_query_embedding)::double precision - 1.0) > 0.00001
       )
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 dense retrieval arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH scope AS (
    SELECT *
    FROM public.resolve_rag_v2_retrieval_scope_v2(p_scope_claim_id, p_owner_user_id, p_session_id)
  ), candidates AS (
    SELECT
      rows.*,
      embedding.embedding <=> CASE
        WHEN membership.component_scope = 'OWNER_PRIVATE' THEN p_owner_query_embedding
        ELSE p_query_embedding
      END AS dense_distance
    FROM scope
    JOIN public.rag_v2_immutable_generation_memberships AS membership
      ON membership.component_generation_id = ANY(
        ARRAY[
          scope.exact30_generation_id,
          scope.oa112_generation_id,
          scope.owner_private_generation_id
        ]::text[]
      )
    JOIN public.rag_v2_immutable_chunks AS chunk
      ON chunk.chunk_id = membership.chunk_id
     AND chunk.source_revision_id = membership.source_revision_id
     AND chunk.source_scope = membership.component_scope
     AND chunk.owner_partition_key = membership.owner_partition_key
    JOIN public.rag_v2_immutable_source_revisions AS source
      ON source.source_revision_id = membership.source_revision_id
     AND source.source_scope = membership.component_scope
     AND source.owner_partition_key = membership.owner_partition_key
    JOIN public.rag_v2_immutable_generation_embeddings AS embedding
      ON embedding.component_generation_id = membership.component_generation_id
     AND embedding.chunk_id = membership.chunk_id
     AND embedding.component_scope = membership.component_scope
     AND embedding.owner_partition_key = membership.owner_partition_key
     AND embedding.embedding_profile_id = CASE
       WHEN membership.component_scope = 'OWNER_PRIVATE' THEN scope.owner_embedding_profile_id
       ELSE scope.embedding_profile_id
     END
    CROSS JOIN LATERAL (
      SELECT
        chunk.canonical_text AS canonical_content,
        chunk.canonical_text_sha256 AS canonical_content_sha256,
        source.canonical_https_url,
        chunk.chunk_id,
        source.document_id,
        CASE
          WHEN source.source_scope = 'OWNER_PRIVATE' THEN scope.owner_embedding_profile_id
          ELSE scope.embedding_profile_id
        END AS embedding_profile_id,
        source.external_processing_eligible,
        membership.component_generation_id AS generation_id,
        chunk.heading_path,
        chunk.locator,
        source.owner_user_id AS candidate_owner_user_id,
        scope.policy_version,
        source.sanitized_display_name,
        scope.scope_claim_id,
        scope.session_id,
        source.source_id,
        source.source_revision_id,
        source.source_scope,
        source.citation_title,
        source.retrieval_topics
    ) AS rows
    WHERE p_topics <@ scope.allowed_topics
      AND source.retrieval_topics && p_topics
      AND (source.source_scope <> 'OWNER_PRIVATE' OR p_owner_query_embedding IS NOT NULL)
      AND (
        (
          source.source_scope IN ('EXACT30', 'OA112')
          AND source.owner_user_id IS NULL
          AND source.citation_title IS NOT NULL
          AND source.sanitized_display_name IS NULL
          AND public.rag_v2_immutable_public_https_url_is_valid(source.canonical_https_url)
        )
        OR (
          source.source_scope = 'OWNER_PRIVATE'
          AND source.owner_user_id = scope.owner_user_id
          AND source.citation_title IS NULL
          AND source.sanitized_display_name IS NOT NULL
          AND source.canonical_https_url IS NULL
        )
      )
      AND (
        source.source_scope <> 'OA112'
        OR EXISTS (
          SELECT 1
          FROM public.rag_v2_immutable_oa_source_cards AS card
          WHERE card.source_revision_id = source.source_revision_id
            AND card.source_id = source.source_id
            AND card.active_oa112_eligible
            AND card.canonical_https_url = source.canonical_https_url
        )
      )
  ), ranked AS (
    SELECT
      candidates.*,
      rank() OVER (
        PARTITION BY embedding_profile_id
        ORDER BY dense_distance
      )::integer AS profile_rank
    FROM candidates
    WHERE dense_distance <= 0.55
  )
  SELECT
    row_number() OVER (
      ORDER BY profile_rank, (source_scope = 'OWNER_PRIVATE') DESC,
               source_id COLLATE "C", chunk_id COLLATE "C"
    )::integer,
    canonical_content,
    canonical_content_sha256,
    canonical_https_url,
    chunk_id,
    document_id,
    embedding_profile_id,
    external_processing_eligible,
    generation_id,
    heading_path,
    locator,
    candidate_owner_user_id,
    policy_version,
    sanitized_display_name,
    scope_claim_id,
    session_id,
    source_id,
    source_revision_id,
    source_scope,
    citation_title,
    retrieval_topics
  FROM ranked
  ORDER BY profile_rank, (source_scope = 'OWNER_PRIVATE') DESC,
           source_id COLLATE "C", chunk_id COLLATE "C"
  LIMIT 30;
END;
$$;


ALTER FUNCTION public.search_authorized_rag_v2_dense_v2(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_embedding public.vector, p_owner_query_embedding public.vector) OWNER TO flyway;


CREATE FUNCTION public.search_authorized_rag_v2_exact(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_identifiers text[]) RETURNS TABLE(rank_no integer, canonical_content text, canonical_content_sha256 text, canonical_https_url text, chunk_id text, document_id text, embedding_profile_id text, external_processing_eligible boolean, generation_id text, heading_path text[], locator jsonb, candidate_owner_user_id text, policy_version bigint, sanitized_display_name text, scope_claim_id text, session_id text, source_id text, source_revision_id text, source_scope text, citation_title text, retrieval_topics text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_identifiers IS NULL
     OR cardinality(p_identifiers) NOT BETWEEN 1 AND 20
     OR cardinality(ARRAY(SELECT DISTINCT identifier FROM unnest(p_identifiers) AS values(identifier))) <> cardinality(p_identifiers)
     OR EXISTS (
       SELECT 1
       FROM unnest(p_identifiers) AS values(identifier)
       WHERE char_length(identifier) NOT BETWEEN 1 AND 256
          OR identifier ~ '[[:cntrl:]]'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 exact retrieval arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH candidates AS (
    SELECT *
    FROM public.authorized_rag_v2_retrieval_rows(
      p_scope_claim_id, p_owner_user_id, p_session_id, p_topics
    )
  ), matched AS (
    SELECT
      candidate.*,
      min(
        CASE
          WHEN candidate.source_id = identifier THEN 0
          WHEN lower(coalesce(candidate.citation_title, candidate.sanitized_display_name, '')) = lower(identifier) THEN 1
          ELSE 2
        END
      ) AS match_kind
    FROM candidates AS candidate
    JOIN unnest(p_identifiers) AS values(identifier)
      ON candidate.source_id = identifier
      OR lower(coalesce(candidate.citation_title, candidate.sanitized_display_name, '')) = lower(identifier)
      OR strpos(lower(candidate.canonical_content), lower(identifier)) > 0
    GROUP BY
      candidate.canonical_content,
      candidate.canonical_content_sha256,
      candidate.canonical_https_url,
      candidate.chunk_id,
      candidate.document_id,
      candidate.embedding_profile_id,
      candidate.external_processing_eligible,
      candidate.generation_id,
      candidate.heading_path,
      candidate.locator,
      candidate.candidate_owner_user_id,
      candidate.policy_version,
      candidate.sanitized_display_name,
      candidate.scope_claim_id,
      candidate.session_id,
      candidate.source_id,
      candidate.source_revision_id,
      candidate.source_scope,
      candidate.citation_title,
      candidate.retrieval_topics
  )
  SELECT
    row_number() OVER (
      ORDER BY match_kind, source_id COLLATE "C", chunk_id COLLATE "C"
    )::integer,
    canonical_content,
    canonical_content_sha256,
    canonical_https_url,
    chunk_id,
    document_id,
    embedding_profile_id,
    external_processing_eligible,
    generation_id,
    heading_path,
    locator,
    candidate_owner_user_id,
    policy_version,
    sanitized_display_name,
    scope_claim_id,
    session_id,
    source_id,
    source_revision_id,
    source_scope,
    citation_title,
    retrieval_topics
  FROM matched
  ORDER BY match_kind, source_id COLLATE "C", chunk_id COLLATE "C"
  LIMIT 30;
END;
$$;


ALTER FUNCTION public.search_authorized_rag_v2_exact(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_identifiers text[]) OWNER TO flyway;


CREATE FUNCTION public.search_authorized_rag_v2_lexical(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_text text) RETURNS TABLE(rank_no integer, canonical_content text, canonical_content_sha256 text, canonical_https_url text, chunk_id text, document_id text, embedding_profile_id text, external_processing_eligible boolean, generation_id text, heading_path text[], locator jsonb, candidate_owner_user_id text, policy_version bigint, sanitized_display_name text, scope_claim_id text, session_id text, source_id text, source_revision_id text, source_scope text, citation_title text, retrieval_topics text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_query'
     OR p_query_text IS NULL
     OR octet_length(p_query_text) NOT BETWEEN 1 AND 12288
     OR p_query_text ~ '[[:cntrl:]]' THEN
    RAISE EXCEPTION 'immutable RAG v2 lexical retrieval arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH candidates AS (
    SELECT *
    FROM public.authorized_rag_v2_retrieval_rows(
      p_scope_claim_id, p_owner_user_id, p_session_id, p_topics
    )
  ), scored AS (
    SELECT
      candidate.*,
      similarity(
        lower(concat_ws(' ', candidate.source_id, candidate.citation_title, candidate.sanitized_display_name, candidate.canonical_content)),
        lower(p_query_text)
      ) AS lexical_score
    FROM candidates AS candidate
  )
  SELECT
    row_number() OVER (
      ORDER BY lexical_score DESC, source_id COLLATE "C", chunk_id COLLATE "C"
    )::integer,
    canonical_content,
    canonical_content_sha256,
    canonical_https_url,
    chunk_id,
    document_id,
    embedding_profile_id,
    external_processing_eligible,
    generation_id,
    heading_path,
    locator,
    candidate_owner_user_id,
    policy_version,
    sanitized_display_name,
    scope_claim_id,
    session_id,
    source_id,
    source_revision_id,
    source_scope,
    citation_title,
    retrieval_topics
  FROM scored
  WHERE lexical_score >= 0.05
  ORDER BY lexical_score DESC, source_id COLLATE "C", chunk_id COLLATE "C"
  LIMIT 30;
END;
$$;


ALTER FUNCTION public.search_authorized_rag_v2_lexical(p_scope_claim_id text, p_owner_user_id text, p_session_id text, p_topics text[], p_query_text text) OWNER TO flyway;


CREATE FUNCTION public.settle_s4_9_google_grounding_budget(p_owner_user_id text, p_reservation_id text, p_outcome text, p_actual_query_count integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  reservation public.s4_9_google_grounding_reservations%ROWTYPE;
  applied_count integer;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_outcome NOT IN ('COMMITTED','UNKNOWN_BILLING','RELEASED') THEN
    RAISE EXCEPTION 'S4.9 Google budget settlement is invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO reservation FROM public.s4_9_google_grounding_reservations
  WHERE reservation_id = p_reservation_id AND owner_user_id = p_owner_user_id FOR UPDATE;
  IF NOT FOUND OR reservation.state <> 'RESERVED' THEN
    RAISE EXCEPTION 'S4.9 Google reservation is unavailable' USING ERRCODE = '55000';
  END IF;
  IF p_outcome = 'COMMITTED' AND p_actual_query_count NOT BETWEEN 0 AND 128 THEN
    RAISE EXCEPTION 'S4.9 actual query count is invalid' USING ERRCODE = '22023';
  END IF;
  applied_count := CASE WHEN p_outcome = 'UNKNOWN_BILLING' THEN reservation.reserved_query_count
                        WHEN p_outcome = 'RELEASED' THEN 0 ELSE p_actual_query_count END;
  UPDATE public.s4_9_google_grounding_monthly_budget
  SET reserved_query_count = reserved_query_count - reservation.reserved_query_count,
      observed_query_count = observed_query_count + CASE WHEN p_outcome = 'COMMITTED' THEN applied_count ELSE 0 END,
      unknown_query_count = unknown_query_count + CASE WHEN p_outcome = 'UNKNOWN_BILLING' THEN applied_count ELSE 0 END,
      updated_at = transaction_timestamp()
  WHERE billing_account_fingerprint = reservation.billing_account_fingerprint
    AND billing_period_start = reservation.billing_period_start;
  UPDATE public.s4_9_google_grounding_reservations
  SET state = p_outcome, actual_query_count = applied_count, completed_at = transaction_timestamp()
  WHERE reservation_id = p_reservation_id;
END
$$;


ALTER FUNCTION public.settle_s4_9_google_grounding_budget(p_owner_user_id text, p_reservation_id text, p_outcome text, p_actual_query_count integer) OWNER TO flyway;


CREATE FUNCTION public.stage_p1_synthetic_async_request(p_mode text, p_partition_key text, p_run_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
#variable_conflict use_column
DECLARE target_job_id text; target_event_id text; payload jsonb; existing_job public.async_job%ROWTYPE;
  existing_event public.event_outbox%ROWTYPE;
BEGIN
  IF session_user <> 'decision_demo' OR p_mode NOT IN ('DB','KAFKA')
     OR p_partition_key !~ '^hmac-sha256:[0-9a-f]{64}$'
     OR p_run_id !~ '^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'P1 synthetic async staging denied' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.p1_offline_demo_authority authority
    WHERE authority.authority_id='P1_OFFLINE_DEMO' AND authority.active
  ) THEN
    RAISE EXCEPTION 'P1 offline demo authority inactive' USING ERRCODE='42501';
  END IF;
  target_job_id:='job_p1_container_'||lower(p_mode)||'_'||p_run_id;
  target_event_id:='evt_p1_container_'||lower(p_mode)||'_'||p_run_id;
  payload:=jsonb_build_object(
    'jobId',target_job_id,
    'ownerRef','usr_demo_user',
    'artifactId','artifact_s8_0ed32aac66088e495ae853bb',
    'contentHash','sha256:0ed32aac66088e495ae853bbac98a35b2c4a22420138bdd58dcdbbb0d9d8ad02'
  );
  PERFORM pg_advisory_xact_lock(hashtextextended('p1-synthetic-async-'||p_mode,8601));
  SELECT * INTO existing_job FROM public.async_job item WHERE item.job_id=target_job_id;
  SELECT * INTO existing_event FROM public.event_outbox item WHERE item.event_id=target_event_id;
  IF existing_event.event_id IS NOT NULL OR existing_job.job_id IS NOT NULL THEN
    IF existing_job.job_id=target_job_id AND existing_job.job_type='ARTIFACT_INGEST'
       AND existing_job.requested_by='usr_demo_user' AND existing_job.payload_json=payload
       AND existing_event.event_id=target_event_id AND existing_event.event_type='artifact.ingest-requested.v1'
       AND existing_event.aggregate_type='ASYNC_JOB' AND existing_event.aggregate_id=target_job_id
       AND existing_event.partition_key=p_partition_key AND existing_event.payload_json=payload
       AND existing_event.schema_version='1.0.0' THEN RETURN target_job_id; END IF;
    RAISE EXCEPTION 'P1 synthetic async identity conflict' USING ERRCODE='23505';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users actor WHERE actor.user_id='usr_demo_user' AND actor.status='ACTIVE') THEN
    RAISE EXCEPTION 'P1 synthetic owner unavailable' USING ERRCODE='55000';
  END IF;
  INSERT INTO public.async_job(job_id,job_type,status,requested_by,payload_json,next_attempt_at)
  VALUES (target_job_id,'ARTIFACT_INGEST','REQUESTED','usr_demo_user',payload,statement_timestamp());
  INSERT INTO public.event_outbox(
    event_id,event_type,aggregate_type,aggregate_id,partition_key,payload_json,schema_version,next_attempt_at
  ) VALUES (
    target_event_id,'artifact.ingest-requested.v1','ASYNC_JOB',target_job_id,p_partition_key,payload,'1.0.0',statement_timestamp()
  );
  RETURN target_job_id;
END
$_$;


ALTER FUNCTION public.stage_p1_synthetic_async_request(p_mode text, p_partition_key text, p_run_id text) OWNER TO flyway;


CREATE FUNCTION public.stage_rag_v2_immutable_external_exact30_voyage_document(p_payload jsonb) RETURNS TABLE(component_generation_id text, materialization_run_id text, state text, source_reused boolean, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  payload_scope text;
  payload_generation_id text;
  payload_run_id text;
  payload_generation_hash text;
  payload_manifest_hash text;
  payload_expected_source_count integer;
  payload_expected_chunk_count integer;
  payload_member_digests text[];
  payload_source_member_digest text;
  computed_manifest_hash text;
  computed_generation_hash text;
  payload_source jsonb;
  payload_document_id text;
  payload_source_id text;
  payload_source_revision_id text;
  payload_source_revision_sha256 text;
  payload_raw_content_sha256 text;
  payload_normalized_document_ir_sha256 text;
  payload_canonical_text_sha256 text;
  payload_canonical_text text;
  payload_mime_type text;
  payload_parser_version text;
  payload_tokenizer_version text;
  payload_document_ir jsonb;
  payload_source_locator jsonb;
  payload_canonical_https_url text;
  payload_source_card_sha256 text;
  payload_machine_fetch_allowed boolean;
  payload_local_processing_allowed boolean;
  payload_external_embedding_allowed boolean;
  payload_external_generation_allowed boolean;
  payload_external_processing_eligible boolean;
  payload_citation_title text;
  payload_topics text[];
  payload_chunk jsonb;
  payload_embedding jsonb;
  payload_chunk_id text;
  payload_chunk_ordinal integer;
  payload_chunk_text text;
  payload_chunk_sha256 text;
  payload_chunk_locator jsonb;
  payload_chunk_heading_path text[];
  payload_chunk_token_count integer;
  payload_chunk_contains_table boolean;
  payload_embedding_input_hash text;
  payload_context_set_hash text;
  payload_embedding_vector vector(1024);
  cached_embedding_vector vector(1024);
  existing_embedding_input_hash text;
  existing_context_set_hash text;
  expected_source_record public.rag_v2_immutable_source_revisions%ROWTYPE;
  expected_generation_record public.rag_v2_immutable_component_generations%ROWTYPE;
  expected_manifest_record public.rag_v2_immutable_external_exact30_voyage_component_manifests%ROWTYPE;
  existing_run_state text;
  observed_chunk_count integer := 0;
  observed_embedding_count integer := 0;
  observed_source_text text := '';
  first_chunk_locator jsonb;
  expected_context_set_hash text;
  observed_source_total integer := 0;
  observed_chunk_total integer := 0;
  existing_membership_count integer := 0;
  existing_component_membership_count integer := 0;
  reused_embedding_count integer := 0;
  source_was_reused boolean := false;
  embedding_was_reused boolean := false;
  complete_state text := 'STAGING';
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) NOT BETWEEN 2 AND 16777216
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_payload) AS root_key
       WHERE root_key NOT IN (
         'componentGenerationId', 'componentScope', 'embeddingProfileId', 'expectedChunkCount',
         'expectedSourceCount', 'generationHash', 'manifestHash', 'materializationRunId',
         'memberDigests', 'schemaVersion', 'source'
       )
     )
     OR NOT (p_payload ?& ARRAY[
       'componentGenerationId', 'componentScope', 'embeddingProfileId', 'expectedChunkCount',
       'expectedSourceCount', 'generationHash', 'manifestHash', 'materializationRunId',
       'memberDigests', 'schemaVersion', 'source'
     ])
     OR jsonb_typeof(p_payload -> 'schemaVersion') <> 'number'
     OR p_payload ->> 'schemaVersion' <> '1'
     OR jsonb_typeof(p_payload -> 'componentGenerationId') <> 'string'
     OR jsonb_typeof(p_payload -> 'componentScope') <> 'string'
     OR jsonb_typeof(p_payload -> 'embeddingProfileId') <> 'string'
     OR jsonb_typeof(p_payload -> 'generationHash') <> 'string'
     OR jsonb_typeof(p_payload -> 'manifestHash') <> 'string'
     OR jsonb_typeof(p_payload -> 'materializationRunId') <> 'string'
     OR p_payload ->> 'embeddingProfileId' <> 'voyage_context_4_1024_v1'
     OR jsonb_typeof(p_payload -> 'expectedSourceCount') <> 'number'
     OR jsonb_typeof(p_payload -> 'expectedChunkCount') <> 'number'
     OR (p_payload -> 'expectedSourceCount')::text !~ '^(0|[1-9][0-9]*)$'
     OR (p_payload -> 'expectedChunkCount')::text !~ '^(0|[1-9][0-9]*)$'
     OR jsonb_typeof(p_payload -> 'memberDigests') <> 'array'
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_payload -> 'memberDigests') AS digest_item(value)
       WHERE jsonb_typeof(digest_item.value) <> 'string'
     )
     OR jsonb_typeof(p_payload -> 'source') <> 'object' THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage staging arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  payload_scope := p_payload ->> 'componentScope';
  payload_generation_id := p_payload ->> 'componentGenerationId';
  payload_run_id := p_payload ->> 'materializationRunId';
  payload_generation_hash := p_payload ->> 'generationHash';
  payload_manifest_hash := p_payload ->> 'manifestHash';
  payload_expected_source_count := (p_payload ->> 'expectedSourceCount')::integer;
  payload_expected_chunk_count := (p_payload ->> 'expectedChunkCount')::integer;
  SELECT coalesce(array_agg(digest_item.value ORDER BY digest_item.ordinality), ARRAY[]::text[])
  INTO payload_member_digests
  FROM jsonb_array_elements_text(p_payload -> 'memberDigests') WITH ORDINALITY AS digest_item(value, ordinality);
  payload_source := p_payload -> 'source';
  IF payload_scope <> 'EXACT30'
     OR payload_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR payload_run_id !~ '^rgr_run_[0-9a-f]{32}$'
     OR payload_generation_hash !~ '^[0-9a-f]{64}$'
     OR payload_manifest_hash !~ '^[0-9a-f]{64}$'
     OR payload_expected_source_count <> 30
     OR payload_expected_chunk_count < payload_expected_source_count
     OR payload_expected_chunk_count > 100000
     OR cardinality(payload_member_digests) <> 30
     OR array_position(payload_member_digests, NULL) IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM unnest(payload_member_digests) AS member_digest
       WHERE member_digest !~ '^[0-9a-f]{64}$'
     )
     OR cardinality(payload_member_digests) <> (
       SELECT count(DISTINCT member_digest) FROM unnest(payload_member_digests) AS member_digest
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage component identity is invalid'
      USING ERRCODE = '22023';
  END IF;
  computed_manifest_hash := public.rag_v2_immutable_external_exact30_voyage_manifest_hash(
    payload_member_digests
  );
  computed_generation_hash := public.rag_v2_immutable_external_exact30_voyage_generation_hash(
    payload_expected_source_count, payload_expected_chunk_count, computed_manifest_hash
  );
  IF payload_manifest_hash <> computed_manifest_hash
     OR payload_generation_hash <> computed_generation_hash
     OR payload_generation_id <> 'rgr_' || substr(computed_generation_hash, 1, 32)
     OR payload_run_id <> 'rgr_run_' || substr(
       encode(digest(
         'rag-v2-external-exact30-voyage-run|' || payload_generation_id || '|' || payload_manifest_hash,
         'sha256'
       ), 'hex'),
       1,
       32
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage component hash binding is invalid'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
       SELECT 1 FROM jsonb_object_keys(payload_source) AS source_key
       WHERE source_key NOT IN (
         'accessEvidenceSha256', 'canonicalHttpsUrl', 'canonicalText', 'canonicalTextSha256',
         'chunks', 'citationTitle', 'documentId', 'documentIr', 'embeddings',
         'externalEmbeddingAllowed', 'externalGenerationAllowed', 'externalProcessingEligible',
         'licenseEvidenceSha256', 'localProcessingAllowed', 'machineFetchAllowed', 'mimeType',
         'oaSourceCard', 'oaTrackId', 'parserVersion', 'rawContentSha256', 'retrievalTopics',
         'sourceCardSha256', 'sourceId', 'sourceLocator', 'sourceRevisionId', 'sourceRevisionSha256',
         'tokenizerVersion'
       )
     )
     OR NOT (payload_source ?& ARRAY[
       'accessEvidenceSha256', 'canonicalHttpsUrl', 'canonicalText', 'canonicalTextSha256',
       'chunks', 'citationTitle', 'documentId', 'documentIr', 'embeddings',
       'externalEmbeddingAllowed', 'externalGenerationAllowed', 'externalProcessingEligible',
       'licenseEvidenceSha256', 'localProcessingAllowed', 'machineFetchAllowed', 'mimeType',
       'oaSourceCard', 'oaTrackId', 'parserVersion', 'rawContentSha256', 'retrievalTopics',
       'sourceCardSha256', 'sourceId', 'sourceLocator', 'sourceRevisionId', 'sourceRevisionSha256',
       'tokenizerVersion'
     ])
     OR jsonb_typeof(payload_source -> 'documentIr') <> 'object'
     OR jsonb_typeof(payload_source -> 'documentId') <> 'string'
     OR jsonb_typeof(payload_source -> 'sourceId') <> 'string'
     OR jsonb_typeof(payload_source -> 'sourceRevisionId') <> 'string'
     OR jsonb_typeof(payload_source -> 'sourceRevisionSha256') <> 'string'
     OR jsonb_typeof(payload_source -> 'rawContentSha256') <> 'string'
     OR jsonb_typeof(payload_source -> 'canonicalTextSha256') <> 'string'
     OR jsonb_typeof(payload_source -> 'canonicalText') <> 'string'
     OR jsonb_typeof(payload_source -> 'mimeType') <> 'string'
     OR jsonb_typeof(payload_source -> 'parserVersion') <> 'string'
     OR jsonb_typeof(payload_source -> 'tokenizerVersion') <> 'string'
     OR jsonb_typeof(payload_source -> 'canonicalHttpsUrl') <> 'string'
     OR jsonb_typeof(payload_source -> 'citationTitle') <> 'string'
     OR jsonb_typeof(payload_source -> 'chunks') <> 'array'
     OR jsonb_typeof(payload_source -> 'embeddings') <> 'array'
     OR jsonb_typeof(payload_source -> 'retrievalTopics') <> 'array'
     OR jsonb_typeof(payload_source -> 'sourceLocator') <> 'object'
     OR jsonb_typeof(payload_source -> 'machineFetchAllowed') <> 'boolean'
     OR jsonb_typeof(payload_source -> 'localProcessingAllowed') <> 'boolean'
     OR jsonb_typeof(payload_source -> 'externalEmbeddingAllowed') <> 'boolean'
     OR jsonb_typeof(payload_source -> 'externalGenerationAllowed') <> 'boolean'
     OR jsonb_typeof(payload_source -> 'externalProcessingEligible') <> 'boolean'
     OR jsonb_typeof(payload_source -> 'sourceCardSha256') <> 'string'
     OR jsonb_typeof(payload_source -> 'oaTrackId') <> 'null'
     OR jsonb_typeof(payload_source -> 'oaSourceCard') <> 'null'
     OR jsonb_typeof(payload_source -> 'licenseEvidenceSha256') <> 'null'
     OR jsonb_typeof(payload_source -> 'accessEvidenceSha256') <> 'null'
     OR jsonb_array_length(payload_source -> 'chunks') NOT BETWEEN 1 AND 50000
     OR jsonb_array_length(payload_source -> 'embeddings') <> jsonb_array_length(payload_source -> 'chunks') THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage source payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  payload_document_id := payload_source ->> 'documentId';
  payload_source_id := payload_source ->> 'sourceId';
  payload_source_revision_id := payload_source ->> 'sourceRevisionId';
  payload_source_revision_sha256 := payload_source ->> 'sourceRevisionSha256';
  payload_raw_content_sha256 := payload_source ->> 'rawContentSha256';
  payload_normalized_document_ir_sha256 := payload_source -> 'documentIr' ->> 'normalizedContentSha256';
  payload_canonical_text_sha256 := payload_source ->> 'canonicalTextSha256';
  payload_canonical_text := payload_source ->> 'canonicalText';
  payload_mime_type := payload_source ->> 'mimeType';
  payload_parser_version := payload_source ->> 'parserVersion';
  payload_tokenizer_version := payload_source ->> 'tokenizerVersion';
  payload_document_ir := payload_source -> 'documentIr';
  payload_source_locator := payload_source -> 'sourceLocator';
  payload_canonical_https_url := payload_source ->> 'canonicalHttpsUrl';
  payload_source_card_sha256 := payload_source ->> 'sourceCardSha256';
  payload_machine_fetch_allowed := (payload_source ->> 'machineFetchAllowed')::boolean;
  payload_local_processing_allowed := (payload_source ->> 'localProcessingAllowed')::boolean;
  payload_external_embedding_allowed := (payload_source ->> 'externalEmbeddingAllowed')::boolean;
  payload_external_generation_allowed := (payload_source ->> 'externalGenerationAllowed')::boolean;
  payload_external_processing_eligible := (payload_source ->> 'externalProcessingEligible')::boolean;
  payload_citation_title := payload_source ->> 'citationTitle';
  SELECT coalesce(array_agg(topic.value ORDER BY topic.ordinality), ARRAY[]::text[])
  INTO payload_topics
  FROM jsonb_array_elements_text(payload_source -> 'retrievalTopics') WITH ORDINALITY AS topic(value, ordinality);
  IF payload_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
     OR payload_source_id !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
     OR payload_source_revision_id !~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'
     OR payload_source_revision_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_raw_content_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_normalized_document_ir_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_canonical_text_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_canonical_text IS NULL
     OR octet_length(payload_canonical_text) NOT BETWEEN 1 AND 16777216
     OR payload_canonical_text_sha256 <> encode(digest(payload_canonical_text, 'sha256'), 'hex')
     OR payload_mime_type IS NULL
     OR payload_parser_version IS NULL
     OR payload_tokenizer_version IS NULL
     OR char_length(payload_mime_type) NOT BETWEEN 3 AND 128
     OR char_length(payload_parser_version) NOT BETWEEN 1 AND 128
     OR char_length(payload_tokenizer_version) NOT BETWEEN 1 AND 128
     OR payload_citation_title IS NULL
     OR char_length(payload_citation_title) NOT BETWEEN 1 AND 500
     OR btrim(payload_citation_title) = ''
     OR payload_citation_title ~ '[[:cntrl:]]'
     OR public.rag_v2_immutable_retrieval_topics_are_valid(payload_topics) IS NOT TRUE
     OR public.rag_v2_immutable_locator_is_valid(payload_source_locator) IS NOT TRUE
     OR public.rag_v2_immutable_public_https_url_is_valid(payload_canonical_https_url) IS NOT TRUE
     OR payload_document_ir ->> 'sourceId' IS DISTINCT FROM payload_source_id
     OR payload_document_ir ->> 'sourceRevisionId' IS DISTINCT FROM payload_source_revision_id
     OR payload_document_ir ->> 'mimeType' IS DISTINCT FROM payload_mime_type
     OR payload_document_ir ->> 'rawContentSha256' IS DISTINCT FROM payload_raw_content_sha256
     OR payload_document_ir ->> 'normalizedContentSha256' IS DISTINCT FROM payload_normalized_document_ir_sha256
     OR payload_document_ir -> 'parserEvidence' ->> 'parserVersion' IS DISTINCT FROM payload_parser_version
     OR public.rag_v2_immutable_document_ir_structure_is_valid(payload_document_ir) IS NOT TRUE
     OR payload_machine_fetch_allowed
     OR NOT payload_local_processing_allowed
     OR NOT payload_external_embedding_allowed
     OR NOT payload_external_generation_allowed
     OR NOT payload_external_processing_eligible
     OR public.rag_v2_immutable_external_exact30_voyage_source_is_approved(
       payload_source_id,
       payload_canonical_https_url,
       payload_raw_content_sha256,
       payload_source_card_sha256
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage source metadata is invalid'
      USING ERRCODE = '22023';
  END IF;

  -- 전체 component lock과 source identity lock을 분리해 resume 때 서로 다른 generation이 같은
  -- S4.7C source/chunk cache를 동시에 새로 쓰는 race를 닫는다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-external-exact30-voyage|' || payload_generation_id, 0)
  );
  SELECT * INTO expected_generation_record
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = payload_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_component_generations (
      component_generation_id, owner_user_id, component_scope, embedding_profile_id, state,
      evaluation_status, expected_source_count, expected_chunk_count, actual_source_count,
      actual_chunk_count, generation_hash, manifest_hash
    ) VALUES (
      payload_generation_id, NULL, 'EXACT30', 'voyage_context_4_1024_v1', 'STAGING',
      'PENDING', 30, payload_expected_chunk_count, 0, 0,
      payload_generation_hash, payload_manifest_hash
    );
  ELSIF expected_generation_record.owner_user_id IS NOT NULL
     OR expected_generation_record.component_scope <> 'EXACT30'
     OR expected_generation_record.embedding_profile_id <> 'voyage_context_4_1024_v1'
     OR expected_generation_record.state <> 'STAGING'
     OR expected_generation_record.evaluation_status <> 'PENDING'
     OR expected_generation_record.expected_source_count <> 30
     OR expected_generation_record.expected_chunk_count <> payload_expected_chunk_count
     OR expected_generation_record.generation_hash <> payload_generation_hash
     OR expected_generation_record.manifest_hash <> payload_manifest_hash THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage component conflicts'
      USING ERRCODE = '23505';
  END IF;

  SELECT * INTO expected_manifest_record
  FROM public.rag_v2_immutable_external_exact30_voyage_component_manifests
  WHERE component_generation_id = payload_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_external_exact30_voyage_component_manifests (
      component_generation_id, component_scope, embedding_profile_id, member_digests,
      manifest_hash, generation_hash
    ) VALUES (
      payload_generation_id, 'EXACT30', 'voyage_context_4_1024_v1', payload_member_digests,
      payload_manifest_hash, payload_generation_hash
    );
  ELSIF expected_manifest_record.component_scope <> 'EXACT30'
     OR expected_manifest_record.embedding_profile_id <> 'voyage_context_4_1024_v1'
     OR expected_manifest_record.member_digests IS DISTINCT FROM payload_member_digests
     OR expected_manifest_record.manifest_hash <> payload_manifest_hash
     OR expected_manifest_record.generation_hash <> payload_generation_hash THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage member manifest conflicts'
      USING ERRCODE = '23505';
  END IF;

  SELECT run.state INTO existing_run_state
  FROM public.rag_v2_immutable_materialization_runs AS run
  WHERE run.materialization_run_id = payload_run_id
    AND run.owner_user_id IS NULL
    AND run.component_generation_id = payload_generation_id
    AND run.component_scope = 'EXACT30'
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_materialization_runs (
      materialization_run_id, owner_user_id, component_generation_id, component_scope, document_id, state
    ) VALUES (payload_run_id, NULL, payload_generation_id, 'EXACT30', NULL, 'OPEN');
  ELSIF existing_run_state NOT IN ('OPEN', 'STAGED') THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage run is not resumable'
      USING ERRCODE = '23505';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'rag-v2-immutable-external-exact30-voyage-source|' || payload_source_revision_id,
      0
    )
  );
  SELECT * INTO expected_source_record
  FROM public.rag_v2_immutable_source_revisions
  WHERE source_revision_id = payload_source_revision_id
  FOR UPDATE;
  IF FOUND THEN
    source_was_reused := true;
    IF expected_source_record.owner_user_id IS NOT NULL
       OR expected_source_record.document_id <> payload_document_id
       OR expected_source_record.source_id <> payload_source_id
       OR expected_source_record.source_scope <> 'EXACT30'
       OR expected_source_record.source_revision_sha256 <> payload_source_revision_sha256
       OR expected_source_record.raw_content_sha256 <> payload_raw_content_sha256
       OR expected_source_record.normalized_document_ir_sha256 <> payload_normalized_document_ir_sha256
       OR expected_source_record.canonical_text_sha256 <> payload_canonical_text_sha256
       OR expected_source_record.document_ir <> payload_document_ir
       OR expected_source_record.canonical_text <> payload_canonical_text
       OR expected_source_record.source_locator <> payload_source_locator
       OR expected_source_record.canonical_https_url <> payload_canonical_https_url
       OR expected_source_record.exact30_source_card_sha256 <> payload_source_card_sha256
       OR expected_source_record.license_evidence_sha256 IS NOT NULL
       OR expected_source_record.access_evidence_sha256 IS NOT NULL
       OR expected_source_record.mime_type <> payload_mime_type
       OR expected_source_record.machine_fetch_allowed
       OR NOT expected_source_record.local_processing_allowed
       OR NOT expected_source_record.external_embedding_allowed
       OR NOT expected_source_record.external_generation_allowed
       OR NOT expected_source_record.external_processing_eligible
       OR expected_source_record.parser_version <> payload_parser_version
       OR expected_source_record.tokenizer_version <> payload_tokenizer_version
       OR expected_source_record.retrieval_topics <> payload_topics
       OR expected_source_record.citation_title <> payload_citation_title
       OR expected_source_record.oa_track_id IS NOT NULL
       OR expected_source_record.reserve_source THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage source revision conflicts'
        USING ERRCODE = '23505';
    END IF;
  ELSE
    INSERT INTO public.rag_v2_immutable_source_revisions (
      source_revision_id, document_id, source_id, owner_user_id, source_scope, oa_track_id,
      reserve_source, source_revision_sha256, raw_content_sha256, normalized_document_ir_sha256,
      canonical_text_sha256, document_ir, canonical_text, sanitized_display_name, source_locator,
      canonical_https_url, exact30_source_card_sha256, license_evidence_sha256, access_evidence_sha256,
      mime_type, machine_fetch_allowed, local_processing_allowed, external_embedding_allowed,
      external_generation_allowed, external_processing_eligible, parser_version, tokenizer_version,
      retrieval_topics, citation_title
    ) VALUES (
      payload_source_revision_id, payload_document_id, payload_source_id, NULL, 'EXACT30', NULL,
      false, payload_source_revision_sha256, payload_raw_content_sha256, payload_normalized_document_ir_sha256,
      payload_canonical_text_sha256, payload_document_ir, payload_canonical_text, NULL, payload_source_locator,
      payload_canonical_https_url, payload_source_card_sha256, NULL, NULL,
      payload_mime_type, false, true, true, true, true, payload_parser_version, payload_tokenizer_version,
      payload_topics, payload_citation_title
    );
  END IF;

  -- chunk/embedding payload는 source-local deterministic order를 강제한다. one source의 context hash가
  -- 달라지면 same document group이 아닌 것으로 간주해 provider result를 stage하지 않는다.
  IF EXISTS (
       SELECT 1
       FROM jsonb_array_elements(payload_source -> 'chunks') AS entry(value)
       GROUP BY entry.value ->> 'chunkId'
       HAVING count(*) <> 1
     )
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(payload_source -> 'embeddings') AS entry(value)
       GROUP BY entry.value ->> 'chunkId'
       HAVING count(*) <> 1
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage chunk identity is duplicated'
      USING ERRCODE = '22023';
  END IF;

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    observed_chunk_count := observed_chunk_count + 1;
    IF jsonb_typeof(payload_chunk) <> 'object'
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(payload_chunk) AS chunk_key
         WHERE chunk_key NOT IN (
           'canonicalText', 'canonicalTextSha256', 'chunkId', 'chunkOrdinal',
           'containsTable', 'headingPath', 'locator', 'tokenCount'
         )
       )
       OR NOT (payload_chunk ?& ARRAY[
         'canonicalText', 'canonicalTextSha256', 'chunkId', 'chunkOrdinal',
         'containsTable', 'headingPath', 'locator', 'tokenCount'
       ])
       OR jsonb_typeof(payload_chunk -> 'headingPath') <> 'array'
       OR jsonb_typeof(payload_chunk -> 'locator') <> 'object'
       OR jsonb_typeof(payload_chunk -> 'chunkOrdinal') <> 'number'
       OR jsonb_typeof(payload_chunk -> 'containsTable') <> 'boolean'
       OR jsonb_typeof(payload_chunk -> 'tokenCount') <> 'number'
       OR (payload_chunk -> 'chunkOrdinal')::text !~ '^(0|[1-9][0-9]*)$'
       OR (payload_chunk -> 'tokenCount')::text !~ '^(0|[1-9][0-9]*)$'
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(payload_chunk -> 'headingPath') AS heading(value)
         WHERE jsonb_typeof(heading.value) <> 'string'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage chunk is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_chunk_id := payload_chunk ->> 'chunkId';
    payload_chunk_ordinal := (payload_chunk ->> 'chunkOrdinal')::integer;
    payload_chunk_text := payload_chunk ->> 'canonicalText';
    payload_chunk_sha256 := payload_chunk ->> 'canonicalTextSha256';
    payload_chunk_locator := payload_chunk -> 'locator';
    payload_chunk_token_count := (payload_chunk ->> 'tokenCount')::integer;
    payload_chunk_contains_table := (payload_chunk ->> 'containsTable')::boolean;
    SELECT coalesce(array_agg(heading.value ORDER BY heading.ordinality), ARRAY[]::text[])
    INTO payload_chunk_heading_path
    FROM jsonb_array_elements_text(payload_chunk -> 'headingPath') WITH ORDINALITY AS heading(value, ordinality);
    IF payload_chunk_id !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR payload_chunk_ordinal <> observed_chunk_count
       OR payload_chunk_text IS NULL
       OR payload_chunk_sha256 !~ '^[0-9a-f]{64}$'
       OR payload_chunk_sha256 <> encode(digest(payload_chunk_text, 'sha256'), 'hex')
       OR payload_chunk_token_count NOT BETWEEN 1 AND 600
       OR cardinality(payload_chunk_heading_path) > 12
       OR public.rag_v2_immutable_locator_is_valid(payload_chunk_locator) IS NOT TRUE THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage chunk contract is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF first_chunk_locator IS NULL THEN
      first_chunk_locator := payload_chunk_locator;
    END IF;
    IF observed_chunk_count = 1 THEN
      observed_source_text := payload_chunk_text;
    ELSE
      observed_source_text := observed_source_text || E'\n\n' || payload_chunk_text;
    END IF;
  END LOOP;
  IF first_chunk_locator IS NULL
     OR payload_source_locator <> first_chunk_locator
     OR payload_canonical_text <> observed_source_text THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage source projection is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF source_was_reused THEN
    IF EXISTS (
         SELECT 1
         FROM jsonb_array_elements(payload_source -> 'chunks') AS supplied(value)
         LEFT JOIN public.rag_v2_immutable_chunks AS stored
           ON stored.chunk_id = supplied.value ->> 'chunkId'
          AND stored.source_revision_id = payload_source_revision_id
          AND stored.owner_user_id IS NULL
          AND stored.source_scope = 'EXACT30'
         WHERE stored.chunk_id IS NULL
            OR stored.chunk_ordinal IS DISTINCT FROM (supplied.value ->> 'chunkOrdinal')::integer
            OR to_jsonb(stored.heading_path) IS DISTINCT FROM supplied.value -> 'headingPath'
            OR stored.locator IS DISTINCT FROM supplied.value -> 'locator'
            OR stored.canonical_text IS DISTINCT FROM supplied.value ->> 'canonicalText'
            OR stored.canonical_text_sha256 IS DISTINCT FROM supplied.value ->> 'canonicalTextSha256'
            OR stored.token_count IS DISTINCT FROM (supplied.value ->> 'tokenCount')::integer
            OR stored.contains_table IS DISTINCT FROM (supplied.value ->> 'containsTable')::boolean
       )
       OR (
         SELECT count(*)::integer
         FROM public.rag_v2_immutable_chunks AS stored
         WHERE stored.source_revision_id = payload_source_revision_id
           AND stored.owner_user_id IS NULL
           AND stored.source_scope = 'EXACT30'
       ) <> observed_chunk_count THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage source cache conflicts'
        USING ERRCODE = '23505';
    END IF;
  ELSE
    FOR payload_chunk IN
      SELECT value
      FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
      ORDER BY ordinality
    LOOP
      SELECT coalesce(array_agg(heading.value ORDER BY heading.ordinality), ARRAY[]::text[])
      INTO payload_chunk_heading_path
      FROM jsonb_array_elements_text(payload_chunk -> 'headingPath') WITH ORDINALITY AS heading(value, ordinality);
      INSERT INTO public.rag_v2_immutable_chunks (
        chunk_id, source_revision_id, owner_user_id, source_scope, chunk_ordinal, heading_path,
        locator, canonical_text, canonical_text_sha256, token_count, contains_table
      ) VALUES (
        payload_chunk ->> 'chunkId', payload_source_revision_id, NULL, 'EXACT30',
        (payload_chunk ->> 'chunkOrdinal')::integer, payload_chunk_heading_path,
        payload_chunk -> 'locator', payload_chunk ->> 'canonicalText', payload_chunk ->> 'canonicalTextSha256',
        (payload_chunk ->> 'tokenCount')::integer, (payload_chunk ->> 'containsTable')::boolean
      );
    END LOOP;
  END IF;

  SELECT count(*)::integer
  INTO existing_membership_count
  FROM public.rag_v2_immutable_generation_memberships AS membership
  WHERE membership.component_generation_id = payload_generation_id
    AND membership.source_revision_id = payload_source_revision_id
    AND membership.owner_user_id IS NULL
    AND membership.component_scope = 'EXACT30';
  SELECT count(*)::integer
  INTO existing_component_membership_count
  FROM public.rag_v2_immutable_generation_memberships AS membership
  WHERE membership.component_generation_id = payload_generation_id
    AND membership.component_scope = 'EXACT30';
  IF source_was_reused AND existing_membership_count > 0 THEN
    -- 이미 같은 generation에 완결된 source가 있으면 caller가 다른 vector를 덮어쓰지 못하게
    -- persisted hash projection만 재검증하고 idempotent receipt로 끝낸다.
    payload_source_member_digest := public.rag_v2_immutable_external_exact30_voyage_source_member_digest(
      payload_generation_id, payload_source_revision_id
    );
    IF payload_source_member_digest IS NULL
       OR array_position(payload_member_digests, payload_source_member_digest) IS NULL
       OR existing_membership_count <> observed_chunk_count
       OR (
         SELECT count(*)::integer
         FROM public.rag_v2_immutable_generation_embeddings AS embedding
         JOIN public.rag_v2_immutable_generation_memberships AS membership
           ON membership.component_generation_id = embedding.component_generation_id
          AND membership.chunk_id = embedding.chunk_id
          AND membership.component_scope = embedding.component_scope
         WHERE embedding.component_generation_id = payload_generation_id
           AND embedding.component_scope = 'EXACT30'
           AND membership.source_revision_id = payload_source_revision_id
       ) <> existing_membership_count
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(payload_source -> 'embeddings') AS supplied(value)
         LEFT JOIN public.rag_v2_immutable_generation_embeddings AS stored
           ON stored.component_generation_id = payload_generation_id
          AND stored.chunk_id = supplied.value ->> 'chunkId'
          AND stored.component_scope = 'EXACT30'
          AND stored.owner_user_id IS NULL
         WHERE stored.chunk_id IS NULL
            OR stored.embedding_input_hash IS DISTINCT FROM supplied.value ->> 'embeddingInputHash'
            OR stored.context_set_hash IS DISTINCT FROM supplied.value ->> 'contextSetHash'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage source resume conflicts'
        USING ERRCODE = '23505';
    END IF;
    SELECT count(DISTINCT membership.source_revision_id)::integer, count(*)::integer
    INTO observed_source_total, observed_chunk_total
    FROM public.rag_v2_immutable_generation_memberships AS membership
    WHERE membership.component_generation_id = payload_generation_id
      AND membership.component_scope = 'EXACT30';
    RETURN QUERY SELECT payload_generation_id, payload_run_id,
      CASE
        WHEN observed_source_total = payload_expected_source_count
          AND observed_chunk_total = payload_expected_chunk_count THEN 'STAGED'
        ELSE 'STAGING'
      END,
      true, observed_source_total, observed_chunk_total;
    RETURN;
  END IF;

  SELECT entry.value ->> 'contextSetHash'
  INTO expected_context_set_hash
  FROM jsonb_array_elements(payload_source -> 'embeddings') AS entry(value)
  WHERE entry.value ->> 'chunkId' = ((payload_source -> 'chunks') -> 0 ->> 'chunkId');
  IF expected_context_set_hash IS NULL
     OR expected_context_set_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage context group is invalid'
      USING ERRCODE = '22023';
  END IF;

  -- generation membership가 vector보다 먼저 존재해야 FK와 source-to-vector binding이 동시에 닫힌다.
  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    INSERT INTO public.rag_v2_immutable_generation_memberships (
      component_generation_id, chunk_id, source_revision_id, owner_user_id, component_scope, ordinal
    ) VALUES (
      payload_generation_id, payload_chunk ->> 'chunkId', payload_source_revision_id, NULL, 'EXACT30',
      existing_component_membership_count + (payload_chunk ->> 'chunkOrdinal')::integer
    );
  END LOOP;

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    observed_embedding_count := observed_embedding_count + 1;
    payload_chunk_id := payload_chunk ->> 'chunkId';
    SELECT entry.value INTO payload_embedding
    FROM jsonb_array_elements(payload_source -> 'embeddings') AS entry(value)
    WHERE entry.value ->> 'chunkId' = payload_chunk_id;
    IF payload_embedding IS NULL
       OR jsonb_typeof(payload_embedding) <> 'object'
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(payload_embedding) AS embedding_key
         WHERE embedding_key NOT IN ('chunkId', 'contextSetHash', 'embedding', 'embeddingInputHash')
       )
       OR NOT (payload_embedding ?& ARRAY['chunkId', 'contextSetHash', 'embedding', 'embeddingInputHash'])
       OR jsonb_typeof(payload_embedding -> 'chunkId') <> 'string'
       OR jsonb_typeof(payload_embedding -> 'contextSetHash') <> 'string'
       OR jsonb_typeof(payload_embedding -> 'embeddingInputHash') <> 'string'
       OR jsonb_typeof(payload_embedding -> 'embedding') <> 'array'
       OR jsonb_array_length(payload_embedding -> 'embedding') <> 1024
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(payload_embedding -> 'embedding') AS coordinate(value)
         WHERE jsonb_typeof(coordinate.value) <> 'number'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage embedding is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_embedding_input_hash := payload_embedding ->> 'embeddingInputHash';
    payload_context_set_hash := payload_embedding ->> 'contextSetHash';
    IF payload_embedding ->> 'chunkId' <> payload_chunk_id
       OR payload_embedding_input_hash !~ '^[0-9a-f]{64}$'
       OR payload_context_set_hash !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage embedding identity is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF payload_context_set_hash IS DISTINCT FROM expected_context_set_hash THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage context group drifted'
        USING ERRCODE = '23514';
    END IF;
    payload_embedding_vector := ((payload_embedding -> 'embedding')::text)::vector;
    IF vector_dims(payload_embedding_vector) <> 1024
       OR vector_norm(payload_embedding_vector)::text IN ('NaN', 'Infinity', '-Infinity')
       OR abs(vector_norm(payload_embedding_vector)::double precision - 1.0) > 0.00001 THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage vector is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.rag_v2_immutable_generation_memberships AS membership
      WHERE membership.component_generation_id = payload_generation_id
        AND membership.chunk_id = payload_chunk_id
        AND membership.source_revision_id = payload_source_revision_id
        AND membership.component_scope = 'EXACT30'
        AND membership.owner_user_id IS NULL
    ) THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage membership is invalid'
        USING ERRCODE = '22023';
    END IF;

    SELECT embedding.embedding_input_hash, embedding.context_set_hash
    INTO existing_embedding_input_hash, existing_context_set_hash
    FROM public.rag_v2_immutable_generation_embeddings AS embedding
    WHERE embedding.component_generation_id = payload_generation_id
      AND embedding.chunk_id = payload_chunk_id
      AND embedding.component_scope = 'EXACT30'
      AND embedding.owner_user_id IS NULL
    FOR SHARE;
    IF FOUND THEN
      IF existing_embedding_input_hash <> payload_embedding_input_hash
         OR existing_context_set_hash <> payload_context_set_hash THEN
        RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage embedding resume conflicts'
          USING ERRCODE = '23505';
      END IF;
    ELSE
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'rag-v2-immutable-external-exact30-voyage-cache|' || payload_chunk_id || '|' ||
          payload_embedding_input_hash || '|' || payload_context_set_hash,
          0
        )
      );
      embedding_was_reused := false;
      SELECT cache.embedding INTO cached_embedding_vector
      FROM public.rag_v2_immutable_embedding_cache AS cache
      WHERE cache.owner_user_id IS NULL
        AND cache.chunk_id = payload_chunk_id
        AND cache.source_scope = 'EXACT30'
        AND cache.embedding_profile_id = 'voyage_context_4_1024_v1'
        AND cache.embedding_input_hash = payload_embedding_input_hash
        AND cache.context_set_hash = payload_context_set_hash
      FOR SHARE;
      embedding_was_reused := FOUND;
      IF embedding_was_reused THEN
        payload_embedding_vector := cached_embedding_vector;
        reused_embedding_count := reused_embedding_count + 1;
      END IF;
      INSERT INTO public.rag_v2_immutable_generation_embeddings (
        component_generation_id, chunk_id, owner_user_id, component_scope, embedding_profile_id,
        embedding_input_hash, context_set_hash, embedding
      ) VALUES (
        payload_generation_id, payload_chunk_id, NULL, 'EXACT30', 'voyage_context_4_1024_v1',
        payload_embedding_input_hash, payload_context_set_hash, payload_embedding_vector
      );
      IF NOT embedding_was_reused THEN
        INSERT INTO public.rag_v2_immutable_embedding_cache (
          cache_id, owner_user_id, source_revision_id, chunk_id, source_scope, embedding_profile_id,
          embedding_input_hash, context_set_hash, embedding
        ) VALUES (
          'rgr_cache_' || substr(encode(digest(
            'rag-v2-immutable-external-exact30-voyage-cache|' || payload_generation_id || '|' || payload_chunk_id,
            'sha256'
          ), 'hex'), 1, 32),
          NULL, payload_source_revision_id, payload_chunk_id, 'EXACT30', 'voyage_context_4_1024_v1',
          payload_embedding_input_hash, payload_context_set_hash, payload_embedding_vector
        );
      END IF;
    END IF;

    INSERT INTO public.rag_v2_immutable_embedding_receipts (
      receipt_id, materialization_run_id, owner_user_id, source_scope, component_generation_id,
      chunk_id, embedding_profile_id, embedding_input_hash, context_set_hash, reuse_state
    ) VALUES (
      'rgr_emb_' || substr(encode(digest(
        'rag-v2-immutable-external-exact30-voyage-embedding-receipt|' || payload_run_id || '|' || payload_chunk_id,
        'sha256'
      ), 'hex'), 1, 32),
      payload_run_id, NULL, 'EXACT30', payload_generation_id, payload_chunk_id,
      'voyage_context_4_1024_v1', payload_embedding_input_hash, payload_context_set_hash,
      CASE WHEN embedding_was_reused THEN 'REUSED' ELSE 'NEW' END
    ) ON CONFLICT (receipt_id) DO NOTHING;
  END LOOP;

  -- Membership must exist before its embedding because the generation-embedding FK closes accidental
  -- vector insertion for a chunk not bound to this exact immutable source revision.
  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_generation_embeddings AS embedding
    LEFT JOIN public.rag_v2_immutable_generation_memberships AS membership
      ON membership.component_generation_id = embedding.component_generation_id
     AND membership.chunk_id = embedding.chunk_id
     AND membership.component_scope = embedding.component_scope
    WHERE embedding.component_generation_id = payload_generation_id
      AND embedding.component_scope = 'EXACT30'
      AND membership.chunk_id IS NULL
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage membership is missing'
      USING ERRCODE = '23514';
  END IF;

  IF observed_embedding_count <> observed_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage embedding count is invalid'
      USING ERRCODE = '22023';
  END IF;
  payload_source_member_digest := public.rag_v2_immutable_external_exact30_voyage_source_member_digest(
    payload_generation_id, payload_source_revision_id
  );
  IF payload_source_member_digest IS NULL
     OR array_position(payload_member_digests, payload_source_member_digest) IS NULL THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage source is outside the bound member manifest'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.rag_v2_immutable_source_receipts (
    receipt_id, materialization_run_id, owner_user_id, source_scope, source_revision_id,
    raw_content_sha256, canonical_text_sha256, reuse_state
  ) VALUES (
    'rgr_src_' || substr(encode(digest(
      'rag-v2-immutable-external-exact30-voyage-source-receipt|' || payload_run_id || '|' || payload_source_revision_id,
      'sha256'
    ), 'hex'), 1, 32),
    payload_run_id, NULL, 'EXACT30', payload_source_revision_id,
    payload_raw_content_sha256, payload_canonical_text_sha256,
    CASE WHEN source_was_reused THEN 'REUSED' ELSE 'NEW' END
  ) ON CONFLICT (receipt_id) DO NOTHING;
  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    INSERT INTO public.rag_v2_immutable_chunk_receipts (
      receipt_id, materialization_run_id, owner_user_id, source_scope, source_revision_id,
      chunk_id, canonical_text_sha256, reuse_state
    ) VALUES (
      'rgr_chk_' || substr(encode(digest(
        'rag-v2-immutable-external-exact30-voyage-chunk-receipt|' || payload_run_id || '|' ||
        (payload_chunk ->> 'chunkId'),
        'sha256'
      ), 'hex'), 1, 32),
      payload_run_id, NULL, 'EXACT30', payload_source_revision_id,
      payload_chunk ->> 'chunkId', payload_chunk ->> 'canonicalTextSha256',
      CASE WHEN source_was_reused THEN 'REUSED' ELSE 'NEW' END
    ) ON CONFLICT (receipt_id) DO NOTHING;
  END LOOP;

  UPDATE public.rag_v2_immutable_materialization_runs AS run
  SET source_reused_count = run.source_reused_count + CASE WHEN source_was_reused THEN 1 ELSE 0 END,
      chunk_reused_count = run.chunk_reused_count + CASE WHEN source_was_reused THEN observed_chunk_count ELSE 0 END,
      embedding_reused_count = run.embedding_reused_count + reused_embedding_count
  WHERE run.materialization_run_id = payload_run_id
    AND run.owner_user_id IS NULL
    AND run.component_scope = 'EXACT30'
    AND run.state = 'OPEN';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage reuse receipt transition failed'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(DISTINCT membership.source_revision_id)::integer, count(*)::integer
  INTO observed_source_total, observed_chunk_total
  FROM public.rag_v2_immutable_generation_memberships AS membership
  WHERE membership.component_generation_id = payload_generation_id
    AND membership.component_scope = 'EXACT30';
  IF observed_source_total > payload_expected_source_count
     OR observed_chunk_total > payload_expected_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage component exceeded exact membership'
      USING ERRCODE = '23514';
  END IF;
  UPDATE public.rag_v2_immutable_component_generations
  SET actual_source_count = observed_source_total,
      actual_chunk_count = observed_chunk_total
  WHERE component_generation_id = payload_generation_id
    AND owner_user_id IS NULL
    AND component_scope = 'EXACT30'
    AND embedding_profile_id = 'voyage_context_4_1024_v1'
    AND state = 'STAGING'
    AND evaluation_status = 'PENDING';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage component transition failed'
      USING ERRCODE = '23514';
  END IF;
  IF observed_source_total = payload_expected_source_count
     AND observed_chunk_total = payload_expected_chunk_count THEN
    IF public.rag_v2_immutable_external_exact30_voyage_component_hashes_are_valid(
      payload_generation_id
    ) IS NOT TRUE THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage component hash projection is invalid'
        USING ERRCODE = '23514';
    END IF;
    complete_state := 'STAGED';
    UPDATE public.rag_v2_immutable_materialization_runs
    SET state = 'STAGED'
    WHERE materialization_run_id = payload_run_id
      AND owner_user_id IS NULL
      AND component_scope = 'EXACT30'
      AND state = 'OPEN';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'immutable RAG v2 external exact-30 Voyage run transition failed'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN QUERY SELECT payload_generation_id, payload_run_id, complete_state,
    source_was_reused, observed_source_total, observed_chunk_total;
END;
$_$;


ALTER FUNCTION public.stage_rag_v2_immutable_external_exact30_voyage_document(p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.stage_rag_v2_immutable_owner_bge_document(p_owner_user_id text, p_ticket_id text, p_payload jsonb) RETURNS TABLE(component_generation_id text, materialization_run_id text, state text, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  payload_hash text;
  expected_generation_id text;
  expected_run_id text;
  expected_manifest_hash text;
  payload_document_id text;
  payload_source_id text;
  payload_source_revision_id text;
  payload_source_revision_sha256 text;
  payload_raw_content_sha256 text;
  payload_normalized_document_ir_sha256 text;
  payload_canonical_text_sha256 text;
  payload_canonical_text text;
  payload_mime_type text;
  payload_parser_version text;
  payload_tokenizer_version text;
  payload_document_ir jsonb;
  payload_source_locator jsonb;
  payload_chunk jsonb;
  payload_embedding jsonb;
  payload_chunk_id text;
  payload_chunk_ordinal integer;
  payload_chunk_text text;
  payload_chunk_sha256 text;
  payload_chunk_locator jsonb;
  payload_chunk_heading_path text[];
  payload_chunk_token_count integer;
  payload_chunk_contains_table boolean;
  payload_embedding_input_hash text;
  payload_embedding_vector vector(1024);
  stage_expected_chunk_count integer;
  observed_embedding_count integer := 0;
  observed_source_text text := '';
  first_chunk_locator jsonb;
  previous_state text;
  previous_source_count integer;
  previous_chunk_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_ticket_id !~ '^rti_[0-9a-f]{32}$'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) NOT BETWEEN 2 AND 16777216
     OR EXISTS (
       SELECT 1
       FROM jsonb_object_keys(p_payload) AS root_key
       WHERE root_key NOT IN (
         'canonicalText', 'canonicalTextSha256', 'chunks', 'documentId', 'documentIr',
         'embeddingProfileId', 'embeddings', 'mimeType', 'normalizedDocumentIrSha256',
         'parserVersion', 'rawContentSha256', 'schemaVersion', 'sourceId',
         'sourceLocator', 'sourceRevisionId', 'sourceRevisionSha256', 'tokenizerVersion'
       )
     )
     OR NOT (p_payload ?& ARRAY[
       'canonicalText', 'canonicalTextSha256', 'chunks', 'documentId', 'documentIr',
       'embeddingProfileId', 'embeddings', 'mimeType', 'normalizedDocumentIrSha256',
       'parserVersion', 'rawContentSha256', 'schemaVersion', 'sourceId',
       'sourceLocator', 'sourceRevisionId', 'sourceRevisionSha256', 'tokenizerVersion'
     ])
     OR jsonb_typeof(p_payload -> 'schemaVersion') <> 'number'
     OR p_payload ->> 'schemaVersion' <> '1'
     OR jsonb_typeof(p_payload -> 'embeddingProfileId') <> 'string'
     OR p_payload ->> 'embeddingProfileId' <> 'bge_m3_local_1024_v1'
     OR jsonb_typeof(p_payload -> 'documentIr') <> 'object'
     OR jsonb_typeof(p_payload -> 'chunks') <> 'array'
     OR jsonb_typeof(p_payload -> 'embeddings') <> 'array' THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  stage_expected_chunk_count := jsonb_array_length(p_payload -> 'chunks');
  IF stage_expected_chunk_count NOT BETWEEN 1 AND 50000
     OR jsonb_array_length(p_payload -> 'embeddings') <> stage_expected_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging cardinality is invalid'
      USING ERRCODE = '22023';
  END IF;

  payload_document_id := p_payload ->> 'documentId';
  payload_source_id := p_payload ->> 'sourceId';
  payload_source_revision_id := p_payload ->> 'sourceRevisionId';
  payload_source_revision_sha256 := p_payload ->> 'sourceRevisionSha256';
  payload_raw_content_sha256 := p_payload ->> 'rawContentSha256';
  payload_normalized_document_ir_sha256 := p_payload ->> 'normalizedDocumentIrSha256';
  payload_canonical_text_sha256 := p_payload ->> 'canonicalTextSha256';
  payload_canonical_text := p_payload ->> 'canonicalText';
  payload_mime_type := p_payload ->> 'mimeType';
  payload_parser_version := p_payload ->> 'parserVersion';
  payload_tokenizer_version := p_payload ->> 'tokenizerVersion';
  payload_document_ir := p_payload -> 'documentIr';
  payload_source_locator := p_payload -> 'sourceLocator';

  IF payload_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
     OR payload_source_id !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
     OR payload_source_revision_id !~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'
     OR payload_source_revision_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_raw_content_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_normalized_document_ir_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_canonical_text_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_canonical_text IS NULL
     OR octet_length(payload_canonical_text) NOT BETWEEN 1 AND 16777216
     OR payload_canonical_text_sha256 <> encode(digest(payload_canonical_text, 'sha256'), 'hex')
     OR payload_mime_type IS NULL
     OR payload_parser_version IS NULL
     OR payload_tokenizer_version IS NULL
     OR char_length(payload_mime_type) NOT BETWEEN 3 AND 128
     OR char_length(payload_parser_version) NOT BETWEEN 1 AND 128
     OR char_length(payload_tokenizer_version) NOT BETWEEN 1 AND 128
     OR NOT public.rag_v2_immutable_locator_is_valid(payload_source_locator)
     OR payload_document_ir ->> 'sourceId' IS DISTINCT FROM payload_source_id
     OR payload_document_ir ->> 'sourceRevisionId' IS DISTINCT FROM payload_source_revision_id
     OR payload_document_ir ->> 'mimeType' IS DISTINCT FROM payload_mime_type
     OR payload_document_ir ->> 'rawContentSha256' IS DISTINCT FROM payload_raw_content_sha256
     OR payload_document_ir ->> 'normalizedContentSha256' IS DISTINCT FROM payload_normalized_document_ir_sha256
     OR payload_document_ir -> 'parserEvidence' ->> 'parserVersion' IS DISTINCT FROM payload_parser_version
     OR public.rag_v2_immutable_document_ir_structure_is_valid(payload_document_ir) IS NOT TRUE THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.users AS owner
    WHERE owner.user_id = p_owner_user_id
      AND owner.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging owner is invalid'
      USING ERRCODE = '22023';
  END IF;

  -- 모든 owner-document writer와 delete는 동일 key로 직렬화한다. tombstone trigger도 같은
  -- lock을 다시 취하므로 stale resume은 commit 이후에만 명확히 거부된다.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'rag-v2-immutable-owner-document|' || p_owner_user_id || '|' || payload_document_id,
      0
    )
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);

  payload_hash := encode(digest(p_payload::text, 'sha256'), 'hex');
  expected_generation_id := 'rgr_' || substr(
    encode(digest('rag-v2-immutable-owner-generation|' || p_owner_user_id || '|' || payload_hash, 'sha256'), 'hex'),
    1,
    32
  );
  expected_run_id := 'rgr_run_' || substr(
    encode(digest('rag-v2-immutable-owner-run|' || p_owner_user_id || '|' || payload_hash, 'sha256'), 'hex'),
    1,
    32
  );
  expected_manifest_hash := encode(
    digest(
      'rag-v2-immutable-owner-manifest|' || payload_source_revision_sha256 || '|' ||
      payload_canonical_text_sha256 || '|' || stage_expected_chunk_count::text,
      'sha256'
    ),
    'hex'
  );

  SELECT run.state, generation.actual_source_count, generation.actual_chunk_count
  INTO previous_state, previous_source_count, previous_chunk_count
  FROM public.rag_v2_immutable_materialization_runs AS run
  JOIN public.rag_v2_immutable_component_generations AS generation
    ON generation.component_generation_id = run.component_generation_id
  WHERE run.materialization_run_id = expected_run_id
    AND run.owner_user_id = p_owner_user_id
    AND run.component_generation_id = expected_generation_id
    AND generation.generation_hash = payload_hash
    AND generation.manifest_hash = expected_manifest_hash;
  IF FOUND THEN
    IF previous_state = 'STAGED'
       AND previous_source_count = 1
       AND previous_chunk_count = stage_expected_chunk_count
       AND EXISTS (
         SELECT 1
         FROM public.rag_v2_immutable_import_tickets AS ticket
         WHERE ticket.ticket_hash = encode(digest(p_ticket_id, 'sha256'), 'hex')
           AND ticket.owner_user_id = p_owner_user_id
           AND ticket.state = 'CONSUMED'
           AND ticket.consumer_run_id = expected_run_id
       ) THEN
      RETURN QUERY SELECT expected_generation_id, expected_run_id, 'STAGED', 1, stage_expected_chunk_count;
      RETURN;
    END IF;
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging identity conflicts'
      USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.rag_v2_immutable_component_generations (
    component_generation_id,
    owner_user_id,
    component_scope,
    embedding_profile_id,
    state,
    evaluation_status,
    expected_source_count,
    expected_chunk_count,
    actual_source_count,
    actual_chunk_count,
    generation_hash,
    manifest_hash
  ) VALUES (
    expected_generation_id,
    p_owner_user_id,
    'OWNER_PRIVATE',
    'bge_m3_local_1024_v1',
    'STAGING',
    'PENDING',
    1,
    stage_expected_chunk_count,
    0,
    0,
    payload_hash,
    expected_manifest_hash
  );
  INSERT INTO public.rag_v2_immutable_materialization_runs (
    materialization_run_id,
    owner_user_id,
    component_generation_id,
    component_scope,
    document_id,
    state
  ) VALUES (
    expected_run_id,
    p_owner_user_id,
    expected_generation_id,
    'OWNER_PRIVATE',
    payload_document_id,
    'OPEN'
  );

  IF NOT public.consume_rag_v2_immutable_import_ticket(
    p_owner_user_id,
    p_ticket_id,
    'OWNER_IMPORT',
    'RAG_V2_OWNER_DOCUMENT_V1',
    expected_run_id
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging ticket was rejected'
      USING ERRCODE = '42501';
  END IF;

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(p_payload -> 'chunks') WITH ORDINALITY AS chunks(value, ordinal)
    ORDER BY ordinal
  LOOP
    IF jsonb_typeof(payload_chunk) <> 'object'
       OR EXISTS (
         SELECT 1
         FROM jsonb_object_keys(payload_chunk) AS chunk_key
         WHERE chunk_key NOT IN (
           'canonicalText', 'canonicalTextSha256', 'chunkId', 'chunkOrdinal',
           'containsTable', 'headingPath', 'locator', 'tokenCount'
         )
       )
       OR NOT (payload_chunk ?& ARRAY[
         'canonicalText', 'canonicalTextSha256', 'chunkId', 'chunkOrdinal',
         'containsTable', 'headingPath', 'locator', 'tokenCount'
       ])
       OR jsonb_typeof(payload_chunk -> 'headingPath') <> 'array'
       OR jsonb_typeof(payload_chunk -> 'locator') <> 'object'
       OR jsonb_typeof(payload_chunk -> 'containsTable') <> 'boolean'
       OR jsonb_typeof(payload_chunk -> 'tokenCount') <> 'number'
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(payload_chunk -> 'headingPath') AS heading(value)
         WHERE jsonb_typeof(heading.value) <> 'string'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 owner BGE staging chunk is invalid'
        USING ERRCODE = '22023';
    END IF;

    payload_chunk_id := payload_chunk ->> 'chunkId';
    payload_chunk_ordinal := (payload_chunk ->> 'chunkOrdinal')::integer;
    payload_chunk_text := payload_chunk ->> 'canonicalText';
    payload_chunk_sha256 := payload_chunk ->> 'canonicalTextSha256';
    payload_chunk_locator := payload_chunk -> 'locator';
    payload_chunk_token_count := (payload_chunk ->> 'tokenCount')::integer;
    payload_chunk_contains_table := (payload_chunk ->> 'containsTable')::boolean;
    SELECT coalesce(array_agg(heading.value ORDER BY heading.ordinality), ARRAY[]::text[])
    INTO payload_chunk_heading_path
    FROM jsonb_array_elements_text(payload_chunk -> 'headingPath') WITH ORDINALITY AS heading(value, ordinality);

    IF payload_chunk_id !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR payload_chunk_ordinal NOT BETWEEN 1 AND stage_expected_chunk_count
       OR payload_chunk_text IS NULL
       OR payload_chunk_sha256 !~ '^[0-9a-f]{64}$'
       OR payload_chunk_sha256 <> encode(digest(payload_chunk_text, 'sha256'), 'hex')
       OR payload_chunk_token_count NOT BETWEEN 1 AND 600
       OR cardinality(payload_chunk_heading_path) > 12
       OR NOT public.rag_v2_immutable_locator_is_valid(payload_chunk_locator) THEN
      RAISE EXCEPTION 'immutable RAG v2 owner BGE staging chunk contract is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF first_chunk_locator IS NULL THEN
      first_chunk_locator := payload_chunk_locator;
    END IF;
    IF payload_chunk_ordinal = 1 THEN
      observed_source_text := payload_chunk_text;
    ELSE
      observed_source_text := observed_source_text || E'\n\n' || payload_chunk_text;
    END IF;

  END LOOP;

  IF first_chunk_locator IS NULL
     OR payload_source_locator <> first_chunk_locator
     OR payload_canonical_text <> observed_source_text THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging source projection is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.rag_v2_immutable_source_revisions (
    source_revision_id,
    document_id,
    source_id,
    owner_user_id,
    source_scope,
    oa_track_id,
    reserve_source,
    source_revision_sha256,
    raw_content_sha256,
    normalized_document_ir_sha256,
    canonical_text_sha256,
    document_ir,
    canonical_text,
    sanitized_display_name,
    source_locator,
    canonical_https_url,
    license_evidence_sha256,
    access_evidence_sha256,
    mime_type,
    machine_fetch_allowed,
    local_processing_allowed,
    external_embedding_allowed,
    external_generation_allowed,
    external_processing_eligible,
    parser_version,
    tokenizer_version
  ) VALUES (
    payload_source_revision_id,
    payload_document_id,
    payload_source_id,
    p_owner_user_id,
    'OWNER_PRIVATE',
    NULL,
    false,
    payload_source_revision_sha256,
    payload_raw_content_sha256,
    payload_normalized_document_ir_sha256,
    payload_canonical_text_sha256,
    payload_document_ir,
    payload_canonical_text,
    NULL,
    payload_source_locator,
    NULL,
    NULL,
    NULL,
    payload_mime_type,
    false,
    true,
    false,
    false,
    false,
    payload_parser_version,
    payload_tokenizer_version
  );

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(p_payload -> 'chunks') WITH ORDINALITY AS chunks(value, ordinal)
    ORDER BY ordinal
  LOOP
    SELECT coalesce(array_agg(heading.value ORDER BY heading.ordinality), ARRAY[]::text[])
    INTO payload_chunk_heading_path
    FROM jsonb_array_elements_text(payload_chunk -> 'headingPath') WITH ORDINALITY AS heading(value, ordinality);
    INSERT INTO public.rag_v2_immutable_chunks (
      chunk_id,
      source_revision_id,
      owner_user_id,
      source_scope,
      chunk_ordinal,
      heading_path,
      locator,
      canonical_text,
      canonical_text_sha256,
      token_count,
      contains_table
    ) VALUES (
      payload_chunk ->> 'chunkId',
      payload_source_revision_id,
      p_owner_user_id,
      'OWNER_PRIVATE',
      (payload_chunk ->> 'chunkOrdinal')::integer,
      payload_chunk_heading_path,
      payload_chunk -> 'locator',
      payload_chunk ->> 'canonicalText',
      payload_chunk ->> 'canonicalTextSha256',
      (payload_chunk ->> 'tokenCount')::integer,
      (payload_chunk ->> 'containsTable')::boolean
    );
  END LOOP;

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(p_payload -> 'chunks') WITH ORDINALITY AS chunks(value, ordinal)
    ORDER BY ordinal
  LOOP
    INSERT INTO public.rag_v2_immutable_generation_memberships (
      component_generation_id,
      chunk_id,
      source_revision_id,
      owner_user_id,
      component_scope,
      ordinal
    ) VALUES (
      expected_generation_id,
      payload_chunk ->> 'chunkId',
      payload_source_revision_id,
      p_owner_user_id,
      'OWNER_PRIVATE',
      (payload_chunk ->> 'chunkOrdinal')::integer
    );
  END LOOP;

  FOR payload_embedding IN
    SELECT value
    FROM jsonb_array_elements(p_payload -> 'embeddings') WITH ORDINALITY AS embeddings(value, ordinal)
    ORDER BY ordinal
  LOOP
    IF jsonb_typeof(payload_embedding) <> 'object'
       OR EXISTS (
         SELECT 1
         FROM jsonb_object_keys(payload_embedding) AS embedding_key
         WHERE embedding_key NOT IN ('chunkId', 'embedding', 'embeddingInputHash')
       )
       OR NOT (payload_embedding ?& ARRAY['chunkId', 'embedding', 'embeddingInputHash'])
       OR jsonb_typeof(payload_embedding -> 'embedding') <> 'array'
       OR jsonb_array_length(payload_embedding -> 'embedding') <> 1024
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(payload_embedding -> 'embedding') AS coordinate(value)
         WHERE jsonb_typeof(coordinate.value) <> 'number'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 owner BGE staging embedding is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_chunk_id := payload_embedding ->> 'chunkId';
    payload_embedding_input_hash := payload_embedding ->> 'embeddingInputHash';
    IF payload_chunk_id !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR payload_embedding_input_hash !~ '^[0-9a-f]{64}$'
       OR NOT EXISTS (
         SELECT 1
         FROM public.rag_v2_immutable_generation_memberships AS membership
         WHERE membership.component_generation_id = expected_generation_id
           AND membership.chunk_id = payload_chunk_id
           AND membership.owner_user_id = p_owner_user_id
           AND membership.component_scope = 'OWNER_PRIVATE'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 owner BGE staging embedding identity is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_embedding_vector := ((payload_embedding -> 'embedding')::text)::vector;
    INSERT INTO public.rag_v2_immutable_generation_embeddings (
      component_generation_id,
      chunk_id,
      owner_user_id,
      component_scope,
      embedding_profile_id,
      embedding_input_hash,
      context_set_hash,
      embedding
    ) VALUES (
      expected_generation_id,
      payload_chunk_id,
      p_owner_user_id,
      'OWNER_PRIVATE',
      'bge_m3_local_1024_v1',
      payload_embedding_input_hash,
      NULL,
      payload_embedding_vector
    );
    INSERT INTO public.rag_v2_immutable_embedding_cache (
      cache_id,
      owner_user_id,
      source_revision_id,
      chunk_id,
      source_scope,
      embedding_profile_id,
      embedding_input_hash,
      context_set_hash,
      embedding
    ) VALUES (
      'rgr_cache_' || substr(
        encode(digest('rag-v2-immutable-owner-cache|' || expected_generation_id || '|' || payload_chunk_id, 'sha256'), 'hex'),
        1,
        32
      ),
      p_owner_user_id,
      payload_source_revision_id,
      payload_chunk_id,
      'OWNER_PRIVATE',
      'bge_m3_local_1024_v1',
      payload_embedding_input_hash,
      NULL,
      payload_embedding_vector
    );
    INSERT INTO public.rag_v2_immutable_embedding_receipts (
      receipt_id,
      materialization_run_id,
      owner_user_id,
      source_scope,
      component_generation_id,
      chunk_id,
      embedding_profile_id,
      embedding_input_hash,
      context_set_hash,
      reuse_state
    ) VALUES (
      'rgr_emb_' || substr(
        encode(digest('rag-v2-immutable-owner-embedding-receipt|' || expected_run_id || '|' || payload_chunk_id, 'sha256'), 'hex'),
        1,
        32
      ),
      expected_run_id,
      p_owner_user_id,
      'OWNER_PRIVATE',
      expected_generation_id,
      payload_chunk_id,
      'bge_m3_local_1024_v1',
      payload_embedding_input_hash,
      NULL,
      'NEW'
    );
    observed_embedding_count := observed_embedding_count + 1;
  END LOOP;

  IF observed_embedding_count <> stage_expected_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging embedding count is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.rag_v2_immutable_source_receipts (
    receipt_id,
    materialization_run_id,
    owner_user_id,
    source_scope,
    source_revision_id,
    raw_content_sha256,
    canonical_text_sha256,
    reuse_state
  ) VALUES (
    'rgr_src_' || substr(
      encode(digest('rag-v2-immutable-owner-source-receipt|' || expected_run_id, 'sha256'), 'hex'),
      1,
      32
    ),
    expected_run_id,
    p_owner_user_id,
    'OWNER_PRIVATE',
    payload_source_revision_id,
    payload_raw_content_sha256,
    payload_canonical_text_sha256,
    'NEW'
  );
  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(p_payload -> 'chunks') WITH ORDINALITY AS chunks(value, ordinal)
    ORDER BY ordinal
  LOOP
    INSERT INTO public.rag_v2_immutable_chunk_receipts (
      receipt_id,
      materialization_run_id,
      owner_user_id,
      source_scope,
      source_revision_id,
      chunk_id,
      canonical_text_sha256,
      reuse_state
    ) VALUES (
      'rgr_chk_' || substr(
        encode(digest('rag-v2-immutable-owner-chunk-receipt|' || expected_run_id || '|' || (payload_chunk ->> 'chunkId'), 'sha256'), 'hex'),
        1,
        32
      ),
      expected_run_id,
      p_owner_user_id,
      'OWNER_PRIVATE',
      payload_source_revision_id,
      payload_chunk ->> 'chunkId',
      payload_chunk ->> 'canonicalTextSha256',
      'NEW'
    );
  END LOOP;

  UPDATE public.rag_v2_immutable_component_generations AS generation
  SET actual_source_count = 1,
      actual_chunk_count = stage_expected_chunk_count
  WHERE generation.component_generation_id = expected_generation_id
    AND generation.owner_user_id = p_owner_user_id
    AND generation.component_scope = 'OWNER_PRIVATE'
    AND generation.state = 'STAGING'
    AND generation.evaluation_status = 'PENDING';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging generation transition failed'
      USING ERRCODE = '23514';
  END IF;
  UPDATE public.rag_v2_immutable_materialization_runs AS run
  SET state = 'STAGED'
  WHERE run.materialization_run_id = expected_run_id
    AND run.owner_user_id = p_owner_user_id
    AND run.component_scope = 'OWNER_PRIVATE'
    AND run.state = 'OPEN';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE staging run transition failed'
      USING ERRCODE = '23514';
  END IF;

  RETURN QUERY SELECT expected_generation_id, expected_run_id, 'STAGED', 1, stage_expected_chunk_count;
END;
$_$;


ALTER FUNCTION public.stage_rag_v2_immutable_owner_bge_document(p_owner_user_id text, p_ticket_id text, p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.stage_rag_v2_immutable_owner_bge_document_v2(p_owner_user_id text, p_ticket_id text, p_payload jsonb) RETURNS TABLE(component_generation_id text, materialization_run_id text, state text, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  v1_payload jsonb;
  payload_display_name text;
  payload_topics text[];
  staged_generation_id text;
  staged_run_id text;
  staged_state text;
  staged_source_count integer;
  staged_chunk_count integer;
  existing_display_name text;
  existing_topics text[];
  source_created_at timestamptz;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_ticket_id !~ '^rti_[0-9a-f]{32}$'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) NOT BETWEEN 2 AND 16777216
     OR EXISTS (
       SELECT 1
       FROM jsonb_object_keys(p_payload) AS root_key
       WHERE root_key NOT IN (
         'canonicalText', 'canonicalTextSha256', 'chunks', 'documentId', 'documentIr',
         'embeddingProfileId', 'embeddings', 'mimeType', 'normalizedDocumentIrSha256',
         'parserVersion', 'rawContentSha256', 'retrievalTopics', 'sanitizedDisplayName',
         'schemaVersion', 'sourceId', 'sourceLocator', 'sourceRevisionId',
         'sourceRevisionSha256', 'tokenizerVersion'
       )
     )
     OR NOT (p_payload ?& ARRAY[
       'canonicalText', 'canonicalTextSha256', 'chunks', 'documentId', 'documentIr',
       'embeddingProfileId', 'embeddings', 'mimeType', 'normalizedDocumentIrSha256',
       'parserVersion', 'rawContentSha256', 'retrievalTopics', 'sanitizedDisplayName',
       'schemaVersion', 'sourceId', 'sourceLocator', 'sourceRevisionId',
       'sourceRevisionSha256', 'tokenizerVersion'
     ])
     OR jsonb_typeof(p_payload -> 'schemaVersion') <> 'number'
     OR p_payload ->> 'schemaVersion' <> '2'
     OR jsonb_typeof(p_payload -> 'sanitizedDisplayName') <> 'string'
     OR jsonb_typeof(p_payload -> 'retrievalTopics') <> 'array'
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements(p_payload -> 'retrievalTopics') AS topic(value)
       WHERE jsonb_typeof(topic.value) <> 'string'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE v2 staging arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  payload_display_name := p_payload ->> 'sanitizedDisplayName';
  SELECT coalesce(
    array_agg(topic.value ORDER BY topic.value COLLATE "C"),
    ARRAY[]::text[]
  )
  INTO payload_topics
  FROM jsonb_array_elements_text(p_payload -> 'retrievalTopics') AS topic(value);
  IF payload_display_name IS NULL
     OR char_length(payload_display_name) NOT BETWEEN 1 AND 160
     OR payload_display_name <> btrim(payload_display_name)
     OR left(payload_display_name, 1) IN ('.', '~')
     OR position('/' IN payload_display_name) > 0
     OR position(E'\\' IN payload_display_name) > 0
     OR position(':' IN payload_display_name) > 0
     OR payload_display_name ~ '[[:cntrl:]]'
     OR NOT public.rag_v2_immutable_retrieval_topics_are_valid(payload_topics) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE v2 citation metadata is invalid'
      USING ERRCODE = '22023';
  END IF;

  -- V28 identity/data-path 검증을 그대로 재사용하되, v2-only citation metadata는 v1 closed
  -- payload에 섞지 않는다. V30 아래의 guarded write가 metadata를 같은 transaction 안에서만 bind한다.
  v1_payload := jsonb_set(
    p_payload - ARRAY['sanitizedDisplayName', 'retrievalTopics'],
    '{schemaVersion}',
    '1'::jsonb,
    true
  );
  SELECT
    staged.component_generation_id,
    staged.materialization_run_id,
    staged.state,
    staged.source_count,
    staged.chunk_count
  INTO
    staged_generation_id,
    staged_run_id,
    staged_state,
    staged_source_count,
    staged_chunk_count
  FROM public.stage_rag_v2_immutable_owner_bge_document(
    p_owner_user_id,
    p_ticket_id,
    v1_payload
  ) AS staged;
  IF staged_generation_id IS NULL
     OR staged_run_id IS NULL
     OR staged_state <> 'STAGED'
     OR staged_source_count <> 1
     OR staged_chunk_count < 1 THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE v2 staging receipt is invalid'
      USING ERRCODE = '23514';
  END IF;

  SELECT
    source.sanitized_display_name,
    source.retrieval_topics,
    source.created_at
  INTO existing_display_name, existing_topics, source_created_at
  FROM public.rag_v2_immutable_source_revisions AS source
  WHERE source.source_revision_id = v1_payload ->> 'sourceRevisionId'
    AND source.source_id = v1_payload ->> 'sourceId'
    AND source.owner_user_id = p_owner_user_id
    AND source.source_scope = 'OWNER_PRIVATE'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE v2 source receipt is absent'
      USING ERRCODE = '23514';
  END IF;

  IF existing_display_name IS NULL AND existing_topics IS NULL THEN
    -- 이 function의 current transaction에서 방금 생성된 source만 metadata를 받을 수 있다.
    -- 과거 V28 STAGED row는 immutable historical record로 남겨 fail-closed한다.
    IF source_created_at IS DISTINCT FROM transaction_timestamp() THEN
      RAISE EXCEPTION 'immutable RAG v2 owner BGE v2 cannot backfill historical staging metadata'
        USING ERRCODE = '55000';
    END IF;
    UPDATE public.rag_v2_immutable_source_revisions
    SET sanitized_display_name = payload_display_name,
        retrieval_topics = payload_topics
    WHERE source_revision_id = v1_payload ->> 'sourceRevisionId'
      AND source_id = v1_payload ->> 'sourceId'
      AND owner_user_id = p_owner_user_id
      AND source_scope = 'OWNER_PRIVATE'
      AND sanitized_display_name IS NULL
      AND retrieval_topics IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'immutable RAG v2 owner BGE v2 metadata binding conflicted'
        USING ERRCODE = '40001';
    END IF;
  ELSIF existing_display_name IS DISTINCT FROM payload_display_name
     OR existing_topics IS DISTINCT FROM payload_topics THEN
    RAISE EXCEPTION 'immutable RAG v2 owner BGE v2 metadata identity conflicted'
      USING ERRCODE = '23505';
  END IF;

  RETURN QUERY
  SELECT staged_generation_id, staged_run_id, staged_state, staged_source_count, staged_chunk_count;
END;
$_$;


ALTER FUNCTION public.stage_rag_v2_immutable_owner_bge_document_v2(p_owner_user_id text, p_ticket_id text, p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.stage_rag_v2_immutable_owner_document_v3(p_owner_user_id text, p_ticket_id text, p_payload jsonb) RETURNS TABLE(component_generation_id text, materialization_run_id text, state text, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  selected_profile text;
  ticket_digest text;
  legacy_payload jsonb;
  legacy_embeddings jsonb;
  staged_generation_id text;
  staged_run_id text;
  staged_state text;
  staged_source_count integer;
  staged_chunk_count integer;
  voyage_generation_hash text;
  voyage_generation_id text;
  voyage_run_id text;
  voyage_manifest_hash text;
  payload_source_revision_id text;
  payload_document_id text;
  payload_chunk jsonb;
  voyage_embedding jsonb;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_ticket_id !~ '^rti_[0-9a-f]{32}$'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR p_payload ->> 'schemaVersion' <> '3'
     OR p_payload ->> 'embeddingProfileId' NOT IN ('bge_m3_local_1024_v1', 'voyage_context_4_1024_v1') THEN
    RAISE EXCEPTION 'immutable RAG v2 owner v3 staging arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  selected_profile := p_payload ->> 'embeddingProfileId';
  IF selected_profile = 'voyage_context_4_1024_v1'
     AND current_setting('app.rag_v2_owner_voyage_completion', true) <> 'enabled' THEN
    RAISE EXCEPTION 'immutable RAG v2 owner Voyage requires atomic completion'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-owner-library|' || p_owner_user_id, 0)
  );
  PERFORM set_config('app.actor_user_id', p_owner_user_id, true);
  IF selected_profile = 'bge_m3_local_1024_v1'
     AND EXISTS (
       SELECT 1
       FROM public.rag_v2_owner_voyage_import_attempts AS attempt
       WHERE attempt.owner_user_id = p_owner_user_id
         AND attempt.state = 'ATTEMPTED'
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner library has an active Voyage attempt'
      USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_source_revisions AS source
    JOIN public.rag_v2_immutable_materialization_runs AS run
      ON run.owner_user_id = source.owner_user_id
     AND run.document_id = source.document_id
     AND run.component_scope = 'OWNER_PRIVATE'
    JOIN public.rag_v2_immutable_component_generations AS generation
      ON generation.component_generation_id = run.component_generation_id
    WHERE source.owner_user_id = p_owner_user_id
      AND source.source_scope = 'OWNER_PRIVATE'
      AND generation.embedding_profile_id <> selected_profile
  ) OR EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_owner_bundle_pointers AS pointer
    JOIN public.rag_v2_immutable_bundles AS bundle
      ON bundle.bundle_id = pointer.active_bundle_id
     AND bundle.owner_user_id = pointer.owner_user_id
    WHERE pointer.owner_user_id = p_owner_user_id
      AND pointer.state = 'READY'
      AND bundle.owner_embedding_profile_id IS NOT NULL
      AND bundle.owner_embedding_profile_id <> selected_profile
  ) THEN
    RAISE EXCEPTION 'immutable RAG v2 owner library profile is locked'
      USING ERRCODE = '22023';
  END IF;

  ticket_digest := encode(digest(p_ticket_id, 'sha256'), 'hex');
  PERFORM 1
  FROM public.rag_v2_immutable_import_tickets AS ticket
  WHERE ticket.ticket_hash = ticket_digest
    AND ticket.owner_user_id = p_owner_user_id
    AND ticket.operation = 'OWNER_IMPORT'
    AND ticket.policy_version = 'RAG_V2_OWNER_DOCUMENT_V2'
    AND ticket.embedding_profile_id = selected_profile
    AND ticket.state = 'ISSUED'
    AND ticket.consumed_at IS NULL
    AND ticket.expires_at > statement_timestamp()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 owner v3 ticket was rejected'
      USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_agg(value - 'contextSetHash' ORDER BY ordinal)
  INTO legacy_embeddings
  FROM jsonb_array_elements(p_payload -> 'embeddings') WITH ORDINALITY AS values(value, ordinal);
  legacy_payload := jsonb_set(p_payload, '{schemaVersion}', '2'::jsonb, true);
  legacy_payload := jsonb_set(legacy_payload, '{embeddingProfileId}', '"bge_m3_local_1024_v1"'::jsonb, true);
  legacy_payload := jsonb_set(legacy_payload, '{embeddings}', coalesce(legacy_embeddings, '[]'::jsonb), true);

  UPDATE public.rag_v2_immutable_import_tickets
  SET policy_version = 'RAG_V2_OWNER_DOCUMENT_V1', embedding_profile_id = NULL
  WHERE ticket_hash = ticket_digest;
  SELECT staged.component_generation_id, staged.materialization_run_id,
         staged.state, staged.source_count, staged.chunk_count
  INTO staged_generation_id, staged_run_id, staged_state,
       staged_source_count, staged_chunk_count
  FROM public.stage_rag_v2_immutable_owner_bge_document_v2(
    p_owner_user_id, p_ticket_id, legacy_payload
  ) AS staged;

  IF selected_profile = 'bge_m3_local_1024_v1' THEN
    UPDATE public.rag_v2_immutable_import_tickets
    SET policy_version = 'RAG_V2_OWNER_DOCUMENT_V2', embedding_profile_id = selected_profile
    WHERE ticket_hash = ticket_digest AND consumer_run_id = staged_run_id;
    RETURN QUERY
    SELECT staged_generation_id, staged_run_id, staged_state,
           staged_source_count, staged_chunk_count;
    RETURN;
  END IF;

  payload_source_revision_id := p_payload ->> 'sourceRevisionId';
  payload_document_id := p_payload ->> 'documentId';
  voyage_generation_hash := encode(
    digest('rag-v2-owner-voyage-generation|' || p_owner_user_id || '|' || p_payload::text, 'sha256'),
    'hex'
  );
  voyage_generation_id := 'rgr_' || substr(voyage_generation_hash, 1, 32);
  voyage_run_id := 'rgr_run_' || substr(
    encode(digest('rag-v2-owner-voyage-run|' || p_owner_user_id || '|' || p_payload::text, 'sha256'), 'hex'),
    1, 32
  );
  voyage_manifest_hash := encode(
    digest('rag-v2-owner-voyage-manifest|' || payload_source_revision_id || '|' || staged_chunk_count::text, 'sha256'),
    'hex'
  );

  INSERT INTO public.rag_v2_immutable_component_generations (
    component_generation_id, owner_user_id, component_scope, embedding_profile_id,
    state, evaluation_status, expected_source_count, expected_chunk_count,
    actual_source_count, actual_chunk_count, generation_hash, manifest_hash
  ) VALUES (
    voyage_generation_id, p_owner_user_id, 'OWNER_PRIVATE', selected_profile,
    'STAGING', 'PENDING', 1, staged_chunk_count, 1, staged_chunk_count,
    voyage_generation_hash, voyage_manifest_hash
  );
  INSERT INTO public.rag_v2_immutable_materialization_runs (
    materialization_run_id, owner_user_id, component_generation_id,
    component_scope, document_id, state
  ) VALUES (
    voyage_run_id, p_owner_user_id, voyage_generation_id,
    'OWNER_PRIVATE', payload_document_id, 'STAGED'
  );
  INSERT INTO public.rag_v2_immutable_generation_memberships (
    component_generation_id, chunk_id, source_revision_id,
    owner_user_id, component_scope, ordinal
  )
  SELECT voyage_generation_id, membership.chunk_id, membership.source_revision_id,
         p_owner_user_id, 'OWNER_PRIVATE', membership.ordinal
  FROM public.rag_v2_immutable_generation_memberships AS membership
  WHERE membership.component_generation_id = staged_generation_id
  ORDER BY membership.ordinal;

  FOR voyage_embedding IN
    SELECT value
    FROM jsonb_array_elements(p_payload -> 'embeddings') WITH ORDINALITY AS values(value, ordinal)
    ORDER BY ordinal
  LOOP
    IF voyage_embedding ->> 'contextSetHash' !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'immutable RAG v2 owner Voyage context identity is invalid'
        USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.rag_v2_immutable_generation_embeddings (
      component_generation_id, chunk_id, owner_user_id, component_scope,
      embedding_profile_id, embedding_input_hash, context_set_hash, embedding
    )
    SELECT voyage_generation_id, old.chunk_id, p_owner_user_id, 'OWNER_PRIVATE',
           selected_profile, voyage_embedding ->> 'embeddingInputHash',
           voyage_embedding ->> 'contextSetHash', old.embedding
    FROM public.rag_v2_immutable_generation_embeddings AS old
    WHERE old.component_generation_id = staged_generation_id
      AND old.chunk_id = voyage_embedding ->> 'chunkId';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'immutable RAG v2 owner Voyage embedding identity is invalid'
        USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.rag_v2_immutable_embedding_cache (
      cache_id, owner_user_id, source_revision_id, chunk_id, source_scope,
      embedding_profile_id, embedding_input_hash, context_set_hash, embedding
    )
    SELECT
      'rgr_cache_' || substr(encode(digest('rag-v2-owner-voyage-cache|' || voyage_generation_id || '|' || old.chunk_id, 'sha256'), 'hex'), 1, 32),
      p_owner_user_id, payload_source_revision_id, old.chunk_id, 'OWNER_PRIVATE',
      selected_profile, voyage_embedding ->> 'embeddingInputHash',
      voyage_embedding ->> 'contextSetHash', old.embedding
    FROM public.rag_v2_immutable_generation_embeddings AS old
    WHERE old.component_generation_id = staged_generation_id
      AND old.chunk_id = voyage_embedding ->> 'chunkId';
    INSERT INTO public.rag_v2_immutable_embedding_receipts (
      receipt_id, materialization_run_id, owner_user_id, source_scope,
      component_generation_id, chunk_id, embedding_profile_id,
      embedding_input_hash, context_set_hash, reuse_state
    ) VALUES (
      'rgr_emb_' || substr(encode(digest('rag-v2-owner-voyage-embedding-receipt|' || voyage_run_id || '|' || (voyage_embedding ->> 'chunkId'), 'sha256'), 'hex'), 1, 32),
      voyage_run_id, p_owner_user_id, 'OWNER_PRIVATE', voyage_generation_id,
      voyage_embedding ->> 'chunkId', selected_profile,
      voyage_embedding ->> 'embeddingInputHash', voyage_embedding ->> 'contextSetHash', 'NEW'
    );
  END LOOP;

  INSERT INTO public.rag_v2_immutable_source_receipts (
    receipt_id, materialization_run_id, owner_user_id, source_scope,
    source_revision_id, raw_content_sha256, canonical_text_sha256, reuse_state
  )
  SELECT
    'rgr_src_' || substr(encode(digest('rag-v2-owner-voyage-source-receipt|' || voyage_run_id, 'sha256'), 'hex'), 1, 32),
    voyage_run_id, p_owner_user_id, 'OWNER_PRIVATE', source.source_revision_id,
    source.raw_content_sha256, source.canonical_text_sha256, 'NEW'
  FROM public.rag_v2_immutable_source_revisions AS source
  WHERE source.source_revision_id = payload_source_revision_id
    AND source.owner_user_id = p_owner_user_id;
  FOR payload_chunk IN SELECT value FROM jsonb_array_elements(p_payload -> 'chunks') AS values(value)
  LOOP
    INSERT INTO public.rag_v2_immutable_chunk_receipts (
      receipt_id, materialization_run_id, owner_user_id, source_scope,
      source_revision_id, chunk_id, canonical_text_sha256, reuse_state
    ) VALUES (
      'rgr_chk_' || substr(encode(digest('rag-v2-owner-voyage-chunk-receipt|' || voyage_run_id || '|' || (payload_chunk ->> 'chunkId'), 'sha256'), 'hex'), 1, 32),
      voyage_run_id, p_owner_user_id, 'OWNER_PRIVATE', payload_source_revision_id,
      payload_chunk ->> 'chunkId', payload_chunk ->> 'canonicalTextSha256', 'NEW'
    );
  END LOOP;

  UPDATE public.rag_v2_immutable_source_revisions
  SET external_embedding_allowed = true,
      external_generation_allowed = true,
      external_processing_eligible = true
  WHERE source_revision_id = payload_source_revision_id
    AND owner_user_id = p_owner_user_id
    AND source_scope = 'OWNER_PRIVATE';
  UPDATE public.rag_v2_immutable_import_tickets
  SET policy_version = 'RAG_V2_OWNER_DOCUMENT_V2',
      embedding_profile_id = selected_profile,
      consumer_run_id = voyage_run_id
  WHERE ticket_hash = ticket_digest AND consumer_run_id = staged_run_id;

  DELETE FROM public.rag_v2_immutable_embedding_receipts WHERE materialization_run_id = staged_run_id;
  DELETE FROM public.rag_v2_immutable_chunk_receipts WHERE materialization_run_id = staged_run_id;
  DELETE FROM public.rag_v2_immutable_source_receipts WHERE materialization_run_id = staged_run_id;
  DELETE FROM public.rag_v2_immutable_embedding_cache
  WHERE owner_user_id = p_owner_user_id
    AND source_revision_id = payload_source_revision_id
    AND embedding_profile_id = 'bge_m3_local_1024_v1';
  DELETE FROM public.rag_v2_immutable_generation_embeddings WHERE component_generation_id = staged_generation_id;
  DELETE FROM public.rag_v2_immutable_generation_memberships WHERE component_generation_id = staged_generation_id;
  DELETE FROM public.rag_v2_immutable_materialization_runs WHERE materialization_run_id = staged_run_id;
  DELETE FROM public.rag_v2_immutable_component_generations WHERE component_generation_id = staged_generation_id;

  RETURN QUERY SELECT voyage_generation_id, voyage_run_id, 'STAGED', 1, staged_chunk_count;
END;
$_$;


ALTER FUNCTION public.stage_rag_v2_immutable_owner_document_v3(p_owner_user_id text, p_ticket_id text, p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.stage_rag_v2_immutable_public_bge_document(p_payload jsonb) RETURNS TABLE(component_generation_id text, materialization_run_id text, state text, source_reused boolean, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  payload_scope text;
  payload_generation_id text;
  payload_run_id text;
  payload_generation_hash text;
  payload_manifest_hash text;
  payload_expected_source_count integer;
  payload_expected_chunk_count integer;
  payload_member_digests text[];
  payload_source_member_digest text;
  computed_manifest_hash text;
  computed_generation_hash text;
  payload_source jsonb;
  payload_document_id text;
  payload_source_id text;
  payload_source_revision_id text;
  payload_source_revision_sha256 text;
  payload_raw_content_sha256 text;
  payload_normalized_document_ir_sha256 text;
  payload_canonical_text_sha256 text;
  payload_canonical_text text;
  payload_mime_type text;
  payload_parser_version text;
  payload_tokenizer_version text;
  payload_document_ir jsonb;
  payload_source_locator jsonb;
  payload_canonical_https_url text;
  payload_source_card_sha256 text;
  payload_oa_track_id text;
  payload_source_card jsonb;
  payload_license_evidence_sha256 text;
  payload_access_evidence_sha256 text;
  payload_machine_fetch_allowed boolean;
  payload_local_processing_allowed boolean;
  payload_external_embedding_allowed boolean;
  payload_external_generation_allowed boolean;
  payload_external_processing_eligible boolean;
  payload_citation_title text;
  payload_topics text[];
  payload_chunk jsonb;
  payload_embedding jsonb;
  payload_chunk_id text;
  payload_chunk_ordinal integer;
  payload_chunk_text text;
  payload_chunk_sha256 text;
  payload_chunk_locator jsonb;
  payload_chunk_heading_path text[];
  payload_chunk_token_count integer;
  payload_chunk_contains_table boolean;
  payload_embedding_input_hash text;
  payload_embedding_vector vector(1024);
  cached_embedding_vector vector(1024);
  expected_source_record public.rag_v2_immutable_source_revisions%ROWTYPE;
  expected_generation_record public.rag_v2_immutable_component_generations%ROWTYPE;
  expected_manifest_record public.rag_v2_immutable_public_component_manifests%ROWTYPE;
  existing_run_state text;
  observed_chunk_count integer := 0;
  observed_embedding_count integer := 0;
  observed_source_text text := '';
  first_chunk_locator jsonb;
  observed_source_total integer := 0;
  observed_chunk_total integer := 0;
  existing_membership_count integer := 0;
  reused_embedding_count integer := 0;
  source_was_reused boolean := false;
  embedding_was_reused boolean := false;
  complete_state text := 'STAGING';
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) NOT BETWEEN 2 AND 16777216
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_payload) AS root_key
      WHERE root_key NOT IN (
         'componentGenerationId', 'componentScope', 'embeddingProfileId', 'expectedChunkCount',
         'expectedSourceCount', 'generationHash', 'manifestHash', 'materializationRunId',
         'memberDigests', 'schemaVersion', 'source'
       )
     )
     OR NOT (p_payload ?& ARRAY[
       'componentGenerationId', 'componentScope', 'embeddingProfileId', 'expectedChunkCount',
       'expectedSourceCount', 'generationHash', 'manifestHash', 'materializationRunId',
       'memberDigests', 'schemaVersion', 'source'
     ])
     OR jsonb_typeof(p_payload -> 'schemaVersion') <> 'number'
     OR p_payload ->> 'schemaVersion' <> '1'
     OR jsonb_typeof(p_payload -> 'componentGenerationId') <> 'string'
     OR jsonb_typeof(p_payload -> 'componentScope') <> 'string'
     OR jsonb_typeof(p_payload -> 'embeddingProfileId') <> 'string'
     OR jsonb_typeof(p_payload -> 'generationHash') <> 'string'
     OR jsonb_typeof(p_payload -> 'manifestHash') <> 'string'
     OR jsonb_typeof(p_payload -> 'materializationRunId') <> 'string'
     OR p_payload ->> 'embeddingProfileId' <> 'bge_m3_local_1024_v1'
     OR jsonb_typeof(p_payload -> 'expectedSourceCount') <> 'number'
     OR jsonb_typeof(p_payload -> 'expectedChunkCount') <> 'number'
     OR (p_payload -> 'expectedSourceCount')::text !~ '^(0|[1-9][0-9]*)$'
     OR (p_payload -> 'expectedChunkCount')::text !~ '^(0|[1-9][0-9]*)$'
     OR jsonb_typeof(p_payload -> 'memberDigests') <> 'array'
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_payload -> 'memberDigests') AS digest_item(value)
       WHERE jsonb_typeof(digest_item.value) <> 'string'
     )
     OR jsonb_typeof(p_payload -> 'source') <> 'object' THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE staging arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  payload_scope := p_payload ->> 'componentScope';
  payload_generation_id := p_payload ->> 'componentGenerationId';
  payload_run_id := p_payload ->> 'materializationRunId';
  payload_generation_hash := p_payload ->> 'generationHash';
  payload_manifest_hash := p_payload ->> 'manifestHash';
  payload_expected_source_count := (p_payload ->> 'expectedSourceCount')::integer;
  payload_expected_chunk_count := (p_payload ->> 'expectedChunkCount')::integer;
  SELECT coalesce(array_agg(digest_item.value ORDER BY digest_item.ordinality), ARRAY[]::text[])
  INTO payload_member_digests
  FROM jsonb_array_elements_text(p_payload -> 'memberDigests') WITH ORDINALITY AS digest_item(value, ordinality);
  payload_source := p_payload -> 'source';
  IF payload_scope IS NULL
     OR payload_scope NOT IN ('EXACT30', 'OA112')
     OR payload_generation_id IS NULL
     OR payload_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR payload_run_id IS NULL
     OR payload_run_id !~ '^rgr_run_[0-9a-f]{32}$'
     OR payload_generation_hash IS NULL
     OR payload_generation_hash !~ '^[0-9a-f]{64}$'
     OR payload_manifest_hash IS NULL
     OR payload_manifest_hash !~ '^[0-9a-f]{64}$'
     OR payload_expected_source_count <> (CASE payload_scope WHEN 'EXACT30' THEN 30 ELSE 112 END)
     OR payload_expected_chunk_count < payload_expected_source_count
     OR cardinality(payload_member_digests) <> payload_expected_source_count
     OR array_position(payload_member_digests, NULL) IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM unnest(payload_member_digests) AS member_digest
       WHERE member_digest !~ '^[0-9a-f]{64}$'
     )
     OR cardinality(payload_member_digests) <> (
       SELECT count(DISTINCT member_digest) FROM unnest(payload_member_digests) AS member_digest
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE component identity is invalid'
      USING ERRCODE = '22023';
  END IF;
  computed_manifest_hash := public.rag_v2_immutable_public_bge_manifest_hash(
    payload_scope, payload_member_digests
  );
  computed_generation_hash := public.rag_v2_immutable_public_bge_generation_hash(
    payload_scope, payload_expected_source_count, payload_expected_chunk_count, computed_manifest_hash
  );
  IF payload_manifest_hash <> computed_manifest_hash
     OR payload_generation_hash <> computed_generation_hash
     OR payload_generation_id <> 'rgr_' || substr(computed_generation_hash, 1, 32)
     OR payload_run_id <> 'rgr_run_' || substr(
       encode(
         digest(
           'rag-v2-public-bge-run|' || payload_generation_id || '|' || payload_manifest_hash,
           'sha256'
         ),
         'hex'
       ),
       1,
       32
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE component hash binding is invalid'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_object_keys(payload_source) AS source_key
    WHERE source_key NOT IN (
      'accessEvidenceSha256', 'canonicalHttpsUrl', 'canonicalText', 'canonicalTextSha256',
      'chunks', 'citationTitle', 'documentId', 'documentIr', 'embeddings',
      'externalEmbeddingAllowed', 'externalGenerationAllowed', 'externalProcessingEligible',
      'licenseEvidenceSha256', 'localProcessingAllowed', 'machineFetchAllowed', 'mimeType',
      'oaSourceCard', 'oaTrackId', 'parserVersion', 'rawContentSha256', 'retrievalTopics',
      'sourceCardSha256', 'sourceId', 'sourceLocator', 'sourceRevisionId', 'sourceRevisionSha256', 'tokenizerVersion'
    )
  )
  OR NOT (payload_source ?& ARRAY[
    'accessEvidenceSha256', 'canonicalHttpsUrl', 'canonicalText', 'canonicalTextSha256',
    'chunks', 'citationTitle', 'documentId', 'documentIr', 'embeddings',
    'externalEmbeddingAllowed', 'externalGenerationAllowed', 'externalProcessingEligible',
    'licenseEvidenceSha256', 'localProcessingAllowed', 'machineFetchAllowed', 'mimeType',
    'oaSourceCard', 'oaTrackId', 'parserVersion', 'rawContentSha256', 'retrievalTopics',
    'sourceCardSha256', 'sourceId', 'sourceLocator', 'sourceRevisionId', 'sourceRevisionSha256', 'tokenizerVersion'
  ])
  OR jsonb_typeof(payload_source -> 'documentIr') <> 'object'
  OR jsonb_typeof(payload_source -> 'documentId') <> 'string'
  OR jsonb_typeof(payload_source -> 'sourceId') <> 'string'
  OR jsonb_typeof(payload_source -> 'sourceRevisionId') <> 'string'
  OR jsonb_typeof(payload_source -> 'sourceRevisionSha256') <> 'string'
  OR jsonb_typeof(payload_source -> 'rawContentSha256') <> 'string'
  OR jsonb_typeof(payload_source -> 'canonicalTextSha256') <> 'string'
  OR jsonb_typeof(payload_source -> 'canonicalText') <> 'string'
  OR jsonb_typeof(payload_source -> 'mimeType') <> 'string'
  OR jsonb_typeof(payload_source -> 'parserVersion') <> 'string'
  OR jsonb_typeof(payload_source -> 'tokenizerVersion') <> 'string'
  OR jsonb_typeof(payload_source -> 'canonicalHttpsUrl') <> 'string'
  OR jsonb_typeof(payload_source -> 'citationTitle') <> 'string'
  OR jsonb_typeof(payload_source -> 'chunks') <> 'array'
  OR jsonb_typeof(payload_source -> 'embeddings') <> 'array'
  OR jsonb_typeof(payload_source -> 'retrievalTopics') <> 'array'
  OR jsonb_typeof(payload_source -> 'sourceLocator') <> 'object'
  OR jsonb_typeof(payload_source -> 'machineFetchAllowed') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'localProcessingAllowed') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'externalEmbeddingAllowed') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'externalGenerationAllowed') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'externalProcessingEligible') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'sourceCardSha256') NOT IN ('null', 'string')
  OR jsonb_typeof(payload_source -> 'oaTrackId') NOT IN ('null', 'string')
  OR jsonb_typeof(payload_source -> 'oaSourceCard') NOT IN ('null', 'object')
  OR jsonb_typeof(payload_source -> 'licenseEvidenceSha256') NOT IN ('null', 'string')
  OR jsonb_typeof(payload_source -> 'accessEvidenceSha256') NOT IN ('null', 'string')
  OR jsonb_array_length(payload_source -> 'chunks') NOT BETWEEN 1 AND 50000
  OR jsonb_array_length(payload_source -> 'embeddings') <> jsonb_array_length(payload_source -> 'chunks') THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE source payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  payload_document_id := payload_source ->> 'documentId';
  payload_source_id := payload_source ->> 'sourceId';
  payload_source_revision_id := payload_source ->> 'sourceRevisionId';
  payload_source_revision_sha256 := payload_source ->> 'sourceRevisionSha256';
  payload_raw_content_sha256 := payload_source ->> 'rawContentSha256';
  payload_normalized_document_ir_sha256 := payload_source -> 'documentIr' ->> 'normalizedContentSha256';
  payload_canonical_text_sha256 := payload_source ->> 'canonicalTextSha256';
  payload_canonical_text := payload_source ->> 'canonicalText';
  payload_mime_type := payload_source ->> 'mimeType';
  payload_parser_version := payload_source ->> 'parserVersion';
  payload_tokenizer_version := payload_source ->> 'tokenizerVersion';
  payload_document_ir := payload_source -> 'documentIr';
  payload_source_locator := payload_source -> 'sourceLocator';
  payload_canonical_https_url := payload_source ->> 'canonicalHttpsUrl';
  payload_source_card_sha256 := payload_source ->> 'sourceCardSha256';
  payload_oa_track_id := payload_source ->> 'oaTrackId';
  payload_source_card := payload_source -> 'oaSourceCard';
  payload_license_evidence_sha256 := payload_source ->> 'licenseEvidenceSha256';
  payload_access_evidence_sha256 := payload_source ->> 'accessEvidenceSha256';
  payload_machine_fetch_allowed := (payload_source ->> 'machineFetchAllowed')::boolean;
  payload_local_processing_allowed := (payload_source ->> 'localProcessingAllowed')::boolean;
  payload_external_embedding_allowed := (payload_source ->> 'externalEmbeddingAllowed')::boolean;
  payload_external_generation_allowed := (payload_source ->> 'externalGenerationAllowed')::boolean;
  payload_external_processing_eligible := (payload_source ->> 'externalProcessingEligible')::boolean;
  payload_citation_title := payload_source ->> 'citationTitle';
  SELECT coalesce(array_agg(topic.value ORDER BY topic.ordinality), ARRAY[]::text[])
  INTO payload_topics
  FROM jsonb_array_elements_text(payload_source -> 'retrievalTopics') WITH ORDINALITY AS topic(value, ordinality);

  IF payload_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
     OR payload_source_id !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
     OR payload_source_revision_id !~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'
     OR payload_source_revision_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_raw_content_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_normalized_document_ir_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_canonical_text_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_canonical_text IS NULL
     OR octet_length(payload_canonical_text) NOT BETWEEN 1 AND 16777216
     OR payload_canonical_text_sha256 <> encode(digest(payload_canonical_text, 'sha256'), 'hex')
     OR payload_mime_type IS NULL
     OR payload_parser_version IS NULL
     OR payload_tokenizer_version IS NULL
     OR char_length(payload_mime_type) NOT BETWEEN 3 AND 128
     OR char_length(payload_parser_version) NOT BETWEEN 1 AND 128
     OR char_length(payload_tokenizer_version) NOT BETWEEN 1 AND 128
     OR payload_citation_title IS NULL
     OR char_length(payload_citation_title) NOT BETWEEN 1 AND 500
     OR btrim(payload_citation_title) = ''
     OR payload_citation_title ~ '[[:cntrl:]]'
     OR public.rag_v2_immutable_retrieval_topics_are_valid(payload_topics) IS NOT TRUE
     OR public.rag_v2_immutable_locator_is_valid(payload_source_locator) IS NOT TRUE
     OR public.rag_v2_immutable_public_https_url_is_valid(payload_canonical_https_url) IS NOT TRUE
     OR payload_document_ir ->> 'sourceId' IS DISTINCT FROM payload_source_id
     OR payload_document_ir ->> 'sourceRevisionId' IS DISTINCT FROM payload_source_revision_id
     OR payload_document_ir ->> 'mimeType' IS DISTINCT FROM payload_mime_type
     OR payload_document_ir ->> 'rawContentSha256' IS DISTINCT FROM payload_raw_content_sha256
     OR payload_document_ir ->> 'normalizedContentSha256' IS DISTINCT FROM payload_normalized_document_ir_sha256
     OR payload_document_ir -> 'parserEvidence' ->> 'parserVersion' IS DISTINCT FROM payload_parser_version
     OR public.rag_v2_immutable_document_ir_structure_is_valid(payload_document_ir) IS NOT TRUE THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE source identity is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF (payload_scope = 'EXACT30' AND (
        payload_oa_track_id IS NOT NULL
        OR payload_source_card <> 'null'::jsonb
        OR payload_license_evidence_sha256 IS NOT NULL
        OR payload_access_evidence_sha256 IS NOT NULL
        OR payload_machine_fetch_allowed
        OR NOT payload_local_processing_allowed
        OR payload_external_embedding_allowed
        OR payload_external_generation_allowed
        OR payload_external_processing_eligible
        OR payload_source_card_sha256 IS NULL
        OR payload_source_card_sha256 !~ '^[0-9a-f]{64}$'
        OR public.rag_v2_immutable_exact30_source_is_approved(
          payload_source_id,
          payload_canonical_https_url,
          payload_raw_content_sha256,
          payload_source_card_sha256
        ) IS NOT TRUE
      ))
     OR (payload_scope = 'OA112' AND (
        payload_oa_track_id IS NULL
        OR payload_source_card IS NULL
        OR jsonb_typeof(payload_source_card) <> 'object'
        OR public.rag_v2_immutable_oa_source_card_v4_is_valid(payload_source_card) IS NOT TRUE
        OR payload_license_evidence_sha256 !~ '^[0-9a-f]{64}$'
        OR payload_access_evidence_sha256 !~ '^[0-9a-f]{64}$'
        OR NOT payload_machine_fetch_allowed
        OR NOT payload_local_processing_allowed
        OR NOT payload_external_embedding_allowed
        OR NOT payload_external_generation_allowed
        OR payload_source_card ->> 'sourceId' IS DISTINCT FROM payload_source_id
        OR payload_source_card ->> 'canonicalUrl' IS DISTINCT FROM payload_canonical_https_url
        OR payload_source_card ->> 'rawContentSha256' IS DISTINCT FROM payload_raw_content_sha256
        OR payload_source_card ->> 'mimeType' IS DISTINCT FROM payload_mime_type
        OR payload_source_card ->> 'licenseEvidenceDigest' IS DISTINCT FROM payload_license_evidence_sha256
        OR payload_source_card -> 'accessEvidence' ->> 'accessEvidenceDigest' IS DISTINCT FROM payload_access_evidence_sha256
        OR payload_source_card -> 'accessEvidence' ->> 'verificationState' <> 'VERIFIED'
        OR payload_source_card ->> 'activeOa112Eligible' <> 'true'
        OR payload_source_card_sha256 IS NOT NULL
      )) THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE scope metadata is invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-public-bge|' || payload_generation_id, 0)
  );
  SELECT * INTO expected_generation_record
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = payload_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_component_generations (
      component_generation_id, owner_user_id, component_scope, embedding_profile_id, state,
      evaluation_status, expected_source_count, expected_chunk_count, actual_source_count,
      actual_chunk_count, generation_hash, manifest_hash
    ) VALUES (
      payload_generation_id, NULL, payload_scope, 'bge_m3_local_1024_v1', 'STAGING',
      'PENDING', payload_expected_source_count, payload_expected_chunk_count, 0,
      0, payload_generation_hash, payload_manifest_hash
    );
  ELSIF expected_generation_record.owner_user_id IS NOT NULL
     OR expected_generation_record.component_scope <> payload_scope
     OR expected_generation_record.embedding_profile_id <> 'bge_m3_local_1024_v1'
     OR expected_generation_record.state <> 'STAGING'
     OR expected_generation_record.evaluation_status <> 'PENDING'
     OR expected_generation_record.expected_source_count <> payload_expected_source_count
     OR expected_generation_record.expected_chunk_count <> payload_expected_chunk_count
     OR expected_generation_record.generation_hash <> payload_generation_hash
     OR expected_generation_record.manifest_hash <> payload_manifest_hash THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE component conflicts'
      USING ERRCODE = '23505';
  END IF;

  SELECT * INTO expected_manifest_record
  FROM public.rag_v2_immutable_public_component_manifests
  WHERE component_generation_id = payload_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_public_component_manifests (
      component_generation_id, component_scope, embedding_profile_id, member_digests,
      manifest_hash, generation_hash
    ) VALUES (
      payload_generation_id, payload_scope, 'bge_m3_local_1024_v1', payload_member_digests,
      payload_manifest_hash, payload_generation_hash
    );
  ELSIF expected_manifest_record.component_scope <> payload_scope
     OR expected_manifest_record.embedding_profile_id <> 'bge_m3_local_1024_v1'
     OR expected_manifest_record.member_digests IS DISTINCT FROM payload_member_digests
     OR expected_manifest_record.manifest_hash <> payload_manifest_hash
     OR expected_manifest_record.generation_hash <> payload_generation_hash THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE member manifest conflicts'
      USING ERRCODE = '23505';
  END IF;

  SELECT run.state INTO existing_run_state
  FROM public.rag_v2_immutable_materialization_runs AS run
  WHERE run.materialization_run_id = payload_run_id
    AND run.owner_user_id IS NULL
    AND run.component_generation_id = payload_generation_id
    AND run.component_scope = payload_scope
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_materialization_runs (
      materialization_run_id, owner_user_id, component_generation_id, component_scope, document_id, state
    ) VALUES (payload_run_id, NULL, payload_generation_id, payload_scope, NULL, 'OPEN');
  ELSIF existing_run_state NOT IN ('OPEN', 'STAGED') THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE run is not resumable'
      USING ERRCODE = '23505';
  END IF;

  -- generation lock alone cannot serialize two refresh generations that carry the
  -- same immutable source. Lock the scope-qualified identity before lookup so the
  -- second transaction observes the first committed source and takes the reuse path.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'rag-v2-immutable-public-bge-source|' || payload_scope || '|' || payload_source_revision_id,
      0
    )
  );
  SELECT * INTO expected_source_record
  FROM public.rag_v2_immutable_source_revisions
  WHERE source_revision_id = payload_source_revision_id
  FOR UPDATE;
  IF FOUND THEN
    source_was_reused := true;
    IF expected_source_record.owner_user_id IS NOT NULL
       OR expected_source_record.document_id <> payload_document_id
       OR expected_source_record.source_id <> payload_source_id
       OR expected_source_record.source_scope <> payload_scope
       OR expected_source_record.source_revision_sha256 <> payload_source_revision_sha256
       OR expected_source_record.raw_content_sha256 <> payload_raw_content_sha256
       OR expected_source_record.normalized_document_ir_sha256 <> payload_normalized_document_ir_sha256
       OR expected_source_record.canonical_text_sha256 <> payload_canonical_text_sha256
       OR expected_source_record.document_ir <> payload_document_ir
       OR expected_source_record.canonical_text <> payload_canonical_text
       OR expected_source_record.source_locator <> payload_source_locator
       OR expected_source_record.canonical_https_url <> payload_canonical_https_url
       OR expected_source_record.exact30_source_card_sha256 IS DISTINCT FROM
          (CASE WHEN payload_scope = 'EXACT30' THEN payload_source_card_sha256 ELSE NULL END)
       OR expected_source_record.mime_type <> payload_mime_type
       OR expected_source_record.machine_fetch_allowed <> payload_machine_fetch_allowed
       OR expected_source_record.local_processing_allowed <> payload_local_processing_allowed
       OR expected_source_record.external_embedding_allowed <> payload_external_embedding_allowed
       OR expected_source_record.external_generation_allowed <> payload_external_generation_allowed
       OR expected_source_record.external_processing_eligible <> payload_external_processing_eligible
       OR expected_source_record.parser_version <> payload_parser_version
       OR expected_source_record.tokenizer_version <> payload_tokenizer_version
       OR expected_source_record.retrieval_topics <> payload_topics
       OR expected_source_record.citation_title <> payload_citation_title
       OR expected_source_record.oa_track_id IS DISTINCT FROM
          (CASE WHEN payload_scope = 'OA112' THEN payload_oa_track_id ELSE NULL END)
       OR expected_source_record.reserve_source THEN
      RAISE EXCEPTION 'immutable RAG v2 public BGE source revision conflicts'
        USING ERRCODE = '23505';
    END IF;
    SELECT COUNT(*)::integer INTO existing_membership_count
    FROM public.rag_v2_immutable_generation_memberships AS membership
    WHERE membership.component_generation_id = payload_generation_id
      AND membership.source_revision_id = payload_source_revision_id
      AND membership.component_scope = payload_scope;
  END IF;

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    observed_chunk_count := observed_chunk_count + 1;
    IF jsonb_typeof(payload_chunk) <> 'object'
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(payload_chunk) AS chunk_key
         WHERE chunk_key NOT IN (
           'canonicalText', 'canonicalTextSha256', 'chunkId', 'chunkOrdinal',
           'containsTable', 'headingPath', 'locator', 'tokenCount'
         )
       )
       OR NOT (payload_chunk ?& ARRAY[
         'canonicalText', 'canonicalTextSha256', 'chunkId', 'chunkOrdinal',
         'containsTable', 'headingPath', 'locator', 'tokenCount'
       ])
       OR jsonb_typeof(payload_chunk -> 'headingPath') <> 'array'
       OR jsonb_typeof(payload_chunk -> 'locator') <> 'object'
       OR jsonb_typeof(payload_chunk -> 'chunkOrdinal') <> 'number'
       OR jsonb_typeof(payload_chunk -> 'containsTable') <> 'boolean'
       OR jsonb_typeof(payload_chunk -> 'tokenCount') <> 'number'
       OR (payload_chunk -> 'chunkOrdinal')::text !~ '^(0|[1-9][0-9]*)$'
       OR (payload_chunk -> 'tokenCount')::text !~ '^(0|[1-9][0-9]*)$'
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(payload_chunk -> 'headingPath') AS heading(value)
         WHERE jsonb_typeof(heading.value) <> 'string'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public BGE chunk is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_chunk_id := payload_chunk ->> 'chunkId';
    payload_chunk_ordinal := (payload_chunk ->> 'chunkOrdinal')::integer;
    payload_chunk_text := payload_chunk ->> 'canonicalText';
    payload_chunk_sha256 := payload_chunk ->> 'canonicalTextSha256';
    payload_chunk_locator := payload_chunk -> 'locator';
    payload_chunk_token_count := (payload_chunk ->> 'tokenCount')::integer;
    payload_chunk_contains_table := (payload_chunk ->> 'containsTable')::boolean;
    SELECT coalesce(array_agg(heading.value ORDER BY heading.ordinality), ARRAY[]::text[])
    INTO payload_chunk_heading_path
    FROM jsonb_array_elements_text(payload_chunk -> 'headingPath') WITH ORDINALITY AS heading(value, ordinality);
    IF payload_chunk_id !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR payload_chunk_ordinal <> observed_chunk_count
       OR payload_chunk_text IS NULL
       OR payload_chunk_sha256 !~ '^[0-9a-f]{64}$'
       OR payload_chunk_sha256 <> encode(digest(payload_chunk_text, 'sha256'), 'hex')
       OR payload_chunk_token_count NOT BETWEEN 1 AND 600
       OR cardinality(payload_chunk_heading_path) > 12
       OR public.rag_v2_immutable_locator_is_valid(payload_chunk_locator) IS NOT TRUE THEN
      RAISE EXCEPTION 'immutable RAG v2 public BGE chunk contract is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF first_chunk_locator IS NULL THEN
      first_chunk_locator := payload_chunk_locator;
    END IF;
    IF observed_chunk_count = 1 THEN
      observed_source_text := payload_chunk_text;
    ELSE
      observed_source_text := observed_source_text || E'\n\n' || payload_chunk_text;
    END IF;
  END LOOP;
  IF first_chunk_locator IS NULL
     OR payload_source_locator <> first_chunk_locator
     OR payload_canonical_text <> observed_source_text THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE source projection is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF source_was_reused THEN
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(payload_source -> 'chunks') AS supplied(value)
      LEFT JOIN public.rag_v2_immutable_chunks AS stored
        ON stored.chunk_id = supplied.value ->> 'chunkId'
       AND stored.source_revision_id = payload_source_revision_id
       AND stored.owner_user_id IS NULL
       AND stored.source_scope = payload_scope
      WHERE stored.chunk_id IS NULL
         OR stored.chunk_ordinal IS DISTINCT FROM (supplied.value ->> 'chunkOrdinal')::integer
         OR to_jsonb(stored.heading_path) IS DISTINCT FROM supplied.value -> 'headingPath'
         OR stored.locator IS DISTINCT FROM supplied.value -> 'locator'
         OR stored.canonical_text IS DISTINCT FROM supplied.value ->> 'canonicalText'
         OR stored.canonical_text_sha256 IS DISTINCT FROM supplied.value ->> 'canonicalTextSha256'
         OR stored.token_count IS DISTINCT FROM (supplied.value ->> 'tokenCount')::integer
         OR stored.contains_table IS DISTINCT FROM (supplied.value ->> 'containsTable')::boolean
    )
    OR (
      SELECT COUNT(*)::integer
      FROM public.rag_v2_immutable_chunks AS stored
      WHERE stored.source_revision_id = payload_source_revision_id
        AND stored.owner_user_id IS NULL
        AND stored.source_scope = payload_scope
    ) <> observed_chunk_count
    OR (
      payload_scope = 'OA112' AND NOT EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_oa_source_cards AS card
        WHERE card.source_revision_id = payload_source_revision_id
          AND card.source_scope = 'OA112'
          AND card.source_card = payload_source_card
      )
    ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public BGE source cache conflicts'
        USING ERRCODE = '23505';
    END IF;
  ELSE
    INSERT INTO public.rag_v2_immutable_source_revisions (
      source_revision_id, document_id, source_id, owner_user_id, source_scope, oa_track_id,
      reserve_source, source_revision_sha256, raw_content_sha256, normalized_document_ir_sha256,
      canonical_text_sha256, document_ir, canonical_text, sanitized_display_name, source_locator,
      canonical_https_url, exact30_source_card_sha256, license_evidence_sha256, access_evidence_sha256, mime_type,
      machine_fetch_allowed, local_processing_allowed, external_embedding_allowed,
      external_generation_allowed, external_processing_eligible, parser_version, tokenizer_version,
      retrieval_topics, citation_title
    ) VALUES (
      payload_source_revision_id, payload_document_id, payload_source_id, NULL, payload_scope,
      CASE WHEN payload_scope = 'OA112' THEN payload_oa_track_id ELSE NULL END,
      false, payload_source_revision_sha256, payload_raw_content_sha256, payload_normalized_document_ir_sha256,
      payload_canonical_text_sha256, payload_document_ir, payload_canonical_text, NULL, payload_source_locator,
      payload_canonical_https_url,
      CASE WHEN payload_scope = 'EXACT30' THEN payload_source_card_sha256 ELSE NULL END,
      CASE WHEN payload_scope = 'OA112' THEN payload_license_evidence_sha256 ELSE NULL END,
      CASE WHEN payload_scope = 'OA112' THEN payload_access_evidence_sha256 ELSE NULL END,
      payload_mime_type, payload_machine_fetch_allowed, payload_local_processing_allowed,
      payload_external_embedding_allowed, payload_external_generation_allowed,
      payload_external_processing_eligible, payload_parser_version, payload_tokenizer_version,
      payload_topics, payload_citation_title
    );
    IF payload_scope = 'OA112' THEN
      INSERT INTO public.rag_v2_immutable_oa_source_cards (
        source_revision_id, source_scope, source_id, source_card, source_card_sha256,
        active_oa112_eligible, title, authors, canonical_https_url, canonical_https_url_sha256,
        identifier_scheme, identifier_value, revision, revision_date, raw_content_sha256, mime_type,
        license_evidence_sha256, access_evidence_sha256, access_checked_at, access_verification_state,
        machine_fetch_allowed, local_processing_allowed, external_embedding_allowed, external_generation_allowed
      ) VALUES (
        payload_source_revision_id, 'OA112', payload_source_id, payload_source_card,
        encode(digest(payload_source_card::text, 'sha256'), 'hex'),
        (payload_source_card ->> 'activeOa112Eligible')::boolean, payload_source_card ->> 'title',
        ARRAY(SELECT value FROM jsonb_array_elements_text(payload_source_card -> 'authors') AS authors(value)),
        payload_canonical_https_url, payload_source_card ->> 'canonicalUrlSha256',
        payload_source_card -> 'identifier' ->> 'scheme', payload_source_card -> 'identifier' ->> 'value',
        payload_source_card ->> 'revision', (payload_source_card ->> 'revisionDate')::date,
        payload_raw_content_sha256, payload_mime_type, payload_license_evidence_sha256,
        payload_access_evidence_sha256, payload_source_card -> 'accessEvidence' ->> 'accessCheckedAt',
        payload_source_card -> 'accessEvidence' ->> 'verificationState', payload_machine_fetch_allowed,
        payload_local_processing_allowed, payload_external_embedding_allowed, payload_external_generation_allowed
      );
    END IF;

    FOR payload_chunk IN
      SELECT value
      FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
      ORDER BY ordinality
    LOOP
      SELECT coalesce(array_agg(heading.value ORDER BY heading.ordinality), ARRAY[]::text[])
      INTO payload_chunk_heading_path
      FROM jsonb_array_elements_text(payload_chunk -> 'headingPath') WITH ORDINALITY AS heading(value, ordinality);
      INSERT INTO public.rag_v2_immutable_chunks (
        chunk_id, source_revision_id, owner_user_id, source_scope, chunk_ordinal, heading_path,
        locator, canonical_text, canonical_text_sha256, token_count, contains_table
      ) VALUES (
        payload_chunk ->> 'chunkId', payload_source_revision_id, NULL, payload_scope,
        (payload_chunk ->> 'chunkOrdinal')::integer, payload_chunk_heading_path,
        payload_chunk -> 'locator', payload_chunk ->> 'canonicalText', payload_chunk ->> 'canonicalTextSha256',
        (payload_chunk ->> 'tokenCount')::integer, (payload_chunk ->> 'containsTable')::boolean
      );
    END LOOP;
  END IF;

  payload_source_member_digest := public.rag_v2_immutable_public_bge_source_member_digest(
    payload_source_revision_id,
    payload_scope
  );
  IF payload_source_member_digest IS NULL
     OR array_position(payload_member_digests, payload_source_member_digest) IS NULL THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE source is outside the bound member manifest'
      USING ERRCODE = '23514';
  END IF;
  IF source_was_reused AND existing_membership_count > 0 THEN
    IF existing_membership_count <> observed_chunk_count
       OR (
         SELECT COUNT(*)
         FROM public.rag_v2_immutable_generation_embeddings AS embedding
         WHERE embedding.component_generation_id = payload_generation_id
           AND embedding.component_scope = payload_scope
           AND embedding.chunk_id IN (
             SELECT membership.chunk_id
             FROM public.rag_v2_immutable_generation_memberships AS membership
             WHERE membership.component_generation_id = payload_generation_id
               AND membership.source_revision_id = payload_source_revision_id
               AND membership.component_scope = payload_scope
           )
       ) <> existing_membership_count THEN
      RAISE EXCEPTION 'immutable RAG v2 public BGE source resume is incomplete'
        USING ERRCODE = '23505';
    END IF;
    SELECT COUNT(DISTINCT membership.source_revision_id)::integer, COUNT(*)::integer
    INTO observed_source_total, observed_chunk_total
    FROM public.rag_v2_immutable_generation_memberships AS membership
    WHERE membership.component_generation_id = payload_generation_id
      AND membership.component_scope = payload_scope;
    RETURN QUERY SELECT payload_generation_id, payload_run_id,
      CASE WHEN observed_source_total = payload_expected_source_count AND observed_chunk_total = payload_expected_chunk_count THEN 'STAGED' ELSE 'STAGING' END,
      true, observed_source_total, observed_chunk_total;
    RETURN;
  END IF;

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    INSERT INTO public.rag_v2_immutable_generation_memberships (
      component_generation_id, chunk_id, source_revision_id, owner_user_id, component_scope, ordinal
    ) VALUES (
      payload_generation_id, payload_chunk ->> 'chunkId', payload_source_revision_id, NULL,
      payload_scope,
      (
        SELECT COUNT(*)::integer
        FROM public.rag_v2_immutable_generation_memberships AS previous_membership
        WHERE previous_membership.component_generation_id = payload_generation_id
      ) + 1
    );
  END LOOP;

  FOR payload_embedding IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'embeddings') WITH ORDINALITY AS embeddings(value, ordinality)
    ORDER BY ordinality
  LOOP
    observed_embedding_count := observed_embedding_count + 1;
    IF jsonb_typeof(payload_embedding) <> 'object'
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(payload_embedding) AS embedding_key
         WHERE embedding_key NOT IN ('chunkId', 'embedding', 'embeddingInputHash')
       )
       OR NOT (payload_embedding ?& ARRAY['chunkId', 'embedding', 'embeddingInputHash'])
       OR jsonb_typeof(payload_embedding -> 'embedding') <> 'array'
       OR jsonb_array_length(payload_embedding -> 'embedding') <> 1024
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(payload_embedding -> 'embedding') AS coordinate(value)
         WHERE jsonb_typeof(coordinate.value) <> 'number'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public BGE embedding is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_chunk_id := payload_embedding ->> 'chunkId';
    payload_embedding_input_hash := payload_embedding ->> 'embeddingInputHash';
    IF payload_chunk_id !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR payload_embedding_input_hash !~ '^[0-9a-f]{64}$'
       OR NOT EXISTS (
         SELECT 1 FROM public.rag_v2_immutable_generation_memberships AS membership
         WHERE membership.component_generation_id = payload_generation_id
           AND membership.chunk_id = payload_chunk_id
           AND membership.source_revision_id = payload_source_revision_id
           AND membership.component_scope = payload_scope
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public BGE embedding identity is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_embedding_vector := ((payload_embedding -> 'embedding')::text)::vector;
    -- 다른 generation이 같은 immutable chunk/profile cache를 동시에 채우면 one writer만 NEW로
    -- 기록하고 나머지는 같은 cached vector를 REUSED로 참조하게 source+hash key로 직렬화한다.
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'rag-v2-immutable-public-bge-cache|' || payload_scope || '|' ||
        payload_chunk_id || '|' || payload_embedding_input_hash,
        0
      )
    );
    SELECT cache.embedding
    INTO cached_embedding_vector
    FROM public.rag_v2_immutable_embedding_cache AS cache
    WHERE cache.owner_user_id IS NULL
      AND cache.chunk_id = payload_chunk_id
      AND cache.source_scope = payload_scope
      AND cache.embedding_profile_id = 'bge_m3_local_1024_v1'
      AND cache.embedding_input_hash = payload_embedding_input_hash
      AND cache.context_set_hash IS NULL
    FOR SHARE;
    embedding_was_reused := FOUND;
    IF embedding_was_reused THEN
      payload_embedding_vector := cached_embedding_vector;
      reused_embedding_count := reused_embedding_count + 1;
    END IF;
    INSERT INTO public.rag_v2_immutable_generation_embeddings (
      component_generation_id, chunk_id, owner_user_id, component_scope, embedding_profile_id,
      embedding_input_hash, context_set_hash, embedding
    ) VALUES (
      payload_generation_id, payload_chunk_id, NULL, payload_scope, 'bge_m3_local_1024_v1',
      payload_embedding_input_hash, NULL, payload_embedding_vector
    );
    IF NOT embedding_was_reused THEN
      INSERT INTO public.rag_v2_immutable_embedding_cache (
        cache_id, owner_user_id, source_revision_id, chunk_id, source_scope, embedding_profile_id,
        embedding_input_hash, context_set_hash, embedding
      ) VALUES (
        'rgr_cache_' || substr(
          encode(digest('rag-v2-immutable-public-bge-cache|' || payload_generation_id || '|' || payload_chunk_id, 'sha256'), 'hex'),
          1, 32
        ),
        NULL, payload_source_revision_id, payload_chunk_id, payload_scope, 'bge_m3_local_1024_v1',
        payload_embedding_input_hash, NULL, payload_embedding_vector
      );
    END IF;
    INSERT INTO public.rag_v2_immutable_embedding_receipts (
      receipt_id, materialization_run_id, owner_user_id, source_scope, component_generation_id,
      chunk_id, embedding_profile_id, embedding_input_hash, context_set_hash, reuse_state
    ) VALUES (
      'rgr_emb_' || substr(
        encode(digest('rag-v2-immutable-public-bge-embedding-receipt|' || payload_run_id || '|' || payload_chunk_id, 'sha256'), 'hex'),
        1, 32
      ),
      payload_run_id, NULL, payload_scope, payload_generation_id, payload_chunk_id,
      'bge_m3_local_1024_v1', payload_embedding_input_hash, NULL,
      CASE WHEN embedding_was_reused THEN 'REUSED' ELSE 'NEW' END
    );
  END LOOP;
  IF observed_embedding_count <> observed_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE embedding count is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.rag_v2_immutable_source_receipts (
    receipt_id, materialization_run_id, owner_user_id, source_scope, source_revision_id,
    raw_content_sha256, canonical_text_sha256, reuse_state
  ) VALUES (
    'rgr_src_' || substr(
      encode(digest('rag-v2-immutable-public-bge-source-receipt|' || payload_run_id || '|' || payload_source_revision_id, 'sha256'), 'hex'),
      1, 32
    ),
    payload_run_id, NULL, payload_scope, payload_source_revision_id,
    payload_raw_content_sha256, payload_canonical_text_sha256,
    CASE WHEN source_was_reused THEN 'REUSED' ELSE 'NEW' END
  );
  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    INSERT INTO public.rag_v2_immutable_chunk_receipts (
      receipt_id, materialization_run_id, owner_user_id, source_scope, source_revision_id,
      chunk_id, canonical_text_sha256, reuse_state
    ) VALUES (
      'rgr_chk_' || substr(
        encode(digest('rag-v2-immutable-public-bge-chunk-receipt|' || payload_run_id || '|' || (payload_chunk ->> 'chunkId'), 'sha256'), 'hex'),
        1, 32
      ),
      payload_run_id, NULL, payload_scope, payload_source_revision_id,
      payload_chunk ->> 'chunkId', payload_chunk ->> 'canonicalTextSha256',
      CASE WHEN source_was_reused THEN 'REUSED' ELSE 'NEW' END
    );
  END LOOP;

  UPDATE public.rag_v2_immutable_materialization_runs AS run
  SET source_reused_count = run.source_reused_count + CASE WHEN source_was_reused THEN 1 ELSE 0 END,
      chunk_reused_count = run.chunk_reused_count + CASE WHEN source_was_reused THEN observed_chunk_count ELSE 0 END,
      embedding_reused_count = run.embedding_reused_count + reused_embedding_count
  WHERE run.materialization_run_id = payload_run_id
    AND run.owner_user_id IS NULL
    AND run.component_scope = payload_scope
    AND run.state = 'OPEN';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE reuse receipt transition failed'
      USING ERRCODE = '23514';
  END IF;

  SELECT COUNT(DISTINCT membership.source_revision_id)::integer, COUNT(*)::integer
  INTO observed_source_total, observed_chunk_total
  FROM public.rag_v2_immutable_generation_memberships AS membership
  WHERE membership.component_generation_id = payload_generation_id
    AND membership.component_scope = payload_scope;
  IF observed_source_total > payload_expected_source_count
     OR observed_chunk_total > payload_expected_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE component exceeded exact membership'
      USING ERRCODE = '23514';
  END IF;
  UPDATE public.rag_v2_immutable_component_generations
  SET actual_source_count = observed_source_total,
      actual_chunk_count = observed_chunk_total
  WHERE component_generation_id = payload_generation_id
    AND owner_user_id IS NULL
    AND component_scope = payload_scope
    AND state = 'STAGING'
    AND evaluation_status = 'PENDING';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 public BGE component transition failed'
      USING ERRCODE = '23514';
  END IF;
  IF observed_source_total = payload_expected_source_count
     AND observed_chunk_total = payload_expected_chunk_count THEN
    complete_state := 'STAGED';
    UPDATE public.rag_v2_immutable_materialization_runs
    SET state = 'STAGED'
    WHERE materialization_run_id = payload_run_id
      AND owner_user_id IS NULL
      AND component_scope = payload_scope
      AND state = 'OPEN';
  END IF;
  RETURN QUERY SELECT payload_generation_id, payload_run_id, complete_state,
    source_was_reused, observed_source_total, observed_chunk_total;
END;
$_$;


ALTER FUNCTION public.stage_rag_v2_immutable_public_bge_document(p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.stage_rag_v2_immutable_public_voyage_document(p_payload jsonb) RETURNS TABLE(component_generation_id text, materialization_run_id text, state text, source_reused boolean, source_count integer, chunk_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  payload_scope text;
  payload_generation_id text;
  payload_run_id text;
  payload_generation_hash text;
  payload_manifest_hash text;
  payload_expected_source_count integer;
  payload_expected_chunk_count integer;
  payload_member_digests text[];
  payload_source_member_digest text;
  computed_manifest_hash text;
  computed_generation_hash text;
  payload_source jsonb;
  payload_document_id text;
  payload_source_id text;
  payload_source_revision_id text;
  payload_source_revision_sha256 text;
  payload_raw_content_sha256 text;
  payload_normalized_document_ir_sha256 text;
  payload_canonical_text_sha256 text;
  payload_canonical_text text;
  payload_mime_type text;
  payload_parser_version text;
  payload_tokenizer_version text;
  payload_document_ir jsonb;
  payload_source_locator jsonb;
  payload_canonical_https_url text;
  payload_source_card_sha256 text;
  payload_oa_track_id text;
  payload_source_card jsonb;
  payload_license_evidence_sha256 text;
  payload_access_evidence_sha256 text;
  payload_machine_fetch_allowed boolean;
  payload_local_processing_allowed boolean;
  payload_external_embedding_allowed boolean;
  payload_external_generation_allowed boolean;
  payload_external_processing_eligible boolean;
  payload_citation_title text;
  payload_topics text[];
  payload_chunk jsonb;
  payload_embedding jsonb;
  payload_chunk_id text;
  payload_chunk_ordinal integer;
  payload_chunk_text text;
  payload_chunk_sha256 text;
  payload_chunk_locator jsonb;
  payload_chunk_heading_path text[];
  payload_chunk_token_count integer;
  payload_chunk_contains_table boolean;
  payload_embedding_input_hash text;
  payload_context_set_hash text;
  payload_embedding_vector vector(1024);
  cached_embedding_vector vector(1024);
  existing_embedding_input_hash text;
  existing_context_set_hash text;
  expected_context_set_hash text;
  expected_source_record public.rag_v2_immutable_source_revisions%ROWTYPE;
  expected_generation_record public.rag_v2_immutable_component_generations%ROWTYPE;
  expected_manifest_record public.rag_v2_immutable_public_voyage_component_manifests%ROWTYPE;
  existing_run_state text;
  observed_chunk_count integer := 0;
  observed_embedding_count integer := 0;
  observed_source_text text := '';
  first_chunk_locator jsonb;
  observed_source_total integer := 0;
  observed_chunk_total integer := 0;
  existing_membership_count integer := 0;
  reused_embedding_count integer := 0;
  source_was_reused boolean := false;
  embedding_was_reused boolean := false;
  complete_state text := 'STAGING';
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR octet_length(p_payload::text) NOT BETWEEN 2 AND 16777216
     OR EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_payload) AS root_key
      WHERE root_key NOT IN (
         'componentGenerationId', 'componentScope', 'embeddingProfileId', 'expectedChunkCount',
         'expectedSourceCount', 'generationHash', 'manifestHash', 'materializationRunId',
         'memberDigests', 'schemaVersion', 'source'
       )
     )
     OR NOT (p_payload ?& ARRAY[
       'componentGenerationId', 'componentScope', 'embeddingProfileId', 'expectedChunkCount',
       'expectedSourceCount', 'generationHash', 'manifestHash', 'materializationRunId',
       'memberDigests', 'schemaVersion', 'source'
     ])
     OR jsonb_typeof(p_payload -> 'schemaVersion') <> 'number'
     OR p_payload ->> 'schemaVersion' <> '1'
     OR jsonb_typeof(p_payload -> 'componentGenerationId') <> 'string'
     OR jsonb_typeof(p_payload -> 'componentScope') <> 'string'
     OR jsonb_typeof(p_payload -> 'embeddingProfileId') <> 'string'
     OR jsonb_typeof(p_payload -> 'generationHash') <> 'string'
     OR jsonb_typeof(p_payload -> 'manifestHash') <> 'string'
     OR jsonb_typeof(p_payload -> 'materializationRunId') <> 'string'
     OR p_payload ->> 'embeddingProfileId' <> 'voyage_context_4_1024_v1'
     OR jsonb_typeof(p_payload -> 'expectedSourceCount') <> 'number'
     OR jsonb_typeof(p_payload -> 'expectedChunkCount') <> 'number'
     OR (p_payload -> 'expectedSourceCount')::text !~ '^(0|[1-9][0-9]*)$'
     OR (p_payload -> 'expectedChunkCount')::text !~ '^(0|[1-9][0-9]*)$'
     OR jsonb_typeof(p_payload -> 'memberDigests') <> 'array'
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_payload -> 'memberDigests') AS digest_item(value)
       WHERE jsonb_typeof(digest_item.value) <> 'string'
     )
     OR jsonb_typeof(p_payload -> 'source') <> 'object' THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage staging arguments are invalid'
      USING ERRCODE = '22023';
  END IF;

  payload_scope := p_payload ->> 'componentScope';
  payload_generation_id := p_payload ->> 'componentGenerationId';
  payload_run_id := p_payload ->> 'materializationRunId';
  payload_generation_hash := p_payload ->> 'generationHash';
  payload_manifest_hash := p_payload ->> 'manifestHash';
  payload_expected_source_count := (p_payload ->> 'expectedSourceCount')::integer;
  payload_expected_chunk_count := (p_payload ->> 'expectedChunkCount')::integer;
  SELECT coalesce(array_agg(digest_item.value ORDER BY digest_item.ordinality), ARRAY[]::text[])
  INTO payload_member_digests
  FROM jsonb_array_elements_text(p_payload -> 'memberDigests') WITH ORDINALITY AS digest_item(value, ordinality);
  payload_source := p_payload -> 'source';
  IF payload_scope IS NULL
     OR payload_scope NOT IN ('EXACT30', 'OA112')
     OR payload_generation_id IS NULL
     OR payload_generation_id !~ '^rgr_[0-9a-f]{32}$'
     OR payload_run_id IS NULL
     OR payload_run_id !~ '^rgr_run_[0-9a-f]{32}$'
     OR payload_generation_hash IS NULL
     OR payload_generation_hash !~ '^[0-9a-f]{64}$'
     OR payload_manifest_hash IS NULL
     OR payload_manifest_hash !~ '^[0-9a-f]{64}$'
     OR payload_expected_source_count <> (CASE payload_scope WHEN 'EXACT30' THEN 30 ELSE 112 END)
     OR payload_expected_chunk_count < payload_expected_source_count
     OR cardinality(payload_member_digests) <> payload_expected_source_count
     OR array_position(payload_member_digests, NULL) IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM unnest(payload_member_digests) AS member_digest
       WHERE member_digest !~ '^[0-9a-f]{64}$'
     )
     OR cardinality(payload_member_digests) <> (
       SELECT count(DISTINCT member_digest) FROM unnest(payload_member_digests) AS member_digest
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage component identity is invalid'
      USING ERRCODE = '22023';
  END IF;
  computed_manifest_hash := public.rag_v2_immutable_public_voyage_manifest_hash(
    payload_scope, payload_member_digests
  );
  computed_generation_hash := public.rag_v2_immutable_public_voyage_generation_hash(
    payload_scope, payload_expected_source_count, payload_expected_chunk_count, computed_manifest_hash
  );
  IF payload_manifest_hash <> computed_manifest_hash
     OR payload_generation_hash <> computed_generation_hash
     OR payload_generation_id <> 'rgr_' || substr(computed_generation_hash, 1, 32)
     OR payload_run_id <> 'rgr_run_' || substr(
       encode(
         digest(
           CASE payload_scope
             WHEN 'EXACT30' THEN
               'rag-v2-external-exact30-voyage-run|' || payload_generation_id || '|' || payload_manifest_hash
             ELSE
               'rag-v2-oa112-voyage-run|' || payload_generation_id || '|' || payload_manifest_hash
           END,
           'sha256'
         ),
         'hex'
       ),
       1,
       32
     ) THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage component hash binding is invalid'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_object_keys(payload_source) AS source_key
    WHERE source_key NOT IN (
      'accessEvidenceSha256', 'canonicalHttpsUrl', 'canonicalText', 'canonicalTextSha256',
      'chunks', 'citationTitle', 'documentId', 'documentIr', 'embeddings',
      'externalEmbeddingAllowed', 'externalGenerationAllowed', 'externalProcessingEligible',
      'licenseEvidenceSha256', 'localProcessingAllowed', 'machineFetchAllowed', 'mimeType',
      'oaSourceCard', 'oaTrackId', 'parserVersion', 'rawContentSha256', 'retrievalTopics',
      'sourceCardSha256', 'sourceId', 'sourceLocator', 'sourceRevisionId', 'sourceRevisionSha256', 'tokenizerVersion'
    )
  )
  OR NOT (payload_source ?& ARRAY[
    'accessEvidenceSha256', 'canonicalHttpsUrl', 'canonicalText', 'canonicalTextSha256',
    'chunks', 'citationTitle', 'documentId', 'documentIr', 'embeddings',
    'externalEmbeddingAllowed', 'externalGenerationAllowed', 'externalProcessingEligible',
    'licenseEvidenceSha256', 'localProcessingAllowed', 'machineFetchAllowed', 'mimeType',
    'oaSourceCard', 'oaTrackId', 'parserVersion', 'rawContentSha256', 'retrievalTopics',
    'sourceCardSha256', 'sourceId', 'sourceLocator', 'sourceRevisionId', 'sourceRevisionSha256', 'tokenizerVersion'
  ])
  OR jsonb_typeof(payload_source -> 'documentIr') <> 'object'
  OR jsonb_typeof(payload_source -> 'documentId') <> 'string'
  OR jsonb_typeof(payload_source -> 'sourceId') <> 'string'
  OR jsonb_typeof(payload_source -> 'sourceRevisionId') <> 'string'
  OR jsonb_typeof(payload_source -> 'sourceRevisionSha256') <> 'string'
  OR jsonb_typeof(payload_source -> 'rawContentSha256') <> 'string'
  OR jsonb_typeof(payload_source -> 'canonicalTextSha256') <> 'string'
  OR jsonb_typeof(payload_source -> 'canonicalText') <> 'string'
  OR jsonb_typeof(payload_source -> 'mimeType') <> 'string'
  OR jsonb_typeof(payload_source -> 'parserVersion') <> 'string'
  OR jsonb_typeof(payload_source -> 'tokenizerVersion') <> 'string'
  OR jsonb_typeof(payload_source -> 'canonicalHttpsUrl') <> 'string'
  OR jsonb_typeof(payload_source -> 'citationTitle') <> 'string'
  OR jsonb_typeof(payload_source -> 'chunks') <> 'array'
  OR jsonb_typeof(payload_source -> 'embeddings') <> 'array'
  OR jsonb_typeof(payload_source -> 'retrievalTopics') <> 'array'
  OR jsonb_typeof(payload_source -> 'sourceLocator') <> 'object'
  OR jsonb_typeof(payload_source -> 'machineFetchAllowed') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'localProcessingAllowed') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'externalEmbeddingAllowed') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'externalGenerationAllowed') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'externalProcessingEligible') <> 'boolean'
  OR jsonb_typeof(payload_source -> 'sourceCardSha256') NOT IN ('null', 'string')
  OR jsonb_typeof(payload_source -> 'oaTrackId') NOT IN ('null', 'string')
  OR jsonb_typeof(payload_source -> 'oaSourceCard') NOT IN ('null', 'object')
  OR jsonb_typeof(payload_source -> 'licenseEvidenceSha256') NOT IN ('null', 'string')
  OR jsonb_typeof(payload_source -> 'accessEvidenceSha256') NOT IN ('null', 'string')
  OR jsonb_array_length(payload_source -> 'chunks') NOT BETWEEN 1 AND 50000
  OR jsonb_array_length(payload_source -> 'embeddings') <> jsonb_array_length(payload_source -> 'chunks') THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage source payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  payload_document_id := payload_source ->> 'documentId';
  payload_source_id := payload_source ->> 'sourceId';
  payload_source_revision_id := payload_source ->> 'sourceRevisionId';
  payload_source_revision_sha256 := payload_source ->> 'sourceRevisionSha256';
  payload_raw_content_sha256 := payload_source ->> 'rawContentSha256';
  payload_normalized_document_ir_sha256 := payload_source -> 'documentIr' ->> 'normalizedContentSha256';
  payload_canonical_text_sha256 := payload_source ->> 'canonicalTextSha256';
  payload_canonical_text := payload_source ->> 'canonicalText';
  payload_mime_type := payload_source ->> 'mimeType';
  payload_parser_version := payload_source ->> 'parserVersion';
  payload_tokenizer_version := payload_source ->> 'tokenizerVersion';
  payload_document_ir := payload_source -> 'documentIr';
  payload_source_locator := payload_source -> 'sourceLocator';
  payload_canonical_https_url := payload_source ->> 'canonicalHttpsUrl';
  payload_source_card_sha256 := payload_source ->> 'sourceCardSha256';
  payload_oa_track_id := payload_source ->> 'oaTrackId';
  payload_source_card := payload_source -> 'oaSourceCard';
  payload_license_evidence_sha256 := payload_source ->> 'licenseEvidenceSha256';
  payload_access_evidence_sha256 := payload_source ->> 'accessEvidenceSha256';
  payload_machine_fetch_allowed := (payload_source ->> 'machineFetchAllowed')::boolean;
  payload_local_processing_allowed := (payload_source ->> 'localProcessingAllowed')::boolean;
  payload_external_embedding_allowed := (payload_source ->> 'externalEmbeddingAllowed')::boolean;
  payload_external_generation_allowed := (payload_source ->> 'externalGenerationAllowed')::boolean;
  payload_external_processing_eligible := (payload_source ->> 'externalProcessingEligible')::boolean;
  payload_citation_title := payload_source ->> 'citationTitle';
  SELECT coalesce(array_agg(topic.value ORDER BY topic.ordinality), ARRAY[]::text[])
  INTO payload_topics
  FROM jsonb_array_elements_text(payload_source -> 'retrievalTopics') WITH ORDINALITY AS topic(value, ordinality);

  IF payload_document_id !~ '^doc_[a-z0-9][a-z0-9_-]{10,95}$'
     OR payload_source_id !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
     OR payload_source_revision_id !~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'
     OR payload_source_revision_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_raw_content_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_normalized_document_ir_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_canonical_text_sha256 !~ '^[0-9a-f]{64}$'
     OR payload_canonical_text IS NULL
     OR octet_length(payload_canonical_text) NOT BETWEEN 1 AND 16777216
     OR payload_canonical_text_sha256 <> encode(digest(payload_canonical_text, 'sha256'), 'hex')
     OR payload_mime_type IS NULL
     OR payload_parser_version IS NULL
     OR payload_tokenizer_version IS NULL
     OR char_length(payload_mime_type) NOT BETWEEN 3 AND 128
     OR char_length(payload_parser_version) NOT BETWEEN 1 AND 128
     OR char_length(payload_tokenizer_version) NOT BETWEEN 1 AND 128
     OR payload_citation_title IS NULL
     OR char_length(payload_citation_title) NOT BETWEEN 1 AND 500
     OR btrim(payload_citation_title) = ''
     OR payload_citation_title ~ '[[:cntrl:]]'
     OR public.rag_v2_immutable_retrieval_topics_are_valid(payload_topics) IS NOT TRUE
     OR public.rag_v2_immutable_locator_is_valid(payload_source_locator) IS NOT TRUE
     OR public.rag_v2_immutable_public_https_url_is_valid(payload_canonical_https_url) IS NOT TRUE
     OR payload_document_ir ->> 'sourceId' IS DISTINCT FROM payload_source_id
     OR payload_document_ir ->> 'sourceRevisionId' IS DISTINCT FROM payload_source_revision_id
     OR payload_document_ir ->> 'mimeType' IS DISTINCT FROM payload_mime_type
     OR payload_document_ir ->> 'rawContentSha256' IS DISTINCT FROM payload_raw_content_sha256
     OR payload_document_ir ->> 'normalizedContentSha256' IS DISTINCT FROM payload_normalized_document_ir_sha256
     OR payload_document_ir -> 'parserEvidence' ->> 'parserVersion' IS DISTINCT FROM payload_parser_version
     OR public.rag_v2_immutable_document_ir_structure_is_valid(payload_document_ir) IS NOT TRUE THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage source identity is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF (payload_scope = 'EXACT30' AND (
        payload_oa_track_id IS NOT NULL
        OR payload_source_card <> 'null'::jsonb
        OR payload_license_evidence_sha256 IS NOT NULL
        OR payload_access_evidence_sha256 IS NOT NULL
        OR payload_machine_fetch_allowed
        OR NOT payload_local_processing_allowed
        OR NOT payload_external_embedding_allowed
        OR NOT payload_external_generation_allowed
        OR NOT payload_external_processing_eligible
        OR payload_source_card_sha256 IS NULL
        OR payload_source_card_sha256 !~ '^[0-9a-f]{64}$'
        OR public.rag_v2_immutable_external_exact30_voyage_source_is_approved(
          payload_source_id,
          payload_canonical_https_url,
          payload_raw_content_sha256,
          payload_source_card_sha256
        ) IS NOT TRUE
      ))
     OR (payload_scope = 'OA112' AND (
        payload_oa_track_id IS NULL
        OR payload_source_card IS NULL
        OR jsonb_typeof(payload_source_card) <> 'object'
        OR public.rag_v2_immutable_oa_source_card_v4_is_valid(payload_source_card) IS NOT TRUE
        OR payload_license_evidence_sha256 !~ '^[0-9a-f]{64}$'
        OR payload_access_evidence_sha256 !~ '^[0-9a-f]{64}$'
        OR NOT payload_machine_fetch_allowed
        OR NOT payload_local_processing_allowed
        OR NOT payload_external_embedding_allowed
        OR NOT payload_external_generation_allowed
        OR payload_source_card ->> 'sourceId' IS DISTINCT FROM payload_source_id
        OR payload_source_card ->> 'canonicalUrl' IS DISTINCT FROM payload_canonical_https_url
        OR payload_source_card ->> 'rawContentSha256' IS DISTINCT FROM payload_raw_content_sha256
        OR payload_source_card ->> 'mimeType' IS DISTINCT FROM payload_mime_type
        OR payload_source_card ->> 'licenseEvidenceDigest' IS DISTINCT FROM payload_license_evidence_sha256
        OR payload_source_card -> 'accessEvidence' ->> 'accessEvidenceDigest' IS DISTINCT FROM payload_access_evidence_sha256
        OR payload_source_card -> 'accessEvidence' ->> 'verificationState' <> 'VERIFIED'
        OR payload_source_card ->> 'activeOa112Eligible' <> 'true'
        OR payload_source_card_sha256 IS NOT NULL
      )) THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage scope metadata is invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('rag-v2-immutable-public-voyage|' || payload_generation_id, 0)
  );
  SELECT * INTO expected_generation_record
  FROM public.rag_v2_immutable_component_generations
  WHERE component_generation_id = payload_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_component_generations (
      component_generation_id, owner_user_id, component_scope, embedding_profile_id, state,
      evaluation_status, expected_source_count, expected_chunk_count, actual_source_count,
      actual_chunk_count, generation_hash, manifest_hash
    ) VALUES (
      payload_generation_id, NULL, payload_scope, 'voyage_context_4_1024_v1', 'STAGING',
      'PENDING', payload_expected_source_count, payload_expected_chunk_count, 0,
      0, payload_generation_hash, payload_manifest_hash
    );
  ELSIF expected_generation_record.owner_user_id IS NOT NULL
     OR expected_generation_record.component_scope <> payload_scope
     OR expected_generation_record.embedding_profile_id <> 'voyage_context_4_1024_v1'
     OR expected_generation_record.state <> 'STAGING'
     OR expected_generation_record.evaluation_status <> 'PENDING'
     OR expected_generation_record.expected_source_count <> payload_expected_source_count
     OR expected_generation_record.expected_chunk_count <> payload_expected_chunk_count
     OR expected_generation_record.generation_hash <> payload_generation_hash
     OR expected_generation_record.manifest_hash <> payload_manifest_hash THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage component conflicts'
      USING ERRCODE = '23505';
  END IF;

  SELECT * INTO expected_manifest_record
  FROM public.rag_v2_immutable_public_voyage_component_manifests
  WHERE component_generation_id = payload_generation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_public_voyage_component_manifests (
      component_generation_id, component_scope, embedding_profile_id, member_digests,
      manifest_hash, generation_hash
    ) VALUES (
      payload_generation_id, payload_scope, 'voyage_context_4_1024_v1', payload_member_digests,
      payload_manifest_hash, payload_generation_hash
    );
  ELSIF expected_manifest_record.component_scope <> payload_scope
     OR expected_manifest_record.embedding_profile_id <> 'voyage_context_4_1024_v1'
     OR expected_manifest_record.member_digests IS DISTINCT FROM payload_member_digests
     OR expected_manifest_record.manifest_hash <> payload_manifest_hash
     OR expected_manifest_record.generation_hash <> payload_generation_hash THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage member manifest conflicts'
      USING ERRCODE = '23505';
  END IF;

  SELECT run.state INTO existing_run_state
  FROM public.rag_v2_immutable_materialization_runs AS run
  WHERE run.materialization_run_id = payload_run_id
    AND run.owner_user_id IS NULL
    AND run.component_generation_id = payload_generation_id
    AND run.component_scope = payload_scope
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.rag_v2_immutable_materialization_runs (
      materialization_run_id, owner_user_id, component_generation_id, component_scope, document_id, state
    ) VALUES (payload_run_id, NULL, payload_generation_id, payload_scope, NULL, 'OPEN');
  ELSIF existing_run_state NOT IN ('OPEN', 'STAGED') THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage run is not resumable'
      USING ERRCODE = '23505';
  END IF;

  -- generation lock alone cannot serialize two refresh generations that carry the
  -- same immutable source. Lock the scope-qualified identity before lookup so the
  -- second transaction observes the first committed source and takes the reuse path.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'rag-v2-immutable-public-voyage-source|' || payload_scope || '|' || payload_source_revision_id,
      0
    )
  );
  SELECT * INTO expected_source_record
  FROM public.rag_v2_immutable_source_revisions
  WHERE source_revision_id = payload_source_revision_id
  FOR UPDATE;
  IF FOUND THEN
    source_was_reused := true;
    IF expected_source_record.owner_user_id IS NOT NULL
       OR expected_source_record.document_id <> payload_document_id
       OR expected_source_record.source_id <> payload_source_id
       OR expected_source_record.source_scope <> payload_scope
       OR expected_source_record.source_revision_sha256 <> payload_source_revision_sha256
       OR expected_source_record.raw_content_sha256 <> payload_raw_content_sha256
       OR expected_source_record.normalized_document_ir_sha256 <> payload_normalized_document_ir_sha256
       OR expected_source_record.canonical_text_sha256 <> payload_canonical_text_sha256
       OR expected_source_record.document_ir <> payload_document_ir
       OR expected_source_record.canonical_text <> payload_canonical_text
       OR expected_source_record.source_locator <> payload_source_locator
       OR expected_source_record.canonical_https_url <> payload_canonical_https_url
       OR expected_source_record.exact30_source_card_sha256 IS DISTINCT FROM
          (CASE WHEN payload_scope = 'EXACT30' THEN payload_source_card_sha256 ELSE NULL END)
       OR expected_source_record.mime_type <> payload_mime_type
       OR expected_source_record.machine_fetch_allowed <> payload_machine_fetch_allowed
       OR expected_source_record.local_processing_allowed <> payload_local_processing_allowed
       OR expected_source_record.external_embedding_allowed <> payload_external_embedding_allowed
       OR expected_source_record.external_generation_allowed <> payload_external_generation_allowed
       OR expected_source_record.external_processing_eligible <> payload_external_processing_eligible
       OR expected_source_record.parser_version <> payload_parser_version
       OR expected_source_record.tokenizer_version <> payload_tokenizer_version
       OR expected_source_record.retrieval_topics <> payload_topics
       OR expected_source_record.citation_title <> payload_citation_title
       OR expected_source_record.oa_track_id IS DISTINCT FROM
          (CASE WHEN payload_scope = 'OA112' THEN payload_oa_track_id ELSE NULL END)
       OR expected_source_record.reserve_source THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage source revision conflicts'
        USING ERRCODE = '23505';
    END IF;
    SELECT COUNT(*)::integer INTO existing_membership_count
    FROM public.rag_v2_immutable_generation_memberships AS membership
    WHERE membership.component_generation_id = payload_generation_id
      AND membership.source_revision_id = payload_source_revision_id
      AND membership.component_scope = payload_scope;
  END IF;

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    observed_chunk_count := observed_chunk_count + 1;
    IF jsonb_typeof(payload_chunk) <> 'object'
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(payload_chunk) AS chunk_key
         WHERE chunk_key NOT IN (
           'canonicalText', 'canonicalTextSha256', 'chunkId', 'chunkOrdinal',
           'containsTable', 'headingPath', 'locator', 'tokenCount'
         )
       )
       OR NOT (payload_chunk ?& ARRAY[
         'canonicalText', 'canonicalTextSha256', 'chunkId', 'chunkOrdinal',
         'containsTable', 'headingPath', 'locator', 'tokenCount'
       ])
       OR jsonb_typeof(payload_chunk -> 'headingPath') <> 'array'
       OR jsonb_typeof(payload_chunk -> 'locator') <> 'object'
       OR jsonb_typeof(payload_chunk -> 'chunkOrdinal') <> 'number'
       OR jsonb_typeof(payload_chunk -> 'containsTable') <> 'boolean'
       OR jsonb_typeof(payload_chunk -> 'tokenCount') <> 'number'
       OR (payload_chunk -> 'chunkOrdinal')::text !~ '^(0|[1-9][0-9]*)$'
       OR (payload_chunk -> 'tokenCount')::text !~ '^(0|[1-9][0-9]*)$'
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(payload_chunk -> 'headingPath') AS heading(value)
         WHERE jsonb_typeof(heading.value) <> 'string'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage chunk is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_chunk_id := payload_chunk ->> 'chunkId';
    payload_chunk_ordinal := (payload_chunk ->> 'chunkOrdinal')::integer;
    payload_chunk_text := payload_chunk ->> 'canonicalText';
    payload_chunk_sha256 := payload_chunk ->> 'canonicalTextSha256';
    payload_chunk_locator := payload_chunk -> 'locator';
    payload_chunk_token_count := (payload_chunk ->> 'tokenCount')::integer;
    payload_chunk_contains_table := (payload_chunk ->> 'containsTable')::boolean;
    SELECT coalesce(array_agg(heading.value ORDER BY heading.ordinality), ARRAY[]::text[])
    INTO payload_chunk_heading_path
    FROM jsonb_array_elements_text(payload_chunk -> 'headingPath') WITH ORDINALITY AS heading(value, ordinality);
    IF payload_chunk_id !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR payload_chunk_ordinal <> observed_chunk_count
       OR payload_chunk_text IS NULL
       OR payload_chunk_sha256 !~ '^[0-9a-f]{64}$'
       OR payload_chunk_sha256 <> encode(digest(payload_chunk_text, 'sha256'), 'hex')
       OR payload_chunk_token_count NOT BETWEEN 1 AND 600
       OR cardinality(payload_chunk_heading_path) > 12
       OR public.rag_v2_immutable_locator_is_valid(payload_chunk_locator) IS NOT TRUE THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage chunk contract is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF first_chunk_locator IS NULL THEN
      first_chunk_locator := payload_chunk_locator;
    END IF;
    IF observed_chunk_count = 1 THEN
      observed_source_text := payload_chunk_text;
    ELSE
      observed_source_text := observed_source_text || E'\n\n' || payload_chunk_text;
    END IF;
  END LOOP;
  IF first_chunk_locator IS NULL
     OR payload_source_locator <> first_chunk_locator
     OR payload_canonical_text <> observed_source_text THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage source projection is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF source_was_reused THEN
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(payload_source -> 'chunks') AS supplied(value)
      LEFT JOIN public.rag_v2_immutable_chunks AS stored
        ON stored.chunk_id = supplied.value ->> 'chunkId'
       AND stored.source_revision_id = payload_source_revision_id
       AND stored.owner_user_id IS NULL
       AND stored.source_scope = payload_scope
      WHERE stored.chunk_id IS NULL
         OR stored.chunk_ordinal IS DISTINCT FROM (supplied.value ->> 'chunkOrdinal')::integer
         OR to_jsonb(stored.heading_path) IS DISTINCT FROM supplied.value -> 'headingPath'
         OR stored.locator IS DISTINCT FROM supplied.value -> 'locator'
         OR stored.canonical_text IS DISTINCT FROM supplied.value ->> 'canonicalText'
         OR stored.canonical_text_sha256 IS DISTINCT FROM supplied.value ->> 'canonicalTextSha256'
         OR stored.token_count IS DISTINCT FROM (supplied.value ->> 'tokenCount')::integer
         OR stored.contains_table IS DISTINCT FROM (supplied.value ->> 'containsTable')::boolean
    )
    OR (
      SELECT COUNT(*)::integer
      FROM public.rag_v2_immutable_chunks AS stored
      WHERE stored.source_revision_id = payload_source_revision_id
        AND stored.owner_user_id IS NULL
        AND stored.source_scope = payload_scope
    ) <> observed_chunk_count
    OR (
      payload_scope = 'OA112' AND NOT EXISTS (
        SELECT 1
        FROM public.rag_v2_immutable_oa_source_cards AS card
        WHERE card.source_revision_id = payload_source_revision_id
          AND card.source_scope = 'OA112'
          AND card.source_card = payload_source_card
      )
    ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage source cache conflicts'
        USING ERRCODE = '23505';
    END IF;
  ELSE
    INSERT INTO public.rag_v2_immutable_source_revisions (
      source_revision_id, document_id, source_id, owner_user_id, source_scope, oa_track_id,
      reserve_source, source_revision_sha256, raw_content_sha256, normalized_document_ir_sha256,
      canonical_text_sha256, document_ir, canonical_text, sanitized_display_name, source_locator,
      canonical_https_url, exact30_source_card_sha256, license_evidence_sha256, access_evidence_sha256, mime_type,
      machine_fetch_allowed, local_processing_allowed, external_embedding_allowed,
      external_generation_allowed, external_processing_eligible, parser_version, tokenizer_version,
      retrieval_topics, citation_title
    ) VALUES (
      payload_source_revision_id, payload_document_id, payload_source_id, NULL, payload_scope,
      CASE WHEN payload_scope = 'OA112' THEN payload_oa_track_id ELSE NULL END,
      false, payload_source_revision_sha256, payload_raw_content_sha256, payload_normalized_document_ir_sha256,
      payload_canonical_text_sha256, payload_document_ir, payload_canonical_text, NULL, payload_source_locator,
      payload_canonical_https_url,
      CASE WHEN payload_scope = 'EXACT30' THEN payload_source_card_sha256 ELSE NULL END,
      CASE WHEN payload_scope = 'OA112' THEN payload_license_evidence_sha256 ELSE NULL END,
      CASE WHEN payload_scope = 'OA112' THEN payload_access_evidence_sha256 ELSE NULL END,
      payload_mime_type, payload_machine_fetch_allowed, payload_local_processing_allowed,
      payload_external_embedding_allowed, payload_external_generation_allowed,
      payload_external_processing_eligible, payload_parser_version, payload_tokenizer_version,
      payload_topics, payload_citation_title
    );
    IF payload_scope = 'OA112' THEN
      INSERT INTO public.rag_v2_immutable_oa_source_cards (
        source_revision_id, source_scope, source_id, source_card, source_card_sha256,
        active_oa112_eligible, title, authors, canonical_https_url, canonical_https_url_sha256,
        identifier_scheme, identifier_value, revision, revision_date, raw_content_sha256, mime_type,
        license_evidence_sha256, access_evidence_sha256, access_checked_at, access_verification_state,
        machine_fetch_allowed, local_processing_allowed, external_embedding_allowed, external_generation_allowed
      ) VALUES (
        payload_source_revision_id, 'OA112', payload_source_id, payload_source_card,
        encode(digest(payload_source_card::text, 'sha256'), 'hex'),
        (payload_source_card ->> 'activeOa112Eligible')::boolean, payload_source_card ->> 'title',
        ARRAY(SELECT value FROM jsonb_array_elements_text(payload_source_card -> 'authors') AS authors(value)),
        payload_canonical_https_url, payload_source_card ->> 'canonicalUrlSha256',
        payload_source_card -> 'identifier' ->> 'scheme', payload_source_card -> 'identifier' ->> 'value',
        payload_source_card ->> 'revision', (payload_source_card ->> 'revisionDate')::date,
        payload_raw_content_sha256, payload_mime_type, payload_license_evidence_sha256,
        payload_access_evidence_sha256, payload_source_card -> 'accessEvidence' ->> 'accessCheckedAt',
        payload_source_card -> 'accessEvidence' ->> 'verificationState', payload_machine_fetch_allowed,
        payload_local_processing_allowed, payload_external_embedding_allowed, payload_external_generation_allowed
      );
    END IF;

    FOR payload_chunk IN
      SELECT value
      FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
      ORDER BY ordinality
    LOOP
      SELECT coalesce(array_agg(heading.value ORDER BY heading.ordinality), ARRAY[]::text[])
      INTO payload_chunk_heading_path
      FROM jsonb_array_elements_text(payload_chunk -> 'headingPath') WITH ORDINALITY AS heading(value, ordinality);
      INSERT INTO public.rag_v2_immutable_chunks (
        chunk_id, source_revision_id, owner_user_id, source_scope, chunk_ordinal, heading_path,
        locator, canonical_text, canonical_text_sha256, token_count, contains_table
      ) VALUES (
        payload_chunk ->> 'chunkId', payload_source_revision_id, NULL, payload_scope,
        (payload_chunk ->> 'chunkOrdinal')::integer, payload_chunk_heading_path,
        payload_chunk -> 'locator', payload_chunk ->> 'canonicalText', payload_chunk ->> 'canonicalTextSha256',
        (payload_chunk ->> 'tokenCount')::integer, (payload_chunk ->> 'containsTable')::boolean
      );
    END LOOP;
  END IF;

  IF source_was_reused AND existing_membership_count > 0 THEN
    IF existing_membership_count <> observed_chunk_count
       OR (
         SELECT COUNT(*)
         FROM public.rag_v2_immutable_generation_embeddings AS embedding
         WHERE embedding.component_generation_id = payload_generation_id
           AND embedding.component_scope = payload_scope
           AND embedding.chunk_id IN (
             SELECT membership.chunk_id
             FROM public.rag_v2_immutable_generation_memberships AS membership
             WHERE membership.component_generation_id = payload_generation_id
               AND membership.source_revision_id = payload_source_revision_id
               AND membership.component_scope = payload_scope
           )
       ) <> existing_membership_count THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage source resume is incomplete'
        USING ERRCODE = '23505';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(payload_source -> 'embeddings') AS supplied(value)
      LEFT JOIN public.rag_v2_immutable_generation_embeddings AS stored
        ON stored.component_generation_id = payload_generation_id
       AND stored.chunk_id = supplied.value ->> 'chunkId'
       AND stored.component_scope = payload_scope
       AND stored.owner_user_id IS NULL
      WHERE stored.chunk_id IS NULL
         OR stored.embedding_input_hash IS DISTINCT FROM supplied.value ->> 'embeddingInputHash'
         OR stored.context_set_hash IS DISTINCT FROM supplied.value ->> 'contextSetHash'
    ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage source resume embedding conflicts'
        USING ERRCODE = '23505';
    END IF;
    payload_source_member_digest := public.rag_v2_immutable_public_voyage_source_member_digest(
      payload_generation_id,
      payload_source_revision_id
    );
    IF payload_source_member_digest IS NULL
       OR array_position(payload_member_digests, payload_source_member_digest) IS NULL THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage resumed source is outside the bound member manifest'
        USING ERRCODE = '23514';
    END IF;
    SELECT COUNT(DISTINCT membership.source_revision_id)::integer, COUNT(*)::integer
    INTO observed_source_total, observed_chunk_total
    FROM public.rag_v2_immutable_generation_memberships AS membership
    WHERE membership.component_generation_id = payload_generation_id
      AND membership.component_scope = payload_scope;
    RETURN QUERY SELECT payload_generation_id, payload_run_id,
      CASE WHEN observed_source_total = payload_expected_source_count AND observed_chunk_total = payload_expected_chunk_count THEN 'STAGED' ELSE 'STAGING' END,
      true, observed_source_total, observed_chunk_total;
    RETURN;
  END IF;

  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    INSERT INTO public.rag_v2_immutable_generation_memberships (
      component_generation_id, chunk_id, source_revision_id, owner_user_id, component_scope, ordinal
    ) VALUES (
      payload_generation_id, payload_chunk ->> 'chunkId', payload_source_revision_id, NULL,
      payload_scope,
      (
        SELECT COUNT(*)::integer
        FROM public.rag_v2_immutable_generation_memberships AS previous_membership
        WHERE previous_membership.component_generation_id = payload_generation_id
      ) + 1
    );
  END LOOP;

  FOR payload_embedding IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'embeddings') WITH ORDINALITY AS embeddings(value, ordinality)
    ORDER BY ordinality
  LOOP
    observed_embedding_count := observed_embedding_count + 1;
    IF jsonb_typeof(payload_embedding) <> 'object'
       OR EXISTS (
         SELECT 1 FROM jsonb_object_keys(payload_embedding) AS embedding_key
         WHERE embedding_key NOT IN ('chunkId', 'contextSetHash', 'embedding', 'embeddingInputHash')
       )
       OR NOT (payload_embedding ?& ARRAY['chunkId', 'contextSetHash', 'embedding', 'embeddingInputHash'])
       OR jsonb_typeof(payload_embedding -> 'chunkId') <> 'string'
       OR jsonb_typeof(payload_embedding -> 'contextSetHash') <> 'string'
       OR jsonb_typeof(payload_embedding -> 'embeddingInputHash') <> 'string'
       OR jsonb_typeof(payload_embedding -> 'embedding') <> 'array'
       OR jsonb_array_length(payload_embedding -> 'embedding') <> 1024
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(payload_embedding -> 'embedding') AS coordinate(value)
         WHERE jsonb_typeof(coordinate.value) <> 'number'
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage embedding is invalid'
        USING ERRCODE = '22023';
    END IF;
    payload_chunk_id := payload_embedding ->> 'chunkId';
    payload_embedding_input_hash := payload_embedding ->> 'embeddingInputHash';
    payload_context_set_hash := payload_embedding ->> 'contextSetHash';
    IF payload_chunk_id !~ '^rag_v2_chk_[0-9a-f]{32}$'
       OR payload_embedding_input_hash !~ '^[0-9a-f]{64}$'
       OR payload_context_set_hash !~ '^[0-9a-f]{64}$'
       OR NOT EXISTS (
         SELECT 1 FROM public.rag_v2_immutable_generation_memberships AS membership
         WHERE membership.component_generation_id = payload_generation_id
           AND membership.chunk_id = payload_chunk_id
           AND membership.source_revision_id = payload_source_revision_id
           AND membership.component_scope = payload_scope
       ) THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage embedding identity is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF expected_context_set_hash IS NULL THEN
      expected_context_set_hash := payload_context_set_hash;
    ELSIF payload_context_set_hash IS DISTINCT FROM expected_context_set_hash THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage source context group drifted'
        USING ERRCODE = '23514';
    END IF;
    payload_embedding_vector := ((payload_embedding -> 'embedding')::text)::vector;
    IF vector_dims(payload_embedding_vector) <> 1024
       OR vector_norm(payload_embedding_vector)::text IN ('NaN', 'Infinity', '-Infinity')
       OR abs(vector_norm(payload_embedding_vector)::double precision - 1.0) > 0.00001 THEN
      RAISE EXCEPTION 'immutable RAG v2 public Voyage vector is invalid'
        USING ERRCODE = '22023';
    END IF;
    -- 다른 generation이 같은 immutable chunk/profile cache를 동시에 채우면 one writer만 NEW로
    -- 기록하고 나머지는 같은 cached vector를 REUSED로 참조하게 source+hash key로 직렬화한다.
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'rag-v2-immutable-public-voyage-cache|' || payload_scope || '|' ||
        payload_chunk_id || '|' || payload_embedding_input_hash || '|' || payload_context_set_hash,
        0
      )
    );
    SELECT cache.embedding
    INTO cached_embedding_vector
    FROM public.rag_v2_immutable_embedding_cache AS cache
    WHERE cache.owner_user_id IS NULL
      AND cache.chunk_id = payload_chunk_id
      AND cache.source_scope = payload_scope
      AND cache.embedding_profile_id = 'voyage_context_4_1024_v1'
      AND cache.embedding_input_hash = payload_embedding_input_hash
      AND cache.context_set_hash = payload_context_set_hash
    FOR SHARE;
    embedding_was_reused := FOUND;
    IF embedding_was_reused THEN
      payload_embedding_vector := cached_embedding_vector;
      reused_embedding_count := reused_embedding_count + 1;
    END IF;
    INSERT INTO public.rag_v2_immutable_generation_embeddings (
      component_generation_id, chunk_id, owner_user_id, component_scope, embedding_profile_id,
      embedding_input_hash, context_set_hash, embedding
    ) VALUES (
      payload_generation_id, payload_chunk_id, NULL, payload_scope, 'voyage_context_4_1024_v1',
      payload_embedding_input_hash, payload_context_set_hash, payload_embedding_vector
    );
    IF NOT embedding_was_reused THEN
      INSERT INTO public.rag_v2_immutable_embedding_cache (
        cache_id, owner_user_id, source_revision_id, chunk_id, source_scope, embedding_profile_id,
        embedding_input_hash, context_set_hash, embedding
      ) VALUES (
        'rgr_cache_' || substr(
          encode(digest('rag-v2-immutable-public-voyage-cache|' || payload_generation_id || '|' || payload_chunk_id || '|' || payload_context_set_hash, 'sha256'), 'hex'),
          1, 32
        ),
        NULL, payload_source_revision_id, payload_chunk_id, payload_scope, 'voyage_context_4_1024_v1',
        payload_embedding_input_hash, payload_context_set_hash, payload_embedding_vector
      );
    END IF;
    INSERT INTO public.rag_v2_immutable_embedding_receipts (
      receipt_id, materialization_run_id, owner_user_id, source_scope, component_generation_id,
      chunk_id, embedding_profile_id, embedding_input_hash, context_set_hash, reuse_state
    ) VALUES (
      'rgr_emb_' || substr(
        encode(digest('rag-v2-immutable-public-voyage-embedding-receipt|' || payload_run_id || '|' || payload_chunk_id, 'sha256'), 'hex'),
        1, 32
      ),
      payload_run_id, NULL, payload_scope, payload_generation_id, payload_chunk_id,
      'voyage_context_4_1024_v1', payload_embedding_input_hash, payload_context_set_hash,
      CASE WHEN embedding_was_reused THEN 'REUSED' ELSE 'NEW' END
    );
  END LOOP;
  IF observed_embedding_count <> observed_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage embedding count is invalid'
      USING ERRCODE = '22023';
  END IF;
  payload_source_member_digest := public.rag_v2_immutable_public_voyage_source_member_digest(
    payload_generation_id,
    payload_source_revision_id
  );
  IF payload_source_member_digest IS NULL
     OR array_position(payload_member_digests, payload_source_member_digest) IS NULL THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage source is outside the bound member manifest'
      USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.rag_v2_immutable_source_receipts (
    receipt_id, materialization_run_id, owner_user_id, source_scope, source_revision_id,
    raw_content_sha256, canonical_text_sha256, reuse_state
  ) VALUES (
    'rgr_src_' || substr(
      encode(digest('rag-v2-immutable-public-voyage-source-receipt|' || payload_run_id || '|' || payload_source_revision_id, 'sha256'), 'hex'),
      1, 32
    ),
    payload_run_id, NULL, payload_scope, payload_source_revision_id,
    payload_raw_content_sha256, payload_canonical_text_sha256,
    CASE WHEN source_was_reused THEN 'REUSED' ELSE 'NEW' END
  );
  FOR payload_chunk IN
    SELECT value
    FROM jsonb_array_elements(payload_source -> 'chunks') WITH ORDINALITY AS chunks(value, ordinality)
    ORDER BY ordinality
  LOOP
    INSERT INTO public.rag_v2_immutable_chunk_receipts (
      receipt_id, materialization_run_id, owner_user_id, source_scope, source_revision_id,
      chunk_id, canonical_text_sha256, reuse_state
    ) VALUES (
      'rgr_chk_' || substr(
        encode(digest('rag-v2-immutable-public-voyage-chunk-receipt|' || payload_run_id || '|' || (payload_chunk ->> 'chunkId'), 'sha256'), 'hex'),
        1, 32
      ),
      payload_run_id, NULL, payload_scope, payload_source_revision_id,
      payload_chunk ->> 'chunkId', payload_chunk ->> 'canonicalTextSha256',
      CASE WHEN source_was_reused THEN 'REUSED' ELSE 'NEW' END
    );
  END LOOP;

  UPDATE public.rag_v2_immutable_materialization_runs AS run
  SET source_reused_count = run.source_reused_count + CASE WHEN source_was_reused THEN 1 ELSE 0 END,
      chunk_reused_count = run.chunk_reused_count + CASE WHEN source_was_reused THEN observed_chunk_count ELSE 0 END,
      embedding_reused_count = run.embedding_reused_count + reused_embedding_count
  WHERE run.materialization_run_id = payload_run_id
    AND run.owner_user_id IS NULL
    AND run.component_scope = payload_scope
    AND run.state = 'OPEN';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage reuse receipt transition failed'
      USING ERRCODE = '23514';
  END IF;

  SELECT COUNT(DISTINCT membership.source_revision_id)::integer, COUNT(*)::integer
  INTO observed_source_total, observed_chunk_total
  FROM public.rag_v2_immutable_generation_memberships AS membership
  WHERE membership.component_generation_id = payload_generation_id
    AND membership.component_scope = payload_scope;
  IF observed_source_total > payload_expected_source_count
     OR observed_chunk_total > payload_expected_chunk_count THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage component exceeded exact membership'
      USING ERRCODE = '23514';
  END IF;
  UPDATE public.rag_v2_immutable_component_generations
  SET actual_source_count = observed_source_total,
      actual_chunk_count = observed_chunk_total
  WHERE component_generation_id = payload_generation_id
    AND owner_user_id IS NULL
    AND component_scope = payload_scope
    AND state = 'STAGING'
    AND evaluation_status = 'PENDING';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 public Voyage component transition failed'
      USING ERRCODE = '23514';
  END IF;
  IF observed_source_total = payload_expected_source_count
     AND observed_chunk_total = payload_expected_chunk_count THEN
    complete_state := 'STAGED';
    UPDATE public.rag_v2_immutable_materialization_runs
    SET state = 'STAGED'
    WHERE materialization_run_id = payload_run_id
      AND owner_user_id IS NULL
      AND component_scope = payload_scope
      AND state = 'OPEN';
  END IF;
  RETURN QUERY SELECT payload_generation_id, payload_run_id, complete_state,
    source_was_reused, observed_source_total, observed_chunk_total;
END;
$_$;


ALTER FUNCTION public.stage_rag_v2_immutable_public_voyage_document(p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.stage_rag_v2_immutable_voyage_document_batch(p_payload jsonb) RETURNS TABLE(batch_plan_sha256 text, batch_id text, state text, batch_reused boolean, completed_batch_count integer, staged_vector_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  payload_plan jsonb;
  payload_batch jsonb;
  payload_vectors jsonb;
  item jsonb;
  observed_vector_count integer;
  payload_vector_set_sha256 text;
  existing_batch public.rag_v2_immutable_voyage_document_batches%ROWTYPE;
  reused boolean := false;
  complete_count integer;
  vector_count integer;
  aggregate_token_count bigint;
  aggregate_chunk_count bigint;
  aggregate_group_count bigint;
  observed_group_count bigint;
  observed_source_count integer;
  distinct_ordinal_count integer;
  minimum_ordinal integer;
  maximum_ordinal integer;
  minimum_batch_count integer;
  maximum_batch_count integer;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_writer'
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(p_payload)) <> 5
     OR NOT (p_payload ?& ARRAY['schemaVersion','plan','batch','packetSha256','vectors'])
     OR p_payload ->> 'schemaVersion' <> 'pre-s5-voyage-document-batch-stage/v1'
     OR jsonb_typeof(p_payload -> 'plan') <> 'object'
     OR jsonb_typeof(p_payload -> 'batch') <> 'object'
     OR jsonb_typeof(p_payload -> 'vectors') <> 'array' THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch stage payload is invalid' USING ERRCODE = '22023';
  END IF;
  payload_plan := p_payload -> 'plan';
  payload_batch := p_payload -> 'batch';
  payload_vectors := p_payload -> 'vectors';
  IF (SELECT count(*) FROM jsonb_object_keys(payload_plan)) <> 8
     OR NOT (payload_plan ?& ARRAY[
       'batchPlanSha256','officialTokenizerSha256','sourceCount','chunkCount','tokenCount',
       'batchCount','ownerScopeSha256','ownerPrivateOrderedGroupCount'
     ])
     OR payload_plan ->> 'batchPlanSha256' !~ '^[0-9a-f]{64}$'
     OR payload_plan ->> 'officialTokenizerSha256' !~ '^[0-9a-f]{64}$'
     OR (payload_plan ->> 'sourceCount')::integer <> 142
     OR (payload_plan ->> 'chunkCount')::integer < 142
     OR (payload_plan ->> 'tokenCount')::integer NOT BETWEEN 1 AND 100000000
     OR (payload_plan ->> 'batchCount')::integer NOT BETWEEN 1 AND 10000
     OR payload_plan -> 'ownerScopeSha256' <> 'null'::jsonb
     OR (payload_plan ->> 'ownerPrivateOrderedGroupCount')::integer <> 0 THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch plan is invalid' USING ERRCODE = '22023';
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(payload_batch)) <> 9
     OR NOT (payload_batch ?& ARRAY[
       'batchId','batchManifestSha256','batchOrdinal','batchCount','tokenCount','chunkCount',
       'groupCount','estimatedResponseBytes','vectorSetSha256'
     ])
     OR payload_batch ->> 'batchId' !~ '^ps5_voyage_doc_[0-9]{4}_[0-9a-f]{16}$'
     OR payload_batch ->> 'batchManifestSha256' !~ '^[0-9a-f]{64}$'
     OR payload_batch ->> 'vectorSetSha256' !~ '^[0-9a-f]{64}$'
     OR (payload_batch ->> 'batchCount')::integer <> (payload_plan ->> 'batchCount')::integer
     OR (payload_batch ->> 'batchOrdinal')::integer NOT BETWEEN 1 AND (payload_plan ->> 'batchCount')::integer
     OR (payload_batch ->> 'tokenCount')::integer NOT BETWEEN 1 AND 110000
     OR (payload_batch ->> 'chunkCount')::integer NOT BETWEEN 1 AND 672
     OR (payload_batch ->> 'groupCount')::integer NOT BETWEEN 1 AND 1000
     OR (payload_batch ->> 'estimatedResponseBytes')::integer
        <> 262144 + (payload_batch ->> 'chunkCount')::integer * 24576
     OR (payload_batch ->> 'estimatedResponseBytes')::integer NOT BETWEEN 286720 AND 16777216
     OR p_payload ->> 'packetSha256' !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch identity is invalid' USING ERRCODE = '22023';
  END IF;
  observed_vector_count := jsonb_array_length(payload_vectors);
  IF observed_vector_count <> (payload_batch ->> 'chunkCount')::integer
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(payload_vectors) AS vector_row(value)
       WHERE jsonb_typeof(vector_row.value) <> 'object'
          OR (SELECT count(*) FROM jsonb_object_keys(vector_row.value)) <> 9
          OR NOT (vector_row.value ?& ARRAY[
            'componentScope','sourceId','sourceRevisionId','chunkId','embeddingInputHash',
            'contextSetHash','vectorSha256','vector','chunkOrdinal'
          ])
          OR vector_row.value ->> 'componentScope' NOT IN ('EXACT30','OA112')
          OR vector_row.value ->> 'sourceId' !~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'
          OR vector_row.value ->> 'sourceRevisionId' !~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'
          OR vector_row.value ->> 'chunkId' !~ '^rag_v2_chk_[0-9a-f]{32}$'
          OR vector_row.value ->> 'embeddingInputHash' !~ '^[0-9a-f]{64}$'
          OR vector_row.value ->> 'contextSetHash' !~ '^[0-9a-f]{64}$'
          OR vector_row.value ->> 'vectorSha256' !~ '^[0-9a-f]{64}$'
          OR jsonb_typeof(vector_row.value -> 'vector') <> 'array'
          OR jsonb_array_length(vector_row.value -> 'vector') <> 1024
          OR (vector_row.value ->> 'chunkOrdinal')::integer < 1
     )
     OR observed_vector_count <> (
       SELECT count(DISTINCT vector_row.value ->> 'chunkId')
       FROM jsonb_array_elements(payload_vectors) AS vector_row(value)
     ) THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch vectors are invalid' USING ERRCODE = '22023';
  END IF;
  payload_vector_set_sha256 := payload_batch ->> 'vectorSetSha256';
  IF NOT EXISTS (
    SELECT 1
    FROM public.rag_v2_immutable_voyage_usage_reservations AS reservation
    JOIN public.rag_v2_immutable_voyage_usage_outcomes AS outcome
      ON outcome.usage_event_id = reservation.usage_event_id
     AND outcome.packet_sha256 = reservation.packet_sha256
     AND outcome.state = 'COMMITTED'
    WHERE reservation.packet_sha256 = p_payload ->> 'packetSha256'
      AND reservation.bundle_manifest_sha256 = payload_batch ->> 'batchManifestSha256'
      AND reservation.official_tokenizer_sha256 = payload_plan ->> 'officialTokenizerSha256'
      AND reservation.byte_cap >= (payload_batch ->> 'estimatedResponseBytes')::integer
      AND outcome.expected_input_tokens = (payload_batch ->> 'tokenCount')::integer
  ) THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch usage outcome is absent' USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.rag_v2_immutable_voyage_document_batch_plans (
    batch_plan_sha256, official_tokenizer_sha256, expected_source_count, expected_chunk_count,
    expected_token_count, expected_batch_count, owner_scope_sha256, owner_private_ordered_group_count
  ) VALUES (
    payload_plan ->> 'batchPlanSha256', payload_plan ->> 'officialTokenizerSha256',
    (payload_plan ->> 'sourceCount')::integer, (payload_plan ->> 'chunkCount')::integer,
    (payload_plan ->> 'tokenCount')::integer, (payload_plan ->> 'batchCount')::integer,
    NULL, (payload_plan ->> 'ownerPrivateOrderedGroupCount')::integer
  ) ON CONFLICT ON CONSTRAINT rag_v2_immutable_voyage_document_batch_plans_pkey DO NOTHING;
  IF NOT EXISTS (
    SELECT 1 FROM public.rag_v2_immutable_voyage_document_batch_plans AS plan
    WHERE plan.batch_plan_sha256 = payload_plan ->> 'batchPlanSha256'
      AND plan.official_tokenizer_sha256 = payload_plan ->> 'officialTokenizerSha256'
      AND plan.expected_source_count = (payload_plan ->> 'sourceCount')::integer
      AND plan.expected_chunk_count = (payload_plan ->> 'chunkCount')::integer
      AND plan.expected_token_count = (payload_plan ->> 'tokenCount')::integer
      AND plan.expected_batch_count = (payload_plan ->> 'batchCount')::integer
      AND plan.owner_scope_sha256 IS NULL
      AND plan.owner_private_ordered_group_count = 0
      AND plan.state IN ('STAGING','COMPLETE')
  ) THEN
    RAISE EXCEPTION 'Pre-S5 Voyage document batch plan conflicts' USING ERRCODE = '23505';
  END IF;
  SELECT * INTO existing_batch
  FROM public.rag_v2_immutable_voyage_document_batches AS selected_batch
  WHERE selected_batch.batch_id = payload_batch ->> 'batchId';
  IF FOUND THEN
    IF existing_batch.batch_plan_sha256 <> payload_plan ->> 'batchPlanSha256'
       OR existing_batch.batch_manifest_sha256 <> payload_batch ->> 'batchManifestSha256'
       OR existing_batch.batch_ordinal <> (payload_batch ->> 'batchOrdinal')::integer
       OR existing_batch.batch_count <> (payload_batch ->> 'batchCount')::integer
       OR existing_batch.expected_token_count <> (payload_batch ->> 'tokenCount')::integer
       OR existing_batch.expected_chunk_count <> observed_vector_count
       OR existing_batch.expected_group_count <> (payload_batch ->> 'groupCount')::integer
       OR existing_batch.expected_response_bytes
          <> (payload_batch ->> 'estimatedResponseBytes')::integer
       OR existing_batch.packet_sha256 <> p_payload ->> 'packetSha256'
       OR existing_batch.vector_set_sha256 <> payload_vector_set_sha256
       OR existing_batch.state <> 'COMMITTED'
       OR (SELECT count(*) FROM public.rag_v2_immutable_voyage_document_batch_vectors AS vector_row
           WHERE vector_row.batch_id = existing_batch.batch_id) <> observed_vector_count THEN
      RAISE EXCEPTION 'Pre-S5 Voyage document batch conflicts' USING ERRCODE = '23505';
    END IF;
    reused := true;
  ELSE
    INSERT INTO public.rag_v2_immutable_voyage_document_batches (
      batch_id, batch_plan_sha256, batch_manifest_sha256, batch_ordinal, batch_count,
      expected_token_count, expected_chunk_count, expected_group_count, expected_response_bytes, packet_sha256,
      vector_set_sha256, provider_physical_call_count, state
    ) VALUES (
      payload_batch ->> 'batchId', payload_plan ->> 'batchPlanSha256',
      payload_batch ->> 'batchManifestSha256', (payload_batch ->> 'batchOrdinal')::integer,
      (payload_batch ->> 'batchCount')::integer, (payload_batch ->> 'tokenCount')::integer,
      observed_vector_count, (payload_batch ->> 'groupCount')::integer,
      (payload_batch ->> 'estimatedResponseBytes')::integer,
      p_payload ->> 'packetSha256', payload_vector_set_sha256, 1, 'COMMITTED'
    );
    FOR item IN SELECT value FROM jsonb_array_elements(payload_vectors) AS vector_row(value) LOOP
      INSERT INTO public.rag_v2_immutable_voyage_document_batch_vectors (
        batch_plan_sha256, batch_id, component_scope, source_id, source_revision_id, chunk_id,
        embedding_input_hash, context_set_hash, vector_sha256, embedding
      ) VALUES (
        payload_plan ->> 'batchPlanSha256', payload_batch ->> 'batchId', item ->> 'componentScope',
        item ->> 'sourceId', item ->> 'sourceRevisionId', item ->> 'chunkId',
        item ->> 'embeddingInputHash', item ->> 'contextSetHash', item ->> 'vectorSha256',
        (item -> 'vector')::text::vector(1024)
      );
    END LOOP;
  END IF;
  SELECT count(*) INTO complete_count
  FROM public.rag_v2_immutable_voyage_document_batches AS batch
  WHERE batch.batch_plan_sha256 = payload_plan ->> 'batchPlanSha256' AND batch.state = 'COMMITTED';
  SELECT count(*) INTO vector_count
  FROM public.rag_v2_immutable_voyage_document_batch_vectors AS vector_row
  WHERE vector_row.batch_plan_sha256 = payload_plan ->> 'batchPlanSha256';
  SELECT
    COALESCE(sum(batch.expected_token_count), 0),
    COALESCE(sum(batch.expected_chunk_count), 0),
    COALESCE(sum(batch.expected_group_count), 0),
    count(DISTINCT batch.batch_ordinal),
    min(batch.batch_ordinal),
    max(batch.batch_ordinal),
    min(batch.batch_count),
    max(batch.batch_count)
  INTO
    aggregate_token_count,
    aggregate_chunk_count,
    aggregate_group_count,
    distinct_ordinal_count,
    minimum_ordinal,
    maximum_ordinal,
    minimum_batch_count,
    maximum_batch_count
  FROM public.rag_v2_immutable_voyage_document_batches AS batch
  WHERE batch.batch_plan_sha256 = payload_plan ->> 'batchPlanSha256'
    AND batch.state = 'COMMITTED';
  SELECT
    count(DISTINCT (vector_row.batch_id, vector_row.source_id)),
    count(DISTINCT vector_row.source_id)
  INTO observed_group_count, observed_source_count
  FROM public.rag_v2_immutable_voyage_document_batch_vectors AS vector_row
  WHERE vector_row.batch_plan_sha256 = payload_plan ->> 'batchPlanSha256';
  IF complete_count = (payload_plan ->> 'batchCount')::integer THEN
    IF vector_count <> (payload_plan ->> 'chunkCount')::integer
       OR aggregate_token_count <> (payload_plan ->> 'tokenCount')::integer
       OR aggregate_chunk_count <> (payload_plan ->> 'chunkCount')::integer
       OR aggregate_group_count <> observed_group_count
       OR observed_source_count <> (payload_plan ->> 'sourceCount')::integer
       OR distinct_ordinal_count <> complete_count
       OR minimum_ordinal <> 1
       OR maximum_ordinal <> complete_count
       OR minimum_batch_count <> complete_count
       OR maximum_batch_count <> complete_count THEN
      RAISE EXCEPTION 'Pre-S5 Voyage document batch completion conflicts' USING ERRCODE = '23505';
    END IF;
    UPDATE public.rag_v2_immutable_voyage_document_batch_plans
    SET state = 'COMPLETE', completed_at = COALESCE(completed_at, transaction_timestamp())
    WHERE rag_v2_immutable_voyage_document_batch_plans.batch_plan_sha256 = payload_plan ->> 'batchPlanSha256'
      AND rag_v2_immutable_voyage_document_batch_plans.state = 'STAGING';
  END IF;
  RETURN QUERY SELECT
    payload_plan ->> 'batchPlanSha256', payload_batch ->> 'batchId',
    (SELECT plan.state FROM public.rag_v2_immutable_voyage_document_batch_plans AS plan
     WHERE plan.batch_plan_sha256 = payload_plan ->> 'batchPlanSha256'),
    reused, complete_count, vector_count;
END
$_$;


ALTER FUNCTION public.stage_rag_v2_immutable_voyage_document_batch(p_payload jsonb) OWNER TO flyway;


CREATE FUNCTION public.stage_signal_batch(p_batch_manifest_sha256 text, p_batch_manifest_canonical_text text, p_signal_batch_id text, p_model_release_id text, p_universe_release_id text, p_membership_sha256 text, p_session_date date, p_as_of timestamp with time zone, p_members_canonical_text text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  batch_manifest jsonb;
  members jsonb;
  member jsonb;
  existing_batch public.signal_batches%ROWTYPE;
  identity_digest text;
  payload_text text;
  payload_digest text;
  generated_signal_id text;
  member_count integer;
  computed_membership_sha256 text;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_signal_writer'
     OR octet_length(p_batch_manifest_canonical_text) NOT BETWEEN 2 AND 1048576
     OR octet_length(p_members_canonical_text) NOT BETWEEN 2 AND 262144 THEN
    RAISE EXCEPTION 'S5 signal batch arguments are invalid' USING ERRCODE = '22023';
  END IF;
  batch_manifest := p_batch_manifest_canonical_text::jsonb;
  IF p_batch_manifest_sha256 !~ '^[0-9a-f]{64}$'
     OR encode(digest(convert_to(p_batch_manifest_canonical_text, 'UTF8'), 'sha256'), 'hex')
        <> p_batch_manifest_sha256
     OR jsonb_typeof(batch_manifest) <> 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(batch_manifest)) <> 16
     OR batch_manifest - ARRAY[
          'asOf','batchPurpose','batchVersion','fixture','membershipSha256','membersSha256','modelReleaseId',
          'parquetFile','parquetSha256','provenanceClass','rowCount','semanticSha256',
          'sessionDate','signalBatchId','timeframe','universeReleaseId'
        ] <> '{}'::jsonb
     OR batch_manifest->>'batchVersion' IS DISTINCT FROM 's5-signal-batch-v1'
     OR batch_manifest->>'batchPurpose' NOT IN ('DAILY','ROLLBACK')
     OR batch_manifest->>'signalBatchId' IS DISTINCT FROM p_signal_batch_id
     OR batch_manifest->>'modelReleaseId' IS DISTINCT FROM p_model_release_id
     OR batch_manifest->>'universeReleaseId' IS DISTINCT FROM p_universe_release_id
     OR batch_manifest->>'membershipSha256' IS DISTINCT FROM p_membership_sha256
     OR batch_manifest->>'sessionDate' IS DISTINCT FROM p_session_date::text
     OR (batch_manifest->>'asOf')::timestamptz IS DISTINCT FROM p_as_of
     OR batch_manifest->>'timeframe' IS DISTINCT FROM '1d'
     OR batch_manifest->>'rowCount' IS DISTINCT FROM '31'
     OR batch_manifest->>'parquetFile' IS DISTINCT FROM 'signals.parquet'
     OR batch_manifest->>'provenanceClass' IS DISTINCT FROM 'PRODUCTION'
     OR batch_manifest->'fixture' IS DISTINCT FROM 'false'::jsonb
     OR p_signal_batch_id !~ '^sgb-[0-9a-f]{12}$'
     OR p_model_release_id !~ '^lgr-[0-9a-f]{12}$'
     OR p_universe_release_id !~ '^sur-[0-9a-f]{12}$'
     OR p_membership_sha256 !~ '^[0-9a-f]{64}$'
     OR batch_manifest->>'membersSha256' !~ '^[0-9a-f]{64}$'
     OR encode(digest(convert_to(p_members_canonical_text, 'UTF8'), 'sha256'), 'hex')
        <> batch_manifest->>'membersSha256'
     OR p_as_of IS NULL THEN
    RAISE EXCEPTION 'S5 signal batch arguments are invalid' USING ERRCODE = '22023';
  END IF;
  members := p_members_canonical_text::jsonb;
  IF jsonb_typeof(members) <> 'array' OR jsonb_array_length(members) <> 31 THEN
    RAISE EXCEPTION 'S5 signal batch must contain exact 31 members' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.signal_model_releases
    WHERE model_release_id = p_model_release_id AND qualification_status = 'QUALIFIED'
      AND fixture = false AND provenance_class = 'PRODUCTION'
  ) THEN
    RAISE EXCEPTION 'S5 signal batch model release is unavailable' USING ERRCODE = '22023';
  END IF;
  -- JSONB 변환이 null/string coercion을 숨기지 않도록 모든 member type과 값을 먼저 닫는다.
  FOR member IN SELECT value FROM jsonb_array_elements(members) LOOP
    IF jsonb_typeof(member) <> 'object'
       OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(member) key) <>
          ARRAY['asOf','confidence','modelReportId','modelVersion','signal','status','symbol']
       OR jsonb_typeof(member->'asOf') <> 'string'
       OR jsonb_typeof(member->'confidence') <> 'number'
       OR jsonb_typeof(member->'modelReportId') <> 'string'
       OR jsonb_typeof(member->'modelVersion') <> 'string'
       OR jsonb_typeof(member->'signal') <> 'string'
       OR jsonb_typeof(member->'status') <> 'string'
       OR jsonb_typeof(member->'symbol') <> 'string'
       OR member->>'symbol' !~ '^[0-9]{6}$'
       OR member->>'status' IS DISTINCT FROM 'AVAILABLE'
       OR member->>'signal' NOT IN ('BUY','HOLD','SELL')
       OR (member->>'asOf')::timestamptz IS DISTINCT FROM p_as_of
       OR (member->>'confidence')::numeric < 0 OR (member->>'confidence')::numeric > 1
       OR NOT EXISTS (
         SELECT 1 FROM public.signal_model_releases release
         WHERE release.model_release_id = p_model_release_id
           AND release.model_version = member->>'modelVersion'
           AND release.model_report_id = member->>'modelReportId'
       ) THEN
      RAISE EXCEPTION 'S5 signal batch member is invalid' USING ERRCODE = '22023';
    END IF;
  END LOOP;
  SELECT count(DISTINCT incoming->>'symbol'),
    encode(digest(
      convert_to('s5-inference-universe-v1', 'UTF8') || decode('00', 'hex') ||
        convert_to(
          '[' || string_agg(to_jsonb(incoming->>'symbol')::text, ',' ORDER BY incoming->>'symbol') || ']',
          'UTF8'
        ),
      'sha256'), 'hex')
  INTO member_count, computed_membership_sha256
  FROM jsonb_array_elements(members) incoming;
  IF member_count <> 31 OR computed_membership_sha256 <> p_membership_sha256
     OR p_universe_release_id <> 'sur-' || substr(computed_membership_sha256, 1, 12) THEN
    RAISE EXCEPTION 'S5 signal batch membership is invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_signal_batch_id, 0));
  SELECT * INTO existing_batch
  FROM public.signal_batches WHERE signal_batch_id = p_signal_batch_id FOR SHARE;
  IF FOUND THEN
    IF existing_batch.batch_manifest_sha256 = p_batch_manifest_sha256
       AND existing_batch.model_release_id = p_model_release_id
       AND existing_batch.universe_release_id = p_universe_release_id
       AND existing_batch.membership_sha256 = p_membership_sha256
       AND existing_batch.batch_purpose = batch_manifest->>'batchPurpose'
       AND existing_batch.session_date = p_session_date
       AND existing_batch.as_of = p_as_of
       AND existing_batch.timeframe = '1d'
       AND existing_batch.row_count = 31
       AND existing_batch.status = 'FINALIZED'
       AND existing_batch.fixture = false
       AND existing_batch.provenance_class = 'PRODUCTION'
       AND (SELECT count(*) FROM public.signal_batch_members stored
            WHERE stored.signal_batch_id = p_signal_batch_id) = 31
       AND NOT EXISTS (
         SELECT 1
         FROM jsonb_array_elements(members) incoming
         LEFT JOIN public.signal_batch_members stored
           ON stored.signal_batch_id = p_signal_batch_id
          AND stored.symbol = incoming->>'symbol'
         WHERE stored.signal_batch_id IS NULL
            OR stored.status IS DISTINCT FROM incoming->>'status'
            OR stored.signal IS DISTINCT FROM incoming->>'signal'
            OR stored.confidence IS DISTINCT FROM (incoming->>'confidence')::numeric
            OR stored.as_of IS DISTINCT FROM (incoming->>'asOf')::timestamptz
            OR stored.model_version IS DISTINCT FROM incoming->>'modelVersion'
            OR stored.model_report_id IS DISTINCT FROM incoming->>'modelReportId'
       ) THEN
      RETURN 'REPLAYED';
    END IF;
    RAISE EXCEPTION 'S5 signal batch identity conflict' USING ERRCODE = '23505';
  END IF;
  INSERT INTO public.signal_universe_releases(
    universe_release_id, policy_version, membership_sha256, member_count, fixture, provenance_class
  ) VALUES (
    p_universe_release_id, 'top30-plus-132030-v1', p_membership_sha256, 31, false, 'PRODUCTION'
  ) ON CONFLICT (universe_release_id) DO NOTHING;
  IF NOT EXISTS (
    SELECT 1 FROM public.signal_universe_releases
    WHERE universe_release_id = p_universe_release_id AND membership_sha256 = p_membership_sha256
  ) THEN
    RAISE EXCEPTION 'S5 universe release identity conflict' USING ERRCODE = '23505';
  END IF;
  INSERT INTO public.signal_batches(
    signal_batch_id, model_release_id, universe_release_id, batch_manifest_sha256,
    membership_sha256, batch_purpose, session_date, as_of, timeframe, row_count, status, fixture, provenance_class
  ) VALUES (
    p_signal_batch_id, p_model_release_id, p_universe_release_id, p_batch_manifest_sha256,
    p_membership_sha256, batch_manifest->>'batchPurpose', p_session_date, p_as_of,
    '1d', 31, 'STAGED', false, 'PRODUCTION'
  );
  FOR member IN SELECT value FROM jsonb_array_elements(members) LOOP
    payload_text := jsonb_build_object(
      'asOf', member->>'asOf', 'confidence', (member->>'confidence')::numeric,
      'modelReportId', member->>'modelReportId', 'modelVersion', member->>'modelVersion',
      'signal', member->>'signal', 'status', 'AVAILABLE', 'symbol', member->>'symbol'
    )::text;
    payload_digest := encode(digest(convert_to(payload_text, 'UTF8'), 'sha256'), 'hex');
    identity_digest := encode(digest(convert_to(concat_ws(E'\n',
      'signal-v2-production-release-identity-v1', p_model_release_id, p_signal_batch_id,
      member->>'symbol', p_session_date::text, '1d'), 'UTF8'), 'sha256'), 'hex');
    generated_signal_id := 'sigv2_' || substr(identity_digest, 1, 24);
    INSERT INTO public.ingested_signals(
      signal_id, producer, source_workspace, symbol, as_of, timeframe, confidence,
      predicted_return, feature_summary_json, payload_json, contract_version, status,
      reason, signal, evaluation_id, model_version, model_report_id, artifact_sha256,
      payload_sha256, provenance_sha256, logical_identity_sha256, fixture,
      provenance_class, payload_canonical_text, artifact_verified, session_date,
      model_release_id, signal_batch_id
    ) VALUES (
      generated_signal_id, 'LIGHTGBM', 'decision-platform', member->>'symbol', p_as_of, '1d',
      (member->>'confidence')::numeric, NULL, '[]'::jsonb, payload_text::jsonb,
      'signal-v2-runtime-v1', 'AVAILABLE', NULL, member->>'signal', p_signal_batch_id,
      member->>'modelVersion', member->>'modelReportId', p_batch_manifest_sha256,
      payload_digest, p_batch_manifest_sha256, identity_digest, false, 'PRODUCTION',
      payload_text, true, p_session_date, p_model_release_id, p_signal_batch_id
    );
    INSERT INTO public.signal_batch_members(
      signal_batch_id, symbol, status, signal, confidence, as_of, model_version,
      model_report_id, logical_identity_sha256
    ) VALUES (
      p_signal_batch_id, member->>'symbol', 'AVAILABLE', member->>'signal',
      (member->>'confidence')::numeric, p_as_of, member->>'modelVersion',
      member->>'modelReportId', identity_digest
    );
  END LOOP;
  SELECT count(*) INTO member_count FROM public.signal_batch_members
  WHERE signal_batch_id = p_signal_batch_id;
  SELECT encode(digest(
    convert_to('s5-inference-universe-v1', 'UTF8') || decode('00', 'hex') ||
      convert_to('[' || string_agg(to_jsonb(symbol)::text, ',' ORDER BY symbol) || ']', 'UTF8'),
    'sha256'), 'hex')
  INTO computed_membership_sha256
  FROM public.signal_batch_members WHERE signal_batch_id = p_signal_batch_id;
  IF member_count <> 31 OR NOT EXISTS (
    SELECT 1 FROM public.signal_batch_members
    WHERE signal_batch_id = p_signal_batch_id AND symbol = '132030'
  ) OR computed_membership_sha256 <> p_membership_sha256
     OR p_universe_release_id <> 'sur-' || substr(computed_membership_sha256, 1, 12) THEN
    RAISE EXCEPTION 'S5 signal batch is incomplete' USING ERRCODE = '22023';
  END IF;
  UPDATE public.signal_batches SET status = 'FINALIZED' WHERE signal_batch_id = p_signal_batch_id;
  RETURN 'INSERTED';
END
$_$;


ALTER FUNCTION public.stage_signal_batch(p_batch_manifest_sha256 text, p_batch_manifest_canonical_text text, p_signal_batch_id text, p_model_release_id text, p_universe_release_id text, p_membership_sha256 text, p_session_date date, p_as_of timestamp with time zone, p_members_canonical_text text) OWNER TO flyway;


CREATE FUNCTION public.stage_signal_model_release(p_release_manifest_sha256 text, p_release_manifest_canonical_text text, p_model_release_id text, p_model_version text, p_model_report_id text, p_feature_manifest_sha256 text, p_source_bundle_set_sha256 text, p_training_dataset_sha256 text, p_code_head text, p_code_tree text, p_uv_lock_sha256 text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  release_manifest jsonb;
  existing_release public.signal_model_releases%ROWTYPE;
  transition_digest text;
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_signal_writer'
     OR octet_length(p_release_manifest_canonical_text) NOT BETWEEN 2 AND 1048576 THEN
    RAISE EXCEPTION 'S5 model release arguments are invalid' USING ERRCODE = '22023';
  END IF;
  release_manifest := p_release_manifest_canonical_text::jsonb;
  IF p_release_manifest_sha256 !~ '^[0-9a-f]{64}$'
     OR encode(digest(convert_to(p_release_manifest_canonical_text, 'UTF8'), 'sha256'), 'hex')
        <> p_release_manifest_sha256
     OR jsonb_typeof(release_manifest) <> 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(release_manifest)) <> 19
     OR release_manifest - ARRAY[
          'calendarName','calendarVersion','codeHead','codeTree','featureManifestSha256','files',
          'fixture','modelReleaseId','modelReportId','modelVersion','provenanceClass',
          'releaseVersion','semanticSha256','sourceBundleSetSha256','sourcePolicySetSha256',
          'status','temporalQuality','trainingDatasetSha256','uvLockSha256'
        ] <> '{}'::jsonb
     OR release_manifest->>'releaseVersion' IS DISTINCT FROM 's5-model-release-v1'
     OR release_manifest->>'modelReleaseId' IS DISTINCT FROM p_model_release_id
     OR release_manifest->>'modelVersion' IS DISTINCT FROM p_model_version
     OR release_manifest->>'modelReportId' IS DISTINCT FROM p_model_report_id
     OR release_manifest->>'featureManifestSha256' IS DISTINCT FROM p_feature_manifest_sha256
     OR release_manifest->>'sourceBundleSetSha256' IS DISTINCT FROM p_source_bundle_set_sha256
     OR release_manifest->>'trainingDatasetSha256' IS DISTINCT FROM p_training_dataset_sha256
     OR release_manifest->>'codeHead' IS DISTINCT FROM p_code_head
     OR release_manifest->>'codeTree' IS DISTINCT FROM p_code_tree
     OR release_manifest->>'uvLockSha256' IS DISTINCT FROM p_uv_lock_sha256
     OR release_manifest->>'calendarName' IS DISTINCT FROM 'XKRX'
     OR release_manifest->>'calendarVersion' IS DISTINCT FROM '4.13.2'
     OR release_manifest->>'temporalQuality' IS DISTINCT FROM 'RECONSTRUCTED_FIXED_LAG'
     OR release_manifest->>'status' IS DISTINCT FROM 'QUALIFIED'
     OR release_manifest->>'provenanceClass' IS DISTINCT FROM 'PRODUCTION'
     OR release_manifest->'fixture' IS DISTINCT FROM 'false'::jsonb
     OR p_model_release_id !~ '^lgr-[0-9a-f]{12}$'
     OR p_model_version !~ '^lgbm-v1-[0-9a-f]{12}$'
     OR p_model_report_id !~ '^mrp-[0-9a-f]{12}$'
     OR p_feature_manifest_sha256 !~ '^[0-9a-f]{64}$'
     OR p_source_bundle_set_sha256 !~ '^[0-9a-f]{64}$'
     OR p_training_dataset_sha256 !~ '^[0-9a-f]{64}$'
     OR p_code_head !~ '^[0-9a-f]{40}$' OR p_code_tree !~ '^[0-9a-f]{40}$'
     OR p_uv_lock_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'S5 model release arguments are invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_model_release_id, 0));
  SELECT * INTO existing_release
  FROM public.signal_model_releases WHERE model_release_id = p_model_release_id FOR SHARE;
  IF FOUND THEN
    IF existing_release.release_manifest_sha256 = p_release_manifest_sha256
       AND existing_release.model_version = p_model_version
       AND existing_release.model_report_id = p_model_report_id
       AND existing_release.feature_manifest_sha256 = p_feature_manifest_sha256
       AND existing_release.source_bundle_set_sha256 = p_source_bundle_set_sha256
       AND existing_release.training_dataset_sha256 = p_training_dataset_sha256
       AND existing_release.code_head = p_code_head
       AND existing_release.code_tree = p_code_tree
       AND existing_release.uv_lock_sha256 = p_uv_lock_sha256
       AND existing_release.temporal_quality = 'RECONSTRUCTED_FIXED_LAG'
       AND existing_release.qualification_status = 'QUALIFIED'
       AND existing_release.fixture = false
       AND existing_release.provenance_class = 'PRODUCTION' THEN
      RETURN 'REPLAYED';
    END IF;
    RAISE EXCEPTION 'S5 model release identity conflict' USING ERRCODE = '23505';
  END IF;
  INSERT INTO public.signal_model_releases(
    model_release_id, model_version, model_report_id, release_manifest_sha256,
    feature_manifest_sha256, source_bundle_set_sha256, training_dataset_sha256,
    code_head, code_tree, uv_lock_sha256, temporal_quality, qualification_status,
    lifecycle_status, fixture, provenance_class
  ) VALUES (
    p_model_release_id, p_model_version, p_model_report_id, p_release_manifest_sha256,
    p_feature_manifest_sha256, p_source_bundle_set_sha256, p_training_dataset_sha256,
    p_code_head, p_code_tree, p_uv_lock_sha256, 'RECONSTRUCTED_FIXED_LAG', 'QUALIFIED',
    'STAGED', false, 'PRODUCTION'
  );
  transition_digest := encode(digest(convert_to(
    concat_ws(E'\n', 's5-model-transition-v1', p_model_release_id, 'STAGED', p_release_manifest_sha256),
    'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.signal_model_release_transitions(
    transition_id, model_release_id, from_status, to_status, reason, evidence_sha256, actor_role
  ) VALUES (
    'smrt-' || substr(transition_digest, 1, 24), p_model_release_id, NULL, 'STAGED',
    'STAGED', p_release_manifest_sha256, session_user
  );
  RETURN 'INSERTED';
END
$_$;


ALTER FUNCTION public.stage_signal_model_release(p_release_manifest_sha256 text, p_release_manifest_canonical_text text, p_model_release_id text, p_model_version text, p_model_report_id text, p_feature_manifest_sha256 text, p_source_bundle_set_sha256 text, p_training_dataset_sha256 text, p_code_head text, p_code_tree text, p_uv_lock_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.stage_synthetic_dashboard_view(p_artifact_id text, p_owner_user_id text, p_run_id text, p_file_name text, p_file_hash text, p_view_kind text, p_projection_text text, p_projection_hash text, p_as_of timestamp with time zone, p_fresh_until timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE changed integer; existing public.dashboard_artifact_staging%ROWTYPE; projection jsonb;
BEGIN
  IF session_user <> 'decision_demo' THEN RAISE EXCEPTION 'dashboard staging role denied' USING ERRCODE='42501'; END IF;
  IF p_projection_text IS NULL OR octet_length(p_projection_text) NOT BETWEEN 2 AND 524288
     OR NOT public.json_text_depth_within(p_projection_text,8) THEN
    RAISE EXCEPTION 'invalid synthetic dashboard projection' USING ERRCODE='22023';
  END IF;
  projection:=p_projection_text::jsonb;
  IF p_owner_user_id<>'usr_demo_user' OR p_artifact_id<>'artifact_s8_0ed32aac66088e495ae853bb'
     OR p_run_id<>'demo_s8_fake_e2e_0001'
     OR p_file_hash<>'sha256:0ed32aac66088e495ae853bbac98a35b2c4a22420138bdd58dcdbbb0d9d8ad02'
     OR p_view_kind NOT IN ('MODEL_EVALUATION','BACKTEST') OR p_projection_hash !~ '^sha256:[0-9a-f]{64}$'
     OR jsonb_typeof(projection)<>'object' OR p_projection_hash<>('sha256:'||encode(public.digest(p_projection_text,'sha256'),'hex'))
     OR p_fresh_until<p_as_of OR projection->'success'<>'true'::jsonb OR projection->'error'<>'null'::jsonb
     OR projection#>>'{data,evidenceMode}'<>'SYNTHETIC_DEMO' OR projection#>'{data,performanceClaimAllowed}'<>'false'::jsonb
     OR projection#>>'{data,viewState}'<>'READY' OR (projection#>>'{data,asOf}')::timestamptz<>p_as_of
     OR (projection#>>'{data,freshUntil}')::timestamptz<>p_fresh_until OR projection#>>'{data,view,runId}'<>p_run_id
     OR p_as_of<>'2026-08-22T00:00:00Z'::timestamptz OR p_fresh_until<>'2026-09-21T00:00:00Z'::timestamptz
     OR (p_view_kind='MODEL_EVALUATION' AND (p_file_name<>'model-evaluation.json'
       OR p_projection_hash<>'sha256:984ff60fba0c795a77b47b4d9180a1f1f7b76a5c3d1fcbbb30bb3510cf322696'))
     OR (p_view_kind='BACKTEST' AND (p_file_name<>'backtest.json'
       OR projection#>>'{data,view,fixtureClass}'<>'SYNTHETIC_FAKE_E2E'
       OR p_projection_hash<>'sha256:0e754cd9ea9ede03de7b54274fcb0540e1aff7dcd4621ba698b506ab817f5d45')) THEN
    RAISE EXCEPTION 'invalid synthetic dashboard projection' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE user_id=p_owner_user_id AND status='ACTIVE') THEN RETURN false; END IF;
  SELECT * INTO existing FROM public.dashboard_artifact_staging WHERE artifact_id=p_artifact_id AND view_kind=p_view_kind;
  IF FOUND THEN
    IF existing.owner_user_id=p_owner_user_id AND existing.run_id=p_run_id AND existing.file_name=p_file_name
       AND existing.file_hash=p_file_hash AND existing.projection_text=p_projection_text
       AND existing.projection_hash=p_projection_hash AND existing.as_of=p_as_of AND existing.fresh_until=p_fresh_until THEN RETURN false; END IF;
    RAISE EXCEPTION 'synthetic dashboard identity conflict' USING ERRCODE='23505';
  END IF;
  INSERT INTO public.dashboard_artifact_staging(artifact_id,view_kind,owner_user_id,run_id,file_name,file_hash,
    schema_version,fixture_class,evidence_mode,projection_text,projection_hash,as_of,fresh_until)
  VALUES (p_artifact_id,p_view_kind,p_owner_user_id,p_run_id,p_file_name,p_file_hash,'1.0.0','SYNTHETIC_FAKE_E2E',
    'SYNTHETIC_DEMO',p_projection_text,p_projection_hash,p_as_of,p_fresh_until);
  GET DIAGNOSTICS changed=ROW_COUNT;RETURN changed=1;
END
$_$;


ALTER FUNCTION public.stage_synthetic_dashboard_view(p_artifact_id text, p_owner_user_id text, p_run_id text, p_file_name text, p_file_hash text, p_view_kind text, p_projection_text text, p_projection_hash text, p_as_of timestamp with time zone, p_fresh_until timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.suspend_signal_model_for_drift(p_model_release_id text, p_evidence_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  transition_digest text;
BEGIN
  IF current_user <> 'flyway' OR session_user NOT IN ('decision_signal_scheduler','decision_signal_admin')
     OR p_evidence_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'S5 drift suspension actor or evidence is invalid' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('s5-signal-active-pointer-v1', 0));
  -- activation/rollback pointer CAS와 drift 대상 판정을 같은 순서로 직렬화한다.
  PERFORM 1 FROM public.active_signal_model_release
  WHERE singleton AND model_release_id = p_model_release_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'S5 drift suspension target is not active' USING ERRCODE = '22023';
  END IF;
  UPDATE public.signal_model_releases SET lifecycle_status = 'SUSPENDED'
  WHERE model_release_id = p_model_release_id AND lifecycle_status = 'ACCEPTED';
  IF NOT FOUND THEN RETURN; END IF;
  transition_digest := encode(digest(convert_to(concat_ws(E'\n',
    's5-model-transition-v1', p_model_release_id, 'SUSPENDED', p_evidence_sha256),
    'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.signal_model_release_transitions(
    transition_id, model_release_id, from_status, to_status, reason, evidence_sha256, actor_role
  ) VALUES (
    'smrt-' || substr(transition_digest, 1, 24), p_model_release_id, 'ACCEPTED', 'SUSPENDED',
    'ARTIFACT_DRIFT', p_evidence_sha256, session_user
  );
END
$_$;


ALTER FUNCTION public.suspend_signal_model_for_drift(p_model_release_id text, p_evidence_sha256 text) OWNER TO flyway;


CREATE FUNCTION public.sync_s4_9_mcp_oauth_client(p_client_id text, p_client_name text, p_metadata_sha256 text, p_redirect_uris text[], p_allowed_scopes text[], p_client_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR p_metadata_sha256 !~ '^[0-9a-f]{64}$' OR p_client_kind NOT IN ('STATIC_ALLOWLIST','CIMD_VERIFIED')
     OR cardinality(p_redirect_uris) NOT BETWEEN 1 AND 8 OR cardinality(p_allowed_scopes) NOT BETWEEN 1 AND 5
     OR NOT p_allowed_scopes <@ ARRAY['mcp:rag.public','mcp:rag.owner','mcp:web.read','mcp:answer.validate','mcp:history.write']::text[]
     OR EXISTS (SELECT 1 FROM unnest(p_redirect_uris) u WHERE u !~ '^https://'
       AND u !~ '^http://(?:127\.0\.0\.1|localhost)(?::[0-9]{1,5})?/') THEN
    RAISE EXCEPTION 'S4.9 MCP client metadata is invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.s4_9_mcp_oauth_clients (
    client_id, client_name, metadata_sha256, redirect_uris, allowed_scopes, client_kind
  ) VALUES (p_client_id, p_client_name, p_metadata_sha256, p_redirect_uris, p_allowed_scopes, p_client_kind)
  ON CONFLICT (client_id) DO UPDATE SET
    client_name = EXCLUDED.client_name,
    metadata_sha256 = EXCLUDED.metadata_sha256,
    redirect_uris = EXCLUDED.redirect_uris,
    allowed_scopes = EXCLUDED.allowed_scopes,
    client_kind = EXCLUDED.client_kind,
    status = 'ACTIVE',
    updated_at = transaction_timestamp();
END
$_$;


ALTER FUNCTION public.sync_s4_9_mcp_oauth_client(p_client_id text, p_client_name text, p_metadata_sha256 text, p_redirect_uris text[], p_allowed_scopes text[], p_client_kind text) OWNER TO flyway;


CREATE FUNCTION public.transition_kill_switch_authorized(p_capability text, p_actor_user_id text, p_actor_security_version bigint, p_requested_active boolean, p_observed_generation bigint, p_request_id text) RETURNS TABLE(active boolean, reason_class text, changed_at timestamp with time zone, changed boolean, previous_active boolean, generation bigint, invalidated_decision_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
#variable_conflict use_column
DECLARE
  actor_role text;
  current_gate public.risk_kill_switch%ROWTYPE;
  next_reason text;
  transition_time timestamptz;
  invalidated_count integer := 0;
BEGIN
  IF session_user <> 'decision_app'
     OR p_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'
     OR p_observed_generation <= 0 THEN
    RAISE EXCEPTION 'kill switch capability request denied' USING ERRCODE = '42501';
  END IF;

  IF NOT public.consume_actor_request_capability(
    p_capability,
    p_actor_user_id,
    p_actor_security_version,
    CASE WHEN p_requested_active THEN NULL ELSE 'ADMIN' END
  ) THEN
    RAISE EXCEPTION 'kill switch actor capability denied' USING ERRCODE = '42501';
  END IF;

  SELECT actor.role INTO actor_role
  FROM public.users actor
  WHERE actor.user_id = p_actor_user_id
    AND actor.status = 'ACTIVE'
    AND actor.security_version = p_actor_security_version
    AND actor.role IN ('USER', 'ADMIN')
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kill switch current actor denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO current_gate
  FROM public.risk_kill_switch gate
  WHERE gate.kill_switch_id = 'GLOBAL'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'kill switch authority unavailable' USING ERRCODE = 'P5501'; END IF;

  IF current_gate.generation <> p_observed_generation THEN
    RAISE EXCEPTION 'kill switch generation conflict' USING ERRCODE = '40001';
  END IF;

  IF current_gate.active = p_requested_active THEN
    RETURN QUERY SELECT current_gate.active,current_gate.reason_class,current_gate.changed_at,false,
      current_gate.active,current_gate.generation,0;
    RETURN;
  END IF;

  next_reason := CASE
    WHEN NOT p_requested_active THEN 'ADMIN_RESUME'
    WHEN actor_role = 'ADMIN' THEN 'OPERATOR_MANUAL_STOP'
    ELSE 'USER_MANUAL_STOP'
  END;
  transition_time := greatest(statement_timestamp(), current_gate.changed_at);

  UPDATE public.risk_kill_switch gate
  SET active = p_requested_active,
      reason_class = next_reason,
      generation = current_gate.generation + 1,
      changed_by = p_actor_user_id,
      changed_by_role = actor_role,
      changed_at = transition_time,
      request_id = p_request_id
  WHERE gate.kill_switch_id = 'GLOBAL'
    AND gate.generation = p_observed_generation;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kill switch generation conflict' USING ERRCODE = '40001';
  END IF;

  IF p_requested_active THEN
    invalidated_count := public.invalidate_unused_decisions_for_kill_switch(
      current_gate.generation + 1,
      transition_time,
      p_request_id
    );
  END IF;

  INSERT INTO public.risk_kill_switch_transitions(
    transition_id,generation,previous_active,next_active,reason_class,changed_by,
    changed_by_role,changed_at,request_id,invalidated_decision_count
  ) VALUES (
    'kst_' || replace(gen_random_uuid()::text,'-',''),current_gate.generation + 1,
    current_gate.active,p_requested_active,next_reason,p_actor_user_id,actor_role,
    transition_time,p_request_id,invalidated_count
  );

  INSERT INTO public.audit_logs(
    audit_log_id,user_id,actor_role,action,target_type,target_id,request_id,payload_json,created_at
  ) VALUES (
    'aud_' || replace(gen_random_uuid()::text,'-',''),p_actor_user_id,actor_role,
    'KILL_SWITCH_CHANGED','KILL_SWITCH','GLOBAL',p_request_id,
    jsonb_build_object(
      'generation',current_gate.generation + 1,
      'previousActive',current_gate.active,
      'nextActive',p_requested_active,
      'reasonClass',next_reason,
      'changedBy',p_actor_user_id,
      'changedByRole',actor_role,
      'correlationId',p_request_id,
      'invalidatedDecisionCount',invalidated_count
    ),transition_time
  );

  INSERT INTO public.event_outbox(
    event_id,event_type,aggregate_type,aggregate_id,partition_key,payload_json,
    schema_version,status,retry_count,created_at,updated_at
  ) VALUES (
    'evt_' || replace(gen_random_uuid()::text,'-',''),'kill-switch.changed','KILL_SWITCH',
    'GLOBAL','GLOBAL',jsonb_build_object('active',p_requested_active,'changedAt',transition_time::text),
    '1.0.0','PENDING',0,transition_time,transition_time
  );

  RETURN QUERY SELECT p_requested_active,next_reason,transition_time,true,current_gate.active,
    current_gate.generation + 1,invalidated_count;
END
$_$;


ALTER FUNCTION public.transition_kill_switch_authorized(p_capability text, p_actor_user_id text, p_actor_security_version bigint, p_requested_active boolean, p_observed_generation bigint, p_request_id text) OWNER TO flyway;


CREATE FUNCTION public.transition_rag_v2_immutable_owner_component_generation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  next_generation_id text;
  previous_generation_id text;
  activation_timestamp timestamptz := clock_timestamp();
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_rag_admin'
     OR NEW.owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR NEW.state <> 'READY'
     OR NEW.active_bundle_id IS NULL THEN
    RAISE EXCEPTION 'immutable RAG v2 owner component activation trigger is not authorized'
      USING ERRCODE = '42501';
  END IF;

  SELECT bundle.owner_private_generation_id
  INTO next_generation_id
  FROM public.rag_v2_immutable_bundles AS bundle
  WHERE bundle.bundle_id = NEW.active_bundle_id
    AND bundle.owner_user_id = NEW.owner_user_id
    AND bundle.state = 'ACTIVE'
    AND bundle.evaluation_status = 'PASSED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 active owner bundle has no evaluated component'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.active_bundle_id IS NOT NULL
     AND OLD.active_bundle_id IS DISTINCT FROM NEW.active_bundle_id THEN
    SELECT bundle.owner_private_generation_id
    INTO previous_generation_id
    FROM public.rag_v2_immutable_bundles AS bundle
    WHERE bundle.bundle_id = OLD.active_bundle_id
      AND bundle.owner_user_id = NEW.owner_user_id;
  END IF;

  UPDATE public.rag_v2_immutable_component_generations
  SET state = 'SUPERSEDED'
  WHERE component_generation_id = previous_generation_id
    AND owner_user_id = NEW.owner_user_id
    AND component_scope = 'OWNER_PRIVATE'
    AND state = 'ACTIVE';
  UPDATE public.rag_v2_immutable_component_generations
  SET state = 'ACTIVE',
      activated_at = coalesce(activated_at, activation_timestamp)
  WHERE component_generation_id = next_generation_id
    AND owner_user_id = NEW.owner_user_id
    AND component_scope = 'OWNER_PRIVATE'
    AND state = 'EVALUATED'
    AND evaluation_status = 'PASSED';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'immutable RAG v2 owner component activation transition failed'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.transition_rag_v2_immutable_owner_component_generation() OWNER TO flyway;


CREATE FUNCTION public.update_owned_principle_authorized(p_capability text, p_actor_user_id text, p_principle_id text, p_expected_version integer, p_title text, p_mode text, p_status text, p_updated_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE next_version integer;
BEGIN
  IF NOT public.consume_current_actor_capability(p_capability,p_actor_user_id) THEN
    RAISE EXCEPTION 'principle update capability denied' USING ERRCODE='42501';
  END IF;
  UPDATE public.principles item SET title=p_title,mode=p_mode,status=p_status,
    current_version=item.current_version+1,updated_at=p_updated_at
  WHERE item.principle_id=p_principle_id AND item.user_id=p_actor_user_id
    AND item.current_version=p_expected_version AND item.current_version<2147483647
  RETURNING item.current_version INTO next_version;
  RETURN next_version;
END
$$;


ALTER FUNCTION public.update_owned_principle_authorized(p_capability text, p_actor_user_id text, p_principle_id text, p_expected_version integer, p_title text, p_mode text, p_status text, p_updated_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.upsert_owned_rag_answer_feedback(p_owner_user_id text, p_answer_id text, p_helpful boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  written boolean;
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_app'
     OR nullif(current_setting('app.actor_user_id', true), '') IS DISTINCT FROM p_owner_user_id
     OR p_answer_id !~ '^rag_ans_[0-9a-f]{32}$'
     OR p_helpful IS NULL THEN
    RAISE EXCEPTION 'RAG feedback arguments are invalid'
      USING ERRCODE = '22023';
  END IF;
  WITH owned AS (
    SELECT history.answer_id
    FROM public.rag_answer_history AS history
    WHERE history.answer_id = p_answer_id
      AND history.owner_user_id = p_owner_user_id
      AND history.expires_at > statement_timestamp()
  ),
  persisted AS (
    INSERT INTO public.rag_answer_feedback (
      answer_id,
      owner_user_id,
      helpful
    )
    SELECT owned.answer_id, p_owner_user_id, p_helpful
    FROM owned
    ON CONFLICT (answer_id) DO UPDATE
    SET helpful = EXCLUDED.helpful,
        updated_at = transaction_timestamp()
    WHERE rag_answer_feedback.owner_user_id = p_owner_user_id
    RETURNING true AS written
  )
  SELECT coalesce(bool_or(persisted.written), false)
  INTO written
  FROM persisted;
  RETURN written;
END
$_$;


ALTER FUNCTION public.upsert_owned_rag_answer_feedback(p_owner_user_id text, p_answer_id text, p_helpful boolean) OWNER TO flyway;


CREATE FUNCTION public.upsert_s4_9_mcp_oauth_code_hash(p_code_sha256 text, p_client_id text, p_owner_user_id text, p_security_version bigint, p_redirect_uri text, p_resource_uri text, p_scopes text[], p_code_challenge text, p_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF current_user <> 'flyway' OR session_user <> 'decision_app'
     OR p_code_sha256 !~ '^[0-9a-f]{64}$' OR p_owner_user_id !~ '^usr_[a-z0-9][a-z0-9_-]{2,95}$'
     OR p_security_version <= 0 OR p_code_challenge !~ '^[A-Za-z0-9_-]{43,128}$'
     OR p_expires_at <= transaction_timestamp() OR p_expires_at > transaction_timestamp() + interval '5 minutes'
     OR p_resource_uri !~ '^https://[^[:space:]]+/mcp$|^http://(?:127\.0\.0\.1|localhost)(?::[0-9]{1,5})?/mcp$'
     OR NOT p_scopes <@ ARRAY['mcp:rag.public','mcp:rag.owner','mcp:web.read','mcp:answer.validate','mcp:history.write']::text[] THEN
    RAISE EXCEPTION 'S4.9 authorization code hash is invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.s4_9_mcp_oauth_authorization_codes (
    code_sha256, client_id, owner_user_id, security_version, redirect_uri, resource_uri,
    scopes, code_challenge, expires_at
  ) VALUES (
    p_code_sha256, p_client_id, p_owner_user_id, p_security_version, p_redirect_uri, p_resource_uri,
    p_scopes, p_code_challenge, p_expires_at
  ) ON CONFLICT (code_sha256) DO NOTHING;
END
$_$;


ALTER FUNCTION public.upsert_s4_9_mcp_oauth_code_hash(p_code_sha256 text, p_client_id text, p_owner_user_id text, p_security_version bigint, p_redirect_uri text, p_resource_uri text, p_scopes text[], p_code_challenge text, p_expires_at timestamp with time zone) OWNER TO flyway;


CREATE FUNCTION public.validate_cross_market_fixture_payload(p_record jsonb, p_key_profile jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user <> 'flyway'
     OR session_user <> 'decision_market_writer'
     OR jsonb_typeof(p_record) IS DISTINCT FROM 'object'
     OR NOT public.cross_market_fixture_payload_keys_are_allowed(p_record, p_key_profile)
     OR p_record::text ~* '"(raw_?body|article_?(body|title|url|metadata)|pdf_?(content|text)|account_?(number|id)|access_?token|api_?key|credential|provider_?raw|providerPhysicalCalls|externalLlmCalls)"[[:space:]]*:'
     OR (p_record ? 'decisionAuthority' AND p_record ->> 'decisionAuthority' <> 'NONE') THEN
    RAISE EXCEPTION 'cross-market fixture payload is not permitted'
      USING ERRCODE = '22023';
  END IF;
END
$$;


ALTER FUNCTION public.validate_cross_market_fixture_payload(p_record jsonb, p_key_profile jsonb) OWNER TO flyway;


CREATE FUNCTION public.verify_p1_synthetic_async_request(p_mode text, p_run_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE target_job_id text; target_event_id text;
BEGIN
  IF session_user <> 'decision_demo' OR p_mode NOT IN ('DB','KAFKA')
     OR p_run_id !~ '^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'P1 synthetic async verification denied' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.p1_offline_demo_authority authority
    WHERE authority.authority_id='P1_OFFLINE_DEMO' AND authority.active
  ) THEN
    RAISE EXCEPTION 'P1 offline demo authority inactive' USING ERRCODE='42501';
  END IF;
  target_job_id:='job_p1_container_'||lower(p_mode)||'_'||p_run_id;
  target_event_id:='evt_p1_container_'||lower(p_mode)||'_'||p_run_id;
  RETURN EXISTS (
    SELECT 1 FROM public.async_job job
    JOIN public.async_materialization_receipt receipt ON receipt.job_id=job.job_id AND receipt.event_id=target_event_id
    JOIN public.processed_event processed ON processed.event_id=target_event_id
      AND processed.consumer_name='python-async-worker-v1' AND NOT processed.payload_hash_conflict
    JOIN public.event_outbox requested ON requested.event_id=target_event_id AND requested.aggregate_id=job.job_id
    WHERE job.job_id=target_job_id AND job.status='COMPLETED' AND job.result_json->>'resultRef'=receipt.result_ref
      AND requested.status='PUBLISHED'
  );
END
$_$;


ALTER FUNCTION public.verify_p1_synthetic_async_request(p_mode text, p_run_id text) OWNER TO flyway;


