    source_revision text,
    effective_at timestamp with time zone NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    canonical_event_id text NOT NULL,
    mapping_version text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT disclosure_risk_state_transitions_corp_code_check CHECK ((corp_code ~ '^[0-9]{8}$'::text)),
    CONSTRAINT disclosure_risk_state_transitions_revision_no_check CHECK ((revision_no > 0)),
    CONSTRAINT disclosure_risk_state_transitions_transition_type_check CHECK ((transition_type = ANY (ARRAY['OPEN'::text, 'CLOSE'::text])))
);


