CREATE VIEW public.active_disclosure_risk_states AS
 SELECT transition_id,
    corp_code,
    state_type,
    state_key,
    revision_no,
    effective_at,
    observed_at,
    canonical_event_id,
    mapping_version
   FROM ( SELECT DISTINCT ON (disclosure_risk_state_transitions.state_key) disclosure_risk_state_transitions.transition_id,
            disclosure_risk_state_transitions.corp_code,
            disclosure_risk_state_transitions.state_type,
            disclosure_risk_state_transitions.state_key,
            disclosure_risk_state_transitions.transition_type,
            disclosure_risk_state_transitions.revision_no,
            disclosure_risk_state_transitions.effective_at,
            disclosure_risk_state_transitions.observed_at,
            disclosure_risk_state_transitions.canonical_event_id,
            disclosure_risk_state_transitions.mapping_version
           FROM public.disclosure_risk_state_transitions
          ORDER BY disclosure_risk_state_transitions.state_key, disclosure_risk_state_transitions.revision_no DESC, disclosure_risk_state_transitions.observed_at DESC, disclosure_risk_state_transitions.transition_id DESC) latest
  WHERE (transition_type = 'OPEN'::text);


