    catalog_version text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone NOT NULL,
    completeness text NOT NULL,
    schema_version text NOT NULL,
    source_version text NOT NULL,
    payload_json jsonb NOT NULL,
    source_ref text NOT NULL,
    artifact_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT instrument_catalog_classification_check CHECK (((NOT is_gold_etf_etn) OR is_etf_etn)),
    CONSTRAINT instrument_catalog_observations_artifact_hash_check CHECK ((artifact_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT instrument_catalog_observations_catalog_version_check CHECK (((char_length(catalog_version) >= 1) AND (char_length(catalog_version) <= 128))),
    CONSTRAINT instrument_catalog_observations_completeness_check CHECK ((completeness = ANY (ARRAY['COMPLETE'::text, 'PARTIAL'::text]))),
    CONSTRAINT instrument_catalog_observations_schema_version_check CHECK (((char_length(schema_version) >= 1) AND (char_length(schema_version) <= 128))),
    CONSTRAINT instrument_catalog_observations_source_ref_check CHECK ((source_ref ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT instrument_catalog_observations_source_version_check CHECK (((char_length(source_version) >= 1) AND (char_length(source_version) <= 128))),
    CONSTRAINT instrument_catalog_observations_symbol_check CHECK ((symbol ~ '^[0-9A-Z._:-]{1,20}$'::text)),
    CONSTRAINT instrument_catalog_payload_check CHECK (((jsonb_typeof(payload_json) = 'object'::text) AND ((octet_length((payload_json)::text) >= 2) AND (octet_length((payload_json)::text) <= 65536)))),
    CONSTRAINT instrument_catalog_risk_check CHECK (((product_risk_score IS NULL) OR ((product_risk_score >= (0)::numeric) AND (product_risk_score <= (1)::numeric)))),
    CONSTRAINT instrument_catalog_time_check CHECK ((received_at >= observed_at))
);


