CREATE VIEW public.active_paper_portfolio_projection WITH (security_barrier='true') AS
 SELECT account_id,
    user_id AS owner_user_id,
    cash_balance AS cash_krw,
    (COALESCE(( SELECT sum("position".market_value) AS sum
           FROM public.paper_positions "position"
          WHERE ("position".account_id = account.account_id)), (0)::numeric) + (cash_balance)::numeric) AS portfolio_equity_krw,
    NULL::bigint AS margin_requirement_krw,
    GREATEST(updated_at, COALESCE(( SELECT max("position".updated_at) AS max
           FROM public.paper_positions "position"
          WHERE ("position".account_id = account.account_id)), updated_at)) AS observed_at,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('symbol', "position".symbol, 'quantity', "position".quantity, 'marketValueKrw', "position".market_value, 'isGoldEtfEtn',
                CASE
                    WHEN (instrument.completeness = 'COMPLETE'::text) THEN instrument.is_gold_etf_etn
                    ELSE NULL::boolean
                END) ORDER BY "position".symbol) AS jsonb_agg
           FROM (public.paper_positions "position"
             LEFT JOIN public.latest_instrument_catalog_observations instrument ON ((instrument.symbol = "position".symbol)))
          WHERE ("position".account_id = account.account_id)), '[]'::jsonb) AS positions_json
   FROM public.paper_accounts account
  WHERE ((status = 'ACTIVE'::text) AND (user_id = current_setting('app.actor_user_id'::text, true)));


