    CONSTRAINT audit_logs_brokerage_order_contract_check CHECK (((target_type <> 'ORDER'::text) OR ((action = 'MOCK_ORDER_SUBMITTED'::text) AND (user_id IS NOT NULL) AND (target_id = (payload_json ->> 'orderId'::text)) AND ((payload_json ->> 'brokerageMode'::text) = 'KIS_MOCK'::text) AND ((payload_json ->> 'status'::text) = 'SUBMITTED'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text]) = '{}'::jsonb)) OR ((action = 'MOCK_ORDER_CANCEL_REQUESTED'::text) AND (user_id IS NOT NULL) AND (target_id = (payload_json ->> 'orderId'::text)) AND ((payload_json ->> 'brokerageMode'::text) = 'KIS_MOCK'::text) AND ((payload_json ->> 'status'::text) = 'CANCEL_REQUESTED'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'brokerageMode'::text, 'status'::text, 'requestedByRole'::text, 'requestedAt'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'brokerageMode'::text, 'status'::text, 'requestedByRole'::text, 'requestedAt'::text]) = '{}'::jsonb)) OR ((action = 'PAPER_ORDER_ACCEPTED'::text) AND (user_id IS NOT NULL) AND (target_id = (payload_json ->> 'orderId'::text)) AND ((payload_json ->> 'brokerageMode'::text) = 'INTERNAL_PAPER'::text) AND ((payload_json ->> 'status'::text) = 'ACCEPTED'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text]) = '{}'::jsonb)) OR ((action = 'PAPER_ORDER_FILLED'::text) AND (user_id IS NOT NULL) AND (target_id = (payload_json ->> 'orderId'::text)) AND ((payload_json ->> 'brokerageMode'::text) = 'INTERNAL_PAPER'::text) AND ((payload_json ->> 'status'::text) = 'FILLED'::text) AND ((payload_json ->> 'priceBasis'::text) = ANY (ARRAY['LAST_QUOTE'::text, 'PREVIOUS_CLOSE'::text])) AND (((payload_json ->> 'fillPriceKrw'::text))::bigint > 0) AND (((payload_json ->> 'fillQuantity'::text))::bigint > 0) AND ((((payload_json ->> 'slippageBps'::text))::integer >= 0) AND (((payload_json ->> 'slippageBps'::text))::integer <= 100)) AND ((payload_json ->> 'feeModel'::text) = 'NONE_V1'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text, 'fillPriceKrw'::text, 'fillQuantity'::text, 'priceBasis'::text, 'slippageBps'::text, 'feeModel'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text, 'fillPriceKrw'::text, 'fillQuantity'::text, 'priceBasis'::text, 'slippageBps'::text, 'feeModel'::text]) = '{}'::jsonb)) OR ((action = 'PAPER_ORDER_CANCELLED'::text) AND (user_id IS NOT NULL) AND (target_id = (payload_json ->> 'orderId'::text)) AND ((payload_json ->> 'brokerageMode'::text) = 'INTERNAL_PAPER'::text) AND ((payload_json ->> 'status'::text) = 'CANCELLED'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'brokerageMode'::text, 'status'::text, 'requestedByRole'::text, 'requestedAt'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'brokerageMode'::text, 'status'::text, 'requestedByRole'::text, 'requestedAt'::text]) = '{}'::jsonb)))),
    CONSTRAINT audit_logs_decision_contract_check CHECK (((target_type <> 'DECISION'::text) OR ((action = 'DECISION_EVALUATED'::text) AND (user_id IS NOT NULL) AND (target_id IS NOT NULL) AND (target_id = (payload_json ->> 'decisionId'::text)) AND (payload_json ?& ARRAY['evaluationId'::text, 'decisionId'::text, 'outcome'::text, 'principleVersionId'::text, 'semanticInputHash'::text, 'snapshotArtifactHash'::text]) AND ((payload_json - ARRAY['evaluationId'::text, 'decisionId'::text, 'outcome'::text, 'principleVersionId'::text, 'semanticInputHash'::text, 'snapshotArtifactHash'::text]) = '{}'::jsonb)))),
    CONSTRAINT audit_logs_kill_switch_contract_check CHECK (((target_type <> 'KILL_SWITCH'::text) OR ((action = 'KILL_SWITCH_CHANGED'::text) AND (user_id IS NOT NULL) AND (target_id = 'GLOBAL'::text) AND (request_id = (payload_json ->> 'correlationId'::text)) AND (user_id = (payload_json ->> 'changedBy'::text)) AND (actor_role = (payload_json ->> 'changedByRole'::text)) AND (payload_json ?& ARRAY['generation'::text, 'previousActive'::text, 'nextActive'::text, 'reasonClass'::text, 'changedBy'::text, 'changedByRole'::text, 'correlationId'::text, 'invalidatedDecisionCount'::text]) AND ((payload_json - ARRAY['generation'::text, 'previousActive'::text, 'nextActive'::text, 'reasonClass'::text, 'changedBy'::text, 'changedByRole'::text, 'correlationId'::text, 'invalidatedDecisionCount'::text]) = '{}'::jsonb)))),
    CONSTRAINT audit_logs_order_reconciliation_contract_check CHECK (((target_type <> 'ORDER_RECONCILIATION'::text) OR ((action = 'ORDER_RECONCILED'::text) AND (user_id IS NOT NULL) AND (target_id = (payload_json ->> 'orderId'::text)) AND ((payload_json ->> 'brokerageMode'::text) = ANY (ARRAY['KIS_MOCK'::text, 'INTERNAL_PAPER'::text])) AND ((payload_json ->> 'reconciliationStatus'::text) = ANY (ARRAY['NOT_APPLICABLE'::text, 'MATCHED'::text, 'MISMATCH'::text])) AND ((((payload_json ->> 'appliedEventCount'::text))::integer >= 0) AND (((payload_json ->> 'appliedEventCount'::text))::integer <= 200)) AND (jsonb_typeof((payload_json -> 'hasMore'::text)) = 'boolean'::text) AND (payload_json ?& ARRAY['orderId'::text, 'brokerageMode'::text, 'reconciliationStatus'::text, 'appliedEventCount'::text, 'invalidEventCount'::text, 'hasMore'::text, 'checkedAt'::text]) AND ((payload_json - ARRAY['orderId'::text, 'brokerageMode'::text, 'reconciliationStatus'::text, 'appliedEventCount'::text, 'invalidEventCount'::text, 'hasMore'::text, 'checkedAt'::text]) = '{}'::jsonb)))),
    CONSTRAINT audit_logs_principle_contract_check CHECK (((target_type <> 'PRINCIPLE'::text) OR ((action = ANY (ARRAY['PRINCIPLE_CREATED'::text, 'PRINCIPLE_UPDATED'::text, 'PRINCIPLE_ARCHIVED'::text, 'PRINCIPLE_REACTIVATED'::text])) AND (jsonb_typeof(payload_json) = 'object'::text) AND (payload_json ?& ARRAY['principleId'::text, 'newVersion'::text, 'changedFields'::text]) AND ((payload_json - ARRAY['principleId'::text, 'newVersion'::text, 'changedFields'::text]) = '{}'::jsonb))))
);


