    CONSTRAINT cross_market_risk_snapshots_v2_evidence_mode_check CHECK ((evidence_mode = ANY (ARRAY['SYNTHETIC_FIXTURE'::text, 'HISTORICAL_REPLAY'::text, 'PROSPECTIVE_SHADOW'::text, 'MANUAL_EOD'::text]))),
    CONSTRAINT cross_market_risk_snapshots_v2_explanation_json_check CHECK (((jsonb_typeof(explanation_json) = 'object'::text) AND (octet_length((explanation_json)::text) <= 65536))),
    CONSTRAINT cross_market_risk_snapshots_v2_exposure_catalog_hash_check CHECK ((exposure_catalog_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT cross_market_risk_snapshots_v2_exposure_classification_check CHECK ((exposure_classification = ANY (ARRAY['NEW_BUY'::text, 'INCREASE_BUY'::text, 'SELL'::text, 'REDUCE'::text, 'LIQUIDATION'::text, 'EXISTING_POSITION'::text, 'UNCLASSIFIED'::text]))),
    CONSTRAINT cross_market_risk_snapshots_v2_owner_scope_hash_check CHECK ((owner_scope_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT cross_market_risk_snapshots_v2_payload_json_check CHECK (((jsonb_typeof(payload_json) = 'object'::text) AND ((octet_length((payload_json)::text) >= 2) AND (octet_length((payload_json)::text) <= 262144)))),
    CONSTRAINT cross_market_risk_snapshots_v2_quality_check CHECK ((quality = ANY (ARRAY['PASS'::text, 'WARN'::text, 'EVIDENCE_GAP'::text]))),
    CONSTRAINT cross_market_risk_snapshots_v2_runtime_mode_check CHECK ((runtime_mode = ANY (ARRAY['OFF'::text, 'SHADOW'::text, 'WARN_ONLY'::text, 'ENFORCED'::text]))),
    CONSTRAINT cross_market_risk_snapshots_v2_semantic_input_hash_check CHECK ((semantic_input_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT cross_market_risk_snapshots_v2_storage_mode_check CHECK ((storage_mode = ANY (ARRAY['ARTIFACT_ONLY'::text, 'STORED_SNAPSHOT'::text]))),
    CONSTRAINT cross_market_risk_snapshots_v2_symbol_check CHECK ((symbol ~ '^[0-9A-Z./-]{1,32}$'::text)),
    CONSTRAINT cross_market_v2_available_check CHECK ((((availability = 'AVAILABLE'::text) AND (score IS NOT NULL) AND (threshold_percentile IS NOT NULL) AND (threshold_artifact_hash ~ '^[0-9a-f]{64}$'::text) AND (config_hash <> repeat('0'::text, 64))) OR (availability = ANY (ARRAY['UNAVAILABLE'::text, 'STALE'::text])))),
    CONSTRAINT cross_market_v2_exposure_time_check CHECK ((exposure_available_at = available_at)),
    CONSTRAINT cross_market_v2_score_check CHECK (((score IS NULL) OR ((score >= (0)::numeric) AND (score <= (100)::numeric)))),
    CONSTRAINT cross_market_v2_threshold_check CHECK (((threshold_percentile IS NULL) OR (threshold_percentile = ANY (ARRAY[(95)::numeric, 97.5, (99)::numeric]))))
);

