CREATE VIEW public.current_corporation_registry_projection WITH (security_barrier='true') AS
 WITH latest_registry AS (
         SELECT DISTINCT ON (candidate.symbol, candidate.corp_code) candidate.observation_id,
            candidate.symbol,
            candidate.corp_code,
            candidate.registry_status,
            candidate.completeness,
            candidate.observed_at,
            candidate.received_at,
            candidate.schema_version,
            candidate.source_version,
            candidate.payload_json,
            candidate.source_ref,
            candidate.artifact_hash,
            candidate.created_at
           FROM public.corporation_registry_observations candidate
          ORDER BY candidate.symbol, candidate.corp_code, candidate.observed_at DESC, candidate.received_at DESC, candidate.observation_id
        )
 SELECT observation_id,
    symbol,
    corp_code,
    observed_at,
    received_at,
    schema_version,
    source_version,
    source_ref,
    artifact_hash
   FROM latest_registry registry
  WHERE ((registry_status = 'ACTIVE'::text) AND (completeness = 'COMPLETE'::text));


ALTER VIEW public.current_corporation_registry_projection OWNER TO flyway;


