CREATE TABLE public.decisions (
    decision_id text NOT NULL,
    user_id text NOT NULL,
    principle_version_id text NOT NULL,
    symbol text NOT NULL,
    side text NOT NULL,
    outcome text NOT NULL,
    mode text DEFAULT 'GUIDE'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    evaluation_id text NOT NULL,
    principle_id text NOT NULL,
    principle_version integer NOT NULL,
    portfolio_source text NOT NULL,
    can_submit_order boolean NOT NULL,
    enforcement_action text NOT NULL,
    evaluation_as_of timestamp with time zone NOT NULL,
    result_schema_version text NOT NULL,
    snapshot_schema_version text NOT NULL,
    catalog_version integer NOT NULL,
    readiness_policy_version text NOT NULL,
    mapping_versions_json jsonb NOT NULL,
    semantic_input_hash text NOT NULL,
    snapshot_artifact_hash text NOT NULL,
    result_json jsonb NOT NULL,
    CONSTRAINT decisions_decision_check CHECK ((outcome = ANY (ARRAY['ALLOW'::text, 'WARN'::text, 'HOLD'::text, 'BLOCK'::text]))),
    CONSTRAINT decisions_enforcement_contract_check CHECK ((((outcome = 'ALLOW'::text) AND can_submit_order AND (enforcement_action = 'NONE'::text)) OR ((outcome = 'WARN'::text) AND can_submit_order AND (((mode = 'GUIDE'::text) AND (enforcement_action = 'ACKNOWLEDGE_WARNING'::text)) OR ((mode = 'STRICT'::text) AND (enforcement_action = 'RECONFIRM_PRINCIPLE'::text)))) OR ((outcome = 'HOLD'::text) AND (NOT can_submit_order) AND (enforcement_action = 'RE_EVALUATE'::text)) OR ((outcome = 'BLOCK'::text) AND (NOT can_submit_order) AND (enforcement_action = 'DO_NOT_SUBMIT'::text)))),
    CONSTRAINT decisions_evaluation_time_check CHECK ((created_at >= evaluation_as_of)),
    CONSTRAINT decisions_hash_check CHECK (((semantic_input_hash ~ '^[0-9a-f]{64}$'::text) AND (snapshot_artifact_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT decisions_mapping_versions_check CHECK ((jsonb_typeof(mapping_versions_json) = 'object'::text)),
    CONSTRAINT decisions_mode_check CHECK ((mode = ANY (ARRAY['GUIDE'::text, 'STRICT'::text]))),
    CONSTRAINT decisions_portfolio_source_check CHECK ((portfolio_source = ANY (ARRAY['KIS_MOCK'::text, 'INTERNAL_PAPER'::text]))),
    CONSTRAINT decisions_principle_version_check CHECK ((principle_version > 0)),
    CONSTRAINT decisions_result_check CHECK (((jsonb_typeof(result_json) = 'object'::text) AND (octet_length((result_json)::text) <= 1048576))),
    CONSTRAINT decisions_side_check CHECK ((side = ANY (ARRAY['BUY'::text, 'SELL'::text]))),
    CONSTRAINT decisions_valid_until_after_created_at_check CHECK ((valid_until > created_at)),
    CONSTRAINT decisions_version_text_check CHECK ((((char_length(result_schema_version) >= 1) AND (char_length(result_schema_version) <= 128)) AND ((char_length(snapshot_schema_version) >= 1) AND (char_length(snapshot_schema_version) <= 128)) AND ((char_length(readiness_policy_version) >= 1) AND (char_length(readiness_policy_version) <= 128)) AND (catalog_version > 0)))
);

ALTER TABLE ONLY public.decisions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.decisions OWNER TO flyway;


CREATE TABLE public.deterministic_risk_observations (
    observation_id text NOT NULL,
    owner_user_id text NOT NULL,
    owner_scope_hash text NOT NULL,
    portfolio_source text NOT NULL,
    daily_loss_rate numeric(19,18),
    max_drawdown numeric(19,18),
    annualized_volatility numeric(19,18),
    completeness text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone NOT NULL,
    schema_version text NOT NULL,
    source_version text NOT NULL,
    payload_json jsonb NOT NULL,
    source_ref text NOT NULL,
    artifact_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT deterministic_risk_observations_artifact_hash_check CHECK ((artifact_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT deterministic_risk_observations_completeness_check CHECK ((completeness = ANY (ARRAY['COMPLETE'::text, 'PARTIAL'::text]))),
    CONSTRAINT deterministic_risk_observations_owner_scope_hash_check CHECK ((owner_scope_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT deterministic_risk_observations_portfolio_source_check CHECK ((portfolio_source = ANY (ARRAY['KIS_MOCK'::text, 'INTERNAL_PAPER'::text]))),
    CONSTRAINT deterministic_risk_observations_schema_version_check CHECK (((char_length(schema_version) >= 1) AND (char_length(schema_version) <= 128))),
    CONSTRAINT deterministic_risk_observations_source_ref_check CHECK ((source_ref ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT deterministic_risk_observations_source_version_check CHECK (((char_length(source_version) >= 1) AND (char_length(source_version) <= 128))),
    CONSTRAINT deterministic_risk_payload_check CHECK (((jsonb_typeof(payload_json) = 'object'::text) AND ((octet_length((payload_json)::text) >= 2) AND (octet_length((payload_json)::text) <= 262144)))),
    CONSTRAINT deterministic_risk_time_check CHECK ((received_at >= observed_at)),
    CONSTRAINT deterministic_risk_values_check CHECK ((((daily_loss_rate IS NULL) OR ((daily_loss_rate >= ('-1'::integer)::numeric) AND (daily_loss_rate <= (0)::numeric))) AND ((max_drawdown IS NULL) OR ((max_drawdown >= ('-1'::integer)::numeric) AND (max_drawdown <= (0)::numeric))) AND ((annualized_volatility IS NULL) OR (annualized_volatility >= (0)::numeric)) AND ((completeness = 'PARTIAL'::text) OR ((daily_loss_rate IS NOT NULL) AND (max_drawdown IS NOT NULL) AND (annualized_volatility IS NOT NULL)))))
);


ALTER TABLE public.deterministic_risk_observations OWNER TO flyway;


CREATE VIEW public.disclosure_collection_status_projection WITH (security_barrier='true') AS
 SELECT source_id,
    operation,
    subject AS corp_code,
    window_from,
    window_to,
    mapping_version,
    completed,
    updated_at
   FROM public.calendar_collection_cursors
  WHERE ((source_id = 'opendart-structured-events'::text) AND (subject ~ '^[0-9]{8}$'::text) AND (operation = ANY (ARRAY['piicDecsn'::text, 'cvbdIsDecsn'::text, 'lwstLg'::text, 'accnutAdtorNmNdAdtOpinion'::text, 'dfOcr'::text, 'ctrcvsBgrq'::text, 'dsRsOcr'::text, 'bnkMngtPcbg'::text, 'bnkMngtPcsp'::text, 'bsnSp'::text, 'crDecsn'::text, 'bdwtIsDecsn'::text, 'exbdIsDecsn'::text, 'cmpMgDecsn'::text, 'cmpDvDecsn'::text, 'cmpDvmgDecsn'::text, 'bsnTrfDecsn'::text])));


ALTER VIEW public.disclosure_collection_status_projection OWNER TO flyway;


CREATE VIEW public.disclosure_event_observation_projection WITH (security_barrier='true') AS
 WITH structured_events AS (
         SELECT current_event.event_id,
            current_event.symbol,
            (current_event.detail ->> 'corp_code'::text) AS corp_code,
            ('OPENDART:'::text || (current_event.detail ->> 'endpoint_id'::text)) AS event_code,
            stored_event.source_event_key AS receipt_no,
            current_event.event_date AS occurred_on,
            current_event.detail
           FROM (public.current_calendar_events current_event
             JOIN public.calendar_events stored_event ON ((stored_event.event_id = current_event.event_id)))
          WHERE ((stored_event.source_id = 'opendart-structured-events'::text) AND (current_event.event_type = 'DISCLOSURE'::text) AND (current_event.status <> 'CANCELLED'::text) AND (current_event.detail ? 'endpoint_id'::text))
        UNION ALL
         SELECT current_event.event_id,
            current_event.symbol,
            active_state.corp_code,
            'OPENDART:bnkMngtPcbg'::text AS event_code,
            stored_event.source_event_key AS receipt_no,
            current_event.event_date AS occurred_on,
            current_event.detail
           FROM ((public.active_disclosure_risk_states active_state
             JOIN public.current_calendar_events current_event ON ((current_event.event_id = active_state.canonical_event_id)))
             JOIN public.calendar_events stored_event ON ((stored_event.event_id = current_event.event_id)))
          WHERE ((active_state.state_type = 'BANK_MANAGEMENT'::text) AND (stored_event.source_id = 'opendart-structured-events'::text) AND (current_event.status <> 'CANCELLED'::text))
        )
 SELECT event.event_id,
    event.symbol,
    event.corp_code,
    event.event_code,
    event.receipt_no,
    event.occurred_on,
    observation.observed_at,
    observation.mapping_version AS source_mapping_version,
    source.opaque_source_ref AS source_ref,
    jsonb_strip_nulls(jsonb_build_object('adt_opinion', (event.detail ->> 'adt_opinion'::text))) AS attributes_json
   FROM ((structured_events event
     JOIN public.calendar_event_sources source ON ((source.event_id = event.event_id)))
     JOIN public.calendar_observations observation ON ((observation.observation_id = source.observation_id)))
  WHERE ((event.symbol ~ '^[0-9]{6}$'::text) AND (event.corp_code ~ '^[0-9]{8}$'::text) AND (event.event_code ~ '^OPENDART:[A-Za-z0-9._:-]{1,118}$'::text) AND (event.receipt_no ~ '^[0-9]{14}$'::text) AND (source.opaque_source_ref ~ '^[0-9a-f]{64}$'::text));


ALTER VIEW public.disclosure_event_observation_projection OWNER TO flyway;


CREATE TABLE public.event_outbox (
    event_id text NOT NULL,
    event_type text NOT NULL,
    aggregate_type text NOT NULL,
    aggregate_id text NOT NULL,
    partition_key text NOT NULL,
    payload_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    schema_version text DEFAULT '1.0.0'::text NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    locked_at timestamp with time zone,
    published_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    claim_token uuid,
    claimed_by text,
    lease_expires_at timestamp with time zone,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    failure_code text,
    error_class text,
    transport_payload_hash text,
    CONSTRAINT event_outbox_brokerage_order_contract_check CHECK (((event_type <> ALL (ARRAY['brokerage.mock-order-submitted.v1'::text, 'brokerage.mock-order-cancel-requested.v1'::text, 'brokerage.paper-order-accepted.v1'::text, 'brokerage.paper-order-filled.v1'::text, 'brokerage.paper-order-cancelled.v1'::text])) OR ((event_type = 'brokerage.mock-order-submitted.v1'::text) AND (aggregate_type = 'ORDER'::text) AND (aggregate_id = (payload_json ->> 'orderId'::text)) AND (partition_key = aggregate_id) AND (schema_version = '1.0.0'::text) AND ((payload_json ->> 'brokerageMode'::text) = 'KIS_MOCK'::text) AND ((payload_json ->> 'status'::text) = 'SUBMITTED'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text]) = '{}'::jsonb)) OR ((event_type = 'brokerage.mock-order-cancel-requested.v1'::text) AND (aggregate_type = 'ORDER'::text) AND (aggregate_id = (payload_json ->> 'orderId'::text)) AND (partition_key = aggregate_id) AND (schema_version = '1.0.0'::text) AND ((payload_json ->> 'brokerageMode'::text) = 'KIS_MOCK'::text) AND ((payload_json ->> 'status'::text) = 'CANCEL_REQUESTED'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'brokerageMode'::text, 'status'::text, 'requestedByRole'::text, 'requestedAt'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'brokerageMode'::text, 'status'::text, 'requestedByRole'::text, 'requestedAt'::text]) = '{}'::jsonb)) OR ((event_type = 'brokerage.paper-order-accepted.v1'::text) AND (aggregate_type = 'ORDER'::text) AND (aggregate_id = (payload_json ->> 'orderId'::text)) AND (partition_key = aggregate_id) AND (schema_version = '1.0.0'::text) AND ((payload_json ->> 'brokerageMode'::text) = 'INTERNAL_PAPER'::text) AND ((payload_json ->> 'status'::text) = 'ACCEPTED'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text]) = '{}'::jsonb)) OR ((event_type = 'brokerage.paper-order-filled.v1'::text) AND (aggregate_type = 'ORDER'::text) AND (aggregate_id = (payload_json ->> 'orderId'::text)) AND (partition_key = aggregate_id) AND (schema_version = '1.0.0'::text) AND ((payload_json ->> 'brokerageMode'::text) = 'INTERNAL_PAPER'::text) AND ((payload_json ->> 'status'::text) = 'FILLED'::text) AND ((payload_json ->> 'priceBasis'::text) = ANY (ARRAY['LAST_QUOTE'::text, 'PREVIOUS_CLOSE'::text])) AND (((payload_json ->> 'fillPriceKrw'::text))::bigint > 0) AND (((payload_json ->> 'fillQuantity'::text))::bigint > 0) AND ((((payload_json ->> 'slippageBps'::text))::integer >= 0) AND (((payload_json ->> 'slippageBps'::text))::integer <= 100)) AND ((payload_json ->> 'feeModel'::text) = 'NONE_V1'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text, 'fillPriceKrw'::text, 'fillQuantity'::text, 'priceBasis'::text, 'slippageBps'::text, 'feeModel'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'evaluationId'::text, 'brokerageMode'::text, 'status'::text, 'idempotencyScopeHash'::text, 'fillPriceKrw'::text, 'fillQuantity'::text, 'priceBasis'::text, 'slippageBps'::text, 'feeModel'::text]) = '{}'::jsonb)) OR ((event_type = 'brokerage.paper-order-cancelled.v1'::text) AND (aggregate_type = 'ORDER'::text) AND (aggregate_id = (payload_json ->> 'orderId'::text)) AND (partition_key = aggregate_id) AND (schema_version = '1.0.0'::text) AND ((payload_json ->> 'brokerageMode'::text) = 'INTERNAL_PAPER'::text) AND ((payload_json ->> 'status'::text) = 'CANCELLED'::text) AND (payload_json ?& ARRAY['orderId'::text, 'decisionId'::text, 'brokerageMode'::text, 'status'::text, 'requestedByRole'::text, 'requestedAt'::text]) AND ((payload_json - ARRAY['orderId'::text, 'decisionId'::text, 'brokerageMode'::text, 'status'::text, 'requestedByRole'::text, 'requestedAt'::text]) = '{}'::jsonb)))),
    CONSTRAINT event_outbox_claim_tuple_check CHECK ((((claim_token IS NULL) AND (claimed_by IS NULL) AND (lease_expires_at IS NULL)) OR ((claim_token IS NOT NULL) AND (claimed_by IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT event_outbox_claimed_by_check CHECK (((claimed_by IS NULL) OR (claimed_by ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{2,63}$'::text))),
    CONSTRAINT event_outbox_decision_contract_check CHECK (((event_type <> 'risk.decision-created.v1'::text) OR ((aggregate_type = 'DECISION'::text) AND (aggregate_id = (payload_json ->> 'decisionId'::text)) AND (partition_key = aggregate_id) AND (schema_version = '1.0.0'::text) AND (payload_json ?& ARRAY['evaluationId'::text, 'decisionId'::text, 'outcome'::text, 'principleVersionId'::text, 'semanticInputHash'::text, 'snapshotArtifactHash'::text]) AND ((payload_json - ARRAY['evaluationId'::text, 'decisionId'::text, 'outcome'::text, 'principleVersionId'::text, 'semanticInputHash'::text, 'snapshotArtifactHash'::text]) = '{}'::jsonb)))),
    CONSTRAINT event_outbox_error_bound_check CHECK (((last_error IS NULL) OR (octet_length(last_error) <= 128))),
    CONSTRAINT event_outbox_error_class_check CHECK (((error_class IS NULL) OR ((octet_length(error_class) <= 128) AND (error_class ~ '^[A-Z][A-Z0-9_]{2,63}$'::text)))),
    CONSTRAINT event_outbox_failure_code_check CHECK (((failure_code IS NULL) OR ((octet_length(failure_code) <= 128) AND (failure_code ~ '^[A-Z][A-Z0-9_]{2,63}$'::text)))),
    CONSTRAINT event_outbox_kill_switch_contract_check CHECK (((event_type <> 'kill-switch.changed'::text) OR ((aggregate_type = 'KILL_SWITCH'::text) AND (aggregate_id = 'GLOBAL'::text) AND (partition_key = 'GLOBAL'::text) AND (schema_version = '1.0.0'::text) AND (payload_json ?& ARRAY['active'::text, 'changedAt'::text]) AND ((payload_json - ARRAY['active'::text, 'changedAt'::text]) = '{}'::jsonb)))),
    CONSTRAINT event_outbox_order_reconciliation_contract_check CHECK (((event_type <> 'brokerage.order-reconciled.v1'::text) OR ((aggregate_type = 'ORDER'::text) AND (aggregate_id = (payload_json ->> 'orderId'::text)) AND (partition_key = aggregate_id) AND (schema_version = '1.0.0'::text) AND ((payload_json ->> 'brokerageMode'::text) = ANY (ARRAY['KIS_MOCK'::text, 'INTERNAL_PAPER'::text])) AND ((payload_json ->> 'reconciliationStatus'::text) = ANY (ARRAY['NOT_APPLICABLE'::text, 'MATCHED'::text, 'MISMATCH'::text])) AND (payload_json ?& ARRAY['orderId'::text, 'brokerageMode'::text, 'reconciliationStatus'::text, 'appliedEventCount'::text, 'invalidEventCount'::text, 'hasMore'::text, 'checkedAt'::text]) AND ((payload_json - ARRAY['orderId'::text, 'brokerageMode'::text, 'reconciliationStatus'::text, 'appliedEventCount'::text, 'invalidEventCount'::text, 'hasMore'::text, 'checkedAt'::text]) = '{}'::jsonb)))),
    CONSTRAINT event_outbox_payload_bound_check CHECK ((octet_length((payload_json)::text) <= 32768)),
    CONSTRAINT event_outbox_retry_cap_check CHECK (((retry_count >= 0) AND (retry_count <= 3))),
    CONSTRAINT event_outbox_retry_count_check CHECK ((retry_count >= 0)),
    CONSTRAINT event_outbox_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'PUBLISHED'::text, 'FAILED'::text, 'DLQ_REQUESTED'::text]))),
    CONSTRAINT event_outbox_transport_payload_hash_check CHECK (((transport_payload_hash IS NULL) OR (transport_payload_hash ~ '^sha256:[0-9a-f]{64}$'::text)))
);


ALTER TABLE public.event_outbox OWNER TO flyway;


CREATE TABLE public.event_outbox_transition_audit (
    transition_id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id text NOT NULL,
    previous_status text NOT NULL,
