    failure_code text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_outbox_transition_audit_check CHECK ((previous_status <> next_status)),
    CONSTRAINT event_outbox_transition_audit_failure_code_check CHECK (((failure_code IS NULL) OR (failure_code ~ '^[A-Z][A-Z0-9_]{2,63}$'::text))),
    CONSTRAINT event_outbox_transition_audit_next_status_check CHECK ((next_status = ANY (ARRAY['PENDING'::text, 'PUBLISHED'::text, 'FAILED'::text, 'DLQ_REQUESTED'::text]))),
    CONSTRAINT event_outbox_transition_audit_previous_status_check CHECK ((previous_status = ANY (ARRAY['PENDING'::text, 'PUBLISHED'::text, 'FAILED'::text, 'DLQ_REQUESTED'::text])))
);


