    CONSTRAINT financial_engineering_snapshots_numeric_payload_hash_check CHECK ((numeric_payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT financial_engineering_snapshots_quality_check CHECK ((quality = ANY (ARRAY['PASS'::text, 'WARN'::text, 'EVIDENCE_GAP'::text]))),
    CONSTRAINT financial_engineering_snapshots_schema_version_check CHECK ((schema_version = 1)),
    CONSTRAINT financial_engineering_snapshots_snapshot_id_check CHECK ((snapshot_id ~ '^fes_[0-9a-f]{24}$'::text)),
    CONSTRAINT financial_engineering_snapshots_source_manifest_hash_check CHECK ((source_manifest_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT financial_engineering_snapshots_staleness_check CHECK ((staleness = ANY (ARRAY['FRESH'::text, 'STALE'::text, 'NOT_ESTIMABLE'::text]))),
    CONSTRAINT financial_engineering_snapshots_symbol_check CHECK ((symbol ~ '^[0-9A-Z./-]{1,32}$'::text))
);

