    CONSTRAINT foreign_news_sentiment_hash_check CHECK (((payload_hash ~ '^[0-9a-f]{64}$'::text) AND (artifact_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT foreign_news_sentiment_identity_hash_check CHECK ((logical_identity_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT foreign_news_sentiment_lanes_check CHECK (((jsonb_typeof(lane_states) = 'array'::text) AND (jsonb_array_length(lane_states) = 4))),
    CONSTRAINT foreign_news_sentiment_payload_check CHECK ((jsonb_typeof(payload_json) = 'object'::text)),
    CONSTRAINT foreign_news_sentiment_status_check CHECK ((status = ANY (ARRAY['AVAILABLE'::text, 'ABSTAIN'::text]))),
    CONSTRAINT foreign_news_sentiment_symbol_check CHECK ((symbol ~ '^[0-9A-Z._:-]{1,20}$'::text))
);

ALTER TABLE ONLY public.foreign_news_sentiment_aggregates FORCE ROW LEVEL SECURITY;


ALTER TABLE public.foreign_news_sentiment_aggregates OWNER TO flyway;


CREATE TABLE public.ingested_signals (
    signal_id text NOT NULL,
    producer text NOT NULL,
    source_workspace text NOT NULL,
    symbol text NOT NULL,
    as_of timestamp with time zone,
    timeframe text NOT NULL,
    confidence numeric(10,6),
    predicted_return numeric(10,6),
    feature_summary_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    contract_version text NOT NULL,
    status text NOT NULL,
    reason text,
    signal text,
    evaluation_id text NOT NULL,
    model_version text,
    model_report_id text,
    artifact_sha256 text,
    payload_sha256 text,
    provenance_sha256 text,
    logical_identity_sha256 text,
    fixture boolean NOT NULL,
    provenance_class text NOT NULL,
    payload_canonical_text text NOT NULL,
    artifact_verified boolean DEFAULT false NOT NULL,
    session_date date NOT NULL,
    model_release_id text,
    signal_batch_id text,
    CONSTRAINT ingested_signals_s5_digest_check CHECK (((contract_version = 'LEGACY_UNVERIFIED'::text) OR ((artifact_sha256 ~ '^[0-9a-f]{64}$'::text) AND (payload_sha256 ~ '^[0-9a-f]{64}$'::text) AND (provenance_sha256 ~ '^[0-9a-f]{64}$'::text) AND (logical_identity_sha256 ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT ingested_signals_s5_fixture_check CHECK (((fixture AND (provenance_class = ANY (ARRAY['FAKE_CONTRACT'::text, 'LEGACY_UNVERIFIED'::text]))) OR ((NOT fixture) AND (provenance_class = 'PRODUCTION'::text)))),
    CONSTRAINT ingested_signals_s5_identity_shape_check CHECK (((contract_version = 'LEGACY_UNVERIFIED'::text) OR ((symbol ~ '^[0-9A-Z._:-]{1,20}$'::text) AND (evaluation_id ~ '^[A-Za-z0-9._:-]{1,128}$'::text) AND (model_version IS NOT NULL) AND ((char_length(model_version) >= 1) AND (char_length(model_version) <= 128)) AND (model_report_id IS NOT NULL) AND ((char_length(model_report_id) >= 1) AND (char_length(model_report_id) <= 128)) AND ((octet_length(payload_canonical_text) >= 2) AND (octet_length(payload_canonical_text) <= 65536)) AND artifact_verified))),
    CONSTRAINT ingested_signals_s5_numeric_check CHECK (((contract_version = 'LEGACY_UNVERIFIED'::text) OR (((confidence IS NULL) OR (((confidence)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text])) AND ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))) AND ((predicted_return IS NULL) OR ((predicted_return)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text])))))),
    CONSTRAINT ingested_signals_s5_producer_workspace_check CHECK ((((producer = ANY (ARRAY['RULE_BASELINE'::text, 'LSTM'::text])) AND (source_workspace = 'return-engine'::text)) OR ((producer = ANY (ARRAY['LIGHTGBM'::text, 'HMM'::text])) AND (source_workspace = 'decision-platform'::text)) OR (contract_version = 'LEGACY_UNVERIFIED'::text))),
    CONSTRAINT ingested_signals_s5_reason_check CHECK (((reason IS NULL) OR (reason = ANY (ARRAY['ARTIFACT_DRIFT'::text, 'STALE_EVIDENCE'::text, 'CALIBRATION_FAILED'::text, 'UNIDENTIFIABLE_OUTPUT'::text, 'MISSING_EVIDENCE'::text, 'POSTERIOR_BELOW_THRESHOLD'::text, 'PRODUCER_FAILED'::text])))),
    CONSTRAINT ingested_signals_s5_signal_check CHECK (((signal IS NULL) OR (signal = ANY (ARRAY['BUY'::text, 'HOLD'::text, 'SELL'::text])))),
    CONSTRAINT ingested_signals_s5_status_check CHECK ((status = ANY (ARRAY['AVAILABLE'::text, 'ABSTAIN'::text]))),
    CONSTRAINT ingested_signals_s5_union_check CHECK (((contract_version = 'LEGACY_UNVERIFIED'::text) OR ((contract_version = 'signal-v2-runtime-v1'::text) AND (timeframe = '1d'::text) AND (((status = 'AVAILABLE'::text) AND (as_of IS NOT NULL) AND (signal IS NOT NULL) AND (confidence IS NOT NULL) AND (reason IS NULL)) OR ((status = 'ABSTAIN'::text) AND (reason IS NOT NULL) AND (as_of IS NULL) AND (signal IS NULL) AND (confidence IS NULL) AND (predicted_return IS NULL))))))
);

ALTER TABLE ONLY public.ingested_signals FORCE ROW LEVEL SECURITY;


ALTER TABLE public.ingested_signals OWNER TO flyway;


