    CONSTRAINT kafka_poison_receipt_failure_code_check CHECK ((failure_code ~ '^[A-Z][A-Z0-9_]{2,63}$'::text)),
    CONSTRAINT kafka_poison_receipt_payload_hash_check CHECK ((payload_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT kafka_poison_receipt_source_offset_check CHECK ((source_offset >= 0)),
    CONSTRAINT kafka_poison_receipt_source_partition_check CHECK (((source_partition >= 0) AND (source_partition <= 1023)))
);


ALTER TABLE public.kafka_poison_receipt OWNER TO flyway;


CREATE TABLE public.risk_kill_switch (
    kill_switch_id text NOT NULL,
    active boolean NOT NULL,
    reason_class text NOT NULL,
    generation bigint NOT NULL,
    changed_by text,
    changed_by_role text NOT NULL,
    changed_at timestamp with time zone NOT NULL,
    request_id text,
    CONSTRAINT risk_kill_switch_actor_check CHECK ((((changed_by_role = 'SYSTEM'::text) AND (changed_by IS NULL)) OR ((changed_by_role = ANY (ARRAY['USER'::text, 'ADMIN'::text])) AND (changed_by IS NOT NULL)))),
    CONSTRAINT risk_kill_switch_changed_by_role_check CHECK ((changed_by_role = ANY (ARRAY['USER'::text, 'ADMIN'::text, 'SYSTEM'::text]))),
    CONSTRAINT risk_kill_switch_generation_check CHECK ((generation > 0)),
    CONSTRAINT risk_kill_switch_kill_switch_id_check CHECK ((kill_switch_id = 'GLOBAL'::text)),
    CONSTRAINT risk_kill_switch_reason_class_check CHECK ((reason_class = ANY (ARRAY['USER_MANUAL_STOP'::text, 'OPERATOR_MANUAL_STOP'::text, 'DATA_FRESHNESS_STOP'::text, 'BROKERAGE_FAILURE_STOP'::text, 'DEMO_SAFETY_STOP'::text, 'ADMIN_RESUME'::text, 'INITIAL_STATE'::text]))),
    CONSTRAINT risk_kill_switch_request_id_check CHECK (((request_id IS NULL) OR ((char_length(request_id) >= 1) AND (char_length(request_id) <= 128)))),
    CONSTRAINT risk_kill_switch_resume_role_check CHECK ((active OR (changed_by_role = ANY (ARRAY['ADMIN'::text, 'SYSTEM'::text]))))
);


ALTER TABLE public.risk_kill_switch OWNER TO flyway;


CREATE VIEW public.kill_switch_user_projection WITH (security_barrier='true') AS
