CREATE VIEW public.latest_analyst_revision_evidence AS
 SELECT logical_identity_hash,
    original_evidence_id,
    symbol,
    broker_id,
    estimate_period,
    contributor_count,
    buy_opinion_weight,
    dispersion,
    published_at,
    received_at,
    available_at,
    retracted,
    supersedes_evidence_id,
    artifact_hash,
    payload_json
   FROM ( SELECT evidence.logical_identity_hash,
            evidence.original_evidence_id,
            evidence.symbol,
            evidence.broker_id,
            evidence.estimate_period,
            evidence.contributor_count,
            evidence.buy_opinion_weight,
            evidence.dispersion,
            evidence.published_at,
            evidence.received_at,
            evidence.available_at,
            evidence.retracted,
            evidence.supersedes_evidence_id,
            evidence.dedupe_key_hash,
            evidence.payload_hash,
            evidence.artifact_hash,
            evidence.payload_json,
            evidence.created_at,
            row_number() OVER (PARTITION BY evidence.symbol, evidence.broker_id, evidence.estimate_period ORDER BY evidence.available_at DESC, evidence.published_at DESC, evidence.logical_identity_hash) AS bounded_rank
           FROM public.analyst_revision_evidence evidence) ranked
  WHERE (bounded_rank = 1);


ALTER VIEW public.latest_analyst_revision_evidence OWNER TO flyway;


