CREATE TABLE public.market_cause_evidence (
    logical_identity_hash text NOT NULL,
    source_family text NOT NULL,
    source_lineage_hash text NOT NULL,
    dedupe_key_hash text NOT NULL,
    classification text NOT NULL,
    relation text NOT NULL,
    counterargument boolean NOT NULL,
    retracted boolean NOT NULL,
    supersedes_evidence_id text,
    occurred_at timestamp with time zone NOT NULL,
    published_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone NOT NULL,
    available_at timestamp with time zone NOT NULL,
    sanitized_summary text NOT NULL,
    payload_hash text NOT NULL,
    artifact_hash text NOT NULL,
    payload_json jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT market_cause_classification_check CHECK ((classification = ANY (ARRAY['CONFIRMED_FACT'::text, 'REPORTED_CLAIM'::text, 'MARKET_INTERPRETATION'::text, 'HYPOTHESIS'::text]))),
    CONSTRAINT market_cause_dedupe_hash_check CHECK ((dedupe_key_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_cause_gdelt_authority_check CHECK (((source_family <> 'GDELT_AGGREGATE'::text) OR ((classification = ANY (ARRAY['REPORTED_CLAIM'::text, 'MARKET_INTERPRETATION'::text, 'HYPOTHESIS'::text])) AND (relation <> 'REPORTED_AS_CAUSE'::text)))),
    CONSTRAINT market_cause_hash_check CHECK (((payload_hash ~ '^[0-9a-f]{64}$'::text) AND (artifact_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT market_cause_identity_hash_check CHECK ((logical_identity_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_cause_lineage_hash_check CHECK ((source_lineage_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_cause_payload_check CHECK ((jsonb_typeof(payload_json) = 'object'::text)),
    CONSTRAINT market_cause_relation_check CHECK ((relation = ANY (ARRAY['PRECEDES'::text, 'CO_MOVES_WITH'::text, 'REPORTED_AS_CAUSE'::text, 'CORROBORATES'::text, 'CONTRADICTS'::text]))),
    CONSTRAINT market_cause_summary_check CHECK (((length(sanitized_summary) >= 1) AND (length(sanitized_summary) <= 1000))),
    CONSTRAINT market_cause_time_check CHECK (((occurred_at <= published_at) AND (published_at <= received_at) AND (received_at <= available_at)))
);


ALTER TABLE public.market_cause_evidence OWNER TO flyway;


CREATE VIEW public.latest_market_cause_evidence AS
 SELECT logical_identity_hash,
    source_family,
    source_lineage_hash,
    dedupe_key_hash,
    classification,
    relation,
    counterargument,
    retracted,
    supersedes_evidence_id,
    occurred_at,
    published_at,
    received_at,
    available_at,
    sanitized_summary,
    artifact_hash,
    payload_json
   FROM ( SELECT evidence.logical_identity_hash,
            evidence.source_family,
            evidence.source_lineage_hash,
            evidence.dedupe_key_hash,
            evidence.classification,
            evidence.relation,
            evidence.counterargument,
            evidence.retracted,
            evidence.supersedes_evidence_id,
            evidence.occurred_at,
            evidence.published_at,
            evidence.received_at,
            evidence.available_at,
            evidence.sanitized_summary,
            evidence.payload_hash,
            evidence.artifact_hash,
            evidence.payload_json,
            evidence.created_at,
            row_number() OVER (PARTITION BY evidence.source_family, evidence.dedupe_key_hash ORDER BY evidence.available_at DESC, evidence.published_at DESC, evidence.logical_identity_hash) AS bounded_rank
           FROM public.market_cause_evidence evidence) ranked
  WHERE (bounded_rank = 1);


ALTER VIEW public.latest_market_cause_evidence OWNER TO flyway;


CREATE TABLE public.market_quote_observations (
    observation_id text NOT NULL,
    symbol text NOT NULL,
    source text NOT NULL,
    price_krw bigint,
    bid_krw bigint,
    ask_krw bigint,
    completeness text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone NOT NULL,
    schema_version text NOT NULL,
    source_version text NOT NULL,
    payload_json jsonb NOT NULL,
    source_ref text NOT NULL,
    artifact_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    previous_close_krw bigint,
    CONSTRAINT market_quote_completeness_check CHECK (((completeness = 'PARTIAL'::text) OR ((bid_krw IS NOT NULL) AND (ask_krw IS NOT NULL)))),
    CONSTRAINT market_quote_observations_artifact_hash_check CHECK ((artifact_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_quote_observations_ask_krw_check CHECK ((ask_krw > 0)),
    CONSTRAINT market_quote_observations_bid_krw_check CHECK ((bid_krw > 0)),
    CONSTRAINT market_quote_observations_completeness_check CHECK ((completeness = ANY (ARRAY['COMPLETE'::text, 'PARTIAL'::text]))),
    CONSTRAINT market_quote_observations_price_krw_check CHECK ((price_krw > 0)),
    CONSTRAINT market_quote_observations_schema_version_check CHECK (((char_length(schema_version) >= 1) AND (char_length(schema_version) <= 128))),
    CONSTRAINT market_quote_observations_source_check CHECK ((source = 'KIS_MOCK'::text)),
    CONSTRAINT market_quote_observations_source_ref_check CHECK ((source_ref ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_quote_observations_source_version_check CHECK (((char_length(source_version) >= 1) AND (char_length(source_version) <= 128))),
    CONSTRAINT market_quote_observations_symbol_check CHECK ((symbol ~ '^[0-9A-Z._:-]{1,20}$'::text)),
    CONSTRAINT market_quote_payload_check CHECK (((jsonb_typeof(payload_json) = 'object'::text) AND ((octet_length((payload_json)::text) >= 2) AND (octet_length((payload_json)::text) <= 65536)))),
    CONSTRAINT market_quote_previous_close_check CHECK (((previous_close_krw IS NULL) OR (previous_close_krw > 0))),
    CONSTRAINT market_quote_price_source_check CHECK (((price_krw IS NOT NULL) OR (previous_close_krw IS NOT NULL))),
    CONSTRAINT market_quote_spread_check CHECK (((bid_krw IS NULL) OR (ask_krw IS NULL) OR (bid_krw <= ask_krw))),
    CONSTRAINT market_quote_time_check CHECK ((received_at >= observed_at))
);


ALTER TABLE public.market_quote_observations OWNER TO flyway;


CREATE VIEW public.latest_market_quote_observations WITH (security_barrier='true') AS
 SELECT DISTINCT ON (symbol) observation_id,
    symbol,
    source,
    price_krw,
    bid_krw,
    ask_krw,
    completeness,
    observed_at,
    received_at,
    schema_version,
    source_version,
    source_ref,
    artifact_hash,
    previous_close_krw
   FROM public.market_quote_observations
  ORDER BY symbol, observed_at DESC, received_at DESC, observation_id;


ALTER VIEW public.latest_market_quote_observations OWNER TO flyway;


CREATE TABLE public.portfolio_balance_observations (
