    owner_user_id text NOT NULL,
    account_scope_hash text NOT NULL,
    source text NOT NULL,
    context_status text NOT NULL,
    cash_krw bigint NOT NULL,
    portfolio_equity_krw bigint NOT NULL,
    margin_requirement_krw bigint NOT NULL,
    completeness text NOT NULL,
    position_count integer NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone NOT NULL,
    schema_version text NOT NULL,
    source_version text NOT NULL,
    payload_json jsonb NOT NULL,
    source_ref text NOT NULL,
    artifact_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portfolio_balance_observations_account_scope_hash_check CHECK ((account_scope_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT portfolio_balance_observations_artifact_hash_check CHECK ((artifact_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT portfolio_balance_observations_cash_krw_check CHECK ((cash_krw >= 0)),
    CONSTRAINT portfolio_balance_observations_completeness_check CHECK ((completeness = ANY (ARRAY['COMPLETE'::text, 'PARTIAL'::text]))),
    CONSTRAINT portfolio_balance_observations_context_status_check CHECK ((context_status = ANY (ARRAY['ACTIVE'::text, 'INACTIVE'::text]))),
    CONSTRAINT portfolio_balance_observations_margin_requirement_krw_check CHECK ((margin_requirement_krw >= 0)),
    CONSTRAINT portfolio_balance_observations_portfolio_equity_krw_check CHECK ((portfolio_equity_krw >= 0)),
    CONSTRAINT portfolio_balance_observations_position_count_check CHECK (((position_count >= 0) AND (position_count <= 1000))),
    CONSTRAINT portfolio_balance_observations_schema_version_check CHECK (((char_length(schema_version) >= 1) AND (char_length(schema_version) <= 128))),
    CONSTRAINT portfolio_balance_observations_source_check CHECK ((source = 'KIS_MOCK'::text)),
    CONSTRAINT portfolio_balance_observations_source_ref_check CHECK ((source_ref ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT portfolio_balance_observations_source_version_check CHECK (((char_length(source_version) >= 1) AND (char_length(source_version) <= 128))),
    CONSTRAINT portfolio_balance_payload_check CHECK (((jsonb_typeof(payload_json) = 'object'::text) AND ((octet_length((payload_json)::text) >= 2) AND (octet_length((payload_json)::text) <= 262144)))),
    CONSTRAINT portfolio_balance_time_check CHECK ((received_at >= observed_at))
);


ALTER TABLE public.portfolio_balance_observations OWNER TO flyway;


CREATE TABLE public.portfolio_position_observations (
