    CONSTRAINT trading_sessions_canonical_hash_check CHECK ((char_length(canonical_hash) = 64)),
    CONSTRAINT trading_sessions_check CHECK (((is_open AND (open_at IS NOT NULL) AND (close_at IS NOT NULL) AND (close_at > open_at)) OR ((NOT is_open) AND (open_at IS NULL) AND (close_at IS NULL)))),
    CONSTRAINT trading_sessions_confidence_bps_check CHECK (((confidence_bps >= 0) AND (confidence_bps <= 9900))),
    CONSTRAINT trading_sessions_exchange_mic_check CHECK ((exchange_mic ~ '^[A-Z0-9]{4}$'::text)),
    CONSTRAINT trading_sessions_timezone_check CHECK ((timezone = 'Asia/Seoul'::text))
);


