    temporal_quality text NOT NULL,
    source_receipt_sha256 text NOT NULL,
    CONSTRAINT market_data_bars_currency_check CHECK ((currency = 'KRW'::text)),
    CONSTRAINT market_data_bars_price_check CHECK (((open_price > 0) AND (high_price >= open_price) AND (high_price >= close_price) AND (low_price > 0) AND (low_price <= open_price) AND (low_price <= close_price) AND (close_price > 0) AND (volume >= 0))),
    CONSTRAINT market_data_bars_quality_check CHECK ((temporal_quality = ANY (ARRAY['PROVIDER_VINTAGE'::text, 'PROVIDER_AS_OF_NO_VINTAGE'::text, 'RECONSTRUCTED_FIXED_LAG'::text, 'COLLECTION_ONLY'::text]))),
