    CONSTRAINT market_data_indices_receipt_check CHECK ((source_receipt_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_data_indices_value_check CHECK (((close_value > (0)::double precision) AND (close_value < 'Infinity'::double precision)))
);


ALTER TABLE public.market_data_indices OWNER TO flyway;


