    CONSTRAINT market_data_macro_receipt_check CHECK ((source_receipt_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_data_macro_series_check CHECK ((series_id = ANY (ARRAY['722Y001/0101000/D'::text, '731Y001/0000001/D'::text]))),
    CONSTRAINT market_data_macro_value_check CHECK (((char_length(value_text) >= 1) AND (char_length(value_text) <= 64)))
);


ALTER TABLE public.market_data_macro OWNER TO flyway;


CREATE TABLE public.market_data_manifests (
    manifest_sha256 text NOT NULL,
    manifest_kind text NOT NULL,
    contract_id text NOT NULL,
    session_date date NOT NULL,
    as_of timestamp with time zone NOT NULL,
    generation integer NOT NULL,
    source_manifest_sha256 text NOT NULL,
    previous_manifest_sha256 text,
    supersedes_sha256 text,
    archive_sha256 text NOT NULL,
    receipt_set_sha256 text,
    calendar_revision text NOT NULL,
    calendar_sha256 text NOT NULL,
    temporal_quality text NOT NULL,
    entitlement_expires_at date,
    status text DEFAULT 'ACCEPTED'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT market_data_archive_sha_check CHECK ((archive_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_data_calendar_sha_check CHECK ((calendar_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_data_contract_id_check CHECK ((((manifest_kind = 'SEED'::text) AND (contract_id = 'market-data-seed.v1'::text)) OR ((manifest_kind = 'DAILY'::text) AND (contract_id = 'market-data-daily-shard.v1'::text)))),
    CONSTRAINT market_data_generation_check CHECK ((generation >= 1)),
    CONSTRAINT market_data_generation_supersedes_check CHECK ((((generation = 1) AND (supersedes_sha256 IS NULL)) OR ((generation > 1) AND (supersedes_sha256 IS NOT NULL)))),
    CONSTRAINT market_data_manifest_kind_check CHECK ((manifest_kind = ANY (ARRAY['SEED'::text, 'DAILY'::text]))),
    CONSTRAINT market_data_manifest_sha_check CHECK ((manifest_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_data_previous_manifest_sha_check CHECK (((previous_manifest_sha256 IS NULL) OR (previous_manifest_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT market_data_receipt_set_sha_check CHECK (((receipt_set_sha256 IS NULL) OR (receipt_set_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT market_data_source_manifest_sha_check CHECK ((source_manifest_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_data_status_check CHECK ((status = 'ACCEPTED'::text)),
    CONSTRAINT market_data_supersedes_sha_check CHECK (((supersedes_sha256 IS NULL) OR (supersedes_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT market_data_temporal_quality_check CHECK ((temporal_quality = ANY (ARRAY['PROVIDER_VINTAGE'::text, 'PROVIDER_AS_OF_NO_VINTAGE'::text, 'RECONSTRUCTED_FIXED_LAG'::text, 'COLLECTION_ONLY'::text])))
);


ALTER TABLE public.market_data_manifests OWNER TO flyway;


CREATE TABLE public.market_data_universes (
    manifest_sha256 text NOT NULL,
    generation integer NOT NULL,
    membership_month text NOT NULL,
    selection_session date NOT NULL,
    effective_from_session date NOT NULL,
    instrument_id text NOT NULL,
    symbol text NOT NULL,
    market text NOT NULL,
    rank integer NOT NULL,
    is_fixed_member boolean NOT NULL,
    temporal_quality text NOT NULL,
    source_receipt_sha256 text NOT NULL,
    CONSTRAINT market_data_universes_fixed_check CHECK ((((symbol = '132030'::text) AND (rank = 31) AND is_fixed_member) OR ((symbol <> '132030'::text) AND (rank <= 30) AND (NOT is_fixed_member)))),
    CONSTRAINT market_data_universes_identity_check CHECK (((instrument_id ~ '^[0-9A-Z]{12}$'::text) OR (instrument_id = 'XKRX:ETF:132030'::text))),
    CONSTRAINT market_data_universes_market_check CHECK ((market = ANY (ARRAY['KOSPI'::text, 'KOSDAQ'::text]))),
    CONSTRAINT market_data_universes_month_check CHECK ((membership_month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'::text)),
    CONSTRAINT market_data_universes_quality_check CHECK ((temporal_quality = ANY (ARRAY['PROVIDER_VINTAGE'::text, 'PROVIDER_AS_OF_NO_VINTAGE'::text, 'RECONSTRUCTED_FIXED_LAG'::text, 'COLLECTION_ONLY'::text]))),
    CONSTRAINT market_data_universes_rank_check CHECK (((rank >= 1) AND (rank <= 31))),
    CONSTRAINT market_data_universes_receipt_check CHECK ((source_receipt_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_data_universes_symbol_check CHECK ((symbol ~ '^[0-9A-Z]{6}$'::text))
);


ALTER TABLE public.market_data_universes OWNER TO flyway;


CREATE VIEW public.market_data_operational_universe WITH (security_barrier='true') AS
 SELECT membership_month,
    symbol,
    market,
    rank,
    is_fixed_member,
    source_receipt_sha256
   FROM public.market_data_universes
  WHERE ((membership_month = ( SELECT max(market_data_universes_1.membership_month) AS max
           FROM public.market_data_universes market_data_universes_1)) AND (generation = ( SELECT max(market_data_universes_1.generation) AS max
           FROM public.market_data_universes market_data_universes_1
          WHERE (market_data_universes_1.membership_month = ( SELECT max(market_data_universes_2.membership_month) AS max
                   FROM public.market_data_universes market_data_universes_2)))))
  ORDER BY rank;


ALTER VIEW public.market_data_operational_universe OWNER TO flyway;


CREATE VIEW public.market_data_operational_bars WITH (security_barrier='true') AS
 SELECT symbol,
    session_date,
    open_price,
    high_price,
    low_price,
    close_price,
    volume,
    currency,
    temporal_quality,
    source_receipt_sha256
   FROM ( SELECT latest.manifest_sha256,
            latest.generation,
            latest.symbol,
            latest.session_date,
            latest.open_price,
            latest.high_price,
            latest.low_price,
            latest.close_price,
            latest.volume,
            latest.currency,
            latest.temporal_quality,
            latest.source_receipt_sha256,
            row_number() OVER (PARTITION BY latest.symbol ORDER BY latest.session_date DESC) AS history_rank
           FROM ( SELECT DISTINCT ON (b.symbol, b.session_date) b.manifest_sha256,
                    b.generation,
                    b.symbol,
                    b.session_date,
                    b.open_price,
                    b.high_price,
                    b.low_price,
                    b.close_price,
                    b.volume,
                    b.currency,
                    b.temporal_quality,
                    b.source_receipt_sha256
                   FROM (public.market_data_bars b
                     JOIN public.market_data_operational_universe u ON ((u.symbol = b.symbol)))
                  ORDER BY b.symbol, b.session_date, b.generation DESC) latest) bounded
  WHERE (history_rank <= 253);


ALTER VIEW public.market_data_operational_bars OWNER TO flyway;


CREATE VIEW public.market_data_research_bars WITH (security_barrier='true') AS
 SELECT symbol,
    session_date,
    open_price,
    high_price,
    low_price,
    close_price,
    volume,
    currency,
    temporal_quality,
    source_receipt_sha256
   FROM ( SELECT latest.manifest_sha256,
            latest.generation,
            latest.symbol,
            latest.session_date,
            latest.open_price,
            latest.high_price,
            latest.low_price,
            latest.close_price,
            latest.volume,
            latest.currency,
            latest.temporal_quality,
            latest.source_receipt_sha256,
            row_number() OVER (PARTITION BY latest.symbol ORDER BY latest.session_date DESC) AS history_rank
           FROM ( SELECT DISTINCT ON (market_data_bars.symbol, market_data_bars.session_date) market_data_bars.manifest_sha256,
                    market_data_bars.generation,
                    market_data_bars.symbol,
                    market_data_bars.session_date,
                    market_data_bars.open_price,
                    market_data_bars.high_price,
                    market_data_bars.low_price,
                    market_data_bars.close_price,
                    market_data_bars.volume,
                    market_data_bars.currency,
                    market_data_bars.temporal_quality,
                    market_data_bars.source_receipt_sha256
                   FROM public.market_data_bars
                  ORDER BY market_data_bars.symbol, market_data_bars.session_date, market_data_bars.generation DESC) latest) bounded
  WHERE (history_rank <= 1260);


ALTER VIEW public.market_data_research_bars OWNER TO flyway;


CREATE VIEW public.market_data_research_indices WITH (security_barrier='true') AS
 SELECT index_id,
    session_date,
    close_value,
    temporal_quality,
    source_receipt_sha256
   FROM ( SELECT latest.manifest_sha256,
            latest.generation,
            latest.index_id,
            latest.session_date,
            latest.close_value,
            latest.temporal_quality,
            latest.source_receipt_sha256,
            row_number() OVER (PARTITION BY latest.index_id ORDER BY latest.session_date DESC) AS history_rank
           FROM ( SELECT DISTINCT ON (market_data_indices.index_id, market_data_indices.session_date) market_data_indices.manifest_sha256,
                    market_data_indices.generation,
                    market_data_indices.index_id,
                    market_data_indices.session_date,
                    market_data_indices.close_value,
                    market_data_indices.temporal_quality,
                    market_data_indices.source_receipt_sha256
                   FROM public.market_data_indices
                  ORDER BY market_data_indices.index_id, market_data_indices.session_date, market_data_indices.generation DESC) latest) bounded
  WHERE (history_rank <= 1260);


ALTER VIEW public.market_data_research_indices OWNER TO flyway;


CREATE TABLE public.market_source_entitlements (
    logical_identity_hash text NOT NULL,
    source_id text NOT NULL,
    source_family text NOT NULL,
    category text NOT NULL,
    activation_status text NOT NULL,
    provider_calls_allowed boolean NOT NULL,
    decision_authority text NOT NULL,
    contract_expiry timestamp with time zone NOT NULL,
    record_hash text NOT NULL,
    payload_json jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT market_source_entitlements_category_check CHECK ((category = ANY (ARRAY['OVERSEAS_LEAD'::text, 'DOMESTIC_AMPLIFICATION'::text, 'ANALYST'::text, 'NEWS_AGGREGATE'::text]))),
    CONSTRAINT market_source_entitlements_disabled_check CHECK (((activation_status = 'CANDIDATE_DISABLED'::text) AND (NOT provider_calls_allowed) AND (decision_authority = 'NONE'::text))),
    CONSTRAINT market_source_entitlements_identity_hash_check CHECK ((logical_identity_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_source_entitlements_payload_check CHECK ((jsonb_typeof(payload_json) = 'object'::text)),
    CONSTRAINT market_source_entitlements_record_hash_check CHECK ((record_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT market_source_entitlements_source_family_check CHECK ((source_family = ANY (ARRAY['KIS'::text, 'GDELT'::text]))),
    CONSTRAINT market_source_entitlements_source_id_check CHECK ((source_id ~ '^(KIS_DISABLED_[0-9]{2}|GDELT_AGGREGATE)$'::text))
);


ALTER TABLE public.market_source_entitlements OWNER TO flyway;


CREATE TABLE public.orders (
    order_id text NOT NULL,
    user_id text NOT NULL,
    account_id text NOT NULL,
    decision_id text NOT NULL,
    symbol text NOT NULL,
    side text NOT NULL,
    order_type text NOT NULL,
    quantity bigint NOT NULL,
    submitted_price_krw bigint,
    status text NOT NULL,
    order_intent_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    submitted_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    decision_evaluation_id text NOT NULL,
    brokerage_mode text NOT NULL,
    account_scope_hash text NOT NULL,
    idempotency_scope_hash text NOT NULL,
    idempotency_owner_scope_hash text NOT NULL,
    request_hash text NOT NULL,
    result_canonical_json text NOT NULL,
    acknowledged_by text NOT NULL,
    acknowledged_at timestamp with time zone NOT NULL,
    filled_quantity bigint DEFAULT 0 NOT NULL,
    leaves_quantity bigint NOT NULL,
    unfilled_terminated_quantity bigint DEFAULT 0 NOT NULL,
    average_fill_price_krw bigint,
    reconciliation_status text DEFAULT 'NOT_APPLICABLE'::text NOT NULL,
    reconciled_at timestamp with time zone,
    provider_order_ref_hash text,
    provider_tr_id text,
    provider_received_at timestamp with time zone,
    CONSTRAINT orders_account_identity_check CHECK (((account_id ~ '^acct_[0-9a-f]{32}$'::text) AND (account_scope_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT orders_ack_actor_check CHECK ((acknowledged_by = user_id)),
    CONSTRAINT orders_active_unfilled_terminated_check CHECK (((status = ANY (ARRAY['FILLED'::text, 'CANCELLED'::text, 'REJECTED'::text])) OR (unfilled_terminated_quantity = 0))),
    CONSTRAINT orders_average_fill_price_positive_check CHECK (((average_fill_price_krw IS NULL) OR (average_fill_price_krw > 0))),
    CONSTRAINT orders_average_price_presence_check CHECK (((filled_quantity = 0) = (average_fill_price_krw IS NULL))),
    CONSTRAINT orders_brokerage_mode_check CHECK ((brokerage_mode = ANY (ARRAY['KIS_MOCK'::text, 'INTERNAL_PAPER'::text]))),
    CONSTRAINT orders_filled_quantity_nonnegative_check CHECK ((filled_quantity >= 0)),
    CONSTRAINT orders_filled_status_check CHECK (((status <> 'FILLED'::text) OR (filled_quantity = quantity))),
    CONSTRAINT orders_idempotency_hash_check CHECK (((idempotency_scope_hash ~ '^[0-9a-f]{64}$'::text) AND (idempotency_owner_scope_hash ~ '^[0-9a-f]{64}$'::text) AND (request_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT orders_identity_check CHECK ((((brokerage_mode = 'KIS_MOCK'::text) AND (order_id ~ '^ord_mock_[0-9a-f]{32}$'::text)) OR ((brokerage_mode = 'INTERNAL_PAPER'::text) AND (order_id ~ '^ord_paper_[0-9a-f]{32}$'::text)))),
    CONSTRAINT orders_leaves_quantity_nonnegative_check CHECK ((leaves_quantity >= 0)),
    CONSTRAINT orders_mock_price_check CHECK ((((order_type = 'MARKET'::text) AND (submitted_price_krw IS NULL)) OR ((order_type = 'LIMIT'::text) AND (submitted_price_krw IS NOT NULL) AND (submitted_price_krw > 0)))),
    CONSTRAINT orders_order_type_check CHECK ((order_type = ANY (ARRAY['MARKET'::text, 'LIMIT'::text]))),
    CONSTRAINT orders_payload_check CHECK (((jsonb_typeof(order_intent_json) = 'object'::text) AND ((octet_length((order_intent_json)::text) >= 2) AND (octet_length((order_intent_json)::text) <= 65536)) AND ((octet_length(result_canonical_json) >= 2) AND (octet_length(result_canonical_json) <= 65536)) AND (jsonb_typeof((result_canonical_json)::jsonb) = 'object'::text))),
    CONSTRAINT orders_provider_reference_check CHECK ((((provider_order_ref_hash IS NULL) AND (provider_tr_id IS NULL) AND (provider_received_at IS NULL)) OR ((brokerage_mode = 'KIS_MOCK'::text) AND (provider_order_ref_hash ~ '^[0-9a-f]{64}$'::text) AND (provider_tr_id = ANY (ARRAY['VTTC0011U'::text, 'VTTC0012U'::text])) AND (provider_received_at IS NOT NULL)))),
    CONSTRAINT orders_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT orders_quantity_conservation_check CHECK ((((filled_quantity + leaves_quantity) + unfilled_terminated_quantity) = quantity)),
    CONSTRAINT orders_reconciliation_status_check CHECK ((reconciliation_status = ANY (ARRAY['NOT_APPLICABLE'::text, 'MATCHED'::text, 'MISMATCH'::text]))),
    CONSTRAINT orders_reconciliation_time_check CHECK (((reconciliation_status = 'NOT_APPLICABLE'::text) = (reconciled_at IS NULL))),
    CONSTRAINT orders_side_check CHECK ((side = ANY (ARRAY['BUY'::text, 'SELL'::text]))),
    CONSTRAINT orders_status_check CHECK ((status = ANY (ARRAY['SUBMITTED'::text, 'PENDING_RECONCILIATION'::text, 'ACCEPTED'::text, 'PARTIALLY_FILLED'::text, 'FILLED'::text, 'CANCEL_REQUESTED'::text, 'CANCELLED'::text, 'REJECTED'::text]))),
    CONSTRAINT orders_terminal_leaves_check CHECK (((status <> ALL (ARRAY['FILLED'::text, 'CANCELLED'::text, 'REJECTED'::text])) OR (leaves_quantity = 0))),
    CONSTRAINT orders_time_check CHECK (((submitted_at >= created_at) AND (updated_at >= created_at) AND (acknowledged_at >= created_at))),
    CONSTRAINT orders_unfilled_terminated_nonnegative_check CHECK ((unfilled_terminated_quantity >= 0))
);

ALTER TABLE ONLY public.orders FORCE ROW LEVEL SECURITY;


ALTER TABLE public.orders OWNER TO flyway;


CREATE VIEW public.mock_order_owner_projection WITH (security_barrier='true', security_invoker='true') AS
