    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT opendart_quota_usage_check CHECK ((daily_budget <= effective_limit)),
    CONSTRAINT opendart_quota_usage_check1 CHECK ((((daily_budget)::bigint * 8) <= ((effective_limit)::bigint * 7))),
    CONSTRAINT opendart_quota_usage_check2 CHECK (((exhausted_at IS NULL) = (exhausted_reason IS NULL))),
    CONSTRAINT opendart_quota_usage_daily_budget_check CHECK (((daily_budget > 0) AND (daily_budget <= 17500))),
    CONSTRAINT opendart_quota_usage_effective_limit_check CHECK ((effective_limit > 0)),
    CONSTRAINT opendart_quota_usage_exhausted_reason_check CHECK (((exhausted_reason IS NULL) OR ((char_length(exhausted_reason) >= 1) AND (char_length(exhausted_reason) <= 64)))),
    CONSTRAINT opendart_quota_usage_last_grant_token_check CHECK (((last_grant_token IS NULL) OR ((char_length(last_grant_token) >= 1) AND (char_length(last_grant_token) <= 128)))),
    CONSTRAINT opendart_quota_usage_physical_attempts_check CHECK ((physical_attempts >= 0))
);


ALTER TABLE public.opendart_quota_usage OWNER TO flyway;


CREATE TABLE public.order_events (
    order_event_id text NOT NULL,
    order_id text NOT NULL,
    event_type text NOT NULL,
    event_status text,
    payload_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    event_seq integer NOT NULL,
    CONSTRAINT order_events_identity_check CHECK ((order_event_id ~ '^oev_[0-9a-f]{32}$'::text)),
    CONSTRAINT order_events_payload_check CHECK (((jsonb_typeof(payload_json) = 'object'::text) AND ((octet_length((payload_json)::text) >= 2) AND (octet_length((payload_json)::text) <= 65536)))),
    CONSTRAINT order_events_sequence_check CHECK ((event_seq > 0)),
    CONSTRAINT order_events_status_check CHECK (((event_status IS NULL) OR (event_status = ANY (ARRAY['SUBMITTED'::text, 'ACCEPTED'::text, 'PARTIALLY_FILLED'::text, 'FILLED'::text, 'CANCEL_REQUESTED'::text, 'CANCELLED'::text, 'REJECTED'::text])))),
    CONSTRAINT order_events_type_check CHECK ((event_type = ANY (ARRAY['MOCK_ORDER_SUBMITTED'::text, 'MOCK_ORDER_PROVIDER_PENDING'::text, 'MOCK_ORDER_ACCEPTED'::text, 'MOCK_ORDER_REJECTED'::text, 'MOCK_ORDER_PARTIALLY_FILLED'::text, 'MOCK_ORDER_FILLED'::text, 'MOCK_ORDER_CANCEL_REQUESTED'::text, 'MOCK_ORDER_CANCELLED'::text, 'PAPER_ORDER_ACCEPTED'::text, 'PAPER_ORDER_FILLED'::text, 'PAPER_ORDER_CANCEL_REQUESTED'::text, 'PAPER_ORDER_CANCELLED'::text, 'INVALID_TRANSITION'::text]))),
    CONSTRAINT order_events_type_status_pair_check CHECK ((((event_type = 'MOCK_ORDER_SUBMITTED'::text) AND (event_status = 'SUBMITTED'::text)) OR ((event_type = 'MOCK_ORDER_PROVIDER_PENDING'::text) AND (event_status = 'PENDING_RECONCILIATION'::text)) OR ((event_type = 'MOCK_ORDER_ACCEPTED'::text) AND (event_status = 'ACCEPTED'::text)) OR ((event_type = 'MOCK_ORDER_REJECTED'::text) AND (event_status = 'REJECTED'::text)) OR ((event_type = 'MOCK_ORDER_PARTIALLY_FILLED'::text) AND (event_status = 'PARTIALLY_FILLED'::text)) OR ((event_type = 'MOCK_ORDER_FILLED'::text) AND (event_status = 'FILLED'::text)) OR ((event_type = 'MOCK_ORDER_CANCEL_REQUESTED'::text) AND (event_status = 'CANCEL_REQUESTED'::text)) OR ((event_type = 'MOCK_ORDER_CANCELLED'::text) AND (event_status = 'CANCELLED'::text)) OR ((event_type = 'PAPER_ORDER_ACCEPTED'::text) AND (event_status = 'ACCEPTED'::text)) OR ((event_type = 'PAPER_ORDER_FILLED'::text) AND (event_status = 'FILLED'::text)) OR ((event_type = 'PAPER_ORDER_CANCEL_REQUESTED'::text) AND (event_status = 'CANCEL_REQUESTED'::text)) OR ((event_type = 'PAPER_ORDER_CANCELLED'::text) AND (event_status = 'CANCELLED'::text)) OR ((event_type = 'INVALID_TRANSITION'::text) AND (event_status IS NULL))))
