    created_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT rag_answer_history_answer_check CHECK (((octet_length(answer_nonce) = 12) AND ((octet_length(answer_ciphertext) >= 0) AND (octet_length(answer_ciphertext) <= 8192)) AND (octet_length(answer_tag) = 16))),
    CONSTRAINT rag_answer_history_coverage_check CHECK (((citation_coverage >= (0.0)::double precision) AND (citation_coverage <= (1.0)::double precision))),
    CONSTRAINT rag_answer_history_expiry_check CHECK ((expires_at = (created_at + '30 days'::interval))),
    CONSTRAINT rag_answer_history_flags_check CHECK ((((cardinality(guardrail_flags) >= 0) AND (cardinality(guardrail_flags) <= 8)) AND (array_position(guardrail_flags, ''::text) IS NULL) AND (octet_length(array_to_string(guardrail_flags, ''::text)) <= 512) AND (array_to_string(guardrail_flags, ''::text) ~ '^[A-Z0-9_]*$'::text))),
    CONSTRAINT rag_answer_history_id_check CHECK ((answer_id ~ '^rag_ans_[0-9a-f]{32}$'::text)),
    CONSTRAINT rag_answer_history_kek_check CHECK ((kek_version ~ '^kek-v[1-9][0-9]{0,8}$'::text)),
    CONSTRAINT rag_answer_history_mode_check CHECK ((answer_mode = ANY (ARRAY['CONCISE'::text, 'DETAILED'::text]))),
    CONSTRAINT rag_answer_history_question_check CHECK (((octet_length(question_nonce) = 12) AND ((octet_length(question_ciphertext) >= 1) AND (octet_length(question_ciphertext) <= 8192)) AND (octet_length(question_tag) = 16))),
    CONSTRAINT rag_answer_history_status_check CHECK ((generation_status = ANY (ARRAY['ANSWERED'::text, 'RETRIEVAL_ONLY'::text, 'RETRIEVAL_FAILURE'::text, 'BLOCKED_SENSITIVE'::text, 'BLOCKED_ADVICE'::text, 'GENERATION_UNAVAILABLE'::text]))),
    CONSTRAINT rag_answer_history_status_result_check CHECK ((((generation_status = 'ANSWERED'::text) AND ((citation_count >= 1) AND (citation_count <= 5)) AND (citation_coverage = (1.0)::double precision) AND (NOT retrieval_failure)) OR ((generation_status = 'RETRIEVAL_FAILURE'::text) AND (citation_count = 0) AND (citation_coverage = (0.0)::double precision) AND retrieval_failure) OR ((generation_status = ANY (ARRAY['RETRIEVAL_ONLY'::text, 'BLOCKED_SENSITIVE'::text, 'BLOCKED_ADVICE'::text, 'GENERATION_UNAVAILABLE'::text])) AND (citation_count = 0) AND (citation_coverage = (0.0)::double precision) AND (NOT retrieval_failure)))),
    CONSTRAINT rag_answer_history_wrap_check CHECK (((octet_length(wrap_nonce) = 12) AND (octet_length(wrapped_dek) = 32) AND (octet_length(wrap_tag) = 16)))
);


