    CONSTRAINT rag_corpus_generations_status_check CHECK ((status = ANY (ARRAY['REGISTERED'::text, 'PLANNED'::text, 'MATERIALIZING'::text, 'MATERIALIZED'::text, 'EVAL_PASSED'::text, 'ACTIVE'::text, 'FAILED_FINAL'::text, 'DISABLED'::text]))),
