    CONSTRAINT rag_corpus_generations_time_check CHECK ((((evaluated_at IS NULL) OR (evaluated_at >= created_at)) AND ((activated_at IS NULL) OR ((evaluated_at IS NOT NULL) AND (activated_at >= evaluated_at))) AND ((failed_at IS NULL) OR (failed_at >= COALESCE(evaluated_at, created_at))) AND ((disabled_at IS NULL) OR (disabled_at >= COALESCE(activated_at, evaluated_at, created_at))) AND ((status <> 'ACTIVE'::text) OR (activated_at IS NOT NULL)) AND ((status <> 'FAILED_FINAL'::text) OR (failed_at IS NOT NULL)) AND ((status <> 'DISABLED'::text) OR (disabled_at IS NOT NULL)))),
