    CONSTRAINT rag_v2_immutable_source_id_check CHECK ((source_id ~ '^src_[a-z0-9][a-z0-9_-]{2,95}$'::text)),
    CONSTRAINT rag_v2_immutable_source_ir_check CHECK (((jsonb_typeof(document_ir) = 'object'::text) AND ((octet_length((document_ir)::text) >= 2) AND (octet_length((document_ir)::text) <= 16777216)) AND public.rag_v2_immutable_document_ir_structure_is_valid(document_ir) AND ((document_ir ->> 'sourceId'::text) = source_id) AND ((document_ir ->> 'sourceRevisionId'::text) = source_revision_id) AND ((document_ir ->> 'mimeType'::text) = mime_type) AND ((document_ir ->> 'rawContentSha256'::text) = raw_content_sha256) AND ((document_ir ->> 'normalizedContentSha256'::text) = normalized_document_ir_sha256) AND (((document_ir -> 'parserEvidence'::text) ->> 'parserVersion'::text) = parser_version) AND (((document_ir -> 'parserEvidence'::text) ->> 'parserArtifactSha256'::text) ~ '^[0-9a-f]{64}$'::text) AND
CASE
    WHEN ((jsonb_typeof(((document_ir -> 'safetyClassification'::text) -> 'externalLlmEligible'::text)) = 'boolean'::text) AND (jsonb_typeof(((document_ir -> 'safetyClassification'::text) -> 'piiDetected'::text)) = 'boolean'::text) AND (jsonb_typeof(((document_ir -> 'safetyClassification'::text) -> 'promptInjectionDetected'::text)) = 'boolean'::text) AND (jsonb_typeof(((document_ir -> 'safetyClassification'::text) -> 'secretDetected'::text)) = 'boolean'::text)) THEN ((((document_ir -> 'safetyClassification'::text) ->> 'secretDetected'::text) = 'false'::text) AND (((((document_ir -> 'safetyClassification'::text) ->> 'piiDetected'::text) = 'false'::text) AND (((document_ir -> 'safetyClassification'::text) ->> 'promptInjectionDetected'::text) = 'false'::text)) OR (((document_ir -> 'safetyClassification'::text) ->> 'externalLlmEligible'::text) = 'false'::text)) AND (external_processing_eligible = ((((document_ir -> 'safetyClassification'::text) ->> 'externalLlmEligible'::text))::boolean AND external_embedding_allowed AND external_generation_allowed)))
    ELSE false
END AND (NOT (document_ir ? 'originalPath'::text)) AND (NOT (document_ir ? 'rawPath'::text)) AND (NOT (document_ir ? 'absolutePath'::text)) AND (NOT (document_ir ? 'filePath'::text)) AND (NOT (document_ir ? 'url'::text)))),
