    CONSTRAINT rag_v2_immutable_source_oa_track_check CHECK ((((source_scope = 'OA112'::text) AND (oa_track_id IS NOT NULL)) OR ((source_scope <> 'OA112'::text) AND (oa_track_id IS NULL)))),
    CONSTRAINT rag_v2_immutable_source_owner_processing_check CHECK (((source_scope <> 'OWNER_PRIVATE'::text) OR local_processing_allowed)),
    CONSTRAINT rag_v2_immutable_source_permission_check CHECK (((NOT external_processing_eligible) OR (external_embedding_allowed AND external_generation_allowed))),
    CONSTRAINT rag_v2_immutable_source_public_url_check CHECK ((((source_scope = ANY (ARRAY['EXACT30'::text, 'OA112'::text])) AND public.rag_v2_immutable_public_https_url_is_valid(canonical_https_url)) OR ((source_scope = 'OWNER_PRIVATE'::text) AND (canonical_https_url IS NULL)))),
