    CONSTRAINT rag_v2_immutable_source_revision_id_check CHECK ((source_revision_id ~ '^srv_[a-z0-9][a-z0-9_-]{2,95}$'::text)),
    CONSTRAINT rag_v2_immutable_source_runtime_text_check CHECK ((((char_length(mime_type) >= 3) AND (char_length(mime_type) <= 128)) AND ((char_length(parser_version) >= 1) AND (char_length(parser_version) <= 128)) AND ((char_length(tokenizer_version) >= 1) AND (char_length(tokenizer_version) <= 128)))),
    CONSTRAINT rag_v2_immutable_source_scope_check CHECK ((((source_scope = ANY (ARRAY['EXACT30'::text, 'OA112'::text])) AND (owner_user_id IS NULL)) OR ((source_scope = 'OWNER_PRIVATE'::text) AND (owner_user_id IS NOT NULL)))),
    CONSTRAINT rag_v2_immutable_source_text_check CHECK ((((octet_length(canonical_text) >= 1) AND (octet_length(canonical_text) <= 16777216)) AND (canonical_text_sha256 = encode(public.digest(canonical_text, 'sha256'::text), 'hex'::text))))
);

