    CONSTRAINT rag_v2_owner_voyage_attempt_hash_check CHECK (((plan_sha256 ~ '^[0-9a-f]{64}$'::text) AND (packet_sha256 ~ '^[0-9a-f]{64}$'::text) AND (approval_manifest_sha256 ~ '^[0-9a-f]{64}$'::text) AND (nonce_sha256 ~ '^[0-9a-f]{64}$'::text) AND (ticket_set_sha256 ~ '^[0-9a-f]{64}$'::text))),
