    user_id text NOT NULL,
    refresh_token_hash text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.user_sessions OWNER TO flyway;


CREATE TABLE public.users (
    user_id text NOT NULL,
    username text NOT NULL,
    role text NOT NULL,
    password_hash text NOT NULL,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    security_version bigint DEFAULT 1 NOT NULL,
    credential_reuse_tag bytea,
    credential_bundle_mac bytea,
    credential_policy_version smallint,
    CONSTRAINT users_credential_evidence_shape_check CHECK ((((credential_reuse_tag IS NULL) AND (credential_bundle_mac IS NULL) AND (credential_policy_version IS NULL)) OR ((credential_reuse_tag IS NOT NULL) AND (octet_length(credential_reuse_tag) = 32) AND (credential_bundle_mac IS NOT NULL) AND (octet_length(credential_bundle_mac) = 32) AND (credential_policy_version = 1)))),
    CONSTRAINT users_demo_credential_evidence_required_check CHECK (((user_id <> ALL (ARRAY['usr_demo_user'::text, 'usr_demo_admin'::text])) OR ((credential_reuse_tag IS NOT NULL) AND (credential_bundle_mac IS NOT NULL) AND (credential_policy_version = 1)))),
    CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['USER'::text, 'ADMIN'::text]))),
    CONSTRAINT users_security_version_positive_check CHECK ((security_version > 0)),
    CONSTRAINT users_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'LOCKED'::text, 'DISABLED'::text])))
);


ALTER TABLE public.users OWNER TO flyway;


