INSERT INTO public.principle_presets (preset_id, name_ko, mode, rules_json, is_active, created_at, name_en, description_ko, description_en, display_order) VALUES ('conservative', '보수형', 'GUIDE', '[{"metric": "asset_weight", "ruleId": "max_position_per_asset", "enabled": true, "operator": "<=", "ruleType": "POSITION_LIMIT", "severity": "BLOCK", "threshold": 0.15}, {"metric": "gold_etf_etn_weight", "ruleId": "max_gold_etf_etn_weight", "enabled": true, "operator": "<=", "ruleType": "POSITION_LIMIT", "severity": "BLOCK", "threshold": 0.2}, {"metric": "order_amount_krw", "ruleId": "max_single_order_amount", "enabled": true, "operator": "<=", "ruleType": "ORDER_SIZE", "severity": "BLOCK", "threshold": 300000}, {"metric": "daily_loss_rate", "ruleId": "daily_loss_guard", "enabled": true, "operator": ">=", "ruleType": "LOSS_LIMIT", "severity": "BLOCK", "threshold": -0.02}, {"metric": "mdd", "ruleId": "mdd_guard", "enabled": true, "operator": ">=", "ruleType": "DRAWDOWN_LIMIT", "severity": "BLOCK", "threshold": -0.1}, {"metric": "daily_order_count", "ruleId": "max_daily_orders", "enabled": true, "operator": "<=", "ruleType": "TRADING_FREQUENCY", "severity": "BLOCK", "threshold": 2}, {"metric": "negative_news_score", "ruleId": "negative_news_guard", "enabled": false, "operator": "<=", "ruleType": "NEWS_GUARD", "severity": "ALLOW", "threshold": 0.5}, {"metric": "disclosure_risk_score", "ruleId": "disclosure_risk_guard", "enabled": false, "operator": "<=", "ruleType": "DISCLOSURE_GUARD", "severity": "ALLOW", "threshold": 0.5}]', true, '2026-08-23 00:00:00+00', 'Conservative', '손실 제한과 분산투자를 우선하는 데모 원칙', 'Demo principle prioritizing loss limits and diversification', 1);
INSERT INTO public.principle_presets (preset_id, name_ko, mode, rules_json, is_active, created_at, name_en, description_ko, description_en, display_order) VALUES ('balanced', '균형형', 'GUIDE', '[{"metric": "asset_weight", "ruleId": "max_position_per_asset", "enabled": true, "operator": "<=", "ruleType": "POSITION_LIMIT", "severity": "BLOCK", "threshold": 0.2}, {"metric": "gold_etf_etn_weight", "ruleId": "max_gold_etf_etn_weight", "enabled": true, "operator": "<=", "ruleType": "POSITION_LIMIT", "severity": "BLOCK", "threshold": 0.3}, {"metric": "order_amount_krw", "ruleId": "max_single_order_amount", "enabled": true, "operator": "<=", "ruleType": "ORDER_SIZE", "severity": "BLOCK", "threshold": 500000}, {"metric": "daily_loss_rate", "ruleId": "daily_loss_guard", "enabled": true, "operator": ">=", "ruleType": "LOSS_LIMIT", "severity": "BLOCK", "threshold": -0.03}, {"metric": "mdd", "ruleId": "mdd_guard", "enabled": true, "operator": ">=", "ruleType": "DRAWDOWN_LIMIT", "severity": "BLOCK", "threshold": -0.15}, {"metric": "daily_order_count", "ruleId": "max_daily_orders", "enabled": true, "operator": "<=", "ruleType": "TRADING_FREQUENCY", "severity": "WARN", "threshold": 3}, {"metric": "negative_news_score", "ruleId": "negative_news_guard", "enabled": false, "operator": "<=", "ruleType": "NEWS_GUARD", "severity": "ALLOW", "threshold": 0.7}, {"metric": "disclosure_risk_score", "ruleId": "disclosure_risk_guard", "enabled": false, "operator": "<=", "ruleType": "DISCLOSURE_GUARD", "severity": "ALLOW", "threshold": 0.7}]', true, '2026-08-23 00:00:00+00', 'Balanced', '위험 제한과 거래 기회를 균형 있게 적용하는 데모 원칙', 'Demo principle balancing risk limits and trading flexibility', 2);
INSERT INTO public.principle_presets (preset_id, name_ko, mode, rules_json, is_active, created_at, name_en, description_ko, description_en, display_order) VALUES ('aggressive', '공격형', 'GUIDE', '[{"metric": "asset_weight", "ruleId": "max_position_per_asset", "enabled": true, "operator": "<=", "ruleType": "POSITION_LIMIT", "severity": "BLOCK", "threshold": 0.3}, {"metric": "gold_etf_etn_weight", "ruleId": "max_gold_etf_etn_weight", "enabled": true, "operator": "<=", "ruleType": "POSITION_LIMIT", "severity": "BLOCK", "threshold": 0.4}, {"metric": "order_amount_krw", "ruleId": "max_single_order_amount", "enabled": true, "operator": "<=", "ruleType": "ORDER_SIZE", "severity": "BLOCK", "threshold": 1000000}, {"metric": "daily_loss_rate", "ruleId": "daily_loss_guard", "enabled": true, "operator": ">=", "ruleType": "LOSS_LIMIT", "severity": "BLOCK", "threshold": -0.05}, {"metric": "mdd", "ruleId": "mdd_guard", "enabled": true, "operator": ">=", "ruleType": "DRAWDOWN_LIMIT", "severity": "BLOCK", "threshold": -0.25}, {"metric": "daily_order_count", "ruleId": "max_daily_orders", "enabled": true, "operator": "<=", "ruleType": "TRADING_FREQUENCY", "severity": "WARN", "threshold": 5}, {"metric": "negative_news_score", "ruleId": "negative_news_guard", "enabled": false, "operator": "<=", "ruleType": "NEWS_GUARD", "severity": "ALLOW", "threshold": 0.85}, {"metric": "disclosure_risk_score", "ruleId": "disclosure_risk_guard", "enabled": false, "operator": "<=", "ruleType": "DISCLOSURE_GUARD", "severity": "ALLOW", "threshold": 0.85}]', true, '2026-08-23 00:00:00+00', 'Aggressive', '더 넓은 위험 한도 안에서도 핵심 손실 제한을 유지하는 데모 원칙', 'Demo principle retaining core loss controls within wider risk limits', 3);



